window.DEVICES = [{"id":"dualcomm-dc-1005pt-faste-switch-tap","hardware_id":"dualcomm-dc-1005pt-faste-switch-tap","name":"10/100 FastE Switch Tap","firmware_kind":"n/a","vendor":"Dualcomm","category":"network-implant","subcategory":"mirroring-switch","status":"available","price_usd":130.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug in the network path through ports 1-4 and connect an analyzer to the mirrored port 5.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"A USB/5VDC-powered 5-port 10/100 Ethernet switch (Dualcomm DC-1005PT) with port-mirroring from Port 1 to Port 5, marketed as a network tap. It is mechanically a real active switch with switching/mirroring logic, not an electrically passive splitter like the Gigabit tap and other true taps in this database.","honest_take":"Despite the 'tap' name, this is an ordinary 5-port unmanaged Ethernet switch with SPAN-style port mirroring - genuinely different from a real passive tap, and worse for covert or high-integrity monitoring in two specific ways: a switch's mirror port can silently drop frames under load the way a true passive tap never does, and being a full switch it fails closed (the link goes down, not through) if it loses power, since there is no physical bypass path. At $130 it also sits close to a genuinely passive Gigabit tap's price ($210, also in this database) while offering weaker guarantees. Worth it only if you specifically want several simultaneous 10/100 drops off one mirrored segment; not a stealthier or more reliable alternative to a real passive tap.","aliases":["DC-1005PT (Hacker Warehouse listing name)","DCSW-1005PT (Dualcomm's own model number)"],"capabilities":{"ethernet_tap_passive":"no","packet_capture":"yes","ethernet_mitm":"no","cloud_c2":"no","vpn_exfil":"no","usb_hid_inject":"no","wifi_scan_24":"no","standalone_untethered":"no","web_ui":"no","app_store":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"Legal to own."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"lab401-1356mhz-field-strength-meter","hardware_id":"lab401-1356mhz-field-strength-meter","name":"13.56MHz RFID Field Strength Meter","firmware_kind":"n/a","vendor":"Lab401","category":"rfid-nfc","subcategory":"field-diagnostic-tool","status":"available","price_usd":95.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Hold it in a field, read the LED colour - no setup, no interpretation beyond the printed ISO-compliance key.","build_effort":"assembled","stealth":"discreet","form_factor":"keychain","summary":"A fully passive, credit-card-sized diagnostic card that harvests power from a 13.56MHz RF field and lights one of 15 colour-coded LEDs to give a quantitative, ISO 10373-7 calibrated reading of field strength - used to verify a reader complies with ISO14443/ISO15693 field-strength requirements, rather than to read or clone anything.","honest_take":"This does one thing and nothing else: it is a passive field-strength indicator, not a reader, writer, sniffer or emulator, and it cannot tell you what protocol or data a reader is using, only how strong its field is. It is the right tool for compliance testing or diagnosing a reader that intermittently fails to power cards, and the wrong tool for literally any offensive RFID task - for that you want an actual reader like the DL533N XL or a Proxmark3, both elsewhere in this batch/database. At EUR80 it is priced like a niche calibration instrument, which is exactly what it is.","aliases":["RFID Field Strength Meter"],"capabilities":{"hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","lf_125khz_read":"no","iso15693":"no","felica":"no","nfc_relay":"no","standalone_untethered":"yes","sd_logging":"no","scriptable":"no"},"legal":{"risk_level":"low","notes":"A passive field-strength meter has no data-capture or cloning capability and carries no meaningful legal restriction on ownership or use in any jurisdiction checked."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"pcb-studios-dual-band-deauther","hardware_id":"pcb-studios-dual-band-deauther","name":"2.4/5 GHz Deauther","firmware":"PCB Studios Deauther firmware","firmware_kind":"stock","vendor":"PCB Studios","category":"wifi","subcategory":"dual-band-deauther","status":"discontinued","price_is_estimate":true,"skill_level":"beginner","skill_note":"Ships as a working board with a browser control panel at 192.168.1.1 - no flashing needed for basic use.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A small RTL8720DN board that hosts its own Wi-Fi AP and a browser-based control panel for scanning and deauthenticating networks on both 2.4GHz and 5GHz. It is one of the very few devices in this whole comparison built on a Realtek chip rather than an Espressif ESP32/ESP8266, which is its only real point of technical distinction.","honest_take":"The RTL8720DN genuinely is a dual-band 2.4/5GHz Wi-Fi chip, which is more than most ESP8266-class deauthers can claim, so the headline capability is at least chip-plausible. But the product is retired, unpriced, sold through a single-person Tindie shop that says it has stopped taking Tindie orders, and no firmware repository or independent teardown was found to verify what the firmware actually does with that silicon - the RGB LED's 'frame transmission' indicator and the 5GHz deauth claim both rest entirely on the seller's own listing text. Like every deauther here, PMF/802.11w on a modern WPA3 or PMF-enabled network defeats it regardless of which chip is doing the transmitting.","aliases":["RTL8720dn Deauther"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"claimed","wifi_deauth_24":"claimed","wifi_deauth_5":"claimed","wifi_monitor_mode":"unknown","wifi_injection":"unknown","wifi_beacon_spam":"no","wifi_evil_twin":"no","wifi_captive_portal":"no","wifi_handshake_capture":"no","wifi_ap_mode":"yes","ble_scan":"no","bt_classic":"no","subghz_rx":"no","hf_1356_read":"no","ir_tx":"no","usb_hid_inject":"no","gps":"no","web_ui":"yes"},"legal":{"risk_level":"medium","notes":"Same exposure as any deauther - transmitting deauth frames against networks you don't own is unlawful interference in most jurisdictions (FCC rules in the US) regardless of which chip sends them."},"ecosystem":{"community":"dormant","docs_quality":"poor","last_release":null,"app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"7941w-rfid-card-cloner","hardware_id":"7941w-rfid-card-cloner","name":"7941W RFID Card Cloner","firmware":"TDiblik 7941W cloner firmware","firmware_kind":"diy","vendor":"TDiblik (Tomas Diblik) - independent open-source project, not a company","category":"rfid-nfc","subcategory":"DIY dual-frequency (125kHz + 13.56MHz) handheld cloner","status":"diy-only","price_usd":35.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Requires soldering/wiring per the repo's schematics, flashing via PlatformIO, 3D-printing a case, and understanding the 7941W's UART protocol. No pre-built kit exists.","build_effort":"full-diy","stealth":"overt","form_factor":"handheld","summary":"A joystick-and-LED-matrix handheld built around a Seeed XIAO nRF52840 driving a 7941W dual-frequency (125kHz/13.56MHz) reader-writer module, able to scan and clone EM4305/T5577 LF tags and Mifare 1K S50 HF cards to blank/writable tags. It's a solo open-source hobby project, not a commercial product.","honest_take":"This is a from-scratch DIY clone box, not a polished tool - 6 GitHub stars, 0 forks, archived since March 2024 with no plans to continue, and the 'display' is icon-only feedback (checkmark/X), not real UI. For the same or less effort, a Proxmark3 or Flipper Zero (already in this database) will read/write the same tag families with far better tooling, active firmware, and a real community; this project's only advantage is novelty and total build transparency (every line of firmware is 788 lines you can read yourself).","released":"2023","aliases":[],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"no","hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"no","mifare_classic_attacks":"unknown","mifare_desfire":"no","nfc_type4_ndef":"no","emv_read":"no","iso15693":"no","felica":"no","magspoof":"no","nfc_relay":"no","sd_logging":"no","scriptable":"no","web_ui":"no","standalone_untethered":"yes"},"legal":{"risk_level":"medium","notes":"Building and owning it is legal almost everywhere - it's just an MCU plus an off-the-shelf reader/writer module."},"ecosystem":{"community":"dead","docs_quality":"good","last_release":null,"app_store":"n/a","abandoned_risk":"already-abandoned"}},{"id":"ac1200-usb-c-wifi-card-mt7921aun","hardware_id":"ac1200-usb-c-wifi-card-mt7921aun","name":"AC1200 USB-C WiFi Card (MT7921AUN, for uConsole)","firmware_kind":"n/a","vendor":"Hacker Gadgets","category":"wifi","subcategory":"internal-wifi-module","status":"preorder","price_usd":45.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Requires opening the uConsole case and connecting to an internal USB-C port on the AIO V2 board - this is a case-open internal install, not a plug-and-play dongle.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A small MT7921AUN-based Wi-Fi 6E + Bluetooth 5.2 module sized and wired specifically to mount inside a ClockworkPi uConsole case. Despite the M.2-like card shape and naming, it connects to the AIO V2 board's internal USB-C port rather than a true M.2 Key-E edge-connector slot (confirmed via the Sapsan Store listing, which describes it as installing via an 'internal USB-C port'). It only works inside this one specific host.","honest_take":"The single most important thing to know: this is NOT a USB dongle like the other two Wi-Fi adapters in this comparison, and despite looking card-shaped it is not a generic M.2 Key-E card you could drop into a laptop either - it plugs into an internal USB-C header that exists only on the uConsole's AIO V2 board. If you don't own that specific device, this card is useless to you. On the chipset: MT7921AUN is the same MT7921-series silicon family as the 'MT7921AU' dongle below, and the mt76/mt7921u Linux driver's monitor-mode support has documented reliability problems - morrownr/USB-WiFi issue #387 reports frame injection failing or falling back to 1-6Mbps rates on this exact chipset family, and openwrt/mt76 issue #839 documents active monitor mode (needed for PMKID attacks via hcxdumptool) being broken on mt7921u entirely. So 'supports monitor mode' on the product page should be read as 'claimed, with known open bugs' rather than a guarantee of ALFA-adapter-grade reliability. Whether 'MT7921AUN' is meaningfully different silicon from the 'MT7921AU' in device 3, or the same die in a different SKU/package, could not be confirmed - MediaTek doesn't publish public consumer datasheets, and even the morrownr/USB-WiFi maintainers have an open, unresolved GitHub thread about exactly this (issue #481, discussion #480). What is confirmed: this board exposes 4 antenna pads (2 Wi-Fi + 2 Bluetooth) versus the MT7921AU dongle's 2 Wi-Fi-only antennas, which is at least circumstantial evidence the 'N' suffix denotes the Bluetooth-combo variant. Of the two MT7921 boards in this batch, this is the worse buy for anyone who doesn't already own a uConsole (zero standalone use); if you do own one, it's your only real internal option.","aliases":["VAYIKE AC1200 USB-C WiFi Card","MT7921AUN uConsole WiFi card"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"claimed","wifi_injection":"partial","wifi_handshake_capture":"partial","wifi_pmkid":"no","wifi_ap_mode":"claimed","packet_capture":"partial","wifi_wardriving":"unknown","bt_classic":"claimed","ble_scan":"claimed","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"Owning and importing this module is legal essentially everywhere - it's a standard Wi-Fi/Bluetooth radio component."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"N/A - it's a Wi-Fi/BT radio module, not an app platform","abandoned_risk":"low"}},{"id":"acr122u","hardware_id":"acr122u","name":"ACR122U","firmware":"ACS stock (CCID / PC/SC)","firmware_kind":"stock","vendor":"Advanced Card Systems (ACS)","category":"rfid-nfc","subcategory":"usb-nfc-reader","status":"discontinued","price_usd":35.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The reader is trivial; the toolchain is not. Getting libnfc, pcscd and the CCID driver to cooperate on Linux - and stop fighting each other over the device - is the actual difficulty, and it is where most people give up.","build_effort":"assembled","stealth":"discreet","form_factor":"desktop","summary":"The ubiquitous cheap USB NFC reader: an NXP PN532 controller behind an ST7 USB microcontroller that presents it as a standard CCID smartcard reader. It is the default hardware assumption in a decade of NFC tutorials, libnfc documentation and MIFARE Classic write-ups, which is most of why it is still everywhere.","honest_take":"Two things catch people out. First, it is 13.56 MHz only - it cannot see a 125 kHz HID Prox or EM4100 badge at all, and 'NFC reader' and 'RFID reader' get used interchangeably enough that people buy one expecting to clone a building badge. Second, ACS has formally end-of-lifed it while publicly warning about widespread counterfeits, so at US$35 you are buying an unknown clone whose firmware version and silicon you cannot verify, and clone-to-clone behaviour under libnfc genuinely varies - some only work through PC/SC, meaning they run on Windows and fail on Linux. What it is honestly good at is NFC Forum Type 1-4 NDEF read/write, and as the cheapest way to run the classic mfoc/mfcuk/libnfc MIFARE Classic workflow, with your PC doing all the computation. Past MIFARE Classic it runs out of road quickly: card emulation support through libnfc is poor, and the PN532 does not do ISO15693.","aliases":["ACR122","ACR122U-A9","ACS NFC reader","PN532 USB reader"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"partial","hf_1356_emulate":"partial","lf_125khz_read":"no","mifare_classic_attacks":"partial","mifare_desfire":"partial","nfc_type4_ndef":"yes","emv_read":"partial","iso15693":"no","felica":"partial","scriptable":"yes"},"legal":{"risk_level":"low","notes":"A commodity USB card reader sold openly on Amazon and used in payment, ticketing and access-control integration everywhere."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":null,"app_store":"No - but an enormous body of libnfc/nfcpy/PC-SC example code targets it specifically","abandoned_risk":"high"}},{"id":"adalm-pluto","hardware_id":"adalm-pluto","name":"ADALM-PLUTO (PlutoSDR)","firmware":"Stock","firmware_kind":"stock","vendor":"Analog Devices","category":"sdr","subcategory":"full-duplex-transceiver","status":"available","price_usd":279.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Excellent teaching hardware with genuinely good ADI documentation, but you still need to understand I/Q, sampling and modulation to get anywhere.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A full-duplex 12-bit SDR built on an AD9363 transceiver and a Xilinx Zynq SoC, sold by Analog Devices as a teaching tool. Guaranteed for 325 MHz to 3.8 GHz with 20 MHz of bandwidth, it is widely reconfigured in software to report as the higher-grade AD9364 and open up 70 MHz to 6 GHz with 56 MHz of bandwidth.","honest_take":"The famous 'hack' deserves a caveat people skip: telling the software the chip is an AD9364 changes what it will let you tune to, but it does not change the silicon's actual calibrated performance. ADI guarantees the AD9363 only from 325 MHz to 3.8 GHz, and unlocked units vary - some are fine at 70 MHz and 6 GHz, some are noticeably worse. Treat the extended range as usable, not specified. Beyond that this is an under-rated device for security work: 12-bit and genuinely full duplex for less than a LimeSDR Mini, with an ARM Linux system on board you can SSH into and run code on.","released":"2017","aliases":["PlutoSDR","Pluto SDR","ADALM PLUTO"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"yes","scriptable":"yes","standalone_untethered":"partial"},"legal":{"risk_level":"high","notes":"Receiving is generally lawful."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"airdrive-forensic-keylogger","hardware_id":"airdrive-forensic-keylogger","name":"AirDrive Forensic Keylogger","firmware":"Stock","firmware_kind":"stock","vendor":"Keelog","category":"usb-hid","subcategory":"hardware-keylogger","status":"available","price_usd":60.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug it inline with the keyboard, then join its Wi-Fi and read a web page.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A 10 mm USB inline keylogger with 16 MB of flash that brings up its own Wi-Fi access point, so keystrokes can be retrieved from a phone without ever touching the device again. The product family extends to cable and module versions that hide inside a keyboard, plus Pro/Max tiers with email reports and live streaming.","honest_take":"Its stealth is physical, not electronic. In factory-default configuration it raises an open Wi-Fi access point (SSID pattern AIR_XXYYZZ, admin at 192.168.4.1), which is exactly what rogue-AP monitoring is built to find - and independent testing also picked it up by its USB current draw (about 0.087 A versus 0.007 A idle). That same testing found it silently failed to log a gaming keyboard. So: excellent against an office desktop that nobody is monitoring, and easy to catch anywhere with WLAN scanning.","released":"2018","aliases":["AirDrive keylogger","KeyGrabber","Keelog"],"capabilities":{"usb_keylogger":"yes","usb_exfil":"yes","wifi_ap_mode":"yes","usb_hid_inject":"partial","usb_mass_storage":"no"},"legal":{"risk_level":"high","notes":"Recording somebody else's keystrokes is interception of communications and, in many countries, a criminal offence even for an employer without a documented policy and notice."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"n/a","app_store":"No","abandoned_risk":"low"}},{"id":"airfrog","hardware_id":"airfrog","name":"Airfrog","firmware":"Airfrog default firmware","firmware_kind":"diy","vendor":"Piers Finlayson","category":"hardware-debug","subcategory":"wireless-swd-debug-coprocessor","status":"diy-only","price_usd":5.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Hand-soldering 0402 passives and a QFN-style ESP32-C3-MINI-1 module onto a coin-sized 2-layer board, wiring SWD to a target, and building Rust firmware with cargo are all required; the resulting web UI itself is simple to use once it's running.","build_effort":"full-diy","stealth":"overt","form_factor":"board","summary":"Airfrog is an open-source, coin-sized (16x28mm) PCB built around a $3 ESP32-C3-MINI-1 module that bit-bangs the SWD protocol to an ARM Cortex-M target and exposes its RAM, flash and peripherals over Wi-Fi via a web UI, a REST API, and a low-overhead binary API, plus probe-rs integration. It's designed to stay wired to one target permanently - the way a network card lives inside a PC - rather than being carried between different boards like a USB debug probe.","honest_take":"This is a wireless SWD bridge for one target, not a general-purpose debug probe you carry between boards - it has no JTAG, only SWD, and has only been tested by the author against STM32F1/F4 and the RP2040/Pico. It's a single-developer project that saw two and a half months of rapid commits (July-September 2025) and then went completely silent - no commits and no replies to any of its 22 open feature-request issues for a full year as of this check. The core idea (debug + telemetry over Wi-Fi without a wired connection) is genuinely useful and not something Tigard or Glasgow Interface Explorer do, but those wired, multi-protocol probes (JTAG/SWD/UART/SPI/I2C) are instantly usable, ship assembled, and don't require permanently wiring hardware to a target - if you just want a working debug probe today, they're the safer choice. The ESP32-C3 silicon is the same family widely used for Wi-Fi deauth/monitor-mode tools elsewhere, but Airfrog's firmware doesn't implement any of that - its Wi-Fi radio exists purely as the SWD backhaul.","released":"2025","aliases":[],"capabilities":{"uart":"yes","jtag_swd":"partial","spi_flash_dump":"yes","i2c":"no","logic_analyzer":"no","glitching":"no","sd_logging":"no","wifi_monitor_mode":"no","wifi_deauth_24":"no","ble_scan":"no","web_ui":"yes","scriptable":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"low","notes":"Not a radio transmitter beyond the pre-certified ESP32-C3 Wi-Fi module, and not designed to attack devices you don't control."},"ecosystem":{"community":"dormant","docs_quality":"excellent","last_release":"2025-09","app_store":"No","abandoned_risk":"medium"}},{"id":"alfa-awus036achm","hardware_id":"alfa-awus036achm","name":"ALFA AWUS036ACHM","firmware_kind":"n/a","vendor":"ALFA Network Inc.","category":"wifi","subcategory":"usb-wifi-adapter","status":"available","price_usd":63.72,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-play driver-wise on modern Linux (mt76 is in-tree, no DKMS) — Rokland's own driver guide calls MediaTek chipsets 'plug and play' — but getting real use out of monitor mode/injection means comfort with aircrack-ng/Wireshark/Kismet.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"Alfa's 'Mini' dual-band adapter: a MediaTek MT7610U chipset, AC600 class (150 Mbps 2.4GHz / 433 Mbps 5GHz), two RP-SMA connectors for external dipole antennas, and a screen-clip mount, aimed at laptop users who want monitor mode and packet injection with in-kernel Linux support. It is easily confused with the larger, older, RTL8812AU-based AWUS036ACH — despite the near-identical name, they use different chipsets, different USB connectors (Mini-USB here vs USB-C on the ACH) and different AC classes (AC600 vs AC1200).","honest_take":"This is 'just a Wi-Fi adapter' in the most literal sense: no display, no attack software, nothing beyond an MT7610U chip and two antenna jacks — and notably no Bluetooth radio at all, unlike the newer AXM adapter in this same product line. Everything useful it does — monitor mode, deauth, handshake capture — comes from free software (aircrack-ng, Wireshark, Kismet) running on your laptop. The chipset itself is fine: MT7610U has mature in-kernel mt76 driver support with no DKMS wrestling, independently confirmed by community documentation (morrownr's USB-WiFi project). But it's a lower tier than the name suggests — AC600, not the AC1200 that at least one reseller's own product title confusingly implies — and it is a cheaper, different chipset from the RTL8812AU in the plain (non-M) 'AWUS036ACH.' Categorized here as 'wifi' rather than 'accessory' because monitor-mode/injection support is a deliberate, marketed feature this chipset was selected for. Be clear-eyed that you're paying for a driver-compatible commodity chip, not proprietary capability — lab401's price is a real premium over general electronics resellers for identical hardware.","aliases":["AWUS036ACHM Mini","Alfa Mini Dual-Band AC600"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_injection":"yes","wifi_deauth_24":"yes","wifi_pmkid":"unknown","wifi_handshake_capture":"yes","wifi_wardriving":"partial","wifi_ap_mode":"claimed","packet_capture":"yes","ble_scan":"no","bt_classic":"no","usb_hid_inject":"no"},"legal":{"risk_level":"medium","notes":"Owning and selling this adapter is legal everywhere it's sold."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"alfa-awus036acm","hardware_id":"alfa-awus036acm","name":"ALFA AWUS036ACM","firmware_kind":"n/a","vendor":"ALFA Network","category":"wifi","subcategory":"usb-wifi-adapter","status":"available","price_usd":46.97,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug into any Linux/Kali box and it just works - in-kernel driver, no compiling, no DKMS.","build_effort":"assembled","stealth":"overt","form_factor":"usb-stick","summary":"A dual-band 802.11ac USB 3.0 Wi-Fi adapter built around MediaTek's MT7612U chipset, with two detachable RP-SMA dipole antennas. It has been the de facto reference monitor-mode/injection adapter in the Kali/aircrack-ng community since around 2018 because its Linux driver (mt76x2u) has been mainlined since kernel 4.19 - no DKMS, no out-of-tree driver drama. It is a pure USB radio peripheral: no MCU, no screen, no battery, nothing standalone.","honest_take":"This is the boring, safe choice, and that is exactly why it is still recommended in 2026 even though the silicon is nearly a decade old: mt76x2u's monitor-mode and injection support, including 'active monitor mode' (which hcxdumptool needs for PMKID capture), is mature and well-tested - unlike the two MT7921AU(N) adapters in this same comparison, where active monitor mode is documented as broken (openwrt/mt76 issue #839) and plain frame injection is reported unreliable (morrownr/USB-WiFi issue #387). Of the three Wi-Fi adapters in this batch, this is the better buy for anyone whose actual job is reliable Wi-Fi auditing today - you're trading Wi-Fi 6E and Bluetooth for a driver stack that's had eight years to become boring and stable. It does zero Bluetooth (MT7612U is Wi-Fi-only silicon), and its deauth/injection is subject to the same 802.11w/PMF limitation as literally every other Wi-Fi adapter on the market: a network enforcing Protected Management Frames (increasingly the default under WPA3) is unaffected by deauth regardless of which adapter drives the attack. The $46.97 price is standard ALFA MSRP across resellers, not case/brand markup - you're paying for the antenna hardware and USB3 shielding, not a name.","released":"2018","aliases":["AWUS036ACM","ALFA ACM"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_injection":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_ap_mode":"yes","wifi_wardriving":"yes","packet_capture":"yes","bt_classic":"no","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"Owning and importing this adapter is legal essentially everywhere - it's sold as a normal consumer Wi-Fi peripheral."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"N/A - it's a Wi-Fi radio peripheral, not an app platform. Driven entirely by host-side Linux tools (aircrack-ng suite, Kismet, Wireshark).","abandoned_risk":"low"}},{"id":"alfa-awus036axm","hardware_id":"alfa-awus036axm","name":"ALFA AWUS036AXM","firmware_kind":"n/a","vendor":"ALFA Network Inc.","category":"wifi","subcategory":"usb-wifi-adapter","status":"available","price_usd":55.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-play on kernel 5.18+ (mt7921u is in-tree, no DKMS needed), but 6GHz/WiFi 6E monitor-mode and injection workflows are newer and less battle-tested than older Realtek-based adapters — expect more troubleshooting.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A compact WiFi 6E adapter built around a MediaTek MT7921AUN combo chip (no separate general-purpose MCU) covering 2.4/5/6GHz WiFi plus Bluetooth 5.2, with two RP-SMA connectors for detachable dipole antennas and a USB 3.2 Gen 1 Type-A connector. Sold into the pentest/wardriving market specifically for its Linux monitor-mode and injection support, which is real but newer and less mature than Alfa's older Realtek-based adapters.","honest_take":"The MT7921AUN's monitor-mode and injection support on Linux is genuinely usable today — in-kernel mt7921u driver, no DKMS needed on kernel 5.18+ — but it is not the drop-in-and-forget experience of an older RTL8812AU adapter. Community reports (morrownr's USB-WiFi reference doc, and two open GitHub issues filed against this exact chipset/driver combination — one against morrownr/USB-WiFi, one against openwrt/mt76) describe passive monitor mode working well while 'active monitor mode' has a documented history of breaking the driver, only recently reported fixed on kernel 6.12 and later. If your workflow needs rock-solid injection today, the Realtek-based AWUS036ACH/ACHM are a safer bet; if you specifically need 6GHz/WiFi 6E visibility or onboard Bluetooth 5.2 (which the ACHM lacks entirely), there is no Realtek alternative and this is the adapter for it. As with the other Alfa adapter in this batch, it's 'just' a combo WiFi/BT chip in a plastic shell with two antenna jacks — the actual attack tooling is separate free software you run on your computer, not anything on the device. No GPS either, despite marketing copy about 'portable WiFi analysis' that could be mistaken for a wardriving feature.","aliases":["AWUS036AXM","Alfa WiFi 6E adapter"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"claimed","wifi_pmkid":"unknown","wifi_handshake_capture":"yes","wifi_wardriving":"partial","wifi_ap_mode":"claimed","packet_capture":"yes","gps":"no","ble_scan":"claimed","bt_classic":"unknown","usb_hid_inject":"no"},"legal":{"risk_level":"medium","notes":"Owning and selling is legal everywhere it's sold."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"ard-rfid-blocker","hardware_id":"ard-rfid-blocker","name":"ARD RFID Blocker (Pack of 2) - NFC Jammer","firmware_kind":"n/a","vendor":"Lab401 (product branded 'ARD')","category":"rfid-nfc","subcategory":"rfid-jammer-card","status":"available","price_usd":22.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"No setup - slip a card into a wallet/passport alongside the cards to be protected.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A credit-card-sized, battery-free card sold in packs of 2 by Lab401 that's placed in a wallet to disrupt 13.56MHz reads of nearby cards (MIFARE Classic/NTAG, generic NFC, EMV payment cards, passports, HID/iCLASS-family, SkiData). Lab401 markets it as 'active defense,' claiming it protects cards placed above or below it - unlike a Faraday sleeve, which must fully enclose each card individually. It does not read, write, or interact with any card's data - it only disrupts nearby reads - so the entire read/write/clone capability list below is 'no'.","honest_take":"Lab401's own description - 'no batteries needed, it takes its energy directly from the reader' - is the textbook definition of what the only independent academic study of blocking cards (Alecci et al., RAID 2023) calls a 'reactive' card: a field-powered resonant circuit that only generates noise while a reader is actively energizing it, not a genuinely battery-powered 'active' jammer that transmits continuously. That study found that real-world blocking cards, including some marketed as 'active,' were bypassed in 8 of 11 tested products simply by filtering the card's own (often near-white-noise) signature out of the recorded signal during post-processing - so 'active defense' is best read as a marketing term here, not a technical guarantee. No independent teardown of this specific ARD card was found (only of a different, genuinely battery-powered product, the ArmourCard, which turned out to be a simple coil+microcontroller design), so this classification rests on matching Lab401's own stated mechanism to the published taxonomy, not a physical inspection.","aliases":["ARD RFID Defence Card","ARD NFC Jammer","ARD RFID Blocker NFC Jammer"],"capabilities":{"hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","mifare_classic_attacks":"no","mifare_desfire":"no","nfc_type4_ndef":"no","emv_read":"no","iso15693":"no","felica":"no","magspoof":"no","nfc_relay":"no","standalone_untethered":"yes","scriptable":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"Because it's field-powered rather than an independent transmitter, this behaves legally more like a passive Faraday shield than a true RF jammer, so it should not run into the jamming-device prohibitions that apply to genuinely battery-powered, continuously-transmitting jammers (e."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"n/a","abandoned_risk":"low"}},{"id":"autoprober","hardware_id":"autoprober","name":"AutoProber","firmware":"Stock (GainSec)","firmware_kind":"diy","vendor":"GainSec","category":"hardware-debug","subcategory":"probing-automation","status":"diy-only","price_usd":700.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"Integrates a GRBL CNC, a computer-vision pad-detection pipeline and pogo-probe measurement into one automated stack - assumes you can already do manual PCB probing and are comfortable wiring/calibrating CNC motion control and (in the safety-hardened build) oscilloscope-based cutoffs.","build_effort":"full-diy","stealth":"overt","form_factor":"desktop","summary":"An open (source-available, noncommercial license) automation stack that turns a hobby CNC router, a USB microscope and (in the safety-hardened reference build) a networked oscilloscope into a semi-autonomous PCB-probing rig: an AI/computer-vision agent maps a board, identifies candidate pads/pins, presents targets through a web dashboard for operator approval, then drives a 3D-printed pogo-probe toolhead to take approved measurements, with an optional scope-monitored safety cutoff that halts motion if voltage thresholds are exceeded.","honest_take":"This replicates, on hobbyist CNC hardware, a category of automated flying-probe testing that is normally only found in expensive closed commercial lab equipment - genuinely notable, and independently covered by outside tech press (Gigazine), not just the developer's own promotion. But the project's own framing ('AI agents independently perform PCB analysis') still means computer-vision pad detection feeding into a mandatory operator review step before any probe moves, not unsupervised autonomous probing of a live board; the scope-monitored safety cutoff is the load-bearing part in the reference build, and the developer's own blog post admits a multimeter is actually more practical for a simpler build. Built in the author's own words in '5 late nights' and sitting at only 2 commits on GitHub despite 330 stars, this is a very early-stage project - budget for debugging the integration yourself, not a turnkey system.","released":"2026","aliases":[],"capabilities":{"uart":"addon","spi_flash_dump":"addon","i2c":"addon","jtag_swd":"addon","logic_analyzer":"no","glitching":"no","scriptable":"yes","web_ui":"yes","standalone_untethered":"no","sd_logging":"claimed","app_store":"no"},"legal":{"risk_level":"low","notes":"A lab-automation integration of off-the-shelf CNC, camera and oscilloscope hardware, with no radio transmitter and no inherent offensive capability - it probes boards you place under it."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-04","app_store":"No","abandoned_risk":"medium"}},{"id":"awok-dual-mini-v3","hardware_id":"awok-dual-mini-v3","name":"AWOK Dual Mini v3","firmware":"None shipped","firmware_kind":"community","vendor":"AWOK Dynamics","category":"accessory","subcategory":"flipper-multiboard","status":"discontinued","price_usd":140.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Ships blank; you flash two chips through two USB ports with two different binaries before it does anything.","build_effort":"flash-only","stealth":"overt","form_factor":"board","summary":"The smaller sibling of the Dual Touch: the same two-ESP32 architecture and onboard GPS, but with a 128x128 colour TFT and a five-way navigation joystick instead of a touchscreen. Like the Touch, it ships with no firmware and is meant to be flashed with Marauder or GhostESP.","honest_take":"Same caveats as the Touch, minus the flaky touch panel - which arguably makes the Mini the better of the two, since a joystick is a more reliable input than a three-zone tap surface. It is still two classic ESP32s, so still 2.4 GHz only, still no CC1101 and no nRF24, and still discontinued and sold out. Note that GhostESP's own hardware matrix lists the AWOK Mini as having no SD card support, which caps what you can do with packet capture on it.","released":"2024","aliases":["AWOK Dual Mini","Dual Mini v3","AwokMini"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"partial","wifi_wardriving":"yes","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","ble_scan":"yes","ble_spam_apple":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"unknown","standalone_untethered":"yes","subghz_rx":"no","nrf24_scan":"no"},"legal":{"risk_level":"medium","notes":"Same profile as the Dual Touch."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-09","app_store":"No - Marauder or GhostESP plus a Flipper companion FAP","abandoned_risk":"high"}},{"id":"awok-dual-touch-v3","hardware_id":"awok-dual-touch-v3","name":"AWOK Dual Touch v3","firmware":"None shipped","firmware_kind":"community","vendor":"AWOK Dynamics","category":"accessory","subcategory":"flipper-multiboard","status":"discontinued","price_usd":140.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"It arrives with no firmware. You must flash two separate chips with two different binaries through two different USB ports before it does anything.","build_effort":"flash-only","stealth":"overt","form_factor":"board","summary":"A Flipper Zero add-on carrying two physically separate ESP32-WROOM chips: one drives a 240x320 ILI9341 touchscreen for standalone use, the other faces the Flipper over GPIO. A single GPS receiver is routed to either or both chips by DIP switches. It ships with no firmware at all - AWOK sells it explicitly as a development board.","honest_take":"Get the naming straight first: 'Dual' here means two ESP32 chips, not dual-band. Both are classic ESP32-WROOM, so this board is 2.4 GHz only and blind to 5 GHz networks - the AliExpress boards marketed as 'dual' mean the opposite thing. The touchscreen is also less than it sounds: per AWOK's own support, the top of the screen is up, the bottom is down and the middle is select, so it is a three-zone tap surface, not a touch UI. There is no CC1101 and no nRF24 on this board despite the multiboard framing. And it is effectively end-of-life: sold out at the vendor, delisted by its EU distributor, superseded by the C5 version. Do not pay a reseller $220 for it.","released":"2024","aliases":["AWOK Dual Touch","Dual Touch v3","AWOK Dual ESP32 Touch"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"partial","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_wardriving":"yes","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","ble_scan":"yes","ble_spam_apple":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"unknown","standalone_untethered":"yes","subghz_rx":"no","nrf24_scan":"no"},"legal":{"risk_level":"medium","notes":"The board is two ESP32s and a GPS; we found no import restrictions."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-09","app_store":"No - Marauder or GhostESP, plus a Flipper companion FAP","abandoned_risk":"high"}},{"id":"bash-bunny-mk2","hardware_id":"bash-bunny-mk2","name":"Bash Bunny Mark II","firmware":"Bash Bunny","firmware_kind":"stock","vendor":"Hak5","category":"usb-hid","subcategory":"multi-vector-usb-attack","status":"available","price_usd":200.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Bash plus an understanding of USB device classes, target OS behaviour, and what a machine will trust from a freshly-enumerated Ethernet adapter.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A small Linux computer in an oversized USB stick that impersonates several trusted USB devices at once - keyboard, gigabit Ethernet adapter, serial port and flash drive - to attack a machine from multiple angles simultaneously. The Mark II adds Bluetooth LE for geofencing and remote triggering, plus a microSD slot for mass exfiltration.","honest_take":"The Bash Bunny's real weapon is not keystroke injection, it is USB Ethernet: when it enumerates as a network adapter, many operating systems will happily make it the default gateway and start sending traffic and credential material at it, which is what makes responder-style attacks so effective from a USB port. That is a genuinely different and more powerful class of attack than a Rubber Ducky. Two clarifications people get wrong. First, it does NOT run DuckyScript 3 - payloads are bash with QUACK-prefixed DuckyScript 1.0-derived commands, and Hak5's own docs tell you to append QUACK to most lines when porting a Ducky payload. Second, it has no Wi-Fi at all - a lot of secondary coverage gets this wrong. The only radio is Bluetooth LE, used for geofencing and remote triggers rather than as an attack radio, and the Bunny reaches a network only by tethering off the host it is plugged into. It is also not a Cloud C2 device. Worth noting that Hak5's own comparison table shows identical CPU and storage for the Mark I and Mark II while the prose alongside it claims faster performance and doubled RAM; the real, verifiable deltas are the microSD slot and BLE. At $200 for five-year-old silicon whose part number Hak5 has never published, this is priced on capability, not components.","released":"2021","aliases":["Bash Bunny","Bunny","Bash Bunny MK2","BB Mark II"],"capabilities":{"usb_hid_inject":"yes","usb_ethernet_attack":"yes","usb_mass_storage":"yes","usb_exfil":"yes","usb_payload_lang":"partial","hid_remote_trigger":"yes","ble_scan":"partial","cloud_c2":"no","sd_logging":"yes","wifi_scan_24":"no","scriptable":"yes","standalone_untethered":"yes","usb_keylogger":"no"},"legal":{"risk_level":"high","notes":"The USB Ethernet impersonation attack does not just enter commands, it intercepts network traffic and credential material - so unauthorised use can engage both computer-misuse and wiretap statutes."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-06","app_store":"Yes - official payload repository, 2,957 stars, last pushed 2026-06-13","abandoned_risk":"low"}},{"id":"biscuit-pro-stock","hardware_id":"biscuit-pro","name":"Biscuit Pro","firmware":"Biscuit (stock)","firmware_kind":"stock","vendor":"The Biscuit Shop","category":"wifi","subcategory":"dual-band-wifi-recon","status":"out-of-stock","price_usd":125.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"There is no screen and no buttons - everything happens in a phone app over Bluetooth, so you need the app working before the device does anything at all.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"A headless, deck-of-cards-sized Wi-Fi and BLE recon box with two radios doing two jobs: an ESP32-C5-WROOM-1 handles all dual-band 2.4 and 5 GHz scanning and attacking, while a separate ESP32-WROOM-32E holds the Bluetooth link to your phone and stores Evil Portal pages. You drive it entirely from a phone app. It genuinely reaches 5 GHz for scanning, raw PCAP capture and EAPOL/PMKID collection - which most devices claiming a C5 do not.","honest_take":"The dual-MCU split is real engineering rather than a spec-sheet flourish: because one chip never has to stop scanning to talk to your phone, captures do not drop while you use the app. And the 5 GHz support is documented in the vendor's own wiki rather than only on the sales page, which puts it ahead of most of this category. But three claims do not survive checking. 'Dual-band scanning 2.4 and 5 GHz simultaneously' is not possible - the C5 has one radio, and the vendor's own wiki describes it hopping channels one second at a time. 'BLE 5.0 + Classic' is wrong for the ESP32-WROOM-32E, which Espressif's datasheet puts at Bluetooth 4.2. And where 5 GHz stops is quietly undocumented: Evil Portal is restricted to channels 1, 6 and 11, the deauth-plus-EAPOL combo is documented as 2.4 GHz only, and plain 5 GHz deauthentication is neither claimed nor denied anywhere. The firmware is closed, there is no screen, no SD card, no GPS, no IR, no sub-GHz and no NFC - and you cannot buy one today.","released":"2026","aliases":["Biscuit","The Biscuit Shop Biscuit Pro"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"unknown","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_evil_twin":"partial","wifi_captive_portal":"partial","wifi_beacon_spam":"yes","wifi_karma":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"partial","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","zigbee":"partial","detect_flipper":"yes","detect_airtag":"yes","detect_skimmer":"partial","detect_pineapple":"yes","detect_pwnagotchi":"yes","detect_drone":"yes","detect_surveillance_cam":"partial","detect_generic_wifi":"yes","cloud_c2":"partial","subghz_rx":"no","ir_tx":"no","hf_1356_read":"no","lf_125khz_read":"no","usb_hid_inject":"no","gps":"no","sd_logging":"no","web_ui":"no","standalone_untethered":"partial","scriptable":"no","app_store":"no","nrf24_scan":"no","detect_deauth":"yes","detect_alpr":"claimed","detect_bodycam":"claimed","detect_meshtastic":"claimed"},"legal":{"risk_level":"medium","notes":"Owning it is legal in most places."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"medium"}},{"id":"biscuit-ultra","hardware_id":"biscuit-ultra","name":"Biscuit Ultra","firmware":"Biscuit (stock)","firmware_kind":"stock","vendor":"The Biscuit Shop","category":"wifi","subcategory":"dual-band-wifi-recon","status":"out-of-stock","price_usd":160.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"No screen and no buttons - everything happens through a phone app over Bluetooth, identical to the Pro.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"The larger sibling to the already-tracked Biscuit Pro, sharing its dual-MCU architecture (an ESP32-C5-WROOM-1 doing all Wi-Fi/BLE scanning and attacking, an ESP32-WROOM-32E holding the phone-app Bluetooth link) in a bigger enclosure with a 3200mAh battery, dual external RP-SMA antenna connectors, a microSD slot for autonomous offline PCAP logging, and support for external 'node' devices extending scan coverage - none of which the Pro has.","honest_take":"The upgrades over the Pro are real and address the Pro's actual weak points rather than being cosmetic: the Pro has no SD card and about a third of the Ultra's claimed battery life, so if you found the Pro's runtime or lack of offline logging frustrating, the Ultra specifically fixes that. But it inherits every one of the Pro's overclaims: 'dual-band scanning 2.4 and 5GHz simultaneously' is not possible with the C5's single radio (it hops channels, per the vendor's own wiki), the WROOM-32E's Bluetooth is 4.2 per Espressif's datasheet despite marketing claiming 'BLE 5.0 + Classic', and there is still no screen, no GPS, no sub-GHz, no NFC and no IR. Same closed firmware, same single-maintainer risk, and a 'do not buy if you have a Nothing 4a pro' compatibility warning on the vendor's own page that should give any buyer pause about how broadly this has been tested against real phones.","released":"2026","aliases":["Biscuit","The Biscuit Shop Biscuit Ultra"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"unknown","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_evil_twin":"partial","wifi_captive_portal":"partial","wifi_beacon_spam":"yes","wifi_karma":"yes","wifi_wardriving":"partial","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","zigbee":"partial","detect_flipper":"yes","detect_airtag":"yes","detect_pineapple":"yes","detect_surveillance_cam":"partial","sd_logging":"yes","cloud_c2":"partial","subghz_rx":"no","hf_1356_read":"no","lf_125khz_read":"no","ir_tx":"no","gps":"no","usb_hid_inject":"no","web_ui":"no","scriptable":"no"},"legal":{"risk_level":"medium","notes":"Owning it is legal in most places."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"medium"}},{"id":"bjorn","hardware_id":"bjorn","name":"Bjorn","firmware":"Bjorn (infinition)","firmware_kind":"diy","vendor":"Community project (infinition)","category":"network-implant","subcategory":"autonomous-lan-attacker","status":"diy-only","price_usd":70.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"The install script does most of the work, but it insists on a specific OS image, a username and hostname of 'bjorn', and a matching e-Paper panel revision - get any of those wrong and you get a blank screen with no useful error.","build_effort":"assembly","stealth":"discreet","form_factor":"pocket","summary":"A Raspberry Pi with a 2.13in e-ink screen that autonomously works a network: it discovers live hosts, scans ports, fingerprints services, runs Nmap vulnerability scripts, then brute-forces FTP, SSH, SMB, RDP, Telnet and SQL logins and pulls files off anything it gets into. A Viking character on the display gains 'levels' as it succeeds, which is the hook that made it popular.","honest_take":"Be very clear what this is: it is not a passive collector like a Pwnagotchi, it is an autonomous credential brute-forcer that steals files, and running it on a network you do not own is straightforwardly a crime in most countries - the cute Viking does not change that. Technically there is nothing here you could not do with a shell script wrapping nmap and hydra; what Bjorn adds is the orchestration, the e-ink UI and the game loop. It also brute-forces loudly, so any network with account lockout, fail2ban or basic monitoring will catch it almost immediately. The 6,000+ stars measure how good the idea looks in a demo video, not how useful it is on a real engagement.","released":"2024","aliases":["Bjorn Pi","infinition Bjorn"],"capabilities":{"packet_capture":"no","ethernet_mitm":"no","usb_exfil":"yes","wifi_scan_24":"partial","wifi_monitor_mode":"no","web_ui":"yes","scriptable":"yes","sd_logging":"yes","standalone_untethered":"yes","cloud_c2":"no"},"legal":{"risk_level":"high","notes":"Higher risk than most things in this batch, because the device's normal operation is unauthorised access."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"No - custom Python action modules instead","abandoned_risk":"medium"}},{"id":"bladerf-2-micro-xa4","hardware_id":"bladerf-2-micro-xa4","name":"bladeRF 2.0 micro xA4","firmware":"Stock","firmware_kind":"stock","vendor":"Nuand","category":"sdr","subcategory":"full-duplex-transceiver","status":"available","price_usd":540.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Full-duplex 2x2 MIMO is only useful if you can drive GNU Radio or write FPGA/host DSP.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An AD9361-based full-duplex SDR covering 47 MHz to 6 GHz with 2x2 MIMO, 56 MHz of filtered bandwidth and a user-programmable Cyclone V FPGA. This is the machine people move to when a HackRF's half-duplex 8-bit front end stops being enough - notably for cellular work (LTE/5G test stacks such as srsRAN and Open5GS).","honest_take":"Three to four times the price of a HackRF and it needs USB 3.0, real antennas and real DSP skill. Nothing about it is turnkey: there are no built-in attacks, no app catalogue, and if your workflow is 'capture a garage remote and replay it' you are wasting most of the hardware.","released":"2018","aliases":["bladeRF micro","bladeRF 2.0"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"yes"},"legal":{"risk_level":"medium","notes":"Transmitting on cellular bands, even in a lab, can radiate outside your building and is illegal without a licence or a shielded enclosure in most countries."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No - GNU Radio, SoapySDR, srsRAN and similar","abandoned_risk":"low"}},{"id":"michalmonday-ble-badusb-jdy08","hardware_id":"michalmonday-ble-badusb-jdy08","name":"BLE BadUSB (JDY-08)","firmware":"supremeDuck","firmware_kind":"community","vendor":"michalmonday","category":"usb-hid","subcategory":"ble-badusb-stick","status":"discontinued","price_usd":25.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Programmable with the Arduino IDE; the accompanying supremeDuck Android app's Google Play listing was removed for inactivity, so triggering payloads today likely means driving the BLE link yourself rather than using an official companion app.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"An ATmega32U4 USB stick paired with a JDY-08 Bluetooth 4.0 module, remotely triggerable over BLE to fire DuckyScript-compatible keystroke/mouse-injection payloads via the open-source supremeDuck firmware. It has been sold out since 2019.","honest_take":"This is the BLE sibling of the same maker's Wifi BadUSB, using identical core silicon (ATmega32U4) with a different radio bolted on, and the honest headline is that it's been unavailable for seven years - this belongs in the database as a documented historical/reference design rather than something to actually go buy. Its JDY-08 module is explicitly BLE 4.0 only and the listing warns it will not connect to a phone that only supports BLE 4.2, which is itself a sign of the module's age; the maker's own comparison notes it has no BLE pairing password at all, and its ~5m range is the shortest of the maker's three variants (WiFi and the JDY-10 BLE variant both reach roughly 14m). If BLE-triggered BadUSB is what you're after today, expect to build this yourself from the open EasyEDA files rather than purchase an assembled unit.","aliases":[],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"unknown","usb_exfil":"unknown","usb_keylogger":"no","hid_remote_trigger":"yes","usb_payload_lang":"yes","scriptable":"yes","ble_hid":"yes","ble_scan":"no","standalone_untethered":"no","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning the device is legal."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"unknown exact date; supremeDuck repo shows 155 commits and 241 stars","app_store":"No - official Android companion app pulled from Google Play for inactivity","abandoned_risk":"high"}},{"id":"hackgnar-ble-ctf","hardware_id":"generic-esp32-ble-ctf","name":"BLE CTF","firmware":"ble_ctf","firmware_kind":"community","vendor":"hackgnar (open source project)","category":"bluetooth","subcategory":"ble-training-target","status":"diy-only","price_usd":8.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Designed specifically as a learning ramp: starts at basic GATT reads and progresses to challenge-response authentication and multi-response notifications across 30 flags.","build_effort":"flash-only","stealth":"discreet","form_factor":"board","summary":"A deliberately vulnerable BLE GATT server used as a hands-on capture-the-flag: 30 progressively harder challenges teaching GATT enumeration, characteristic read/write, notifications, descriptors and challenge-response authentication. It is the de facto standard practice target for learning BLE exploitation, referenced across many independent walkthroughs.","honest_take":"This is a training target, not an attack device - it does nothing to anyone else's equipment and has no offensive capability of its own; the attacker brings their own BLE scanning/GATT client tooling (gatttool, a phone's nRF Connect app, or another device in this database) and this box is simply the thing being practiced against. Its value is entirely in the progressive challenge design and the large body of independent write-ups that exist for when you get stuck - 776 stars and multiple community walkthroughs make it genuinely well-trodden ground for BLE learning, unlike a lot of single-purpose ESP32 firmware in this space.","aliases":["ble_ctf","BLECTF"],"capabilities":{"ble_advertise":"yes","ble_scan":"no","ble_sniff":"no","ble_jam":"no","ble_hid":"no","bt_classic":"no","ble_spam_apple":"no","findmy_track":"no","scriptable":"no","standalone_untethered":"yes","web_ui":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"A self-hosted training target with no offensive function of its own; there is no legal exposure from owning or running it."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"blekey","hardware_id":"blekey","name":"BLEKey","firmware":"BLEKey (LinkLayer)","firmware_kind":"third-party-product","vendor":"LinkLayer (sold via Hacker Warehouse)","category":"rfid-nfc","subcategory":"access-control-implant","status":"out-of-stock","price_usd":35.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Reader installation plus phone-side BLE tooling from 2015.","build_effort":"assembly","stealth":"implant","form_factor":"board","summary":"The original Bluetooth Low Energy Wiegand tap, released at Black Hat 2015: hide it in a card reader, let it sniff badge swipes, then collect them from a phone over BLE and optionally replay a captured credential to the reader. Historically important - it is the device The Tick and ESPKey were designed to improve on.","honest_take":"Effectively dead. The repository has not been touched since 2017, has no licence file, and the product has been out of stock at its only reseller for years. It is battery powered rather than reader powered, so it runs down. Listed here because it is still widely name-checked in access-control talks and buyers should know to reach for The Tick or ESPKey instead.","released":"2015","aliases":["BLE Key"],"capabilities":{"lf_125khz_read":"partial","lf_125khz_emulate":"partial","ble_scan":"no","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"A covert credential tap; unauthorised installation is unlawful interception and tampering."},"ecosystem":{"community":"dead","docs_quality":"sparse","last_release":"2017","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"bleshark-nano-stock","hardware_id":"bleshark-nano","name":"BLEShark Nano","firmware":"InfiShark stock","firmware_kind":"stock","vendor":"InfiShark Technologies Inc.","category":"multitool","subcategory":"wifi-ble-ir-handheld","status":"available","price_usd":50.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Three buttons and a tiny OLED menu; there is also a documented Rust CLI and SDK if you want to drive it from a computer.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A 50-dollar pocket toy built on a Seeed XIAO ESP32-C3 module with a 0.66in 64x48 OLED, a 500mAh cell and an infrared transmitter and receiver. It does 2.4 GHz Wi-Fi recon and attacks, BLE advertisement spam, IR remote work, a handful of arcade games, and an ESP-NOW mesh mode that links up to sixteen units into one coordinated rig. No sub-GHz, no NFC, no nRF24, no microSD.","honest_take":"It is honestly what it says it is at the price, but two claims need correcting. It has no USB HID and physically cannot: the ESP32-C3's USB block is a fixed-function serial/JTAG controller with no OTG, and InfiShark's own documentation concedes the device 'only ever acts as a device, never as a host'. What it calls Bad-BT is a Bluetooth keyboard that the target has to pair with first, which is a far weaker attack than plugging in a rubber ducky. Second, the firmware is closed and the public GitHub repo is archived with nothing in it - so the archived v0.8 binary from early 2025 is the last thing anyone outside the vendor has been able to look at, while shipping units are years past it. If you are in the EU you are also buying a different product: EU firmware ships with deauthentication removed to satisfy the Radio Equipment Directive, and there are community guides devoted to VPNing around the geo-locked update server.","released":"2024","aliases":["BLEShark","BLE Shark Nano","BLS-N-001"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"partial","wifi_deauth_5":"no","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_beacon_spam":"yes","wifi_ap_mode":"yes","wifi_wardriving":"no","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_swift_pair":"yes","ble_hid":"yes","usb_hid_inject":"no","usb_payload_lang":"yes","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","detect_flipper":"unknown","detect_airtag":"partial","subghz_rx":"no","nrf24_scan":"no","hf_1356_read":"no","lf_125khz_read":"no","sd_logging":"no","gps":"no","scriptable":"partial","app_store":"no","standalone_untethered":"yes","web_ui":"partial","games":"yes","txt_viewer":"yes","video_player":"no","timer_stopwatch":"yes","pc_monitor":"claimed","emergency_mode":"yes"},"legal":{"risk_level":"medium","notes":"This is one of the very few devices in this class with a proper compliance paper trail: FCC Grant of Equipment Authorization and SDoC, Canadian ICES-003, CE RED/EMC/RoHS, UKCA plus a UK PSTI statement, Australian/NZ RCM, and a published security-support commitment through 30 September 2027."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025-02","app_store":"No","abandoned_risk":"medium"}},{"id":"proxmark3-rdv4-blueshark-module","hardware_id":"proxmark3-rdv4-blueshark-module","name":"Bluetooth + Battery Module for Proxmark3 RDV4 (Blue Shark)","firmware_kind":"n/a","vendor":"RFID Research Group (ProxGrind)","category":"rfid-nfc","subcategory":"proxmark-accessory","status":"available","price_usd":100.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Clips onto the RDV4 with no soldering; the skill required is entirely in using the standalone modes it enables, not installing the module.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"The official RRG/ProxGrind battery-and-Bluetooth add-on for the Proxmark3 RDV4, commonly called 'Blue Shark'. It supplies a 400mAh Li-Po and a Bluetooth 2.0 EDR radio (~6m range at 4dBm), which is what turns the RDV4 from a USB-tethered bench tool into something that can run its standalone offline sniffing/reading/simulation modes untethered in the field.","honest_take":"This module adds no RFID capability of its own - every read/write/emulate/attack capability lives in the Proxmark3 RDV4 it clips onto, which is already tracked separately in this database. What it actually buys you is a name for something the RDV4 could technically do already via its onboard SPI flash and standalone-mode firmware: run away from a laptop. Without this (or an equivalent Proxmark5 wireless module) the RDV4's ~40 standalone modes are a checkbox feature nobody can use in the field. Bluetooth 2.0 EDR at 4dBm/~6m range is dated compared to BLE, and the module is a genuine RDV4-specific fit - it will not clip onto a Proxmark3 Easy or a Proxmark 5, which use different connectors and wireless standards entirely (the Proxmark 5's equivalent module is a separate SKU in this same batch).","aliases":["Blue Shark","BlueShark Module","Proxmark 3 RDV4 BlueShark Standalone Module"],"capabilities":{"hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","lf_125khz_read":"no","lf_125khz_write":"no","mifare_classic_attacks":"no","iso15693":"no","felica":"no","nfc_relay":"no","bt_classic":"yes","ble_scan":"no","standalone_untethered":"yes","sd_logging":"no","web_ui":"no","scriptable":"no"},"legal":{"risk_level":"medium","notes":"A power/Bluetooth accessory carries no legal exposure of its own beyond whatever applies to the Proxmark3 RDV4 it is attached to - see that device's record for the relevant legal notes on RFID reading/cloning."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"bluetooth-ducky-esp32","hardware_id":"generic-esp32-bluetooth-ducky","name":"Bluetooth Ducky","firmware":"Bluetooth Ducky","firmware_kind":"community","vendor":"Linuxndroid (open source project)","category":"bluetooth","subcategory":"ble-hid-injection-firmware","status":"diy-only","price_usd":8.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Requires manual code customization and Arduino IDE compilation before deployment - payloads aren't loaded from an SD card the way a USB Rubber Ducky's are, you edit and reflash source.","build_effort":"flash-only","stealth":"covert","form_factor":"board","summary":"Open-source firmware that turns an ESP32 into a BLE HID keyboard emulator, running Ducky Script-style keystroke payloads (open apps, type URLs, run commands) once paired with a target across Windows, macOS, Linux and Android. Positioned as a wireless alternative to a USB Rubber Ducky that doesn't need physical USB port access.","honest_take":"The 'no physical USB access needed' pitch is real but comes with a big asterisk the project name doesn't advertise: unlike a USB Rubber Ducky, which a target device trusts instantly on physical insertion, this requires the victim to see and accept a Bluetooth pairing prompt the first time - it is not silent on first contact. After that initial pairing it can auto-reconnect quietly, so the realistic attack path is 'get physical access once to pair it, walk away, trigger payloads remotely later,' not 'wave it near an unlocked laptop and go.' It only works against hosts that accept unauthenticated BLE HID pairing, which is common but not universal. At 42 GitHub stars this is a small, lightly-used project compared to established BadUSB tooling - expect rougher edges.","released":"2025","aliases":["BluetoothDucky","BLE Ducky"],"capabilities":{"ble_hid":"yes","ble_advertise":"yes","ble_scan":"no","ble_sniff":"no","ble_jam":"no","bt_classic":"no","usb_hid_inject":"no","usb_payload_lang":"partial","hid_remote_trigger":"yes","scriptable":"yes","standalone_untethered":"partial","findmy_track":"no"},"legal":{"risk_level":"high","notes":"Injecting keystrokes into a device you don't own or lack authorization to test is unauthorized computer access in essentially every jurisdiction, and the project's own README says as much."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"2025-07","app_store":"No","abandoned_risk":"medium"}},{"id":"bluetooth-nugget-esp32s3","hardware_id":"bluetooth-nugget-esp32s3","name":"Bluetooth Nugget (ESP32S3)","firmware":"Nugget","firmware_kind":"community","vendor":"Retia","category":"bluetooth","subcategory":"nugget-lineage","status":"out-of-stock","price_usd":80.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Browser-based flashing via nugget.dev; six physical buttons and an OLED screen for on-device payload selection without needing a laptop connected.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"The ESP32-S3-based member of the Nugget educational hacking-platform family, adding native Bluetooth/BLE to the Wi-Fi monitor-mode scanning and USB-HID keystroke-injection capability the ESP8266/ESP32-S2 Nuggets had. Dual-core with roughly double the older single-core Nugget's performance, an OLED screen and six buttons for on-device use, and an optional LoRa 'backpack' add-on for Meshtastic.","honest_take":"The performance-marketing language here ('7-8x faster image processing', 'nearly double the performance') is standard ESP32-S3-vs-S2 chip-spec talk dressed up as a product achievement - it is true of any board that swaps an S2 for an S3, not something Retia specifically engineered. The genuinely new thing is native BLE, which the older Wi-Fi/USB Nuggets did not have, and the publicly demoed BLE pairing-popup spam is a real, if by now well-worn, iOS/Android nuisance attack rather than anything novel. Whether this firmware is open source the way the original WiFi Nugget was is not stated anywhere on the product page, and no dedicated GitHub repo for this specific board was found - worth confirming before assuming it can be audited or forked.","released":"2026","aliases":["BLE Nugget"],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","wifi_monitor_mode":"yes","wifi_scan_24":"yes","wifi_deauth_24":"unknown","wifi_scan_5":"no","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"claimed","bt_classic":"no","subghz_rx":"addon","hf_1356_read":"no","ir_tx":"no","gps":"no","sd_logging":"unknown","mesh_lora":"addon"},"legal":{"risk_level":"medium","notes":"USB-HID injection against a computer you don't have authorization to test, and BLE pairing-spam against phones you don't own, both carry computer-misuse exposure depending on jurisdiction."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"bombercat","hardware_id":"bombercat","name":"BomberCat","firmware":"Stock","firmware_kind":"stock","vendor":"Electronic Cats","category":"rfid-nfc","subcategory":"payment-terminal-audit","status":"available","price_usd":119.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Relay work involves two endpoints, Wi-Fi setup and an understanding of EMV flows.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An open-hardware board combining an NXP PN7150 NFC controller, an RP2040 and an ESP32 co-processor with an on-board MagSpoof coil, so one device covers both contactless and magnetic-stripe emulation. Its headline feature is acting as an NFCGate-compatible relay endpoint over Wi-Fi for testing whether a payment terminal accepts a relayed transaction.","honest_take":"The magstripe side is Samy Kamkar's MagSpoof trick, which works on readers that still accept swipe and does nothing to chip-and-PIN. The relay mode does not break EMV cryptography - it forwards a live card's responses, so it needs a real card in play at the other end and it takes roughly 4.5 seconds per transaction, which many terminals time out. Treat it as a way to test whether a terminal's defences (timing, distance bounding, CVM rules) actually work, not as a way to steal money.","released":"2022","aliases":["Bomber Cat"],"capabilities":{"hf_1356_read":"yes","hf_1356_emulate":"yes","nfc_type4_ndef":"yes","emv_read":"partial","nfc_relay":"yes","magspoof":"yes","lf_125khz_read":"no","wifi_ap_mode":"yes"},"legal":{"risk_level":"high","notes":"Emulating payment cards and relaying transactions maps directly onto fraud statutes; several countries also criminalise possessing devices designed to skim or emulate cards."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"bruce-rf-reaper","hardware_id":"bruce-rf-reaper","name":"Bruce RF Reaper","firmware":"Bruce","firmware_kind":"community","vendor":"Elecrow (for the Bruce project)","category":"multitool","subcategory":"rf-multitool","status":"out-of-stock","price_usd":80.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"It has no built-in display, ships as a bare PCBA, and expects you to source antennas, GPS and a case yourself.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"The Bruce project's purpose-built board: an ESP32-S3 with 16MB flash and 8MB PSRAM, a real CC1101 sub-GHz transceiver, an ST25R3916 NFC front end, an amplified 2.4GHz module, eight IR LEDs for transmit and receive, a GPS header, microSD and an AW9523 I/O expander with Flipper Zero and iButton header compatibility. It is what Bruce looks like when the hardware matches the firmware.","honest_take":"This is the honest answer to 'Bruce has loads of features that need modules' - here they are all on one board, and the ST25R3916 is the same NFC front end the Flipper Zero uses. But it ships as a bare PCBA with no display, no antenna, no GPS and no case, so the $80 sticker is not the finished cost and it is not a device you hand to a beginner. It has been out of stock, which is the recurring story with small-batch community hardware. The 2.4GHz 'jammer' is an amplified module doing protocol spam and constant carrier, not wideband jamming - amplifying it makes it a louder nuisance and a bigger regulatory problem, not a different capability. On the Wi-Fi side it inherits the usual ceiling: deauth only works where management frames are unprotected, so 802.11w/PMF defeats it and WPA3 mandates PMF.","released":"2026","aliases":["RF Reaper","Bruce PCB RF Reaper"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_monitor_mode":"yes","packet_capture":"yes","ethernet_mitm":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_hid":"yes","bt_classic":"no","usb_hid_inject":"yes","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_external_antenna":"yes","subghz_amplified":"yes","hf_1356_read":"yes","hf_1356_write":"yes","mifare_classic_attacks":"unknown","hf_1356_emulate":"no","lf_125khz_read":"partial","nrf24_scan":"yes","nrf24_jam":"yes","mousejack":"no","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ibutton_1wire":"yes","gps":"addon","gps_wardrive_log":"addon","sd_logging":"yes","scriptable":"yes","web_ui":"yes","standalone_untethered":"partial"},"legal":{"risk_level":"high","notes":"This board combines an amplified sub-GHz transmitter, an amplified 2."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-08","app_store":"No - JavaScript interpreter and web flasher","abandoned_risk":"low"}},{"id":"bruschetta-board-whid","hardware_id":"bruschetta-board","name":"BRUSCHETTA Board","firmware_kind":"n/a","vendor":"Luca Bongiorni (WHID Injector), manufactured/distributed by AprBrother","category":"hardware-debug","subcategory":"multi-protocol-probe","status":"available","price_usd":70.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Requires understanding target voltage selection, DIP-switch operating modes, and separately compiling/using OpenOCD, flashrom, or ch347eeprom - not plug-and-play for a total beginner.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"BRUSCHETTA Board is Luca Bongiorni's (WHID Injector) open, assembled multi-protocol debugger built around WCH's CH347 USB bridge chip, wired for UART, JTAG/SWD (via a Bongiorni-patched OpenOCD build), I2C (EEPROM read/write via his ch347eeprom tool), and SPI (including flash chip dumping via flashrom's ch347_spi driver). A DIP switch selects between two main modes (UART+I2C+SPI, or UART+JTAG) and jumper-selectable level shifters cover 1.8V-5V targets.","honest_take":"This sits in the exact niche already covered by Bus Pirate 5 and Tigard in this database, and it doesn't clearly beat either. It's built on a single off-the-shelf WCH CH347 bridge chip rather than a general-purpose MCU (Bus Pirate 5 uses an RP2040) or a dedicated FTDI part (Tigard uses an FT2232H), and its protocols are split across two DIP-switch-selected modes rather than all available simultaneously - you have to physically flip the switch and unplug I2C/SPI devices before using it as a JTAG debugger. The GitHub repo has had no commits since October 2024, is maintained by one person, and carries no license file. The genuine draw is that it's Luca Bongiorni's own board with his own OpenOCD fork already patched for CH347 and flashrom support baked in, and it undercuts Tigard on price - a reasonable pick if you're already using his WHID toolset, but not an obvious upgrade over the probes already tracked here.","released":"2023","aliases":["BURSCHETTA Board (alternate spelling seen on some reseller listings)"],"capabilities":{"uart":"yes","spi_flash_dump":"yes","i2c":"yes","jtag_swd":"yes","logic_analyzer":"no","glitching":"no","web_ui":"no","standalone_untethered":"no","usb_mass_storage":"no","scriptable":"yes"},"legal":{"risk_level":"low","notes":"A wired, non-radio debug/programmer tool - owning and using it is not restricted anywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2024-10","app_store":"N/A","abandoned_risk":"medium"}},{"id":"bugblat-minisniffer-2","hardware_id":"bugblat-minisniffer-2","name":"BugBlat miniSniffer 2","firmware_kind":"n/a","vendor":"BugBlat","category":"hardware-debug","subcategory":"usb-analyzer","status":"available","price_usd":99.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-play capture via BugBlat's own desktop app, but making sense of raw USB packet dumps or using the Python/Lua/C++ APIs for custom tooling needs real USB protocol knowledge.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A small (about half a credit card) inline USB protocol analyzer that sits between host and target device, sampling Low/Full/High-Speed USB traffic with an onboard FPGA and streaming or buffering (up to 256MB compressed) captures to a PC over a Cypress FX2LP USB-C link. BugBlat has sold sniffers of this family since the 2000s, aimed at USB firmware/device developers rather than consumer hobbyists.","honest_take":"The 'FPGA samples the bus, FX2LP handles the buffered high-speed USB uplink' architecture is the standard pattern for this whole product category (the same split used by the open-source Taradov design and OpenVizsla) - BugBlat just never names the actual FPGA part in any public material, so you're trusting a closed design for the part that actually does the sampling. The genuinely open piece is the host-side Python/Lua/C++ capture API on GitHub (MIT), not the gateware. At $99.99 direct it's a fair price for a real LS/FS/HS sniffer with meaningful buffer depth; paying lab401's $160-195 for the identical board is paying a real premium for UK/EU stock convenience.","released":"2019","aliases":["miniSniffer2","miniSniffer2b"],"capabilities":{"standalone_untethered":"partial","usb_hid_inject":"no","usb_mass_storage":"no","usb_keylogger":"no","hid_remote_trigger":"no","jtag_swd":"no","uart":"no","i2c":"no","spi_flash_dump":"no","ethernet_tap_passive":"no"},"legal":{"risk_level":"low","notes":"Passively capturing USB traffic on hardware you own/control is broadly legal."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"2024-03","app_store":"No","abandoned_risk":"low"}},{"id":"bus-pirate-5","hardware_id":"bus-pirate-5","name":"Bus Pirate 5","firmware":"Stock (Dangerous Prototypes)","firmware_kind":"stock","vendor":"Dangerous Prototypes","category":"hardware-debug","subcategory":"protocol-bridge","status":"available","price_usd":75.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The terminal interface is friendlier than most, and the on-screen display showing live pin voltages removes a lot of the guesswork that makes hardware hacking frustrating.","build_effort":"assembled","stealth":"overt","form_factor":"pocket","summary":"A universal serial-protocol bridge: eight IO pins that can speak 1-Wire, I2C, SPI, UART, MIDI and addressable-LED protocols from an interactive terminal, plus a programmable 1-5 V supply with current limiting and a colour LCD that shows what every pin is doing. The modern rewrite of a tool that has been in hardware hackers' bags since 2008.","honest_take":"It is a bench tool for talking to chips, not an attack tool. The genuinely useful part is not the protocol support - a $5 FTDI cable does UART - it is the current-limited programmable supply and the live per-pin voltage display, which between them stop you from destroying the target while you work out what its pinout is. Two caveats for this comparison: its documented protocol modes do not include JTAG, so for JTAG or SWD you want a Tigard, Glasgow or JTAGulator instead; and its IO range starts at 1.2 V, which is better than most, but it is a level-translated bridge rather than a full logic analyser.","released":"2024","aliases":["BP5","Bus Pirate v5"],"capabilities":{"uart":"yes","i2c":"yes","spi_flash_dump":"yes","jtag_swd":"unknown","logic_analyzer":"claimed","glitching":"no","scriptable":"partial","ibutton_1wire":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A bench instrument with no radio and no ability to interfere with anything wireless."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"bus-pirate-v3-6","hardware_id":"bus-pirate-v3-6","name":"Bus Pirate v3.6","firmware":"Community firmware v6.x/v7.x","firmware_kind":"community","vendor":"Dangerous Prototypes (design is open; boards made by many)","category":"hardware-debug","subcategory":"protocol-bridge","status":"discontinued","price_usd":30.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Same conceptual difficulty as the Bus Pirate 5, but with a plain terminal and no display to tell you what is going on.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The original Bus Pirate, built on a Microchip PIC24 with five IO pins at 3.3 V logic. Superseded by the Bus Pirate 5 in almost every respect, but still worth knowing about because a decade and a half of hardware-hacking tutorials, courseware and forum answers are written against it specifically.","honest_take":"Where it still fits is documentation, not capability. If you are following an older write-up or a training course that says 'connect your Bus Pirate and type m for mode', it means this one, and the command syntax carried over only partly to the Bus Pirate 5. It is also cheap enough to be disposable. Everything else argues for the newer board: 3.3 V logic with no 1.8 V support at all is a real problem on modern targets, it is much slower, and the firmware has not meaningfully moved in years. Buy it as a second cheap unit or to follow old tutorials; do not buy it as your only tool.","released":"2010","aliases":["Bus Pirate v3","BPv3","Bus Pirate 3.6"],"capabilities":{"uart":"yes","i2c":"yes","spi_flash_dump":"partial","jtag_swd":"partial","logic_analyzer":"partial","glitching":"no","ibutton_1wire":"yes","scriptable":"partial","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A bench instrument with no radio."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2020","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"buskill-cable-kit","hardware_id":"buskill","name":"BusKill","vendor":"Alt Shift / BusKill","category":"accessory","subcategory":"dead-man-switch","status":"available","price_usd":99.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Basic screen-lock/shutdown triggers are point-and-click through the companion app; the LUKS self-destruct trigger requires hand-editing udev rules and shell scripts on Linux.","build_effort":"assembled","stealth":"discreet","form_factor":"cable","summary":"A laptop dead-man's switch: a USB extension cable interrupted by a strong magnetic breakaway connector that clips to your body. The cable itself is dumb hardware with no chip — all detection and response logic runs as software on the laptop, watching for that specific USB device's removal and firing a configured trigger (lock screen, shutdown by default; an optional, off-by-default script can shred a Linux LUKS header).","honest_take":"There's no electronics in the BusKill cable at all — it's a magnetic USB breakaway connector, and the 'smarts' are entirely the open-source buskill-app watching for that specific device to disappear. The LUKS self-destruct feature that shows up in most coverage of this device is NOT included by default and not what you get by just buying the cable: BusKill's own docs state plainly it 'will not be released with this self-destruct trigger' — you have to write your own udev rule and script to wire it up, Linux-only, and it is irreversible (no pre-made backup of the LUKS header means permanent data loss, including from an accidental trip). The plain lock/shutdown triggers are reliable and low-risk; the self-destruct trigger people associate with the product name is a DIY add-on with real failure modes of its own (SSD wear-leveling can leave key material behind despite an overwrite, and an accidental snag destroys everything with no recovery).","released":"2020","aliases":["BusKill Cable","BusKill Kit"],"capabilities":{"hardware_destruct":"addon","device_lock":"yes","emergency_mode":"yes","usb_mass_storage":"no","usb_hid_inject":"no","usb_keylogger":"no","scriptable":"yes","standalone_untethered":"no","sd_logging":"no","cloud_c2":"no","wifi_ap_mode":"no"},"legal":{"risk_level":"medium","notes":"Owning and using the default lock/shutdown triggers is legal everywhere the authors are aware of."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"No","abandoned_risk":"low"}},{"id":"c5-lowkey-flipper-zero","hardware_id":"c5-lowkey","name":"C5 LowKey - Flipper Zero","firmware":"ESP32 Marauder","firmware_kind":"third-party-product","vendor":"JCMK LLC (JustCallMeKoko)","category":"wifi","subcategory":"flipper-wifi6-wardriving-module","status":"out-of-stock","price_usd":44.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plugs straight into Flipper GPIO and is controlled from the Flipper Marauder app, but interpreting Wi-Fi 6/5GHz scan results and wardriving logs assumes some existing Wi-Fi security background.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A Flipper Zero GPIO daughterboard with an ESP32-C5 soldered directly to the PCB (no separate DevKit needed), preloaded with ESP32 Marauder firmware. The headline feature over older ESP32-S3 Marauder boards is 5GHz Wi-Fi support, plus an onboard GPS module for wardriving logged straight to microSD.","honest_take":"The silicon underneath is a $15 Espressif dev-board chip running the same open-source Marauder firmware available free for a dozen other ESP32 boards - the $44 buys assembly, the GPS module, and a case, not novel capability. The real reason to pick this over an ESP32-S3 Marauder board is genuine 5GHz support, but ESP32-C5 has a single RF front end shared between 2.4 and 5GHz - it cannot monitor or scan both bands simultaneously, only switch between them, despite 'dual-band' branding implying otherwise. It is currently sold out at the vendor.","released":"2026","aliases":["Marauder C5 LowKey"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"claimed","wifi_beacon_spam":"yes","wifi_evil_twin":"claimed","wifi_probe_sniff":"yes","wifi_pmkid":"yes","wifi_wardriving":"yes","wifi_ap_mode":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","ble_scan":"unknown","bt_classic":"no","nrf24_scan":"no","subghz_rx":"no","zigbee":"unknown","app_store":"no","standalone_untethered":"partial"},"legal":{"risk_level":"medium","notes":"Owning the board is legal in the US."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"unknown","app_store":"No - Marauder companion app only","abandoned_risk":"low"}},{"id":"c5-wardriver-dualband","hardware_id":"c5-wardriver","name":"C5 Wardriver","firmware":"ESP32 Dual Band Wardriver","firmware_kind":"stock","vendor":"JustCallMeKoko LLC","category":"wardriving","subcategory":"dual-band-wardriver","status":"out-of-stock","price_usd":69.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Slot in the dev board, add a cell, set it up through a captive portal in a browser. It does one thing and the UI is built around that one thing.","build_effort":"assembly","stealth":"discreet","form_factor":"pocket","summary":"A single-purpose dual-band wardriver: an ESP32-C5 dev board dropped into a host PCB that adds GPS, an 18650 with charging and fuel gauge, a microSD, a small display and three buttons. It logs 2.4 GHz Wi-Fi, 5 GHz Wi-Fi and BLE to WiGLE-format CSV and can upload straight to WiGLE and WDGWars from the device. It has no offensive features at all.","honest_take":"This is the honest one in the batch. It does exactly one job, it is MIT-licensed with the mechanical files published, the author wrote both the hardware and the firmware, and the 5 GHz is genuinely implemented rather than being a chip on a spec sheet. Two caveats: it is not a pentest tool - there is no deauth, no evil portal, no BLE spam, nothing offensive whatsoever - and $69 buys a host board, not a finished device, so budget for a C5 dev kit and an 18650 on top. It was also sold out at the vendor when checked.","released":"2026","aliases":["JCMK C5 Wardriver","ESP32 Dual Band Wardriver","JustCallMeKoko C5 Wardriver"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_wardriving":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","ble_scan":"yes","web_ui":"yes","standalone_untethered":"yes","wifi_deauth_24":"no","wifi_evil_twin":"no","subghz_rx":"no","scriptable":"no"},"legal":{"risk_level":"low","notes":"Passive collection only."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"cactus-whid","hardware_id":"cactus-whid","name":"Cactus WHID","firmware":"ESPloitV2","firmware_kind":"diy","vendor":"April Brother (manufacturer); design by Luca Bongiorni","category":"usb-hid","subcategory":"wireless-badusb","status":"available","price_usd":19.9,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Arrives working and pre-flashed: plug it in, join its Wi-Fi, open a browser, type a payload. Reflashing it requires the usual Arduino toolchain juggling for two chips.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"One of the original wireless BadUSB devices: an ATmega32u4 and an ESP8266 on a small board that plugs into a USB port, enumerates as a keyboard, and lets you write and fire payloads from a browser over its own Wi-Fi. It is small enough to be hidden inside another USB gadget, which was the design intent - the author's talks were about smuggling it inside innocuous-looking hardware.","honest_take":"The best value in this whole batch, with a maintenance asterisk. At $19.90 assembled it undercuts building your own, it does the same job as a $60 wireless BadUSB, and the design is open. But the repo is coasting: the last commit of any kind was a README edit in September 2023, and there are 35 open issues. Nothing is broken - HID injection is a stable target - but nobody is adding keyboard layouts or fixing the web GUI. Also understand the operational trade: like every wireless BadUSB, the thing that makes it convenient is an access point broadcasting from inside the target machine's USB port.","released":"2017","aliases":["WHID","WHID Injector","WiFi HID Injector","Cactus WHID Injector"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","hid_remote_trigger":"yes","usb_mass_storage":"no","usb_exfil":"partial","wifi_ap_mode":"yes","web_ui":"yes","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Owning it is legal."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"n/a - no tagged releases; firmware ships pre-installed","app_store":"No","abandoned_risk":"high"}},{"id":"flipper-canbus-electroniccats","hardware_id":"flipper-canbus-electroniccats","name":"CAN Bus for Flipper Zero (Electronic Cats)","firmware":"Flipper MCP2515 CANBUS app","firmware_kind":"community","vendor":"Electronic Cats","category":"automotive","subcategory":"flipper-canbus-addon","status":"available","price_usd":35.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Requires a Flipper Zero and basic CAN-bus/OBD-II knowledge to use meaningfully.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A GPIO add-on board that turns a Flipper Zero into a basic CAN 2.0B sniffer/injector using an MCP2515 SPI CAN controller, with an official app supporting packet sniffing (hex or normal display), SD-card logging of sniff sessions, and packet injection/replay including saved-and-modified packets. It also supports OBD2 scanning and UDS diagnostics per the vendor. The vendor explicitly states it is 'directly incompatible' with CAN-FD vehicles.","honest_take":"At $35 direct it's a cheap way to add CAN sniffing to a Flipper Zero you already own, but it is CAN 2.0B only via the MCP2515 - the vendor's own page warns it will not work on CAN-FD vehicles, an increasingly large share of the fleet since roughly 2020. If you need CAN-FD or isolation, this isn't it - look at panda ($99, CAN-FD on 3 buses) or CANable Pro (isolated) instead; this addon's value is convenience (reusing a Flipper you already have), not raw capability. Also worth knowing: three different resellers list this as three apparently different products at three different prices ($35 Electronic Cats direct / $55 Hacker Warehouse / ~$42 Lab401) - they are the same board, and one first-pass automated scan flagged the Lab401 listing as a possible duplicate of an unrelated nRF24L01+ Flipper module (a 2.4GHz radio addon) rather than of these other two CAN listings; that flag was a false positive on the wrong pair - the real duplication is among these three CAN resellers, which this record merges into one.","released":"2024","aliases":["Flipper Add-On: CANBus","CANBus Module for Flipper Zero"],"capabilities":{"packet_capture":"yes","scriptable":"no","web_ui":"no","app_store":"yes","sd_logging":"yes","standalone_untethered":"no","cloud_c2":"no","usb_mass_storage":"no","uart":"no","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","can_sniff":"yes","can_inject":"yes","can_fd":"no","can_isolated":"no","obd2":"claimed"},"legal":{"risk_level":"low","notes":"Owning and using a CAN interface for diagnostics/research on a vehicle you own or are authorized to test is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-01","app_store":"Yes - official Flipper app catalog","abandoned_risk":"low"}},{"id":"canable-pro","hardware_id":"canable-pro","name":"CANable Pro","firmware":"Stock slcan / candleLight","firmware_kind":"stock","vendor":"Protofusion Labs / Openlight Labs (Ethan Zonca)","category":"automotive","subcategory":"can-bus-interface","status":"available","price_usd":70.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"A bare CAN interface; expects SocketCAN/CAN-tooling familiarity.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An open-hardware, single-channel, galvanically isolated (5kV on the current 1.1 revision, 2.5kV on the original) USB-to-CAN adapter with a 3-pin screw terminal (CANH/CANL/GND), descended from the original CANtact design. It supports CAN 2.0 A/B up to 1 Mbit/s and works with slcan (via can-utils/slcand/Wireshark on Linux, or the cantact-app GUI on Windows/Mac), candleLight firmware for native SocketCAN, Cangaroo (with DBC file decoding), and the cross-platform canard Python library.","honest_take":"The critical thing to know before buying anything in this product line is that isolation and CAN-FD are currently mutually exclusive across the vendor's own catalog: the isolated CANable Pro/Pro 1.1 (this record) is CAN 2.0-only with no FD, while the cheaper, non-isolated CANable 2.0 sibling has beta CAN-FD support but zero isolation between your laptop's USB port and the vehicle bus. You cannot buy one board from this vendor with both today - pick the risk you'd rather manage (frying a USB port vs. being unable to talk to a CAN-FD-only bus) before ordering. Also worth knowing: the Tindie storefront that shows up first in a lot of searches for 'CANable Pro' has had a dormant 'seller on a break' banner since 2018; buy from openlightlabs.com instead.","released":"2022","aliases":["CANable 2.0","CANable Pro 1.1","CANable (original)"],"capabilities":{"packet_capture":"yes","scriptable":"yes","web_ui":"no","app_store":"no","standalone_untethered":"no","sd_logging":"no","cloud_c2":"no","usb_mass_storage":"no","uart":"no","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","can_sniff":"yes","can_inject":"yes","can_fd":"no","can_isolated":"yes","obd2":"unknown"},"legal":{"risk_level":"low","notes":"Owning and using a CAN interface for diagnostics/research on a vehicle you own or are authorized to test is legal."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2023-09","app_store":"No","abandoned_risk":"medium"}},{"id":"canpico-canhack","hardware_id":"canpico-canhack","name":"CANHack Toolkit / CANPico","firmware":"CANHack (MicroPython)","firmware_kind":"diy","vendor":"Canis Automotive Labs (Dr. Ken Tindell)","category":"automotive","subcategory":"can-bus-attack-toolkit","status":"discontinued","price_usd":45.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"This is a protocol data-link-layer attack toolkit (bus-off DoS, selective frame corruption via precise bit timing), not a beginner sniffing tool - it assumes real understanding of CAN's arbitration/error-handling mechanics.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A proof-of-concept library demonstrating that CAN's data-link layer can be attacked directly through precisely-timed bit-banging - no cryptographic break needed - to cause denial-of-service (bus-off attacks) or selective corruption of specific frames on a live CAN bus. It ran on CANPico, a carrier board pairing a Raspberry Pi Pico (RP2040) with Microchip's MCP2517FD CAN-FD controller and MCP2562FD CAN-FD transceiver on a screw terminal, with a MicroPython build also made for the DEF CON 30 Car Hacking Village badge.","honest_take":"The real contribution here is the technique, not the board: CANHack proves that CAN's total lack of frame authentication and its cooperative, deterministic error-handling can be turned into precision denial-of-service and selective-corruption primitives using only accurate timing, which is a genuinely important result for understanding why CAN alone is not a security boundary. The hardware it shipped on (CANPico) looks to be discontinued at its original retailer and the vendor's own product page is dead, but because the technique only needs an RP2040 plus an FD-capable MCP2517FD/MCP2562FD pair and runs in MicroPython, it is straightforward to rebuild on generic parts if you can't find an original board.","released":"2021","aliases":["CANHack","CANPico"],"capabilities":{"packet_capture":"yes","scriptable":"yes","standalone_untethered":"yes","usb_mass_storage":"yes","web_ui":"no","app_store":"no","sd_logging":"no","cloud_c2":"no","uart":"no","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","can_sniff":"yes","can_inject":"yes","can_fd":"yes","can_isolated":"unknown","obd2":"unknown"},"legal":{"risk_level":"medium","notes":"Unlike passive CAN sniffing, this toolkit implements active attacks (bus-off denial-of-service, selective frame corruption) against a live CAN network."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2024-04","app_store":"No","abandoned_risk":"high"}},{"id":"cantact-pro","hardware_id":"cantact-pro","name":"CANtact Pro","firmware":"Stock (Linklayer Labs)","firmware_kind":"stock","vendor":"Linklayer Labs","category":"automotive","subcategory":"can-bus-interface","status":"discontinued","price_usd":129.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Aimed at engineers doing real CAN/CAN-FD bus work, not a beginner tool.","build_effort":"assembled","stealth":"overt","form_factor":"box","summary":"An open-hardware, dual-channel, galvanically isolated USB-to-CAN interface: one channel is CAN/CAN-FD/single-wire-CAN, the other is CAN/CAN-FD, both behind isolation between the CAN side and USB/host side, over a high-speed (480 Mbit/s) USB link with dual DB9 connectors. It was the professional successor to Eric Evenchick's original single-channel, non-isolated CANtact, and directly benchmarked itself on its own Crowd Supply page against the isolated 2-channel ICS ValueCAN 4-2 ($445) and the non-isolated Tiny-CAN II-XL (~$180).","honest_take":"On paper this is exactly the 'isolation + CAN-FD + dual channel' combination that separates a lab-grade interface from a $15 hobby build, and its own comparison table against ValueCAN/Tiny-CAN backs that up - but you cannot actually buy one today. The Crowd Supply campaign is fully sold out and marked discontinued, so treat any listing you find elsewhere with suspicion; the currently-buyable open-hardware alternative with real isolation is CANable Pro from Openlight Labs, though that one drops CAN-FD to keep isolation, which CANtact Pro did not have to compromise on.","released":"2020","aliases":[],"capabilities":{"packet_capture":"yes","scriptable":"yes","web_ui":"no","app_store":"no","standalone_untethered":"no","sd_logging":"no","cloud_c2":"no","usb_mass_storage":"no","uart":"no","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","can_sniff":"yes","can_inject":"yes","can_fd":"yes","can_isolated":"yes","obd2":"unknown"},"legal":{"risk_level":"low","notes":"Owning and using a CAN interface for diagnostics/research on a vehicle or system you own or are authorized to test is legal."},"ecosystem":{"community":"dead","docs_quality":"good","last_release":"2023-03","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"cantact-v1-2-hackerwarehouse","hardware_id":"cantact-v1-2-hackerwarehouse","name":"CANtact v1.2","firmware":"Original CANtact firmware","firmware_kind":"stock","vendor":"Hacker Warehouse (fork of the original CANtact design)","category":"automotive","subcategory":"can-bus-interface","status":"available","price_usd":80.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"A raw single-channel CAN interface; expects familiarity with SocketCAN/CAN tooling.","build_effort":"assembled","stealth":"overt","form_factor":"box","summary":"A Hacker Warehouse repackaging of Eric Evenchick's original open-source CANtact USB-to-CAN interface, with two changes from the original design: a USB-C connector in place of USB-B, and an RJ45-to-OBD-II adapter (with an included Cat5 cable) in place of the original's direct wiring. Per the original CANtact's own published comparison table (used by its successor CANtact Pro to position itself), the base CANtact design is single-channel, has no CAN-FD support, and is not galvanically isolated.","honest_take":"This is the original entry-level CANtact with a couple of connector conveniences bolted on, sold at $80 - which is more expensive than the $60-70 isolated CANable Pro from Openlight Labs (a more direct descendant of the same open-source lineage) while offering strictly less: single channel, no isolation, no CAN-FD. Unless the RJ45-to-OBD-II adapter specifically is what you need, CANable Pro is the better buy for the same money or less.","aliases":["CANtact"],"capabilities":{"packet_capture":"yes","scriptable":"yes","web_ui":"no","app_store":"no","standalone_untethered":"no","sd_logging":"no","cloud_c2":"no","usb_mass_storage":"no","uart":"no","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","can_sniff":"yes","can_inject":"yes","can_fd":"no","can_isolated":"no","obd2":"partial"},"legal":{"risk_level":"low","notes":"Owning and using a CAN interface for diagnostics/research on a vehicle you own or are authorized to test is legal."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2021-11","app_store":"No","abandoned_risk":"high"}},{"id":"captaindma-75t","hardware_id":"captaindma-75t","name":"CaptainDMA 75T","firmware":"PCILeech-compatible","firmware_kind":"third-party-product","vendor":"CaptainDMA","category":"hardware-debug","subcategory":"dma-attack","status":"available","price_usd":160.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Same PCILeech workflow as any DMA card.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A cheap Artix-7 75T PCIe DMA card supported by the PCILeech project, offering roughly 200 MB/s memory access over USB 3.2 Gen 2. It is the mass-market alternative to LambdaConcept's boards, and the larger 75T FPGA leaves more room for custom gateware.","honest_take":"This product exists mainly because of game cheating - the vendor's community is a Discord, the resellers advertise 'ships flashed for BattlEye', and the bigger FPGA is popular because it fits device-ID spoofing logic. That does not make it a bad DMA card for legitimate memory forensics, but it does mean you are buying from a grey ecosystem with no security-vendor accountability, and firmware that ships pre-flashed by an unknown party. If provenance matters to your work, flash your own bitstream from the PCILeech repo before using it.","released":"2023","aliases":["Captain DMA","75T DMA card"],"capabilities":{"usb_exfil":"yes","scriptable":"yes","spi_flash_dump":"no","glitching":"no"},"legal":{"risk_level":"high","notes":"Unauthorised memory access is a computer-misuse offence."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026","app_store":"No","abandoned_risk":"medium"}},{"id":"catsniffer-v3","hardware_id":"catsniffer-v3","name":"CatSniffer V3","firmware":"Stock","firmware_kind":"stock","vendor":"Electronic Cats","category":"wardriving","subcategory":"iot-protocol-sniffer","status":"out-of-stock","price_usd":136.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Output is pcap into Wireshark - useful only if you can read 802.15.4/BLE frames.","build_effort":"flash-only","stealth":"discreet","form_factor":"usb-stick","summary":"A USB dongle carrying a TI CC1352P7 (sub-GHz plus 2.4 GHz 802.15.4/BLE), an RP2040 as USB bridge and an SX1262 LoRa modem, so one stick sniffs Zigbee, Thread, Matter, BLE, Wi-SUN, 6LoWPAN and LoRa into Wireshark. It fills the gap left by discontinued Zigbee sniffers like the CC2531 and ApiMote.","honest_take":"It is a sniffer first. It is not a Zigbee attack toolkit out of the box, it does not touch Wi-Fi at all, and the LoRa side is a plain SX1262 - no magic decryption of LoRaWAN payloads you do not have keys for. Availability has been patchy; it has been out of stock at the vendor repeatedly.","released":"2023","aliases":["Cat Sniffer","CatSniffer v3.2"],"capabilities":{"zigbee":"yes","ble_sniff":"yes","ble_scan":"yes","subghz_rx":"yes","subghz_tx":"partial","packet_capture":"yes","wifi_scan_24":"no"},"legal":{"risk_level":"low","notes":"Passive capture of unencrypted IoT traffic in your own lab is low risk; intercepting other people's traffic is regulated in most countries."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No","abandoned_risk":"low"}},{"id":"cc1101-module-generic-2pack","hardware_id":"cc1101-module-generic-2pack","name":"CC1101 Sub-GHz Transceiver Module (2-Pack, generic)","firmware_kind":"n/a","vendor":"Generic/unbranded (commonly resold on AliExpress and Amazon under various storefront names)","category":"accessory","subcategory":"cc1101-breakout","status":"available","price_usd":17.99,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Bare radio breakout with no onboard processor - you must wire it to your own microcontroller over SPI and write or reuse firmware (e.g. an Arduino CC1101 library, rfcat-alike code) to do anything with it.","build_effort":"soldering","stealth":"discreet","form_factor":"board","summary":"A generic, unbranded breakout board for the TI CC1101 sub-1 GHz transceiver IC with an SMA antenna connector, tunable across 300-348/387-464/779-928 MHz - the same radio chip used inside the Flipper Zero, YARD Stick One, Daeva and many other sub-GHz tools, sold bare with no host processor or firmware of its own.","honest_take":"This is the raw silicon everyone else's sub-GHz tool in this batch (Flipper Zero, Daeva, RFQuack, the Electronic Cats add-on) is ultimately built around - buying it directly is the cheapest possible way into CC1101 experimentation, but you are entirely on your own for the microcontroller, wiring, firmware and case that turn it into an actual tool. Per the TI datasheet the chip supports up to roughly +10 to +12 dBm output and -110 to -116 dBm sensitivity depending on band and data rate; generic listings rarely specify which PCB layout/antenna matching they used, so real-world range and sensitivity on a $9-per-unit clone board can vary noticeably between sellers even though the chip itself is identical. Like every other CC1101-based device in this batch, it has zero rolling-code capability built in - that would have to come from whatever firmware you write.","aliases":["CC1101 Wireless Module with SMA Antenna"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"addon","subghz_rolling_code":"no","subghz_bruteforce":"addon","subghz_external_antenna":"yes","subghz_amplified":"no","standalone_untethered":"no","scriptable":"addon","sd_logging":"no","gps":"no","app_store":"no"},"legal":{"risk_level":"high","notes":"Same as any bare sub-GHz transceiver: receiving is broadly legal, but transmitting outside license-exempt ISM allocations without authorization is a criminal offense in most countries, and replaying a captured signal to actuate a gate, garage, alarm or vehicle you do not own is typically a separate offense again."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"cc1101-tool-arduino","hardware_id":"cc1101-tool","name":"cc1101-tool","firmware":"cc1101-tool","firmware_kind":"diy","vendor":"mcore1976 (independent developer)","category":"subghz","subcategory":"diy-transceiver","status":"diy-only","price_usd":12.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"No PCB - you wire a CC1101 breakout to a Pro Micro (or ESP32/ESP8266/Nano/Pro Mini/RP2040) by hand following the repo's pinout photos, then flash the sketch and talk to it over a serial terminal. Nothing about the RF side is beginner-friendly; commands are typed, not menued.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"An open-source Arduino sketch that drives a bare CC1101 breakout from a plain serial terminal - no Flipper, no SDR software, no proprietary app. It supports Pro Micro, Nano, Pro Mini, ESP32, ESP8266 and RP2040 as the host MCU, and the author positions it explicitly as a budget alternative to the YARD Stick One.","honest_take":"This is genuinely a YARD Stick One competitor for people willing to build it themselves, and at $12 in parts versus roughly $200 for a YARD Stick One it is a real budget option - but you are trading a calibrated, driverless, GNU Radio-integrated tool for a hand-wired breakout and a text CLI with no official support channel beyond GitHub issues. It does the same fundamental things a Flipper Zero's sub-GHz app does (RX, TX, raw record/replay, jamming) using the identical CC1101 silicon, so if you already own a Flipper this buys you nothing except a dedicated headless box. The 'brute force' feature is fixed-code DIP-switch garage doors only - it does nothing against rolling codes, and the project makes no such claim.","aliases":["cc1101-tool"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"partial","subghz_rolling_code":"no","subghz_external_antenna":"claimed","subghz_amplified":"no","scriptable":"yes","standalone_untethered":"no","usb_mass_storage":"no","app_store":"no"},"legal":{"risk_level":"medium","notes":"Building and owning the hardware is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025-12 (no tagged GitHub releases; commit history is the changelog)","app_store":"No","abandoned_risk":"low"}},{"id":"ch552-daplink","hardware_id":"ch552-daplink","name":"CH552-DAPLink","firmware":"wagiminator CH552-DAPLink","firmware_kind":"diy","vendor":"wagiminator","category":"hardware-debug","subcategory":"jtag-swd-probe-diy","status":"diy-only","price_usd":5.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You are ordering a PCB, hand-soldering an 8051-family chip and passives, and compiling firmware with the SDCC toolchain yourself - this is a build project, not a purchase.","build_effort":"soldering","stealth":"discreet","form_factor":"board","summary":"A DIY, from-scratch CMSIS-DAP debug probe built around the CH552, an 8-bit 8051-core microcontroller from WCH (Nanjing Qinheng) that costs under $1 in single quantities. It implements SWD and JTAG plus a virtual COM port, making it one of the cheapest possible ways to get a working ARM Cortex debug probe if you're willing to solder and compile it yourself.","honest_take":"The headline appeal is the sub-$1 chip, but the CH552's 8051 core is doing everything - CMSIS-DAP framing, SWD/JTAG bit-banging and the USB stack - on an architecture with none of the bit-banging throughput of an ARM Cortex-M0+ (like the RP2040 in a Mini DAPLink) or the LPC11U35 in an IBDAP. Expect it to be the slowest probe in this comparison, not the cheapest-per-performance one; nobody publishes a benchmark number for it, which is itself telling. It also has no I2C, SPI flash-dumping or glitching capability - it is SWD/JTAG plus UART, nothing more. It is a genuinely good learning project - real open firmware you compile yourself, on real Cortex-M silicon - but not a build you'd choose over a $4.80 pre-assembled Mini DAPLink if raw debugging speed or your own time matters.","released":"2021","aliases":[],"capabilities":{"jtag_swd":"yes","uart":"yes","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","glitching":"no","scriptable":"unknown","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"DIY bench debug probe with no radio - legal to build and use everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2025-06","app_store":"No","abandoned_risk":"low"}},{"id":"chameleon-lite","hardware_id":"chameleon-lite","name":"Chameleon Lite","firmware":"ChameleonUltra (official)","firmware_kind":"stock","vendor":"RFID Research Group (ProxGrind)","category":"rfid-nfc","subcategory":"card-emulator","status":"available","price_usd":77.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same MTools app and slot-based workflow as the Chameleon Ultra; the only added skill is knowing in advance that you cannot read/write a card with this unit, only emulate one you already have a dump for.","build_effort":"assembled","stealth":"discreet","form_factor":"keychain","summary":"The cut-down, emulation-only member of the Chameleon Ultra family: same nRF52840-class firmware and 8 HF + 8 LF slot structure, but with the MFRC522 reader chip removed entirely and the larger LiPo swapped for a coin cell. It is not a smaller Chameleon Ultra with reduced range - it physically cannot read or write any card, HF or LF; it can only emulate cards whose data you already have (captured elsewhere, e.g. with a Proxmark3 or the Ultra).","honest_take":"This is NOT simply a budget Chameleon Ultra, and the first-pass 'possible duplicate of Chameleon Ultra' flag is wrong in the way that matters most: the Ultra can independently capture a card via its onboard MFRC522, while the Lite cannot read or write anything at all, on either HF or LF - it is a pure playback device for dumps sourced elsewhere. If you already own a Proxmark3 or a Chameleon Ultra to do the capturing, the Lite is a genuinely reasonable $69 keychain emulator to carry the resulting dumps around without risking your primary tool. If it is your only RFID device, it is close to useless on its own - you have no way to get a card's data onto it in the first place beyond typing a known UID/key by hand.","aliases":["Chameleon Lite RRG"],"capabilities":{"hf_1356_emulate":"yes","hf_1356_read":"no","hf_1356_write":"no","lf_125khz_emulate":"yes","lf_125khz_read":"no","lf_125khz_write":"no","mifare_classic_attacks":"no","mifare_desfire":"no","iso15693":"no","felica":"no","nfc_relay":"no","standalone_untethered":"yes","scriptable":"partial"},"legal":{"risk_level":"medium","notes":"Owning a card emulator is legal in most countries."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":null,"app_store":"No - shares the Chameleon Ultra's official CLI, MTools apps and community JS library","abandoned_risk":"low"}},{"id":"chameleon-tiny","hardware_id":"chameleon-tiny","name":"Chameleon Tiny / Tiny Pro","firmware":"Custom","firmware_kind":"third-party-product","vendor":"RFID Research Group (ProxGrind)","category":"rfid-nfc","subcategory":"card-emulator","status":"discontinued","price_is_estimate":false,"skill_level":"intermediate","skill_note":"Was the easiest Chameleon to operate thanks to the mobile apps. Moot now.","build_effort":"assembled","stealth":"discreet","form_factor":"keychain","summary":"ProxGrind's shrunk, keychain-sized reworking of the ChameleonMini RevG: same 8-bit AVR firmware lineage, smaller board, USB-C, mobile apps, and on the Tiny Pro a Bluetooth link. It was the direct predecessor to the Chameleon Ultra and has been comprehensively superseded by it.","honest_take":"Do not buy this in 2026. The Chameleon Ultra replaced it on every axis that matters - a Cortex-M4F instead of an 8-bit AVR, a real reader front end (MFRC522) so it can capture cards as well as replay them, LF 125 kHz support the Tiny never had, and firmware that is still shipping releases while the Tiny's fork went quiet in June 2023. The Ultra costs about US$130, which is roughly what a Tiny cost. The only reason to own one now is that you already do. Separately, be careful where you shop for ProxGrind hardware: on 2026-09-06 sneaktechnology.com presented a TLS certificate for an unrelated hostname and proxgrind.com was serving injected SEO spam links, so go through Lab401, KSEC or Hacker Warehouse.","released":"2020","aliases":["ChameleonTiny","Chameleon Tiny Pro","ProxGrind Chameleon Tiny"],"capabilities":{"lf_125khz_read":"no","hf_1356_read":"partial","hf_1356_emulate":"yes","hf_1356_write":"partial","mifare_classic_attacks":"partial","mifare_desfire":"partial","iso15693":"yes","emv_read":"no","standalone_untethered":"yes","scriptable":"partial"},"legal":{"risk_level":"medium","notes":"Same as any card emulator: legal to own in most countries, illegal to use against credentials you are not authorised to use."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2023-06","app_store":"No - RRG mobile apps only","abandoned_risk":"already-abandoned"}},{"id":"chameleon-ultra","hardware_id":"chameleon-ultra","name":"Chameleon Ultra","firmware":"ChameleonUltra (official)","firmware_kind":"stock","vendor":"RFID Research Group (ProxGrind)","category":"rfid-nfc","subcategory":"card-emulator","status":"available","price_usd":130.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The mobile app makes basic clone-and-emulate genuinely easy, but interpreting what a failed emulation means still requires knowing which card technology you are up against.","build_effort":"assembled","stealth":"discreet","form_factor":"keychain","summary":"A keychain-sized dual-frequency card emulator: 8 LF slots and 8 HF slots, switched with two buttons, running about six months on a 90mAh cell. HF emulation runs on the nRF52840's on-die NFC-A tag peripheral, which draws around 5mA and does not need the CPU awake - this is why it behaves like a real card rather than like a microcontroller pretending to be one. A separate MFRC522 gives it reader capability so it can capture a card as well as replay it.","honest_take":"Two hard limits get papered over in the marketing. First, the reader front end is an MFRC522, which is ISO14443A-only silicon: no ISO15693, no ISO14443B, no FeliCa, ever, at any firmware version. That rules out iCODE, most library and ski-pass tags, and the HF layer iCLASS rides on. Second, seeing 'DESFire EV1 & EV2' and 'MIFARE Plus' in the supported-tag list means it can hold a conversation in those protocols at 106 kbit/s - not that it can clone one. Without the site's AES keys a real DESFire reader will reject the emulation instantly, and the firmware's own whitepaper flags DESFire as low-bit-rate only. Where it genuinely beats a Flipper Zero is emulation fidelity: full control of UID, SAK, ATQA and ATS, and a detection mode that logs reader nonces for MFKEY32 recovery while sitting in the field.","released":"2023","aliases":["ChameleonUltra","Chameleon Ultra ProxGrind","CU"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"yes","hf_1356_read":"partial","hf_1356_write":"partial","hf_1356_emulate":"yes","mifare_classic_attacks":"yes","mifare_desfire":"partial","nfc_type4_ndef":"partial","emv_read":"no","iso15693":"no","felica":"no","nfc_relay":"no","standalone_untethered":"yes","scriptable":"partial"},"legal":{"risk_level":"medium","notes":"Owning a card emulator is legal in most countries."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-07","app_store":"No - official CLI, MTools iOS/Android apps and a community JS library","abandoned_risk":"low"}},{"id":"chameleon-mini-revg","hardware_id":"chameleon-mini-revg","name":"ChameleonMini RevG","firmware":"emsec ChameleonMini (official)","firmware_kind":"stock","vendor":"Kasper & Oswald GmbH","category":"rfid-nfc","subcategory":"card-emulator","status":"available","price_usd":174.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Driven by a serial AT-style command set. Straightforward to operate; understanding what the emulation is or is not fooling is the hard part.","build_effort":"assembled","stealth":"discreet","form_factor":"keychain","summary":"The original credit-card-form-factor NFC emulator from the academic group at Ruhr University Bochum, productised by Kasper & Oswald after a 1,700-backer Kickstarter. An ATxmega128A4U clocked at 27.12 MHz - exactly twice 13.56 MHz - driving a single HF antenna, with 8 slots of card configurations. It emulates, it sniffs, and it barely reads.","honest_take":"It is 13.56 MHz only. The project's own support table lists 'any non-13.56 MHz tag' as NO at the hardware, software and application layers, so there is no LF 125 kHz path at all - no HID Prox, no EM4100. That single fact makes it the wrong tool for most physical access work, where LF is still enormously common. Reader mode is also far weaker than people expect: there is still no implemented command to read a MIFARE Classic or a DESFire, only 'dump_mfu' for Ultralight, even though the crypto primitives are sitting in the firmware. What it uniquely does, and the Chameleon Ultra cannot, is emulate and sniff ISO15693. Its DESFire emulation is also the most serious in this batch - real AES ciphers, app and key creation, encrypted file operations - but note that this is emulating a DESFire whose keys you supply, not breaking anyone's. EV2/EV3-specific functionality is explicitly absent. Development has been quiet since August 2023.","released":"2016","aliases":["Chameleon Mini","ChameleonMini RevG","Chameleon RevG"],"capabilities":{"lf_125khz_read":"no","lf_125khz_emulate":"no","hf_1356_read":"partial","hf_1356_write":"partial","hf_1356_emulate":"yes","mifare_classic_attacks":"partial","mifare_desfire":"partial","nfc_type4_ndef":"partial","iso15693":"yes","felica":"no","emv_read":"no","standalone_untethered":"yes","scriptable":"partial"},"legal":{"risk_level":"medium","notes":"A card emulator in a credit-card form factor."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2023-08","app_store":"No","abandoned_risk":"medium"}},{"id":"chimerable-esp32","hardware_id":"generic-esp32-chimerable","name":"ChimeraBLE","firmware":"ChimeraBLE","firmware_kind":"community","vendor":"Matthew KuKanich (open source project)","category":"bluetooth","subcategory":"ble-recon-mitm-firmware","status":"diy-only","price_usd":8.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Serial CLI operation on the generic-ESP32/XIAO targets assumes comfort with BLE/GATT concepts; the Cardputer build adds a menu UI but the underlying operations (cloning, MITM) still require understanding what you're doing.","build_effort":"flash-only","stealth":"discreet","form_factor":"board","summary":"Open-source BLE security and reverse-engineering firmware for ESP32 that can act as a scanning/enumerating central, a cloned/emulated peripheral, or both simultaneously as a man-in-the-middle proxy. It does full GATT service/characteristic/descriptor enumeration with SIG UUID resolution, decodes HID report maps to show live keystrokes from a connected keyboard, clones a device's GATT tree with MAC spoofing, and includes RSSI-based direction finding ('fox-hunting').","honest_take":"The 'MITM' capability here is impersonation-based, not over-the-air interception: ChimeraBLE connects to the real device as a central and simultaneously advertises a cloned peripheral to the victim host, proxying traffic between the two active connections it holds. That is a real and useful attack, but it is not the same thing as passively following an existing BLE connection's frequency-hopping pattern the way a dedicated sniffer (Ubertooth, Sniffle-class nRF52 dongle) does - ChimeraBLE cannot eavesdrop on a connection it isn't a party to. Cloned characteristics also run without encryption and can't replicate bonding-protected access, so a device relying on BLE bonding for security will not be fully fooled by the clone. It's a genuinely capable, actively developed multi-role tool for the price of a $5-10 board - just don't expect passive network-level sniffing.","released":"2026","aliases":["Chimera BLE"],"capabilities":{"ble_scan":"yes","ble_sniff":"no","ble_advertise":"yes","ble_hid":"yes","ble_tracker_detect":"partial","ble_jam":"no","bt_classic":"no","ble_spam_apple":"no","findmy_track":"no","scriptable":"yes","standalone_untethered":"partial","usb_hid_inject":"no"},"legal":{"risk_level":"high","notes":"Connecting to, cloning or proxying a BLE device you don't own or lack authorization to test is unauthorized access to a computer system in most jurisdictions."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"No","abandoned_risk":"medium"}},{"id":"chipjabber-unplugged","hardware_id":"chipjabber-unplugged","name":"ChipJabber Unplugged","firmware_kind":"n/a","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"side-channel-glitching","status":"vaporware","price_is_estimate":false,"skill_level":"intermediate","skill_note":"NewAE pitches it explicitly as 'designed more for fun than real-life usage' and as a hands-on way to learn what voltage fault injection actually is - you turn physical potentiometers and watch a boot process fail or succeed, no software required for the glitcher itself. The included NOTDuino target does need basic Arduino IDE familiarity to reprogram.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"A deliberately simple, no-programmable-logic voltage fault-injection tool from NewAE (the ChipWhisperer/ChipSHOUTER company) meant to teach the mechanics of glitching by hand: it drops a target's core voltage momentarily at a manually-timed instant during boot, using discrete analog circuitry and physical potentiometers instead of software. It pairs with NewAE's 'NOTDuino' demo board, which uses an EEPROM as a naive boot-time 'key' check, so you can watch the glitch actually defeat it. NewAE's own pitch is explicit that for real work you want ChipWhisperer or ChipSHOUTER instead - this exists to teach the concept, not to do the job professionally.","honest_take":"Judge this by what it actually is, not what it might become: it has read 'Coming Soon' on Crowd Supply since before 2020, the GitHub repo's last commit is from September 2020, and NewAE's own page still says 'this project is launching soon' with zero updates posted in six years. That is not a slow-burn crowdfunding campaign, that is an abandoned commercial launch for a design that otherwise works fine - the open schematics and NOTDuino demo are real and documented, and NewAE's own campaign page tells you plainly to buy ChipWhisperer or ChipSHOUTER-PicoEMP instead once you outgrow it. If you want to actually own one, your only route right now is building it yourself from the public GitHub schematics - there was never a functioning 'buy it' path, so DIY was effectively always the only real option despite being marketed as three purchasable variants.","aliases":["ChipJabber-Unplugged Kit","ChipJabber Unplugged Mini","ChipJabber Unplugged Old-School PCB"],"capabilities":{"glitching":"yes","standalone_untethered":"yes","scriptable":"no","uart":"addon","jtag_swd":"no","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A simple bench glitching tool with no radio; legal to own and build everywhere."},"ecosystem":{"community":"dead","docs_quality":"sparse","last_release":"2020","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"chipshouter","hardware_id":"chipshouter","name":"ChipSHOUTER","firmware":"Stock (NewAE)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"fault-injection","status":"out-of-stock","price_usd":4605.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"EMFI is a search problem: position, timing, voltage and pulse width all have to be swept.","build_effort":"assembled","stealth":"overt","form_factor":"desktop","summary":"The reference commercial electromagnetic fault injection tool: 150-500 V charge voltage driving an injection probe that induces faults in a running chip without any electrical contact, which makes it effective against packages and boards where you cannot reach the power rail. Ships with four probe tips of different sizes and polarities.","honest_take":"The price is the story. At USD 4,605 this is lab equipment for people who bill for silicon security assessments; hobbyists use the PicoEMP or Faulty Cat, which are the same physics at a tenth of the repeatability and a fiftieth of the price. EMFI is also not a magic unlock button - you are searching a large parameter space for a fault that happens to land somewhere useful, and plenty of targets never yield. It has also been persistently out of stock.","released":"2018","aliases":["Chip Shouter","EMFI tool"],"capabilities":{"glitching":"yes","jtag_swd":"no","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Lab equipment, legal to own."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"chipshouter-picoemp","hardware_id":"picoemp","name":"ChipSHOUTER-PicoEMP","firmware":"PicoEMP (open source)","firmware_kind":"diy","vendor":"NewAE Technology (kit) / open hardware","category":"hardware-debug","subcategory":"fault-injection","status":"available","price_usd":100.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"You assemble it, and then you are working with roughly 250 V - the safety shield is not optional.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"Colin O'Flynn's open-source electromagnetic fault injector: a Raspberry Pi Pico plus a transformer stage generating around 250 V into an SMA-connected injection probe. It is the accessible entry point to EMFI, explicitly designed for self-study rather than as a cheap ChipSHOUTER.","honest_take":"It is deliberately worse than the commercial tool and says so: about 1-4 seconds recovery between glitches versus a ChipSHOUTER's rapid fire, uncalibrated feedback so pulse energy is only approximate, and no interlocks beyond the plastic shield. That makes campaigns slow and results harder to reproduce. It is also a genuine shock hazard if you run it without the shield fitted. Excellent for learning EMFI and for one-off attacks; not for production assessment work.","released":"2021","aliases":["PicoEMP","Pico EMP"],"capabilities":{"glitching":"yes","scriptable":"yes","jtag_swd":"no"},"legal":{"risk_level":"medium","notes":"Open hardware, legal to build and own."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"chipshover","hardware_id":"chipshover","name":"ChipSHOVER","firmware":"Stock (NewAE, open source)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"positioning-stage","status":"available","price_usd":10000.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"A precision robotics platform for automated EM fault-injection mapping across a die surface - assumes you already understand fault injection and side-channel methodology; the ChipSHOVER only automates the physical positioning.","build_effort":"assembled","stealth":"overt","form_factor":"desktop","summary":"A motorized 3-axis XYZ positioning stage from NewAE built to automate scanning an EM fault-injection probe or side-channel sensor across a chip's surface - something normally done by hand with a manual micromanipulator. The commercial PS1 kit uses a medium-resolution stage (156.25nm step size, ~3um backlash/repeatability) with NewAE's own ChipShover-One controller board; the open-source ChipShover GitHub repo also documents a cheaper, lower-precision DIY variant (781.25nm step, 50-100um backlash) built around a widely-available ~$500 CNC frame and an open ~$180 Archim2 controller, which NewAE deliberately doesn't sell as a finished product. It includes a direct mounting adapter for NewAE's own ChipSHOUTER EM fault-injection tool, and is controlled either from its onboard LCD or scripted over USB via Python.","honest_take":"Despite the name similarity to the ChipSHOUTER, this is a completely different product - the ChipSHOUTER is the EM pulse generator itself, the ChipSHOVER is the robot arm that moves it (or any other probe) around a chip automatically. It does not inject faults or do side-channel capture on its own; you still need a ChipSHOUTER, an EM probe, or other sensing hardware to actually do the work, this just automates the tedious manual XY-scanning that fault-injection research otherwise requires. The bigger finding: NewAE open-sourced the whole design, including a DIY low-resolution build path (a common CNC frame plus an ~$180 open controller, roughly $680 all-in) that they explicitly chose not to productize because the precision is ~5x worse (781nm vs 156nm steps) and backlash is far higher (50-100um vs 3um). If your fault-injection work can tolerate that lower precision, building the DIY variant from NewAE's own open repo saves roughly $9,300 over the $10k PS1 kit - a genuinely rare case of a vendor publishing the cheap path around their own flagship product.","released":"2024","aliases":[],"capabilities":{"glitching":"addon","scriptable":"yes","jtag_swd":"no","uart":"no","i2c":"no","spi_flash_dump":"no","logic_analyzer":"no","standalone_untethered":"yes","web_ui":"no","sd_logging":"no","side_channel_power":"addon"},"legal":{"risk_level":"low","notes":"A precision robotics/lab-automation tool with no radio transmitter and no inherent attack capability of its own - it positions probes, it doesn't generate faults or capture data by itself."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"chipwhisperer-huskyplus","hardware_id":"chipwhisperer-huskyplus","name":"ChipWhisperer HuskyPlus","firmware":"Stock (NewAE, open source)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"side-channel-capture","status":"available","price_usd":1100.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"Same side-channel power-analysis and fault-injection workflow as the standard ChipWhisperer-Husky - this is professional/academic embedded-security tooling, not a beginner board.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An upgraded variant of NewAE's ChipWhisperer-Husky side-channel power-analysis and fault-injection capture board. Confirmed via NewAE's own documentation, the differentiator over the standard Husky is a faster ADC (250MS/s vs. 200MS/s, both 12-bit) and a roughly 2.5x larger sample buffer (327,828 samples vs. 131,124). It keeps the Husky's synchronous capture architecture, FPGA-based clock/voltage glitch generation (up to 32 programmable glitches), six trigger methods including SAD pattern matching, and >20MS/s streaming capture for attacking asymmetric-key algorithms.","honest_take":"The Plus is a genuine, distinct SKU rather than a rename or a dupe of the existing ChipWhisperer-Husky - the differentiators (250MS/s vs. 200MS/s ADC, 327,828 vs. 131,124 sample buffer) are both confirmed directly against NewAE's own documentation. But the extra headroom is a marginal win for most side-channel work, not a step change; if your target and traces are well-served by 200MS/s and ~131k samples (which covers most microcontroller-class DPA/CPA work), the plain Husky at roughly half the premium price does the same job. Pay the HuskyPlus premium specifically when you need the extra sample rate or the longer capture window for higher-frequency or higher-bandwidth targets, not by default.","released":"2025","aliases":["ChipWhisperer-HuskyPlus","NAE-CWHUSKYPLUS"],"capabilities":{"glitching":"yes","jtag_swd":"yes","logic_analyzer":"yes","scriptable":"yes","uart":"addon","spi_flash_dump":"no","i2c":"no","standalone_untethered":"no","web_ui":"no","app_store":"no","sd_logging":"no","sdr_rx":"no","side_channel_power":"yes"},"legal":{"risk_level":"low","notes":"A side-channel research/capture tool with no radio transmitter - legal to own and use on hardware you own or are authorized to test essentially everywhere."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"chipwhisperer-husky","hardware_id":"chipwhisperer-husky","name":"ChipWhisperer-Husky","firmware":"Stock (NewAE)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"side-channel-glitching","status":"available","price_usd":550.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"This is research-grade equipment. Its advanced features - SAD triggering, Arm Trace, 32-glitch sequences - only make sense once you already know why you need them.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"NewAE's current flagship compact capture board: a 12-bit 200 MS/s ADC with a 131,124-sample buffer, an Artix-7 A35 FPGA, voltage and clock glitching, six trigger modules including sum-of-absolute-differences pattern matching and ARM CoreSight trace, and the ability to fire up to 32 independently-timed glitches per trigger event.","honest_take":"This is where ChipWhisperer stops being courseware and becomes a real instrument, and the price and learning curve reflect that. Two features genuinely change what is possible: the SAD trigger matches on the shape of the power trace itself, so you can trigger on a specific operation inside a target rather than on an external signal; and the internal 600-1200 MHz VCO makes clock-glitch resolution independent of how slow the target clock is. Neither of those is something you will use in your first month. Be honest with yourself about whether you need them - most people asking 'should I get into side-channel' should spend $50 on a Nano first and come back here in a year.","released":"2022","aliases":["CW-Husky","CWHUSKY","ChipWhisperer Husky Plus"],"capabilities":{"glitching":"yes","logic_analyzer":"no","uart":"partial","jtag_swd":"partial","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"Laboratory equipment with no radio, legal to own and use."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"chipwhisperer-lite","hardware_id":"chipwhisperer-lite","name":"ChipWhisperer-Lite (CW1173)","firmware":"Stock (NewAE)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"side-channel-glitching","status":"out-of-stock","price_usd":290.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"Real side-channel work on targets you choose yourself means understanding trace alignment, filtering, leakage models and statistics - the hardware is the easy part.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The long-standing mid-tier ChipWhisperer: a 10-bit 105 MS/s capture path with both voltage and clock glitching, a 5-200 MHz synchronous clock generator, and a ~24,500 sample buffer. It is the board most published side-channel research and training material was developed on.","honest_take":"The step up from the Nano is real and it is mostly about clock glitching and synchronous sampling - the Lite can clock the target and sample in lockstep with it, which removes an enormous amount of trace-alignment pain. The honest caveat is that NewAE has clearly moved on: the Husky supersedes it with a 12-bit 200 MS/s ADC, a five-times-larger buffer and far better triggering, and the Lite is out of stock at resellers. If you can find one cheap second-hand it is still a capable tool with a decade of documentation behind it; buying new, look at the Husky.","released":"2015","aliases":["CW-Lite","CW1173","NAE-CWL"],"capabilities":{"glitching":"yes","logic_analyzer":"no","uart":"partial","jtag_swd":"no","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"Laboratory equipment with no radio, legal to own and use."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"chipwhisperer-nano","hardware_id":"chipwhisperer-nano","name":"ChipWhisperer-Nano","firmware":"Stock (NewAE)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"side-channel-glitching","status":"available","price_usd":50.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"The included Jupyter notebooks hold your hand well, but you are learning differential power analysis and fault injection - the concepts are genuinely hard regardless of the tool.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The teaching entry point to NewAE's side-channel and fault-injection line: an 8-bit 20 MS/s capture path and a voltage-glitching output on one board, with an STM32F030 target and its programmer built in. It exists so you can run the ChipWhisperer course without wiring anything.","honest_take":"Be clear-eyed that this is courseware hardware, and NewAE's own documentation lists the limits plainly: 8-bit at 20 MS/s, a fixed 10 dB analogue gain you cannot change, no clock glitching at all, no ability to multiply or divide the sampling clock, roughly 200 ns of jitter on glitch offset, rising-edge triggering only, and full-speed rather than high-speed USB. Those constraints mean it will teach you AES power analysis on its own bundled target and will struggle on a real-world target you bring yourself. That is a fine $50 - the notebooks are excellent and the concepts transfer - but do not buy it expecting to attack a product with it.","released":"2018","aliases":["CW-Nano","CWNANO","NAE-CWNANO"],"capabilities":{"glitching":"partial","logic_analyzer":"no","uart":"partial","jtag_swd":"no","spi_flash_dump":"no","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A laboratory instrument with no radio, legal to own and use everywhere."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025","app_store":"No - but the Jupyter notebook course is effectively the product","abandoned_risk":"low"}},{"id":"chipwhisperer-pro","hardware_id":"chipwhisperer-pro","name":"ChipWhisperer-Pro (CW1200)","firmware":"Stock (NewAE)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"side-channel-glitching","status":"discontinued","price_is_estimate":false,"skill_level":"expert","skill_note":"Same underlying discipline as the Lite/Nano/Husky - differential power analysis and fault injection - plus a more complex trigger/streaming setup that assumes you already know why you want SAD triggering or SPI/UART-pattern triggers.","build_effort":"assembled","stealth":"overt","form_factor":"box","summary":"The former top tier of NewAE's ChipWhisperer capture-hardware line: a 10-bit, 105 MS/s ADC with a 98,119-sample buffer, streaming capture up to 10 MS/s, a 5-200 MHz synchronous clock generator, four trigger module types (basic edge/level, analog SAD, SPI decode and UART decode), and both crowbar voltage glitching and clock glitching. It used the same FPGA-based architecture and 20-pin target connector as the ChipWhisperer-Lite, just with far more FPGA resources behind it, plus an onboard touchscreen the Lite and Husky don't have.","honest_take":"NewAE's own current documentation states plainly that the CW1200 is discontinued and tells buyers to get a ChipWhisperer-Husky instead - and the Husky beats it outright on paper (12-bit/200 MS/s vs 10-bit/105 MS/s, a bigger buffer, and a newer VCO-based clock-glitch design), presumably at a fraction of the Pro's original price. This is a genuinely different product from the ChipWhisperer-Nano despite the naming similarity people sometimes assume: the Nano was always the ~$50 fixed-function education board with an 8-bit/20 MS/s ADC and no clock glitching at all, while the Pro was NewAE's flagship lab instrument aimed at labs already committed to the platform - different market tier, different silicon, not a rebrand or a variant of the same board. If you already own one, it is still a genuinely capable 10-bit/105 MS/s instrument with trigger modules the Lite lacks (SAD, SPI/UART decode) - it just is not the thing to go buy today, and a used unit carries the usual risk of an FPGA design nobody at NewAE is actively patching anymore.","released":"2016","aliases":["CW-Pro","CW1200","NAE-CW1200-KIT","ChipWhisperer Pro Level 3 Starter Kit"],"capabilities":{"glitching":"yes","logic_analyzer":"no","uart":"partial","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","scriptable":"yes","standalone_untethered":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A laboratory instrument with no radio; legal to own and use everywhere."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"cinder-ferret","hardware_id":"cinder-ferret","name":"Cinder Ferret","firmware":"HaleHound-CYD","firmware_kind":"n/a","vendor":"HaleHound","category":"accessory","subcategory":"cyd-radio-companion-board","status":"available","price_usd":30.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-play into a pre-existing HaleHound CYD build via wiring harness; the skill barrier is really in building/flashing the CYD host, not this board.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A pre-soldered companion radio board for the HaleHound project that plugs into an ESP32 'Cheap Yellow Display' (CYD) build, combining a CC1101 sub-GHz transceiver and an NRF24L01 2.4GHz radio with wiring harnesses included. It exists purely to save builders from hand-wiring loose CC1101/NRF24 modules to the CYD's SPI bus.","honest_take":"This is a CC1101 and an NRF24L01 - parts that cost under $5-8 combined on AliExpress - pre-soldered to a breakout with the correct HaleHound pinout and JST harnesses. The $30 buys assembly and pin-mapping correctness, not unique hardware; if you're comfortable soldering and reading a pinout diagram, you can build the equivalent for a fraction of the price. Its value is entirely in not bricking your CYD wiring on the first attempt.","released":"2025","aliases":[],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"claimed","subghz_bruteforce":"claimed","subghz_rolling_code":"no","nrf24_scan":"yes","mousejack":"claimed","ble_jam":"no","wifi_deauth_24":"no","gps":"no","ibutton_1wire":"no","sd_logging":"unknown"},"legal":{"risk_level":"medium","notes":"The board itself is unrestricted hardware."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"cinder-ferret-v2","hardware_id":"cinder-ferret-v2","name":"Cinder Ferret V2","firmware":"HaleHound-CYD","firmware_kind":"n/a","vendor":"HaleHound","category":"accessory","subcategory":"cyd-radio-companion-board","status":"available","price_usd":40.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same plug-and-play profile as the original Cinder Ferret; GPS adds wardriving log interpretation to the skill set.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"The current-generation HaleHound companion board, adding an ATGM336H GPS module (via 1.25mm JST) to the original Cinder Ferret's CC1101 + NRF24L01 combo, developed with Midwest Gadgets. It's the standard radio+GPS board now shipped in HaleHound DIY kits.","honest_take":"Same value proposition as the original Cinder Ferret - pre-soldered off-the-shelf radio chips, not custom silicon - plus a $3-5 ATGM336H GPS module for wardriving logs. The $10 premium over the original Cinder Ferret roughly tracks the GPS module's real parts cost, which is reasonable, but don't mistake this for anything beyond assembly convenience.","released":"2026","aliases":[],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"claimed","subghz_bruteforce":"claimed","subghz_rolling_code":"no","nrf24_scan":"yes","mousejack":"claimed","ble_jam":"no","wifi_deauth_24":"no","gps":"yes","gps_wardrive_log":"yes","sd_logging":"unknown"},"legal":{"risk_level":"medium","notes":"Same posture as the original Cinder Ferret: the hardware is unrestricted, but sub-GHz transmission against systems you don't own/have authorization for is illegal in most jurisdictions."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"cinder-ferret-v2-2-double-nrf","hardware_id":"cinder-ferret-v2-2","name":"Cinder Ferret V2.2 Double NRF","firmware":"HaleHound-CYD","firmware_kind":"n/a","vendor":"HaleHound","category":"accessory","subcategory":"cyd-radio-companion-board","status":"available","price_usd":40.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Buying hardware ahead of its firmware support requires comfort with unfinished features and following the vendor's Discord for firmware drops.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A variant of the Cinder Ferret V2 companion board with two NRF24L01 radios instead of one, alongside the same CC1101 sub-GHz chip, co-developed with Midwest Gadgets for wider simultaneous 2.4GHz coverage. No GPS on this variant.","honest_take":"At the time of this research, the vendor's own product page stated firmware for the second NRF24 radio was 'out shortly, in a few weeks' and not yet released - meaning buying this today gets you hardware ahead of software support. Until that firmware lands, the second NRF24 is inert silicon; functionally it's a same-priced Cinder Ferret V2 minus GPS, plus a bet on a near-term firmware update.","released":"2026","aliases":["Cinder Ferret Double NRF"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"claimed","subghz_rolling_code":"no","nrf24_scan":"partial","mousejack":"claimed","ble_jam":"no","wifi_deauth_24":"no","gps":"no","gps_wardrive_log":"no"},"legal":{"risk_level":"medium","notes":"Hardware itself is unrestricted."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"medium"}},{"id":"crazyradio-pa","hardware_id":"crazyradio-pa","name":"Crazyradio PA","firmware":"MouseJack research firmware","firmware_kind":"community","vendor":"Bitcraze","category":"bluetooth","subcategory":"nrf24-24ghz","status":"discontinued","price_usd":38.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Command-line Python tooling; you must flash research firmware yourself.","build_effort":"flash-only","stealth":"discreet","form_factor":"usb-stick","summary":"A USB dongle built around the Nordic nRF24LU1+ with a 20 dBm power amplifier. It is the reference hardware for MouseJack - sniffing and injecting keystrokes into vulnerable 2.4 GHz (non-Bluetooth) wireless keyboards and mice - and for related nRF24 research such as KeySniffer.","honest_take":"Two catches. First, the vulnerabilities are from 2016; most currently sold peripherals are patched or use BLE, so hit rates in a modern office are low. Second and more important: Bitcraze is replacing it with Crazyradio 2.0, which is nRF52-based and explicitly cannot run the nRF24 research firmware - so buying the wrong model leaves you with a drone radio, not a security tool. Grab an nRF24LU1+ dongle while they exist.","released":"2014","aliases":["Crazyradio","MouseJack dongle"],"capabilities":{"nrf24_scan":"yes","mousejack":"yes","nrf24_jam":"partial","ble_scan":"no","wifi_scan_24":"no"},"legal":{"risk_level":"high","notes":"Injecting keystrokes into someone else's computer is unauthorised access in every jurisdiction that has a computer-misuse law."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2017","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"curious-bolt","hardware_id":"curious-bolt","name":"Curious Bolt","firmware":"Curious Bolt firmware","firmware_kind":"stock","vendor":"Curious Supplies","category":"hardware-debug","subcategory":"glitcher-logic-analyzer-scope multitool","status":"available","price_usd":49.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Voltage glitching and differential power analysis both require understanding the attack you're attempting and iterating with the bundled Python library; it was built for a cybersecurity-competition (ECSC 2023) audience, not total beginners, though the included challenges give a structured on-ramp.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The Curious Bolt is a Raspberry Pi RP2040-based hardware-hacking multitool combining three functions on one small board: a PIO-driven crowbar voltage glitcher with roughly 8.3ns timing resolution, an 8-channel logic analyzer speaking the SUMP protocol (works directly in PulseView/sigrok), and a 10-bit ADC used as a differential power-analysis scope. It originated as the hardware for the 2023 European Cyber Security Challenge (ECSC23) in Oslo and is now sold as a 'limited edition' kit bundled with the STM32F103 target board and four challenges used in that competition.","honest_take":"The RP2040 is doing essentially all the real-time work here - its PIO state machines generate the glitch pulses and clock the logic-analyzer/ADC sampling - so this is fundamentally a well-executed RP2040 project, not custom silicon; the actual engineering is in the PIO programs and the MS9280 parallel ADC front end. It sits in the same functional niche as the well-established ChipWhisperer-Nano and ChipWhisperer-Lite (glitcher plus power-analysis capture on one board), which have a far bigger user base and published courses behind them; Bolt's differential-power-scope mode is explicitly marked 'documentation in progress' by the vendor, making it the least mature of its three advertised functions. The firmware repo has had no commits since February 2024 and carries an open issue literally titled 'Firmware build instructions' because there aren't any in the repo - fine if you only ever run it as shipped, a real obstacle if you want to modify the firmware yourself. It is also not a JTAG/SWD debug probe or a UART bridge, despite being marketed as a general 'security multitool' - those are separate categories of tool it doesn't touch.","released":"2023","aliases":["Bolt","Curious Bolt Limited Edition"],"capabilities":{"glitching":"yes","logic_analyzer":"yes","uart":"no","jtag_swd":"no","i2c":"no","spi_flash_dump":"no","sd_logging":"no","scriptable":"yes","web_ui":"no","standalone_untethered":"no","side_channel_power":"partial"},"legal":{"risk_level":"low","notes":"A voltage glitcher, logic analyzer and power-analysis scope for hardware you own or are authorized to test; no radio, no restricted crypto."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2024-02","app_store":"No","abandoned_risk":"medium"}},{"id":"cw305-artix-fpga-target","hardware_id":"cw305-artix-fpga-target","name":"CW305 Artix FPGA Target Board","firmware":"Stock (NewAE)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"fpga-side-channel-target","status":"discontinued","price_usd":1462.5,"price_is_estimate":true,"skill_level":"expert","skill_note":"You are expected to bring or write your own FPGA bitstream (Verilog/VHDL crypto core) and a Vivado project - this is a target for people already doing FPGA-based side-channel or fault-injection research, not a beginner board.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A standalone Artix-7 FPGA target board built specifically to be attacked: it carries a socketable or soldered XC7A35T or XC7A100T FPGA, diode-protected power rails built for fault injection, dedicated shunt-resistor measurement points, and the standard 20-pin ChipWhisperer connector, so a CW1200/Lite/Husky can run power analysis or voltage-glitching experiments against whatever crypto core you load into the FPGA. NewAE ships example AES cores and Vivado projects to get started. It is the target, not the attack tool - by itself it does nothing.","honest_take":"This is not an attack tool at all - it is the victim board, and it only does anything once paired with a real ChipWhisperer capture unit (Lite, Husky, or the now-discontinued Pro) and your own FPGA bitstream. NewAE appears to have quietly walked away from selling it directly: the product page 404s and their old storefront domain is dead, even though the ChipWhisperer documentation still lists it as a supported target. Distributor stock exists (around $1,460, which is suspiciously identical across both FPGA sizes and probably stale), but there's no confirmed live channel to buy new from NewAE itself. If you need a new Artix-7 FPGA side-channel target today, NewAE's current lineup points two different directions instead: the smaller CW312T-XC7A35 on their newer modular CW312/CW313 target system for something closer to the CW305's own scope, or the much larger CW310 'Bergen Board' ($5,310, Kintex-7 K410T) if you actually need SoC/OpenTitan-scale emulation. Neither is a drop-in replacement for the CW305's specific form factor and price point, so treat 'buy a CW310 instead' with caution - it may be the wrong tier entirely for what the CW305 was doing.","released":"2016","aliases":["CW305","Artix FPGA Target Board","NAE-CW305-04-7A35-0.10-X","NAE-CW305-04-7A100-0.10-X"],"capabilities":{"glitching":"addon","jtag_swd":"yes","uart":"no","i2c":"no","spi_flash_dump":"no","logic_analyzer":"no","scriptable":"yes","standalone_untethered":"no","sd_logging":"no","web_ui":"no","side_channel_power":"addon"},"legal":{"risk_level":"low","notes":"A bare FPGA target board with no radio; legal to own and use everywhere."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025","app_store":"No","abandoned_risk":"medium"}},{"id":"cw308-ufo-board","hardware_id":"cw308-ufo-board","name":"CW308 UFO Board","firmware_kind":"n/a","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"target-baseboard","status":"out-of-stock","price_usd":325.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"The standard target platform for ChipWhisperer-based power analysis and glitching - assumes you already have a ChipWhisperer capture board and understand the basic DPA/CPA/glitching workflow; the UFO board itself is just the standardized victim-board plumbing.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"NewAE's standard baseboard, released in 2016, for building ChipWhisperer side-channel and glitching target ('victim') boards. It supplies clean, filtered power at 1.2V/1.8V/2.5V/3.3V and an adjustable 1.25-3.5V rail, a crystal-socket oscillator, an onboard LC low-pass filter for accurate shunt-based power measurement, and diode-protected I/O for voltage glitch injection - all shared infrastructure so a target daughtercard only needs to carry the chip under test. NewAE's own documentation notes the daughtercards deliberately omit decoupling capacitors the chip vendor would normally include, specifically to keep power traces clean for measurement.","honest_take":"This is the unglamorous infrastructure board that makes ChipWhisperer side-channel work reproducible across different target chips - it does nothing attack-related by itself, it just standardizes power filtering, clocking and glitch-injection wiring so daughtercards (STM32F3, XMEGA, AVR, FPGA targets) can be swapped without re-engineering the measurement setup each time. It's the right board to own once you're doing serious ChipWhisperer work across multiple target chip families; if you only ever plan to attack one specific chip, a purpose-built single-target board is cheaper.","released":"2016","aliases":["CW308","UFO Board"],"capabilities":{"glitching":"yes","uart":"addon","jtag_swd":"addon","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","scriptable":"yes","standalone_untethered":"no","web_ui":"no","app_store":"no","sd_logging":"no","side_channel_power":"yes"},"legal":{"risk_level":"low","notes":"A side-channel research target/victim baseboard with no radio transmitter and no offensive capability toward third-party systems - it hosts chips you deliberately mount and attack for research purposes."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"cw310-bergen-board","hardware_id":"cw310-bergen-board","name":"CW310 Bergen Board (Large FPGA, K410T)","firmware_kind":"n/a","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"fpga-target-board","status":"out-of-stock","price_usd":5310.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"A full SoC/crypto-core emulation target board for side-channel and fault-injection research on large security designs (e.g. OpenTitan) - this is research-lab-tier equipment, not a beginner side-channel board.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"NewAE's large-FPGA target board built around a Xilinx Kintex-7 XC7K410T (406,720 logic cells, 28nm, 900-pin FCBGA), sized for emulating full SoC and cryptographic-core designs such as OpenTitan for side-channel and fault-injection research. It carries a supervisory MCU handling FPGA configuration, thermal/voltage/clock management and USB control, DDR3/SRAM memory, JTAG/USB/PMOD headers, multi-stage VCC-INT filtering with an inductive shunt and LNA for clean power-analysis measurements, and SMA connectors plus cooling fans for EM fault-injection die access.","honest_take":"This is purpose-built for emulating large, realistic SoC/RoT designs like OpenTitan rather than the small toy targets (STM32F3, XMEGA) that ship with NewAE's entry-level CW308 UFO board - it's the board you move to once your research target is big enough that a small microcontroller emulation isn't representative anymore. One thing worth checking before buying: OpenTitan's current getting-started documentation points newcomers toward the newer CW340 board rather than CW310, which suggests CW310 may already be the previous-generation reference platform for that specific project rather than the current one - still fine for general large-FPGA side-channel work, but confirm compatibility with whatever bitstream you plan to load before paying $5,310 for a board that's also out of stock. At that price and with supply constrained, this is squarely academic/professional-lab equipment; a CW308 UFO board with a small target daughtercard covers general side-channel learning for a fraction of the cost.","aliases":["CW310","Bergen Board"],"capabilities":{"jtag_swd":"yes","glitching":"yes","scriptable":"yes","uart":"yes","spi_flash_dump":"addon","logic_analyzer":"no","i2c":"no","standalone_untethered":"no","web_ui":"no","sd_logging":"no","gps":"no","side_channel_power":"yes"},"legal":{"risk_level":"low","notes":"A research FPGA target board with no radio transmitter - it is the thing being attacked in side-channel/fault-injection research, not an offensive tool aimed at third parties."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"cw312t-rp2350","hardware_id":"cw312t-rp2350","name":"CW312T-RP2350","firmware_kind":"n/a","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"side-channel-target-board","status":"available","price_usd":30.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"This is a target, not a capture tool - using it for real side-channel or glitch work assumes you already know how to run a ChipWhisperer capture session.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A CW312-standard target board carrying a Raspberry Pi RP2350 (dual Cortex-M33 + Hazard3 RISC-V), with the chip's internal voltage regulator bypassed in favour of an external LDO so a ChipWhisperer capture unit can cleanly measure and glitch its 1.0 V core supply. It exists purely to give ChipWhisperer owners a current-generation MCU to practice power analysis and fault injection against.","honest_take":"This is not a standalone tool - it is a victim board. It plugs into NewAE's CW312 connector standard and needs a separate ChipWhisperer capture device (Nano, Lite or Husky) to do anything at all; budget for that if you don't already own one, since none of the glitching, power-analysis or debug capability lives on this board itself. The value here is specifically that it is a current, real-world MCU family (the RP2350/Pico 2 line) rather than the older toy targets bundled with entry kits, so glitch-detector and power-analysis practice transfers better to real hardware.","released":"2025","aliases":[],"capabilities":{"glitching":"partial","jtag_swd":"unknown","uart":"unknown","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","scriptable":"no","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no","side_channel_power":"partial"},"legal":{"risk_level":"low","notes":"A bare development/target board with no radio - legal to own and use everywhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"cynthion","hardware_id":"cynthion","name":"Cynthion","firmware":"Stock (LUNA gateware + Apollo)","firmware_kind":"stock","vendor":"Great Scott Gadgets","category":"hardware-debug","subcategory":"usb-analyzer","status":"out-of-stock","price_usd":210.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Packetry makes capture straightforward, but reading USB descriptors, transfers and endpoint traffic is a skill in itself.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An FPGA-based USB test instrument that captures Low, Full and High Speed USB 2.0 traffic between a host and a device, and can also emulate devices itself. It pairs Packetry for analysis with Facedancer for emulation, at a fraction of the price of commercial USB protocol analysers.","honest_take":"The value proposition is straightforward and real: commercial High-Speed USB protocol analysers start in the low thousands, and this does the core job for around $200 with open gateware you can modify. The limit to be clear about is that it is USB 2.0 only - Low, Full and High Speed. It does not capture SuperSpeed (USB 3.x), so a USB 3 device negotiating SuperSpeed will fall back or be invisible; Great Scott Gadgets has a separate 'LUNA SuperSpeed' project in development for that. Also budget for cables, because none are in the box and you need three connections to use it properly.","released":"2024","aliases":["LUNA","Cynthion USB multitool","Great Scott Gadgets Cynthion"],"capabilities":{"packet_capture":"yes","usb_hid_inject":"yes","usb_mass_storage":"yes","usb_ethernet_attack":"partial","usb_exfil":"partial","logic_analyzer":"no","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A bench instrument with no radio, legal to own and use everywhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"cypher-pn532","hardware_id":"cypher-pn532","name":"Cypher NFC (cypher-pn532)","firmware":"Cypher NFC v2.0","firmware_kind":"diy","vendor":"dkyazzentwatwa (independent open-source maintainer)","category":"rfid-nfc","subcategory":"nfc-workstation-diy","status":"diy-only","price_usd":25.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Requires wiring/soldering discrete modules, flashing Arduino IDE 2.x with ESP32 board support, and installing Adafruit_PN532/SSD1306/BusIO libraries. Using the dictionary-attack and magic-card-cloning features requires basic MIFARE Classic knowledge.","build_effort":"full-diy","stealth":"overt","form_factor":"handheld","summary":"Cypher NFC is an open-source, single-maintainer Arduino project that turns an ESP32-C3 + PN532 + SSD1306 OLED + SD card into a pocket NFC workstation: it reads and dumps MIFARE Classic/Ultralight/NTAG cards, runs an onboard dictionary attack against MIFARE Classic keys, clones Gen1a magic cards, and can emulate a Type 4 NDEF tag from a saved dump. A companion sketch ports the same logic to the M5Stack Cardputer ADV and a separate 'Cypherbox Mini' build.","honest_take":"This is a hobbyist Arduino sketch wired to off-the-shelf modules (PN532, SSD1306, generic SD reader) you can buy on Amazon for well under $25 total - there's no finished product, case, or kit sold; you solder and wire it yourself. Functionally it's a slower, more limited clone of what a Flipper Zero or Proxmark3 already does for MIFARE Classic: the PN532 chip itself can't emulate a MIFARE Classic target (only NTAG/Type4 NDEF), and there's no MIFARE DESFire, ISO15693, or EMV support at all. It's maintained by one person (48 stars, 10 forks, 5 open issues), and the built-in Wi-Fi control mode runs an unauthenticated AP at 192.168.4.1 - don't leave it powered on an open network mid-attack.","released":"2024","aliases":["Cypher PN532","CYPHER NFC v2.0"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"partial","mifare_classic_attacks":"yes","mifare_desfire":"no","nfc_type4_ndef":"yes","emv_read":"no","iso15693":"no","felica":"no","nfc_relay":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","sd_logging":"yes","scriptable":"yes","web_ui":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"medium","notes":"Owning and building the device is legal essentially everywhere - it's generic ESP32/PN532 hobbyist hardware."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2026-05","app_store":"n/a","abandoned_risk":"medium"}},{"id":"cypherock-emfi-board","hardware_id":"cypherock-emfi-board","name":"Cypherock EMFI Board","firmware":"Cypherock EMFI firmware","firmware_kind":"diy","vendor":"Cypherock","category":"hardware-debug","subcategory":"electromagnetic-fault-injection","status":"diy-only","price_usd":65.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"This is a roughly 1kV pulsed high-voltage device you build and hand-tune yourself, aimed at bypassing MCU read-out protection - it assumes you already understand fault-injection methodology, EMFI probe positioning, and high-voltage safety. A field report (see honest_take) describes the switching transistor, and on a repeat attempt the STM32 itself, being destroyed during first bring-up on a unit built exactly as documented.","build_effort":"full-diy","stealth":"overt","form_factor":"box","summary":"The Cypherock EMFI Board is an open-hardware electromagnetic fault-injection tool: a USB-powered, STM32L412-controlled boost converter and a 1200V IGBT (IXGA30N120B3) drive a step-up transformer and diode voltage multiplier into a bank of 1000V-rated capacitors, then discharge through a hand-built EM probe coil to inject a fast electromagnetic pulse timed against a target chip. Cypherock, a hardware crypto-wallet maker, designed and published it to research fault-injection and read-out-protection-bypass attacks against microcontroller families (STM32, ATSAMD, ATmega, ESP32) and a crypto-authentication IC used in wallets like their own, and shipped 8 matching DUT target boards for exactly that testing.","honest_take":"This sits in ChipSHOUTER territory - a purpose-built EMFI pulse generator - not ChipSHOUTER-PicoEMP territory; the PicoEMP is a much simpler, lower-voltage board, while this one runs a closed-loop PID voltage regulator up to roughly 1kV through a real IGBT switching stage, which is meaningfully more dangerous and more capable to build and operate. The single most important thing to know before attempting this: an open GitHub issue (filed August 2025, still unanswered as of this research) reports that the IGBT (Q1) self-excites and destroys itself on first power-up as designed, because it's switched directly by a logic-level MOSFET (Q3) instead of a proper isolated gate driver - and that repeated rebuild attempts destroyed further parts, including the STM32 MCU. Cypherock has not commented, and the repo has had zero commits since January 2024, so treat this as an unmaintained, reportedly broken-as-published design rather than a working product - budget for spare IGBTs and STM32s, or look at the actively-maintained ChipSHOUTER if you need something that works out of the box. The repo also ships 8 DUT boards (STM32F205RET6, STM32F427VIT6TR, STM32L496RGT6, STM32H753VIT6, ESP32-D0WD-V3, ATSAMD51J20A-AU, ATMEGA328P-AU, and an ATECC secure-element board), not the 7 MCU families the README's prose lists - the text and the actual hardware folder disagree by one.","released":"2023","aliases":["Cypherock EMFI","emfi-board"],"capabilities":{"glitching":"yes","uart":"yes","jtag_swd":"no","i2c":"no","spi_flash_dump":"no","logic_analyzer":"no","scriptable":"yes","web_ui":"no","standalone_untethered":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"Not a radio transmitter and not export-controlled crypto; owning/building a research EMFI tool is uncontroversial in most jurisdictions, similar to the already-tracked ChipSHOUTER."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2024-01","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"daeva","hardware_id":"daeva","name":"Daeva","firmware":"Daeva firmware","firmware_kind":"diy","vendor":"cifertech (open-source project, no commercial vendor)","category":"subghz","subcategory":"diy-subghz-replay-tool","status":"diy-only","price_usd":30.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Requires sourcing parts, fabricating and soldering a custom PCB (schematic provided in the repo), 3D printing the case, and building/flashing the firmware yourself - no assembled option exists.","build_effort":"full-diy","stealth":"discreet","form_factor":"handheld","summary":"An open-source, MIT-licensed, ESP32 + CC1101 sub-GHz scanner/replay tool with an OLED display, rotary encoder, microSD logging and TP4056 battery charging - a small-form-factor, bare-metal alternative to a Flipper Zero's sub-GHz function, buildable from the published schematic. 201 GitHub stars; last commit 2024-06-25.","honest_take":"This is functionally 'a Flipper Zero's CC1101 sub-GHz app, minus the Flipper, plus solder fumes' - the CC1101 radio is the same chip the Flipper uses internally, so its actual RF capability ceiling is identical (region-locked ISM bands, no rolling-code decryption of any kind). The README markets 'replay attack' capability without ever mentioning rolling versus fixed codes, which is a real gap: replaying a captured KeeLoq or similar rolling-code transmission from a modern car or garage door will not work, and nothing in the documented feature set suggests otherwise. The project has been quiet since its last commit in June 2024 (well over a year as of this research), so treat it as a working reference design rather than an actively-maintained tool - expect to debug it yourself if something doesn't work on current toolchain versions.","released":"2024","aliases":[],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_bruteforce":"no","subghz_amplified":"no","subghz_external_antenna":"unknown","sd_logging":"yes","standalone_untethered":"yes","scriptable":"unknown","gps":"no","app_store":"no","web_ui":"no","ble_scan":"no","wifi_scan_24":"no"},"legal":{"risk_level":"high","notes":"Same as any sub-GHz transceiver: receiving is broadly legal, but transmitting outside license-exempt ISM allocations - or replaying a captured signal to actuate a gate, garage, alarm or vehicle you do not own - is a separate offense from radio licensing in most countries."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2024-06","app_store":"No","abandoned_risk":"medium"}},{"id":"maltronics-deauth-detector","hardware_id":"maltronics-deauth-detector","name":"Deauth Detector","firmware":"Spacehuhn deauth detector","firmware_kind":"third-party-product","vendor":"Maltronics","category":"detection-defense","subcategory":"wifi-attack-detector","status":"available","price_usd":20.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug into USB power, watch the LED.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A pre-flashed ESP8266 dongle that watches 2.4 GHz channels for deauthentication frames and flashes an LED when someone is running a deauth attack nearby. Useful at conferences and in offices as a cheap canary.","honest_take":"It is a USD 3 ESP8266 with free firmware in a case - you can flash the identical thing yourself in ten minutes. It only sees 2.4 GHz, only counts deauth/disassoc frames, and cannot tell an attack from a badly behaved AP kicking clients off. It detects one specific attack, not 'hacking'.","released":"2019","aliases":["Spacehuhn Deauth Detector"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","detect_generic_wifi":"partial","detect_pineapple":"no"},"legal":{"risk_level":"low","notes":"Purely passive receive."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"2023-08","app_store":"No","abandoned_risk":"medium"}},{"id":"unit72784-diabolic-drive","hardware_id":"unit72784-diabolic-drive","name":"Diabolic Drive","firmware":"Diabolic Drive firmware","firmware_kind":"third-party-product","vendor":"UNIT 72784","category":"usb-hid","subcategory":"wireless-badusb-drive","status":"available","price_usd":115.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Default operation (plug in, trigger a stored payload over the web UI) is approachable; spoofing hardware IDs, writing custom firmware, or using the exposed ATmega32U4 bootloader for deep customization is not.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A USB-A flash drive that is a genuine, working 64GB storage device (real read/write, ~20/10 Mbps) until wirelessly commanded over its own Wi-Fi access point to expose a HID keyboard interface and fire a stored keystroke-injection payload. Both its storage and HID personas can have their VID/PID/serial/vendor strings spoofed to match a specific brand.","honest_take":"This is the most direct like-for-like comparison in the batch: the vendor's own listing puts it against the Rubber Ducky ($100, no wireless, no storage) and O.MG Cable Basic ($120, wireless but no 64GB of real storage) and the pricing genuinely tracks - you're paying about the same as those for meaningfully more (dual persona, real usable storage that works *during* payload firing, spoofable IDs). The catch is architectural, not marketing: it's an ATmega32U4 doing the HID work talking to an ESP8266 over serial/I2C, the same pairing used by several $25 hobbyist boards in this very batch (Wifi BadUSB, and the open-source WiFi Duck/supremeDuck lineage it's explicitly compatible with) - so a chunk of the $115 is the 64GB flash controller, the assembled/tested universal-drive PCB, and spoofable-ID firmware polish, not exotic silicon.","released":"2023","aliases":[],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","usb_exfil":"partial","usb_keylogger":"no","hid_remote_trigger":"yes","usb_payload_lang":"claimed","hardware_destruct":"no","wifi_ap_mode":"yes","standalone_untethered":"partial","app_store":"no","scriptable":"yes"},"legal":{"risk_level":"high","notes":"Owning the hardware is legal."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"2025-06 (keystroke reflection, dynamic hardware-ID spoofing, OS detection firmware update)","app_store":"No","abandoned_risk":"low"}},{"id":"unit72784-diabolic-parasite","hardware_id":"unit72784-diabolic-parasite","name":"Diabolic Parasite","firmware":"Diabolic Parasite firmware","firmware_kind":"third-party-product","vendor":"UNIT 72784","category":"usb-hid","subcategory":"covert-usb-implant","status":"preorder","price_usd":125.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Deploying it well requires physical access to swap a target's existing keyboard/mouse cable, understanding of USB HID descriptor behavior, and operational awareness of what its keystroke-injection and exfiltration channel will and won't trigger in EDR/behavioral tooling.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"An inline USB pass-through implant: you unplug a target's keyboard/mouse, plug it into the Parasite's female port, then plug the Parasite into the freed host port. It clones the passthrough device's full USB identity (VID/PID/manufacturer/product strings), logs every keystroke to a web UI over Wi-Fi, and can be wirelessly triggered to inject keystrokes or open an encrypted covert shell - all while behaving as an inert passthrough the rest of the time.","honest_take":"The headline feature isn't the keystroke injection - every device in this batch does that - it's that Diabolic Parasite is simultaneously a full hardware keylogger for whatever real keyboard is plugged through it, which almost none of the cheaper BadUSB cables/sticks here can do. That capability is also exactly why it's the most legally dangerous device in this batch: wiretapping/keylogger statutes in most jurisdictions treat *capturing someone else's input* very differently from injecting your own, and 'Diabolic Shell' turning stray keystrokes into a live exfiltration channel is squarely built for interactive access to systems you don't own. It's still pre-order as of this check (ships Oct 31, 2026, per the vendor), so nothing about its real-world detectability against modern EDR is independently verified yet - treat vendor evasion claims as marketing until someone publishes a teardown or a blue-team writeup.","released":"2026","aliases":[],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"no","usb_keylogger":"yes","usb_exfil":"yes","hid_remote_trigger":"yes","usb_payload_lang":"claimed","hardware_destruct":"yes","usb_ethernet_attack":"no","standalone_untethered":"partial","app_store":"no","scriptable":"claimed"},"legal":{"risk_level":"high","notes":"This device both injects keystrokes AND captures a third party's real keystrokes - the latter is a wiretapping/interception offence in most jurisdictions (e."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"2026-02 (enclosure design files; firmware v2.0/Diabolic Shell announced Jan 2026)","app_store":"No","abandoned_risk":"low"}},{"id":"digilab-flipperzero-lab401","hardware_id":"digilab-flipperzero","name":"DigiLab for FlipperZero","firmware":"Lab401 DigiLab companion app","firmware_kind":"third-party-product","vendor":"Lab401 (hardware design by tixlegeek)","category":"hardware-debug","subcategory":"multi-protocol-probe","status":"available","price_usd":64.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Designed to be approachable: guided in-app calibration, and voltage/protocol info is surfaced via audio/LED/haptic feedback rather than requiring the user to read raw numbers or scope traces.","build_effort":"assembly","stealth":"overt","form_factor":"hat-shield","summary":"DigiLab is a Flipper Zero GPIO add-on designed by tixlegeek for Lab401: a probe module with its own analog front-end (protection/conditioning circuitry rated to 12V, plus an onboard I2C EEPROM used for demos) that feeds signals to the Flipper's own CPU rather than carrying a separate processor. The open-source (GPL-3.0) companion app provides four tools: an oscilloscope-style Scope with configurable audio/LED/haptic feedback, a quick voltage/frequency Probe, and I2C/SPI device scanners with a built-in hex editor for reading and writing device registers.","honest_take":"This is not just a GPIO pin breakout: Lab401's own behind-the-scenes post says they tried and abandoned putting an ESP32 on the board, and shipped analog signal-conditioning circuitry (voltage scaling/protection up to 12V) plus an onboard demo EEPROM instead - there is genuine purpose-built hardware behind the $64. That said, most of what makes it interesting - the oscilloscope view, the configurable feedback, the I2C/SPI 'prediction engine' - is software running entirely on the Flipper's own CPU, so DigiLab itself is best understood as a well-engineered analog probe front-end for the Flipper's GPIO. It also caps out at ~200kHz and is 3.3V-only for its I2C/SPI modes, so it's explicitly pitched as a first-look exploration tool rather than a scope or logic-analyzer replacement. It does NOT add any of the Flipper's headline radio capabilities (Sub-GHz, NFC/RFID, IR) - those come from the Flipper itself and are unrelated to this module, a common point of confusion for anyone assuming a Flipper 'module' adds radio range or protocols.","released":"2025","aliases":["Lab401 DigiLab","401 DigiLab","401/DigiLab"],"capabilities":{"i2c":"yes","spi_flash_dump":"partial","uart":"no","jtag_swd":"no","logic_analyzer":"partial","glitching":"no","subghz_rx":"no","hf_1356_read":"no","ir_rx":"no","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A passive probe accessory with no radio or transmit function - owning and using it carries no meaningful restriction anywhere, independent of any Flipper Zero-specific import rules that apply to the host device itself."},"ecosystem":{"community":"slow","docs_quality":"excellent","last_release":"2025-10","app_store":"Yes - official Flipper App Catalog (catalog.flipperzero.one)","abandoned_risk":"medium"}},{"id":"cheap-badusb-boards","hardware_id":"cheap-badusb-boards","name":"Digispark and CH552 BadUSB boards","firmware":"Custom","firmware_kind":"diy","vendor":"No single vendor - generic AliExpress/eBay clone boards","category":"usb-hid","subcategory":"budget-badusb","status":"available","price_usd":3.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Cheap to buy, fiddly to use. On Digispark you fight the micronucleus bootloader, Windows driver installation via Zadig, and a plug-in timing window; on CH552 the flashing is easier but the toolchain is less familiar. Neither is a plug-and-play experience.","build_effort":"flash-only","stealth":"discreet","form_factor":"usb-stick","summary":"The budget end of keystroke injection: two families of very cheap microcontroller boards with a USB-A plug on the PCB, flashed with a sketch that makes them enumerate as a keyboard and type a payload. The Digispark uses an ATtiny85 with software USB; CH552 boards use a WCH 8051 microcontroller with a real hardware USB peripheral. Together they are the standard answer to 'do I really need a $80 Rubber Ducky'.","honest_take":"For most people, no, you do not need the expensive one - but know what you are giving up. There is no storage on either, so the payload is compiled into the firmware and changing it means reflashing, and there is no exfiltration path at all. And prefer CH552 over Digispark: the ATtiny85 bit-bangs USB in software (V-USB, low-speed only), which is why Digisparks are notorious for failing to enumerate on USB 3.x ports and hubs, for needing driver wrangling on Windows, and for the five-second bootloader delay before your payload runs. The CH552 has a hardware full-speed USB peripheral and roughly twice the flash for about the same money. Also note the ecosystem here is quiet: the big Digispark script collections were last touched in 2022-2023. Finally, if a seller markets one of these as a 'hacking device' at $25, you are paying $22 for a sticker.","released":"2012","aliases":["Digispark","Digispark ATtiny85","Duckduino","CH552","CH552G BadUSB","poor man's rubber ducky","$5 rubber ducky"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"partial","usb_mass_storage":"no","usb_exfil":"no","hid_remote_trigger":"no","scriptable":"partial"},"legal":{"risk_level":"medium","notes":"These are ordinary hobbyist development boards, sold openly and legal to own everywhere."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"n/a - no single project; the largest Digispark script collection was last updated 2023-02","app_store":"No","abandoned_risk":"medium"}},{"id":"dirtyjtag","hardware_id":"dirtyjtag","name":"DirtyJTAG","firmware":"DirtyJTAG","firmware_kind":"diy","vendor":"dirtyjtag","category":"hardware-debug","subcategory":"jtag-adapter-firmware","status":"diy-only","price_usd":5.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flashing the firmware onto an ST-Link clone or blue pill is a documented, well-trodden process, but you are working with unbranded clone hardware and a project whose own author calls the JTAG implementation imperfect.","build_effort":"flash-only","stealth":"discreet","form_factor":"board","summary":"Open-source firmware that turns dirt-cheap ST-Link v2 clones and STM32 'blue pill' boards into a generic USB JTAG adapter, filling the role of the old LPT Wiggler cable for a few dollars of hardware. It speaks a simple USB protocol (VID 0x1209 / PID 0xC0CA) that UrJTAG, openFPGAloader and flashrom already support natively.","honest_take":"The project's own README is refreshingly blunt: 'DirtyJTAG is dirty and dirt cheap, but is not fast nor a perfect implementation of the JTAG protocol.' Independent testing has found its TCK clock effectively capped around 1 MHz no matter what speed you request in software - call it an order of magnitude slower than a real J-Link or even a decent CMSIS-DAP probe. OpenOCD support has existed only as an out-of-tree patch under review rather than a merged feature (check current status before assuming it works out of the box), and the flashy 'runs on a Pi Pico or Tang Nano too' claim is true only via separate community forks, not the official project. It also has no SWD support at all - JTAG only. Buy it for what it is: a way to turn a $2-5 clone board you already have lying around into a slow-but-usable JTAG cable for UrJTAG/openFPGAloader/flashrom, not a fast general debug probe.","released":"2016","aliases":[],"capabilities":{"jtag_swd":"partial","spi_flash_dump":"no","uart":"no","i2c":"no","logic_analyzer":"no","glitching":"no","scriptable":"yes","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"DIY firmware for a bench JTAG adapter with no radio - legal to own and build everywhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-03","app_store":"No","abandoned_risk":"low"}},{"id":"halehound-diy-28-kit","hardware_id":"halehound-diy-28-kit","name":"DIY 2.8\" HaleHound Kit","firmware":"HaleHound","firmware_kind":"third-party-product","vendor":"HaleHound","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":139.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same JST-harness, Cinder Ferret V2 approach as the 3.5in kit, just on the smaller 2.8in board.","build_effort":"assembly","stealth":"overt","form_factor":"handheld","summary":"The cheapest current HaleHound kit: a QDtech E32R28T exposed-SPI CYD touchscreen, a 3D-printed case with an embedded NTAG216 passive NFC tag, a combined CC1101+NRF24 'Cinder Ferret V2' companion board, an ATGM336H GPS with ceramic antenna, and a JST wiring harness - the same closed HaleHound firmware as the rest of the line, on the smaller 2.8in screen, without a battery or the PN532 NFC reader.","honest_take":"This is functionally the 3.5in DIY kit on a smaller, cheaper screen - same Cinder Ferret V2 board, same missing PN532 (so no real NFC/RFID capability despite the embedded NTAG216 passive tag in the case), same GPS, same 300-439MHz sub-GHz ceiling documented for this firmware family. The already-tracked bare 2.8in CYD entry in this database documents the same firmware running on an unmounted board for roughly $45-65 all-in with loose modules you source and wire yourself; this $139 kit is that same destination reached with a combined companion board, a pre-made harness, a case and a bundled GPS instead of individual module shopping and wiring. Whether that convenience is worth roughly double the DIY price is a real question worth asking before buying either.","released":"2026","aliases":["HaleHound 2.8in DIY Kit"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"yes","ble_scan":"yes","ble_advertise":"yes","ble_tracker_detect":"yes","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"yes","subghz_amplified":"unknown","nrf24_scan":"yes","mousejack":"yes","nrf24_jam":"claimed","hf_1356_read":"no","hf_1356_write":"no","lf_125khz_read":"no","gps":"yes","gps_wardrive_log":"claimed","sd_logging":"yes","usb_hid_inject":"no","ir_tx":"no","detect_surveillance_cam":"yes","detect_skimmer":"yes"},"legal":{"risk_level":"high","notes":"Same profile as the rest of the HaleHound line: jamming modules are a criminal offence to transmit in the US, UK and EU; deauth, evil twin, MouseJack and sub-GHz replay/bruteforce each carry separate legal exposure."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"No","abandoned_risk":"high"}},{"id":"halehound-diy-35-kit","hardware_id":"halehound-diy-35-kit","name":"DIY HaleHound 3.5\" Kit","firmware":"HaleHound","firmware_kind":"third-party-product","vendor":"HaleHound","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":149.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"JST-connector wiring harness and the combined Cinder Ferret V2 board reduce this from a loose-module soldering project to mostly plugging harnesses together, per the included PDF build guide.","build_effort":"assembly","stealth":"overt","form_factor":"handheld","summary":"The 3.5-inch DIY HaleHound kit: a QDtech E32R35T exposed-SPI CYD touchscreen, a 3D-printed case with an embedded NTAG216 passive NFC tag, a combined CC1101+NRF24 'Cinder Ferret V2' companion board, an ATGM336H GPS with ceramic antenna, and a JST wiring harness - running the same HaleHound firmware as the rest of the line, without a battery or the PN532 NFC reader.","honest_take":"The embedded NTAG216 in the case is a passive tag, not a reader - without the PN532 this kit no longer includes, the firmware itself cannot read or write any NFC/RFID card; the NTAG216 is presumably there for something like tap-to-identify the unit, not for adding NFC capability to the toolset. That is a meaningful, easy-to-miss downgrade from the Complete Unit above and from the base bare-CYD HaleHound build documented elsewhere in this database, both of which do include a PN532. What you are paying $149 for over that bare-board approach (documented there at roughly $45-65 all-in for the same sub-GHz/2.4GHz/Wi-Fi/BLE feature set) is the combined Cinder Ferret V2 board and pre-made harness replacing loose-module soldering, plus a case and a bundled GPS - genuinely less DIY risk, at roughly 2-3x the parts cost. The firmware itself carries every caveat documented on the base entry: closed source, one maintainer, one flasher domain, 300-439MHz sub-GHz ceiling.","released":"2026","aliases":["HaleHound 3.5in DIY Kit"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"yes","ble_scan":"yes","ble_advertise":"yes","ble_tracker_detect":"yes","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"yes","subghz_amplified":"unknown","nrf24_scan":"yes","mousejack":"yes","nrf24_jam":"claimed","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","lf_125khz_read":"no","gps":"yes","gps_wardrive_log":"claimed","sd_logging":"yes","usb_hid_inject":"no","ir_tx":"no","detect_surveillance_cam":"yes","detect_skimmer":"yes"},"legal":{"risk_level":"high","notes":"Same profile as the rest of the HaleHound line: jamming modules are a criminal offence to transmit in the US, UK and EU; deauth, evil twin, MouseJack and sub-GHz replay/bruteforce each carry separate legal exposure."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"No","abandoned_risk":"high"}},{"id":"doppelganger-core","hardware_id":"doppelganger-core","name":"Doppelgänger Core","firmware":"Doppelgänger","firmware_kind":"third-party-product","vendor":"Mayweather Group / Physical Exploitation (PPE)","category":"rfid-nfc","subcategory":"access-control-implant","status":"available","price_usd":66.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You are wiring into a live reader's Wiegand lines inside someone's building.","build_effort":"assembly","stealth":"implant","form_factor":"board","summary":"An ESP32-based implant that hides inside a commercial card reader, captures Wiegand (and keypad) credential data, and makes it available over Wi-Fi with notification egress so the operator does not have to return to the reader. The modern successor to BLEKey and a sibling of ESPKey, with card-format decoding for HID, Indala, Paxton and others.","honest_take":"The board is cheap; the ecosystem is not. Community Edition covers a handful of HID and Indala formats, and the interesting stuff - keypad PINs, MIFARE, Corporate 1000 48-bit, Simplex - sits behind the paid Pro/Stealth/MFAS tiers, with ATLAS as an annual subscription on top. It is also, functionally, a bug you install in someone's wall: without a signed engagement scope it is straightforwardly illegal, and it needs physical access to the reader in the first place.","released":"2022","aliases":["Doppelganger","Doppelgänger Pro/Stealth/MFAS"],"capabilities":{"lf_125khz_read":"partial","hf_1356_read":"partial","web_ui":"yes","cloud_c2":"yes","wifi_ap_mode":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"This is a covert credential-capture implant."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025-12","app_store":"No - paid firmware tiers plus the ATLAS mobile platform","abandoned_risk":"low"}},{"id":"dstike-deauther-watch","hardware_id":"dstike-deauther-watch","name":"DSTIKE Deauther Watch","firmware":"esp8266_deauther 2.6.1","firmware_kind":"community","vendor":"DSTIKE (hardware); firmware by Spacehuhn Technologies","category":"wifi","subcategory":"deauther","status":"available","price_usd":49.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Arrives flashed and working with an on-screen menu; the only real skill needed is understanding why it often does nothing, which is a networking question rather than a hardware one.","build_effort":"flash-only","stealth":"discreet","form_factor":"wearable","summary":"A wrist-worn ESP8266 running Spacehuhn's Deauther firmware: it scans 2.4GHz networks and clients, then sends deauthentication and disassociation management frames to knock clients off, along with beacon spam and probe flooding. DSTIKE makes the hardware - a customised 4MB ESP-07 module, a 1.3in SH1106 OLED, a 1000mAh cell, a three-way switch and USB-C - and the firmware is the free open-source project everyone else uses too.","honest_take":"Say this every single time: the deauth attack works only because 802.11 management frames were historically unauthenticated. 802.11w/PMF authenticates them, WPA3 makes PMF mandatory, and modern WPA2 gear increasingly turns it on - against any of those this watch does absolutely nothing, silently. It is also 2.4GHz only, so every 5GHz network is invisible to it. And it does not capture, crack or reveal anything: there is no handshake capture, no password recovery, nothing beyond disruption. On the firmware side, the last release was 2.6.1 in August 2021 and the last real code commit to the v2 branch was April 2022 - a v3 branch exists and has existed for years without shipping. The hardware is nice and the maker is legitimate; just understand you are paying $49 for a wearable case around a $4 board running frozen free software.","released":"2017","aliases":["Deauther Watch","DSTIKE Deauther","ESP8266 Deauther","Spacehuhn Deauther","Deauther Watch X","Deauther Watch Y"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"partial","wifi_deauth_5":"no","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_monitor_mode":"partial","wifi_handshake_capture":"no","wifi_evil_twin":"no","detect_generic_wifi":"partial","usb_hid_inject":"addon","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Owning it is legal in most places."},"ecosystem":{"community":"slow","docs_quality":"excellent","last_release":"2021-08","app_store":"No","abandoned_risk":"high"}},{"id":"dual-band-wifi-mt7921au","hardware_id":"dual-band-wifi-mt7921au","name":"Dual Band WiFi MT7921AU USB Adapter","firmware_kind":"n/a","vendor":"Generic (MediaTek MT7921AU)","category":"wifi","subcategory":"usb-wifi-adapter","status":"available","price_usd":40.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-play USB dongle; relies on the same in-kernel mt7921u driver as device 2 above.","build_effort":"assembled","stealth":"overt","form_factor":"usb-stick","summary":"A dual-band, Wi-Fi 6-capable USB adapter built on MediaTek's MT7921AU chipset, sold by Hacker Warehouse as an unbranded/generic listing (no manufacturer named). Physically it's a small USB dongle body with two detachable external omni-directional antennas, using the same mt76/mt7921u Linux driver family as the internal uConsole card (device 2 in this batch). The listing claims monitor mode and packet injection support across 802.11 a/g/n/ac.","honest_take":"This is a generic, likely white-label board - Hacker Warehouse doesn't name a manufacturer, and the listing's own disclaimer that you might receive a device that looks different from the picture is a real red flag for a security tool where you want to know exactly what silicon you're plugging in. Chipset-wise it's the same MT7921-series family as the uConsole card above, sharing the same mt7921u driver and the same open reliability problems: morrownr/USB-WiFi issue #387 documents frame injection failing or falling back to 1/6Mbps on this exact chipset, and openwrt/mt76 issue #839 documents active monitor mode (needed for PMKID capture) being broken on mt7921u. Whether 'MT7921AU' here is the identical die to the 'MT7921AUN' in device 2, or a genuinely distinct SKU, could not be confirmed from public sources - even the morrownr/USB-WiFi maintainers have an open, unresolved GitHub thread about it. Of the three Wi-Fi adapters in this batch, this is the one to skip: it costs almost the same as the ALFA AWUS036ACM ($40 vs $46.97), comes with no verifiable brand accountability, and inherits the same unresolved mt7921u injection bugs as the uConsole card - without that card's one real advantage of fitting a specific niche host. If you specifically want a WiFi 6/6E-class adapter for its own sake, this at least gives you a standalone dongle (unlike device 2), but for reliable monitor-mode/injection work, the MT7612U-based ALFA adapter remains the better buy at a similar price.","aliases":["MT7921AU USB WiFi adapter"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"claimed","wifi_injection":"partial","wifi_handshake_capture":"partial","wifi_pmkid":"no","wifi_ap_mode":"claimed","wifi_wardriving":"yes","packet_capture":"partial","bt_classic":"unknown","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"Owning and importing this adapter is legal essentially everywhere - it's sold as a consumer Wi-Fi peripheral."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"N/A - it's a Wi-Fi radio peripheral, not an app platform","abandoned_risk":"low"}},{"id":"dualcomm-etap-2003-gigabit-tap","hardware_id":"dualcomm-etap-2003-gigabit-tap","name":"Dualcomm ETAP-2003 Gigabit Ethernet Tap","firmware_kind":"n/a","vendor":"Dualcomm","category":"network-implant","subcategory":"ethernet-tap","status":"available","price_usd":210.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-use hardware, but interpreting captured traffic needs a separate analyzer on the monitor port and real 802.11/Ethernet knowledge.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"A single inline-port, USB-powered 10/100/1000BASE-T copper Ethernet tap with PoE pass-through, in a small metal case. It presents a mirrored copy of both directions of traffic on a monitor port for an external analyzer; unlike the 5-port switch-based tap in this same batch, it is built specifically as a dedicated tap rather than a repurposed switch.","honest_take":"Reseller copy for this device family claims 'no power needed' and 'lossless' Gigabit monitoring, but that claim needs scrutiny: full-duplex 1000BASE-T uses all four copper pairs bidirectionally, so a Gigabit tap generally cannot just electrically split the line onto a passive monitor port the way a true zero-power 10/100 tap (like the Throwing Star LAN Tap, already tracked here) can - most designs in this class need active circuitry to aggregate both directions onto a single monitor port, and that circuitry needs power even if the inline link itself might keep passing traffic unpowered. Dualcomm's own site doesn't spell out which parts of this device are truly passive versus USB-powered, so treat any 'can't be detected, no power needed' claim as something to verify yourself with a bench test, not something to take on faith.","aliases":["Gigabit Ethernet Tap (Hacker Warehouse listing name)","DC-2003","ETAP-2003"],"capabilities":{"ethernet_tap_passive":"claimed","packet_capture":"yes","ethernet_mitm":"no","cloud_c2":"no","vpn_exfil":"no","usb_hid_inject":"no","wifi_scan_24":"no","standalone_untethered":"no","web_ui":"no","app_store":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"Legal to own."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"epic-erebus","hardware_id":"epic-erebus","name":"EPIC Erebus","firmware":"Custom","firmware_kind":"diy","vendor":"SecuringHardware.com","category":"hardware-debug","subcategory":"dma-attack","status":"vaporware","price_is_estimate":false,"skill_level":"expert","skill_note":"Pitched explicitly around protocol-layer tinkering (open PCIe implementation, deep gateware modification), a level beyond just running pre-built PCILeech firmware on a Squirrel-class board.","build_effort":"assembled","stealth":"implant","form_factor":"board","summary":"A pre-launch M.2 2230 FPGA card built around a Lattice ECP5 (ECP5-25 or ECP5-5G-85) for PCIe-based direct memory access research, positioned as PCILeech-compatible. Unlike bench-style PCIe DMA cards, it's sized and marketed to live permanently inside a laptop's internal M.2 slot and run standalone - acquiring memory and doing patch/match operations without a tethered host. Gateware, firmware and toolchain are promised fully open source. As of September 2026 it exists only as a pre-launch Crowd Supply listing with no price, no funded campaign, and no published source code.","honest_take":"This is not a product you can buy yet: as of September 2026 the Crowd Supply page says 'launching soon,' with zero backers, zero updates, no price, and a linked GitHub org (github.com/epic-erebus) that contains nothing. Compared to the already-shipping Screamer PCIe Squirrel - an Artix-7 card you plug into a desktop PCIe x1 slot when you want to run an attack, priced around EUR 159 - Erebus targets the opposite use case: an M.2 2230 card small enough to install inside a laptop's Wi-Fi/NVMe slot and leave there, which the vendor states outright ('you can keep installed inside your laptop'). That makes it a plausible internal implant rather than a bench tool, and shifts the threat model from 'plug a card in' to 'install something permanently and close the case.' The people behind it (Joe FitzPatrick of SecuringHardware.com and Piotr Esden-Tempski) have a genuine track record in hardware-security training and open FPGA tooling, so this reads as a credible upcoming project rather than vaporware in the pejorative sense - but today it is unpriced, unreleased, and the 'fully open gateware' claim can't be checked against any published source.","aliases":["Erebus","EPIC Erebus DMA board"],"capabilities":{"usb_exfil":"claimed","standalone_untethered":"claimed","scriptable":"claimed","sd_logging":"claimed","packet_capture":"no","glitching":"no","ethernet_mitm":"no","ethernet_tap_passive":"no","cloud_c2":"no","vpn_exfil":"no","hdmi_capture":"no","spi_flash_dump":"no","jtag_swd":"unknown","uart":"unknown","i2c":"unknown","logic_analyzer":"no","pcie_dma":"claimed"},"legal":{"risk_level":"high","notes":"Same category as other PCIe DMA cards: reading or modifying a machine's memory without authorization is unauthorized computer access almost everywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No - no software released","abandoned_risk":"medium"}},{"id":"esp-rfid-tool","hardware_id":"esp-rfid-tool","name":"ESP RFID Tool","firmware":"ESP-RFID-Tool (Corey Harding)","firmware_kind":"third-party-product","vendor":"April Brother (manufacturer), sold by Hacker Warehouse, Lab401, Tindie","category":"rfid-nfc","subcategory":"wiegand-logger","status":"available","price_usd":30.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Wire three lines to a reader, then use a web page - the hard part is the wiring and the authorisation.","build_effort":"assembly","stealth":"implant","form_factor":"board","summary":"The cheap, widely stocked Wiegand logger: an ESP8266 board that taps a reader's data lines, stores captured credentials and serves them from a built-in Wi-Fi access point. Also works inline with long-range readers such as the HID MaxiProx 5375, which is how most people use it for badge harvesting.","honest_take":"The firmware has not been touched since 2023 and is built against an ancient ESP8266 core, so treat it as frozen. Its 'experimental TX' replay and PIN brute-force features are exactly that - experimental, and they can lock accounts or trip alarms. For new work The Tick or ESPKey are better maintained; the ESP RFID Tool's advantage is that it is USD 30 and always in stock.","released":"2018","aliases":["ESP RFID Thief","Wiegand sniffer"],"capabilities":{"lf_125khz_read":"partial","web_ui":"yes","wifi_ap_mode":"yes","usb_payload_lang":"no","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Same as other reader taps - legal to own and to test on your own reader, criminal to attach to somebody else's access control without authorisation."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2023-01","app_store":"No","abandoned_risk":"high"}},{"id":"esp-rfid-tool-v2-pro","hardware_id":"esp-rfid-tool-v2-pro","name":"ESP-RFID-Tool v2 PRO","firmware":"Einstein2150 v2 (open source)","firmware_kind":"stock","vendor":"Raik Schneider (Einstein2150)","category":"rfid-nfc","subcategory":"wiegand-interceptor","status":"available","price_usd":41.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Requires physical access to a reader's Data0/Data1/Ground wiring and working knowledge of Wiegand bit-length math to make sense of captures - a red-team physical-access tool, not a point-and-click gadget.","build_effort":"assembled","stealth":"covert","form_factor":"board","summary":"An ESP8266 (ESP-12) board that taps a standard 5V Wiegand reader-to-panel wire run, logs the raw bitstream with automatic UID decoding for common HID bit-length formats, and can actively replay or fuzz a captured or synthesised bitstream back onto the line via MOSFET-driven active pull-downs, all through a mobile-friendly web UI. It has no RFID/NFC radio of its own - it works entirely at the wired Wiegand-signal level, downstream of whatever reader already decoded the card.","honest_take":"This is a fork of Corey Harding's earlier open-source ESP-RFID-Tool logging project, but the 'v2 PRO adds transmit' framing oversimplifies it - the original already had an experimental TX/replay/fuzzing mode of its own, just explicitly unofficial. What the €38 assembled board actually buys is a properly engineered MOSFET TX path instead of a 'consider it a bonus' hack, wider auto-decoded bit formats, and not having to build it yourself. It only sees what's already in cleartext on the Wiegand wire, which is every legacy HID/Wiegand deployment by design; it does nothing against a modern OSDP or other encrypted reader-to-panel link. The vendor's own 'fuzzing/brute-force' framing and 'qualified professionals only' disclaimer both point at the same thing: this is built for scoped engagements, and casual use on a system you don't own crosses a legal line fast.","aliases":["ESP RFID Tool v2 PRO","ESP-RFID-Tool-v2"],"capabilities":{"lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","ibutton_1wire":"no","gps":"no","scriptable":"yes","web_ui":"yes","standalone_untethered":"partial","sd_logging":"no","wiegand_tap":"yes"},"legal":{"risk_level":"high","notes":"Owning the board is legal."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2026-08","app_store":"n/a","abandoned_risk":"medium"}},{"id":"cyd-2432s028r-halehound","hardware_id":"cyd-2432s028r","name":"ESP32 Cheap Yellow Display (ESP32-2432S028R)","firmware":"HaleHound","firmware_kind":"third-party-product","vendor":"Jesse C. Hale (firmware) on generic CYD hardware","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":13.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flashing is a two-minute browser job, but anything past Wi-Fi and BLE means soldering four modules onto a board with three free GPIOs and resolving documented pin collisions.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"A dense multi-protocol offensive toolkit for the Cheap Yellow Display, forked from CiferTech's ESP32-DIV. Roughly 40 modules spanning Wi-Fi, BLE, 2.4 GHz nRF24, sub-GHz via CC1101 and NFC via PN532 or Chameleon Ultra, plus detection features and named CVE modules. Every offensive module sits behind a liability gate; decline it and the firmware runs in a passive Blue Team mode.","honest_take":"Almost every write-up calls HaleHound open source. It is not. The repo holds a README and a proprietary licence and zero lines of code, the binaries come only from the author's own web flasher (the GitHub releases carry no assets), and the licence explicitly forbids redistributing, modifying or selling them - while the thing itself is a derivative of CiferTech's MIT-licensed ESP32-DIV. One maintainer, no source, one distribution channel: if he stops, the firmware goes with him and nobody can fork it. On the hardware side, 'broadband jamming' means an nRF24L01+PA+LNA spraying 2.4 GHz at +20 dBm rather than any real wideband jammer, the documented CC1101 wiring only covers 300-439 MHz so it will not touch 868 or 915 MHz gear, and no ESP32-WROOM-32 build can ever do BadUSB.","released":"2026","aliases":["HaleHound","HaleHound-CYD","ESP32-DIV HaleHound Edition"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_karma":"yes","wifi_handshake_capture":"yes","wifi_wardriving":"addon","ble_scan":"yes","ble_advertise":"yes","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","ble_jam":"claimed","subghz_rx":"addon","subghz_tx":"addon","subghz_replay":"addon","subghz_bruteforce":"addon","subghz_rolling_code":"partial","subghz_amplified":"addon","nrf24_scan":"addon","nrf24_jam":"addon","mousejack":"addon","hf_1356_read":"addon","hf_1356_write":"addon","hf_1356_emulate":"addon","mifare_classic_attacks":"addon","lf_125khz_read":"no","detect_surveillance_cam":"yes","detect_drone":"yes","detect_skimmer":"yes","gps":"addon","sd_logging":"yes","usb_hid_inject":"no","ir_tx":"no"},"legal":{"risk_level":"high","notes":"This firmware ships jamming modules."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"high"}},{"id":"cyd-2432s028r-bare","hardware_id":"cyd-2432s028r","name":"ESP32 Cheap Yellow Display (ESP32-2432S028R)","firmware":"None (bare board)","firmware_kind":"n/a","vendor":"Generic - commonly labelled JCZN or Sunton, sold unbranded by many resellers","category":"wifi","subcategory":"esp32-platform-board","status":"available","price_usd":13.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flashing is trivial; getting anything past Wi-Fi and BLE means soldering modules onto a board with three genuinely free GPIOs.","build_effort":"flash-only","stealth":"overt","form_factor":"board","summary":"A $10-15 generic ESP32 development board with a 2.8-inch resistive touchscreen, microSD slot, RGB LED and speaker output, nicknamed the Cheap Yellow Display after its yellow PCB. It has become the default cheap platform for ESP32 security firmware: Bruce, GhostESP and HaleHound all ship builds for it, which makes it the honest price benchmark that every boutique handheld in this category should be compared against.","honest_take":"This is the value benchmark: a $10-15 board with a colour touchscreen running exactly the same firmware as $150-280 boutique devices. The catches are real, though. Only three GPIOs are genuinely free - 22, 27 and 35, and 35 is input-only - so every 'full build' bolting on CC1101, nRF24, PN532 and GPS is sharing the display's SPI bus and juggling pin conflicts. There is no battery and no charging circuit, so it is a desk toy until you add both. The touch is resistive, not capacitive. And the ESP32-WROOM-32 has no USB peripheral at all - the USB port goes through a CH340 UART bridge - so BadUSB is permanently impossible on this board, no matter what firmware you flash.","released":"2023","aliases":["CYD","Cheap Yellow Display","ESP32-2432S028R","JCZN CYD-2432S028","CYD2432S028R"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_handshake_capture":"yes","ble_scan":"yes","bt_classic":"yes","sd_logging":"yes","subghz_rx":"addon","subghz_tx":"addon","nrf24_scan":"addon","hf_1356_read":"addon","lf_125khz_read":"no","gps":"addon","usb_hid_inject":"no","ir_tx":"no","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"As a bare development board this is an ordinary electronics component, legal to own and import everywhere."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"n/a - hardware","app_store":"No - depends entirely on the firmware","abandoned_risk":"low"}},{"id":"marauder-double-barrel-5g-c5","hardware_id":"marauder-double-barrel-5g-c5","name":"ESP32 Marauder Double Barrel 5G - C5 version","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"HoneyHoneyTrading","category":"multitool","subcategory":"dual-marauder-combo","status":"available","price_usd":139.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Two independent Marauder UIs to learn rather than one; mixed customer reviews (1-5 stars) cite a real learning curve and documentation gaps.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"A bundle pairing a standalone ESP32 Marauder handheld (2.8in touchscreen, 800mAh battery, GPS, microSD) with a separate ESP32-C5 module that a Flipper Zero drives over GPIO for dual-band 2.4/5GHz Wi-Fi, plus a CC1101 for 433MHz sub-GHz on the module side. The two Marauder instances run independently and do not coordinate with each other in firmware - the pitch is literally running two single-tasking Marauder units side by side.","honest_take":"Read past the '5G' in the name - this is 5GHz Wi-Fi via the ESP32-C5's dual-band radio, not cellular 5G, and that ambiguity is exactly the kind of thing casual buyers get wrong. The underlying premise is honest about a real limitation: Marauder genuinely can only do one thing at a time on a single unit (you can't deauth and wardrive simultaneously), and 'Double Barrel' is two off-the-shelf Marauder targets - a handheld and a Flipper-controlled C5 module - sold as a kit rather than special firmware engineering to make them cooperate. You are paying for the convenience of buying both pieces and a case together; you could reach the same functional result from a standalone Marauder board plus a Flipper C5 accessory like the already-tracked Honey Honey Apex 5, for comparable or less money if you already own a Flipper. Mixed 1-to-5-star customer reviews citing documentation gaps and hardware issues suggest this specific bundle is not HoneyHoneyTrading's most polished product.","released":"2026","aliases":["Marauder Double Barrel 5G","Double Barrel C5"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"partial","wifi_evil_twin":"yes","wifi_beacon_spam":"yes","wifi_wardriving":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"unknown","subghz_rx":"yes","subghz_tx":"yes","subghz_external_antenna":"yes","subghz_amplified":"no","ble_scan":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","hf_1356_read":"no","ir_tx":"no","usb_hid_inject":"no","standalone_untethered":"partial"},"legal":{"risk_level":"medium","notes":"Standard Marauder legal profile - deauth and rogue-AP attacks against networks you don't own are unlawful interference in most jurisdictions (FCC rules in the US); sub-GHz transmission at 433MHz is subject to regional power/duty-cycle limits."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-04","app_store":"No","abandoned_risk":"medium"}},{"id":"marauder-mini-v3","hardware_id":"marauder-mini-v3","name":"ESP32 Marauder Mini v3","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"Just Call Me Koko LLC","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"out-of-stock","price_usd":95.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"5-way tactile switch menu; arrives flashed. Smaller screen makes the denser views harder to read than the v8.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"The pocket-sized official Marauder. Same ESP32-C5 dual-band radio and same firmware as the v8, in a roughly 2.5 x 1.5 inch package with a small screen, 5-way switch, GPS and microSD. Aimed at being carried every day rather than sat on a bench.","honest_take":"It is the v8's radio and firmware minus the touchscreen and minus the 18650, for $5 less - the value is the form factor, not the capability. The same caveats bite harder here: no sub-GHz, no NFC, no IR, and deauth that 802.11w/PMF and therefore WPA3 defeats outright. The tiny screen makes the channel analyser and packet views genuinely cramped, and with no battery in the box it is not actually pocketable until you buy one.","released":"2026","aliases":["Marauder Mini","Marauder Mini v3"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_deauth_5":"partial","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"yes","wifi_ap_mode":"yes","packet_capture":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","bt_classic":"no","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","detect_flipper":"yes","detect_skimmer":"yes","detect_pineapple":"yes","detect_pwnagotchi":"yes","detect_surveillance_cam":"partial","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","scriptable":"partial","standalone_untethered":"yes","subghz_rx":"no","hf_1356_read":"no","ir_tx":"no"},"legal":{"risk_level":"medium","notes":"Scanning and logging are broadly legal; transmitting deauth frames at networks you do not own is not, and the captive-portal credential capture is the feature most likely to cross into criminal territory."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No - monolithic firmware with a web installer and Flipper companion app","abandoned_risk":"low"}},{"id":"marauder-v6-1","hardware_id":"marauder-v6-1","name":"ESP32 Marauder v6.1","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"Just Call Me Koko LLC","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"out-of-stock","price_usd":85.5,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Touchscreen plus physical buttons.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"The touchscreen Marauder that preceded the v7 and v8. ESP32, 2.4GHz only, with a touch display, IP5306-based battery management, buttons, a NeoPixel, microSD, GPS and a temperature sensor. The v6.1 added GPS over the plain v6.","honest_take":"Two generations old and 2.4GHz only, which is the limitation that matters most today. The firmware still supports it, so it is not e-waste, but there is no reason to seek one out - the same firmware runs on a $20 M5StickC Plus2 with the same radio capability, and a current v8 adds 5 GHz that no amount of firmware can retrofit onto this board. The deauth feature is also increasingly moot: 802.11w/PMF defeats it, and WPA3 makes PMF mandatory, so it works only against older or misconfigured networks.","released":"2023","aliases":["Marauder v6.1","Marauder v6.2"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_wardriving":"yes","packet_capture":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_tracker_detect":"yes","detect_flipper":"yes","detect_pineapple":"yes","gps":"partial","sd_logging":"yes","standalone_untethered":"yes","subghz_rx":"no","hf_1356_read":"no"},"legal":{"risk_level":"medium","notes":"Scanning is broadly legal; deauthing networks you do not own and harvesting portal credentials are not."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"marauder-v7","hardware_id":"marauder-v7","name":"ESP32 Marauder v7","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"Just Call Me Koko LLC","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"out-of-stock","price_usd":120.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Physical keyboard plus buttons; menu-driven.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"The generation before the v8: an ESP32 with a full screen, a small physical keyboard, battery, GPS, SD and a temperature sensor. It is 2.4GHz only - the dual-band C5 did not arrive until the v8 and Mini v3. Still fully supported by current firmware.","honest_take":"Buying one secondhand today means paying for a board whose radio is a generation behind, and the 5 GHz gap is the one that actually matters now that most real networks have a 5 GHz side the v7 cannot even see. It is not obsolete - the firmware still gets releases - but a $20 M5StickC Plus2 runs the same 2.4GHz feature set, so the v7's value is the keyboard, the GPS and the battery rather than anything the radio does. And the deauth everyone buys these for is on borrowed time regardless of generation: 802.11w/PMF blocks it outright, and WPA3 makes PMF mandatory.","released":"2024","aliases":["Marauder v7","Marauder v7.1"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"yes","packet_capture":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_tracker_detect":"yes","detect_flipper":"yes","detect_pineapple":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","standalone_untethered":"yes","subghz_rx":"no","hf_1356_read":"no"},"legal":{"risk_level":"medium","notes":"Same position as the rest of the line: scanning is generally fine, transmitting deauth at networks you do not own is not, and harvesting credentials through the portal is the sharpest legal edge."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"marauder-v8","hardware_id":"marauder-v8","name":"ESP32 Marauder v8","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"Just Call Me Koko LLC","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"out-of-stock","price_usd":100.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Touchscreen menu, no command line needed for the common functions; it arrives flashed and working.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"The current flagship official Marauder board: an ESP32-C5 with a 2.8-inch touchscreen, GPS, microSD and dual SMA antenna connectors. The C5 makes it the first Marauder that can see and transmit on 5 GHz as well as 2.4 GHz. It is a Wi-Fi and BLE analysis and attack tool, and nothing else.","honest_take":"This is a Wi-Fi/BLE box, not a Flipper competitor - there is no sub-GHz, no NFC, no RFID and no IR, so the ~30% of Flipper use cases that involve gates, badges and TV remotes are simply absent. Its headline deauth attack only works against unprotected management frames: 802.11w/PMF stops it dead, and WPA3 makes PMF mandatory, so on any modern network deauth increasingly does nothing. The firmware is free and MIT-licensed and runs on a $20 M5StickC Plus2, so what you are paying $100 for is the C5's 5 GHz radio, the touchscreen, the GPS and the antenna connectors - which is a fair deal, but understand that is what you are buying.","released":"2026","aliases":["Marauder v8","ESP32 Marauder V8"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_deauth_5":"partial","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"unknown","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"yes","wifi_ap_mode":"yes","packet_capture":"yes","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","bt_classic":"no","ble_sniff":"partial","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","findmy_track":"partial","detect_flipper":"yes","detect_airtag":"yes","detect_skimmer":"yes","detect_pineapple":"yes","detect_pwnagotchi":"yes","detect_surveillance_cam":"partial","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","scriptable":"partial","standalone_untethered":"yes","subghz_rx":"no","hf_1356_read":"no","lf_125khz_read":"no","ir_tx":"no","usb_hid_inject":"no"},"legal":{"risk_level":"medium","notes":"Owning and using it to scan and log is legal in most places."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No - single monolithic firmware, but a web-based Marauder Installer and a Flipper Zero companion app exist","abandoned_risk":"low"}},{"id":"esp32-network-toolbox","hardware_id":"esp32-network-toolbox-klhnikov","name":"ESP32 Network Toolbox","firmware":"Custom","firmware_kind":"third-party-product","vendor":"Klhnikov's","category":"wifi","subcategory":"wifi-bluetooth-multitool","status":"out-of-stock","price_usd":50.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Needs either the Android app or a PC running Python3 with the published control scripts; there's no on-device screen or buttons.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An ESP32 board in a 3D-printed case, sold with an Android app and PC Python scripts for Wi-Fi scanning/sniffing, deauthentication, an evil-twin captive portal, network mapping, and Bluetooth scanning, exporting results as PCAP/CSV/JSON. It has been listed as out of stock on Tindie continuously since August 2023.","honest_take":"Everything this claims to do - Wi-Fi promiscuous sniffing, deauth, evil twin, BLE scanning - is within reach of any ESP32 dev board running one of several free, open-source projects (e.g. risinek/esp32-wifi-penetration-tool for the deauth/evil-twin side). The $50 here mostly buys the 3D-printed case, a cable, and the maker's own closed firmware plus his Android app - and unlike the open projects it resembles, you can't audit or rebuild that firmware, since only the PC control scripts (not the on-device firmware) are public. That trade-off is moot for new buyers anyway: the listing has been sold out for more than three years with no confirmed restock, longer than most single-maker Tindie listings survive before quietly dying. The exact ESP32 variant inside was never published, so claims can't be checked against known chip capabilities.","aliases":[],"capabilities":{"wifi_scan_24":"claimed","wifi_monitor_mode":"claimed","wifi_injection":"claimed","wifi_deauth_24":"claimed","wifi_evil_twin":"claimed","wifi_captive_portal":"claimed","wifi_handshake_capture":"claimed","packet_capture":"claimed","ble_scan":"claimed","bt_classic":"unknown","scriptable":"yes","app_store":"yes","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"The board itself is unrestricted."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"2026-01","app_store":"Yes - official Android app only, no iOS","abandoned_risk":"high"}},{"id":"esp32-wardriver-pro","hardware_id":"esp32-wardriver-pro","name":"ESP32 Wardriver Pro","firmware":"esp32-gps-wifi-wigle","firmware_kind":"diy","vendor":"dkyazzentwatwa (open-source project, not sold)","category":"wardriving","subcategory":"gps-wifi-logger","status":"diy-only","price_usd":25.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Breadboard or perfboard wiring of four modules to documented GPIOs, then arduino-cli compilation with a few named libraries - more involved than flashing a pre-built board, less involved than designing a PCB.","build_effort":"full-diy","stealth":"discreet","form_factor":"board","summary":"ESP32 Wardriver Pro is a solo-maintained, deliberately minimal wardriving logger: an ESP32 DevKit board, a GPS module, a small OLED and a microSD card, wired together and flashed with an Arduino sketch that scans Wi-Fi, waits for a GPS fix, and writes properly-formatted WigleWifi-1.4 CSV rows to the SD card. The README states outright that it does not deauthenticate, join networks, inject packets, or attack anything - it only watches and logs.","honest_take":"The 'passive' framing is honest about intent but worth reading precisely: the underlying WiFi.scanNetworks() call is Arduino's standard active station-mode scan, which transmits 802.11 probe requests on every channel to elicit responses - the same thing your phone does constantly, not a promiscuous-mode radio that only listens. What 'passive' actually means here is narrower and true: no deauth, no packet injection, no joining networks, confirmed directly in the source (WifiScanner.cpp calls nothing but WiFi.scanNetworks). The upside of that narrow scope is real: this is a solo hobby project (40 stars) that still shipped exactly what it says it does - a genuine WigleWifi-1.4 CSV with a correct header - unlike wardriver3000 (also in this database), whose custom PCB and README both promise Wigle compatibility that its own firmware doesn't deliver. Against JCMK's actively-maintained 'C5 Wardriver' (dual-band 2.4+5GHz, BLE, also correctly WiGLE-formatted, from the same team behind ESP32 Marauder), this is the honest budget pick if you specifically want 2.4GHz-only passive logging and don't mind wiring your own board from loose modules - the C5 Wardriver adds 5GHz and BLE for not much more cost and effort, and has a larger, more active community behind it.","released":"2024","aliases":["esp32-gps-wifi-wigle"],"capabilities":{"wifi_scan_24":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","wifi_wardriving":"yes","wifi_deauth_24":"no","wifi_injection":"no","wifi_ap_mode":"no","ble_scan":"partial","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"Passive network discovery and GPS logging is legal essentially everywhere - it's the same 802."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2026-05","app_store":"No","abandoned_risk":"low"}},{"id":"esp32-div-v1","hardware_id":"esp32-div-v1","name":"ESP32-DIV v1","firmware":"ESP32-DIV (official)","firmware_kind":"diy","vendor":"CiferTech (open-source project, nothing sold assembled)","category":"multitool","subcategory":"diy-rf-multitool","status":"diy-only","price_usd":65.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Two custom PCBs with fine-pitch SMD parts plus three stacked RF modules that must be powered without browning out the ESP32 - you must be comfortable with SMD soldering, reading a schematic, and debugging a board that will not enumerate.","build_effort":"soldering","stealth":"overt","form_factor":"handheld","summary":"A handheld open-source wireless toolkit: a plain ESP32 driving a 2.8in touchscreen, with a plug-on shield carrying three nRF24L01+ modules, a CC1101 sub-GHz transceiver and an IR transceiver. Wi-Fi and BLE come from the ESP32's own radio, 2.4GHz ShockBurst and MouseJack from the nRF24s, 300-928MHz replay from the CC1101. It is a project you build, not a product you buy.","honest_take":"Genuinely capable for the parts cost, but the author's own 'better than Flipper' framing is marketing. All Wi-Fi is 2.4GHz only; deauth works only against WPA2 networks that have not enabled 802.11w/PMF, and WPA3 mandates PMF so it is immune. The RFID/NFC and GPS menus in the feature list need a PN532 and a GNSS module that are not on the published BOM - you add them yourself. And if you would rather not solder two custom PCBs, the same firmware has a build for the ~$12 ESP32-2432S028 'CYD' board, which with a $15-25 RF companion hat gets you most of this for a third of the work.","released":"2024","aliases":["ESP32DIV","ESP32 DIV","CiferTech ESP32-DIV"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"partial","wifi_deauth_5":"no","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_karma":"yes","wifi_probe_sniff":"yes","wifi_monitor_mode":"partial","wifi_handshake_capture":"unknown","wifi_wardriving":"addon","wifi_ap_mode":"yes","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"unknown","ble_hid":"yes","ble_jam":"partial","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","findmy_track":"partial","detect_skimmer":"partial","detect_generic_wifi":"yes","nrf24_scan":"yes","nrf24_jam":"partial","mousejack":"yes","zigbee":"no","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_bruteforce":"yes","subghz_external_antenna":"yes","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","lf_125khz_read":"no","hf_1356_read":"addon","hf_1356_emulate":"addon","mifare_classic_attacks":"partial","gps":"addon","sd_logging":"yes","scriptable":"partial","standalone_untethered":"yes","usb_hid_inject":"no"},"legal":{"risk_level":"high","notes":"Building and owning the board is generally legal; several of its headline functions are not."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No - monolithic firmware, no plugin or app system","abandoned_risk":"low"}},{"id":"esp32-div-v2","hardware_id":"esp32-div-v2","name":"ESP32-DIV v2","firmware":"ESP32-DIV (official)","firmware_kind":"diy","vendor":"CiferTech (open-source project, nothing sold assembled)","category":"multitool","subcategory":"diy-rf-multitool","status":"diy-only","price_usd":80.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"The same two-PCB SMD build as v1 plus pogo-pin alignment between main board and shield; you must be comfortable flashing, reading a schematic, and diagnosing brownouts when three nRF24s transmit at once.","build_effort":"soldering","stealth":"overt","form_factor":"handheld","summary":"The second-generation ESP32-DIV: an ESP32-S3 main board with a 2.8in touchscreen, IP5306 battery management, microSD and four status NeoPixels, plus a pogo-pin stacking shield carrying three nRF24L01+ modules, a CC1101 sub-GHz transceiver and an IR transceiver. Moving to the S3 fixed the pin conflicts that constrained v1 and adds a native USB peripheral. Still a build-it-yourself project.","honest_take":"The author's blog headline is 'I built something better than Flipper', and that is the claim to be sceptical about. It has more radios than a Flipper for less money, but it is a hand-soldered two-board project with no case, no app ecosystem, no NFC or GPS unless you bolt them on, and no 5GHz - and the Flipper's value was always polish and the software catalogue, not the silicon. Buy the comparison on radios; do not buy it on usability. If you want most of these features without a soldering iron, the same firmware runs on the ~$12 ESP32-2432S028 'CYD' board plus a $15-25 RF hat.","released":"2026","aliases":["ESP32DIV v2","ESP32-DIV V2","CiferTech ESP32-DIV v2"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"partial","wifi_deauth_5":"no","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_karma":"yes","wifi_probe_sniff":"yes","wifi_monitor_mode":"partial","wifi_handshake_capture":"unknown","wifi_wardriving":"addon","wifi_ap_mode":"yes","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"unknown","ble_hid":"yes","ble_jam":"partial","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","findmy_track":"partial","detect_skimmer":"partial","detect_generic_wifi":"yes","nrf24_scan":"yes","nrf24_jam":"partial","mousejack":"yes","zigbee":"no","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_bruteforce":"yes","subghz_external_antenna":"yes","subghz_amplified":"unknown","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","hf_1356_read":"addon","hf_1356_emulate":"addon","mifare_classic_attacks":"partial","lf_125khz_read":"no","gps":"addon","sd_logging":"yes","scriptable":"partial","standalone_untethered":"yes","usb_hid_inject":"unknown"},"legal":{"risk_level":"high","notes":"Owning the board is generally lawful; several functions are not."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No - single monolithic firmware image","abandoned_risk":"low"}},{"id":"esp32-mdk-portapack-h4m","hardware_id":"esp32-mdk-portapack-h4m","name":"ESP32-MDK for PortaPack H4M","firmware":"htotoo/ESP32-Portapack","firmware_kind":"community","vendor":"OpenSourceSDRLab","category":"accessory","subcategory":"sdr-addon-module","status":"available","price_usd":45.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Requires already owning and running a HackRF + PortaPack H4M with a Mayhem build that has the external-module API, plus flashing separate ESP32-S3 firmware yourself via ESP-IDF - not a beginner add-on.","build_effort":"flash-only","stealth":"overt","form_factor":"hat-shield","summary":"A small ESP32-S3-based expansion board that attaches to a HackRF + PortaPack H4M rig over UART/I2C/USB, adding a second, independent Wi-Fi/BLE radio (the HackRF/PortaPack itself has no Wi-Fi) to an SDR platform that otherwise only receives/transmits via HackRF's wideband RF front end. It is an accessory for the existing 'HackRF + PortaPack H4M' device already tracked in this database, not a standalone gadget - it does nothing without that host.","honest_take":"This is fundamentally 'an ESP32 dev board in a matching case' - the interesting part is entirely in whichever firmware you flash onto it, and the two options found are not equivalent: the official 'mayhem-mdk' reference firmware from the PortaPack Mayhem project only documents a single UART-passthrough demo app, while the real Wi-Fi functionality (an SSID-spam/spoofer app, plus IR-receive and a Meshtastic-related bridge) comes from a separate, single-maintainer community project (htotoo/ESP32-Portapack) that is explicitly described by its own author as early-stage. Marketing this as 'enable[s] WiFi applications' is accurate but easy to over-read: it does not turn the HackRF into a Wi-Fi attack tool in the Marauder/Flipper sense - deauth was not found documented anywhere in either firmware's app list, only beacon/SSID spam. You also need the PortaPack side running a Mayhem build recent enough to include the external-module API (PR #2290) or the app simply won't appear in the menu, which is a real trap for anyone still on an older Mayhem build or the original havoc fork. On price: the SKU 'OSL-ESP32' and matching product description point to Hacker Warehouse reselling OpenSourceSDRLab's own board, which OpenSourceSDRLab sells directly for as little as $35 on sale - so part of the $45 here is Hacker Warehouse's convenience/bundling markup, not unique hardware.","aliases":["OpenSourceSDRLab ESP32 MDK","Mayhem MDK","ESP32-Portapack module"],"capabilities":{"wifi_scan_24":"claimed","wifi_scan_5":"no","wifi_deauth_24":"no","wifi_beacon_spam":"yes","ir_rx":"partial","uart":"yes","i2c":"yes","ble_scan":"claimed","bt_classic":"no","standalone_untethered":"no","scriptable":"no","mesh_lora":"no"},"legal":{"risk_level":"low","notes":"The ESP32-S3 module itself only transmits standard consumer Wi-Fi/BLE, which is legal to own and use like any other Wi-Fi device in most countries."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":null,"app_store":"No formal app store - each app is a firmware build you flash yourself; a Utilities-menu app only appears once the PortaPack side is running the external-module-API version of Mayhem","abandoned_risk":"medium"}},{"id":"esp32jtag-ez32","hardware_id":"esp32jtag","name":"ESP32JTAG","firmware":"esp32jtag_firmware (stock)","firmware_kind":"stock","vendor":"EZ32 Inc.","category":"hardware-debug","subcategory":"jtag-swd-probe","status":"available","price_usd":139.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The web UI removes driver hassle, but you still need to understand JTAG/SWD, target voltage selection, and (for the FPGA/XVC side) an FPGA toolchain - not a first hardware-debug tool.","build_effort":"assembled","stealth":"overt","form_factor":"box","summary":"ESP32JTAG is a wireless debug probe from Canadian startup EZ32 Inc.: an ESP32-S3 running open-source firmware (BlackMagic Probe GDB server + CMSIS-DAP via CherryDAP) paired with a small Lattice iCE40UP5K FPGA that does the high-speed signal capture for a 16-channel logic analyzer and FPGA bitstream programming (Xilinx Virtual Cable). Everything - JTAG/SWD debugging, the logic analyzer, a UART terminal, and firmware updates - is driven through a built-in HTTPS web server reached over Wi-Fi, so there's no USB driver install.","honest_take":"Wireless JTAG is a real engineering tradeoff, not a free upgrade: Wi-Fi adds latency and jitter a wired USB-HS probe (hs-probe, a J-Link, or even a $15 clone) doesn't have, and for tight real-time debugging that shows up as slower round-trips no matter how good the raw throughput numbers look. The vendor's own comparison table also lists 'Wi-Fi 6' connectivity, but the ESP32-S3's radio is 802.11 b/g/n (Wi-Fi 4) only - the silicon has no 802.11ax hardware, so that line is either a spec-sheet error or marketing inflation; treat the rest of that comparison table skeptically too. It's also a debug probe running an HTTPS web server on your Wi-Fi network with no documented authentication - on a shared or IoT-segment network that's an open control/flash surface for anyone who can reach its IP. The 16-channel/250MHz logic analyzer plus driver-free multi-tool angle is a genuinely strong pitch, since the iCE40UP5K FPGA is doing real work, this is not 'just an ESP32 in a case'. But for latency-sensitive production debugging, a wired probe is still the safer default.","released":"2026","aliases":["EZ32 ESP32JTAG"],"capabilities":{"uart":"yes","spi_flash_dump":"unknown","i2c":"no","jtag_swd":"yes","logic_analyzer":"yes","glitching":"no","web_ui":"yes","wifi_monitor_mode":"no","ble_scan":"no","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A Wi-Fi/BLE debug tool, not a transmitter aimed at attacking other networks - no different legally from any other Wi-Fi-enabled electronics."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"N/A - browser-based web UI, no app store","abandoned_risk":"medium"}},{"id":"esp8266-deauther","hardware_id":"esp8266-deauther","name":"ESP8266 Deauther","firmware":"ESP8266 Deauther","firmware_kind":"community","vendor":"Spacehuhn Technologies (Stefan Kremser)","category":"wifi","subcategory":"wifi-deauth-firmware","status":"diy-only","price_usd":6.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Flash-and-go on a $6 board over USB; no soldering for basic use, though the optional OLED/TFT display and button add-ons are a separate wiring step.","build_effort":"flash-only","stealth":"discreet","form_factor":"board","summary":"The firmware that effectively founded the ESP-based Wi-Fi attack category: deauthentication flooding, beacon/SSID spam, and Wi-Fi scanning on a sub-$10 ESP8266 board, with a web UI and an optional physical display. It has no Bluetooth, no 5GHz, and no packet injection beyond management-frame attacks - 2017-era ESP8266 capability, not the newer ESP32/C5 feature set found elsewhere in this batch.","honest_take":"This is the firmware essentially every other ESP-based deauther and Marauder-style tool descends from conceptually, and it is still maintained nearly a decade later - genuinely unusual longevity for this category. But do not confuse 'foundational' with 'capable': the ESP8266 has no Bluetooth radio at all, no 5GHz, and PMF/802.11w defeats its deauth exactly as it defeats every newer device's deauth, on any modern access point. If you want the same basic idea with a screen, GPS, BLE and an actively maintained community, ESP32 Marauder (already tracked at multiple price points from $20 up) picked up where this project left off and is the better buy for anything built after about 2019.","aliases":["Spacehuhn Deauther","ESP8266 Deauther v3"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"partial","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_deauth_5":"no","wifi_beacon_spam":"yes","wifi_evil_twin":"no","wifi_captive_portal":"no","wifi_handshake_capture":"no","wifi_pmkid":"no","wifi_ap_mode":"yes","wifi_wardriving":"no","ble_scan":"no","bt_classic":"no","usb_hid_inject":"no","subghz_rx":"no","hf_1356_read":"no","ir_tx":"no","web_ui":"yes"},"legal":{"risk_level":"medium","notes":"Deauthenticating networks you do not own is a computer-misuse/interference offence in most countries, and unlawful under FCC rules in the US regardless of intent."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2024-08","app_store":"No","abandoned_risk":"medium"}},{"id":"espboy-diy","hardware_id":"espboy-diy","name":"ESPboy:DIY","firmware":"Custom","firmware_kind":"stock","vendor":"ESPboy (Roman S.)","category":"multitool","subcategory":"retro-handheld-with-rf-modules","status":"out-of-stock","price_usd":79.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Arrives assembled and preloaded with 30+ games, but the security-relevant capability (RFID/NFC, sub-GHz, iButton, BadUSB) requires buying separate modules and, for some, the right firmware sketch flashed via Arduino IDE.","build_effort":"assembly","stealth":"discreet","form_factor":"handheld","summary":"A retro-gaming-styled ESP8266 handheld (1.44in 128x128 color TFT, 8 buttons, speaker, RGB LED) built around a standardized expansion connector. On its own it is a Little Game Engine console; plugging in separate modules adds Wi-Fi attacks, RFID/NFC read/write/clone/emulate, iButton storage, 433MHz garage/barrier control, GPS, LoRa, and BadUSB-style payloads. Fully open source and OSHWA-certified.","honest_take":"The gaming branding is doing real work to disguise a genuinely capable multi-protocol platform, and that cuts both ways. As a stealth angle, nothing about this looks like a hacking tool, which is a real advantage over an overtly 'pentest' branded handheld. But 'multi-protocol capability bolted onto a retro-gaming platform' undersells how much extra buying is required: the base $79 unit does none of the RF/RFID/BadUSB tricks by itself - every one of those needs its own separate module purchase, and the ESP8266 at the core has no Bluetooth and no native USB, so any 'BadUSB' claim for this platform almost certainly means a separate USB-capable companion board rather than the ESP8266 itself emulating a keyboard. It is the most genuinely open-source device in this whole batch (OSHWA RU000001, full schematics and code per module on GitHub), which deserves real credit - but only 1 unit was in stock at last check, so availability is a live concern.","aliases":["ESPboy"],"capabilities":{"games":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"claimed","hf_1356_read":"addon","hf_1356_write":"addon","hf_1356_emulate":"addon","mifare_classic_attacks":"addon","ibutton_1wire":"addon","subghz_rx":"addon","subghz_tx":"addon","nrf24_scan":"addon","gps":"addon","ir_tx":"addon","usb_hid_inject":"unknown","bt_classic":"no","ble_scan":"no","scriptable":"yes","app_store":"no"},"legal":{"risk_level":"medium","notes":"Legal exposure scales with which modules are bought and used - sub-GHz transmission, Wi-Fi deauth and RFID cloning each carry separate exposure depending on jurisdiction and target."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"espkey","hardware_id":"espkey","name":"ESPKey","firmware":"ESPKey (Octosavvi)","firmware_kind":"stock","vendor":"Octosavvi (sold via Red Team Tools)","category":"network-implant","subcategory":"wiegand-implant","status":"available","price_usd":79.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The electronics are three wires and a web page. The skill is entirely in the physical job: getting a reader off a wall without triggering a tamper switch, identifying the right conductors, and getting out.","build_effort":"assembled","stealth":"implant","form_factor":"board","summary":"A small ESP8266 board that sits behind a card reader on the Wiegand wires between the reader and the door controller. It records every credential presented, up to a vendor-claimed 80,000 bitstreams in non-volatile memory, and will replay or inject any of them on demand from a web interface. It can also act as a standalone door controller, which makes it a useful test rig.","honest_take":"It is an ESP8266 wired to two data lines, and that is enough to defeat almost every access control system in service, because Wiegand is a 1980s protocol with no authentication, no encryption and no replay protection. The card technology is completely irrelevant: a US$2,000 SEOS reader hands the controller the same naked bit string a US$40 Prox reader does, and a fingerprint scanner does too. That indifference is the entire point, and it is why this US$79 board sidesteps every crypto argument in the rest of this batch. The real barrier is physical - you have to unscrew a reader from a wall, often outdoors, often on camera, often with a tamper switch behind it - and no amount of firmware helps with that. Two things to know before deploying one: the firmware's last commit was January 2022, and the default AP SSID and passphrase are published in the source, so an ESPKey left in place is itself a finding for the next person who wardrives the car park. Change them. Mitigation on the defensive side is OSDP with Secure Channel, not a better reader.","aliases":["ESP Key","ESP RFID Tool","Wiegand sniffer","ESPKey Wiegand Interception Tool"],"capabilities":{"lf_125khz_read":"no","hf_1356_read":"no","web_ui":"yes","wifi_ap_mode":"yes","sd_logging":"partial","standalone_untethered":"yes","scriptable":"partial"},"legal":{"risk_level":"high","notes":"Installing one requires opening someone's access control hardware, and using one means capturing other people's credentials and then replaying them to open a door."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2022-01","app_store":"No","abandoned_risk":"medium"}},{"id":"evil-crow-cable","hardware_id":"evil-crow-cable","name":"Evil Crow Cable","firmware":"BadUSB-Cable (ATtiny85)","firmware_kind":"diy","vendor":"AprilBrother (manufacturing/PCB); design by Joel Serna and Ernesto Sanchez","category":"usb-hid","subcategory":"badusb-cable","status":"out-of-stock","price_usd":12.5,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Simple keystroke-injection cable; editing the payload needs the Arduino ATtiny85 toolchain.","build_effort":"assembled","stealth":"covert","form_factor":"cable","summary":"The base model in AprilBrother's Evil Crow Cable line: an ATtiny85-based BadUSB built into a working USB cable, with the data lines enabled and no wireless hardware. It is the entry-level, fixed-payload sibling of the ESP32-S3/Wi-Fi-equipped Evil Crow Cable Wind, which is already in this database as a separate, more capable product.","honest_take":"Checked against Evil Crow Cable Wind (already tracked here): this is genuinely different hardware, not a rebrand - Wind runs an ESP32-S3 or similar with Wi-Fi and a web control panel for remote-triggered, in-field payload swapping; this base Cable is a plain ATtiny85 with no wireless and no on-device script storage, at roughly half Wind's price. That's a fair trade if you only need to drop one fixed payload and retrieve the cable later, but if you need to change the payload or trigger it without physically pulling the cable, you need Wind (or something like it), not this.","aliases":["EvilCrowCable (base, non-Wind)"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","scriptable":"yes","usb_mass_storage":"no","usb_ethernet_attack":"no","usb_keylogger":"no","usb_exfil":"no","hid_remote_trigger":"no","wifi_scan_24":"no","ble_scan":"no","web_ui":"no","standalone_untethered":"yes","cloud_c2":"no","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning and building it is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"evil-crow-cable-wind","hardware_id":"evil-crow-cable-wind","name":"Evil Crow Cable Wind","firmware":"EvilCrowCable-Wind","firmware_kind":"diy","vendor":"April Brother (manufacturer); design by Joel Serna Moreno","category":"usb-hid","subcategory":"badusb-cable","status":"available","price_usd":42.95,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Arrives pre-flashed. Set up a Wi-Fi hotspot on your phone, plug the cable in, open the web panel, write a payload. The concepts are the hard part, not the operation.","build_effort":"assembled","stealth":"covert","form_factor":"cable","summary":"A USB charging cable with an ESP32-S3 hidden inside it. Plugged into a computer it enumerates as a keyboard and types payloads; plugged into a phone it just charges, which is the point of the disguise. It connects out to a Wi-Fi access point you control (station mode, not hosting its own AP), and you drive it from a web panel that can detect the host OS, switch keyboard layout live, run a remote shell and plan AutoExec payloads per detected OS.","honest_take":"This is the most genuinely covert thing in the batch and should be treated accordingly - the whole design goal is that it is indistinguishable from a charging cable. Two practical notes. First, it is station mode, not AP mode: it joins a hotspot you provide, so it does not broadcast a suspicious network of its own, but it also does nothing until that hotspot is in range. Second, do not put this in a 'DIY' shopping list - the firmware is open but the hardware is a moulded cable made by April Brother, so you buy it, you do not build it. The CC BY-NC-SA licence also means non-commercial only.","released":"2024","aliases":["Evil Crow Wind","EvilCrowCable Wind","Evil Crow Cable"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","hid_remote_trigger":"yes","usb_mass_storage":"no","usb_exfil":"partial","wifi_ap_mode":"no","web_ui":"yes","scriptable":"yes","cloud_c2":"partial"},"legal":{"risk_level":"high","notes":"Owning it is legal in most places, but its entire design is concealment, and using it on a machine you do not own or lack written authorisation to test is unauthorised access under the CFAA in the US, the Computer Misuse Act in the UK and equivalents elsewhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-05","app_store":"No","abandoned_risk":"low"}},{"id":"usbarmyknife-evil-crow-cable-wind","hardware_id":"evil-crow-cable-wind","name":"Evil Crow Cable Wind (USB Army Knife)","firmware":"USB Army Knife","firmware_kind":"third-party-product","vendor":"April Brother (design by Joel Serna Moreno)","category":"usb-hid","subcategory":"malicious-cable","status":"available","price_usd":24.5,"price_is_estimate":false,"skill_level":"advanced","skill_note":"There is no screen and no obvious button - you enter flashing mode by holding a magnet against the active connector while plugging it in. Everything is done over Wi-Fi and DuckyScript.","build_effort":"flash-only","stealth":"covert","form_factor":"cable","summary":"A functioning USB charging cable with an ESP32-S3 hidden inside the connector shell. It presents as a keyboard to whatever it is plugged into, is controlled live over Wi-Fi, and looks exactly like the cable already on someone's desk. The most covert device in this batch by a wide margin.","honest_take":"The covertness is real and is the whole product - there is no screen, no LED and no accessible button, and it charges a phone normally, so it passes inspection in a way a USB stick does not. The trade-offs are equally real: only 8MB of flash with 1.5MB for payloads, no SD card, and the ESP32-S3 gets genuinely hot when hosting a Wi-Fi AP - hot enough that USB Army Knife implements thermal throttling and the author recommends joining an existing network instead. Note the licence is CC BY-NC-SA 4.0, a non-commercial Creative Commons licence, not an OSI-approved open-source licence, which is unusual for something described as open hardware. And buy direct if you can: the manufacturer sells it for $24.50 while regional resellers charge nearly double. The bundled Marauder fork brings Wi-Fi attacks along for the ride, but do not buy this for them: deauth is blocked by 802.11w/PMF and WPA3 makes PMF mandatory, and running the radio hard is exactly what overheats the cable.","released":"2024","aliases":["Evil Crow Cable Wind","EvilCrowCable-Wind","ECC Wind"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_mass_storage":"yes","usb_ethernet_attack":"yes","usb_exfil":"yes","hid_remote_trigger":"yes","wifi_ap_mode":"partial","wifi_scan_24":"yes","wifi_deauth_24":"yes","wifi_scan_5":"no","bt_classic":"no","web_ui":"yes","sd_logging":"no","scriptable":"yes","standalone_untethered":"no","subghz_rx":"no","hf_1356_read":"no"},"legal":{"risk_level":"high","notes":"The highest-risk item in this batch, because covertness is its design goal rather than a side effect."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-02","app_store":"No - DuckyScript payloads","abandoned_risk":"low"}},{"id":"evil-crow-rf-v2","hardware_id":"evil-crow-rf-v2","name":"Evil Crow RF V2","firmware":"EvilCrowRF-V2","firmware_kind":"diy","vendor":"April Brother (manufacturer); design by Joel Serna Moreno","category":"subghz","subcategory":"dual-cc1101-rf-tool","status":"available","price_usd":52.95,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Sold assembled and driven from a browser, but sub-GHz work itself demands you understand modulation, bit rate and frequency - the tool will happily let you transmit garbage.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A sub-GHz research board: an ESP32 with two independent CC1101 transceivers and one nRF24L01, driven entirely from a web panel over its own Wi-Fi. The two CC1101s are the point - they can receive and transmit on different frequencies at the same time, which single-radio tools cannot do, and that opens up jamming-plus-capture and other two-frequency techniques. Captures can be exported for analysis in Universal Radio Hacker.","honest_take":"The dual-CC1101 design is a genuine capability that a Flipper Zero does not have, and it is why this board still matters in 2026 - simultaneous transmit and receive on two different sub-GHz frequencies is what rolling-code capture-and-replay research actually requires. Two caveats. First, the board gives you the radio; it does not give you a working rollback attack - the separate ECRFv2-RollBack and Kaiju repos exist precisely because that is extra work, and those repos have not been touched since 2022-2023. Second, this is not really DIY: the hardware is manufactured by April Brother and the gerbers are not published, so despite the open CC-BY-4.0 firmware, you buy it. Maintenance is steady rather than energetic - last push October 2025, with the author's attention now largely on the Evil Crow Cable line.","released":"2022","aliases":["EvilCrow RF V2","Evil Crow RF","ECRF v2"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"partial","subghz_bruteforce":"unknown","subghz_external_antenna":"yes","sdr_rx":"no","nrf24_scan":"yes","mousejack":"yes","web_ui":"yes","sd_logging":"yes","wifi_ap_mode":"yes","standalone_untethered":"partial","ir_tx":"no","hf_1356_read":"no"},"legal":{"risk_level":"high","notes":"Owning it is legal in most places."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"n/a - no tagged releases; last code push 2025-10","app_store":"No, but a small ecosystem of add-on projects exists (rollback, Kaiju, Tesla charge-port)","abandoned_risk":"medium"}},{"id":"evilapplejuice-esp32","hardware_id":"generic-esp32-evilapplejuice","name":"EvilAppleJuice ESP32","firmware":"EvilAppleJuice-ESP32","firmware_kind":"community","vendor":"ckcr4lyf (open source project)","category":"bluetooth","subcategory":"ble-spam-firmware","status":"diy-only","price_usd":8.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"PlatformIO or Arduino IDE flash onto a generic board; no soldering, no case.","build_effort":"flash-only","stealth":"covert","form_factor":"board","summary":"Open-source firmware that spams spoofed BLE advertisements mimicking Apple's Continuity proximity-pairing protocol, triggering repeated fake AirPods/device-setup notification popups on nearby iPhones and iPads. It broadcasts 29 device-type adverts across 3 formats with randomized MAC addresses; with randomization tuned up it can produce a new notification on a target phone as fast as the previous one is dismissed.","honest_take":"This is advertising-only - it broadcasts BLE packets, it does not scan or listen to anything, so calling it a 'sniffer' or a general BLE attack tool would be wrong. It's also iOS-specific and purely an annoyance/social-engineering vector: it cannot access data, install anything or bypass a lock screen, it just floods the Continuity protocol's UI with fake pairing prompts (the author notes opening the keyboard or camera app suppresses the popups). It runs on any $5-10 generic ESP32 - there's no proprietary hardware here, the $0 firmware is genuinely the whole product, and a Flipper Zero's WiFi Dev Board or any ESP32 add-on already in this database can run it just as well.","released":"2024","aliases":["EvilAppleJuice","iOS BLE Proximity Attack"],"capabilities":{"ble_advertise":"yes","ble_scan":"no","ble_sniff":"no","ble_spam_apple":"yes","ble_spam_android":"no","ble_spam_samsung":"no","ble_spam_swift_pair":"no","ble_jam":"no","ble_hid":"no","bt_classic":"no","findmy_track":"no","scriptable":"yes","standalone_untethered":"partial"},"legal":{"risk_level":"medium","notes":"Broadcasting BLE advertisements is not itself illegal in most places (unlicensed 2."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-06","app_store":"No","abandoned_risk":"low"}},{"id":"evilcrow-keylogger","hardware_id":"evilcrow-keylogger","name":"EvilCrow-Keylogger","vendor":"Joel Serna & Ernesto Sánchez; PCB manufactured and distributed by April Brother","category":"usb-hid","subcategory":"hardware-keylogger","status":"available","price_usd":35.9,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-play for basic logging; the ATmega32U4 and ESP32-PICO firmware can be re-flashed by the user for custom builds.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"An open-hardware inline USB keylogger combining an ATmega32U4 (native-USB HID device to the target PC, driven via the Arduino Lilypad USB bootloader) with a MAX3421E USB host controller to read the attached keyboard, an ESP32-PICO for WiFi log access, and a microSD slot for onboard backup logging. Sold via multiple regional resellers (AliExpress, Tindie, EU/UK/Mexico distributors) with fully open firmware and hardware design (CC-BY-4.0).","honest_take":"This is a genuine dual-USB-role design — MAX3421E reads the physical keyboard on the device's host port, and the ATmega32U4's own native USB (with the Lilypad bootloader specifically used for HID emulation) re-presents those keystrokes to the downstream target PC — so the 'inline passthrough' framing in reseller listings checks out against the actual hardware, unlike some competitors that leave this ambiguous. It logs and forwards; it does not inject scripted payloads or emulate an independent HID attack device the way the Masterkey does, so don't buy this expecting Rubber-Ducky-style scripting. The GitHub README is upfront that 'some keys or modifiers have not been implemented' across the 11 supported keyboard layouts — expect occasional dropped or misread keys, especially with less common layouts, rather than a flawless capture rate. Actively maintained (pushed January 2026) which is unusual for this category — most competitors here are dormant.","released":"2020","aliases":["Evil Crow Keylogger"],"capabilities":{"usb_keylogger":"yes","usb_hid_inject":"no","hid_remote_trigger":"no","usb_exfil":"yes","wifi_ap_mode":"yes","usb_mass_storage":"no","scriptable":"yes","standalone_untethered":"no","sd_logging":"yes","ble_scan":"no"},"legal":{"risk_level":"high","notes":"Owning the hardware is generally legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-01","app_store":"No","abandoned_risk":"low"}},{"id":"evilduck-s3","hardware_id":"evilduck-s3","name":"EvilDuck S3","firmware":"EvilDuck S3","firmware_kind":"diy","vendor":"cifertech (open source; no assembled unit sold)","category":"usb-hid","subcategory":"badusb-wifi","status":"diy-only","price_usd":10.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flash-only if using a stock ESP32-S3 dev board; some builds add a WS2812 LED and voltage regulator that need soldering.","build_effort":"flash-only","stealth":"covert","form_factor":"usb-stick","summary":"The current-generation EvilDuck: an ESP32-S3 doing both native USB HID and Wi-Fi on one chip, with a browser-based control panel for uploading, storing, and remotely triggering DuckyScript-style payloads. Same open-source project as EvilDuck SD, but a different board and a materially different feature set (wireless, multi-payload, remote trigger vs SD-only, single active script).","honest_take":"This is 'ESP32-S3 doing the real work' in the same vein as WiFi Duck and the ESP32-S3 side of Evil Crow Cable Wind - a single cheap SoC handling both HID and Wi-Fi, with a web UI on top. If you already own any ESP32-S3 dev board, the marginal cost of this capability is just flashing new firmware; the value here is entirely the open-source software (payload storage, remote trigger, autorun) rather than unique hardware. Compare directly against commercial devices like the O.MG Cable or Evil Crow Cable Wind before buying dedicated hardware for this - the silicon doing the work is the same class of chip.","released":"2026-06","aliases":["EvilDuck (Gen 2/3)"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","web_ui":"yes","hid_remote_trigger":"yes","scriptable":"yes","wifi_ap_mode":"claimed","usb_mass_storage":"no","usb_ethernet_attack":"no","usb_keylogger":"no","usb_exfil":"unknown","cloud_c2":"no","ble_scan":"no","app_store":"no","standalone_untethered":"yes","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"Building and owning it is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-06-08","app_store":"No","abandoned_risk":"low"}},{"id":"evilduck-sd","hardware_id":"evilduck-sd","name":"EvilDuck SD","firmware":"EvilDuck","firmware_kind":"diy","vendor":"cifertech (open source; no assembled unit sold)","category":"usb-hid","subcategory":"badusb-sd","status":"diy-only","price_usd":10.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Requires wiring an SD breakout to specific Arduino Micro pins and flashing the sketch yourself; no vendor-assembled option.","build_effort":"soldering","stealth":"covert","form_factor":"board","summary":"The original EvilDuck: an Arduino Micro (ATmega32U4) running a Rubber Ducky-style script interpreter that reads a script.txt file off a microSD card and types it as a real, hardware-native USB keyboard on plug-in, with hot-swap detection for changing the SD card between drops. Open source, DIY-only, no vendor sells an assembled unit.","honest_take":"Because the ATmega32U4 has real USB hardware (unlike the ATtiny85 sticks/cables in this same batch), this one gets a genuinely native, low-latency USB HID stack rather than a bit-banged V-USB implementation - a real technical edge over cheaper ATtiny85 BadUSB devices, and functionally very close to the original USB Rubber Ducky's approach (SD card holds the script, no wireless). The catch is it is DIY-only: there's no case, no vendor support, and you're sourcing and wiring an Arduino Micro clone and SD breakout yourself. If you want this exact capability pre-built, pico-ducky and the original Rubber Ducky (both already tracked here) get you there without a soldering iron.","aliases":["EvilDuck (Gen 1)","EvilDuck classic"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","scriptable":"yes","standalone_untethered":"yes","usb_mass_storage":"no","usb_ethernet_attack":"no","usb_keylogger":"no","usb_exfil":"no","hid_remote_trigger":"no","web_ui":"no","wifi_scan_24":"no","ble_scan":"no","cloud_c2":"no","app_store":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"Building and owning it is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-06","app_store":"No","abandoned_risk":"low"}},{"id":"facedancer","hardware_id":"facedancer","name":"Facedancer","firmware_kind":"n/a","vendor":"Great Scott Gadgets (maintainer)","category":"hardware-debug","subcategory":"usb-emulation-framework","status":"available","price_usd":0.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"You write Python that implements a USB device class by hand - descriptors, endpoints, control transfers. It assumes you understand the USB specification.","build_effort":"flash-only","stealth":"overt","form_factor":"board","summary":"A Python framework for emulating USB devices in software, using a piece of supported hardware as the remote-controlled USB controller. It is the standard tool for USB host fuzzing, protocol man-in-the-middle, and building a fake USB device to see how a host reacts.","honest_take":"The confusion worth clearing up is that 'Facedancer' names three things: the original dedicated boards from Travis Goodspeed's GoodFET lineage, the modern Python library, and loosely the whole technique. What you install today is the library, and the hardware you run it on is almost always a Cynthion or a GreatFET One. It is genuinely powerful - being able to write a USB device in Python and watch a host's driver fall over is a rare capability - but it is a framework, not a tool. There is no menu, no payload library and no GUI. If you want a USB attack device that just works, this is not it; if you want to write one, this is what you build it on.","released":"2012","aliases":["Facedancer21","GoodFET Facedancer","USBProxy (predecessor)"],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","usb_ethernet_attack":"partial","usb_payload_lang":"no","usb_exfil":"partial","packet_capture":"partial","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"The software is free and legal to possess and study."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"faultier","hardware_id":"faultier","name":"Faultier","firmware":"Custom","firmware_kind":"stock","vendor":"Hextree.io (sold by 1BitSquared)","category":"hardware-debug","subcategory":"fault-injection","status":"out-of-stock","price_usd":49.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The cheapest genuinely guided route into voltage glitching, because the courses come with it.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A USD 49 voltage fault-injection board built around an RP2040 with a crowbar MOSFET, a two-channel analogue switch for voltage dipping or re-powering, 5 ns glitch resolution and an integrated SWD probe so you can glitch a chip and then dump it with the same tool. Designed as the companion hardware to Hextree's free fault-injection course material.","honest_take":"It only does voltage glitching - no EM injection - so targets that need EMFI are out of scope. Practice targets ('Glitch Tags') are treated as consumables because they break, which is an ongoing cost the headline price hides. And it has been hard to buy: out of stock at the time of writing. But at USD 49 with a real course behind it, this is the least wasteful way to find out whether you actually like fault injection before spending ChipWhisperer money.","released":"2024","aliases":["Hextree Faultier"],"capabilities":{"glitching":"yes","jtag_swd":"yes","scriptable":"yes","logic_analyzer":"no"},"legal":{"risk_level":"low","notes":"Low-voltage bench tool, legal to own."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"faulty-cat","hardware_id":"faulty-cat","name":"Faulty Cat","firmware":"faultycat-firmware","firmware_kind":"stock","vendor":"Electronic Cats","category":"hardware-debug","subcategory":"fault-injection","status":"out-of-stock","price_usd":120.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Two attack methods to learn, plus target analysis.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An RP2040-based fault injector that does both electromagnetic injection (240-250 V flyback into a coil) and crowbar glitching (MOSFET shorting the target's supply), with an 8-channel logic analyser and an SWD/JTAG pin scanner thrown in. Effectively a productised PicoEMP with the voltage-glitching path added.","honest_take":"It is a hobby-to-prosumer instrument, not lab equipment: pulse energy is not calibrated, and the EMFI side inherits the PicoEMP's limitations. The bundled logic analyser and pin scanner are convenience features, not replacements for real tools. Availability has been the recurring complaint - it has been out of stock at the vendor repeatedly, and the European price is nearly 40% above the direct price.","released":"2023","aliases":["FaultyCat","Faulty Cat V2.2"],"capabilities":{"glitching":"yes","logic_analyzer":"yes","jtag_swd":"partial","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Open hardware and legal to own."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"No","abandoned_risk":"low"}},{"id":"feberis-pro","hardware_id":"feberis-pro","name":"Feberis Pro","firmware_kind":"third-party-product","vendor":"SAPSAN, manufactured with Lab401","category":"accessory","subcategory":"flipper-multiboard","status":"available","price_usd":119.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plugs onto the Flipper's GPIO header and needs the right Flipper app/setting for each radio; not a single unified interface the way a phone-app-controlled device is.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A 4-in-1 Flipper Zero GPIO expansion combining two CC1101 radios (one tuned to 433MHz, one to 868MHz), an nRF24 for 2.4GHz, an onboard ESP32 pre-loaded with Marauder for Wi-Fi/BLE, and a GPS module, all on four external antennas with physical band-select switches and status LEDs.","honest_take":"This is functionally very close to the already-tracked Honey Honey Apex 5 - dual CC1101 (433/868), nRF24, ESP32 running Marauder, GPS, external antennas, all on a Flipper GPIO board - down to the same 868MHz-not-915MHz choice that leaves North American sub-GHz devices outside the matched band. The vendor's '10x performance gains over Flipper's built-in modules' is a plausible but unverified marketing figure with no test methodology published; treat it as 'a real external antenna genuinely outperforms the Flipper's internal one,' not a precise 10x measurement. At $119 (or EUR90 depending which store you land on) it lands in the same bracket as the Apex 5 - worth comparing both feature-for-feature before buying either, since they overlap this closely.","released":"2026","aliases":["FEBERIS PRO"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_external_antenna":"yes","subghz_amplified":"claimed","subghz_replay":"yes","nrf24_scan":"yes","mousejack":"partial","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_handshake_capture":"yes","ble_scan":"yes","gps":"yes","gps_wardrive_log":"claimed","hf_1356_read":"no","lf_125khz_read":"no","ir_tx":"no","usb_hid_inject":"no","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"Same profile as any Flipper sub-GHz/Wi-Fi/2."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026","app_store":"Yes - Flipper community apps for sub-GHz/nRF24; the Marauder ecosystem for WiFi","abandoned_risk":"medium"}},{"id":"halehound-fire-weasel-leash-pro","hardware_id":"halehound-fire-weasel-leash-pro","name":"Fire Weasel and Leash PRO DIY Kit","firmware":"HaleHound","firmware_kind":"third-party-product","vendor":"HaleHound (Fire Weasel carrier board designed by community members BkBroiler and Midwest Gadgets/Hamspice)","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":185.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The Fire Weasel carrier PCB and a pre-made wiring harness replace most of the hand-wiring the base HaleHound build needs, but this is still a multi-board RF assembly - vendor states roughly 45 minutes for an experienced builder.","build_effort":"assembly","stealth":"overt","form_factor":"handheld","summary":"A HaleHound kit built around the community-designed 'Fire Weasel' carrier PCB, which exists specifically to replace the hand-wiring the original bare-CYD HaleHound build requires: a 3.5-inch exposed-SPI CYD, an E07-class CC1101 sub-GHz module, an nRF24 module, an ATGM336H GPS with ceramic antenna, matched boost/buck converters, and a 3D-printed case, running the same closed HaleHound firmware as every other entry in this line.","honest_take":"The real engineering here is the Fire Weasel carrier board itself, credited to community designers BkBroiler and Midwest Gadgets/Hamspice rather than to HaleHound's own operator - it turns a build that otherwise needs four separately hand-wired modules into something closer to a harness-and-connector job, a genuine usability improvement over the bare-CYD DIY approach documented elsewhere in this database. The firmware underneath is identical, though, and carries the same caveats: closed source, one maintainer, one flasher domain, CC1101 wiring documented at 300-439MHz (not the full sub-GHz range), and 'jamming' modules that are narrowband nRF24 spam rather than real wideband jamming. The bundled boost and buck converters strongly suggest the CC1101 module here is the amplified E07 PA variant, which needs exactly that separate 3.3V supply per the firmware's own documentation elsewhere - a good sign this kit is wired correctly for it, but that is inference from the parts list, not a vendor claim.","released":"2026","aliases":["Fire Weasel Kit","HaleHound Fire Weasel"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"yes","ble_scan":"yes","ble_advertise":"yes","ble_tracker_detect":"yes","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"yes","subghz_rolling_code":"partial","subghz_amplified":"claimed","nrf24_scan":"yes","mousejack":"yes","nrf24_jam":"claimed","hf_1356_read":"no","hf_1356_write":"no","lf_125khz_read":"no","gps":"yes","gps_wardrive_log":"claimed","sd_logging":"yes","usb_hid_inject":"no","ir_tx":"no","detect_surveillance_cam":"yes","detect_skimmer":"yes"},"legal":{"risk_level":"high","notes":"Same profile as the rest of the HaleHound line: jamming modules are a criminal offence to transmit in the US, UK and EU; deauth, evil twin, MouseJack and sub-GHz replay/bruteforce each carry separate legal exposure."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"No","abandoned_risk":"high"}},{"id":"fire-weasel-board-and-leash-diy-kit","hardware_id":"fire-weasel","name":"Fire Weasel Board and Leash DIY Kit","firmware":"HaleHound-CYD","firmware_kind":"community","vendor":"HaleHound","category":"accessory","subcategory":"multitool-carrier-board","status":"available","price_usd":48.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The bare board itself needs no skill to unbox, but it is inert until you source, wire, and flash a CYD plus separately-bought radio modules yourself - the vendor's own PRO-kit copy says the full build 'takes around 45 minutes on average with experience', implying it is not a true first-solder-job beginner project.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"A bare carrier PCB and wearable strap ('leash') sold on their own by HaleHound, for builders who already have (or will separately buy) their own 'CYD' (Cheap Yellow Display, an ESP32 dev board with a 2.8-3.5in touchscreen) plus CC1101 sub-GHz, NRF24L01+PA+LNA 2.4GHz, and GPS modules. Originally designed by the Midwest Gadgets/BkBroiler/Hamspice community and 'relinquished to the HaleHound', it exists to make wiring a HaleHound-CYD-style RF multitool less of an ad-hoc breadboard job.","honest_take":"The single most important thing to know before buying: as sold, for $48-78, you get a PCB and a strap. Zero MCU, zero radios, zero screen - nothing that transmits, receives, or even boots on its own. It becomes a Flipper-style Wi-Fi/BT/sub-GHz/NRF24/GPS multitool only after you separately source and wire in a ~$15 CYD board, a ~$5-10 CC1101 module, a ~$5-10 amplified NRF24L01 module, and a ~$10 GPS module - none of which are in this box. If you want the finished tool, the vendor's own 'PRO' kit bundles all of that (plus a case) for $185, which is the realistic all-in price of a working Fire Weasel; this listing is for people who already own the modules (e.g. from a previous CYD build) and just want a proper carrier board and strap instead of a breadboard. Whether that convenience is worth $48-78 for a two-part PCB+strap is a judgment call - there's no independent BOM/cost breakdown published to weigh it against.","aliases":[],"capabilities":{"wifi_scan_24":"addon","wifi_deauth_24":"addon","ble_scan":"addon","subghz_rx":"addon","subghz_tx":"addon","nrf24_scan":"addon","mousejack":"addon","gps":"addon","gps_wardrive_log":"addon","sd_logging":"addon","standalone_untethered":"addon","ble_spam_apple":"unknown","ble_spam_android":"unknown","wifi_monitor_mode":"addon","wifi_wardriving":"addon","usb_mass_storage":"addon","ir_tx":"unknown","app_store":"no"},"legal":{"risk_level":"low","notes":"As literally sold (a bare PCB and strap with no radios), this carries no more regulatory weight than any blank circuit board."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"v3.9.5 (2026-08)","app_store":"No","abandoned_risk":"low"}},{"id":"firewalla-red","hardware_id":"firewalla-red","name":"Firewalla (Red)","firmware":"Firewalla firmware","firmware_kind":"third-party-product","vendor":"Firewalla LLC","category":"detection-defense","subcategory":"home-network-security-appliance","status":"out-of-stock","price_usd":109.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Managed entirely through a mobile app; no CLI or manual configuration required for stock features.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"A small ARM-based network appliance that sits on a home LAN (originally sold as 'Firewalla Red') and passively monitors connected devices, flags anomalous behavior, blocks ads/malicious content and adult content by category, and offers a VPN server and DDNS - a consumer home-security and parental-control box, not a penetration-testing tool.","honest_take":"This is the weakest fit of anything assigned in this batch: it is a consumer defensive home-network appliance aimed at protecting a household, with none of the offensive or RF-attack capability that most of the devices in this database have. It's included here because it's a real hardware security product with independently verifiable specs, but if you're shopping this database for pentest gear, skip it - it belongs next to a home router or a parental-control app, not next to a Wi-Fi Pineapple. At $109 for a ~100Mbps-capable box (per the specs on this specific SKU), it's also well behind Firewalla's current Gigabit-capable models (Blue/Purple/Gold) in raw throughput, which matters directly for whether it can actually inspect traffic on a modern home internet connection without becoming the bottleneck.","aliases":["Firewalla Red"],"capabilities":{"packet_capture":"partial","usb_hid_inject":"no","wifi_scan_24":"no","ble_scan":"no","subghz_rx":"no","ethernet_tap_passive":"no","ethernet_mitm":"partial","cloud_c2":"partial","vpn_exfil":"yes","web_ui":"no","app_store":"yes","gps":"no","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"Fully legal defensive consumer product for use on a network you own."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"Yes - iOS/Android companion app","abandoned_risk":"low"}},{"id":"flatsat-defcon-34","hardware_id":"flatsat","name":"FlatSat – DEFCON 34","firmware":"FlatSat Firmware","firmware_kind":"stock","vendor":"Electronic Cats","category":"hardware-debug","subcategory":"training-target","status":"out-of-stock","price_usd":100.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Marketed as needing 'no soldering or coding initially' (drag-and-drop firmware, guided 3-level CTF), but the actual attack walkthroughs (buffer overflows, telecommand spoofing, RF protocol analysis) assume real binary-exploitation and RF fundamentals.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An RP2040-based training board built around two Semtech SX1262 LoRa radios and a BME280/LIS2DH12 sensor pair, preloaded with deliberately vulnerable firmware that mimics a small satellite's telemetry/command bus. Originally an independent open-source project published by researcher(s) as Pwnsat, this DEFCON 34 edition is a limited commemorative production run manufactured and sold by Electronic Cats (an established open-hardware company) from a fork of the original Pwnsat/FlatSat GitHub repo.","honest_take":"The RP2040 and SX1262 radios are real and confirmed, and the underlying Pwnsat project has genuine traction (500+ GitHub stars, active commits) - this isn't vaporware. But 'analyze LoRa telemetry with an SDR' oversells what's onboard: FlatSat's own radios are fixed-function SX1262 LoRa transceivers, not an SDR - you bring your own RTL-SDR/HackRF to passively watch the RF side; the board itself doesn't do general-purpose signal capture. Also worth knowing before buying: when checked, the project's own GitHub wiki pages (hardware anatomy, attack walkthroughs) all returned load errors - the polished front page currently oversells docs that weren't fully working. It's out of stock at Electronic Cats regardless, so hobbyist interest is currently better served by building from the open Pwnsat/FlatSat repo directly than waiting on the commemorative edition.","released":"2026","aliases":["FlatSat 1","Pwnsat FlatSat"],"capabilities":{"uart":"yes","i2c":"yes","jtag_swd":"partial","spi_flash_dump":"unknown","sdr_rx":"no","scriptable":"yes","sdr_tx":"no","sdr_bandwidth":"no","sdr_full_duplex":"no","gps":"no","packet_capture":"yes","usb_mass_storage":"yes","logic_analyzer":"no","glitching":"no"},"legal":{"risk_level":"low","notes":"Transmits on unlicensed ISM bands (433/915MHz) at low power for a training simulation, not a real satellite uplink - no special licence needed to own or use it in most countries."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"flipper-addon-subghz-electroniccats","hardware_id":"flipper-addon-subghz-electroniccats","name":"Flipper Add-On SubGhz","firmware_kind":"n/a","vendor":"Electronic Cats","category":"accessory","subcategory":"flipper-gpio-addon","status":"available","price_usd":35.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Requires official Flipper firmware with Sub-GHz mode explicitly set to 'external,' plus installing Electronic Cats' own LoRa Relay app - not a drop-in that works out of the box with every custom firmware.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A Flipper Zero GPIO shield adding a second, independent CC1101 sub-GHz transceiver plus a Semtech SX1262 LoRa radio (150-960 MHz, LoRaWAN-PHY compliant), letting the Flipper analyze a second sub-GHz signal simultaneously or reach LoRa/LoRaWAN traffic its stock internal CC1101 cannot decode.","honest_take":"The main value here is not more sub-GHz range - the Flipper's own internal CC1101 already covers the same 300-348/387-464/779-928 MHz bands this add-on's CC1101 does - it is the SX1262 LoRa radio, which the stock Flipper has no equivalent for at all. If you only want general sub-GHz replay/analysis and never touch LoRa/LoRaWAN, this board adds little beyond a second simultaneous-capture channel. It requires the Flipper's official firmware with Sub-GHz mode set to 'external' plus a specific .fap app, so it is not a universal drop-in for every custom firmware build, and like the Flipper's own internal radio, nothing about it defeats rolling codes.","aliases":["Flipper SubGhz Add-On","Flipper LRA SubGHz"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"addon","subghz_rolling_code":"no","subghz_external_antenna":"yes","subghz_amplified":"no","standalone_untethered":"no","scriptable":"addon","app_store":"addon","web_ui":"no","gps":"no","ble_scan":"no","hf_1356_read":"no"},"legal":{"risk_level":"high","notes":"Receiving is broadly legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"Yes - LoRa Relay app distributed via Flipper's app catalog","abandoned_risk":"low"}},{"id":"electronic-cats-flipper-magspoof-addon","hardware_id":"electronic-cats-flipper-magspoof-addon","name":"Flipper Add-On: MagSpoof","firmware":"MagSpoof FAP for Flipper Zero","firmware_kind":"third-party-product","vendor":"Electronic Cats","category":"rfid-nfc","subcategory":"Flipper Zero GPIO add-on: magstripe emulator","status":"available","price_usd":28.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Requires already owning a Flipper Zero, a separate USB magstripe reader to capture track data, installing the MagSpoof FAP, and hand-editing/loading .mag track files onto the SD card - not plug-and-play out of the box, but well-documented with a 10-step tutorial.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A GPIO add-on board for the Flipper Zero that wirelessly emulates magnetic-stripe cards: a TC4424 driver chip amplifies the Flipper's pulses through an integrated coil to generate the electromagnetic field a physical swipe would produce, transmitting Track 1 and Track 2 data simultaneously. It requires a companion USB magstripe reader to first capture the target card's track data, and the official page reports only basic transmission confirmed working against one specific reader model (MSR90). It has no RFID/NFC capability at all - magstripe only.","honest_take":"This is at least the second (arguably third) commercial Flipper GPIO board implementing the exact same Samy Kamkar MagSpoof trick - the Rabbit-Labs 'Multi Pass MagSpoof Flipper Board' (hand-soldered, credit-card-thin PCB, sold on Tindie) does the same job, and Electronic Cats itself separately sells a cheaper standalone 'MagSpoof V4' board (no Flipper required) for $10-18 on the same store page. Electronic Cats is a real open-hardware company (Aguascalientes, Mexico) shipping a genuine PCB with a named driver IC and an open hardware/firmware license, not a shell reseller - so it's a legitimate independent implementation, not a rebadge of Rabbit-Labs' board. But the vendor's own page candidly says the team is 'still testing alternate transmission paths' and has only confirmed basic transmission against one reader model, so treat range/reliability claims cautiously versus the more established standalone MagSpoof devices already in this database.","released":"2023","aliases":[],"capabilities":{"magspoof":"yes","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","iso15693":"no","felica":"no","nfc_relay":"no","sd_logging":"addon","scriptable":"no","web_ui":"no","standalone_untethered":"addon"},"legal":{"risk_level":"medium","notes":"Owning and building/testing is legal for authorized security work in most places, and is common practice among red teams and researchers."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"Distributed via GitHub (ElectronicCats/magspoof_flipper) and a Hackster.io getting-started guide; not confirmed present in Flipper's official app catalog - appears to require manual sideload via qFlipper/SD card.","abandoned_risk":"low"}},{"id":"flipper-marauder-electroniccats","hardware_id":"flipper-marauder-electroniccats","name":"Flipper Add-On: Marauder","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"Electronic Cats","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"available","price_usd":40.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Pre-flashed, plugs onto the GPIO header, driven by a touchscreen-style menu once the Flipper is running custom firmware (Momentum/Unleashed/Xtreme/RogueMaster).","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"Electronic Cats' base ESP32-S3 Marauder add-on for the Flipper Zero GPIO header - the same free, MIT-licensed ESP32 Marauder firmware used on roughly 25 other targets (including a $20 M5StickC Plus2), packaged for the Flipper. No MagSpoof, no GPS, no SD or screen of its own confirmed.","honest_take":"This is the plainest, cheapest way into Marauder-on-Flipper from a named, open-hardware vendor, but it is the same firmware you'd get on a $20 M5StickC Plus2 - you're paying for the GPIO form factor and Electronic Cats' companion 'Marauder UI Pro' dashboard, not unique capability. Skip the $10-more Marauder_Spoof unless you specifically want magstripe-card emulation bundled in; skip Hacker Warehouse's $50 resale of this exact board (SKU EC-WMFZ matches this listing) since it's $10 more for nothing extra. A GitHub release note from Electronic Cats claims a hardware revision moved this board from ESP32-S3 to ESP32-C5 (which would add 5GHz support), but the live store listing still describes ESP32-S3 as of this check - verify the current chip before buying if dual-band matters to you.","released":"2024","aliases":["Flipper Add-On: Marauder","ESP32 Marauder Add-On for Flipper Zero"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"no","wifi_ap_mode":"yes","packet_capture":"addon","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","bt_classic":"no","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","detect_flipper":"yes","detect_skimmer":"yes","detect_pineapple":"yes","detect_pwnagotchi":"yes","gps":"no","sd_logging":"addon","scriptable":"partial","standalone_untethered":"no","subghz_rx":"no","hf_1356_read":"no","lf_125khz_read":"no","ir_tx":"no","usb_hid_inject":"no"},"legal":{"risk_level":"medium","notes":"Owning and using it to scan/log is legal in most places."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-05","app_store":"No - single firmware plus Electronic Cats' browser-based 'Marauder UI Pro' dashboard","abandoned_risk":"low"}},{"id":"flipper-marauder-spoof-electroniccats","hardware_id":"flipper-marauder-spoof-electroniccats","name":"Flipper Add-On: Marauder_Spoof","firmware":"Custom","firmware_kind":"community","vendor":"Electronic Cats","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"available","price_usd":50.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Ships pre-flashed; plugs onto the Flipper GPIO header. Flipper must run Unleashed/Momentum/Xtreme/RogueMaster, not stock firmware.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"Electronic Cats' plain ESP32-S3 Marauder WiFi/BLE add-on with their separate MagSpoof magnetic-stripe emulator (an open design descended from Samy Kamkar's MagSpoof, sold standalone by Electronic Cats for a similar price) built onto the same PCB. It is two existing Electronic Cats products combined, not a beefed-up or 'more powerful' version of Marauder itself.","honest_take":"The name invites you to assume 'Spoof' means stronger jamming, amplified TX, or extra antennas added to Marauder - it doesn't. It means Electronic Cats put their separate MagSpoof magnetic-stripe-card emulator (an electromagnet coil and driver chip that reproduces a swipe without a physical card, based on Samy Kamkar's open-source design) on the same board as their plain Marauder. The WiFi/BLE side is byte-for-byte identical to the cheaper $40 'Marauder' add-on (device flipper-marauder-electroniccats below) - same ESP32-S3, same firmware, same deauth-dies-against-WPA3 caveat. If you don't specifically want magstripe emulation, you're paying $10 for a feature you won't use; if you do want it, this is $10 cheaper than buying the standalone MagSpoof add-on ($40-ish) plus the Marauder add-on ($40) separately.","released":"2024","aliases":["Marauder_Spoof","Marauder Spoof","Flipper Add-On: Marauder + MagSpoof"],"capabilities":{"magspoof":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"no","wifi_ap_mode":"yes","packet_capture":"addon","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","bt_classic":"no","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","detect_flipper":"yes","detect_skimmer":"yes","detect_pineapple":"yes","detect_pwnagotchi":"yes","gps":"no","sd_logging":"addon","scriptable":"partial","standalone_untethered":"no","subghz_rx":"no","hf_1356_read":"no","lf_125khz_read":"no","ir_tx":"no","usb_hid_inject":"no"},"legal":{"risk_level":"medium","notes":"Owning and testing your own hardware is legal in most places."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-05","app_store":"No - single firmware plus Electronic Cats' browser-based 'Marauder UI Pro' dashboard","abandoned_risk":"low"}},{"id":"electroniccats-flipper-modbus","hardware_id":"electroniccats-flipper-modbus","name":"Flipper Add-On: RS485 Modbus","firmware":"flipper-rs485modbus","firmware_kind":"community","vendor":"Electronic Cats","category":"accessory","subcategory":"flipper-ics-board","status":"available","price_usd":20.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Requires understanding of Modbus RTU addressing, function codes and RS485 wiring/termination to use meaningfully - this is an industrial-protocol tool, not a plug-and-play attack board.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A GPIO shield plus companion Flipper Zero app that adds RS485 differential signaling and voltage-level shifting, letting the Flipper sniff and inject Modbus RTU traffic on industrial control networks - PLCs, sensors, actuators and similar serial-bus ICS/OT equipment.","honest_take":"This is a rare, genuinely niche addition to the Flipper ecosystem: real ICS/OT protocol testing (sniff Modbus RTU frames, build and send requests by peripheral ID/function code/address, replay captured packets) rather than another RFID or sub-GHz board. The vendor is upfront that Modbus RTU has no built-in authentication or encryption - which is the industrial-protocol reality, not a flaw in this tool - so anything you can address on the bus you can generally write to. It's explicitly billed as 'designed and built for authorized security testing'; there's no ambiguity about what it's for.","aliases":["Flipper RS485 Modbus Plugin","Sniff & Inject: RS485 Modbus Add-On"],"capabilities":{"uart":"partial","packet_capture":"yes","scriptable":"yes","standalone_untethered":"no","web_ui":"no","usb_mass_storage":"no","i2c":"no","spi_flash_dump":"no","jtag_swd":"no","glitching":"no","app_store":"no"},"legal":{"risk_level":"high","notes":"Modbus RTU has no authentication or encryption by design, so unauthorized access to a live industrial network can directly affect physical equipment (valves, motors, sensors) - this carries real safety as well as legal exposure."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No - GitHub source, not the Flipper catalog","abandoned_risk":"low"}},{"id":"flipper-blackhat","hardware_id":"flipper-blackhat","name":"Flipper BlackHat","firmware":"BlackhatOS (Armbian-based)","firmware_kind":"third-party-product","vendor":"Rootkit Labs (Ryan Walker)","category":"accessory","subcategory":"flipper-linux-board","status":"out-of-stock","price_usd":133.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"This is a Linux box you drive from a command line over a serial bridge. If you are not comfortable with Armbian, wireless drivers and monitor mode, most of it will be out of reach.","build_effort":"flash-only","stealth":"overt","form_factor":"board","summary":"A quad-core Allwinner A33 Linux single-board computer in a Flipper Zero GPIO board shape, which borrows the Flipper's screen, buttons and battery and talks to it over the USB-UART bridge at 115200 baud. It runs an Armbian image with real Linux wireless tooling, and ships with a 5 GHz USB Wi-Fi dongle alongside its onboard 2.4 GHz radio.","honest_take":"It is not an ESP32 board and comparing it to one misses the point - it is a 2014-era Android tablet SoC running Debian, which is both its strength (real aircrack-ng, real drivers, real scripting) and its weakness (512 MB RAM, a slow A7 cluster, and Wi-Fi that depends on Realtek out-of-tree drivers being happy). The 5 GHz capability everyone quotes comes from the bundled RTL8821CU USB dongle, not from the board's own RTL8723DS radio. Supply is the real problem: it sells out constantly, and the creator's hardware licence (CC BY-NC-SA) explicitly asks people not to resell boards, so there is no second source.","released":"2025","aliases":["BlackHat","Flipper Blackhat","Rootkit Labs Blackhat"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"partial","wifi_monitor_mode":"partial","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_ap_mode":"yes","packet_capture":"yes","scriptable":"yes","usb_ethernet_attack":"unknown","standalone_untethered":"partial","subghz_rx":"no","nrf24_scan":"no","gps":"no"},"legal":{"risk_level":"medium","notes":"It is a small Linux computer with Wi-Fi adapters; owning one raises no import issue we could find."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No - it is Linux, you install packages; the Flipper-side .fap ships preinstalled in recent Momentum firmware","abandoned_risk":"medium"}},{"id":"flipper-zero-momentum","hardware_id":"flipper-zero","name":"Flipper Zero","firmware":"Momentum","firmware_kind":"community","vendor":"Flipper Devices","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":169.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Easier to live with than stock in some ways - the settings app puts everything on device - but it hands you transmit capability that stock deliberately withholds, so the responsibility is on you.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"A pocket multitool built around four independent radios - a CC1101 sub-GHz transceiver, an ST25R3916 13.56 MHz NFC front end, a separate 125 kHz coil driven straight off the STM32, and the STM32WB55's own Bluetooth LE core - plus infrared, iButton and an 18-pin GPIO header. Momentum is the customisation-first community firmware: it removes the sub-GHz region lock, can push the CC1101 beyond its rated bands, and bundles the apps people actually install anyway - BLE Spam, FindMy Flipper, NFC Maker, Wardriver, Bad-Keyboard. It is the direct continuation of Xtreme, written by the same developers.","honest_take":"It is a very well-built fork, but almost everything people credit it with is either an APP that also runs on other firmware, or a hardware capability that was always there and was only being withheld by policy. The extended frequency range (281-361 / 378-481 / 749-962 MHz) is the one to be careful about: it drives the CC1101's PLL outside TI's specified bands and the antenna matching is wrong there, so you get poor performance and the projects themselves warn it can damage the hardware. Also note the release cadence - the last tagged stable is mntm-012 from 2025-12-31 and everything since has been dev builds.","released":"2020","aliases":["Momentum","MNTM","Momentum FW"],"capabilities":{"subghz_rx":"yes","subghz_replay":"yes","subghz_external_antenna":"addon","subghz_amplified":"addon","lf_125khz_read":"yes","lf_125khz_write":"partial","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"partial","iso15693":"yes","felica":"partial","mifare_desfire":"partial","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","ble_advertise":"yes","ble_hid":"yes","bt_classic":"no","ble_sniff":"no","usb_hid_inject":"yes","usb_payload_lang":"yes","uart":"yes","i2c":"yes","jtag_swd":"partial","glitching":"no","ibutton_1wire":"yes","gps":"addon","sd_logging":"yes","scriptable":"yes","app_store":"yes","standalone_untethered":"yes","wifi_scan_24":"addon","wifi_scan_5":"no","wifi_monitor_mode":"addon","wifi_deauth_24":"addon","wifi_deauth_5":"no","wifi_evil_twin":"addon","wifi_captive_portal":"addon","wifi_handshake_capture":"addon","wifi_pmkid":"addon","wifi_beacon_spam":"addon","wifi_probe_sniff":"addon","wifi_wardriving":"addon","wifi_ap_mode":"addon","nrf24_scan":"addon","mousejack":"addon","sdr_rx":"no","sdr_tx":"no","subghz_tx":"yes","subghz_rolling_code":"partial","subghz_bruteforce":"yes","mifare_classic_attacks":"partial","nfc_type4_ndef":"yes","emv_read":"partial","hf_1356_emulate":"partial","magspoof":"addon","usb_mass_storage":"yes","spi_flash_dump":"addon","logic_analyzer":"partial","ble_scan":"partial","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","findmy_track":"yes","ble_tracker_detect":"partial","rpg_leveling":"yes","device_lock":"yes","rgb_backlight":"addon","subghz_wardrive":"addon"},"legal":{"risk_level":"medium","notes":"Owning a Flipper Zero is legal in the US, the UK, the EU and most of the world - the device is CE/FCC marked and sold openly by the vendor."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2025-12","app_store":"Yes - bundled Momentum-Apps set plus the official catalog","abandoned_risk":"low"}},{"id":"flipper-zero-official","hardware_id":"flipper-zero","name":"Flipper Zero","firmware":"Official (stock)","firmware_kind":"stock","vendor":"Flipper Devices","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":169.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"The menus are genuinely approachable and you can do something useful on day one; understanding WHY an attack works is the hard part, not driving the device.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"A pocket multitool built around four independent radios - a CC1101 sub-GHz transceiver, an ST25R3916 13.56 MHz NFC front end, a separate 125 kHz coil driven straight off the STM32, and the STM32WB55's own Bluetooth LE core - plus infrared, iButton and an 18-pin GPIO header. Stock firmware is the sane default: everything is signed, supported and gets security fixes, and the sub-GHz transmitter is restricted to what is legal where you provisioned the device. Best first stop for anyone learning RF and access control.","honest_take":"The single biggest misconception is that it does Wi-Fi. It does not - there is no Wi-Fi radio in the device at all, and every Wi-Fi feature you have seen in a video is an ESP32 add-on board doing the work. The second is that stock firmware is crippled; it is not, it just will not transmit outside your region and will not ship the joke apps. For pure NFC research a Proxmark3 is far more capable, and for anything spectrum-shaped an RTL-SDR at a quarter the price sees vastly more.","released":"2020","aliases":["Flipper","Dolphin","OFW","Stock firmware"],"capabilities":{"subghz_rx":"yes","subghz_replay":"yes","subghz_external_antenna":"no","subghz_amplified":"no","lf_125khz_read":"yes","lf_125khz_write":"partial","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"partial","iso15693":"yes","felica":"partial","mifare_desfire":"partial","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","ble_advertise":"yes","ble_hid":"yes","bt_classic":"no","ble_sniff":"no","usb_hid_inject":"yes","usb_payload_lang":"yes","uart":"yes","i2c":"yes","jtag_swd":"partial","glitching":"no","ibutton_1wire":"yes","gps":"addon","sd_logging":"yes","scriptable":"yes","app_store":"yes","standalone_untethered":"yes","wifi_scan_24":"addon","wifi_scan_5":"no","wifi_monitor_mode":"addon","wifi_deauth_24":"addon","wifi_deauth_5":"no","wifi_evil_twin":"addon","wifi_captive_portal":"addon","wifi_handshake_capture":"addon","wifi_pmkid":"addon","wifi_beacon_spam":"addon","wifi_probe_sniff":"addon","wifi_wardriving":"addon","wifi_ap_mode":"addon","nrf24_scan":"addon","mousejack":"addon","sdr_rx":"no","sdr_tx":"no","subghz_tx":"partial","subghz_rolling_code":"partial","subghz_bruteforce":"no","mifare_classic_attacks":"partial","nfc_type4_ndef":"partial","emv_read":"no","hf_1356_emulate":"partial","ble_scan":"no","ble_spam_apple":"no","ble_spam_android":"no","ble_spam_samsung":"no","ble_spam_swift_pair":"no","findmy_track":"no","magspoof":"addon","usb_mass_storage":"partial","spi_flash_dump":"addon","logic_analyzer":"partial","rpg_leveling":"partial","device_lock":"yes","rgb_backlight":"no","subghz_wardrive":"no"},"legal":{"risk_level":"medium","notes":"Owning a Flipper Zero is legal in the US, the UK, the EU and most of the world - the device is CE/FCC marked and sold openly by the vendor."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2025-12","app_store":"Yes - official catalog at lab.flipper.net, plus community packs","abandoned_risk":"low"}},{"id":"flipper-zero-roguemaster","hardware_id":"flipper-zero","name":"Flipper Zero","firmware":"RogueMaster","firmware_kind":"community","vendor":"Flipper Devices","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":169.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Not because it is technically harder, but because the sheer number of bundled apps - many unmaintained - makes it harder to tell what actually works and what is broken.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"A pocket multitool built around four independent radios - a CC1101 sub-GHz transceiver, an ST25R3916 13.56 MHz NFC front end, a separate 125 kHz coil driven straight off the STM32, and the STM32WB55's own Bluetooth LE core - plus infrared, iButton and an 18-pin GPIO header. RogueMaster is the maximalist fork: it tracks Unleashed and official upstream and adds nearly every community plugin, game, IR remote and asset pack in existence. Frequent builds, an enormous app list, and a Patreon that gates the most frequent compiled releases (GitHub releases run roughly monthly; the source is open either way).","honest_take":"The value here is curation-by-inclusion, not original engineering - almost all the RF and NFC work it ships comes from Unleashed and official upstream, which the changelog is honest about crediting. The cost is real: hundreds of bundled apps of wildly varying quality, large asset packs that make the device sluggish, and a much bigger surface for something to be subtly broken. If you want everything to try and do not mind the mess, it is great. If you want to trust that a feature works, use Unleashed.","released":"2020","aliases":["RogueMaster","RM","wPlugins"],"capabilities":{"subghz_rx":"yes","subghz_replay":"yes","subghz_external_antenna":"addon","subghz_amplified":"addon","lf_125khz_read":"yes","lf_125khz_write":"partial","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"partial","iso15693":"yes","felica":"partial","mifare_desfire":"partial","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","ble_advertise":"yes","ble_hid":"yes","bt_classic":"no","ble_sniff":"no","usb_hid_inject":"yes","usb_payload_lang":"yes","uart":"yes","i2c":"yes","jtag_swd":"partial","glitching":"no","ibutton_1wire":"yes","gps":"addon","sd_logging":"yes","scriptable":"yes","app_store":"yes","standalone_untethered":"yes","wifi_scan_24":"addon","wifi_scan_5":"no","wifi_monitor_mode":"addon","wifi_deauth_24":"addon","wifi_deauth_5":"no","wifi_evil_twin":"addon","wifi_captive_portal":"addon","wifi_handshake_capture":"addon","wifi_pmkid":"addon","wifi_beacon_spam":"addon","wifi_probe_sniff":"addon","wifi_wardriving":"addon","wifi_ap_mode":"addon","nrf24_scan":"addon","mousejack":"addon","sdr_rx":"no","sdr_tx":"no","subghz_tx":"yes","subghz_rolling_code":"partial","subghz_bruteforce":"yes","mifare_classic_attacks":"partial","nfc_type4_ndef":"yes","emv_read":"partial","hf_1356_emulate":"partial","magspoof":"addon","usb_mass_storage":"yes","spi_flash_dump":"addon","logic_analyzer":"partial","ble_scan":"partial","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","findmy_track":"yes","ble_tracker_detect":"partial","rpg_leveling":"yes","device_lock":"yes","rgb_backlight":"addon","subghz_wardrive":"addon"},"legal":{"risk_level":"medium","notes":"Owning a Flipper Zero is legal in the US, the UK, the EU and most of the world - the device is CE/FCC marked and sold openly by the vendor."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"Yes - and hundreds of apps are already bundled","abandoned_risk":"medium"}},{"id":"flipper-zero-unleashed","hardware_id":"flipper-zero","name":"Flipper Zero","firmware":"Unleashed","firmware_kind":"community","vendor":"Flipper Devices","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":169.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Behaves almost exactly like stock, so nothing new to learn; the difference is what it will let you transmit.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"A pocket multitool built around four independent radios - a CC1101 sub-GHz transceiver, an ST25R3916 13.56 MHz NFC front end, a separate 125 kHz coil driven straight off the STM32, and the STM32WB55's own Bluetooth LE core - plus infrared, iButton and an 18-pin GPIO header. Unleashed is the most stable and most actively released community fork. It removes the sub-GHz region lock, adds a large number of sub-GHz protocol decoders and manual-creation flows, an on-device frequency analyser and external CC1101 module support, and stays API-compatible with official firmware apps. Extra apps ship separately as an app pack rather than being compiled in.","honest_take":"If you want the region lock gone and nothing else weird, this is the one - it is the least opinionated fork and by some distance the most frequently released. It is also where most of the real sub-GHz and NFC engineering in this ecosystem now happens; the other forks pull from it. Do not expect a flashier device: Unleashed deliberately does not ship the animations, theming and joke apps, and BLE Spam is a bundled SD-card app rather than a firmware feature.","released":"2020","aliases":["Unleashed","UL","unlshd"],"capabilities":{"subghz_rx":"yes","subghz_replay":"yes","subghz_external_antenna":"addon","subghz_amplified":"addon","lf_125khz_read":"yes","lf_125khz_write":"partial","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"partial","iso15693":"yes","felica":"partial","mifare_desfire":"partial","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","ble_advertise":"yes","ble_hid":"yes","bt_classic":"no","ble_sniff":"no","usb_hid_inject":"yes","usb_payload_lang":"yes","uart":"yes","i2c":"yes","jtag_swd":"partial","glitching":"no","ibutton_1wire":"yes","gps":"addon","sd_logging":"yes","scriptable":"yes","app_store":"yes","standalone_untethered":"yes","wifi_scan_24":"addon","wifi_scan_5":"no","wifi_monitor_mode":"addon","wifi_deauth_24":"addon","wifi_deauth_5":"no","wifi_evil_twin":"addon","wifi_captive_portal":"addon","wifi_handshake_capture":"addon","wifi_pmkid":"addon","wifi_beacon_spam":"addon","wifi_probe_sniff":"addon","wifi_wardriving":"addon","wifi_ap_mode":"addon","nrf24_scan":"addon","mousejack":"addon","sdr_rx":"no","sdr_tx":"no","subghz_tx":"yes","subghz_rolling_code":"partial","subghz_bruteforce":"yes","mifare_classic_attacks":"partial","nfc_type4_ndef":"yes","emv_read":"partial","hf_1356_emulate":"partial","magspoof":"addon","usb_mass_storage":"yes","spi_flash_dump":"addon","logic_analyzer":"partial","ble_scan":"partial","ble_spam_apple":"partial","ble_spam_android":"partial","ble_spam_samsung":"partial","ble_spam_swift_pair":"partial","findmy_track":"yes","ble_tracker_detect":"partial","rpg_leveling":"partial","device_lock":"yes","rgb_backlight":"addon","subghz_wardrive":"no"},"legal":{"risk_level":"medium","notes":"Owning a Flipper Zero is legal in the US, the UK, the EU and most of the world - the device is CE/FCC marked and sold openly by the vendor."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"Yes - official catalog plus the maintained all-the-plugins pack","abandoned_risk":"low"}},{"id":"flipper-zero-xtreme","hardware_id":"flipper-zero","name":"Flipper Zero","firmware":"Xtreme","firmware_kind":"community","vendor":"Flipper Devices","category":"multitool","subcategory":"rf-multitool","status":"discontinued","price_usd":169.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Listed for historical accuracy only; there is no reason to choose it today.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"Historically the customisation-focused Flipper Zero fork, and the firmware that originated BLE Spam and the Xtreme Settings app. It is now discontinued: the GitHub repository is archived, the last release was 2024-02-02 and the last commit 2024-11-19. Its own README carries a caution telling users to install a different firmware.","honest_take":"This is a dead project and you should not install it - it is here so people who find old tutorials and YouTube videos know what happened to it. It did not vanish because it was bad; the same developers carried the work forward into Momentum, which is explicitly described in Momentum's README as 'a direct continuation of the Xtreme firmware'. Interestingly, Xtreme's own archived README points users to Unleashed rather than Momentum. Anything you liked about Xtreme exists in Momentum today.","released":"2020","aliases":["Xtreme","XFW","Xtreme Firmware","Flipper-XFW"],"capabilities":{"subghz_rx":"yes","subghz_replay":"yes","subghz_external_antenna":"addon","subghz_amplified":"addon","lf_125khz_read":"yes","lf_125khz_write":"partial","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"partial","iso15693":"yes","felica":"partial","mifare_desfire":"partial","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","ble_advertise":"yes","ble_hid":"yes","bt_classic":"no","ble_sniff":"no","usb_hid_inject":"yes","usb_payload_lang":"yes","uart":"yes","i2c":"yes","jtag_swd":"partial","glitching":"no","ibutton_1wire":"yes","gps":"addon","sd_logging":"yes","scriptable":"yes","app_store":"yes","standalone_untethered":"yes","wifi_scan_24":"addon","wifi_scan_5":"no","wifi_monitor_mode":"addon","wifi_deauth_24":"addon","wifi_deauth_5":"no","wifi_evil_twin":"addon","wifi_captive_portal":"addon","wifi_handshake_capture":"addon","wifi_pmkid":"addon","wifi_beacon_spam":"addon","wifi_probe_sniff":"addon","wifi_wardriving":"addon","wifi_ap_mode":"addon","nrf24_scan":"addon","mousejack":"addon","sdr_rx":"no","sdr_tx":"no","subghz_tx":"yes","subghz_rolling_code":"partial","subghz_bruteforce":"yes","mifare_classic_attacks":"partial","nfc_type4_ndef":"yes","emv_read":"unknown","hf_1356_emulate":"partial","magspoof":"addon","usb_mass_storage":"yes","spi_flash_dump":"addon","logic_analyzer":"partial","ble_scan":"partial","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","findmy_track":"unknown","ble_tracker_detect":"partial","rpg_leveling":"yes","device_lock":"yes","rgb_backlight":"addon","subghz_wardrive":"addon"},"legal":{"risk_level":"medium","notes":"Owning a Flipper Zero is legal in the US, the UK, the EU and most of the world - the device is CE/FCC marked and sold openly by the vendor."},"ecosystem":{"community":"dead","docs_quality":"sparse","last_release":"2024-02","app_store":"No longer maintained; app API is obsolete","abandoned_risk":"already-abandoned"}},{"id":"flipper-predator-module","hardware_id":"flipper-predator-module","name":"Flipper Zero \"Predator\" Module (unbranded ESP32-S2 + display + GPS + 433 MHz)","firmware":"Custom","firmware_kind":"community","vendor":"Unbranded - sold under the 'Predator' name by marketplace sellers; no first-party vendor could be verified","category":"accessory","subcategory":"flipper-multiboard","status":"available","price_usd":60.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Same GPIO-mapping problem as every Flipper multiboard, but with worse documentation - even owners writing public notes say they are still working out which GPIO the display uses.","build_effort":"flash-only","stealth":"overt","form_factor":"board","summary":"A marketplace-sourced Flipper Zero expansion board sold under the name 'Predator', built around an ESP32-S2 with a 2.8-inch display, a GPS receiver and a 433 MHz 'A07' sub-GHz module. It is the same category as the generic 3-in-1 multiboards, distinguished mainly by the large screen and by having no identifiable manufacturer behind it.","honest_take":"Be careful with this one. There is no vendor: 'Predator' is a name that appears on marketplace listings and in a couple of hobbyist GitHub notebooks, not a product line with a company, documentation or support behind it. The public notes that exist are honest about how little is known - one owner's repo openly lists 'which GPIO the display actually uses' and 'whether the A07 is just an RF front end or needs its own firmware' as open questions. Separately, the 'Predator Security Suite' Flipper app that shares the name is a software project with single-digit stars whose README leads with claims about supporting 35 car manufacturers and 18 frequencies; treat that as marketing, not as evidence the hardware opens cars. If you want this class of board, buy the documented equivalents instead.","released":"2025","aliases":["Predator","Predator Module","Flipper Predator board","ESP32 Predator"],"capabilities":{"wifi_scan_24":"claimed","wifi_scan_5":"no","wifi_deauth_24":"claimed","ble_scan":"no","subghz_rx":"claimed","subghz_tx":"unknown","subghz_external_antenna":"claimed","gps":"claimed","gps_wardrive_log":"unknown","nrf24_scan":"no"},"legal":{"risk_level":"medium","notes":"Nothing about the hardware is restricted, but two things are worth flagging."},"ecosystem":{"community":"dormant","docs_quality":"poor","last_release":null,"app_store":"No dedicated app; owners use Marauder plus the Flipper's stock apps","abandoned_risk":"high"}},{"id":"flipper-multiboard-3in1-generic","hardware_id":"flipper-multiboard-3in1-generic","name":"Flipper Zero 3-in-1 Multi Board (generic ESP32 + CC1101 + nRF24)","firmware":"Custom","firmware_kind":"community","vendor":"Multiple - Honey Honey Lab, TSGP Studio, MTools Tec, rek5lab, FlipMods and many unbranded AliExpress sellers","category":"accessory","subcategory":"flipper-multiboard","status":"available","price_usd":20.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"The hard part is not the hardware, it is knowing which GPIO pin mapping each radio expects and switching the Flipper's settings accordingly.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The commodity Flipper Zero expansion board: an ESP32 for Wi-Fi and BLE, a CC1101 for extra sub-GHz range with an external antenna, and an nRF24L01+ for 2.4 GHz raw packet work, usually with three SMA connectors and sometimes a small screen, microSD and GPS. Dozens of sellers ship near-identical designs; TSGP Studio publishes its gerbers openly, which is why the boards look the same everywhere.","honest_take":"This is genuinely a $6 ESP32 module, a $2-4 CC1101 module, a $2 nRF24 module and a few SMA jacks on a shared PCB - and you can verify that from the market, because a real vendor sells the bare 3-in-1 for about US$16 while brand-name Flipper boards with the same chip count ask $140-160. What the money buys at the low end is that someone routed the SPI bus and sorted out the pin conflicts, and that is not nothing: the three radios share the Flipper's limited GPIO, so most boards make you pick one at a time with a physical toggle, and the pin mapping differs between designs. Honey Honey's own Apex 5 shipped a first batch where the ESP32 and the GPS could not both be connected, which silently broke wardriving until a v2 board remapped the pins. Judge a specific board on whether its pinout matches your firmware's defaults, not on the chip list.","released":"2023","aliases":["3in1 Multi Board","Flipper Multi Board","Marauder Multi Board","ESP32 + CC1101 + NRF24 board","4in1 board","wardriving board"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"partial","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"partial","wifi_ap_mode":"yes","ble_scan":"yes","ble_spam_apple":"yes","subghz_rx":"yes","subghz_tx":"yes","subghz_external_antenna":"yes","subghz_amplified":"no","subghz_replay":"yes","nrf24_scan":"yes","mousejack":"partial","nrf24_jam":"partial","gps":"partial","gps_wardrive_log":"partial","sd_logging":"yes","standalone_untethered":"partial"},"legal":{"risk_level":"medium","notes":"The board itself is three common radio modules; we found no import restrictions on the category."},"ecosystem":{"community":"very-active","docs_quality":"sparse","last_release":"2026-09","app_store":"Yes - the Flipper side uses apps from Flipper Lab and the community catalogs; the ESP32 side is Marauder or GhostESP","abandoned_risk":"low"}},{"id":"flipper-addon-ethernet-electroniccats","hardware_id":"flipper-addon-ethernet-electroniccats","name":"Flipper Zero Add-On: Ethernet (ENC28J60)","firmware":"flipper-ENC28J60-ethernet","firmware_kind":"third-party-product","vendor":"Electronic Cats","category":"accessory","subcategory":"wired-lan-addon","status":"available","price_usd":25.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plugs onto the Flipper's GPIO header and needs the .fap sideloaded, but using ARP scan/spoof/sniffer meaningfully requires basic network knowledge.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A small GPIO daughterboard that gives the Flipper Zero a wired 10BASE-T Ethernet port via a Microchip ENC28J60 controller, paired with an open-source app for ARP scanning, passive LLDP discovery, ARP spoofing, and PCAP-exportable packet sniffing. It brings basic wired-network auditing to a device that otherwise has no Ethernet capability at all.","honest_take":"The ENC28J60 is a 10Mbps-only, half/full-duplex 10BASE-T chip from the 2000s — it will not see or touch a modern gigabit-only switch port, and even where it links up, throughput is a fraction of what a $10 USB Ethernet dongle on a laptop gives you. The real value is convenience (it rides on hardware you already carry) rather than raw capability; a Raspberry Pi Zero with the same ENC28J60-class chip and Ettercap will out-perform it for actual MITM work. ARP spoofing on a network you don't control and don't have permission to test is illegal in most places even though the app makes it a two-tap operation.","released":"2024","aliases":["Flipper Ethernet Add-On","Flipper ENC28J60"],"capabilities":{"packet_capture":"yes","ethernet_mitm":"partial","ethernet_tap_passive":"yes","usb_ethernet_attack":"no","wifi_scan_24":"no","wifi_monitor_mode":"no","cloud_c2":"no","standalone_untethered":"no","sd_logging":"yes","app_store":"unknown","scriptable":"no"},"legal":{"risk_level":"low","notes":"Owning and using it for authorized network diagnostics is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08","app_store":"Unknown","abandoned_risk":"low"}},{"id":"flipper-bffb-v1","hardware_id":"flipper-bffb-v1","name":"Flipper Zero BFFB (v1)","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"JustCallMeKoko LLC","category":"accessory","subcategory":"flipper-multiboard","status":"discontinued","price_usd":146.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same as v2 - Marauder menus and correct antenna placement across five SMAs.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The original Big Flipper Board: an ESP32-WROOM-32EU with two band-tuned CC1101 radios (400 MHz and 900 MHz), a 500 mW Ebyte nRF24, GPS and microSD, on five SMA connectors. Functionally identical to v2 except that its Wi-Fi radio is 2.4 GHz only.","honest_take":"The only meaningful difference from v2 is the Wi-Fi chip, and it is a big one: ESP32-WROOM-32 cannot see 5 GHz at all, so on a modern dual-band network this board is deaf to most of what is happening. If you find one second-hand, price it as a sub-GHz-plus-nRF24 board that happens to have 2.4 GHz Wi-Fi attached, not as a Wi-Fi tool.","released":"2024","aliases":["BFFB","BFFB v1","Big Flipper Board"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"yes","wifi_evil_twin":"yes","wifi_wardriving":"yes","ble_scan":"yes","ble_spam_apple":"yes","bt_classic":"partial","subghz_rx":"yes","subghz_tx":"yes","subghz_external_antenna":"yes","nrf24_scan":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes"},"legal":{"risk_level":"high","notes":"Same profile as v2: sub-GHz TX, Wi-Fi deauth and an amplified 2."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":null,"app_store":"No - Marauder plus a Flipper companion FAP","abandoned_risk":"low"}},{"id":"flipper-bffb-v2","hardware_id":"flipper-bffb-v2","name":"Flipper Zero BFFB v2","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"JustCallMeKoko LLC","category":"accessory","subcategory":"flipper-multiboard","status":"out-of-stock","price_usd":160.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Physically plug-and-play with a Flipper, but you are living in Marauder's menus and you will need to understand which antenna belongs on which SMA.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The 'Big Flipper Board' from the author of ESP32 Marauder: a maximalist Flipper add-on carrying an ESP32-C5 for dual-band Wi-Fi, two separate CC1101 radios individually tuned for the 400 MHz and 900 MHz bands, an nRF24 with PA and LNA, GPS and a microSD slot, with five SMA connectors on the edge. It is the most radio-dense Flipper add-on board that is actually a designed product rather than a generic import.","honest_take":"The two band-tuned CC1101s are the genuinely clever bit - a single CC1101 with one antenna is always a compromise across 300-900 MHz, and splitting it lets you also hang your own amplifier on each band. Everything else is the usual multiboard bill of materials, just done properly. Three practical warnings: it is expensive at $160 and almost never in stock; the Marauder wiki carries a dedicated 'BFFB NRF24 Fix' page, which means at least one revision shipped with an nRF24 hardware problem; and 500 mW into an nRF24 is not a magic weapon - it is still a 2.4 GHz GFSK transceiver, and pushing it that hard is an interference and legality question, not a capability upgrade.","released":"2025","aliases":["BFFB","BFFB v2","Big Flipper Board","Big F***ing Flipper Board"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"partial","wifi_beacon_spam":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_wardriving":"yes","wifi_probe_sniff":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_sniff":"partial","subghz_rx":"yes","subghz_tx":"yes","subghz_external_antenna":"yes","subghz_amplified":"no","nrf24_scan":"yes","mousejack":"partial","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes"},"legal":{"risk_level":"high","notes":"A board that can transmit on sub-GHz, 2."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":null,"app_store":"No - the ESP32 side is Marauder; the Flipper side uses a Marauder companion FAP","abandoned_risk":"low"}},{"id":"flipper-devboard-pro-gps-expansion","hardware_id":"flipper-devboard-pro-gps-expansion","name":"Flipper Zero Dev Board Pro GPS Expansion","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"JustCallMeKoko LLC","category":"wifi","subcategory":"gps-wardriving-accessory","status":"out-of-stock","price_usd":21.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Unlike the plug-in Flipper GPIO boards in this database, this specifically requires hand soldering.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"A small GPS receiver + ceramic antenna + replacement faceplate kit that solders onto JustCallMeKoko's own 'Flipper Zero WiFi Dev Board Pro' (an ESP32-WROOM-based Marauder board, sold separately) to unlock Marauder's GPS-tagged wardriving mode. On its own this SKU does nothing; it is meaningless without the host board, which was also out of stock at time of check.","honest_take":"Read the name literally: this is an expansion FOR the Dev Board Pro, not a product in its own right - buying just this $21 kit with no Dev Board Pro gets you an antenna and some wire. Both halves of the combination were simultaneously out of stock on JustCallMeKoko's own store when checked, which is a real availability problem, not a hypothetical one. It also requires actual soldering (four 30AWG wires), unlike every plug-and-play Flipper GPIO board elsewhere in this database - factor that into skill level and time before assuming it's a quick add-on. Note that the 'medium' abandonment risk here is about the hardware, not the code: the underlying ESP32 Marauder firmware project is very healthy (12k+ stars, MIT, commits within the last week), but the Dev Board Pro and this accessory are both one-person-LLC Shopify SKUs from the same maintainer, and a two-part product with both halves out of stock at once is exactly the supply-continuity risk you don't get buying from Electronic Cats or Flipper Devices themselves.","aliases":["Dev Board Pro GPS Expansion","WiFi Dev Board Pro GPS Mod","SD GPS Expansion Board"],"capabilities":{"gps":"yes","gps_wardrive_log":"yes","wifi_wardriving":"yes","sd_logging":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","packet_capture":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","bt_classic":"unknown","detect_flipper":"yes","detect_skimmer":"yes","detect_pineapple":"yes","detect_pwnagotchi":"yes","standalone_untethered":"no","subghz_rx":"no","hf_1356_read":"no","ir_tx":"no","usb_hid_inject":"no"},"legal":{"risk_level":"low","notes":"The GPS expansion itself is passive receive-only hardware - no transmit, no privacy-invasive capability of its own beyond logging your own location while wardriving."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08","app_store":"No - relies on the same single-firmware ESP32 Marauder project used by every other board in this family","abandoned_risk":"medium"}},{"id":"flipper-zero-spi-adapter-board-jcmk","hardware_id":"flipper-zero-spi-adapter-board-jcmk","name":"Flipper Zero SPI Adapter Board","firmware_kind":"n/a","vendor":"JustCallMeKoko LLC (JCMK)","category":"accessory","subcategory":"gpio-breakout","status":"out-of-stock","price_usd":5.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"It is a passive pass-through board - plug it onto the Flipper's GPIO header and plug your SPI module into it.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A small passive breakout board that exposes the Flipper Zero's SPI pins on its GPIO header, so external SPI-capable modules such as CC1101 or NRF24 add-on boards can be connected without wiring individual jumpers. It has no MCU, radio or active circuitry of its own - it is purely a pinout adapter.","honest_take":"There is nothing to evaluate technically here - it is a $5 pass-through PCB with no chip on it, sold specifically so JCMK's own SubGHz and NRF24 modules (and other third-party SPI boards) have a clean connector instead of loose jumper wires to the Flipper's header. Worth buying only if you already own or plan to own an SPI add-on module for the Flipper; it does nothing by itself, has no debug, capture or storage function of any kind, and is currently sold out with no restock date given.","released":"2023","aliases":[],"capabilities":{"spi_flash_dump":"no","uart":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","scriptable":"no","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A passive adapter board with no radio and no independent function - legal to own and use everywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"n/a","app_store":"No","abandoned_risk":"low"}},{"id":"jcmk-flipper-subghz-module","hardware_id":"jcmk-flipper-subghz-module","name":"Flipper Zero SubGHz Module","firmware_kind":"n/a","vendor":"JustCallMeKoko LLC (JCMK)","category":"subghz","subcategory":"flipper-accessory","status":"out-of-stock","price_usd":12.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"No soldering; it plugs onto the SPI Adapter Board, which plugs onto the Flipper's GPIO header.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A standalone CC1101 module that plugs into a Flipper Zero's GPIO header (via a required separate adapter board) to externalize sub-GHz radio duties, so a bigger antenna or an amplifier can be attached instead of using the Flipper's small internal antenna. It does not add any new firmware capability - the Flipper's own sub-GHz app still runs the same features it always did.","honest_take":"This is a single-radio accessory with no amplifier of its own, sold at the same price point as commodity 3-in-1 Flipper expansion boards that pack an ESP32 and an nRF24 alongside the same CC1101 - so buyers comparing on price alone are giving up two radios for the same money. If your actual goal is more transmit range, this module alone doesn't get you there; Rabbit-Labs' Flux Capacitor bundles a genuine +20 dBm power amplifier (E07-433M20S) into a similar GPIO board for about $59, versus this module's bare CC1101 with just a better antenna connector. Both the module and its required adapter board are currently sold out, so as of this check it isn't actually buyable at any price.","aliases":["JCMK SubGHz Module"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_external_antenna":"yes","subghz_amplified":"no","subghz_replay":"partial","subghz_rolling_code":"no","standalone_untethered":"no","usb_mass_storage":"no","scriptable":"no","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning the module is legal."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"n/a - hardware accessory, no firmware releases","app_store":"No","abandoned_risk":"medium"}},{"id":"flipper-video-game-module","hardware_id":"flipper-video-game-module","name":"Flipper Zero Video Game Module","firmware":"Official","firmware_kind":"stock","vendor":"Flipper Devices","category":"accessory","subcategory":"display-dev-addon","status":"available","price_usd":49.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Trivial to plug in and mirror the screen; writing your own firmware means the Raspberry Pi Pico SDK and C.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"An RP2040 board that presses onto the Flipper's GPIO header, outputs 640x480p60 video over an HDMI-shaped connector, and carries a 6-axis motion sensor for tilt-controlled games. Developed with Raspberry Pi and announced February 2024. It is a genuinely open, Pico-compatible dev board: schematics are published, the toolchain is the standard Pico SDK, and it exposes 11 spare GPIO.","honest_take":"Be clear that this is a games and development accessory, not a security tool - there is nothing offensive in the design and nobody has built anything offensive on it. Two technical points worth knowing: the video is DVI-D bit-banged by the RP2040's PIO units via PicoDVI with no transmitter chip, which only works because the chip is overclocked to 252MHz at raised core voltage (1.2V) against a 133MHz rated spec; and Flipper carefully avoid the word HDMI because they have no adopter licence. The bigger problem is that the ecosystem stalled: the official firmware has not been touched since May 2024, the game engine meant to seed it has been untouched since February 2024, and about 1% of the official app catalog targets it. At $49 you are paying roughly ten times a bare Raspberry Pi Pico for the same RP2040, plus a video connector, an IMU and a Flipper-shaped case.","released":"2024-02","aliases":["VGM","Video Game Module","FLP-M-VGM"],"capabilities":{"hdmi_capture":"no","uart":"yes","i2c":"partial","spi_flash_dump":"no","logic_analyzer":"no","scriptable":"partial","usb_mass_storage":"partial","standalone_untethered":"partial"},"legal":{"risk_level":"low","notes":"No restrictions found anywhere."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2024-05","app_store":"Technically yes, but only about 5-6 of roughly 441 official catalog apps target it, and most of those are Flipper's own demos","abandoned_risk":"high"}},{"id":"texas-flipper-boards-wardriving-gps","hardware_id":"texas-flipper-boards-wardriving-gps","name":"Flipper Zero Wardriving GPS enabled ESP32 Board","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"Texas Flipper Boards","category":"wardriving","subcategory":"flipper-zero-addon","status":"out-of-stock","price_usd":120.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Arrives pre-flashed and pre-assembled; use is mostly plugging it onto the Flipper's GPIO/UART header and running the Marauder app from the Flipper app catalog.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"The official Flipper Zero Wi-Fi Devboard (Flipper Devices' own $35 ESP32 add-on) modified by Texas Flipper Boards with a bolted-on GPS module and an external Wi-Fi antenna, reshipped in a custom 3D-printed enclosure and preloaded with the official ESP32 Marauder firmware. It has no storage or Bluetooth radio of its own - the upstream firmware's own board-feature table explicitly disables Bluetooth for this target - and wardriving logs (Wi-Fi scans tagged with GPS coordinates) are relayed over UART to the Flipper Zero's own microSD card.","honest_take":"This is the official $35 Flipper Zero Wi-Fi Devboard with a GPS module and antenna added, resold for $120 - the markup buys someone else's soldering and a 3D-printed shell, not new silicon. It's also a direct head-to-head with BPM Circuits' NetNinja board, which costs $20 less ($100): the underlying Marauder firmware's own board-configuration file shows this board's stock 'MARAUDER_FLIPPER' target ships with Bluetooth explicitly disabled (`HAS_BT` is commented out), while the NetNinja's board target ships with it enabled. So the cheaper NetNinja is also, on paper, the more capable one - it can do BLE scanning and spam on top of the wardriving that both boards do, while this board is Wi-Fi- and GPS-only. What this board has going for it instead is that it tracks the current, actively-maintained upstream Marauder release (v1.16.0 at last check) rather than a vendor fork frozen years behind, so it should keep gaining features the NetNinja's stale fork won't. Neither board carries its own storage - both write to the Flipper's SD card - and as of September 2026 the seller has stopped taking orders, so it isn't purchasable right now regardless.","aliases":["Texas Flipper Wardriving Board","Flipper WiFi Devboard + GPS (Texas Flipper Boards)"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_deauth_5":"no","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"unknown","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","wifi_wardriving":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","standalone_untethered":"no","scriptable":"partial","ble_scan":"no","ble_advertise":"no","ble_tracker_detect":"no","bt_classic":"no","detect_flipper":"no","detect_pineapple":"yes","detect_pwnagotchi":"yes","subghz_rx":"no","hf_1356_read":"no","lf_125khz_read":"no","ir_tx":"no","usb_hid_inject":"no","nrf24_scan":"no","mousejack":"no","zigbee":"no"},"legal":{"risk_level":"medium","notes":"Owning the board and passively wardriving/logging is legal in most places."},"ecosystem":{"community":"commercial","docs_quality":"poor","last_release":null,"app_store":"No - relies on the Flipper Zero Marauder companion app and upstream Marauder firmware releases","abandoned_risk":"medium"}},{"id":"flipper-wifi-devboard","hardware_id":"flipper-wifi-devboard","name":"Flipper Zero Wi-Fi Dev Board","firmware":"Official","firmware_kind":"stock","vendor":"Flipper Devices","category":"accessory","subcategory":"wifi-addon","status":"out-of-stock","price_usd":35.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plugging it in is trivial; getting offensive Wi-Fi out of it means flashing third-party firmware and knowing what a deauth frame is and when sending one is legal.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A small ESP32-S2-WROVER board that presses onto the Flipper's GPIO header and gives it the Wi-Fi radio it does not otherwise have. Flipper's own firmware for it is a debug probe - Black Magic Probe SWD over Wi-Fi or USB, DAPLink over USB, and UART log capture that works even when the Flipper's OS is down. The Wi-Fi attack features everyone buys it for come from reflashing it with third-party firmware such as ESP32 Marauder.","honest_take":"Two things to get straight. First, this board is where every 'Flipper Zero Wi-Fi hack' video actually happens - the Flipper is just a screen, keypad and battery; the ESP32 does all of it, and you could flash the same Marauder firmware onto a $10 ESP32 dev board. Second, and less well known: the ESP32-S2 has NO Bluetooth radio at all, so Marauder's BLE features - blespam, findmy, sniffbt, Flipper-detection - are compiled out and silently do nothing on this board. It is also single-core, 2.4 GHz only, and the module is EOL at Espressif. Third-party ESP32/ESP32-S3 boards in the same form factor cost about the same and keep Bluetooth. The official board's one real advantage is the thing the clones mostly skip: SWD debugging over Wi-Fi.","released":"2022","aliases":["WiFi Devboard","Wi-Fi Developer Board","ESP32-S2 devboard","Marauder board","FLP-M-WIFI"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"partial","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_deauth_5":"no","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_beacon_spam":"yes","wifi_karma":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"partial","wifi_ap_mode":"yes","packet_capture":"partial","detect_pineapple":"yes","detect_pwnagotchi":"yes","detect_flipper":"no","ble_scan":"no","ble_spam_apple":"no","jtag_swd":"yes","uart":"yes","web_ui":"yes","gps":"addon","sd_logging":"addon"},"legal":{"risk_level":"medium","notes":"The board itself is an unremarkable ESP32 development board and is not restricted anywhere we could find - it is the Flipper it attaches to that attracts import attention, not this."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2025-09","app_store":"Yes - Marauder companion and Evil Portal ship in the official Flipper app catalog, though the ESP-side firmware is third-party","abandoned_risk":"medium"}},{"id":"fpga-nfc","hardware_id":"fpga-nfc","name":"FPGA-NFC","firmware":"Stock","firmware_kind":"diy","vendor":"WangXuan95 (independent developer)","category":"rfid-nfc","subcategory":"hf-reader-diy","status":"diy-only","price_usd":20.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"You are writing and debugging the ISO14443A PHY and MAC layers yourself in Verilog, then soldering an analogue front end and tuning a 4-turn antenna coil by hand. This is an RF and digital-logic project, not a 'buy and flash' tool.","build_effort":"full-diy","stealth":"overt","form_factor":"board","summary":"A from-scratch ISO14443A card reader built entirely in FPGA logic and a handful of discrete parts (a 3Msps AD7276B ADC, an FDV301N MOSFET, a diode envelope detector and a 4-turn coil) instead of a dedicated NFC chip like the PN532 or ST25R3916. It talks to a host PC over a plain 9600-baud serial line and has been demonstrated reading MIFARE Classic (M1) cards. It's a teaching/hobby project by a single developer, not a product.","honest_take":"This does exactly one useful thing that a $9 PN532 breakout doesn't: it proves the NFC PHY layer isn't magic - carrier generation, ASK demodulation via envelope detection, and the ISO14443A frame format are all implemented in visible, readable Verilog. But as a tool it is strictly worse than a PN532 or Proxmark3 for any practical RFID work: no write support beyond the protocol layer, no anti-collision beyond basic REQA/ANTICOLL, no MIFARE Classic crypto attacks, and a carrier that auto-shuts-off after 1.2 seconds of serial inactivity. Buy this only if the point is learning FPGA-based RF signal processing; buy a PN532 if the point is reading cards.","released":"2022","aliases":["FPGA NFC (RFID)","NFC_BreakoutBoard"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"partial","hf_1356_emulate":"no","mifare_classic_attacks":"no","mifare_desfire":"no","nfc_type4_ndef":"no","emv_read":"no","iso15693":"partial","felica":"no","magspoof":"no","nfc_relay":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","scriptable":"yes","standalone_untethered":"no","web_ui":"no","app_store":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A bare-metal 13."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2024-01","app_store":"No","abandoned_risk":"medium"}},{"id":"gatekeeper","hardware_id":"gatekeeper","name":"Gatekeeper","firmware":"Custom","firmware_kind":"diy","vendor":"n/a (DIY project, no commercial vendor)","category":"rfid-nfc","subcategory":"lf-covert-capture-clone","status":"diy-only","price_usd":220.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Everything Wiegotcha requires (donor-reader sourcing, covert install, Pi/GPIO wiring), plus setting up and debugging a Proxmark3 client driven through expect scripts on the Pi.","build_effort":"full-diy","stealth":"implant","form_factor":"box","summary":"Gatekeeper forks Wiegotcha and adds a USB-attached Proxmark3 so a captured Wiegand ID from the same HID Maxiprox 5375/Indala ASR-620/HID R90 donor-reader build can be cloned to a blank card on the spot: submitting the captured ID through the web UI runs an expect script that drives the Proxmark3 to write the ID to a blank card, then re-scans to verify the clone matches.","honest_take":"Everything true of Wiegotcha applies here too - same Pi-in-a-stolen-reader-shell core, same reliance on the donor reader's own decode, same 'the hard part is the donor reader and not getting caught, not the electronics.' What Gatekeeper genuinely adds is real: gatekeeper_webserv.py's source shows it actually shells out to a Proxmark3 clone-and-verify flow, not just a README promise (and Wiegotcha's own README explicitly lists this as an unimplemented 'future plan', confirming the delta). But look closely and the clone/scan regex only recognizes HID Prox and Indala tag responses - despite the README listing an HID R90 (13.56MHz iClass) donor option, no iClass-specific clone handling was found in the code, so treat the iClass claim as unverified. It's a low-activity single-contributor project (19 stars, last commit April 2024, no releases) forked from an already-dead upstream - expect to patch things yourself.","released":"2018","aliases":["Long Range RFID Stealing and Cloning"],"capabilities":{"lf_125khz_read":"partial","lf_125khz_write":"yes","lf_125khz_emulate":"no","hf_1356_read":"partial","hf_1356_write":"no","mifare_classic_attacks":"unknown","standalone_untethered":"yes","wifi_ap_mode":"yes","sd_logging":"yes","web_ui":"yes","scriptable":"yes","gps":"no","wiegand_tap":"yes"},"legal":{"risk_level":"high","notes":"Same analysis as Wiegotcha, plus an added step: Gatekeeper doesn't just intercept a badge ID, it clones it to a working card in the field via an attached Proxmark3."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2024-04","app_store":"n/a","abandoned_risk":"high"}},{"id":"ghost-esp-generic-esp32","hardware_id":"generic-esp32-devboard","name":"Generic ESP32 dev board (Ghost ESP)","firmware":"Ghost ESP","firmware_kind":"community","vendor":"Various (Espressif reference design, many resellers)","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"diy-only","price_usd":8.5,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"You must pick a matching build from the final release zip set, flash it with esptool, and accept that nothing will ever be fixed.","build_effort":"flash-only","stealth":"discreet","form_factor":"board","summary":"Ghost ESP was an ESP-IDF Wi-Fi and BLE pentest firmware with a web UI, a serial command line and a Flipper Zero companion app, covering scanning, deauth, beacon spam, evil portals, wardriving and some novelty attacks against Chromecast/DIAL and TP-Link devices. Its maintainer archived it in April 2025.","honest_take":"Do not start here. The repo is archived and the README says outright that the project is dead and will not return, the last release was March 2025, and the maintainer has since moved on to unrelated projects. Its 230 forks contain nobody with meaningful traction - every actively-pushed fork has zero stars - so there is no successor to migrate to. Anything Ghost ESP did, ESP32 Marauder and Bruce both still do, on the same hardware, with active maintenance. The only reason to touch it now is historical curiosity or because you already have a device with it flashed. Its genuinely distinctive bits - the DIAL/Chromecast casting attack and the TP-Link smart-device probe - are the parts no maintained firmware directly replaced. Its Wi-Fi attacks were also frozen in 2025, before this mattered as much: deauth is defeated by 802.11w/PMF, which WPA3 makes mandatory, and nobody is going to update this firmware to work around that.","released":"2024","aliases":["GhostESP","Ghost ESP32"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_wardriving":"yes","wifi_probe_sniff":"yes","packet_capture":"yes","ble_scan":"yes","detect_skimmer":"yes","detect_pineapple":"yes","detect_pwnagotchi":"yes","bt_classic":"no","gps":"addon","gps_wardrive_log":"addon","web_ui":"yes","scriptable":"partial","sd_logging":"partial","subghz_rx":"no","hf_1356_read":"no","usb_hid_inject":"no"},"legal":{"risk_level":"medium","notes":"MIT-licensed and freely distributed; the archive is still public."},"ecosystem":{"community":"dead","docs_quality":"sparse","last_release":"2025-03","app_store":"No - there was a Flipper Zero companion app, also last updated March 2025","abandoned_risk":"already-abandoned"}},{"id":"generic-125khz-handheld-copier","hardware_id":"generic-125khz-handheld-copier","name":"Generic handheld 125 kHz RFID copier (EM4100/T5577)","firmware":"Stock (unbranded)","firmware_kind":"stock","vendor":"Various unbranded Chinese manufacturers (Amazon, AliExpress, eBay)","category":"rfid-nfc","subcategory":"lf-cloner","status":"available","price_usd":15.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Two buttons: read, write.","build_effort":"assembled","stealth":"discreet","form_factor":"handheld","summary":"The USD 15 blue handheld 'RFID copier' sold everywhere. It reads an EM4100/TK4100 tag and writes the same ID onto a rewritable T5577 or EM4305 blank. Included here because it is the single most commonly bought RFID tool by beginners and almost none of them know what it cannot do.","honest_take":"Buyer beware. These copy an unencrypted 125 kHz ID and nothing else - one Amazon listing says it outright: 'It's not for any HID type Card.' It cannot touch MIFARE, DESFire, iCLASS or any 13.56 MHz credential; the 'multi-frequency' versions only copy a 13.56 MHz UID onto a magic card, which modern readers check against sector data anyway. Worse, on some models writing a Wiegand-format HID clone permanently locks the T5577 blank. If you need to work with real access-control systems, a Proxmark or Chameleon is the honest starting point; if you only want to duplicate an apartment fob, this is genuinely all you need.","released":"2015","aliases":["Blue RFID copier","125kHz duplicator","RFID cloner"],"capabilities":{"lf_125khz_read":"partial","lf_125khz_write":"partial","lf_125khz_emulate":"no","hf_1356_read":"no","mifare_classic_attacks":"no"},"legal":{"risk_level":"medium","notes":"Sold openly as a consumer product for duplicating your own fobs."},"ecosystem":{"community":"dead","docs_quality":"none","last_release":"n/a","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"ggtag","hardware_id":"ggtag","name":"GGtag","firmware_kind":"stock","vendor":"Eurolan Ltd (design by Radoslav Gerganov)","category":"rfid-nfc","subcategory":"lf-emulator-epaper-badge","status":"available","price_usd":45.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Programmed through a browser-based web-serial badge designer or by playing an audio clip - no toolchain needed for basic use; a Python package (ggtag on PyPI) exists for advanced/scripted use.","build_effort":"assembled","stealth":"discreet","form_factor":"wearable","summary":"An RP2040-based e-paper badge (3.52-inch display) that emulates 125kHz LF RFID tags. RFID emulation works by having the RP2040 compile and flash the existing open-source avrfid EM4100-simulator firmware onto an onboard ATtiny85 co-processor at runtime, rather than through any dedicated RFID silicon. It can be programmed over USB serial, a browser's Web Serial API, or acoustically using the ggwave FSK audio protocol. It is a genuinely single-purpose RFID device (LF emulate only) wrapped in a general-purpose e-paper badge platform.","honest_take":"It only emulates - GGtag has no reader/scan hardware at all, so it can replay a tag ID you already know, but it cannot capture a badge from someone walking by the way a Proxmark or a covert Wiegand tap can. The '125kHz emulation' isn't a from-scratch implementation either: on each RFID program event the RP2040 compiles and flashes a fresh copy of the existing open-source avrfid project onto the ATtiny85, reusing a technique that predates this product by well over a decade. What's genuinely novel is the e-paper badge form factor and the audio/web-serial programming path, not the RFID capability itself.","released":"2023","aliases":[],"capabilities":{"lf_125khz_emulate":"yes","lf_125khz_read":"no","lf_125khz_write":"no","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","iso15693":"no","felica":"no","nfc_relay":"no","magspoof":"no","scriptable":"yes","standalone_untethered":"partial","web_ui":"partial","sd_logging":"no"},"legal":{"risk_level":"low","notes":"Emulating a 125kHz tag ID you legitimately captured (e."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":null,"app_store":"n/a","abandoned_risk":"medium"}},{"id":"glinet-ar300m-pentest-dropbox","hardware_id":"glinet-ar300m","name":"GL.iNet GL-AR300M (as a Wi-Fi Pineapple alternative)","firmware":"Custom","firmware_kind":"community","vendor":"GL Technologies (GL.iNet)","category":"wifi","subcategory":"drop-box-router","status":"available","price_usd":37.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"You are building the toolkit yourself on OpenWrt - there is no attack UI.","build_effort":"flash-only","stealth":"discreet","form_factor":"box","summary":"The honest answer to 'what competes with a Wi-Fi Pineapple': nobody sells one, so people buy a cheap OpenWrt travel router and build it themselves. The GL-AR300M is the most commonly recommended of these - a QCA9531 router with 128 MB RAM and 16 MB flash that will run hostapd, a captive portal, a VPN tunnel home and a small package set.","honest_take":"Be clear about what you are buying: this is a plain travel router with no security firmware and no attack tooling. It is 2.4 GHz 802.11n only, its radio does not do the multi-radio tricks a Pineapple does, and 16 MB of flash fills up fast (an external USB drive or the NAND variant helps). What you get for USD 37 instead of USD 300+ is a legitimate, boring-looking box on which you install exactly what you need - and a lot of homework.","released":"2017","aliases":["GL-AR300M","Shadow","Mango-class travel router"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_ap_mode":"yes","wifi_evil_twin":"partial","wifi_captive_portal":"partial","vpn_exfil":"yes","packet_capture":"yes","scriptable":"yes","web_ui":"yes"},"legal":{"risk_level":"medium","notes":"The router itself is an ordinary consumer product."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026 (OpenWrt)","app_store":"No - OpenWrt package repositories","abandoned_risk":"low"}},{"id":"glasgow-interface-explorer","hardware_id":"glasgow-interface-explorer","name":"Glasgow Interface Explorer","firmware":"Stock","firmware_kind":"stock","vendor":"1BitSquared (manufacture); designed by Catherine 'whitequark'","category":"hardware-debug","subcategory":"fpga-interface-tool","status":"out-of-stock","price_usd":179.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"The applet model is elegant but assumes you know what interface you are talking to; adding a new applet means writing Amaranth HDL.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An FPGA-based digital interface multitool that reconfigures its logic for each protocol rather than bit-banging from a microcontroller. It handles UART, SPI, QSPI, I2C, JTAG and SWD, debugs ARM7TDMI, ARC and MIPS cores, reads 24-series I2C EEPROMs and 25-series SPI flash, and from revD upwards includes a logic analyzer. Certified open hardware by OSHWA.","honest_take":"The FPGA is not a gimmick - it is why Glasgow can analyse SPI and QSPI at around 100 MHz and hold precise timing that an FT2232H or an RP2040 cannot. It is also the most technically ambitious tool in this batch and the hardest to buy: production runs in batches, revC is out of stock, and revD has been in pre-launch for a while. If you need something today, get a Tigard. Get a Glasgow if you are doing genuine reverse engineering of unusual or high-speed interfaces and are comfortable in a Python-and-HDL toolchain.","released":"2019","aliases":["Glasgow","Glasgow revC","Glasgow revD"],"capabilities":{"uart":"yes","i2c":"yes","spi_flash_dump":"yes","jtag_swd":"yes","logic_analyzer":"partial","glitching":"no","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A bench instrument with no radio."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No - but the applet system is effectively a plugin catalogue in the repository","abandoned_risk":"low"}},{"id":"glitchcaster","hardware_id":"glitchcaster","name":"GlitchCaster","firmware_kind":"n/a","vendor":"Diffused Tactics","category":"hardware-debug","subcategory":"emfi-injection","status":"vaporware","price_is_estimate":false,"skill_level":"expert","skill_note":"It ships with no built-in controller - you must supply and program your own PWM/GPIO source to actually time and fire pulses, on top of the usual EMFI skill (finding a fault-sensitive spot and timing window on a live target) and the safety knowledge to handle a device that stores hundreds of volts.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"An open-hardware EMFI (electromagnetic fault injection) probe head from a small Colorado-based team (Diffused Tactics), explicitly built on Colin O'Flynn's open-source PicoEMP design - the same design behind NewAE's own ChipSHOUTER-PicoEMP kit already in this database. It generates a roughly 250V pulse through a leaded or SMA probe coil via an LDA111/ATB3225-based flyback circuit and a 630V/470nF storage capacitor, but unlike PicoEMP it deliberately ships with no built-in controller - instead it uses 40mm-fan mounting so it can be bolted to a 3D printer or CNC head for repeatable XYZ-staged glitch mapping, with a coil adapter that accepts either leaded or SMA probe coils interchangeably.","honest_take":"Do not confuse 'inspired by PicoEMP' with 'better than PicoEMP' - GlitchCaster is explicitly the same ~250V flyback circuit, and PicoEMP is open-source CC-BY-SA hardware you can build yourself or buy pre-built as NewAE's own ChipSHOUTER-PicoEMP Kit for $100. What GlitchCaster is actually selling is not more voltage or a new attack capability, it is mechanical: 40mm-fan mounting so you can bolt it to a 3D printer or CNC gantry for repeatable XYZ probe positioning, plus a coil adapter that takes both leaded and SMA coils, neither of which the stock PicoEMP kit provides out of the box. Whether that mechanical convenience is worth paying for over a $100 PicoEMP kit plus your own 3D-printed mount depends entirely on the eventual price, which does not exist yet - as of this check the project has never launched a Crowd Supply campaign, has zero updates, and its promised open-source GitHub repo does not exist publicly yet either, so right now there is nothing to buy and nothing independently verifiable beyond the campaign page's own claims. Treat every capability claim here as vendor-stated until backers actually receive hardware.","aliases":[],"capabilities":{"glitching":"addon","standalone_untethered":"no","scriptable":"claimed","jtag_swd":"no","uart":"no","i2c":"no","spi_flash_dump":"no","logic_analyzer":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A bench EMFI tool with no radio and no offensive capability of its own without a target you deliberately attack; legal to own everywhere."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"high"}},{"id":"glytch-ethernet-module-pineapple-pager","hardware_id":"glytch-ethernet-module-pineapple-pager","name":"Glytch Ethernet Module for Pineapple Pager","firmware_kind":"n/a","vendor":"Glytch, in collaboration with Hak5","category":"accessory","subcategory":"wired-network-addon","status":"available","price_usd":40.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Snaps onto a WiFi Pineapple Pager; no configuration beyond the Pager's own software.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A 3D-printed, hand-assembled add-on for the WiFi Pineapple Pager built around a Realtek RTL8152B USB-to-Ethernet controller, giving the otherwise Wi-Fi-only Pager a wired RJ45 port for LAN-based payload deployment - functionally similar in role to plugging in a LAN Turtle, but as an accessory to the Pager rather than a standalone device.","honest_take":"The RTL8152B is a completely generic USB-Ethernet controller chip, the same one found in countless no-name $10 USB-to-Ethernet dongles - there is no tap, capture, or security-specific circuitry of any kind in this module. You are paying Hak5/Glytch prices almost entirely for the fitted 3D-printed case that clips onto the Pager and the brand, not for anything the chip itself couldn't do in a five-dollar dongle. It only has value if you already own a Pineapple Pager and specifically want wired-LAN payload delivery from it.","aliases":["Glytch Ethernet Mod for Pager"],"capabilities":{"usb_ethernet_attack":"no","standalone_untethered":"no","web_ui":"no","app_store":"no","wifi_scan_24":"no","ble_scan":"no","gps":"no","sd_logging":"no","usb_hid_inject":"no","ethernet_tap_passive":"no","packet_capture":"no"},"legal":{"risk_level":"low","notes":"The module itself is a plain network interface adapter and legal everywhere; legal risk depends entirely on how the host WiFi Pineapple Pager is used."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"glytch-gps-mod-pager","hardware_id":"glytch-gps-mod-pager","name":"Glytch GPS Mod for Pager","firmware_kind":"n/a","vendor":"Glytch, in collaboration with Hak5","category":"accessory","subcategory":"pineapple-pager-gps","status":"available","price_usd":60.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plugs into the Pager's USB port; the only setup step is picking the right serial device and baud rate in the Pager's Settings > GPS menu.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A small 3D-printed, hand-assembled add-on carrying a Quectel LC86-series multi-constellation GNSS chipset, connecting to the WiFi Pineapple Pager over USB to geotag its Wi-Fi survey and attack logs via the Pager's built-in gpsd support. It requires a WiFi Pineapple Pager as the host - it has no function on its own.","honest_take":"This is exactly what it says: a GPS receiver in a box, nothing more. It adds Wigle-compatible geotagging to wardriving logs the Pager already collects - it does not add any new attack capability. Accuracy is ordinary consumer GNSS (a few meters outdoors with clear sky, degraded or absent indoors), fine for venue-scale wardriving, not for anything needing tight geofence precision. It's a genuinely single-purpose accessory, so don't expect much beyond 'the Pager now knows where it is' - and remember it does nothing without a Pager to plug into.","released":"2026","aliases":["Glytch GPS Module for Pineapple Pager"],"capabilities":{"gps":"yes","gps_wardrive_log":"yes","sd_logging":"no","standalone_untethered":"no","web_ui":"no","scriptable":"no"},"legal":{"risk_level":"low","notes":"A passive GNSS receiver; receiving GPS signals is unregulated nearly everywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"n/a","abandoned_risk":"low"}},{"id":"glytch-gps-module-pineapple-pager","hardware_id":"glytch-gps-module-pineapple-pager","name":"Glytch GPS Module for Pineapple Pager","firmware_kind":"n/a","vendor":"Glytch, in collaboration with Hak5","category":"accessory","subcategory":"wardriving-addon","status":"available","price_usd":79.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Snaps onto a WiFi Pineapple Pager; no configuration beyond the Pager's own software.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A GPS add-on module for the WiFi Pineapple Pager built around a Quectel LC86 multi-constellation GNSS chipset, adding location tagging to the Pager's wardriving/recon sessions so captured networks and clients can be geo-correlated (WiGLE-compatible).","honest_take":"This only makes sense if you already own a WiFi Pineapple Pager - it has no standalone function. You're paying Hak5/Glytch prices for a small breakout of a GNSS chip (the Quectel LC86 is a commodity part used across many drone/wardriving projects, typically a few dollars to a low double digits on its own) fitted with a connector and case to match the Pager, plus the fitted 3D-printed housing. If you're building your own wardriving rig on a Flipper Zero, ESP32 board, or similar, a generic NEO-6M/LC86-class GPS breakout will do the same geotagging job for a fraction of this price - you're buying fit and finish, not unique capability.","aliases":["Glytch GPS Mod for Pager"],"capabilities":{"gps":"yes","gps_wardrive_log":"yes","wifi_wardriving":"addon","standalone_untethered":"no","sd_logging":"no","web_ui":"no","app_store":"no","usb_hid_inject":"no","ble_scan":"no","hf_1356_read":"no"},"legal":{"risk_level":"low","notes":"GPS reception hardware is legal everywhere to own and use; legality of the underlying wardriving/capture activity follows the host Pineapple Pager's own legal considerations."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"glytch-mesh-mod-pager","hardware_id":"glytch-mesh-mod-pager","name":"Glytch Mesh Mod for Pager","firmware":"MeshtasticD","firmware_kind":"third-party-product","vendor":"Glytch (GlytchTech), sold through Hak5","category":"accessory","subcategory":"lora-mesh-addon","status":"available","price_usd":60.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Physical install is described as roughly 5 minutes; the MeshtasticD service starts automatically, but getting real use out of a mesh node still requires understanding Meshtastic's own network concepts.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A 3D-printed, hand-assembled clip-on module adding an 868/900 MHz radio with an integrated antenna to the Hak5 WiFi Pineapple Pager, installing the standard MeshtasticD daemon to give the Pager a decentralized mesh-messaging channel independent of Wi-Fi or cellular infrastructure.","honest_take":"This turns the Pineapple Pager into a Meshtastic mesh node, not into a sub-GHz attack tool - despite living in the 'subghz' candidate bucket, its actual job is off-grid team communication, closer in spirit to Retia's Nibble boards than to a replay or jamming device. The vendor does not publish the exact radio IC, so treat range and throughput claims as generic LoRa/Meshtastic performance until tested. Buying it from Hak5 directly ($60) is meaningfully cheaper than the EU reseller lab401's listing (EUR79, roughly $85, and shown sold out during this research pass) - check both before paying reseller markup, and note that Glytch also sells GPS and Ethernet mods for the same Pager if mesh isn't the only expansion you want.","aliases":["Glytch Mesh Module for Pineapple Pager"],"capabilities":{"subghz_rx":"claimed","subghz_tx":"claimed","subghz_replay":"no","subghz_rolling_code":"no","subghz_external_antenna":"unknown","standalone_untethered":"no","scriptable":"addon","sd_logging":"no","gps":"no","app_store":"no","web_ui":"addon","ble_scan":"no","ir_tx":"no","hf_1356_read":"no","mesh_lora":"yes"},"legal":{"risk_level":"low","notes":"Standard Meshtastic operation in the license-exempt 868/900 MHz ISM bands; staying within regional power/duty-cycle limits (ETSI EN 300 220 in Europe, FCC Part 15 in the US) keeps this in normal amateur/IoT-radio territory, not the higher-risk category of devices that replay or jam licensed signals."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"greatfet-one","hardware_id":"greatfet-one","name":"GreatFET One","firmware":"Stock (Great Scott Gadgets)","firmware_kind":"stock","vendor":"Great Scott Gadgets","category":"hardware-debug","subcategory":"usb-interface-tool","status":"available","price_usd":90.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Enormously flexible, which is another way of saying it does not tell you what to do - you write Python against a general-purpose interface API.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A general-purpose USB-attached interface board with 100 expansion pins, two USB ports, and a Python API covering SPI, I2C, UART, JTAG, logic analysis, ADC/DAC and USB peripheral emulation. It is the successor to the GoodFET and the most common hardware for running Facedancer.","honest_take":"Its identity is genuinely blurry and that is the main thing to understand before buying. It is not the best UART adapter (Tigard is cheaper and better labelled), not the best logic analyser (Glasgow, or a $10 dedicated one), and not the best USB analyser (Cynthion, from the same vendor). What it is best at is being the one board that can do a bit of everything from Python, and being solid Facedancer hardware for USB device emulation. If you have a specific problem, a specific tool beats it; if you do not yet know what your problem is, it is a reasonable thing to own.","released":"2019","aliases":["GreatFET","GSG-GF1"],"capabilities":{"uart":"yes","i2c":"yes","spi_flash_dump":"yes","jtag_swd":"partial","logic_analyzer":"yes","glitching":"no","usb_hid_inject":"yes","usb_mass_storage":"yes","packet_capture":"partial","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A bench instrument with no radio, legal to own and use everywhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"hackrf-portapack-h2-mayhem","hardware_id":"hackrf-portapack-h2","name":"HackRF + PortaPack H2","firmware":"Mayhem","firmware_kind":"community","vendor":"Multiple third-party manufacturers (no single official vendor)","category":"sdr","subcategory":"handheld-sdr","status":"available","price_usd":120.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Same as the H4M, plus the extra burden of working out whether the board you received is a good one.","build_effort":"assembly","stealth":"overt","form_factor":"handheld","summary":"The previous-generation PortaPack and still the most widely sold. It does the same job as the H4M - screen, controls, battery, microSD, standalone operation of a HackRF via Mayhem - with an older resistive-feeling screen, micro-USB, no speaker on the base variants, and voltage-only battery monitoring.","honest_take":"The H2's specific defects are worth knowing before you buy the cheaper option: the encoder knob doubles as the power control and routinely switches the unit on inside a bag, and battery monitoring is a crude voltage reading rather than a fuel gauge. The bigger risk is the counterfeit tier below it - 'H3' boards use proprietary firmware that Mayhem does not support and nobody maintains, and boards that look visually different from the reference design or arrive with a bundled firmware .bin file are a warning sign. If your budget stretches, the H4M fixes essentially all of this.","released":"2017","aliases":["PortaPack H2","PortaPack H2+","HackRF Portapack"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"no","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","ble_sniff":"partial","sd_logging":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Identical to the H4M: receiving is generally lawful, one-button transmitting on licensed bands is not, and replaying a captured signal to actuate something you do not own is usually a separate offence."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026","app_store":"No","abandoned_risk":"low"}},{"id":"hackrf-portapack-h4m-mayhem","hardware_id":"hackrf-portapack-h4m","name":"HackRF + PortaPack H4M","firmware":"Mayhem","firmware_kind":"community","vendor":"OpenSourceSDRLab (PortaPack H4M design); Mayhem firmware by the portapack-mayhem community","category":"sdr","subcategory":"handheld-sdr","status":"available","price_usd":190.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Mayhem's menus make individual functions easy to launch, but interpreting what you see - and knowing which buttons are illegal to press - still needs RF knowledge.","build_effort":"assembly","stealth":"overt","form_factor":"handheld","summary":"A screen, battery, speaker and navigation controls that bolt onto a HackRF to make it a standalone handheld radio tool, with the community Mayhem firmware doing the actual work. The H4M is the 2025-generation board from OpenSourceSDRLab, adding USB-C, a real power switch, a speaker and microphone, a proper battery fuel gauge, a matte 3.2-inch touchscreen and an I2C-capable GPIO port.","honest_take":"Read this part carefully: Great Scott Gadgets does not make the PortaPack and never has. The original was a ShareBrained Technology design from 2014, ShareBrained stopped manufacturing years ago, and what you can buy today is a field of third-party boards of wildly varying quality. Almost every 'HackRF PortaPack' bundle on Amazon and AliExpress ships a cloned HackRF, so you are buying clone silicon and sending nothing to the people who designed it. The hardware is also not the product - Mayhem is. Without Mayhem the PortaPack is a screen that does very little, and the radio underneath is still an 8-bit half-duplex HackRF with all the same limits.","released":"2025","aliases":["PortaPack H4M","HackRF Portapack H4","Mayhem Signature Edition"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"no","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_bruteforce":"partial","subghz_external_antenna":"yes","ble_sniff":"partial","ble_advertise":"partial","wifi_scan_24":"partial","gps":"addon","sd_logging":"yes","standalone_untethered":"yes","app_store":"no"},"legal":{"risk_level":"high","notes":"This is the highest-legal-risk item in this batch, because it puts one-button transmit into a handheld you can carry around."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026","app_store":"No - apps ship inside the firmware image; stable and nightly builds on GitHub","abandoned_risk":"low"}},{"id":"hackrf-one","hardware_id":"hackrf-one","name":"HackRF One","firmware":"Stock (Great Scott Gadgets)","firmware_kind":"stock","vendor":"Great Scott Gadgets","category":"sdr","subcategory":"wideband-transceiver","status":"out-of-stock","price_usd":330.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"It is a bare RF front end - you supply the DSP knowledge, the antenna for the band, and the understanding of why your signal looks wrong.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A half-duplex, 8-bit software-defined radio covering 1 MHz to 6 GHz that both receives and transmits, tethered to a computer over USB 2.0. It is the reference open-source wideband SDR and the one nearly every RF security tutorial is written against. Great Scott Gadgets publishes the full schematics and firmware.","honest_take":"Two specs people gloss over will bite you: it is 8-bit and it is half-duplex. Eight bits of ADC gives roughly 48 dB of dynamic range, so a strong nearby signal will bury everything else in the same capture - an RTL-SDR is 8-bit too, but a $150 Airspy or a 12-bit PlutoSDR will genuinely hear things a HackRF cannot. Half-duplex means it physically cannot listen while transmitting, which rules out the whole class of attacks that need to see a response mid-transmission. It is also a transmitter, and casually transmitting is how people get in real legal trouble.","released":"2014","aliases":["HackRF","HackRF One r9"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"no","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_external_antenna":"yes","ble_sniff":"partial","wifi_scan_24":"partial","packet_capture":"partial","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"high","notes":"Owning and receiving with a HackRF is legal in most countries, and listening across the spectrum is generally unrestricted in the US (with the notable exception of intercepting cellular voice)."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2025","app_store":"No - it is a peripheral; software lives on the host (GNU Radio, SDRangel, SDR++, Universal Radio Hacker)","abandoned_risk":"low"}},{"id":"hackrf-pro","hardware_id":"hackrf-pro","name":"HackRF Pro","firmware":"Stock (Great Scott Gadgets)","firmware_kind":"stock","vendor":"Great Scott Gadgets","category":"sdr","subcategory":"wideband-transceiver","status":"available","price_usd":400.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Identical learning curve to HackRF One; the improvements are analogue, not conceptual.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The successor to the HackRF One: a half-duplex 100 kHz - 6 GHz software-defined radio with an on-board TCXO, an FPGA in place of the One's CPLD, better shielding and the DC spike fixed. It is a straight hardware refresh, not a new platform - the software you already use with a HackRF One works with it unchanged.","honest_take":"It fixes the annoyances rather than the fundamentals. It is still half-duplex and still 8-bit at full rate, so the dynamic-range and simultaneous-TX/RX limits of the original are unchanged - the extended-precision 16-bit mode only works at low sample rates. Worth the extra $70 over a HackRF One mostly for the built-in TCXO and the missing DC spike, both of which you would otherwise pay for or work around. If you already own a working HackRF One, this is not an upgrade that unlocks new attacks.","released":"2025","aliases":["HackRF Pro SDR"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"no","subghz_rx":"yes","subghz_tx":"yes","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"high","notes":"Same position as HackRF One: receiving is broadly permitted, transmitting on licensed bands without authorisation is a criminal offence in most countries."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2025","app_store":"No - host software only","abandoned_risk":"low"}},{"id":"sbcomponents-hackypi","hardware_id":"sbcomponents-hackypi","name":"HackyPi","firmware":"HackyPi-Software","firmware_kind":"community","vendor":"SB Components","category":"usb-hid","subcategory":"badusb-board","status":"out-of-stock","price_usd":37.99,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-play, no drivers required, drag-and-drop CircuitPython programming with a 1.14in TFT to watch what's executing; the RP2040's Thonny/CircuitPython workflow is friendlier than raw Arduino sketches for first-time buyers.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"An RP2040-based (Cortex-M0+ dual-core) BadUSB board with a 1.14in TFT display and SD card slot, open-source and programmed in CircuitPython/Python via drag-and-drop. Cross-platform payload examples target Windows, Mac and Linux.","honest_take":"It has a screen and SD storage that most sub-$40 BadUSB sticks in this batch don't, and it's genuinely open source with 245 GitHub stars - real community traction for a hobbyist board. But the published example payloads (shutting down Windows, deleting Mac browser history, grabbing a camera snapshot) are closer to novelty pranks than the kind of payload library a red-team engagement would use, and no VID/PID spoofing is documented anywhere in available sources - if hardware-identity spoofing matters to your use case, this isn't confirmed to offer it. As with HackyPi's peers here, it's currently unpurchasable: the seller's Tindie store is on a break.","aliases":[],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","usb_exfil":"unknown","usb_keylogger":"no","hid_remote_trigger":"no","usb_payload_lang":"yes","scriptable":"yes","sd_logging":"yes","standalone_untethered":"yes","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning the device is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"unknown exact date; repo shows 147 commits and is actively starred (245)","app_store":"No","abandoned_risk":"medium"}},{"id":"hacphone-nexus5x","hardware_id":"hacphone-nexus5x","name":"HacPhone - Rooted NetHunter/Kali Nexus 5X","firmware":"Kali NetHunter","firmware_kind":"third-party-product","vendor":"Unlimited Coverage (UCShop)","category":"multitool","subcategory":"pentest-phone","status":"available","price_usd":119.99,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Arrives rooted and pre-configured, so no prior experience rooting a phone or installing NetHunter is required, which is the entire value proposition given both are normally a free weekend project for someone already comfortable with Android.","build_effort":"assembled","stealth":"discreet","form_factor":"handheld","summary":"A 2015 Google Nexus 5X, rooted and pre-loaded with Kali NetHunter, sold as a ready-to-use mobile pentest platform: Wi-Fi auditing, Nmap/Wireshark-style network recon, basic web vulnerability testing, and Bluetooth/NFC assessment, all through NetHunter's standard app and chroot environment.","honest_take":"NetHunter itself is free and open source, and rooting a Nexus 5X and flashing it is a well-documented weekend project - what you are actually paying $120 for is someone else doing that setup, on hardware Google stopped patching in December 2018. That matters here specifically: this is a phone whose Android base has been unpatched for roughly eight years, running as your security-testing device, with all the exposure that implies for the device itself. On top of that, the Nexus 5X's internal Broadcom Wi-Fi chip is not reliably supported for monitor mode and packet injection in the wider NetHunter community's experience with this device class - most guides for phones like this recommend an external USB Wi-Fi adapter (an Alfa or similar RTL8812AU/RT3070-based unit) for real Wi-Fi cracking and deauth work, so 'WiFi cracking and deauthentication' as a bullet point is optimistic marketing rather than a guaranteed internal capability. If you can find any old, cheap, NetHunter-supported phone and 30 minutes of tutorial-following, you get the identical software for the cost of the used hardware alone.","aliases":["HacPhone"],"capabilities":{"wifi_scan_24":"yes","wifi_monitor_mode":"claimed","wifi_injection":"claimed","wifi_deauth_24":"claimed","wifi_scan_5":"unknown","bt_classic":"claimed","ble_scan":"claimed","hf_1356_read":"claimed","usb_hid_inject":"unknown","packet_capture":"yes","scriptable":"yes","web_ui":"no","app_store":"no","sd_logging":"unknown","subghz_rx":"no","gps":"yes","ir_tx":"no","hf_1356_write":"unknown","usb_mass_storage":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"medium","notes":"Same as any Wi-Fi/network pentest platform: scanning your own network is fine almost everywhere; deauthing or attacking networks you don't own or lack written authorization for is a computer-misuse offence in most countries."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"halehound-cyd-35-complete","hardware_id":"halehound-cyd-35-complete","name":"HaleHound-CYD 3.5\" Complete Unit Build","firmware":"HaleHound","firmware_kind":"third-party-product","vendor":"Jesse C. Hale (HaleHound)","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":235.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Hand-built and pre-flashed by the seller; buyer adds a battery and antennas but does no soldering or flashing themselves.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"The flagship assembled HaleHound: a Hosyond 3.5-inch ST7796U touchscreen CYD-style board hand-wired to a CC1101 sub-GHz radio, an NRF24L01+PA+LNA 2.4GHz radio, a PN532 NFC/RFID reader and a GPS module, running HaleHound's closed multi-protocol firmware. It is the only current HaleHound SKU that still includes the PN532 - the cheaper DIY kits dropped it.","honest_take":"This is the same firmware documented in detail on the already-tracked bare-CYD HaleHound entry, and every caveat there applies here too: it is marketed in places as open source and is not - the firmware repo holds only a README and a proprietary license, no code, and that license explicitly forbids redistribution or modification. What $235 actually buys over the $139-185 DIY kits below is someone else soldering and wiring in the discrete CC1101/nRF24/PN532/GPS modules by hand, plus the PN532 those kits no longer include. It still needs a battery and antennas bought separately, still cannot do BadUSB (no ESP32 in this class has native USB), and the CC1101 sub-GHz wiring documented for this firmware family tops out around 439MHz - it will not reach 868/915MHz gear. The 'Airoha RACE CVE' Bluetooth-headphone exploit is a genuinely current, specific attack, unusual to see actually implemented rather than just namedropped - but it targets a narrow list of affected headphone models, not Bluetooth broadly.","released":"2026","aliases":["HaleHound Complete Unit","HaleHound 3.5in"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_karma":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"yes","wifi_wardriving":"addon","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"claimed","ble_tracker_detect":"yes","ble_tracker_spoof":"claimed","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"yes","subghz_rolling_code":"partial","subghz_amplified":"unknown","nrf24_scan":"yes","mousejack":"yes","nrf24_jam":"claimed","hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"partial","mifare_classic_attacks":"yes","lf_125khz_read":"no","gps":"yes","gps_wardrive_log":"claimed","sd_logging":"yes","usb_hid_inject":"no","ir_tx":"no","detect_surveillance_cam":"yes","detect_skimmer":"yes","detect_drone":"yes"},"legal":{"risk_level":"high","notes":"This firmware ships jamming modules."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"No","abandoned_risk":"high"}},{"id":"high-boy-tentacleos","hardware_id":"high-boy","name":"High Boy","firmware":"TentacleOS","firmware_kind":"stock","vendor":"High Code","category":"multitool","subcategory":"rf-multitool","status":"preorder","price_usd":160.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The on-device UI is menu-driven and approachable, but this is beta firmware on a dual-MCU board where at least one headline feature is documented as not actually driving its radio yet.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"A Brazilian open-source handheld built on an unusual split: an ESP32-P4 application processor, which has no radio at all, driving a 2in colour LCD and USB, paired over SPI with an ESP32-C5 that provides dual-band 2.4 and 5 GHz Wi-Fi 6 and BLE. On top of that sit a CC1101 sub-GHz transceiver with a real .sub file stack, an SX1262 LoRa radio, an ST25R3916 NFC front end, 125 kHz RFID, infrared, microSD, haptics, a speaker and microphone, and a Game Boy emulator. The firmware and per-component documentation are published; the schematics are one revision behind.","honest_take":"Of everything in this group this is the most serious piece of engineering - forty-odd documented components, a Linux UI simulator, CI, and a genuine dual-band Wi-Fi implementation whose sniffer really does hop 5 GHz channels 36 to 48 and 149 to 165 rather than just 2.4. It is also the most honest about its own faults, which is how you learn that NFC does not work: the vendor's own documentation says the ST25R3916 shares an SPI bus whose MISO line is tied to LCD reset by a board jumper and cannot be read reliably, so every NFC screen runs a simulation model rather than the radio - while the marketing comparison table on the same company's website ticks NFC as native read, write and emulate. Similarly the site claims 125 kHz read/write/emulate when the shipping driver is a read-only serial reader module. Add that the firmware calls itself beta, that the only published schematics are for an older ESP32-S3 prototype the vendor labels an MVP, and that after 600,000 dollars raised nothing appears to have shipped, and this is a promising project rather than a product.","released":"2026","aliases":["HighBoy","High Boy V2","TentacleOS device"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"unknown","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_beacon_spam":"yes","wifi_captive_portal":"yes","wifi_ap_mode":"yes","wifi_probe_sniff":"yes","subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"unknown","subghz_rolling_code":"unknown","subghz_external_antenna":"partial","lf_125khz_read":"yes","lf_125khz_emulate":"unknown","hf_1356_read":"no","hf_1356_emulate":"no","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","usb_hid_inject":"yes","usb_payload_lang":"yes","ble_scan":"yes","ble_advertise":"yes","sd_logging":"yes","scriptable":"partial","web_ui":"partial","standalone_untethered":"yes","app_store":"no","gps":"no","sdr_rx":"no","zigbee":"no","detect_generic_wifi":"yes"},"legal":{"risk_level":"medium","notes":"Owning it would be legal in most places."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-08","app_store":"No","abandoned_risk":"medium"}},{"id":"hiletgo-pn532-kit","hardware_id":"hiletgo-pn532-kit","name":"HiLetgo PN532 NFC RFID Module Kit","firmware_kind":"n/a","vendor":"HiLetgo","category":"rfid-nfc","subcategory":"hf-reader-module","status":"available","price_usd":8.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"A bare breakout board - you wire it to a microcontroller or SBC over I2C/SPI/UART and run libnfc or a vendor SDK yourself; no standalone app.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A breakout board for NXP's PN532, the NFC controller chip found in the overwhelming majority of phones and consumer NFC readers, exposing I2C, SPI and UART (HSU) interfaces. It reads and writes NFC Type 1-4 tags and MIFARE Classic/Ultralight, and can do ISO18092 peer-to-peer and limited card emulation - it is the standard low-cost building block behind countless libnfc, Arduino and Raspberry Pi RFID projects.","honest_take":"This is genuinely the same silicon inside a large share of commercial NFC readers, not a toy chip - the PN532's read/write/P2P feature set is real, and NXP's own PN532 User Manual (UM0701-02) confirms full FeliCa support. But three things are commonly assumed and wrong: it does not do ISO15693 (a different chip family, e.g. ST25R3916, handles that); its 'card emulation' mode does not implement the MIFARE Classic authentication sequence as a target, so it can present static data but not fully impersonate an authenticating card; and DESFire (7-byte UID) detection is inconsistent across PN532 board variants - libnfc bug reports show Adafruit's version reliably sees DESFire/Ultralight/Jewel tags while cheaper Elechouse-style clones (which HiLetgo's board resembles) often see only 4-byte-UID MIFARE Classic cards. If you want a point-and-use device rather than a module to wire up yourself, a Flipper Zero or ACR122U is the better buy; if you're building your own project on a Pi or microcontroller, this is the standard part to reach for, just budget time for clone-board quirks.","aliases":["PN532 NFC/RFID breakout","PN532 V3 kit"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"partial","nfc_type4_ndef":"yes","felica":"yes","mifare_classic_attacks":"no","mifare_desfire":"partial","iso15693":"no","emv_read":"partial","magspoof":"no","nfc_relay":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no","scriptable":"yes"},"legal":{"risk_level":"low","notes":"A generic, widely-sold NFC reader/writer module identical in function to the chip inside most phones and payment terminals - owning and using one to read/write tags you have rights to is unremarkable almost everywhere."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":null,"app_store":"No - relies on libnfc and community libraries rather than a vendor app store","abandoned_risk":"low"}},{"id":"hitager","hardware_id":"hitager","name":"hitager","firmware":"Stock (kivijakola)","firmware_kind":"diy","vendor":"kivijakola (independent open-source project)","category":"rfid-nfc","subcategory":"automotive-transponder-tool","status":"diy-only","price_usd":25.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"Requires deep familiarity with NXP Hitag2/Hitag3/Hitag AES cryptography and automotive immobiliser systems, plus sourcing and wiring a separate PCF7991 reader board the project does not provide.","build_effort":"full-diy","stealth":"overt","form_factor":"board","summary":"A Windows GUI plus Arduino firmware combination for reading, writing, and cloning NXP Hitag-family low-frequency (125kHz) automotive immobiliser transponders - Hitag2, Hitag2+EE, Hitag2 Extended (including the BMW EE extension), Hitag3, Hitag AES, and Hitag Pro - plus VVDI Super Chip and specific BMW key part numbers (PCF7944/7945/7953). It relies on an NXP PCF7991 Advanced Base Station IC, which must be sourced from a compatible existing reader product (examples given: an iProg RFID Adapter, a Hitag2 v3.1 reader, or a ZedBull Mini) since the project does not sell or design its own RF front end.","honest_take":"This is a serious, narrow tool for one specific job - attacking NXP Hitag-family immobiliser transponders used across a large share of 2000s-2010s VAG/BMW/etc. keys - not a general RFID/NFC tool, and it has zero HF 13.56MHz capability (no Mifare, no general NFC, no EMV), so don't buy it expecting Flipper-style card cloning. It's also genuinely bring-your-own-hardware in a way the $25 headline cost obscures: the actual RF front end (a PCF7991-based reader) isn't sold by the project at all, so the real cost and difficulty of getting a working setup are both meaningfully higher than the Arduino-only estimate suggests. It has been quiet since a January 2023 last commit, so treat it as a stable-but-unmaintained reference tool rather than an actively supported one.","released":"2022","aliases":[],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"unknown","hf_1356_read":"no","mifare_classic_attacks":"no","iso15693":"no","emv_read":"no","scriptable":"yes","standalone_untethered":"no","web_ui":"no","app_store":"no","sd_logging":"no","cloud_c2":"no","usb_mass_storage":"no"},"legal":{"risk_level":"high","notes":"Transponder cloning tools for vehicle immobilisers sit in a genuinely higher-risk legal category than passive RFID/NFC readers: possessing and researching this kind of hardware is generally legal, but using it to clone or bypass an immobiliser on a vehicle you are not authorized to access is theft-adjacent conduct (unauthorized access to a motor vehicle), and several jurisdictions have specific statutes targeting tools connected to keyless/immobiliser vehicle theft (for example, preparatory-offense provisions in UK law)."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2023-01","app_store":"No","abandoned_risk":"high"}},{"id":"honeyhoney-apex-5","hardware_id":"honeyhoney-apex-5","name":"Honey Honey Apex 5 (ESP32 Marauder 5G Module)","firmware":"ESP32 Marauder (preloaded)","firmware_kind":"community","vendor":"Honey Honey Team / Honey Honey Lab (Australia)","category":"accessory","subcategory":"flipper-multiboard","status":"out-of-stock","price_usd":79.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Batch 2 is plug-and-play with default Flipper GPIO settings; Batch 1 needs you to hand-configure four separate GPIO mappings before anything works.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The most capable of the commodity Flipper multiboards: an ESP32-C5 with 5 GHz Wi-Fi running Marauder, two separate CC1101s dedicated to 433 MHz and 868 MHz with a hardware switch and indicator LEDs, an nRF24 for 2.4 GHz raw packet work, a GPS, and an SDXC slot, on five antennas. Documentation is unusually good for this market - a full manual with GPIO diagrams is published on GitHub.","honest_take":"This is what the generic multiboard category looks like when someone actually engineers it, and the vendor's own documentation is refreshingly honest - it states plainly that Batch 1 could not do Marauder wardriving because the ESP32 UART and the GPS UART collided on the Flipper's pins, and that Batch 2 exists to fix exactly that. That is the whole story of this product class in one sentence: the chips are cheap and interchangeable, the pin routing is the hard part. Two caveats before you buy: it is chronically sold out, and dedicating one CC1101 to 868 MHz is a European-centric choice - if you are in North America, 915 MHz devices sit outside where that radio is matched.","released":"2026","aliases":["Apex 5","ESP32 Marauder 5G Apex 5","Honey Honey Apex 5"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"partial","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"partial","wifi_ap_mode":"yes","ble_scan":"yes","ble_spam_apple":"yes","subghz_rx":"yes","subghz_tx":"yes","subghz_external_antenna":"yes","subghz_amplified":"no","subghz_replay":"yes","nrf24_scan":"yes","mousejack":"partial","gps":"yes","gps_wardrive_log":"partial","sd_logging":"yes","standalone_untethered":"partial"},"legal":{"risk_level":"medium","notes":"The board carries no restricted technology and we found no import bans."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-07","app_store":"Yes - the Flipper side uses community apps; the ESP32 side is Marauder","abandoned_risk":"medium"}},{"id":"hs-probe-proberrs","hardware_id":"hs-probe","name":"hs-probe","firmware":"hs-probe-firmware","firmware_kind":"stock","vendor":"probe-rs","category":"hardware-debug","subcategory":"jtag-swd-probe","status":"out-of-stock","price_usd":47.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Built for embedded developers who have hit USB Full-Speed throughput limits on cheaper probes; ships as a bare PCB, no beginner hand-holding.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"hs-probe is an open-hardware SWD/JTAG debug probe built around an STM32F723 (Cortex-M7 with an integrated USB 2.0 High-Speed PHY), designed for the probe-rs project. It enumerates as a CMSIS-DAP v1/v2 probe over genuine USB-HS (480 Mbit/s) rather than the USB Full-Speed (12 Mbit/s) most CMSIS-DAP probes are limited to, and includes a USB mux so the STM32's bootloader stays reachable for firmware recovery. Hardware is CERN-OHL-P v2 licensed with published schematics; firmware is dual Apache-2.0/MIT.","honest_take":"For most hobbyist STM32/nRF work, a $15 CMSIS-DAP clone or a Raspberry Pi Pico running DAPLink firmware will flash and debug just as well - the difference only shows up when you're moving real data over the wire: high-rate SWO tracing, big flash writes, or RTT-style logging, where hs-probe's genuine USB-HS link is meaningfully faster. What the project's own materials undersell: the firmware source has a full jtag.rs module, so JTAG is implemented even though probe-rs's docs and the Tindie listing both lean almost entirely on 'SWD probe' framing. The bigger concern is the project itself: the hardware repo hasn't been touched since January 2022, firmware commits stopped in November 2023 with 11 issues still open, there's been only one tagged firmware release ever (2021), and the Tindie shop isn't taking orders. It still works today because CMSIS-DAP is a stable protocol and the parent probe-rs debugging software keeps supporting it, but don't expect the hs-probe hardware/firmware itself to see more attention. This is a genuinely single-purpose device (SWD/JTAG only, nothing else) - the short capability list below is a real finding about the product, not a research gap.","released":"2020","aliases":["HS-Probe"],"capabilities":{"uart":"unknown","spi_flash_dump":"no","i2c":"no","jtag_swd":"yes","logic_analyzer":"no","glitching":"no","usb_mass_storage":"no","web_ui":"no"},"legal":{"risk_level":"low","notes":"A standard debug probe with no radio and no controlled functionality - owning and using it carries no meaningful legal restriction anywhere."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2021-08","app_store":"N/A","abandoned_risk":"high"}},{"id":"hunter-cat","hardware_id":"hunter-cat","name":"Hunter Cat","firmware":"Stock","firmware_kind":"stock","vendor":"Electronic Cats","category":"detection-defense","subcategory":"skimmer-detector","status":"available","price_usd":41.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Insert, remove, read the LEDs.","build_effort":"assembled","stealth":"covert","form_factor":"keychain","summary":"A bank-card-shaped detector for magnetic-stripe skimmers: you insert it into an ATM or fuel-pump reader and it counts how many magnetic read heads touch it on the way in. More than one head means something extra is reading cards. Three LEDs give an Ok / Warning / Dangerous verdict in about a second.","honest_take":"Very narrow by design. It finds insert-type skimmers with a second read head and nothing else - not shimmers inside the chip slot, not overlay keypads, not Bluetooth skimmer modules, not tampered PIN pads. It also does not disable anything. Treat it as one check among several, and note that the store currently ships v1.1 while newer revisions exist but are not sold.","released":"2019","aliases":["HunterCat","Card Skimmer Detector"],"capabilities":{"detect_skimmer":"yes","detect_generic_ble":"no"},"legal":{"risk_level":"low","notes":"Passive, non-transmitting consumer safety device."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"medium"}},{"id":"hunter-cat-nfc","hardware_id":"hunter-cat-nfc","name":"Hunter Cat NFC","firmware":"Electronic Cats stock","firmware_kind":"stock","vendor":"Electronic Cats","category":"detection-defense","subcategory":"nfc-reader-detector","status":"discontinued","price_usd":99.99,"price_is_estimate":false,"skill_level":"beginner","skill_note":"As shipped it is a one-button device with an LED. Doing anything past that means writing Arduino or CircuitPython against the PN7150 yourself.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A card-sized board pairing a SAMD21 Cortex-M0+ with an NXP PN7150 NFC controller, sold as a contactless skimmer detector. Its shipped firmware watches for an active 13.56 MHz reader field and flashes an LED. Because the PN7150 is a full NFC front end, the board can also be reprogrammed as a reader, a card emulator, or a peer-to-peer endpoint.","honest_take":"The headline feature is an LED that lights when something nearby is energising a 13.56 MHz field. That is a real and occasionally useful primitive, but it is not skimmer detection in any meaningful sense: a legitimate payment terminal, a door reader and a hostile skimmer all produce an identical RF field, and the shipped firmware does no signature matching, no protocol fingerprinting and no reader identification. It tells you a reader is on, nothing about whose it is. The interesting hardware is the PN7150, and to use it you have to write your own firmware, which is a different product from the one being sold. Electronic Cats have retired it - it is gone from their store, sold out on Tindie since January 2023, and they now point buyers at the BomberCat (US$119), which folds the same reader-detection into a device that also does NFC relay and magstripe work. Do not confuse this with the plain 'Hunter Cat', a separate and still-current US$41-46 magnetic-stripe skimmer detector.","released":"2021","aliases":["HunterCat NFC","Hunter Cat NFC by Electronic Cats"],"capabilities":{"detect_skimmer":"partial","hf_1356_read":"partial","hf_1356_emulate":"partial","lf_125khz_read":"no","nfc_type4_ndef":"partial","iso15693":"partial","felica":"partial","emv_read":"no","scriptable":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"low","notes":"A passive field detector with no transmit function in its shipped configuration - unremarkable to own or carry anywhere."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"hydra-esp","hardware_id":"hydra-esp","name":"Hydra-ESP","firmware":"Hydra-ESP","firmware_kind":"diy","vendor":"Sameer Al Sahab","category":"wifi","subcategory":"deauth-evil-twin-ble-spam-firmware","status":"diy-only","price_usd":6.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flashing is straightforward, but running deauth/evil-twin/credential-harvesting attacks responsibly and legally requires understanding what you're actually doing to a network.","build_effort":"flash-only","stealth":"discreet","form_factor":"board","summary":"Open-source Wi-Fi and BLE offensive firmware for a bare ESP32 board: multi-target deauthentication, WPA handshake/PMKID capture, evil-twin captive portals, BSSID cloning, a deauth detector, and Apple/Samsung/Google-style BLE advertisement spam plus BLE HID keystroke injection, all driven from a web UI at 192.168.4.1.","honest_take":"Despite the project's earlier name (ESP32-Deauther/HydraESP) and feature overlap, this is not a Marauder fork - it's built on risinek's esp32-wifi-penetration-tool for the Wi-Fi attacks and the EvilAppleJuice project for BLE spam, so it has a different codebase, app ecosystem, and hardware-support list than Marauder. It only runs on the original Xtensa ESP32 (not the newer, more commonly available S2/S3/C3 boards), which is a real compatibility trap for anyone who already owns a modern ESP32 dev board. The feature list (16 simultaneous deauth targets, PMKID capture, evil twin, BSSID cloning to defeat Management Frame Protection, BLE HID payloads to Windows) is genuinely capable for a $6 board, and the project is actively maintained (203 stars, pushed within the last two months), but this is unsigned firmware doing credential harvesting and unauthorized-access-adjacent attacks - using it against networks you don't control and have authorization to test is illegal in most places, web UI polish notwithstanding.","released":"2025","aliases":["ESP32-Deauther","HydraESP"],"capabilities":{"wifi_scan_24":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"no","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_injection":"yes","detect_deauth":"yes","ble_spam_apple":"yes","ble_spam_samsung":"yes","ble_spam_android":"claimed","ble_hid":"yes","web_ui":"yes","scriptable":"yes","app_store":"no"},"legal":{"risk_level":"high","notes":"Owning/flashing the firmware is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"No","abandoned_risk":"low"}},{"id":"hydralink","hardware_id":"hydralink","name":"HydraLink","firmware":"Stock (dissecto GmbH)","firmware_kind":"stock","vendor":"dissecto GmbH","category":"automotive","subcategory":"automotive-ethernet-interface","status":"preorder","price_usd":349.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Assumes familiarity with Ethernet tooling (Wireshark/tcpdump/bridge-utils) and automotive network concepts (SOME/IP, DoIP); the hardware itself is plug-and-play.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A USB 3.0 to automotive Ethernet (100BASE-T1 and 1000BASE-T1 single twisted pair) adapter that enumerates as a native Ethernet interface (hydra0/hydra1) on Linux/macOS/Windows, so standard tools - Wireshark, Scapy, tcpdump, bridge-utils, ethtool - work against in-vehicle Ethernet with no special drivers. Two units, one set to master and one to slave, form a transparent Layer-2 wire-speed MITM bridge for fuzzing SOME/IP or validating DoIP implementations. It has no CAN, LIN, or any other automotive-bus support at all - Ethernet only.","honest_take":"This solves a real, underserved gap - almost every other budget automotive tool on the market (including everything else in this batch) is CAN-only, and modern vehicles increasingly run Ethernet backbones that those tools simply cannot see. But 'open source' here is qualified: dissecto states the schematic is redacted because it depends on proprietary information from the single-pair PHY chip vendor, so you get open drivers and firmware, not a fully open hardware design, unlike CANable/CANtact/panda. It also only speaks single-pair automotive Ethernet (100/1000BASE-T1) - it will not talk to a normal office switch or a standard 100BASE-Tx/1000BASE-T link the way the pricier TOSUN TE1051 ($1,642) can.","released":"2025","aliases":[],"capabilities":{"ethernet_tap_passive":"yes","ethernet_mitm":"yes","usb_ethernet_attack":"yes","packet_capture":"yes","scriptable":"yes","web_ui":"no","app_store":"no","standalone_untethered":"no","cloud_c2":"no","sd_logging":"no","automotive_ethernet":"yes","can_sniff":"no","can_inject":"no","can_fd":"no","can_isolated":"no","lin_bus":"no","obd2":"no"},"legal":{"risk_level":"low","notes":"Owning and using this on a vehicle's network you own or are authorized to test is legal research/diagnostic work."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025-10","app_store":"No","abandoned_risk":"low"}},{"id":"hydranfc-shield-v2","hardware_id":"hydranfc-shield-v2","name":"HydraNFC Shield v2","firmware":"HydraFW (official)","firmware_kind":"stock","vendor":"HydraBus (Benjamin Vernoux)","category":"rfid-nfc","subcategory":"research-platform-shield","status":"available","price_usd":231.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"Command-line HydraBus console driving raw NFC frames; there is no app or GUI. You need to already understand ISO14443/15693 framing to get anything useful out of it.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"An open-source 13.56MHz NFC shield built around ST25R3916 - the same NFC chipset used in the Proxmark3 RDV4.01 and other reference platforms - that plugs onto a HydraBus v1 multi-tool board. It reads/writes/emulates ISO14443A, ISO14443B, FeliCa and ISO15693, and includes a genuine real-time RF sniffer mode with a dedicated PulseView decoder, at claimed 12cm+ (ISO14443A) and 16cm+ (ISO15693) ranges.","honest_take":"This is not a Flipper-style all-in-one - it is a bare shield that does nothing without a separate HydraBus v1 host, and the whole stack is console-driven with no app. Where it earns its place next to a Proxmark3 is the same ST25R3916 chipset giving genuinely comparable RF performance at a fraction of the price, plus a real hardware sniffer mode most cheap NFC tools lack entirely. What it does not have is a Proxmark3's library of ready-made MIFARE Classic key-recovery attacks (darkside/nested/hardnested) - the firmware gives you raw frame access and expects you to build that yourself. The catch is availability: the official storefront was effectively non-functional when checked (empty shop listing, 404 product page), so budget for the possibility this is easier to find via Digi-Key or an EU reseller than direct from the maker.","released":"2020","aliases":["HydraNFC v2","HydraBus + HydraNFC Shield v2"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"partial","hf_1356_emulate":"yes","mifare_classic_attacks":"no","mifare_desfire":"no","iso15693":"yes","felica":"yes","emv_read":"no","nfc_type4_ndef":"unknown","lf_125khz_read":"no","lf_125khz_emulate":"no","nfc_relay":"unknown","uart":"yes","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"Owning an open reader/writer/sniffer platform is legal in most countries."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025-11","app_store":"No - console command set only","abandoned_risk":"low"}},{"id":"i2cdriver","hardware_id":"i2cdriver","name":"I2CDriver","firmware":"Stock (ExCamera Labs)","firmware_kind":"stock","vendor":"ExCamera Labs","category":"hardware-debug","subcategory":"protocol-bridge","status":"available","price_usd":29.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Straightforward to wire up (three ready-made ports with jumpers included) but you still need to understand I2C addressing, pull-ups and clock stretching to interpret what it shows you.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"The I2C-only counterpart to the SPIDriver: a small open-hardware USB probe with a live display of bus traffic (including a live address map of every device it sees on the bus), programmable auto-tuning pull-up resistors, and three identical I2C ports so you can probe several devices without rewiring. Built around the same FTDI + Silicon Labs EFM8 combination.","honest_take":"The programmable, auto-tuning pull-up resistors are the genuinely useful part - getting pull-up values wrong is a classic source of flaky I2C bugs, and this tool removes the guesswork, as does the live address map that shows every device answering on the bus. But like the SPIDriver, it is a single-protocol tool at multi-protocol-tool pricing: a Bus Pirate 5 costs roughly twice as much but adds SPI, UART and 1-Wire on top of I2C, and this device has zero JTAG/SWD or SPI capability of its own. Buy this specifically if I2C is most of your bench work and you want the nicest possible I2C-only experience, not as a general hardware-hacking tool.","released":"2019","aliases":[],"capabilities":{"i2c":"yes","logic_analyzer":"partial","spi_flash_dump":"no","uart":"no","jtag_swd":"no","glitching":"no","scriptable":"yes","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A passive bench probe with no radio - legal to own and use everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"ibdap","hardware_id":"ibdap","name":"IBDAP - CMSIS-DAP JTAG/SWD Debug Adapter","firmware":"Stock","firmware_kind":"stock","vendor":"Armstart","category":"hardware-debug","subcategory":"jtag-swd-probe","status":"out-of-stock","price_usd":35.95,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"A standard CMSIS-DAP probe - if you already use OpenOCD or Keil with any other CMSIS-DAP adapter, this behaves the same way.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An open-hardware CMSIS-DAP debug adapter built on an NXP LPC11U35 Cortex-M0 running at 48 MHz, giving JTAG and SWD access to ARM Cortex targets from multiple vendors (Nordic, Atmel, NXP, Freescale, TI) plus UART/I2C/SPI/ADC/GPIO breakout. Functionally a from-scratch alternative to a DAPLink or ST-Link for Cortex-M debugging, with more general peripheral breakout than most dedicated probes in this comparison.","honest_take":"This is a competent, fully open CMSIS-DAP probe on paper, with more peripheral breakout (I2C, dual SPI, 8-channel ADC) than any other debug probe in this batch - but the listing is currently unbuyable. The seller's own page says they are 'taking a break', not just sold out, and the upstream firmware repo has had exactly two commits since it was published, so treat this as effectively dormant rather than an active product. At the price point where this normally sits ($35.95), a Mini DAPLink or an XDS110-class probe from an actively-stocked seller is the safer buy right now; there is nothing IBDAP does for JTAG/SWD that a current CMSIS-DAP probe does not, and its extra peripheral breakout is a bonus you can't currently purchase.","released":"2015","aliases":["IBDAP CMSIS-DAP"],"capabilities":{"jtag_swd":"yes","uart":"yes","i2c":"yes","spi_flash_dump":"partial","logic_analyzer":"no","glitching":"no","scriptable":"unknown","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A bench debug probe with no radio - legal to own and use everywhere."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2015","app_store":"No","abandoned_risk":"high"}},{"id":"icopy-x-factory","hardware_id":"icopy-x","name":"iCopy-XS","firmware":"Factory (stock, closed source)","firmware_kind":"stock","vendor":"iCopy-X","category":"rfid-nfc","subcategory":"automated-cloner","status":"available","price_usd":435.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"That is the entire product thesis: a screen, four buttons and a wizard, so an installer or a locksmith can clone a badge without learning a command line.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"A Proxmark3-derived RF platform bolted to a Linux single-board computer with a 1.3-inch screen, buttons and a 2000mAh battery, wrapped in a clone-this-badge wizard. The genuinely useful part is that the Linux side runs the Proxmark client on the device itself, so MIFARE Classic key recovery finishes in your hand instead of on a laptop.","honest_take":"You are paying roughly three Proxmark3s for a screen and a wizard, and the wizard automates the half of the problem that was already easy. LF 125 kHz cloning is unauthenticated by design and MIFARE Classic has been broken since 2008; those are what the one-button flow handles. Lab401's own spec sheet lists MIFARE DESFire, iCLASS Elite with custom keys, and EMV as NOT supported. The 'iCLASS SE / SEOS cloning' headline is the one to read carefully: it needs the separate EUR425 iCS Decoder, and what it performs is a downgrade attack, not a clone. The decoder extracts the PACS payload from the secure credential, and the iCopy-X writes those Wiegand bits onto a legacy iCLASS/PicoPass or T5577 blank. That blank only opens the door if the reader still has legacy iCLASS or ProxII formats enabled - if the site turned legacy off, you have an expensive coaster. The Proxmark project's own downgrade notes state there are no card-only attack vectors against SE/SEOS. Finally, the price tiers are a software paywall on identical hardware, and there is a free open-source firmware that removes them entirely.","released":"2020","aliases":["iCopy-X","iCopyX","iCopy XS"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"partial","hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"partial","mifare_classic_attacks":"yes","mifare_desfire":"no","emv_read":"no","iso15693":"yes","nfc_type4_ndef":"unknown","standalone_untethered":"yes","scriptable":"no"},"legal":{"risk_level":"high","notes":"Unlike a Proxmark, this device has no plausible research framing - it is a one-button badge duplicator with a wizard, and that shapes how its presence gets interpreted."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"icopy-x-open","hardware_id":"icopy-x","name":"iCopy-XS","firmware":"iCopy-X Open (lab-401)","firmware_kind":"community","vendor":"iCopy-X (hardware) / lab-401 (firmware)","category":"rfid-nfc","subcategory":"automated-cloner","status":"available","price_usd":435.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The wizard survives, but you now have the full Iceman command set behind it - which means you can also reach every way of getting a wrong answer that a Proxmark offers.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"The same iCopy-XS hardware running a from-scratch open firmware. It keeps the screen-and-buttons cloner workflow but strips the licence tiers, tracks current Iceman Proxmark releases, and adds a plugin architecture that lets you drive the Proxmark or the Linux subsystem from JSON-described UI apps.","honest_take":"This firmware is the strongest argument for owning the hardware and simultaneously the strongest argument against the vendor's pricing: it deletes the tag DRM, so the EUR375 tier and the EUR529 tier become identical devices. Know that before you order. What it does not do is change physics - you still cannot recover a DESFire AES key or clone an iCLASS SE / SEOS credential, and the ICS Decoder path it integrates is still a downgrade attack that writes PACS bits to a legacy blank and only works where the reader still accepts legacy formats. The ICS bridge has been tested only against a DIY decoder build; the commercial Nikola decoder is listed as testing pending. And the licence bars commercial use, which for a device most often bought by consultants is a real constraint.","released":"2020","aliases":["iCopy-X Open","iCopy-X jailbreak","icopy-x open source firmware"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"yes","mifare_classic_attacks":"yes","mifare_desfire":"partial","emv_read":"partial","iso15693":"yes","felica":"partial","nfc_type4_ndef":"yes","standalone_untethered":"yes","web_ui":"no","scriptable":"yes"},"legal":{"risk_level":"high","notes":"Same exposure as the factory firmware, plus one extra consideration: the firmware licence explicitly forbids commercial use, so a consultant running it on a paid engagement has a licensing problem separate from any criminal-law question."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No - JSON plugin system, community-contributed","abandoned_risk":"medium"}},{"id":"ics-decoder-icopy-x","hardware_id":"ics-decoder-icopy-x","name":"iCS Decoder for iCopy-X","firmware_kind":"n/a","vendor":"ICopyX","category":"rfid-nfc","subcategory":"cloning-accessory","status":"available","price_usd":450.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Plugging it in is trivial; understanding which target readers are actually running in the legacy-compatible mode this decoder depends on requires real iCLASS SE/SEOS knowledge.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A USB-C decoder dongle that plugs into an iCopy-X/iCopy-XS and extends its cloning ability to HID iCLASS SE and SEOS cards - previously the two formats no consumer-grade cloner could touch. It decodes the target card's data and lets the iCopy-X write a new card using legacy iCLASS encoding, provided the destination reader still accepts legacy-compatible credentials.","honest_take":"The catch is buried in the vendor's own coverage figure: this works on iCLASS SE/SEOS readers 'configured to accept legacy cards,' which the vendor estimates covers about 85% of deployments - it is a downgrade attack against backward-compatibility, not a break of SE/SEOS's actual AES cryptography. A site that has disabled legacy mode (which HID explicitly supports and recommends) is unaffected by this device entirely, and there is no independent confirmation of that 85% figure beyond the seller's own claim. It is real and it is the only consumer-accessible way to touch these formats at all, but it is not 'iCLASS SE/SEOS cracked.'","aliases":["iCS Decoder for iCLASS SE/SEOS","iCS Decoder"],"capabilities":{"hf_1356_read":"addon","hf_1356_write":"addon","hf_1356_emulate":"no","mifare_classic_attacks":"no","mifare_desfire":"no","iso15693":"no","felica":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","standalone_untethered":"no","scriptable":"no"},"legal":{"risk_level":"medium","notes":"Cloning an access badge you are not authorised to duplicate is a computer-misuse/access-device offence in most jurisdictions regardless of which card format is involved."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"lab401-industrial-handheld-uhf-reader","hardware_id":"lab401-industrial-handheld-uhf-reader","name":"Industrial Handheld UHF Reader","firmware_kind":"n/a","vendor":"Unbranded/white-label industrial Android handheld (rebranded by Lab401); OEM/ODM not disclosed","category":"rfid-nfc","subcategory":"uhf-reader","status":"available","price_usd":1263.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"It is a rugged Android phone with a UHF reader built in - point, scan, read the screen. The skill is in interpreting tag data during a sweep, not operating the device.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"A rugged Android industrial handheld computer with an integrated long-range UHF RFID reader module (865-928MHz band coverage spanning EU/US/China allocations), sold by Lab401 as the verification/location companion to UHFKill: sweeping a carton or rack to find every embedded UHF tag and confirm deactivation worked, rather than to attack anything.","honest_take":"This is not a bespoke security tool - it is a category of industrial UHF inventory reader (the kind warehouses use for stocktaking) that Lab401 has picked up and repositioned for a red-team/loss-prevention audience. The 10m+ read range and 1300 tags/sec figures are standard for this reader class, not something unique to this SKU. If you already have any commercial UHF handheld (Zebra, Chainway, Impinj-based readers all exist at similar or lower prices from industrial suppliers), it will do the same job; you are paying Lab401 for curation and pairing with the UHFKill workflow, not for unique hardware. It is also UHF-only - it will not touch the 125kHz or 13.56MHz badges most access-control and payment work involves.","aliases":[],"capabilities":{"lf_125khz_read":"no","hf_1356_read":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","iso15693":"no","felica":"no","gps":"yes","gps_wardrive_log":"unknown","standalone_untethered":"yes","sd_logging":"unknown","scriptable":"unknown","web_ui":"unknown","uhf_rfid_read":"yes","uhf_rfid_write":"unknown"},"legal":{"risk_level":"low","notes":"A UHF inventory reader has no meaningful restriction on ownership or use in most jurisdictions - it is the same class of device used openly in retail and logistics."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"Standard Android app ecosystem","abandoned_risk":"medium"}},{"id":"inputstick-rat","hardware_id":"inputstick","name":"InputStick RAT","firmware":"Stock","firmware_kind":"stock","vendor":"InputStick","category":"usb-hid","subcategory":"wireless-hid-injector","status":"available","price_usd":44.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Plug in, pair with the phone app, type.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A small USB dongle that presents itself as a keyboard, mouse, gamepad or consumer-control device and is driven live from an Android phone over Bluetooth 5.2, with AES-128 on the link and password protection. Where a Rubber Ducky runs a pre-written script, this is interactive: you type on your phone and the keystrokes land on the host.","honest_take":"The 'undetected by antivirus' line in the marketing is true only in the trivial sense that a keyboard is not malware - endpoint tools increasingly flag new HID devices, and any USB device-control policy blocks it outright. Range is about 10 m, so you have to stay nearby, and it needs the vendor's Android app - there is no iOS equivalent. It is a genuinely useful live-input tool, not a stealth implant.","released":"2014","aliases":["InputStick"],"capabilities":{"usb_hid_inject":"yes","hid_remote_trigger":"yes","usb_mass_storage":"no","usb_payload_lang":"partial","usb_exfil":"no"},"legal":{"risk_level":"high","notes":"Typing into a computer you are not authorised to use is unauthorised access."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"unknown","app_store":"No - vendor Android app","abandoned_risk":"medium"}},{"id":"int3rcept0r","hardware_id":"int3rcept0r","name":"Int3rcept0r","vendor":"unknwncharlie (independent developer)","category":"network-implant","subcategory":"usb-ethernet-mitm","status":"diy-only","price_usd":20.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Requires flashing Raspbian, editing boot config for SPI/USB gadget mode, wiring GPIO jumpers, and configuring Ettercap/DNSMASQ/iptables by hand.","build_effort":"full-diy","stealth":"covert","form_factor":"board","summary":"A homebrew LAN Turtle-equivalent built from a Raspberry Pi Zero using g_ether USB gadget mode to appear as a USB-to-Ethernet adapter, bridging a victim's Ethernet connection to the attacker's USB host while running Ettercap-based ARP/DNS spoofing and credential sniffing (Telnet, FTP, POP3, SSH1, SMB, MySQL, HTTP) with reverse SSH/Netcat/Meterpreter backdoors for remote access.","honest_take":"This is functionally a DIY clone of Hak5's LAN Turtle, built from parts that cost a fraction of the $50 Hak5 device — but you're trading that savings for hours of manual Raspbian/iptables/Ettercap configuration and none of the polished module marketplace or support the commercial product has. The credential-sniffing module only catches cleartext protocols (Telnet, FTP, POP3, SSH1, unencrypted HTTP); against a modern network running TLS and SSH2 everywhere, the 'credential theft' headline feature mostly nets nothing. Development stopped in April 2024 after 9 commits, so treat it as a proof-of-concept to learn from rather than a maintained tool.","released":"2017","aliases":[],"capabilities":{"usb_ethernet_attack":"yes","ethernet_mitm":"yes","packet_capture":"yes","cloud_c2":"partial","usb_exfil":"no","usb_mass_storage":"no","usb_hid_inject":"no","vpn_exfil":"no","wifi_scan_24":"no","standalone_untethered":"no","scriptable":"yes","sd_logging":"yes"},"legal":{"risk_level":"medium","notes":"Building and owning the hardware is legal."},"ecosystem":{"community":"dead","docs_quality":"sparse","last_release":"2024-04","app_store":"No","abandoned_risk":"high"}},{"id":"jtagulator","hardware_id":"jtagulator","name":"JTAGulator","firmware":"Stock","firmware_kind":"stock","vendor":"EXPLIoT (manufacturing and support since July 2025); designed by Joe Grand, Grand Idea Studio","category":"hardware-debug","subcategory":"interface-discovery","status":"available","price_usd":249.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Conceptually simple to operate - hook up 24 wires and run a scan - but you need to understand what a false positive looks like and how to avoid damaging the target.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A dedicated interface-discovery tool: connect up to 24 unknown test points and it brute-forces the pin combinations to identify JTAG, SWD and UART interfaces automatically. It solves one specific, genuinely painful problem that no other tool in this batch solves.","honest_take":"It does one job and it is expensive for one job - $249 to find pinouts you could, with patience, find with a multimeter, an oscilloscope and a lot of time. Whether that is worth it depends entirely on how often you face an unlabelled board. For a professional doing regular teardowns it pays for itself the first week; for a hobbyist with one project it does not. Two practical limits: the target I/O voltage range is 1.4 V to 3.3 V, so 5 V targets need level shifting and very low-voltage cores may be out of range; and once it has found the interface you still need a Tigard, Glasgow or dedicated debugger to actually use it. It is a discovery tool, not a debugger.","released":"2013","aliases":["JTAGulator revD","Grand Idea Studio JTAGulator"],"capabilities":{"jtag_swd":"yes","uart":"yes","logic_analyzer":"yes","spi_flash_dump":"no","i2c":"no","glitching":"no","scriptable":"partial","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A bench instrument with no radio, legal to own and use everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"medium"}},{"id":"key-croc","hardware_id":"key-croc","name":"Key Croc","firmware":"Key Croc 1.4","firmware_kind":"stock","vendor":"Hak5","category":"usb-hid","subcategory":"keylogger-implant","status":"available","price_usd":200.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Basic keylogging is plug-and-forget; the match-triggered payloads that justify the price need real scripting and an understanding of USB attack modes.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A hardware keylogger that is also a small Linux computer. It sits between a USB keyboard and the host, logs every keystroke, and - crucially - can watch that stream for keywords or regular expressions and fire a payload when one appears. It can then switch USB personalities to a keyboard, flash drive, serial device or Ethernet adapter to act on what it saw.","honest_take":"The keyword-matching trigger is the genuinely novel bit and nothing cheap does it: a $10 hardware keylogger records to a chip you have to come back and retrieve, whereas this can notice someone typing a password and immediately react over Wi-Fi. Two things to be clear about. First, despite the price and the marketing, this is DuckyScript 2.0, not 3 - commands are QUACK-prefixed and you do not get the compiled language's variables, conditionals, loops or Keystroke Reflection exfiltration. Second, Hak5's own specification block lists no CPU, no RAM and no SoC; the 'quad-core 1.2 GHz ARM, 512 MB RAM' figures you will see quoted come from marketing copy and third-party wikis, not a published spec or a teardown. There is also a well-reported operational footgun: logs are flushed to storage when you enter arming mode, so pulling it out of the port without arming it first can cost you the capture.","released":"2020","aliases":["KeyCroc","Croc"],"capabilities":{"usb_keylogger":"yes","usb_hid_inject":"yes","usb_mass_storage":"yes","usb_ethernet_attack":"yes","usb_exfil":"yes","usb_payload_lang":"partial","hid_remote_trigger":"yes","cloud_c2":"yes","wifi_ap_mode":"no","scriptable":"yes","standalone_untethered":"yes","sd_logging":"no"},"legal":{"risk_level":"high","notes":"Keylogging is specifically named in interception and computer-misuse statutes in many countries and in most US states, and unlike passive network sniffing it captures passwords and private messages directly."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2023-07","app_store":"Yes - official payload repository, 232 stars, last pushed 2026-01","abandoned_risk":"medium"}},{"id":"keygrabber-keelog","hardware_id":"keygrabber","name":"KeyGrabber","vendor":"Keelog","category":"usb-hid","subcategory":"hardware-keylogger","status":"available","price_usd":55.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-play inline device across all variants; no drivers or software needed to log.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"KeyGrabber is Keelog's long-running hardware keylogger line, sold at Hacker Warehouse across three variants: PS/2 (4MB), USB Pico (16MB), and USB WiFi Premium (16MB, timestamping, Mac compatibility, wireless retrieval). All are inline, driverless devices that record keystrokes transparently and switch into USB mass-storage mode for retrieval via a key combination.","honest_take":"The batch's original vendor attribution of 'KeyCarbon' for this product is incorrect — KeyCarbon LLC/BitForensics was a distinct, unrelated hardware-keylogger maker (PCI-card and Mini-PCI laptop keyloggers, apparently defunct) with no connection to KeyGrabber. The actual maker, confirmed via keelog.com's own site metadata and copyright, is Keelog, which has sold KeyGrabber since 2005 and claims 100,000+ units sold across the KeyGrabber/AirDrive lines. One nuance worth flagging: Keelog's current site markets its Wi-Fi-retrieval keyloggers under a separate 'AirDrive' brand name, not 'KeyGrabber' — the 'USB WiFi Premium' KeyGrabber SKU sold at Hacker Warehouse may be a legacy naming still used by this reseller rather than Keelog's current catalog term, so confirm current firmware/support status with Keelog directly if buying for that specific variant. Also note: keystroke-injection scripting is a feature of Keelog's separate 'Forensic Keylogger Pro/Max' line, not the classic PS/2/USB/WiFi Premium family covered here — don't assume this family can inject.","released":"2005","aliases":["KeyGrabber PS/2","KeyGrabber USB Pico","KeyGrabber USB WiFi Premium"],"capabilities":{"usb_keylogger":"yes","usb_hid_inject":"no","usb_exfil":"addon","usb_mass_storage":"yes","wifi_ap_mode":"no","hid_remote_trigger":"no","scriptable":"no","standalone_untethered":"no","sd_logging":"no","ble_scan":"no"},"legal":{"risk_level":"high","notes":"Owning the hardware is generally legal."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"hackerwarehouse-keylogger-usb-extension-cable","hardware_id":"hackerwarehouse-keylogger-usb-extension-cable","name":"Keylogger USB Extension Cable","vendor":"Generic (unbranded OEM, sold via Hacker Warehouse)","category":"usb-hid","subcategory":"hardware-keylogger","status":"out-of-stock","price_usd":65.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-play; no drivers or configuration to log keystrokes.","build_effort":"assembled","stealth":"covert","form_factor":"cable","summary":"A hardware keylogger built into the body of an ordinary-looking USB extension cable, with 16MB of internal flash and date/time-stamping, supporting over 40 national keyboard layouts. The SKU (EW-C16TK) and spec sheet are a near-exact match for Keelog's own 'KeyGrabber Forensic Keylogger Cable' (16MB, extension-cable form factor, 40+ layouts, special-key-combination retrieval into USB mass-storage mode) — this is very likely the same or a closely cloned product resold generically rather than a house-designed device.","honest_take":"The listing's claim of being '100% stealthy, undetectable for security software' is true of essentially every hardware keylogger in this category — antivirus and other host-side software fundamentally cannot see a passive device sitting between the keyboard and the USB port, since nothing runs on the host OS at all. That's a category-wide property, not something unique to this product, and it's worth recognizing as boilerplate marketing rather than a differentiator. This listing itself doesn't document a retrieval method, but Keelog's identically-specced 'KeyGrabber Forensic Keylogger Cable' — same 16MB capacity, same cable form factor, same feature list — documents pressing a predefined key combination to switch into USB mass-storage mode; treat that as the likely (not vendor-confirmed for this exact listing) retrieval mechanism. At $65 versus Keelog's own $59.99 for what looks like the same device, and versus the KeyGrabber PS/2 at $55 elsewhere in this database, the generic listing isn't winning on price either.","aliases":[],"capabilities":{"usb_keylogger":"yes","usb_hid_inject":"no","usb_exfil":"partial","usb_mass_storage":"partial","wifi_ap_mode":"no","hid_remote_trigger":"no","scriptable":"no","standalone_untethered":"no","sd_logging":"no","ble_scan":"no"},"legal":{"risk_level":"high","notes":"Owning the hardware is generally legal."},"ecosystem":{"community":"commercial","docs_quality":"poor","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"keysy-lf-duplicator","hardware_id":"keysy","name":"Keysy LF RFID Duplicator & Emulator","firmware":"Stock (closed)","firmware_kind":"stock","vendor":"Keysy (sold by Lab401 and others)","category":"rfid-nfc","subcategory":"lf-cloner","status":"available","price_usd":71.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Two buttons and an LED - hold it against a badge and it stores it.","build_effort":"assembled","stealth":"discreet","form_factor":"keychain","summary":"A keyfob-sized 125 kHz cloner that stores four LF credentials, replays them directly at a reader, and can write them out to blank T5577-style tags later. It covers a wide list of LF formats: HID Prox, Indala, EM410x, AWID, Keri, ioProx, Pyramid, DoorKing, Radio Key and generic T55x7.","honest_take":"It is 125 kHz only. It will not touch MIFARE, iCLASS, DESFire or anything at 13.56 MHz, which is most modern badges. Two important footnotes in the vendor's own spec: HID Prox emulation does not work against multiCLASS readers, and AWID cannot be emulated at all (both can still be cloned to a rewritable tag). Convenient, discreet, and strictly limited to legacy LF systems.","released":"2018","aliases":["Keysy RFID copier"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_emulate":"partial","lf_125khz_write":"yes","hf_1356_read":"no"},"legal":{"risk_level":"high","notes":"A pocket badge cloner is exactly the sort of device covered by 'possession of a device for unauthorised access' statutes in some jurisdictions."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"n/a","app_store":"No","abandoned_risk":"medium"}},{"id":"keyvilboard-wifi","hardware_id":"keyvilboard","name":"KEYVILBOARD - Wi-Fi","vendor":"RedBulletTooling / KEYVILBOARD","category":"usb-hid","subcategory":"hardware-keylogger","status":"out-of-stock","price_usd":79.95,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-play inline device; no drivers or configuration needed to log, though connecting to the hidden Wi-Fi network to retrieve data requires knowing its credentials.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A fully open-source inline hardware keylogger for QWERTY keyboards that stores roughly 3 million characters in onboard flash and is retrieved over a hidden Wi-Fi network at up to ~30m range, with vendor-claimed support for remote keystroke injection back into the host. It's part of the RedBulletTooling KEYVILBOARD family, which also includes an SMS-exfiltration variant on the same open hardware base.","honest_take":"Unlike most hardware keyloggers in this category, KEYVILBOARD is genuinely open-source top to bottom (firmware and hardware on GitHub under MIT), which is a real differentiator from closed competitors like KeyGrabber — you can audit exactly what it does with captured keystrokes instead of trusting a vendor's word. That said, 'remote key injection' is a vendor claim on the Tindie listing that I could not independently verify against the firmware source in the time available, so treat it as claimed rather than confirmed. Like all inline hardware keyloggers, it doesn't require drivers or show up as a new process to antivirus software — but that's true of every device in this category, not a special feature of this one; the real detection risk is physical (a technician spotting an extra inline module) or, on some designs, an unexpected USB hub/device enumeration, which the vendor doesn't address either way here.","released":"2018","aliases":[],"capabilities":{"usb_keylogger":"yes","usb_hid_inject":"claimed","hid_remote_trigger":"claimed","usb_exfil":"yes","usb_mass_storage":"no","wifi_ap_mode":"yes","wifi_scan_24":"no","ble_scan":"no","scriptable":"yes","standalone_untethered":"no","sd_logging":"no"},"legal":{"risk_level":"high","notes":"Owning the hardware is generally legal."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2022-09","app_store":"No","abandoned_risk":"medium"}},{"id":"kiisu-v4b-kiisu-firmware","hardware_id":"kiisu-v4b","name":"KIISU V4B","firmware":"Kiisu Firmware","firmware_kind":"community","vendor":"Rainwalker OU (KIISU)","category":"multitool","subcategory":"rf-multitool","status":"preorder","price_usd":145.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The software is Flipper firmware, so it is familiar - but this ships as a bare board with a coin cell, you supply and format the microSD, and adding an external antenna means soldering an SMA connector and moving a 0805 capacitor.","build_effort":"assembly","stealth":"discreet","form_factor":"pocket","summary":"A credit-card-sized open-hardware board that reimplements the Flipper Zero's peripheral set - CC1101 sub-GHz, ST25R3916 NFC, 125 kHz RFID, infrared, iButton, Flipper-pin-compatible GPIO - around the same STM32WB55 MCU, with a second STM32G4 handling power and Flipper compatibility. It runs real Flipper firmware including Momentum and Unleashed builds, and the schematics are published under CERN-OHL-S. The vendor calls it a development board rather than a consumer product, and means it.","honest_take":"This is the real thing rather than a re-skinned ESP32, and it is the only device in this group that touches sub-GHz, NFC, RFID and infrared at all - but it is not a drop-in Flipper. It lacks Flipper Zero's secret keys, so U2F and some sub-GHz protocols will not work under official firmware; the tiny LIR2032 coin cell gives you a fraction of a Flipper's runtime, and putting an ordinary CR2032 in it is a fire hazard; and the built-in 433 MHz ceramic antenna is much worse than a Flipper's, with better range gated behind soldering an SMA connector yourself. You are trading polish, battery and range for a wallet-sized form factor, open schematics and about a third off the price.","released":"2025","aliases":["Kiisu","Kiisu V4","KIISU V4BR","Kiisu Development Board v4b"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"partial","subghz_bruteforce":"yes","subghz_external_antenna":"addon","lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"yes","mifare_classic_attacks":"yes","nfc_type4_ndef":"yes","iso15693":"yes","emv_read":"yes","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","ibutton_1wire":"yes","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_hid":"yes","usb_hid_inject":"yes","usb_payload_lang":"yes","wifi_scan_24":"addon","wifi_deauth_24":"addon","uart":"yes","spi_flash_dump":"yes","i2c":"yes","jtag_swd":"partial","sd_logging":"yes","scriptable":"yes","app_store":"partial","standalone_untethered":"partial","sdr_rx":"no","gps":"no"},"legal":{"risk_level":"medium","notes":"Owning it is legal in most places, and being an open-hardware development board rather than a branded consumer gadget has so far kept it clear of the import trouble the Flipper Zero has run into."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-05","app_store":"No dedicated store - it uses Flipper community apps, with caveats","abandoned_risk":"medium"}},{"id":"kode-dot-kodeos","hardware_id":"kode-dot","name":"Kode Dot","firmware":"kodeOS","firmware_kind":"stock","vendor":"KODE DIY SL","category":"multitool","subcategory":"maker-handheld","status":"preorder","price_usd":199.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The workflow is Arduino IDE, PlatformIO or ESP-IDF - write code, compile, upload. There is no ready-made menu of attacks the way a Flipper or a Marauder build gives you.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A pocket handheld built around an ESP32-P4 application processor with an ESP32-C5 radio co-processor, a 2.13in 502x410 AMOLED with capacitive touch, a 9-axis IMU, NFC, 125 kHz RFID, infrared, haptics, audio and a 20-pin expansion header. The vendor markets it to makers and pentesters, but the security-relevant radio hardware - sub-GHz in particular - lives entirely in optional plug-on modules. In practice it is a very well-specified ESP32 developer handheld rather than a pentest tool.","honest_take":"Two things a buyer needs to know before the spec sheet seduces them. First, the device that was crowdfunded is not the device being sold: the campaign design was an ESP32-S3 and the shipping design is an ESP32-P4 plus ESP32-C5, with a different fuel gauge and a different IMU - and the vendor's own documentation site still describes the S3. Second, it is not a security tool out of the box. There is no sub-GHz radio on the mainboard at all; that is the 59-dollar F*CK module, which is gated behind the same January 2027 batch. Add that every repository in the vendor's GitHub org has no licence file at all despite 'open source' branding, that the actual OS is unpublished, that the product page claims 16,000 backers against a public record of 8,646, and that the gen-2 spec grid lists battery capacity as 'TBD' on a 199-dollar product, and the picture is a genuinely impressive bill of materials wrapped in claims that do not survive checking.","released":"2026","aliases":["KodeDot","Kode.","Kode Dot v2"],"capabilities":{"wifi_scan_24":"claimed","wifi_scan_5":"claimed","wifi_deauth_24":"unknown","wifi_deauth_5":"unknown","ble_scan":"claimed","hf_1356_read":"claimed","hf_1356_emulate":"claimed","lf_125khz_read":"claimed","ir_tx":"claimed","ir_rx":"claimed","subghz_rx":"addon","subghz_tx":"addon","subghz_external_antenna":"addon","gps":"addon","usb_hid_inject":"unknown","scriptable":"yes","app_store":"no","sd_logging":"yes","standalone_untethered":"yes","zigbee":"claimed"},"legal":{"risk_level":"low","notes":"As sold this is a developer handheld and carries no more legal weight than any other ESP32 board."},"ecosystem":{"community":"slow","docs_quality":"poor","last_release":"none","app_store":"Advertised but does not exist","abandoned_risk":"medium"}},{"id":"krakensdr","hardware_id":"krakensdr","name":"KrakenSDR","firmware":"KrakenSDR DoA / Krakensdr_doa","firmware_kind":"stock","vendor":"KrakenRF","category":"sdr","subcategory":"coherent-receiver","status":"available","price_usd":749.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Direction finding needs correct antenna spacing, calibration and a host computer; it is not plug-and-play.","build_effort":"assembly","stealth":"overt","form_factor":"box","summary":"Five phase-coherent RTL-SDR receivers on one board with automatic coherence calibration, aimed at radio direction finding and passive radar. It is the only affordable way to get real bearing-to-transmitter capability rather than guessing from signal strength.","honest_take":"It is five R820T2 tuners: 8-bit, 24-1766 MHz, receive only. It will not transmit, and per-channel performance is exactly an RTL-SDR, not better. The real cost is the antenna array and the vehicle work - people who buy it expecting a handheld 'signal locator' end up with an unused box.","released":"2021","aliases":["Kraken SDR","KrakenRF 5-channel"],"capabilities":{"sdr_rx":"yes","sdr_tx":"no","sdr_bandwidth":"partial","gps":"addon","wifi_wardriving":"no"},"legal":{"risk_level":"low","notes":"Receive-only hardware is legal to own in most countries, but intercepting and acting on the content of communications you are not party to is regulated separately in many jurisdictions."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"lab401-flashing-multi-tool","hardware_id":"lab401-flashing-multi-tool","name":"Lab401 Flashing Multi-tool for Proxmark & Chameleon","firmware_kind":"n/a","vendor":"Lab401","category":"accessory","subcategory":"rfid-tool-flashing-adapter","status":"available","price_usd":32.39,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Trivial to use once wired - the whole point is removing the need to solder pogo-pin or wire jigs - but you need to already know how to drive a Segger J-Link or an AVR ISP mkII.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A passive breakout adapter (11 x 8 x 1.5 cm, 8-9 g) that pre-wires the JTAG/ICSP headers needed to reflash a Proxmark 3 RDV4/4.01 or a ChameleonMini RevE/RevG without building your own jig. It is not itself a programmer - it just routes a Segger J-Link (for the Proxmark) or an AVR ISP mkII (for the Chameleon) to the right pins. Intended for brick recovery and switching between major firmware branches; routine firmware updates over USB do not need it.","honest_take":"The name overstates what you are buying: this is a header-routing adapter, not a programmer. You still need to separately own a Segger J-Link and/or an AVR ISP mkII - both sold separately and each costing as much or more than this board - before it does anything. Its entire value is saving you from hand-wiring pogo pins to a Proxmark or Chameleon's debug pads, which is a real but narrow convenience specifically for brick recovery and firmware-branch switching (not routine updates, which work fine over USB alone). If you already have proper jigs or don't mind wiring your own, skip it; if you regularly reflash both device families and don't want to fight tiny test points every time, it earns its price.","released":"2018","aliases":["Proxmark 3 RDV4 Flash Support","Multi-Flash Adaptor"],"capabilities":{"spi_flash_dump":"no","jtag_swd":"addon","uart":"no","i2c":"no","logic_analyzer":"no","glitching":"no","scriptable":"no","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A passive adapter board with no radio and no independent function - legal to own and use everywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"n/a","app_store":"No","abandoned_risk":"low"}},{"id":"lan-turtle","hardware_id":"lan-turtle","name":"LAN Turtle","firmware":"LAN Turtle 6.2","firmware_kind":"stock","vendor":"Hak5","category":"network-implant","subcategory":"usb-ethernet-implant","status":"out-of-stock","price_usd":80.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The ncurses menu makes reverse shells easy, but you need to understand outbound filtering and where a rogue Ethernet adapter would actually go unnoticed.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A small OpenWrt computer hidden inside a case that looks like a generic USB Ethernet adapter. Plugged into a workstation's USB port and the network, it gets its power from the host, gives the host normal network access, and quietly opens an outbound shell back to you. The disguise is the product.","honest_take":"This is 2015 hardware - a 400 MHz single-core MIPS AR9331 with 64 MB of RAM and 16 MB of flash - and the firmware has not been updated since October 2019. Seven years without a security update on a device whose entire purpose is to sit persistently on someone else's network is a real problem, not a nitpick. The disguise still works well, and that remains its genuine advantage over a Raspberry Pi Zero doing the same job. But it is out of stock, the 3G variant is formally discontinued, and Hak5 has shipped the LAN Turtle Hub as a replacement with USB-C, a web interface, Wi-Fi and current firmware. If you want this capability today, buy the Hub; if you want it cheap, a Pi Zero W with a USB Ethernet gadget does the same thing for about $20 and you control the software.","released":"2015","aliases":["LANTurtle","Turtle"],"capabilities":{"ethernet_mitm":"partial","packet_capture":"yes","vpn_exfil":"yes","cloud_c2":"yes","usb_ethernet_attack":"yes","scriptable":"yes","web_ui":"no","standalone_untethered":"yes","sd_logging":"partial","wifi_scan_24":"no"},"legal":{"risk_level":"high","notes":"A device deliberately disguised as an innocuous accessory, installed on someone else's machine to open a covert channel out of their network, is close to the paradigm case that computer-misuse law was written for."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2019-10","app_store":"Yes - module repository, 353 stars, last pushed 2025-02","abandoned_risk":"high"}},{"id":"lan-turtle-hub","hardware_id":"lan-turtle-hub","name":"LAN Turtle Hub","firmware":"LAN Turtle Hub 1.0.1","firmware_kind":"stock","vendor":"Hak5","category":"network-implant","subcategory":"usb-ethernet-implant","status":"available","price_usd":120.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The web UI lowers the barrier considerably compared with the original, but VPN and DNS work still needs networking knowledge.","build_effort":"assembled","stealth":"covert","form_factor":"box","summary":"A USB-C Ethernet hub that is also an implant. It genuinely works as a USB 3 hub and Ethernet adapter for the person using it, while providing you with remote shell access, Wi-Fi out-of-band management, VPN tunnelling, DNS manipulation and USB device interception. This is the replacement for the original LAN Turtle.","honest_take":"The disguise here is smarter than the original's: a USB-C dock with Ethernet is a thing people actively want on their desk and will plug in themselves, and it does its cover job properly. The Wi-Fi management AP is the risk to manage - Hak5 says so plainly in its own docs, warning that the management AP is detectable and that hiding the SSID 'will not fully hide it' from tools like Kismet. Leave it off unless you need it. Hak5 publishes no SoC, RAM or flash figure, but unlike its older siblings there is an FCC filing (2A52Y-TURTLEHUB, granted May 2025) with internal photos, a block diagram and schematics listed, so this one is actually verifiable if you want to dig. Firmware is 1.0.1 from December 2024 - current, but only just.","released":"2026","aliases":["Turtle Hub","LAN Turtle 2"],"capabilities":{"ethernet_mitm":"yes","packet_capture":"yes","vpn_exfil":"yes","cloud_c2":"yes","usb_ethernet_attack":"yes","usb_keylogger":"partial","wifi_ap_mode":"yes","wifi_scan_24":"partial","web_ui":"yes","scriptable":"yes","usb_payload_lang":"partial","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"This is deliberately disguised as a useful accessory that a target will plug in themselves, and it intercepts both network and USB traffic."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2024-12","app_store":"Yes - Hak5 Payload Hub","abandoned_risk":"low"}},{"id":"lilygo-t-deck-plus","hardware_id":"lilygo-t-deck-plus","name":"LilyGo T-Deck Plus","firmware":"Meshtastic / MeshCore","firmware_kind":"community","vendor":"LILYGO","category":"multitool","subcategory":"lora-gps-handheld","status":"available","price_usd":85.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Arrives as a development platform, not a finished security tool - you choose and flash firmware yourself, and Meshtastic/MeshCore setup assumes some comfort with ESP32 flashing tools.","build_effort":"flash-only","stealth":"discreet","form_factor":"handheld","summary":"A BlackBerry-style ESP32-S3 handheld with a QWERTY keyboard, trackball, 2.8-inch IPS touchscreen, SX1262 LoRa radio, GPS and a 2000mAh battery, sold as a Meshtastic/MeshCore off-grid mesh communicator. It is a general-purpose ESP32-S3 dev platform that happens to carry LoRa and GPS, not a purpose-built security tool.","honest_take":"Like other LoRa/GPS handhelds in this space, people see 'LoRa + GPS + keyboard' and assume it's a Flipper-class attack tool; it isn't one out of the box. There is no sub-GHz CC1101, no NFC/RFID reader, and no offensive firmware pre-loaded - the SX1262 is a LoRa/FSK part locked to whichever frequency SKU you bought, not a general sub-GHz scanner, and Meshtastic itself has no attack tooling at all. What you're buying for $85 is a capable ESP32-S3 dev board with a keyboard and screen already built - a good base if you intend to write or port your own BLE/Wi-Fi tooling, a poor buy if you expected a mesh-networking Flipper.","released":"2024","aliases":["T-Deck Plus","LILYGO T-Deck Plus"],"capabilities":{"wifi_scan_24":"claimed","wifi_scan_5":"no","wifi_deauth_24":"no","ble_scan":"claimed","bt_classic":"no","subghz_rx":"partial","subghz_tx":"partial","subghz_replay":"no","gps":"yes","sd_logging":"yes","scriptable":"yes","standalone_untethered":"yes","usb_hid_inject":"no","ir_tx":"no","hf_1356_read":"no","mesh_lora":"yes"},"legal":{"risk_level":"low","notes":"An ordinary development kit running licence-exempt LoRa ISM bands in the region matching its SKU."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026","app_store":"No - Meshtastic/MeshCore apps and firmware, not a security app store","abandoned_risk":"low"}},{"id":"lilygo-t-dongle-c5-ghostesp","hardware_id":"lilygo-t-dongle-c5","name":"LilyGo T-Dongle-C5","firmware":"GhostESP (Revival)","firmware_kind":"community","vendor":"LILYGO","category":"wifi","subcategory":"dual-band-usb-dongle","status":"available","price_usd":12.58,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Flashing is easy, but you are driving a menu on a 0.96-inch screen with no buttons to speak of, and every 'field' use needs a USB port or power bank.","build_effort":"flash-only","stealth":"discreet","form_factor":"usb-stick","summary":"A USB-A stick containing an ESP32-C5 with dual-band Wi-Fi 6, a 0.96-inch colour screen and a microSD slot, for around $13. Flashed with GhostESP it becomes a genuine 2.4 and 5 GHz Wi-Fi tool - scanning, monitor mode, deauth, evil portal, handshake capture - in the smallest and cheapest package in this batch.","honest_take":"This is the value argument for the whole scene in one product: the same ESP32-C5 dual-band radio the $220 Banshee and the ~$152 ZeroTrace AirLeak Pro are built around, running the identical free GhostESP firmware, for $12.58. What you give up is real and worth taking seriously - no battery, no buttons, no proper case, a 0.96-inch screen that is genuinely unpleasant to navigate a menu on, and no sub-GHz, NFC or IR at all. It also looks exactly like a USB flash drive without being one: the C5's USB is a Serial/JTAG peripheral, not the S3's USB-OTG, so it cannot pretend to be a keyboard. This is not a BadUSB.","aliases":["T-Dongle C5","LILYGO T-Dongle-C5","T-Dongle-C5 ESP32-C5"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"partial","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_wardriving":"addon","wifi_ap_mode":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","zigbee":"partial","packet_capture":"yes","sd_logging":"yes","web_ui":"yes","app_store":"yes","usb_hid_inject":"no","standalone_untethered":"no","gps":"no","subghz_rx":"no","ir_tx":"no","hf_1356_read":"no"},"legal":{"risk_level":"medium","notes":"The board itself is an ordinary development kit and is legal to own everywhere."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-09","app_store":"Yes - via GhostESP","abandoned_risk":"low"}},{"id":"usbarmyknife-t-dongle-s3","hardware_id":"lilygo-t-dongle-s3","name":"LilyGo T-Dongle-S3 (USB Army Knife)","firmware":"USB Army Knife","firmware_kind":"community","vendor":"LilyGO","category":"usb-hid","subcategory":"usb-attack-platform","status":"available","price_usd":11.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Browser flashing is easy, but writing useful payloads means learning DuckyScript and thinking about the target's OS and keyboard layout.","build_effort":"flash-only","stealth":"covert","form_factor":"usb-stick","summary":"A USB-stick-shaped ESP32-S3 with a small colour LCD and a microSD slot hidden inside the USB-A connector housing, running USB Army Knife. Plugged into a target it can be a keyboard, a mass storage device, a CDROM or a USB network adapter, and it can be driven live over its own Wi-Fi from a phone browser - including streaming the victim's screen once an agent is deployed.","honest_take":"This is the most genuinely capable device in this batch for its price, because it attacks over USB rather than over the air - and USB attacks do not care about WPA3 or PMF. Being realistic about the limits: HID injection still needs an unlocked, logged-in machine and the right keyboard layout, and modern EDR increasingly flags a keyboard that types 200 words per minute. The board has no PSRAM (a widely-copied spec claiming 8MB is actually the T-Dongle-S3-Plus, a different model), and LilyGO's own product page carries a note saying 'TF card has no function' which directly contradicts the working SD examples in their GitHub repo - worth testing your specific unit before relying on the card. The embedded Marauder fork gives you deauth and pcap, with all the usual PMF caveats.","released":"2023","aliases":["UAK","T-Dongle S3"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_mass_storage":"yes","usb_ethernet_attack":"yes","usb_exfil":"yes","hid_remote_trigger":"yes","packet_capture":"yes","cloud_c2":"partial","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_ap_mode":"yes","wifi_handshake_capture":"yes","ble_scan":"yes","bt_classic":"no","web_ui":"yes","hdmi_capture":"no","sd_logging":"partial","scriptable":"yes","standalone_untethered":"no","subghz_rx":"no","hf_1356_read":"no","ir_tx":"no"},"legal":{"risk_level":"high","notes":"This is a purpose-built covert intrusion tool, and that matters legally."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-02","app_store":"No - payloads are DuckyScript files, with worked examples in the repo","abandoned_risk":"low"}},{"id":"lilygo-t-embed-cc1101-bruce","hardware_id":"lilygo-t-embed-cc1101","name":"LilyGo T-Embed CC1101","firmware":"Bruce","firmware_kind":"community","vendor":"LILYGO","category":"multitool","subcategory":"rf-multitool","status":"available","price_usd":49.38,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Flash Bruce from a browser and everything works from a rotary-encoder menu. No soldering, no add-on modules, no pin conflicts.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"The strongest ready-made Flipper Zero alternative in this batch: an ESP32-S3 handheld with a genuine CC1101 sub-GHz transceiver covering 300-928 MHz, a PN532 NFC reader, IR transmit and receive, a 1.9-inch colour screen and a rotary encoder, all onboard for about $49. Running Bruce it covers sub-GHz, NFC, IR, Wi-Fi, BLE and BadUSB from one menu.","honest_take":"This is the one device here where the hardware genuinely earns the price - a real CC1101 across all three sub-GHz bands, a real PN532, real IR TX and RX, no soldering, no add-on modules, nothing shared with the display bus. Two things to know before buying. Several retail listings claim '125/134 kHz LF' RFID support; that is wrong - the PN532 is 13.56 MHz only, so this cannot read or clone an HID Prox or EM4100 badge, which is the single most common misconception about it. And it has no more rolling-code magic than a Flipper: it replays fixed codes and brute-forces static remotes, and that is the end of it.","aliases":["T-Embed CC1101","LILYGO T-Embed CC1101","T-Embed CC1101 Plus"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"yes","subghz_rolling_code":"no","subghz_external_antenna":"yes","hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"partial","mifare_classic_attacks":"yes","nfc_type4_ndef":"yes","lf_125khz_read":"no","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_wardriving":"addon","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_hid":"yes","usb_hid_inject":"yes","nrf24_scan":"addon","sd_logging":"yes","scriptable":"yes","standalone_untethered":"yes","ibutton_1wire":"no","gps":"no"},"legal":{"risk_level":"high","notes":"Sub-GHz transmit is the sharp edge here."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"Yes - Bruce apps and JavaScript scripts","abandoned_risk":"low"}},{"id":"lilygo-t-lora-pager-bruce","hardware_id":"lilygo-t-lora-pager","name":"LilyGo T-LoRa Pager","firmware":"Bruce","firmware_kind":"community","vendor":"LILYGO","category":"multitool","subcategory":"lora-mesh-handheld","status":"out-of-stock","price_usd":87.35,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Multiple competing firmwares (Meshtastic, MeshCore, Bruce) with different flashing routes, and Bruce's support here is partial.","build_effort":"flash-only","stealth":"discreet","form_factor":"handheld","summary":"A finished ESP32-S3 handheld with a QWERTY keyboard, a 2.33-inch wide display, an SX1262 LoRa radio, u-blox GNSS, NFC, an audio codec and an AI motion IMU. It is designed as an off-grid mesh communicator - Meshtastic and MeshCore are its real ecosystems - and Bruce will run on it, which is why it turns up in security-gadget comparisons.","honest_take":"This is a LoRa mesh communicator that Bruce happens to run on, not a security tool that happens to have LoRa. Bruce's own device table puts it in the limited-support tier, and the sub-GHz radio is an SX1262 fixed to one band by SKU - it is not a CC1101 and it will not sweep 300-928 MHz or replay a 433 MHz garage remote unless you bought that variant, and Bruce's sub-GHz tooling is written around the CC1101 anyway. At $87 and sold out, you are paying for the GNSS, the keyboard, the audio codec and the IMU, none of which do anything for wireless attacks. If you want an ESP32-S3 handheld for RF work, the T-Embed CC1101 is $49 and has the right radio.","released":"2025","aliases":["T-Lora Pager","LILYGO T-LoRa Pager","T-LoRa Pager"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"partial","wifi_evil_twin":"partial","wifi_wardriving":"partial","ble_scan":"yes","ble_spam_apple":"yes","subghz_rx":"partial","subghz_tx":"partial","subghz_replay":"unknown","hf_1356_read":"claimed","gps":"yes","sd_logging":"yes","usb_hid_inject":"claimed","scriptable":"yes","standalone_untethered":"yes","ir_tx":"no","nrf24_scan":"addon"},"legal":{"risk_level":"medium","notes":"The board is an ordinary development kit."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"No - Bruce apps and JS scripts","abandoned_risk":"low"}},{"id":"lilygo-t-watch-s3-ghostesp","hardware_id":"lilygo-t-watch-s3","name":"LilyGo T-Watch S3","firmware":"GhostESP (Revival)","firmware_kind":"community","vendor":"LILYGO","category":"multitool","subcategory":"wearable-esp32","status":"out-of-stock","price_usd":42.98,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Flashing is easy; driving a menu system designed for larger screens on a 1.54-inch watch face is not.","build_effort":"flash-only","stealth":"discreet","form_factor":"wearable","summary":"An open smartwatch built on an ESP32-S3, with a 1.54-inch capacitive touchscreen, an SX1262 LoRa radio, an IR LED, haptics, a microphone and speaker, and an AXP2101 power management IC. Flashed with GhostESP or Bruce it becomes a wrist-worn 2.4 GHz Wi-Fi and BLE tool - the only genuinely wearable device in this batch.","honest_take":"The reason to pick this over any other ESP32-S3 is that it looks like a watch, which matters for a physical assessment and for nothing else. Everything it does, a $12.58 T-Dongle-C5 does better: there is no SD card at all - GhostESP fakes a 4 MB internal volume, so handshake captures are measured in minutes rather than hours - no GPS, no CC1101, 2.4 GHz only, and a 1.54-inch screen driving menus built for bigger displays. LILYGO does not publish the battery capacity, which for a continuous-scan workload is the one number that actually matters. And it was sold out when checked.","released":"2023","aliases":["T-Watch S3","LILYGO T-Watch-S3","TWatch S3"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"partial","wifi_ap_mode":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_tracker_detect":"yes","ir_tx":"yes","ir_universal_remote":"yes","ir_rx":"unknown","subghz_rx":"partial","usb_hid_inject":"partial","web_ui":"yes","standalone_untethered":"yes","sd_logging":"no","gps":"no"},"legal":{"risk_level":"medium","notes":"An ordinary open-source smartwatch to own."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-09","app_store":"Yes - via GhostESP","abandoned_risk":"low"}},{"id":"usbarmyknife-t-watch-s3","hardware_id":"lilygo-t-watch-s3","name":"LilyGo T-Watch S3 (USB Army Knife)","firmware":"USB Army Knife","firmware_kind":"community","vendor":"LilyGO","category":"usb-hid","subcategory":"wearable-attack-platform","status":"available","price_usd":42.98,"price_is_estimate":false,"skill_level":"advanced","skill_note":"The README notes flashing this platform is more complex than the others and points to a device-specific wiki page.","build_effort":"flash-only","stealth":"covert","form_factor":"wearable","summary":"An ESP32-S3 smartwatch with a 240x240 touch display, 8MB PSRAM, a LoRa transceiver, microphone, accelerometer, RTC, IR emitter and haptics, running USB Army Knife. It is a wrist-worn HID injection and Wi-Fi attack platform that looks like a chunky smartwatch.","honest_take":"Wearing your attack platform is the appeal and it genuinely works, but be clear on the compromises. There is no SD card slot at all, so USB Army Knife caps scripts and results at around 10MB of onboard flash - the covert-storage and long-PCAP use cases are gone. It charges and programs over Micro-USB, not USB-C, which in 2026 is an awkward thing to be carrying. Every GPIO in LilyGO's pin map is marked unavailable, so it is a sealed appliance with no expansion. And the LoRa SX1262 - the most interesting radio in this batch, and the only sub-GHz hardware anywhere in it - is not used by USB Army Knife at all, so you are paying for silicon that sits idle. Also note LilyGO's own documentation contradicts itself on the screen size, giving both 1.54 and 1.3 inches. The Wi-Fi attacks it inherits from the embedded Marauder fork have the usual ceiling too: 802.11w/PMF defeats deauth and WPA3 makes PMF mandatory.","released":"2023","aliases":["T-Watch S3","LilyGo T-Watch"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_mass_storage":"partial","usb_ethernet_attack":"yes","usb_exfil":"yes","hid_remote_trigger":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_ap_mode":"yes","ble_scan":"yes","bt_classic":"no","subghz_rx":"no","subghz_tx":"no","ir_tx":"no","web_ui":"yes","sd_logging":"no","gps":"no","scriptable":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"HID injection into an unauthorised machine is unauthorised access under computer-misuse law in most countries, and doing it from a worn device is not a mitigating factor."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-02","app_store":"No - DuckyScript payloads","abandoned_risk":"low"}},{"id":"limesdr-mini-2","hardware_id":"limesdr-mini-2","name":"LimeSDR Mini 2.0","firmware":"Stock","firmware_kind":"stock","vendor":"Lime Microsystems","category":"sdr","subcategory":"full-duplex-transceiver","status":"available","price_usd":399.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"Getting the most out of it means touching FPGA gateware; even basic use has historically involved fighting driver and LimeSuite version mismatches.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A full-duplex 12-bit SDR covering 10 MHz to 3.5 GHz with 40 MHz of bandwidth, built on the LMS7002M transceiver and a Lattice ECP5 FPGA with 44K LUTs of user-accessible logic. It is aimed at people building radio systems - small cellular basestations, custom protocols - rather than at people poking at garage doors.","honest_take":"This is a development platform that happens to be usable for security work, not a security tool. Its two genuine advantages over a HackRF are that it is full duplex and 12-bit, which matter enormously if you are implementing a protocol that must respond to what it hears - a HackRF simply cannot do that. Against it: narrower coverage (3.5 GHz vs 6 GHz), a much smaller community, a rougher software story around LimeSuite, and a price that buys a HackRF Pro with change. Unless you specifically need full duplex or FPGA access, most people are better served elsewhere.","released":"2022","aliases":["LimeSDR Mini v2","LimeSDR Mini 2"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"yes","subghz_rx":"yes","subghz_tx":"yes","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"high","notes":"Receiving is generally lawful."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"medium"}},{"id":"littlepcap-network-tap","hardware_id":"littlepcap-network-tap","name":"LittlePcap Network Tap","firmware":"LittlePcap firmware","firmware_kind":"third-party-product","vendor":"Little Things","category":"network-implant","subcategory":"standalone-capture-tap","status":"available","price_usd":80.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug inline, attach a USB drive, power it on; captures start automatically after roughly a 16-second boot.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"An inline dual-Gigabit-Ethernet capture appliance that writes traffic straight to PCAP files on an attached USB drive, with no host computer needed and no IP address of its own on the monitored network. USB-C powered (5V/2A), roughly 16-second boot, and rated to pass a full 1Gbps of traffic - unlike the 10/100-limited passive taps in this database, it is built on an actual small ARM Linux board (NanoPi R3S in v2) rather than a passive electrical splitter.","honest_take":"The 'invisible network tap - no IP address' claim is about being unaddressable at layer 3, not about being electrically passive - this is a small ARM Linux single-board computer bridging two Ethernet ports and copying frames to a local file, and it says so itself: no automatic bypass, network connectivity only exists while it's powered on. That means an unplanned reboot or power loss on this box takes the monitored link down with it - something a true zero-power passive tap (like the Throwing Star LAN Tap already in this database) never does. Where it genuinely wins is standalone capture: no laptop needed, just plug in a USB drive and walk away, and it explicitly passes 802.1X traffic through untouched rather than trying to defeat it.","aliases":[],"capabilities":{"ethernet_tap_passive":"no","packet_capture":"yes","standalone_untethered":"yes","cloud_c2":"no","usb_hid_inject":"no","wifi_scan_24":"no","ble_scan":"no","ethernet_mitm":"no","web_ui":"unknown","app_store":"no","vpn_exfil":"no","sd_logging":"no","hdmi_capture":"no"},"legal":{"risk_level":"medium","notes":"Legal to own."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"lockedusb-charge-only-adapter","hardware_id":"lockedusb-charge-only-adapter","name":"LockedUSB Charge Only Adapter","firmware_kind":"n/a","vendor":"LockedUSB","category":"accessory","subcategory":"usb-data-blocker","status":"out-of-stock","price_usd":20.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug in between a cable and a charger/port. No configuration of any kind.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A small USB-A male-to-female pass-through adapter that physically omits or disconnects the D+/D- data pins so a phone or laptop plugged in through it can only draw power, not exchange data. It is a defensive accessory for using untrusted public USB charging ports (airports, hotels, conference kiosks), not an attack tool.","honest_take":"It does exactly one boring thing and does it fine, but it solves a narrower problem than people think: it protects you from a malicious wall socket or charging kiosk reading your device over the data pins ('juice jacking'), not from a malicious cable. If the cable itself is the implant - like an O.MG Cable - the compromise already happened at the cable, upstream of where this adapter sits, and the blocker does nothing. There's also no chip disclosed, so 'DCP charging mode support' just means it fakes the resistor/voltage handshake phones expect on a dumb charger; some phones will still only trickle-charge through it.","aliases":["USB data blocker","USB condom"],"capabilities":{"usb_hid_inject":"no","usb_mass_storage":"no","usb_ethernet_attack":"no","usb_keylogger":"no","usb_exfil":"no","hid_remote_trigger":"no","usb_payload_lang":"no","scriptable":"no","web_ui":"no","cloud_c2":"no","standalone_untethered":"no","usb_data_block":"yes","usb_cable_detect":"no"},"legal":{"risk_level":"low","notes":"Fully legal to own and use everywhere; it is a passive protective accessory with no offensive function."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"dl533n-xl","hardware_id":"dl533n-xl","name":"Long Range RFID Reader/Writer DL533N XL","firmware_kind":"n/a","vendor":"D-Logic","category":"rfid-nfc","subcategory":"reader-writer","status":"available","price_usd":101.52,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"LibNFC-compatible, so anyone comfortable with nfc-mfclassic/mfoc/mfcuk on the command line can drive it immediately; no proprietary software to learn.","build_effort":"assembled","stealth":"covert","form_factor":"board","summary":"A large-antenna variant of D-Logic's PN533-based DL533N reader/writer, trading a normal-size card-reader footprint for an oversized 178x178mm built-in antenna that extends read/write range to about 18cm - enough to sit under a desk or inside a bag rather than needing the card presented directly to it. It is fully libnfc-compatible, so it plugs directly into the standard open-source MIFARE tooling (nfc-mfclassic, mfoc, mfcuk) rather than requiring vendor software.","honest_take":"The extra range comes entirely from a bigger antenna coil, not from more powerful silicon - it uses the same NXP PN533 chip as D-Logic's pocket-sized DL533N and DL533N CS models, so anything it can do those smaller (and cheaper) readers can also do, just at 2-3x the range. At 18cm it is meaningfully better than a standard USB reader for a 'reader under a desk/bag' scenario, but it is nowhere near the 40-120cm a tuned Proxmark3 HF antenna or the 45-60cm the PPE long-range capture systems in this same batch claim - PN533 is a fixed-function reader IC, not the reconfigurable RF frontend a Proxmark's FPGA gives you. Buying through Lab401 costs roughly 40% more than ordering the same board directly from D-Logic.","aliases":["DL533N XL","DL533N XL OEM"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"no","mifare_classic_attacks":"addon","mifare_desfire":"partial","iso15693":"no","felica":"yes","emv_read":"unknown","nfc_type4_ndef":"unknown","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","standalone_untethered":"no","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Owning a libnfc-compatible reader/writer is legal in most jurisdictions - it is standard security-research hardware."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No - libnfc/nfc-tools CLI ecosystem","abandoned_risk":"low"}},{"id":"ppe-iclass-r90se-longrange-capture","hardware_id":"ppe-iclass-r90se-longrange-capture","name":"Long-range iCLASS RFID Capture System","firmware":"Doppelgänger","firmware_kind":"third-party-product","vendor":"Mayweather Group (PPE - Physical Exploitation)","category":"rfid-nfc","subcategory":"long-range-badge-capture","status":"available","price_usd":845.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Operating the reader-in-a-bag is trivial via the phone app; getting useful results requires understanding iCLASS's legacy/SE/SEOS split and knowing the target site's configuration well enough to plan a brush-by.","build_effort":"assembled","stealth":"covert","form_factor":"box","summary":"A genuine HID iCLASS R90SE industrial-grade reader with a Doppelgänger Core capture module wired into its Wiegand line, built to be carried in a bag or backpack and read iCLASS badges off people's belts or bags from up to ~45cm. It is the productised, ready-to-carry version of the same Doppelgänger Core hardware already tracked in this database as a bare implant board - here bolted to real long-range reader hardware and cased for field use.","honest_take":"The read range comes entirely from the HID R90SE being genuine long-range industrial reader hardware, not from any trick in the Doppelgänger firmware - you could build the same thing yourself for less by buying an R90SE and a bare Doppelgänger Core board (~$60) and wiring them together, which is exactly what this product is. What it captures for iCLASS SE/SEOS cards is the card's identity/CSN, not a working key - PPE's own downgrade-attack language and the wider iCLASS research (including this database's Proxmark3 entry) both note there is no card-only attack on properly configured SE/SEOS; a captured SEOS card only clones cleanly if the site's readers still accept legacy/downgraded credentials. On plain iCLASS Legacy or HID Prox it works exactly as advertised.","aliases":["PPE iCLASS R90SE Longrange Data Interpreter","iCLASS Longrange Capture System"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"no","hf_1356_emulate":"addon","mifare_classic_attacks":"no","mifare_desfire":"no","iso15693":"no","felica":"no","emv_read":"no","lf_125khz_read":"no","nfc_relay":"no","web_ui":"yes","cloud_c2":"addon","standalone_untethered":"partial","scriptable":"no","wiegand_tap":"yes"},"legal":{"risk_level":"high","notes":"This is a covert long-range credential skimmer, sold explicitly for penetration testing."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-01","app_store":"No - Doppelgänger Assistant app/WebUI","abandoned_risk":"low"}},{"id":"ppe-maxiprox-5375-longrange-capture","hardware_id":"ppe-maxiprox-5375-longrange-capture","name":"Long-range MaxiProx 5375 125KHz Capture System","firmware":"Doppelgänger","firmware_kind":"third-party-product","vendor":"Mayweather Group (PPE - Physical Exploitation)","category":"rfid-nfc","subcategory":"long-range-badge-capture","status":"available","price_usd":875.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Same as the iCLASS sibling: trivial to operate, but you need to know the target site is still running unauthenticated 125kHz HID Prox before this is worth carrying, since that is the entire reason it works.","build_effort":"assembled","stealth":"covert","form_factor":"box","summary":"A genuine HID MaxiProx 5375 - a reader designed for vehicle-gate and long-corridor access control, with up to 60cm rated range on standard 125kHz cards - fitted with a Doppelgänger Core capture module on its Wiegand line and cased for reader-in-bag or drive-by credential capture. It is the LF sibling of the iCLASS capture system in the same product line.","honest_take":"125kHz HID Prox, Indala, AWID and the other formats this reads are unauthenticated by design - the card broadcasts its ID to anything that energises it, and that has been true since these formats existed. This device's entire value is repackaging that known weakness into genuine long-range industrial reader hardware you can carry in a bag; there is no clever attack here, and a site that has moved to iCLASS SE/SEOS or another authenticated credential is completely immune to it. The 60cm range figure is HID's own spec for the MaxiProx reading a standard ProxCard II, not a guaranteed real-world figure for every card format or badge holder orientation - PPE's own listing quotes shorter ranges (15-24 inches) for several other Wiegand formats.","aliases":["HID MaxiProx 5375 Longrange Data Interpreter","MaxiProx Longrange Capture System"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"no","lf_125khz_emulate":"addon","hf_1356_read":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","iso15693":"no","magspoof":"no","nfc_relay":"no","web_ui":"yes","cloud_c2":"addon","standalone_untethered":"partial","scriptable":"no","wiegand_tap":"yes"},"legal":{"risk_level":"high","notes":"A covert long-range LF credential skimmer sold for penetration testing."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-01","app_store":"No - Doppelgänger Assistant app/WebUI","abandoned_risk":"low"}},{"id":"lora-radio-backpack-nugget","hardware_id":"lora-radio-backpack-nugget","name":"LoRa Radio Backpack for USB & Bluetooth Nuggets (RFM95)","firmware_kind":"n/a","vendor":"Retia (Retia LLC)","category":"accessory","subcategory":"lora-badusb-backpack","status":"available","price_usd":30.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-play onto an existing USB Nugget or Bluetooth Nugget; requires already knowing how to use the host Nugget's own payload/DuckyScript system.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"An RFM95 LoRa radio backpack (selectable 868 or 915 MHz, up to +20 dBm/100 mW) that plugs onto Retia's USB Nugget or Bluetooth Nugget BadUSB platforms, letting a Nugget receive and execute DuckyScript-style keystroke-injection payloads over a long-range LoRa link instead of only Wi-Fi/Bluetooth.","honest_take":"This is a range extender for an existing attack platform, not an attack tool by itself - the actual BadUSB/keystroke-injection capability lives entirely in the Nugget it plugs into; this board just adds a LoRa command-and-control channel. Retia's own marketing line, 'send BadUSB commands from miles away,' is technically true of LoRa's point-to-point range in ideal open-field, line-of-sight conditions (the RFM95's own datasheet-class figures are commonly cited around 2km with simple antennas, up to double digits of km with directional antennas), but real-world range through walls and buildings during a physical-access engagement will be a small fraction of that - treat 'miles' as a lab number, not an operational one. The RFM95 is a well-understood, off-the-shelf LoRa module also used in Retia's own Nibble boards; nothing about the chip itself is novel.","aliases":[],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"no","subghz_rolling_code":"no","subghz_external_antenna":"unknown","subghz_amplified":"yes","hid_remote_trigger":"yes","usb_hid_inject":"addon","scriptable":"addon","standalone_untethered":"no","app_store":"no","web_ui":"addon","gps":"no"},"legal":{"risk_level":"medium","notes":"The LoRa radio itself operates in license-exempt 868/915 MHz ISM allocations and is low-risk if kept within regional power/duty-cycle limits (ETSI EN 300 220 / FCC Part 15) - at the module's maximum +20 dBm output you are close to or at the legal limit in some regions, so check your local allocation before maxing out power."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"usbarmyknife-atoms3u","hardware_id":"m5stack-atoms3u","name":"M5Stack AtomS3U (USB Army Knife)","firmware":"USB Army Knife","firmware_kind":"community","vendor":"M5Stack","category":"usb-hid","subcategory":"usb-attack-platform","status":"available","price_usd":12.5,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"No screen, so all feedback is the RGB LED and the web interface. Enter boot mode by holding the side RESET button until the LED turns green.","build_effort":"flash-only","stealth":"discreet","form_factor":"usb-stick","summary":"A 53 x 20 mm ESP32-S3 with a USB-A male plug, a microphone, an RGB LED and a button, running USB Army Knife. No screen and no SD card, but it is the cheapest way into the platform and the only supported board with a usable microphone for audio exfiltration.","honest_take":"For $12.50 this is remarkable value, but be clear about what is missing: no screen means no Hollywood UI and no visual confirmation, and no SD card means payloads and captures live in onboard flash only, so the covert-storage and large-PCAP tricks are off the table. The microphone is the differentiator - the hot-mic example streams room audio over Wi-Fi, which is a genuinely serious capability and one that carries much heavier legal weight than keystroke injection in most places, since recording people without consent is a separate offence in its own right. It looks like a generic USB gadget rather than a memory stick, which is slightly less covert than the T-Dongle. The embedded Marauder fork adds Wi-Fi attacks, with the standard ceiling - deauth is defeated by 802.11w/PMF, and WPA3 makes PMF mandatory.","released":"2023","aliases":["AtomS3U"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_mass_storage":"partial","usb_ethernet_attack":"yes","usb_exfil":"yes","hid_remote_trigger":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_ap_mode":"yes","ble_scan":"yes","bt_classic":"no","web_ui":"yes","sd_logging":"no","scriptable":"yes","standalone_untethered":"no","ir_tx":"no","subghz_rx":"no"},"legal":{"risk_level":"high","notes":"HID injection into a machine you are not authorised to use is unauthorised access under computer-misuse law in most countries."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-02","app_store":"No - DuckyScript payloads with worked examples","abandoned_risk":"low"}},{"id":"ghost-esp-cardputer","hardware_id":"m5stack-cardputer","name":"M5Stack Cardputer (Ghost ESP)","firmware":"Ghost ESP","firmware_kind":"community","vendor":"M5Stack","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"discontinued","price_usd":23.9,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Flashing is straightforward, but you are adopting dead software.","build_effort":"flash-only","stealth":"discreet","form_factor":"handheld","summary":"The original M5Stack Cardputer - ESP32-S3, 56-key keyboard, 1.14-inch screen, microSD - running the archived Ghost ESP firmware. A combination of dead firmware and discontinued hardware that mainly exists in the wild on units flashed before April 2025.","honest_take":"Both halves of this pairing are end-of-line: Ghost ESP was archived by its maintainer with a note saying it is never coming back, and M5Stack has EOL'd this Cardputer revision in favour of the Adv. If you own this combination it still works, but there is no upgrade path on either side. The same board runs Bruce, which is actively maintained and strictly more capable, and reflashing takes minutes - there is no good reason to stay on Ghost ESP. Worth noting the original Cardputer has no PSRAM at all, so packet capture was always constrained here. The frozen firmware also means frozen limitations - its deauth is defeated by 802.11w/PMF, which WPA3 makes mandatory, and that will never be revisited here.","released":"2024","aliases":["Ghost ESP Cardputer"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_wardriving":"addon","packet_capture":"partial","ble_scan":"yes","bt_classic":"no","detect_skimmer":"yes","detect_pineapple":"yes","detect_pwnagotchi":"yes","web_ui":"yes","sd_logging":"yes","usb_hid_inject":"no","ir_tx":"no","subghz_rx":"no"},"legal":{"risk_level":"medium","notes":"Unrestricted consumer hardware running MIT-licensed firmware."},"ecosystem":{"community":"dead","docs_quality":"sparse","last_release":"2025-03","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"bruce-cardputer-adv","hardware_id":"m5stack-cardputer-adv","name":"M5Stack Cardputer Adv (Bruce)","firmware":"Bruce","firmware_kind":"community","vendor":"M5Stack","category":"multitool","subcategory":"esp32-multitool","status":"available","price_usd":29.9,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Flashing is a browser click, but the menu is deep and many entries silently do nothing until you attach the matching module.","build_effort":"flash-only","stealth":"discreet","form_factor":"handheld","summary":"A pocket ESP32-S3 computer with a 56-key keyboard, 1.14-inch screen, 1750 mAh battery and microSD, running Bruce - the broadest open-source ESP32 offensive-security firmware. Out of the box it does Wi-Fi, BLE, IR transmit, BadUSB and network attacks; sub-GHz, NFC and 2.4GHz-jamming appear in the menu but need add-on modules.","honest_take":"Bruce's enormous feature list is the thing to be careful about: roughly half of it - CC1101 sub-GHz, PN532 NFC, NRF24, FM - is driver support for hardware the Cardputer does not have, so a fresh unit shows you menus that will not work. What it genuinely does unaided is Wi-Fi, BLE, IR transmit, BadUSB over native USB, and a surprisingly good set of network attacks (ARP spoofing, Responder, WireGuard tunnelling, SSH). The 'RF Jammer' entries are not jamming in any meaningful sense - the CC1101 one keys a constant carrier on a single frequency, and the NRF24 one hops channels spamming 2.4GHz; neither is wideband. Deauth is still deauth: 802.11w/PMF kills it and WPA3 makes PMF mandatory. Note the original Cardputer is now EOL, so the Adv is the one you can actually buy.","released":"2026","aliases":["Bruce Cardputer","Cardputer Adv"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_beacon_spam":"yes","wifi_wardriving":"addon","wifi_ap_mode":"yes","wifi_karma":"partial","packet_capture":"partial","ethernet_mitm":"yes","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","ble_hid":"yes","bt_classic":"no","usb_hid_inject":"yes","usb_payload_lang":"yes","ir_tx":"yes","ir_rx":"addon","subghz_rx":"addon","subghz_tx":"addon","subghz_replay":"addon","hf_1356_read":"addon","lf_125khz_read":"addon","hf_1356_emulate":"no","nrf24_jam":"addon","mousejack":"no","ibutton_1wire":"partial","scriptable":"yes","web_ui":"yes","sd_logging":"yes","standalone_untethered":"yes","gps":"addon","wifi_handshake_capture":"partial"},"legal":{"risk_level":"medium","notes":"The hardware is an unrestricted consumer dev kit."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-08","app_store":"No, but there is a JavaScript interpreter, a web flasher and M5Launcher/M5Burner integration","abandoned_risk":"low"}},{"id":"evil-cardputer","hardware_id":"m5stack-cardputer-adv","name":"M5Stack Cardputer Adv (Evil-Cardputer)","firmware":"Evil-M5Project","firmware_kind":"community","vendor":"M5Stack","category":"wifi","subcategory":"karma-eviltwin","status":"available","price_usd":29.9,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Menu-driven with a keyboard, but the Karma and Evil-Twin workflows expect you to understand what a probe request is and why a client answers a rogue AP.","build_effort":"flash-only","stealth":"discreet","form_factor":"handheld","summary":"The Cardputer Adv running Evil-Cardputer, a Wi-Fi attack firmware built around KARMA and Evil-Twin rather than around scanning. It sniffs probe requests, clones the networks clients are asking for, stands up a captive portal, deauthenticates to force reconnection, captures handshakes and verifies them, and adds a web crawler, SSH client and BadUSB on top.","honest_take":"This is the most focused Wi-Fi attack tool in the batch - where Marauder is a scanner with attacks bolted on, Evil-Cardputer is built around actually capturing credentials, and features like Karma Spear, handshake verification and Wardriving Master are genuinely more advanced than the competition's equivalents. Two things to weigh. First, the repo has NO licence file at all, which legally means all rights reserved rather than open source, despite being publicly developed - worth knowing before you build on it. Second, it publishes no GitHub releases or tags; the version is encoded in the .ino filename and binaries are committed into the repo, which is a fragile way to ship security software. The KARMA attack is also less effective than it once was - modern iOS and Android randomise MACs and mostly stopped broadcasting directed probe requests, which is the behaviour KARMA depends on. And the deauth half still dies against PMF/WPA3.","released":"2024","aliases":["Evil-Cardputer","Evil-M5Project","Evil-M5Core2"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_karma":"partial","wifi_probe_sniff":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_deauth_24":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_wardriving":"addon","packet_capture":"partial","detect_generic_wifi":"yes","detect_flipper":"yes","detect_skimmer":"yes","detect_pwnagotchi":"yes","ble_hid":"yes","bt_classic":"no","usb_hid_inject":"yes","usb_payload_lang":"yes","web_ui":"yes","sd_logging":"yes","subghz_tx":"addon","standalone_untethered":"yes","hf_1356_read":"no"},"legal":{"risk_level":"high","notes":"Higher risk than a scanning tool because the whole design goal is capturing other people's credentials."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No - single firmware, binaries committed into the repo","abandoned_risk":"low"}},{"id":"nemo-cardputer-adv","hardware_id":"m5stack-cardputer-adv","name":"M5Stack Cardputer Adv (NEMO)","firmware":"M5Stick-NEMO","firmware_kind":"community","vendor":"M5Stack","category":"detection-defense","subcategory":"prank-and-defense","status":"available","price_usd":29.9,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Keyboard navigation and a well-documented menu; M5Burner flashes it without a terminal.","build_effort":"flash-only","stealth":"discreet","form_factor":"handheld","summary":"The Cardputer Adv running NEMO. Same prank-and-defence feature set as on the Stick, plus SD-backed credential logging and BadUSB Hunter - a USB device analyser that enumerates whatever you plug into the USB-C port and tells you whether it looks like an O.MG cable, a Rubber Ducky or an honest keyboard.","honest_take":"BadUSB Hunter is the reason to pick this pairing, and it is genuinely useful and genuinely rare: it enumerates device class and interface descriptors and flags anything presenting HID alongside storage or serial, which is exactly how a malicious cable gives itself away. Its limits are honest ones the author documents - the Cardputer only supplies 3.7-4.2V to the port unless you feed 5V through the Grove connector, so some devices will not enumerate, and 'HID-only' is explicitly not the same as safe. The rest of NEMO is still the narrow prank set with no deauth attack, no handshake capture and no RF beyond IR. If you want an attack tool, this is the wrong firmware; if you want to know what is attacking you, it is the right one.","released":"2026","aliases":["NEMO Cardputer"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"no","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"no","ble_spam_apple":"partial","ble_spam_android":"yes","ble_spam_swift_pair":"yes","bt_classic":"no","detect_generic_ble":"yes","detect_generic_wifi":"yes","detect_pineapple":"yes","usb_keylogger":"no","usb_hid_inject":"no","ir_tx":"yes","sd_logging":"yes","gps":"no","standalone_untethered":"yes","subghz_rx":"no","hf_1356_read":"no"},"legal":{"risk_level":"low","notes":"Mostly a defensive tool, and the detection and USB-analysis features are passive and legal essentially everywhere."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-07","app_store":"No - M5Burner and GitHub releases","abandoned_risk":"low"}},{"id":"evil-m5project-core2","hardware_id":"m5stack-core2-evil-m5","name":"M5Stack Core2 (Evil-M5Project)","firmware":"Evil-M5Core2","firmware_kind":"community","vendor":"M5Stack","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"available","price_usd":42.9,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"M5Burner's web flasher covers basic installation in a couple of minutes, but the project's own instructions require pinning an old ESP32 Arduino core (2.1.4 or below), running a separate script to bypass Espressif's deauth guard, adding extra libraries for BadUSB, and placing SD content inside a specifically-named 'evil' folder - none of that is beginner-friendly.","build_effort":"flash-only","stealth":"discreet","form_factor":"handheld","summary":"Evil-M5Project is a free Wi-Fi/BLE pentest firmware, MIT-licensed per its README (though GitHub finds no separate LICENSE file to auto-detect), that the author builds for several M5Stack boards - M5Cardputer, Core2, Core3, AtomS3 and M5Stack Fire - from one shared codebase. On Core2 it covers scanning, deauth, captive-portal credential capture, karma attacks, beacon spam, handshake capture, a basic LAN toolkit (rogue DHCP/DNS, port scanning), and Flipper/skimmer/deauth detection; the fuller module set (BadUSB, IMSI catcher, LLM chat, IR) is Cardputer-only.","honest_take":"This is firmware for the plain ESP32 inside a Core2, not a purpose-built security device - the same Xtensa LX6 silicon is in $5 dev boards, and the $42.90 buys you the screen, battery, case and Grove ports, not any special radio capability. The project's own README recommends the Cardputer over the Core2 ('Better one: M5Cardputer'), and its own feature matrix confirms it: Core2 gets deauth, karma, captive portals and a basic LAN toolkit, but not BadUSB, IMSI catching, IR or the 'Wardriving Master' multi-node mode. The 'Evil-Twin' checkbox itself is unchecked for Core2 in that same matrix - despite having network cloning, karma and a captive portal, the developer doesn't consider the automated evil-twin chain complete on this target. Deauth and beacon spam only reach unprotected management frames - WPA3's mandatory PMF stops it like every other ESP32 tool. And the credential-harvesting captive portal plus rogue-DHCP/DNS features push this well past 'harmless Wi-Fi scanner' territory some buyers expect - using them against a network you don't own is a computer-misuse-shaped decision, not a grey area.","released":"2023","aliases":["Evil-M5Core2","Evil-M5Project"],"capabilities":{"wifi_scan_24":"yes","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_evil_twin":"partial","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_karma":"yes","wifi_wardriving":"addon","wifi_ap_mode":"yes","packet_capture":"yes","sd_logging":"yes","ble_hid":"yes","detect_flipper":"yes","detect_deauth":"yes","detect_skimmer":"yes","pwnagotchi_spam":"yes","web_ui":"yes","standalone_untethered":"yes","network_host_scan":"yes"},"legal":{"risk_level":"medium","notes":"Owning and flashing this is legal in the US and most places."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No - single firmware image per target, no plugin system","abandoned_risk":"low"}},{"id":"marauder-m5stickc-plus2","hardware_id":"m5stickc-plus2","name":"M5StickC Plus2 (ESP32 Marauder)","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"M5Stack","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"discontinued","price_usd":19.95,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"You flash it yourself - the web installer makes this a few minutes, but nothing arrives working and there is no support if it goes wrong.","build_effort":"flash-only","stealth":"discreet","form_factor":"keychain","summary":"A stock M5Stack M5StickC Plus2 dev kit running the official ESP32 Marauder firmware. Roughly $20 buys you most of the Marauder Wi-Fi and BLE feature set in a 48 x 24 mm package with a 1.14-inch screen and a 200 mAh battery. It is the reference point every purpose-built ESP32 security gadget should be measured against.","honest_take":"This is the honest baseline for the whole category: the firmware is free and MIT-licensed, so a $20 dev kit gives you the same 2.4GHz Wi-Fi and BLE attacks as a $100 purpose-built board. What you give up is real though - no SD card slot means no sustained pcap capture, the 200 mAh battery gives well under an hour with the radio busy, there is no GPS so no wardriving, and no external antenna connector. And it is 2.4GHz only, so no 5 GHz, plus deauth that PMF and WPA3 defeat. Worth knowing it is now EOL at M5Stack, and that it is the only board here with Bluetooth Classic - the ESP32-S3 successors are all BLE-only.","released":"2023","aliases":["M5StickC Plus2 Marauder","StickC Plus2"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"partial","wifi_handshake_capture":"partial","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"no","packet_capture":"partial","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_swift_pair":"yes","bt_classic":"yes","ble_tracker_detect":"yes","detect_flipper":"yes","detect_pineapple":"yes","detect_skimmer":"yes","gps":"no","sd_logging":"addon","ir_tx":"partial","usb_hid_inject":"no","standalone_untethered":"partial","subghz_rx":"no","hf_1356_read":"no"},"legal":{"risk_level":"medium","notes":"The hardware is a generic IoT dev kit and is unrestricted everywhere."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No - but M5Burner and the Marauder web installer make swapping firmware easy","abandoned_risk":"low"}},{"id":"nemo-m5stickc-plus2","hardware_id":"m5stickc-plus2","name":"M5StickC Plus2 (NEMO)","firmware":"M5Stick-NEMO","firmware_kind":"community","vendor":"M5Stack","category":"detection-defense","subcategory":"prank-and-defense","status":"discontinued","price_usd":19.95,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Three-button menu, and M5Burner will flash it for you without ever opening a terminal.","build_effort":"flash-only","stealth":"discreet","form_factor":"keychain","summary":"A $20 M5Stack stick running NEMO, a firmware its author describes as being for high-tech pranks and digital self-defence. It does TV-B-Gone infrared, Apple/Windows/Android BLE pairing spam, Wi-Fi SSID spam and a credential-capturing portal - and, unusually, a set of detectors that warn you when someone else is running those same attacks nearby.","honest_take":"NEMO is refreshingly honest about being small: the author says outright he has no delusions of superseding anything. It has NO deauth attack - the source contains only deauth_hunter.h, a detector - so anyone buying it expecting a Wi-Fi weapon has misread it. Its real value is the defensive half: BLE Hunter, Deauth Hunter, PineAP Hunter and BadUSB Hunter tell you when you are being attacked, which almost nothing else in this category does. Be aware the offensive half is ageing badly - the README itself notes Apple has patched much of the BLE spam since 2023. On this board there is also no SD slot, so portal credentials have nowhere to go, and no GPS.","released":"2023","aliases":["NEMO","M5Stick-NEMO"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"no","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"partial","wifi_handshake_capture":"no","packet_capture":"no","ble_advertise":"yes","ble_spam_apple":"partial","ble_spam_android":"yes","ble_spam_swift_pair":"yes","bt_classic":"partial","detect_generic_ble":"yes","detect_generic_wifi":"yes","detect_pineapple":"yes","ir_tx":"yes","ir_universal_remote":"partial","usb_hid_inject":"no","sd_logging":"addon","gps":"no","standalone_untethered":"partial","subghz_rx":"no","hf_1356_read":"no"},"legal":{"risk_level":"low","notes":"The lowest-risk firmware in this batch, because it has no deauth attack."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-07","app_store":"No - distributed through M5Burner and GitHub releases","abandoned_risk":"low"}},{"id":"bruce-m5sticks3","hardware_id":"m5stick-s3","name":"M5StickS3 (Bruce)","firmware":"Bruce","firmware_kind":"community","vendor":"M5Stack","category":"multitool","subcategory":"esp32-multitool","status":"available","price_usd":21.5,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Three-button navigation on a 1.14-inch screen makes Bruce's deep menu tree tedious; the firmware is much happier on a Cardputer.","build_effort":"flash-only","stealth":"discreet","form_factor":"keychain","summary":"M5Stack's 48 x 24 mm ESP32-S3 stick running Bruce. It swaps the old StickC Plus2's ESP32-PICO for an ESP32-S3-PICO with 8MB of PSRAM and native USB, adds an IR receiver, and drops Bluetooth Classic. Bruce gives it Wi-Fi, BLE, IR and BadUSB in a keychain-sized package.","honest_take":"The upgrade over the StickC Plus2 is real but two-edged: you gain native USB (so BadUSB now works, which it physically could not before), 8MB PSRAM and an IR receiver, but you lose Bluetooth Classic entirely because the ESP32-S3 has no BR/EDR radio. There is still no microSD slot, so pcap logging and portal credential capture have nowhere to go, and the 250 mAh battery means well under an hour of transmitting. Bruce's sub-GHz, NFC and NRF24 menus are all add-on-module features here too. As a $21 keychain scanner it is good value; as a serious capture tool it is not, and the tiny screen fights Bruce's menu depth. And Bruce's deauth is the same deauth as everyone else's - 802.11w/PMF stops it dead and WPA3 makes PMF mandatory, so treat it as a legacy-network trick rather than a capability.","released":"2026","aliases":["M5Stack StickC S3","StickS3","M5StickS3"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_evil_twin":"partial","wifi_captive_portal":"partial","wifi_beacon_spam":"yes","wifi_ap_mode":"yes","ethernet_mitm":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_swift_pair":"yes","ble_hid":"yes","bt_classic":"no","usb_hid_inject":"yes","usb_payload_lang":"yes","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","subghz_rx":"addon","subghz_tx":"addon","hf_1356_read":"addon","nrf24_jam":"addon","scriptable":"yes","web_ui":"yes","sd_logging":"no","gps":"addon","standalone_untethered":"partial"},"legal":{"risk_level":"medium","notes":"Unrestricted consumer dev kit."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-08","app_store":"No - JavaScript interpreter plus web flasher and M5Burner","abandoned_risk":"low"}},{"id":"macobox","hardware_id":"macobox","name":"MACOBOX","firmware":"Stock (Mindstorm Security)","firmware_kind":"stock","vendor":"Mindstorm Security","category":"hardware-debug","subcategory":"integrated-pentest-platform","status":"available","price_usd":11000.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"Built for professional hardware pentest engagements - rapid multi-interface firmware extraction (UART/SPI/JTAG/I2C/SWD) assumes you already know how to identify and wire test points on unknown PCBs.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"A self-contained hardware-pentest lab-in-a-box from Mindstorm Security: an Orange Pi Zero3 (Cortex-A53, 1.5GHz, 4GB RAM) single-board Linux computer with a touchscreen, running a Dockerized web interface in kiosk mode, bundled with a full physical toolkit (PCBite probes, eMMC reader, SOP flash sockets, SPI clips) for connecting to and dumping firmware from UART, SPI, JTAG, I2C and SWD interfaces on unknown target boards. Marketing describes an integrated 'AI' for log analysis and component photo identification; the project's own open-source GitHub repo describes this more modestly as integration with third-party firmware-analysis tools rather than a proprietary in-house model.","honest_take":"Two things to know before paying $11k. First, this is priced and positioned as a subscription service wrapped around hardware, not a one-time tool purchase - the headline price buys you a year of engineering support, hardware replacement and a cloud analysis pipeline, and it's unclear what the device is worth once that year lapses without renewing. Second, the 'integrated AI' marketing (demoed across several YouTube videos) is, per Mindstorm's own GitHub README, actually 'integration with third-party firmware analysis tools' running on a $20-class Orange Pi Zero3 SBC - not a bespoke model, and the open-source companion repo has only 19 stars and 2 commits, suggesting the software side is much less mature than the polished demo videos imply. Every physical interface it exposes (UART, SPI, JTAG, I2C, SWD) is also covered by tools costing a tiny fraction of $11k - a Tigard, Bus Pirate 5, or JTAGulator plus a laptop covers the same protocols for well under $200 combined, with a far larger open community behind them. The case for MACOBOX is workflow speed, a pre-assembled probe kit, and vendor support in a professional engagement where billable hours matter more than hardware cost, not raw capability you can't get elsewhere.","aliases":["MACOBOX Hardware Pentest Platform"],"capabilities":{"uart":"yes","spi_flash_dump":"yes","i2c":"yes","jtag_swd":"yes","logic_analyzer":"no","glitching":"no","web_ui":"yes","scriptable":"claimed","app_store":"no","sd_logging":"yes","standalone_untethered":"yes","gps":"no"},"legal":{"risk_level":"low","notes":"A professional diagnostic/pentest platform sold openly to security firms - owning and using it on hardware you own or are contractually authorized to test carries no special legal exposure beyond ordinary hardware-pentest engagement terms."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No - proprietary cloud analysis platform, not a public app store","abandoned_risk":"low"}},{"id":"magspoof","hardware_id":"magspoof","name":"MagSpoof","firmware":"Samy Kamkar reference firmware","firmware_kind":"diy","vendor":"Samy Kamkar (open source project)","category":"rfid-nfc","subcategory":"magstripe-emulator","status":"diy-only","price_usd":15.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"The electronics are simple but the coil is fiddly - winding it and getting the drive strong enough for a reliable read is where builds fail. You also need an AVR programmer.","build_effort":"full-diy","stealth":"discreet","form_factor":"pocket","summary":"A coil driven by a microcontroller through an H-bridge, rapidly reversing polarity to induce in a magnetic read head exactly the flux transitions a physical card swipe would produce. It emulates all three magnetic stripe tracks and can transmit tracks 1 and 2 simultaneously, at a range of a few inches, with no contact and no card. Samy Kamkar published it in November 2015 with full schematics and code.","honest_take":"MagSpoof was a brilliant demonstration and is now largely a museum piece for its headline use. It replays a static magnetic stripe, and the entire payments industry moved to chip and contactless precisely because static data is replayable - the US liability shift landed in October 2015, the same month this was published. A decade on, terminals generally refuse a magstripe transaction on a card whose service code says it has a chip, and the fallback paths that made this interesting have been closed one by one. It is also not a contactless device: the 'wireless' in every write-up means it induces a field into a swipe reader's head from an inch or two away. It has no 13.56 MHz radio and cannot touch NFC, EMV or a bank card's contactless interface. Samy stripped the chip-and-PIN-disabling code and withheld the Amex prediction algorithm, so what you can build is the demonstration, not the attack. Where magstripe emulation still genuinely works is the long tail: hotel key cards, gym and loyalty cards, some building-access magstripe readers, older parking and transit systems, and point-of-sale in regions that never migrated to chip.","released":"2015","aliases":["MagSpoof","Magspoof v1","Samy Kamkar magstripe emulator"],"capabilities":{"magspoof":"yes","hf_1356_emulate":"no","lf_125khz_emulate":"no","emv_read":"no","scriptable":"partial","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Building a coil and an ATtiny is unremarkable, and emulating your own cards is what the author designed it for - he is explicit that MagSpoof 'does not enable you to use credit cards that you are not legally authorized to use'."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2015-11","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"maltronics-malduino-3","hardware_id":"maltronics-malduino-3","name":"MalDuino 3","firmware":"MalDuino 3 firmware","firmware_kind":"third-party-product","vendor":"Maltronics","category":"usb-hid","subcategory":"badusb-stick","status":"out-of-stock","price_usd":44.45,"price_is_estimate":false,"skill_level":"beginner","skill_note":"A physical 3-position switch selects between two stored scripts or a setup mode that exposes the onboard storage - no wireless configuration, no app.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A cable-free, offline BadUSB stick with dual USB-A/USB-C connectors, 128MB of onboard storage, and a physical 3-position switch to select between two stored scripts or a setup mode that exposes the storage for editing. It supports 34 keyboard locales and spoofable VID/PID for both its HID and mass-storage personas.","honest_take":"This is the plug-in-only, no-wireless sibling to MalDuino W in the same product family - if you don't need remote/wireless triggering, it's the cheaper and simpler option and its 128MB of storage (versus the W's 4MB) is genuinely useful for file-exfiltration-style payloads. Maltronics doesn't publish the MCU for this specific revision, but the product line's history (Lite/Elite, both ATmega32U4-based, already in this database) makes an ATmega32U4-class native-USB chip the reasonable assumption rather than a confirmed fact - treat the exact silicon as unverified. As with the W, you're paying mostly for an assembled, documented, support-backed unit; the underlying trick (switch-selected DuckyScript payloads with VID/PID spoofing) is the same thing a $25 hobbyist board in this batch does.","aliases":[],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","usb_exfil":"partial","usb_keylogger":"no","hid_remote_trigger":"no","usb_payload_lang":"yes","hardware_destruct":"no","standalone_untethered":"yes","app_store":"no","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Owning the device is legal."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"medium"}},{"id":"malduino-elite","hardware_id":"malduino-elite","name":"MalDuino Elite","firmware":"MalDuino (Maltronics)","firmware_kind":"third-party-product","vendor":"Maltronics","category":"usb-hid","subcategory":"badusb","status":"discontinued","price_usd":44.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Write a DuckyScript text file, put it on the card, flip the switch, plug in. That simplicity was the point.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A commercial BadUSB from Maltronics: an ATmega32u4 board that enumerates as a USB keyboard and types DuckyScript payloads. The Elite variant added a microSD slot and a DIP switch bank so you could carry several payloads and pick one physically, rather than reflashing to change the script. It is discontinued; the line continues as MalDuino 3 and MalDuino W.","honest_take":"This is the entry that most needs a date check before anyone buys. The Elite is gone from the vendor's catalogue, so any tutorial or comparison recommending it is out of date. Of what replaced it, MalDuino 3 is a straight BadUSB with 128MB of onboard flash and 34 keyboard layouts at GBP35 but is currently sold out, and MalDuino W at GBP49 is the wireless one. And for context on value: a $3 CH552 board does the same keystroke injection, just without the storage, the layout coverage, the case, or a shop to email when it does not work. What you are buying from Maltronics is polish and support, not capability nobody else has.","released":"2017","aliases":["MalDuino","Malduino Elite","Maltronics MalDuino"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_mass_storage":"no","usb_exfil":"no","hid_remote_trigger":"no","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Owning it is legal."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"n/a - product discontinued","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"maltronics-malduino-w","hardware_id":"maltronics-malduino-w","name":"MalDuino W","firmware":"MalDuino-W","firmware_kind":"community","vendor":"Maltronics","category":"usb-hid","subcategory":"wireless-badusb-stick","status":"available","price_usd":62.23,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Scripts run/edit/delete/download entirely through a web interface over its own Wi-Fi hotspot - no separate cable-based reflashing needed for day-to-day payload work.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A wireless BadUSB stick built on the open-source WiFi Duck architecture (ATmega32U4 for injection, ESP8266 for Wi-Fi), letting an operator run, edit, and manage DuckyScript-style payloads over a web interface hosted by the device's own Wi-Fi hotspot instead of needing to physically reprogram it.","honest_take":"Maltronics doesn't publish the exact chips on their own product or docs pages, but their GitHub repo states plainly that MalDuino-W's firmware is a fork of Spacehuhn's open-source WiFiDuck project, and WiFiDuck's own documented hardware is an ATmega32U4 + ESP8266 pair - the same combination used by the $25 Wifi BadUSB board elsewhere in this batch, and the same open-source lineage. The $66 you're paying over that $25 hobbyist board buys an assembled dual-connector (USB-A + USB-C) unit, a maintained web-UI firmware fork, and a company that answers support requests - not different silicon.","aliases":[],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"unknown","usb_exfil":"unknown","usb_keylogger":"no","hid_remote_trigger":"yes","usb_payload_lang":"yes","wifi_ap_mode":"yes","hardware_destruct":"no","standalone_untethered":"partial","app_store":"no","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Owning the device is legal."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"unknown - no dated releases visible on the maltronics/MalDuino-W GitHub repo","app_store":"No","abandoned_risk":"low"}},{"id":"marauder-c5-adapter-flipper-zero","hardware_id":"marauder-c5-adapter","name":"Marauder C5 Adapter - Flipper Zero","firmware":"ESP32 Marauder","firmware_kind":"third-party-product","vendor":"JCMK LLC (JustCallMeKoko)","category":"wifi","subcategory":"flipper-wifi6-wardriving-module","status":"out-of-stock","price_usd":30.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Requires flashing Marauder firmware onto a separate ESP32-C5-DevKitC-1 yourself before it works - more setup than the pre-flashed C5 LowKey.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A bring-your-own-devkit adapter that hosts a user-supplied, user-flashed ESP32-C5-DevKitC-1 to run Marauder from a Flipper Zero, with onboard GPS, microSD, and an enclosure. It is the budget sibling of the C5 LowKey, trading a lower sticker price for the buyer sourcing and flashing their own radio module.","honest_take":"The lower price is misleading once you account for the ESP32-C5-DevKitC-1 you have to buy separately - total cost ends up close to or above the fully-assembled C5 LowKey, and you take on the flashing step yourself. It only makes sense if you already own a spare ESP32-C5-DevKitC-1, or you specifically want the DevKit to be swappable/reusable outside the adapter.","released":"2026","aliases":[],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"claimed","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_pmkid":"yes","wifi_wardriving":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","ble_scan":"unknown","bt_classic":"no","nrf24_scan":"no","subghz_rx":"no","standalone_untethered":"partial","app_store":"no"},"legal":{"risk_level":"medium","notes":"Same legal posture as the C5 LowKey: owning it is legal, using deauth/evil-twin features against networks you don't control is not, in most jurisdictions."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"masterkey-wifi-usb-keylogger","hardware_id":"masterkey-wifi-usb-keylogger","name":"Masterkey - WiFi USB Keylogger","vendor":"JustCallMeKoko","category":"usb-hid","subcategory":"keylogger-hid-injector","status":"out-of-stock","price_usd":45.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-play for basic logging, but writing Ducky Script injection payloads and using the Live Execute feature needs real scripting familiarity.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"An inline USB pass-through keylogger built around an ATmega32U4 (USB HID passthrough to the keyboard/host) and an ESP8266 (WiFi retrieval), running a modified fork of spacehuhn's wifi_keylogger project. It logs keystrokes to the ESP8266's filesystem, serves a web interface over its own \"Masterkey\" access point at 192.168.4.1, and can also run Ducky Script keystroke-injection payloads live or from saved scripts — combining keylogging and HID injection in one device, from the ESP32 Marauder author.","honest_take":"This is honestly closer to 'an ESP8266 plus an ATmega32U4 in a 3D-printed case, running a fork of a well-known open-source project' than a from-scratch design — the vendor's own listing credits spacehuhn's wifi_keylogger as the base, which is fair and transparent, but worth knowing if you'd rather build the equivalent yourself for the cost of the two chips. The default AP password is documented in the wild (open-source repo), so if you deploy one, change the Wi-Fi credentials immediately or anyone in range who knows the project can pull your logs. It's one of the only devices in this batch that combines logging AND scripted HID injection in a single $45 device, which is a genuine capability edge over pure loggers like KeyGrabber or the generic extension-cable keylogger — but the GitHub repo (justcallmekoko/USBKeylogger) hasn't been pushed to since March 2021, so treat it as a frozen, unmaintained snapshot rather than an actively supported tool.","released":"2020","aliases":["USBKeylogger"],"capabilities":{"usb_keylogger":"yes","usb_hid_inject":"yes","hid_remote_trigger":"yes","usb_exfil":"yes","wifi_ap_mode":"yes","usb_mass_storage":"no","usb_payload_lang":"yes","scriptable":"yes","standalone_untethered":"no","sd_logging":"no","ble_scan":"no"},"legal":{"risk_level":"high","notes":"Owning the hardware is generally legal."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2021-03","app_store":"No","abandoned_risk":"high"}},{"id":"mellon-osdp","hardware_id":"mellon-osdp","name":"Mellon","firmware":"Stock (Bishop Fox)","firmware_kind":"diy","vendor":"Bishop Fox","category":"rfid-nfc","subcategory":"osdp-attack-tool","status":"diy-only","price_usd":15.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You need to understand OSDP wiring (RS485 A/B, controller vs. reader roles), physically tap or insert into the wiring between a door controller and a reader, and interpret raw protocol captures - this is not a point-and-click tool.","build_effort":"full-diy","stealth":"covert","form_factor":"board","summary":"Bishop Fox's reference proof-of-concept toolkit for attacking OSDP (Open Supervised Device Protocol), the RS485 protocol that connects most modern access-control card readers to their door controllers. It implements the five attacks from their 2023 Black Hat/DEF CON research 'Badge of Shame': passive eavesdropping of unencrypted card numbers, forcing an encryption downgrade, extracting the shared key during install mode, capturing keys sent during a key-rotation, and brute-forcing weak/default keys. It's a research tool released alongside the talk, not a commercial product, and it deliberately does not read or clone RFID/NFC cards itself - it attacks the wire between the reader and the controller.","honest_take":"Mellon is the reference implementation behind real, disclosed OSDP weaknesses - not marketing. The catch is that most of its attacks (downgrade, install-mode key extraction, weak-key brute force) require physical access to the RS485 wire between reader and controller, which usually means opening a reader or getting inside a wiring closet; this is a wired-access-control research tool, not a wireless card-cloning tool like a Proxmark or Flipper - it has zero RFID/NFC card-reading capability of its own, which is easy to assume given the category it's filed under. Independent commentary (IPVM) has since pushed back that the practical exploitation bar is higher than the DEF CON framing implied, since several attacks need sustained physical bus access most attackers won't have. The single most common misconception is treating this as a plug-and-play badge cloner - it attacks the wire, not the card.","released":"2023","aliases":["Mellon OSDP Attack Tool","Badge of Shame toolkit"],"capabilities":{"uart":"yes","scriptable":"yes","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","mifare_classic_attacks":"no","nfc_relay":"no","magspoof":"no","standalone_untethered":"no","web_ui":"no","app_store":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"The code itself is a legal research tool, published openly by a security firm alongside a conference talk."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2023-08","app_store":"No","abandoned_risk":"medium"}},{"id":"meowkit-s3","hardware_id":"meowkit-s3","name":"MeowKit S3","firmware":"MeowKit firmware (stock)","firmware_kind":"stock","vendor":"MeowKit (Hong Kong)","category":"multitool","subcategory":"esp32-handheld","status":"available","price_usd":143.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"A finished handheld with a touchscreen, but the interesting work is writing or installing Lua apps.","build_effort":"assembled","stealth":"discreet","form_factor":"handheld","summary":"A standalone ESP32-S3 pocket device with a 2.0-inch colour touchscreen, 16 MB flash and 8 MB PSRAM, audio in and out, an IMU, an RTC, IR transmit and receive, a microSD slot and an Arduino-style GPIO header. It funded on Kickstarter in late 2025 at nearly 2,800 percent of goal and ships with open-source Lua-scriptable firmware.","honest_take":"The 'Flipper Zero killer' framing in the YouTube coverage is not supportable by the hardware: there is no sub-GHz radio at all - no CC1101, nothing at 433/868/915 MHz - and no 125 kHz LF RFID, which between them are most of what people actually use a Flipper for. The 13.56 MHz NFC reader is an optional extra, not standard. What it is instead is a very well-specified ESP32-S3 handheld: bigger screen, far more memory, audio, motion sensing and a real GPIO header. Judge it as a maker's pocket computer, not as an RF tool. One published figure to distrust: at least one review quotes 2800 mAh; the vendor's own tech-spec page says 1200 mAh.","released":"2025","aliases":["MeowKit","MeowKit-S3","MeowKit S3 Standard Edition"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_ap_mode":"yes","wifi_deauth_24":"unknown","ble_scan":"yes","ble_advertise":"yes","bt_classic":"no","hf_1356_read":"addon","hf_1356_emulate":"addon","lf_125khz_read":"no","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","usb_hid_inject":"partial","usb_mass_storage":"yes","scriptable":"yes","sd_logging":"yes","standalone_untethered":"yes","subghz_rx":"no","subghz_tx":"no","ibutton_1wire":"no"},"legal":{"risk_level":"low","notes":"With no sub-GHz radio and no LF RFID, it raises far fewer regulatory questions than a Flipper Zero, and we found no import restrictions on it."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No formal store; Lua app folders are copied to the SD card over USB","abandoned_risk":"medium"}},{"id":"mini-daplink-debug-probe-muselab","hardware_id":"mini-daplink-debug-probe-muselab","name":"Mini DAPLink Debug Probe","firmware":"Stock (MuseLab, DAPLink-based)","firmware_kind":"stock","vendor":"MuseLab","category":"hardware-debug","subcategory":"jtag-swd-probe","status":"available","price_usd":4.8,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Standard driverless CMSIS-DAP operation with Keil/IAR/pyOCD/OpenOCD - if you've used any DAPLink-class probe before, this behaves the same way.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A 3.2 x 1.7 cm USB-C CMSIS-DAP/DAPLink probe for ARM Cortex-M targets (STM32, GD32, nRF51/52) over SWD or JTAG, with a built-in UART bridge that enumerates as a serial port alongside the debug interface. At $4.80 it is the budget floor of the debug-probe market covered in this batch, and the same MuseLab store also sells a 'Mini High-Speed DAPLink' variant, implying this base model is the slower of the two.","honest_take":"This is the price-to-performance benchmark every other probe in this batch has to be measured against: $4.80 for a driverless, CMSIS-DAP-compliant SWD/JTAG probe plus a UART bridge is genuinely hard to beat, and it is built on the same DAPLink lineage as far more expensive branded probes. The vendor's claim of being faster than J-Link/ST-Link at a lower price is a marketing line from the Tindie listing, not something independently benchmarked here - mark it as claimed, not confirmed, and note that MuseLab sells a separate 'Mini High-Speed DAPLink' as a different product, which quietly suggests this base model is not the fast option in their own lineup. Its real limitation next to the IBDAP or XDS110 in this batch is scope: it is SWD/JTAG-plus-UART only, with no I2C/SPI/ADC breakout or glitching, so it is a pure debug probe rather than a general peripheral-access tool.","released":"2023","aliases":[],"capabilities":{"jtag_swd":"yes","uart":"yes","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","glitching":"no","scriptable":"unknown","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A bench debug probe with no radio - legal to own and use everywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"mini-rtl-sdr-dongle-hackergadgets","hardware_id":"mini-rtl-sdr-dongle-hackergadgets","name":"Mini RTL-SDR Dongle","firmware_kind":"n/a","vendor":"Hacker Gadgets","category":"sdr","subcategory":"rx-only-dongle","status":"available","price_usd":49.5,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug in, install SDR++ or SDR#, and you are receiving within minutes; no way to transmit and therefore no way to break the law with the hardware itself.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A compact receive-only RTL2832U+R860 SDR dongle in a CNC aluminum case with USB-C, a 1 PPM TCXO, an SMA connector and a software-switchable 5V bias tee, covering 100 kHz-1.74 GHz (HF below 28.8 MHz via direct sampling).","honest_take":"Functionally this is an RTL-SDR Blog V3-class dongle (single-input R860/R820T2 tuner, direct-sampling HF, no dedicated upconverter) in a nicer aluminum shell with USB-C instead of micro-USB - not a new design. At $49.50 it costs $10-15 more than a bare RTL-SDR Blog V3, which has the identical TCXO-and-bias-tee feature set; the premium buys the case and connector, not better reception. Community documentation, tutorials and troubleshooting all assume the RTL-SDR Blog boards, so a first-timer following any RTL-SDR guide will be working slightly off-script with this one.","aliases":[],"capabilities":{"sdr_rx":"yes","sdr_tx":"no","sdr_bandwidth":"yes","subghz_rx":"yes","subghz_tx":"no","subghz_rolling_code":"no","subghz_external_antenna":"yes","gps":"partial","scriptable":"yes","wifi_scan_24":"no","ble_scan":"no","packet_capture":"partial","standalone_untethered":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"Receive-only; owning and using it is legal essentially everywhere, subject to the normal local caveats about intercepting cellular or other protected traffic."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"minino","hardware_id":"minino","name":"Minino","firmware":"Minino stock firmware","firmware_kind":"stock","vendor":"Electronic Cats","category":"multitool","subcategory":"iot-multitool","status":"available","price_usd":65.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Menu-driven on a small OLED; no host computer needed for most functions.","build_effort":"assembled","stealth":"overt","form_factor":"pocket","summary":"An ESP32-C6 pocket tool with GPS, OLED and microSD that covers 2.4 GHz Wi-Fi, BLE and 802.15.4 (Zigbee/Thread/Matter) from one menu: wardriving, deauth, beacon spam, BLE tracker detection, Zigbee sniffing to Wireshark, Remote ID drone decoding and a Flock Safety ALPR/body-cam detector. It is the closest thing to a Flipper for the IoT/2.4 GHz side.","honest_take":"It is an ESP32-C6 in a nice case with a GPS bolted on - there is no sub-GHz radio, no NFC/RFID and no infrared, so it is not a Flipper replacement. Everything it does is 2.4 GHz plus GNSS. The 'surveillance detection' features are pattern matching on Wi-Fi/BLE identifiers of known camera and ALPR gear, so they find kit that advertises itself and miss anything that does not.","released":"2024","aliases":["Minino IoT Multitool","Mini Cat"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_captive_portal":"yes","wifi_wardriving":"yes","ble_scan":"yes","ble_sniff":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_hid":"yes","ble_tracker_detect":"yes","zigbee":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","detect_drone":"yes","detect_surveillance_cam":"partial","detect_generic_wifi":"yes","subghz_rx":"no","hf_1356_read":"no","web_ui":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Deauthentication, beacon flooding and BLE advertisement spam are transmissions that disrupt other people's equipment and are illegal in many countries even as a demo."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No - single firmware with a menu of apps, OTA updates","abandoned_risk":"low"}},{"id":"monstatek-m1-stock","hardware_id":"monstatek-m1","name":"Monstatek M1","firmware":"M1 firmware (official)","firmware_kind":"stock","vendor":"MonstaTek","category":"multitool","subcategory":"rf-multitool","status":"preorder","price_usd":180.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Feature set and menus are Flipper-like and approachable, but this is an early-production device with reported per-unit hardware faults and no retail support channel.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"A Flipper-shaped multitool built on an STM32H573 - a Cortex-M33 with TrustZone, hardware crypto and PSA Certified Level 3 security, which is a genuinely serious MCU for this class - carrying an Si4463 sub-GHz transceiver, an ST25R3916 NFC front end, a 125 kHz RFID coil, infrared with a bundled database, microSD and USB. It has no radio of its own for Wi-Fi or Bluetooth; an ESP32-C6 co-processor on an SPI link provides those. The firmware is GPL-3.0 and written from scratch.","honest_take":"The Si4463 is the one place where this genuinely beats a Flipper Zero: it tunes continuously rather than in three bands and puts out around +20 dBm against the CC1101's +12, though the M1's own firmware only claims 315-915 MHz, which is roughly Flipper territory anyway. Everything else is a warning. The vendor's website is stale enough to be misleading - it advertises Bluetooth 4.2 BR/EDR when the shipping co-processor is an ESP32-C6 that has no Bluetooth Classic at all, and it says 'microSDHC up to 256GB' when microSDHC by definition stops at 32 GB. The GPIO is 5V-capable on the Kickstarter and 3.3V CMOS on the website. There is no shop, no price and no support channel, delivery has run two years behind for some backers, and firmware development has been quiet since June 2026 while the community picks up the slack with an app SDK and desktop companion. The hardware is real and the firmware is honestly open; the operation around it is not a retail business yet.","released":"2026","aliases":["M1","MonstaTek M1","M1 Multitool"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"unknown","subghz_rolling_code":"unknown","subghz_external_antenna":"addon","lf_125khz_read":"yes","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_emulate":"partial","iso15693":"yes","felica":"yes","ir_tx":"yes","ir_rx":"yes","ir_learn":"yes","ir_universal_remote":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_ap_mode":"yes","wifi_deauth_24":"unknown","ble_scan":"yes","ble_advertise":"yes","bt_classic":"no","usb_hid_inject":"yes","usb_mass_storage":"yes","sd_logging":"yes","scriptable":"partial","app_store":"no","standalone_untethered":"yes","web_ui":"no","sdr_rx":"no","gps":"no","ibutton_1wire":"unknown"},"legal":{"risk_level":"medium","notes":"Owning it is legal in most places."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"No official store; a community SDK and app runtime exist","abandoned_risk":"medium"}},{"id":"morfeus","hardware_id":"morfeus","name":"moRFeus","firmware":"Stock (Othernet)","firmware_kind":"stock","vendor":"Othernet","category":"accessory","subcategory":"frequency-converter-signal-generator","status":"available","price_usd":159.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Useful only if you already understand frequency mixing/up-down conversion and why you'd want to shift a signal outside your SDR's native tuning range.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A pocket-sized, field-configurable RF frequency mixer and continuous-wave signal generator covering a 30MHz-6GHz input/output range with an 85MHz-5.4GHz local oscillator, switchable between mixer mode (up/down-converting a signal in or out of another SDR's usable range) and standalone CW generator mode. Configured via an onboard LCD/button interface or programmatically over USB HID.","honest_take":"This is a lab accessory, not a radio you use on its own - in mixer mode it doesn't receive or transmit anything itself, it just frequency-shifts whatever signal you feed it so a separate SDR (like a HackRF or RTL-SDR) can reach frequencies outside its native tuning range. The exact mixer/synthesizer IC is not officially disclosed by the vendor; independent hobbyist analysis based on the frequency specs has speculated it's built around an RFFC5071/RFFC5072-class wideband synthesizer/mixer, but that is not vendor-confirmed. In CW generator mode it can put out a signal across a huge span (30MHz-6GHz) with low spurious emissions, which makes it genuinely useful as a cheap signal source for testing receivers - just remember any output on a licensed band without authorization is a regulatory problem independent of the device's own legality.","released":"2018","aliases":["Outernet moRFeus"],"capabilities":{"sdr_rx":"no","sdr_tx":"partial","sdr_bandwidth":"no","sdr_full_duplex":"no","scriptable":"yes","standalone_untethered":"yes","app_store":"no","wifi_scan_24":"no","gps":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"Owning the device is legal."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"medium"}},{"id":"hackerwarehouse-mouse-jiggler","hardware_id":"hackerwarehouse-mouse-jiggler","name":"Mouse Jiggler","firmware":"unknown/proprietary","firmware_kind":"third-party-product","vendor":"Generic (sold via Hacker Warehouse)","category":"usb-hid","subcategory":"mouse-jiggler","status":"available","price_usd":20.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug in and forget - no configuration, no software, no switches.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A USB device that enumerates as a generic mouse and injects small, randomized cursor movements referenced back to the original position, purely to prevent screensaver/idle-lock/sleep from triggering. It is not an attack tool - it's an operational-support accessory used during physical or remote engagements (or ordinary desk use) to keep a session from locking.","honest_take":"This is the simplest, most single-purpose device in the entire batch, and that's fine - it does exactly one narrow thing and the vendor doesn't oversell it. The common misconception is that 'mouse jiggler' implies something clever defeating enterprise idle-detection; in reality this is a generic HID mouse sending small relative movements, and independent security-vendor writeups describe exactly this class of device being flagged by modern EDR (naming CrowdStrike, SentinelOne and Microsoft Defender for Endpoint) via synthetic-movement timing analysis or known jiggler HID/VID-PID signatures - so treat 'undetectable' marketing claims skeptically in a monitored enterprise environment even though the movement itself is genuinely imperceptible to a human eye. No MCU, firmware source, or internal design is published by the vendor, unlike the open-source ATtiny85/Digispark mouse-jiggler projects that do the same thing for a few dollars in parts if you're willing to build one.","aliases":["USB Mouse Mover","Mouse Mover"],"capabilities":{"usb_hid_inject":"no","usb_mass_storage":"no","usb_exfil":"no","usb_keylogger":"no","hid_remote_trigger":"no","usb_payload_lang":"no","scriptable":"no","standalone_untethered":"yes","app_store":"no"},"legal":{"risk_level":"low","notes":"Generally legal to own and use for keeping your own session active."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"n/a - fixed-function hardware product, no firmware updates","app_store":"No","abandoned_risk":"low"}},{"id":"msi-sdr","hardware_id":"msi-sdr","name":"MSi.SDR 10kHz-2GHz Panadapter SDR Receiver","firmware_kind":"n/a","vendor":"MMM999 (Tindie reseller; original manufacturer of this clone not disclosed)","category":"sdr","subcategory":"rsp1-clone-receiver","status":"available","price_usd":65.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Works with SDRplay's own software stack once installed, so the learning curve is SDRplay's, not a new one - but you are troubleshooting a clone with unofficial support if something goes wrong.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A receive-only 12-bit SDR in an aluminum case covering 10 kHz-2 GHz with up to 10 MHz of bandwidth, built on Mirics-family silicon - the same chip family SDRplay uses in its RSP line - and enumerating to the host as an SDRplay RSP1, so it runs SDRplay's own SDRuno/EXTIO software and anything else that speaks the RSP1 driver.","honest_take":"Call this what independent reviewers already call it: a Chinese clone of the (now-discontinued) SDRplay RSP1, not an original design - it works because it uses Mirics chips and presents itself as the real thing over USB. It is genuinely good value on HF (reviewers found it close to indistinguishable from a real RSP1/RSP1A on shortwave), but it has 'very minimal filtering' compared to SDRplay's own current RSP1A, so expect more intermodulation and image problems on crowded bands without external filtering. It is also 12-bit, not the 14-bit ADC of the current SDRplay RSP1A (~$100, still in production, official support and firmware updates) - if you can stretch the extra ~$35, the genuine article gets you two more bits of dynamic range and a vendor who will answer support requests. None of your money reaches SDRplay when you buy this clone.","aliases":["MSI.SDR","MSi SDR RSP1 clone"],"capabilities":{"sdr_rx":"yes","sdr_tx":"no","sdr_bandwidth":"yes","sdr_full_duplex":"no","subghz_rx":"yes","subghz_tx":"no","subghz_rolling_code":"no","wifi_scan_24":"no","ble_scan":"no","gps":"partial","scriptable":"yes","packet_capture":"partial","standalone_untethered":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"Receive-only device; owning and listening is legal essentially everywhere, with the usual caveats about which specific traffic (e."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"multifunction-network-box","hardware_id":"multifunction-network-box","name":"Multifunction Network Box","firmware":"Custom Linux build","firmware_kind":"third-party-product","vendor":"Hacker Warehouse (custom build; underlying hardware OEM not disclosed)","category":"network-implant","subcategory":"engagement-router","status":"available","price_usd":1500.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"It's a bare Linux appliance you configure yourself for traffic logging and selective blocking during an engagement; there's no turnkey point-and-click workflow documented.","build_effort":"assembled","stealth":"overt","form_factor":"box","summary":"A custom-built, LCD-equipped Linux network appliance with 8-16 Gigabit Ethernet ports, sold by Hacker Warehouse as an all-in-one alternative to running a separate network tap plus a separate logging/blocking host during an engagement. It is positioned as combining traffic logging with active selective blocking, which a passive tap alone cannot do.","honest_take":"Strip away the case and LCD and the two tiers are, respectively, a dual-core Atom mini-PC with 2GB of RAM and a Core i5 box with 16GB - ordinary small-form-factor PC hardware with several Ethernet ports, running unspecified Linux software, for $1,500 and $3,000. There is no published detail on the actual blocking mechanism (iptables-style rules? a real inline proxy?), whether the box fails open or closed if it crashes or loses power, or whether it can defeat or merely sits behind things like 802.1X - none of that is documented anywhere in the listing. You are paying almost entirely for Hacker Warehouse's integration and the 'one box for a multi-person engagement' framing; a comparably specced mini-PC with a few USB/PCIe NIC cards and open-source bridging + tcpdump/nftables software would cost a small fraction of this if you're willing to build and validate the software stack yourself.","aliases":["Model 100","Model 1000"],"capabilities":{"packet_capture":"claimed","ethernet_mitm":"partial","ethernet_tap_passive":"no","standalone_untethered":"yes","cloud_c2":"unknown","vpn_exfil":"unknown","hdmi_capture":"no","usb_hid_inject":"no","wifi_scan_24":"no","web_ui":"unknown","app_store":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"Legal to own."},"ecosystem":{"community":"commercial","docs_quality":"poor","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"multipick-kronos-epg","hardware_id":"multipick-kronos-epg","name":"Multipick Kronos EPG","firmware_kind":"n/a","vendor":"Multipick (sold in the security-tool market as 'Kronos Electric Pick' by Lab401 and others)","category":"hardware-debug","subcategory":"electric-lock-pick","status":"available","price_usd":250.52,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Consistent tension and needle placement matter more than raw power; reviewers describe real competence as taking deliberate practice, more so on security-pin cylinders.","build_effort":"assembled","stealth":"discreet","form_factor":"handheld","summary":"A German-made (Multipick) motorized electric pick gun for non-destructive opening of pin-tumbler profile cylinders, including many standard high-security cylinders. A DC motor drives a needle at up to 13,000 strokes/minute with adjustable 1-4mm stroke amplitude, aimed at locksmiths and physical-penetration testers rather than hobbyists.","honest_take":"This is a pin-tumbler tool and only a pin-tumbler tool: it is explicitly not effective on disc-detainer, dimple or wafer locks, which is the most common misconception buyers have about 'electric pick guns' in general - people assume one tool defeats all lock families the way a Flipper is assumed to defeat all RFID. Vendor claims of opening '75%+ of locks with practice' are for standard pin-tumbler cylinders under favorable conditions; tight keyways and genuine security pins still demand real skill and time, motor or no motor. At $232-250 for the bare unit it undercuts hand-picking training time, but it is not a shortcut past lock-picking skill - it automates the raking motion, not the reading of pins.","aliases":["Kronos Electric Pick","Multipick Elite Kronos EPG","Kronos EPG"],"capabilities":{"standalone_untethered":"yes","hid_remote_trigger":"no","scriptable":"no","usb_mass_storage":"no","web_ui":"no","jtag_swd":"no","i2c":"no","glitching":"no","magspoof":"no"},"legal":{"risk_level":"medium","notes":"Possession of lock-picking tools is legal in most US states and much of Europe for personal or professional use, but a handful of US states and other countries restrict possession without a locksmith license or 'burglary tool' intent, and using it on a lock you don't own or lack authorization to open is a property/burglary offence everywhere."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"n/a","abandoned_risk":"low"}},{"id":"nanovna-f","hardware_id":"nanovna-f","name":"NanoVNA-F","firmware":"Stock (DeepElec/NanoVNA)","firmware_kind":"stock","vendor":"DeepElec (design); manufactured/sold via resellers including Zeenko-branded units","category":"accessory","subcategory":"vector-network-analyzer","status":"available","price_usd":143.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Reading Smith charts and S-parameter plots to tune an antenna requires some RF theory background, though the touchscreen makes basic SWR checks approachable.","build_effort":"assembled","stealth":"discreet","form_factor":"handheld","summary":"A handheld Vector Network Analyzer (the base 'F' model, distinct from the higher-range 'F V2') covering roughly 50kHz-1.5GHz, used to measure and tune antennas (SWR, S-parameters, Smith chart) rather than to receive or analyze arbitrary signals. It has a 4.3-inch touchscreen and a 5000mAh battery.","honest_take":"This is not an SDR and cannot receive, demodulate, or capture arbitrary signals - it measures how a passive RF network (almost always an antenna) reflects and passes energy at swept frequencies, which is a completely different function that only looks superficially similar to spectrum/signal tools because of the touchscreen and SMA connectors. Its practical use in a pentest kit is narrow but real: confirming an antenna is actually resonant and well-matched at your target frequency before you trust range/reception numbers from a HackRF, CC1101, or other radio attached to it. Don't confuse this base 'NanoVNA-F' (50kHz-1.5GHz) with the very similarly-named 'NanoVNA-F V2' (50kHz-3GHz) - sellers are inconsistent about which one they mean, so confirm the exact model before buying if the upper frequency matters to you.","released":"2020","aliases":[],"capabilities":{"sdr_rx":"no","sdr_tx":"no","sdr_bandwidth":"no","scriptable":"yes","standalone_untethered":"yes","sd_logging":"unknown","app_store":"no","web_ui":"no","wifi_scan_24":"no","gps":"no","packet_capture":"no"},"legal":{"risk_level":"low","notes":"A VNA is a passive measurement instrument; it carries essentially no independent legal risk to own or use."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"negotchi","hardware_id":"negotchi","name":"Negotchi - Network Security Scanner","firmware":"Netgotchi","firmware_kind":"diy","vendor":"OlleStore","category":"detection-defense","subcategory":"network-honeypot-scanner","status":"available","price_usd":44.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Configured entirely through an on-device AutoConnectAP web portal; no coding needed to use it, only to modify it.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"The base model in the Netgotchi line: an ESP8266 + small OLED board that periodically scans the local 2.4GHz Wi-Fi network for hosts and runs a honeypot service, sounding an on-screen alarm (the on-screen character 'crying') if the honeypot is touched. Same firmware as Netgotchi Pro, in a smaller/cheaper non-portable form.","honest_take":"Identical function to the pricier Netgotchi Pro - same open-source code (MXZZ/Netgotchi), same ESP8266 scan-and-honeypot behavior, same 2.4GHz-only limitation, same complete blindness to actual attacker RF hardware (Pineapples, Flippers, rogue APs) since it only watches hosts on the one network it joins. At $15 less than the Pro, this is the better buy for anyone who doesn't specifically need the Pro's pocket-portable case, since the detection capability is the same either way.","aliases":["Netgotchi (base)"],"capabilities":{"wifi_scan_24":"yes","scriptable":"yes","standalone_untethered":"yes","web_ui":"yes","usb_hid_inject":"no","ble_scan":"no","subghz_rx":"no","gps":"no","app_store":"no","cloud_c2":"no","vpn_exfil":"no","ethernet_tap_passive":"no","hf_1356_read":"no","network_host_scan":"yes"},"legal":{"risk_level":"low","notes":"Purely defensive; legal to build, own, and run on a network you control."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"netgotchi-pro","hardware_id":"netgotchi-pro","name":"Netgotchi Pro","firmware":"Netgotchi","firmware_kind":"diy","vendor":"OlleStore","category":"detection-defense","subcategory":"network-honeypot-scanner","status":"available","price_usd":59.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Configured entirely through an on-device AutoConnectAP web portal; no coding needed to use it, only to modify it.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A pocket-portable ESP8266 + OLED network security scanner: it periodically scans the local Wi-Fi network for hosts, reports newly connected devices, and runs a honeypot service that triggers an on-screen visual alert (and, from v2, a sound alert) if touched. Despite 'battery-powered' in some marketing copy, the product page itself specifies it is USB-powered from an external power bank (not included), not from a built-in cell.","honest_take":"This is a Pwnagotchi-style novelty display wrapped around a very simple ESP8266 network scanner and single honeypot port - the personality/crying-on-alert framing is cosmetic, the actual security function is a periodic host sweep plus one exposed decoy service, and the open-source code (MXZZ/Netgotchi on GitHub) is identical to what runs on the cheaper Negotchi. You're paying the $15 premium over the base Negotchi for portability and a nicer case, not for different detection capability. It also only watches the one Wi-Fi network it's joined to - it has no ability to detect attacker RF hardware like a Pineapple or a Flipper (that's a different category of device entirely).","aliases":[],"capabilities":{"wifi_scan_24":"yes","scriptable":"yes","standalone_untethered":"yes","web_ui":"yes","usb_hid_inject":"no","ble_scan":"no","subghz_rx":"no","gps":"no","app_store":"no","cloud_c2":"no","vpn_exfil":"no","ethernet_tap_passive":"no","hf_1356_read":"no","network_host_scan":"yes"},"legal":{"risk_level":"low","notes":"Purely defensive; legal to build, own, and run on a network you control."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"netninja-wardriving-gps-marauder","hardware_id":"netninja-wardriving-gps-marauder","name":"NetNinja Wardriving GPS Marauder","firmware":"ESP32 Marauder","firmware_kind":"third-party-product","vendor":"BPM Circuits","category":"wardriving","subcategory":"flipper-zero-addon","status":"out-of-stock","price_usd":100.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Arrives pre-assembled and pre-flashed; plug it onto the Flipper's GPIO/UART header and run the Marauder companion app.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A purpose-built ESP32-WROOM-32UE add-on board for the Flipper Zero, combining a battery-backed GPS module and a high-gain 2.4GHz antenna with a BPM Circuits fork of the ESP32 Marauder firmware. Unlike the Texas Flipper Boards competitor, its firmware target ships with Bluetooth/BLE compiled in, so it adds BLE scanning and spam on top of Wi-Fi wardriving. It writes wardriving data directly to the Flipper Zero's own microSD card and reports status via an onboard RGB NeoPixel and TX/RX LEDs.","honest_take":"Strip the branding away and this is an ESP32-WROOM-32UE running a forked build of the same open-source Marauder firmware every ESP32 wardriving board runs - the real differentiators are a battery-backed GPS module (faster first satellite fix than a bare GPS chip) and a purpose-built PCB with Bluetooth left switched on, unlike the $120 Texas Flipper Boards competitor, whose stock firmware target has Bluetooth explicitly compiled out. At $100 this is $20 cheaper and, on that evidence, the more capable of the two boards. The catch: the fork's own configs.h reports firmware version v1.2.1 while the upstream project it's based on is at v1.16.0, meaning it's frozen well behind current Marauder - newer scan/detection modes (Flock Safety camera detection, newer BLE spam variants, and other features added to upstream since) may simply not be present here, and there's no way to tell without the vendor publishing a changelog. It has no storage of its own - everything is written to the Flipper's SD card - and the original dual-core ESP32 (not an S2/S3/C-series part) means 2.4GHz-only Wi-Fi with no 5GHz visibility. As of September 2026 BPM Circuits has stopped taking orders, so neither board in this comparison is actually purchasable right now.","aliases":["NetNinja","NetNinja Marauder Board"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_deauth_5":"no","wifi_evil_twin":"unknown","wifi_captive_portal":"unknown","wifi_handshake_capture":"yes","wifi_pmkid":"unknown","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","wifi_wardriving":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","standalone_untethered":"no","scriptable":"partial","ble_scan":"yes","ble_advertise":"yes","bt_classic":"no","ble_spam_apple":"unknown","ble_tracker_detect":"unknown","detect_flipper":"unknown","detect_pineapple":"unknown","detect_pwnagotchi":"unknown","subghz_rx":"no","hf_1356_read":"no","lf_125khz_read":"no","ir_tx":"no","usb_hid_inject":"no","nrf24_scan":"no","mousejack":"no","zigbee":"no"},"legal":{"risk_level":"medium","notes":"Owning the board and passively wardriving/logging is legal in most places."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No - relies on the Flipper Zero Marauder companion app","abandoned_risk":"medium"}},{"id":"newae-probe-set-psu","hardware_id":"newae-probe-set-psu","name":"NewAE Probe Set with Power Supply","firmware_kind":"n/a","vendor":"NewAE Technology","category":"accessory","subcategory":"side-channel-probes","status":"available","price_usd":350.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Passive sensing accessories for power/EM side-channel analysis - useful only if you already have a capture instrument (oscilloscope or ChipWhisperer) and know how to use differential/H-field probes for SCA.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"An isolated USB-powered supply (5V USB in, delivering 3.3V for an LNA and +/-7.8V for a differential probe, with up to 50V isolation to prevent ground-loop contamination - functionally NewAE's CW503 Probe Power Supply) sold together with three sensing probes matching NewAE's CW501 differential probe and CW505-class H-field/LNA probe lines: a differential probe for power-consumption analysis, an LNA probe and an H-field probe for electromagnetic side-channel measurement. It's a sensing accessory, not a capture instrument - you still need an oscilloscope or ChipWhisperer to record what the probes pick up.","honest_take":"This is instrumentation, not an attack tool by itself, and there is no capability key in this database's schema for 'passive power/EM side-channel sensing probe' - that gap is itself worth noting, since it means this device's actual function doesn't show up anywhere in the comparison table below. The differential and H-field probes measure power draw and EM emissions, which only becomes a side-channel attack once fed into capture and analysis software (ChipWhisperer or your own scope + DPA/CPA toolchain) and correlated against known plaintext/ciphertext. The isolated power supply is the unglamorous but important part: NewAE's own documentation notes the differential probe's supply rails must sit at least 2V above/below the common-mode voltage, and without galvanic isolation, ground loops between your target and your scope can swamp exactly the small signals these probes are trying to measure.","aliases":["NAE-PBSET-PSU-03"],"capabilities":{"glitching":"no","jtag_swd":"no","uart":"no","i2c":"no","scriptable":"no","standalone_untethered":"no","spi_flash_dump":"no","logic_analyzer":"no","web_ui":"no","app_store":"no","side_channel_power":"addon"},"legal":{"risk_level":"low","notes":"Passive sensing/measurement accessories with no transmitter - equivalent in legal terms to oscilloscope probes."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"newsheen-cat-lamp","hardware_id":"newsheen-cat-lamp","name":"Newsheen Hacker Smart Cat Lamp Kit (pre-assembled)","firmware":"Stock lamp firmware","firmware_kind":"stock","vendor":"Retia (base hardware OEM'd as 'Newsheen')","category":"accessory","subcategory":"hackable-iot","status":"out-of-stock","price_usd":75.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Works as a plain smart lamp immediately. Turning it into a mesh node or anything else needs ESP32 flashing knowledge Retia doesn't teach on this product page.","build_effort":"assembled","stealth":"covert","form_factor":"desktop","summary":"A squishy cat-shaped desk lamp built on a Newsheen-brand ESP32-S3 smart-lighting reference board, resold by Retia with the microcontroller left open for reflashing. Out of the box it is a Wi-Fi/Bluetooth smart light; owners can reflash the same ESP32-S3 into an audio-reactive light, an internet radio, or a Meshtastic/Meshcore/Reticulum mesh node.","honest_take":"Be clear about what this is: a smart lamp with a reflashable chip, not a security tool. There is no scanning, no attack capability, no detection feature, and nothing in Retia's own description claims one - the 'hacker' branding refers entirely to the fact that a buyer can put their own firmware on it, the same as any bare ESP32-S3 dev board would allow. Its only real relevance to this comparison is as the cheapest, most disguised possible carrier for a Meshtastic/Meshcore mesh node - genuinely excellent cover if that's the goal, since nothing about a cat lamp on a desk draws attention - but if the goal is actual Wi-Fi/BLE security capability, this ships with none, and a buyer would be writing all of that themselves.","released":"2026","aliases":["Hacker Cat Lamp"],"capabilities":{"rgb_backlight":"yes","scriptable":"yes","wifi_scan_24":"unknown","ble_scan":"unknown","wifi_deauth_24":"no","usb_hid_inject":"no","hf_1356_read":"no","subghz_rx":"no","gps":"no","standalone_untethered":"yes","lf_125khz_read":"no","ir_tx":"no","mousejack":"no","detect_generic_wifi":"no","wifi_monitor_mode":"no","mesh_lora":"unknown"},"legal":{"risk_level":"low","notes":"As shipped, it's a smart lamp - no meaningful legal exposure."},"ecosystem":{"community":"slow","docs_quality":"poor","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"hermitx-nfc-cardreader-esp32s3","hardware_id":"hermitx-nfc-cardreader-esp32s3","name":"NFC Card Reader Module with ESP32-S3","firmware_kind":"stock","vendor":"HermitX (Ivan Hermida / HermitX SLU)","category":"rfid-nfc","subcategory":"nfc-dev-board-audio-visual","status":"available","price_usd":46.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Ships as a dev board with maker-project example firmware (Arduino/ESP-IDF/MicroPython/ESPHome) - any pentest-style behaviour has to be written by the buyer.","build_effort":"flash-only","stealth":"overt","form_factor":"board","summary":"An ESP32-S3 dev board pairing an NXP PN532-family NFC reader (the product title calls it 'PN5321', the repo's own spec table calls it 'PN532' - NXP's own product pages confirm PN5321A3HN and PN532 are literally the same 80C51-core silicon family, just different ordering codes, so this is not really a contradiction) with 8 addressable RGB LEDs, a 3W I2S speaker and a microSD slot. It's sold and documented as an interactive-art/access-control project platform, not a pentest tool.","honest_take":"This is explicitly not marketed or documented as a security tool - the maker's own listed use cases are an interactive museum guide, an educational coding kit, and a sound-art installation. Whatever MIFARE read/write capability it has comes entirely from the PN532-family chip and whatever open-source PN532 library you bring yourself; the vendor's repo documents no key-cracking, nested-attack, or emulation-limit discussion at all. If you want that, you're writing it on top of a bare PN532 reader library, the same starting point as a $10 breakout board (and NXP has marked the whole PN532/PN5321 family 'not recommended for new designs' in favour of the PN7160, for what that's worth on a 2026 purchase). The RGB LEDs, speaker and SD slot - not the NFC chip - are the actual reason for the $46 price.","aliases":[],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"claimed","hf_1356_emulate":"claimed","mifare_desfire":"partial","mifare_classic_attacks":"no","felica":"claimed","iso15693":"no","nfc_type4_ndef":"claimed","emv_read":"no","nfc_relay":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","scriptable":"yes","standalone_untethered":"partial","web_ui":"no","sd_logging":"yes"},"legal":{"risk_level":"low","notes":"A general-purpose NFC reader/writer dev board is legal to own essentially everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":null,"app_store":"n/a","abandoned_risk":"medium"}},{"id":"nfckill","hardware_id":"nfckill","name":"NFC Kill (v3)","firmware":"Stock (closed)","firmware_kind":"stock","vendor":"NFCKill","category":"rfid-nfc","subcategory":"rfid-fuzzing-destruction","status":"out-of-stock","price_usd":299.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Trivial to operate; knowing when it is appropriate is the hard part.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"A handheld device that couples roughly 1600 V pulses into an RFID tag or reader coil by induction, either to destroy tags permanently or to fuzz access-control readers by hitting them with electrical stress and watching how they fail. Covers LF 125-134 kHz and HF 13.56 MHz at 0-6 cm; UHF needs the separate UHFKill.","honest_take":"Two very different uses get marketed as one. As a tag-killer it works and is irreversible - that is destruction of property if the badge is not yours. As a 'fuzzer' it is crude: you are inducing electrical faults and observing whether a reader fails open, reboots or corrupts, which is a legitimate but narrow test, not protocol fuzzing. At USD 299 it is expensive for what it is, it has been persistently out of stock, and it does nothing at all to read, clone or analyse cards.","released":"2018","aliases":["NFCKill","RFID killer"],"capabilities":{"lf_125khz_read":"no","hf_1356_read":"no","detect_skimmer":"no","hardware_destruct":"yes"},"legal":{"risk_level":"high","notes":"Permanently disabling RFID tags that are not yours is criminal damage, and disabling tags in identity documents can be an offence in itself."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"n/a","app_store":"No","abandoned_risk":"medium"}},{"id":"nibble-screen-connect","hardware_id":"nibble-screen-connect","name":"Nibble Screen Connect","firmware":"Meshtastic","firmware_kind":"community","vendor":"Retia (Retia LLC)","category":"subghz","subcategory":"lora-mesh-node","status":"available","price_usd":50.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Meshtastic setup is app-guided; Meshcore support is explicitly labeled 'preliminary' by the vendor, so expect rougher edges on that firmware path.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A more expandable ESP32-S3 + Semtech SX1262 LoRa mesh node than the Nibble Zero, adding a 0.92-inch SSD1306 OLED display for on-device message viewing, two buttons, an LED, and a BME280 environmental sensor, sized to fit inside a PVC pipe for outdoor or semi-permanent mesh relay deployment.","honest_take":"The core hardware story is the same as the Nibble Zero: ESP32-S3 + SX1262 is a commodity Meshtastic combination available on many boards for less, and this design descends from the same fully open-source Nibble project (originally built around an RFM95 radio at 38C3, before this commercial variant moved to SX1262). What's genuinely different here is the OLED screen, letting you read mesh messages without a phone, and the PVC-pipe-friendly form factor for a semi-permanent outdoor relay node. If you want a 'read messages on the device itself' Meshtastic node rather than a phone-paired one, this is a reasonable niche pick - but check Meshcore support status first, since the vendor calls it only 'preliminary,' meaning that firmware path is less mature than Meshtastic.","aliases":["Nibble Connect"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"no","subghz_rolling_code":"no","subghz_external_antenna":"yes","gps":"no","ble_scan":"yes","wifi_scan_24":"partial","standalone_untethered":"yes","scriptable":"yes","txt_viewer":"yes","sd_logging":"no","app_store":"no","web_ui":"addon","mesh_lora":"yes"},"legal":{"risk_level":"low","notes":"Standard license-exempt LoRa/Meshtastic operation in the 868/915 MHz ISM bands; stay within regional power and duty-cycle limits (ETSI EN 300 220 / FCC Part 15)."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"nibble-zero","hardware_id":"nibble-zero","name":"Nibble Zero","firmware":"Custom","firmware_kind":"community","vendor":"Retia (Retia LLC)","category":"subghz","subcategory":"lora-mesh-node","status":"available","price_usd":75.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Meshtastic/Meshcore setup is largely app-guided; flashing firmware via the browser-based Nugget.dev tool or directly from a Flipper Zero needs no development environment.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"An open-hardware ESP32-S3 (Waveshare ESP32-S3 Zero) + Semtech SX1262 (Seeed WIO-SX1262 module) LoRa mesh node running Meshtastic, Meshcore or Reticulum firmware, with a BMP280 environmental sensor and a Flipper-Zero-compatible pinout that lets it mount directly onto a Flipper Zero, using the Flipper as a battery and keyboard.","honest_take":"This is not a Flipper Zero add-on in the GPIO-shield sense (like Electronic Cats' board) - it is an independent, fully open-source LoRa mesh node (design credited to Kody Kinzie, Zac Beran and Felix Orozco, released as open hardware at HOPE 2025) that happens to be pin-compatible with a Flipper Zero and can use it as a battery/keyboard when mounted. The underlying ESP32-S3 + SX1262 combination is a commodity Meshtastic pairing used by many boards; the $75 kit price buys Retia's case, BMP280 sensor, the dedicated 3.3V regulator fix, and convenience - not anything electrically unique, and since the full design is open-source on GitHub you can build the bare board yourself for materially less if you don't need the finished kit. If you don't specifically want the Flipper integration, a bare Heltec or LilyGo LoRa32 board running the same open Meshtastic firmware is cheaper still.","released":"2025","aliases":[],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"no","subghz_rolling_code":"no","subghz_external_antenna":"yes","gps":"no","ble_scan":"yes","wifi_scan_24":"partial","standalone_untethered":"yes","scriptable":"yes","app_store":"no","web_ui":"addon","sd_logging":"no","ibutton_1wire":"no","mesh_lora":"yes"},"legal":{"risk_level":"low","notes":"Standard license-exempt LoRa/Meshtastic operation in the 868/915 MHz ISM bands; stay within your region's power and duty-cycle limits (ETSI EN 300 220 / FCC Part 15)."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"nm-rf-hat","hardware_id":"nm-rf-hat","name":"NM-RF-HAT (NerdMiner RF Hat)","firmware":"Bruce","firmware_kind":"community","vendor":"NMTech / NMMiner","category":"accessory","subcategory":"rf-expansion-board","status":"available","price_usd":18.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"No soldering: the hat plugs onto the CYD board and you flash Bruce from a browser. The hardest part is picking the right ESP32-2432S028 revision, since that board ships with several different touch controllers.","build_effort":"assembly","stealth":"overt","form_factor":"hat-shield","summary":"A multi-band RF expansion board that plugs onto the ESP32-2432S028 'Cheap Yellow Display', turning a $12 display board into a handheld RF tool. It carries a CC1101 sub-GHz transceiver, an nRF24L01 2.4GHz transceiver, a PN532 NFC front end, a 433MHz ASK receiver, IR transmit and receive, a TF card slot and battery management. It is intended to run Bruce firmware.","honest_take":"First, answer the name directly: despite 'NerdMiner' in the branding, this IS a security tool, not a Bitcoin miner. The confusion is real and understandable - it is made by NMTech, the company behind the NerdMiner v2 solo-mining device, and marketplace listings routinely bundle the two in one title. The hat itself contains no miner and no processor at all; it is a passive carrier for radios that the host ESP32 drives. Second, the value case is strong: for around $30 all-in with no soldering you get most of what the ESP32-DIV asks you to build two custom PCBs for. What you give up is a maintained hardware design - it is an anonymous AliExpress board with no published schematic - and you inherit every limitation of the underlying radios: 2.4GHz only for Wi-Fi and BLE, fixed-code sub-GHz replay only, and PN532-class NFC that cannot recover MIFARE Classic keys.","released":"2025","aliases":["NM-RF-HAT","NM RF Hat","NerdMiner RF Hat","Bruce CYD RF hat","Multi-Band RF Companion Hat"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_external_antenna":"unknown","nrf24_scan":"yes","mousejack":"partial","nrf24_jam":"partial","hf_1356_read":"yes","hf_1356_emulate":"partial","mifare_classic_attacks":"partial","lf_125khz_read":"no","ir_tx":"yes","ir_rx":"yes","ir_universal_remote":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"partial","ble_scan":"yes","ble_spam_apple":"yes","sd_logging":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Owning the board is legal."},"ecosystem":{"community":"very-active","docs_quality":"sparse","last_release":"2026-08","app_store":"No, but Bruce is a large, actively developed firmware with a wide feature set","abandoned_risk":"medium"}},{"id":"nrf52840-dongle-nrfsniffer","hardware_id":"nrf52840-dongle","name":"Nordic nRF52840 Dongle","firmware":"nRF Sniffer for Bluetooth LE","firmware_kind":"stock","vendor":"Nordic Semiconductor","category":"bluetooth","subcategory":"ble-sniffer","status":"available","price_usd":11.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flashing is a few clicks in nRF Connect and the output lands in Wireshark - but reading BLE in Wireshark is where the actual difficulty is.","build_effort":"flash-only","stealth":"covert","form_factor":"usb-stick","summary":"A $10 USB dongle carrying Nordic's nRF52840 SoC that, flashed with Nordic's free nRF Sniffer firmware, becomes a working BLE packet capture device feeding Wireshark. It is the cheapest legitimate way to start looking at Bluetooth Low Energy traffic.","honest_take":"First, a correction that trips people up constantly: this dongle does NOT run Sniffle. Sniffle is NCC Group's sniffer and it targets TI CC1352/CC26x2 hardware only - the nRF52840 is not in its supported list and is not mentioned in the project at all. What the Nordic dongle runs is Nordic's own nRF Sniffer, which is a decent free tool but weaker: it watches one advertising channel at a time, so it frequently misses the CONNECT_IND that starts a session and therefore fails to follow the connection you actually care about. If BLE sniffing is the point of your purchase, spend $20 on a Sonoff CC2652P dongle and run Sniffle instead. Buy this one because it is a superb $10 nRF52840 development board that happens to sniff.","released":"2018","aliases":["nRF52840 Dongle","PCA10059","nRF Sniffer dongle"],"capabilities":{"ble_sniff":"partial","ble_scan":"yes","ble_advertise":"addon","bt_classic":"no","zigbee":"addon","ble_tracker_detect":"addon","packet_capture":"yes","scriptable":"yes","usb_hid_inject":"addon","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"Owning and using it is legal everywhere."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2025","app_store":"No - but a very large third-party firmware ecosystem exists for the nRF52840","abandoned_risk":"low"}},{"id":"flipper-nrf24-module","hardware_id":"flipper-nrf24-module","name":"nRF24L01+ module for Flipper Zero (mousejack / 2.4 GHz)","firmware_kind":"n/a","vendor":"Generic - Nordic Semiconductor silicon on modules from countless Chinese board houses; also sold pre-wired by Flipper accessory shops","category":"accessory","subcategory":"flipper-24ghz-module","status":"available","price_usd":4.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Buying the module is trivial; wiring seven SPI lines to the right Flipper GPIO pins, and understanding that most of the famous attacks no longer land, is the real work.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"A Nordic nRF24L01+ transceiver on a small module, wired to the Flipper's GPIO header. It gives the Flipper access to the 2.4 GHz band outside Wi-Fi and Bluetooth: scanning for proprietary GFSK links, sniffing and replaying wireless keyboard and mouse traffic, and the MouseJack keystroke-injection attack. It is by far the cheapest capability upgrade a Flipper can get.","honest_take":"Two blunt points. First, MouseJack is a 2016 vulnerability. Bastille disclosed it in February 2016, the vendors shipped receiver firmware updates that year, mousejack.com is now a dead link, and the canonical Flipper app (mothball187's) has had no code push since August 2022 - so treat 'it can hijack wireless keyboards' as 'it might, against a ten-year-old unpatched dongle you find in a drawer'. Second, the 'nRF24 jammer' apps that make this module popular are not jammers in any meaningful sense: the chip is a narrowband GFSK transceiver with 1 MHz channels and 0 dBm output, so what those apps do is hop a single tone around, which can disrupt other nRF24-family links on the same channels and will do essentially nothing to Wi-Fi or to a connected Bluetooth link. Nordic themselves list the whole nRF24 series as not recommended for new designs, which tells you where this technology sits.","released":"2008","aliases":["NRF24","nRF24L01+","Flipper mousejack module","NRF24 PA LNA"],"capabilities":{"nrf24_scan":"yes","mousejack":"partial","nrf24_jam":"partial","ble_scan":"no","wifi_scan_24":"no","zigbee":"no"},"legal":{"risk_level":"medium","notes":"A $3 transceiver module is not restricted anywhere we found, and receiving is generally lawful."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"2024-11","app_store":"Yes - nrf24 apps are in the Flipper community catalogs","abandoned_risk":"high"}},{"id":"nrfbox-v1","hardware_id":"nrfbox-v1","name":"nRFBox v1","firmware":"nRFBox v1 (Arduino sketches)","firmware_kind":"diy","vendor":"CiferTech (open-source project, no official vendor)","category":"bluetooth","subcategory":"24ghz-scanner","status":"diy-only","price_usd":25.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Through-hole only, buildable on perfboard from a wiring diagram, flashed over USB from the Arduino IDE. Genuinely a first-project build - the caveat is that the design is four years old and the repo has moved on.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"The original nRFBox: an Arduino Nano with a couple of nRF24L01+ modules and a small OLED, doing three things - scanning the 2.4GHz band for channel activity, displaying that as an analyser view, and flooding selected channels. It is the ancestor of the current ESP32 versions and is now a historical design.","honest_take":"Don't build this one. The scanner and analyser are a genuinely nice way to see the 2.4GHz band on a $25 budget, but the project's own code and documentation have moved to ESP32 hardware, so you would be following the least-maintained path in the repo to get the fewest features. Build v3, or if you only want the spectrum view, note that the same nRF24 energy scan is a well-known 40-line Arduino sketch that predates this project - there is no secret sauce in the hardware.","released":"2022","aliases":["nRFBOX v1","NRFBox Arduino"],"capabilities":{"nrf24_scan":"yes","nrf24_jam":"partial","ble_scan":"no","wifi_scan_24":"no"},"legal":{"risk_level":"medium","notes":"The scanner and analyser are passive and unproblematic to run."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"n/a - predates the project's tagged releases","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"nrfbox-v3","hardware_id":"nrfbox-v3","name":"nRFBox v3","firmware":"nRFBox v2.7.2","firmware_kind":"diy","vendor":"CiferTech (open-source project, no official vendor)","category":"multitool","subcategory":"24ghz-multitool","status":"diy-only","price_usd":50.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Custom PCB, three radio modules and an OLED; you must be comfortable soldering, flashing an ESP32, and troubleshooting brownouts when all three radios transmit together.","build_effort":"soldering","stealth":"overt","form_factor":"handheld","summary":"The current nRFBox: an ESP32-WROOM-32U with three nRF24L01+ modules and an OLED, combining passive 2.4GHz spectrum scanning and analysis with active BLE and multi-protocol disruption, plus Wi-Fi and BLE scanning and a deauther that use the ESP32's own radio. It is the more useful sibling of RF-Clown - same jamming ability, but with the eyes to see what you are doing.","honest_take":"The honest split here is that half this device is a legitimate, genuinely useful 2.4GHz spectrum tool and the other half is a jammer that is illegal to switch on almost everywhere. Understand which mode you are in. The 'Proto Kill' name oversells it: eight protocols in a menu is still three nRF24s putting narrowband energy on a handful of 1MHz channels, and it does not speak Zigbee or Wi-Fi any more than a bullhorn speaks French. 'Sour Apple' is BLE advertisement spam that makes iPhone popups appear - an annoyance, not a compromise. And the deauther inherits the usual limit: 2.4GHz only, and useless against any network with 802.11w/PMF enabled, which WPA3 mandates.","released":"2025","aliases":["nRFBOX","NRF Box","nRFBox V3"],"capabilities":{"nrf24_scan":"yes","nrf24_jam":"partial","ble_jam":"partial","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"partial","wifi_deauth_5":"no","zigbee":"no","standalone_untethered":"yes","sd_logging":"partial"},"legal":{"risk_level":"high","notes":"The scanner and analyser modes are passive and fine."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025-06","app_store":"No","abandoned_risk":"low"}},{"id":"nyanbox-stock","hardware_id":"nyanbox","name":"nyanBOX","firmware":"nyanBOX (Nyan Devices)","firmware_kind":"stock","vendor":"Nyan Devices","category":"detection-defense","subcategory":"24ghz-scanner","status":"available","price_usd":220.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Menu-driven on a 128x64 OLED with five buttons; no commands, no config files, no SD card to manage.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"A 2.4 GHz-only scanner and spammer: an ESP32-WROOM-32U doing all the Wi-Fi and BLE work, plus three nRF24L01+ radios that do coarse energy sweeps of the band and can emit constant-carrier noise. The long feature list is mostly BLE and Wi-Fi signature matching wrapped in a friendly menu with an XP and levelling system. It has no sub-GHz radio, no NFC, no RFID, no infrared and no storage.","honest_take":"Almost every headline detector is a few lines of string comparison on a BLE advertisement, and the published source proves it: the Axon detector keeps only devices whose MAC begins 00:25:df and throws away everything else; the skimmer detector matches the literal names 'HC-03', 'HC-05' and 'HC-06'; the Pineapple detector just looks for ':13:37:' in a BSSID. The three nRF24s cannot demodulate Wi-Fi or BLE at all - they give a one-bit above-or-below -64 dBm reading per 1 MHz channel, so the 'spectrum analyzer' is a coarse activity sweep, and the hidden SigKill jammer is three unmodulated carriers, not broadband jamming. Worst of all the current firmware is closed: the repo now ships binaries plus a tarball of old source, so you cannot audit the newer detectors or maintain the thing yourself if the two-person team walks away.","released":"2025","aliases":["nyan BOX","Nyan Box","nyanBOX Complete Kit"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"no","wifi_beacon_spam":"yes","wifi_captive_portal":"yes","wifi_evil_twin":"partial","wifi_handshake_capture":"partial","wifi_pmkid":"no","wifi_wardriving":"no","wifi_ap_mode":"yes","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","ble_hid":"no","bt_classic":"no","ble_sniff":"no","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","findmy_track":"partial","nrf24_scan":"yes","nrf24_jam":"partial","mousejack":"no","ble_jam":"partial","zigbee":"no","sdr_rx":"no","subghz_rx":"no","ir_tx":"no","hf_1356_read":"no","lf_125khz_read":"no","usb_hid_inject":"no","sd_logging":"no","gps":"no","scriptable":"no","app_store":"no","web_ui":"no","standalone_untethered":"yes","detect_flipper":"yes","detect_airtag":"partial","detect_tile":"yes","detect_skimmer":"partial","detect_pineapple":"partial","detect_pwnagotchi":"yes","detect_drone":"yes","detect_meshtastic":"yes","detect_surveillance_cam":"partial","detect_generic_ble":"yes","detect_generic_wifi":"yes","detect_bodycam":"yes","detect_alpr":"partial","detect_smartglasses":"partial","detect_meshcore":"partial","detect_deauth":"yes","pwnagotchi_spam":"yes","drone_spoof":"yes","rpg_leveling":"yes","device_lock":"partial"},"legal":{"risk_level":"high","notes":"Owning it is legal in most places."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"No","abandoned_risk":"medium"}},{"id":"omg-adapter","hardware_id":"omg-adapter","name":"O.MG Adapter","firmware":"O.MG Firmware v3.0 (stock)","firmware_kind":"stock","vendor":"Mischief Gadgets (sold via Hak5)","category":"usb-hid","subcategory":"malicious-adapter-implant","status":"available","price_usd":200.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same workflow as the rest of the O.MG line.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"The O.MG implant in a small USB adapter body, so it can be added to a cable the target already owns rather than replacing it. Sold Elite-only, meaning it includes the keylogger, covert exfiltration channel, networked C2 and the full 200-slot payload storage.","honest_take":"Operationally this is the most flexible shape in the family: you are not asking anyone to accept a new cable, you are adding a small adapter to one they already trust, and it works with whatever cable is already there. That is why it is Elite-only and why it costs the same as the most expensive cables. Same caveats as the rest of the line though - ESP8266, 2.4 GHz Wi-Fi only, closed firmware you cannot audit, and storage measured in kilobytes. And the adapter is the variant most likely to be noticed, because an unexplained dongle between a cable and a port is more visually anomalous than a cable that simply looks like a cable.","released":"2022","aliases":["OMG Adapter"],"capabilities":{"usb_hid_inject":"yes","usb_keylogger":"yes","usb_exfil":"yes","usb_payload_lang":"partial","hid_remote_trigger":"yes","wifi_ap_mode":"yes","cloud_c2":"partial","web_ui":"yes","scriptable":"yes","standalone_untethered":"yes","ble_scan":"no"},"legal":{"risk_level":"high","notes":"Same as the O."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"Yes - shared O.MG payload repository","abandoned_risk":"low"}},{"id":"omg-cable","hardware_id":"omg-cable","name":"O.MG Cable","firmware":"O.MG Firmware v3.0 (stock)","firmware_kind":"stock","vendor":"Mischief Gadgets (sold via Hak5)","category":"usb-hid","subcategory":"malicious-cable-implant","status":"available","price_usd":180.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Deployment is trivial; writing payloads that survive a real target, and understanding the operational risk of a Wi-Fi beacon in a cable, is not.","build_effort":"assembled","stealth":"covert","form_factor":"cable","summary":"A charging cable with an implant built into the connector housing. It works as a real cable, but it also runs a web server on its own Wi-Fi, stores DuckyScript payloads, injects keystrokes into whatever it is plugged into, and on Elite models logs keystrokes from a keyboard plugged through it. It is visually indistinguishable from a normal cable.","honest_take":"The implant's brain is an ESP8266 - the shipped firmware binary literally contains the string 'Firmware ONLY supports ESP8266!!!'. Not an ESP32 and not a custom ASIC; a CT scan found two dies in one package, which is custom packaging, not custom silicon. There is no separate USB chip either: the ESP8266 has no USB peripheral, so USB is bit-banged in software using the open-source cnlohr/espusb stack. That sets a hard ceiling - 2.4 GHz Wi-Fi only, no Bluetooth, low-speed USB, and storage measured in kilobytes. What $150-220 buys is the engineering that fits all that inside a connector housing that still looks and works like a cable, which genuinely nobody else does as well. Three things to weigh. The tier matters far more than the connector: Basic is 8 payload slots, ~4,000 keystrokes and 120 keys/sec with no keylogger; Elite is 50-300 slots, ~1.5 million keystrokes, 890 keys/sec, the keylogger and the C2. The 'geo-fencing' feature is not GPS - it is Wi-Fi SSID presence detection, so it fences on 'is this network in range', not on location. And the firmware is closed with a EULA that forbids reverse engineering, so you cannot audit the cable you are about to plug into a client's machine.","released":"2019","aliases":["OMG Cable","O.MG","Mischief Gadgets cable","Demonseed"],"capabilities":{"usb_hid_inject":"yes","usb_keylogger":"partial","usb_exfil":"partial","usb_payload_lang":"partial","hid_remote_trigger":"yes","wifi_ap_mode":"yes","gps":"no","cloud_c2":"partial","web_ui":"yes","scriptable":"yes","standalone_untethered":"yes","ble_scan":"no","sd_logging":"no"},"legal":{"risk_level":"high","notes":"This is the most legally exposed device in the whole Hak5 catalogue, because deception is the entire product."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"Yes - the hak5/omg-payloads repository, 1,090 stars, last pushed 2025-11","abandoned_risk":"low"}},{"id":"omg-cable-programmer-usb-ac","hardware_id":"omg-cable-programmer-usb-ac","name":"O.MG Cable Programmer (USB A+C)","firmware_kind":"n/a","vendor":"O.MG (Hak5)","category":"accessory","subcategory":"programmer-dongle","status":"available","price_usd":25.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug the O.MG device into the programmer, the programmer into a host, and use the web interface or app - no soldering or firmware-flashing expertise required for routine use.","build_effort":"assembled","stealth":"overt","form_factor":"usb-stick","summary":"The dedicated setup/recovery dongle for Hak5's O.MG line (Cable, Plug, Adapter, UnBlocker): it puts a connected O.MG device into DFU mode so an operator can configure Wi-Fi settings, upload DuckyScript-compatible payloads and trigger settings, perform firmware upgrades or recovery, pull forensic dumps/backups, or batch-flash multiple units - none of which is possible over the O.MG device's own limited USB interface once it's deployed.","honest_take":"This is infrastructure, not an attack tool - you cannot deploy this against anything, only use it to prepare something else in this same product family for deployment. It exists because the O.MG Cable/Plug/Adapter/UnBlocker are deliberately built to look and behave like innocuous everyday accessories in the field, which means they don't expose an easy configuration interface once assembled; the programmer is what restores that access. If you already own the O.MG Cable Programmer's older single-connector predecessor, this buys you USB-C target support and not much else.","released":"2023","aliases":["O.MG Programmer"],"capabilities":{"usb_hid_inject":"no","usb_mass_storage":"no","usb_exfil":"no","usb_keylogger":"no","hid_remote_trigger":"no","usb_payload_lang":"claimed","scriptable":"no","standalone_untethered":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"The programmer itself has no offensive capability - it configures other hardware."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"n/a - hardware accessory","app_store":"No","abandoned_risk":"low"}},{"id":"omg-demonseed-edu","hardware_id":"omg-demonseed-edu","name":"O.MG DemonSeed EDU","firmware":"DemonSeed","firmware_kind":"diy","vendor":"Mischief Gadgets","category":"usb-hid","subcategory":"diy-education-kit","status":"discontinued","price_usd":49.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"You solder it yourself and flash Arduino sketches. The kit deliberately contains two implants so you can afford to destroy one learning.","build_effort":"soldering","stealth":"covert","form_factor":"cable","summary":"THERE IS NO 'O.MG DevKit'. The educational/development product Mischief Gadgets actually sold was the O.MG DemonSeed EDU: a $49.99 solder-it-yourself kit containing two ATtiny85-based cable implants, a programmer and jig supplies, taught through a video series. It was discontinued around 2023.","honest_take":"If your source list says 'O.MG DevKit', this is almost certainly what it means - and the substitution matters, because the DemonSeed is not a cut-down O.MG Cable, it is a completely different and far simpler device. Mike Grover said so explicitly: it is not an O.MG Cable and is missing nearly every feature. Critically it has NO WIRELESS AT ALL - it is an ATtiny85 that types a hardcoded payload, so no Wi-Fi, no web UI, no C2, no remote triggering, no keylogging, no payload slots. It was a teaching product about how a cable implant is physically built, and a good one. For a current comparison site the right move is to drop this row entirely and, if you need an O.MG accessory entry, use the $25 O.MG Programmer, which is the item people actually need since every O.MG device ships deactivated and cannot be set up without one.","released":"2019","aliases":["DemonSeed","DemonSeed EDU","O.MG DevKit (misnomer)"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"partial","wifi_ap_mode":"no","cloud_c2":"no","usb_keylogger":"no","hid_remote_trigger":"no"},"legal":{"risk_level":"medium","notes":"A cable implant that types a fixed payload, so the same unauthorised-access considerations apply as for any keystroke injector - but with no wireless, no keylogging and no remote control, its practical reach is far smaller than a real O."},"ecosystem":{"community":"dead","docs_quality":"none","last_release":null,"app_store":"No - the original repository was deleted and only a community mirror survives","abandoned_risk":"already-abandoned"}},{"id":"omg-malicious-cable-detector","hardware_id":"omg-malicious-cable-detector","name":"O.MG Malicious Cable Detector","vendor":"O.MG / Hak5","category":"detection-defense","subcategory":"malicious-usb-cable-detector","status":"out-of-stock","price_usd":40.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug the cable into the detector, then the detector into a USB port; LED indicates the result. No configuration required for basic use.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A small bus-powered inline dongle that samples a connected USB-A cable's power draw 200,000 times per second, using side-channel power analysis to flag cables with hidden active electronics (like O.MG-style implant cables) that stay electrically invisible on the data lines until triggered. It doubles as a USB data blocker (\"USB condom\") for safe charging.","honest_take":"O.MG's own product description admits the limit plainly: it 'is not a guarantee against bespoke nation-state-grade implants, but it covers the commercially available malicious cables' — this is a signature/power-fingerprint check against known classes of implant, not a cryptographic or exhaustive guarantee. There's also a timing gap inherent to the method: because implant cables like O.MG's own products are designed to stay dormant until remotely triggered or a specific condition is met, a clean reading only means 'not actively transmitting data during this test,' not 'verified safe.' That's the single most common misread of what a green light here means. As a data blocker alone it's solid and simple — charge-only USB condoms are a mature, low-risk category — but buying it purely for the detector half and expecting certainty against a sophisticated implant overstates what side-channel power sampling can promise.","released":"2022","aliases":["O.MG Cable Detector"],"capabilities":{"usb_mass_storage":"no","usb_hid_inject":"no","usb_keylogger":"no","usb_exfil":"no","scriptable":"claimed","standalone_untethered":"no","sd_logging":"no","wifi_ap_mode":"no","ble_scan":"no","packet_capture":"no","side_channel_power":"yes","usb_cable_detect":"yes","usb_data_block":"yes"},"legal":{"risk_level":"low","notes":"Purely defensive hardware; legal to own and use everywhere pentest hardware generally is."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"omg-plug","hardware_id":"omg-plug","name":"O.MG Plug","firmware":"O.MG Firmware v3.0 (stock)","firmware_kind":"stock","vendor":"Mischief Gadgets (sold via Hak5)","category":"usb-hid","subcategory":"malicious-charger-implant","status":"available","price_usd":115.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same payload workflow as the O.MG Cable.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"The O.MG implant in a USB wall-charger body rather than a cable. It behaves like an ordinary charger while running the same web-managed payload engine, Wi-Fi and C2 as the O.MG Cable. Elite adds up to 200 payload slots, port stealthing, self-destruct and the covert exfiltration channel.","honest_take":"Same ESP8266 brain and the same closed firmware as the cable, in a keychain-sized shell, and at $85-115 it is the cheapest honest way to evaluate the O.MG ecosystem before spending $180-220 on a cable. The tradeoff is the threat model: a plug is something people connect their own devices to, whereas a cable is something that ends up in a laptop. One specific trap worth knowing: the Plug's Basic tier is weaker than the Cable's Basic - Plug Basic has neither self-destruct nor port stealthing, while Cable Basic at least has self-destruct. If any of the marquee features are the point, you need Elite.","released":"2021","aliases":["OMG Plug","O.MG Wall Plug"],"capabilities":{"usb_hid_inject":"yes","usb_exfil":"partial","usb_payload_lang":"partial","hid_remote_trigger":"yes","wifi_ap_mode":"yes","cloud_c2":"partial","web_ui":"yes","scriptable":"yes","standalone_untethered":"yes","usb_keylogger":"no","ble_scan":"no"},"legal":{"risk_level":"high","notes":"Same as the O."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"Yes - shared O.MG payload repository","abandoned_risk":"low"}},{"id":"omg-programmer-usb-ac","hardware_id":"omg-programmer-usb-ac","name":"O.MG Programmer USB A+C","firmware":"Stock (MG.LOL / Hak5)","firmware_kind":"stock","vendor":"MG.LOL, sold via Hak5","category":"accessory","subcategory":"implant-programmer-recovery-tool","status":"available","price_usd":25.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-flash via the O.MG GUI/companion tooling - the programmer itself requires no special skill; the skill requirement lives in the O.MG cable/plug/adapter payloads you write with it.","build_effort":"assembled","stealth":"overt","form_factor":"usb-stick","summary":"The required companion programmer for the entire O.MG implant line (Cable, Plug, Adapter, UnBlocker): it handles initial provisioning, firmware updates, recovery after a self-destruct event, forensic dumps/backups, and batch firmware installs for bulk deployments. One unit covers every device in the family via its combined USB-A and USB-C ports.","honest_take":"This is not an attack tool itself - it is the maintenance dongle every O.MG device eventually needs, and Hak5/MG.LOL made it effectively mandatory rather than optional: several O.MG devices ship without a way to be reprovisioned or recovered except through this programmer. If you own or plan to own more than one O.MG product, budget for this alongside them; it is a sunk cost of the ecosystem, not an add-on capability, and it has no debug-probe or bus-analysis function of its own - it only talks to O.MG silicon.","released":"2022","aliases":["O.MG Cable Programmer USB A+C"],"capabilities":{"usb_exfil":"no","jtag_swd":"no","spi_flash_dump":"no","i2c":"no","uart":"no","logic_analyzer":"no","glitching":"no","scriptable":"unknown","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"The programmer itself has no offensive capability - it flashes and images other devices."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"omg-unblocker","hardware_id":"omg-unblocker","name":"O.MG UnBlocker","firmware":"O.MG Firmware v3.0 (stock)","firmware_kind":"stock","vendor":"Mischief Gadgets (sold via Hak5)","category":"usb-hid","subcategory":"malicious-adapter-implant","status":"available","price_usd":150.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same payload workflow as the rest of the line; the sophistication is in the social engineering, not the operation.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"An O.MG implant disguised as a USB data blocker - the small dongle security-conscious people carry specifically to make public charging safe. It looks like a defensive product and is sold in the same bright colours real ones use, but it is a full Elite-tier implant.","honest_take":"This is the most conceptually vicious device in the entire catalogue, and that is the point of it: it weaponises the exact precaution a careful person takes. Someone who carries a USB condom is by definition someone thinking about USB security, and this turns that habit into the attack. Technically it is the same ESP8266 Elite implant as the Adapter, at $50 less, and it is genuinely useful as an awareness tool - it is the fastest way to make an audience understand that a trusted-looking accessory is not a trust anchor. Note the irony that Mischief Gadgets also sells the $40 Malicious Cable Detector, so the same vendor sells you both the problem and a partial answer. Practically, everything true of the O.MG Adapter is true here: 2.4 GHz only, closed firmware, kilobyte-scale storage.","released":"2023","aliases":["OMG UnBlocker","O.MG Data Blocker"],"capabilities":{"usb_hid_inject":"yes","usb_keylogger":"partial","usb_exfil":"yes","usb_payload_lang":"partial","hid_remote_trigger":"yes","wifi_ap_mode":"yes","cloud_c2":"partial","web_ui":"yes","scriptable":"yes","standalone_untethered":"yes","ble_scan":"no"},"legal":{"risk_level":"high","notes":"The highest-risk item here."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"Yes - shared O.MG payload repository","abandoned_risk":"low"}},{"id":"odiin-nfc-emulator","hardware_id":"odiin-nfc-emulator","name":"Odiin","firmware":"Odiin (official, prototype)","firmware_kind":"diy","vendor":"cmd; wtf? (Chris Marc Dailey)","category":"rfid-nfc","subcategory":"tag-emulator","status":"out-of-stock","price_usd":169.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Drag-and-drop tag dump files onto it like a USB drive and tap it to a reader - simple in concept, but the firmware is an acknowledged unfinished prototype, so expect to troubleshoot.","build_effort":"assembled","stealth":"discreet","form_factor":"handheld","summary":"A small nRF52840-based handheld with a colour LCD that emulates NFC-A tags - NTAG213/215/216 well, MIFARE Ultralight C in rudimentary form - by loading dump files from an onboard drive exposed over USB-C, then presenting the selected tag to a reader like a real NFC-A card. Comparable in concept to a Flipper Zero's NFC-emulation slice, but purpose-built and open source, with hardware and firmware both public.","honest_take":"The maker's own description is the most honest one available: 'absolutely a prototype,' with acknowledged bugs and unfinished write handling. MIFARE Classic emulation and NDEF payload formatting are listed as planned, not shipped. As of this research the seller is not actively selling it - 'taking a break' - so this is currently a buy-if-you-can-find-one-secondhand-or-build-it-yourself device rather than something you can order today. If NFC tag emulation is the only thing you need, a Flipper Zero or Chameleon Ultra are both actively sold, actively maintained, and more capable out of the box; Odiin's appeal is being small, open, and hackable rather than being the most capable emulator available.","released":"2020","aliases":["Odiin NFC Tag Emulation Toolkit"],"capabilities":{"hf_1356_emulate":"partial","hf_1356_read":"no","hf_1356_write":"no","mifare_classic_attacks":"no","mifare_desfire":"no","iso15693":"no","felica":"no","nfc_type4_ndef":"partial","lf_125khz_read":"no","lf_125khz_emulate":"no","nfc_relay":"no","sd_logging":"partial","standalone_untethered":"yes","ble_scan":"no","scriptable":"no"},"legal":{"risk_level":"medium","notes":"Owning an NFC tag emulator is legal in most places."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"okhi","hardware_id":"okhi","name":"okhi (Open Keylogger Hardware Implant)","firmware":"Stock (therealdreg), v7+","firmware_kind":"diy","vendor":"therealdreg / rootkit.es (now via Elecrow)","category":"usb-hid","subcategory":"keylogger-implant","status":"available","price_usd":89.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"The implant itself ships assembled and pre-designed for concealment, but wiring it into a target keyboard/tower covertly (tapping cable pads or internal traces) demands real soldering and tradecraft even though the board needs no assembly.","build_effort":"assembled","stealth":"implant","form_factor":"board","summary":"A tiny (implant-sized) RP2040 + ESP32-C2 board designed to be concealed inside a keyboard, laptop, or tower case, intercepting USB (low-speed) or PS/2 keystrokes and serving them over its own Wi-Fi web dashboard in real time. It draws its power parasitically from the keyboard's own cable (~120 mA) rather than needing a battery, persists every keystroke to its own flash so nothing is lost across reboots, and supports OTA firmware updates over Wi-Fi from v7 onward so it never needs to be pulled once installed.","honest_take":"The parasitic-power design and OTA updates make this materially harder to detect and easier to maintain than a typical inline keylogger dongle - there's no separate device plugged into a USB port to notice, and updates don't require reopening the target. That is also exactly why it is a serious surveillance/wiretapping tool rather than a toy: unlike a bolt-on USB dongle, it is explicitly engineered to be permanently embedded and forgotten. Treat the 'proof of concept and educational tool' framing in the README as a legal disclaimer, not a technical limitation - the hardware works exactly as advertised for covert, persistent keystroke capture.","released":"2024","aliases":[],"capabilities":{"usb_keylogger":"yes","usb_hid_inject":"no","usb_mass_storage":"partial","usb_exfil":"no","web_ui":"yes","cloud_c2":"no","sd_logging":"no","standalone_untethered":"yes","app_store":"no"},"legal":{"risk_level":"high","notes":"Same wiretapping/interception exposure as any hardware keylogger (see USBKeylogger's legal note), heightened here because the product is explicitly engineered and marketed as a concealable 'implant' rather than a visible inline dongle - covert, persistent capture of another person's keystrokes without consent is a criminal offense in essentially every jurisdiction this database covers."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"retia-meshtastic-nibble","hardware_id":"retia-meshtastic-nibble","name":"Open Source Meshtastic Nibble","firmware":"Meshtastic (upstream)","firmware_kind":"community","vendor":"Retia (retia.io)","category":"subghz","subcategory":"mesh-comms-node","status":"out-of-stock","price_usd":10.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The unsoldered kit needs surface-mount-adjacent hand soldering (LoRa module, MCU module, LED); the Meshtastic side then needs comfort with mesh-network configuration (channels, PSK, node roles) which is not beginner territory even if the hardware is easy.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"An open-source LoRa mesh-networking node built around an RFM95 (Semtech SX1276) radio and either an RP2040 or ESP32-S3, designed to fit inside a 1-inch PVC pipe for cheap weatherproof field deployment. It ships pre-loaded with mainline Meshtastic firmware, and the board design has been merged upstream into the Meshtastic project itself rather than being a one-off fork.","honest_take":"This is not an offensive or defensive security tool - it's an encrypted off-grid mesh-comms node, useful to the same crowd that carries a Flipper because it solves 'no cell signal at a protest, a disaster site, or a remote con venue' rather than anything resembling a pentest primitive. It earns a place here because the comparison database already tracks general-purpose hacker-con hardware, and because Meshtastic mesh networks are exactly what some detection tooling elsewhere in this database (the MeshCore/Meshtastic detector keys) is built to spot - so a reader comparing detectors benefits from seeing what they're detecting. Buy the RP2040 version unless you specifically need BLE/Wi-Fi pairing with a phone: the ESP32-S3 variant burns meaningfully more power for that convenience. Every variant is currently sold out.","released":"2024","aliases":["Nibble","Retia Nibble"],"capabilities":{"sd_logging":"no","scriptable":"no","standalone_untethered":"partial","app_store":"no","ble_scan":"no","ble_advertise":"partial","wifi_ap_mode":"partial","wifi_scan_24":"no","gps":"no","gps_wardrive_log":"no","usb_mass_storage":"no","mesh_lora":"yes"},"legal":{"risk_level":"low","notes":"Operating a LoRa mesh node is generally legal worldwide on the applicable unlicensed ISM band (868 MHz in the EU, 915 MHz in the US) subject to the usual duty-cycle and power limits for that band."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09 (Retia's companion scriptkitty.sh flasher repo was updated 2026-09-05; the Nibble hardware repo shows recent 2026 activity)","app_store":"No - uses the standard Meshtastic app","abandoned_risk":"low"}},{"id":"takeit-open-source-usb-sniffer-usb20","hardware_id":"takeit-open-source-usb-sniffer-usb20","name":"Open Source Portable USB Sniffer USB2.0","firmware":"Custom","firmware_kind":"third-party-product","vendor":"takeit","category":"hardware-debug","subcategory":"usb-analyzer","status":"out-of-stock","price_usd":85.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"No polished companion app - you work from generic Wireshark/USB-standard knowledge and the board's CPLD test points. Listing text reads as machine-translated and is thin on real documentation.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A low-cost (~$85) bare PCB USB 1.1/2.0 bus sniffer sold by a Hong Kong-based Tindie seller ('takeit'), built around an unnamed CPLD/FPGA with four status LEDs, claiming stable capture above 48Mbps and Wireshark-compatible output. Framed as 'open source' but the listing links no schematic, firmware repository, or original design credit.","honest_take":"The description - 'open source,' CPLD-based, USB2.0/1.1 capture 'stable above 48Mbps,' sub-$100 price - matches the well-known genre of open-source CPLD/FPGA USB sniffers popularized by Alex Taradov's BSD-3-licensed design (Lattice MachXO2 FPGA + Cypress FX2LP MCU + Microchip USB3343 PHY, ~$50 BOM). Taradov's own project explicitly warns buyers off 'fake or sketchy' AliExpress/eBay clones of exactly this kind, and this listing has the same shape. But because the seller names no chips, links no repo, and credits no original author, I can't confirm this is that specific design versus a different derivative - or just marketing language borrowed from that scene. Given the seller is now inactive and there's zero public documentation to fall back on, this is a worse bet than either Taradov's own $50 DIY build or BugBlat's supported $99.99 unit.","released":"unknown","aliases":["Open Source USB Sniffer USB2.0 (takeit)"],"capabilities":{"usb_hid_inject":"no","usb_mass_storage":"no","usb_keylogger":"no","hid_remote_trigger":"no","jtag_swd":"no","uart":"no","i2c":"no","spi_flash_dump":"no","logic_analyzer":"no","ethernet_tap_passive":"no"},"legal":{"risk_level":"low","notes":"Passively capturing USB traffic on hardware you own/control is broadly legal."},"ecosystem":{"community":"dormant","docs_quality":"poor","last_release":"unknown","app_store":"No","abandoned_risk":"high"}},{"id":"opera-cake-hackrf","hardware_id":"opera-cake-hackrf","name":"Opera Cake for HackRF","firmware_kind":"n/a","vendor":"Great Scott Gadgets","category":"accessory","subcategory":"hackrf-antenna-switch","status":"available","price_usd":190.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Purely a plumbing accessory for an existing HackRF workflow - configuring frequency- or time-based automatic switching via the command-line hackrf_operacake tool assumes you already know your way around HackRF.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An open-source antenna-switching add-on for HackRF One covering 1MHz-4GHz, offering two banks of four RF ports (or one bank of eight in single-switch mode), controllable manually or automatically based on frequency or time via the hackrf_operacake command-line tool.","honest_take":"This adds zero RF capability of its own - HackRF's own tuning range, ADC, and bandwidth are completely unchanged. What it buys you is not having to physically unplug and replug antennas/filters when switching between bands or antenna types during automated sweeps, which matters for wideband scanning workflows but is irrelevant if you only ever use one antenna. It caps out at 4GHz even though HackRF One tunes to 6GHz, so it won't help you switch antennas for HackRF's top octave.","released":"2018","aliases":[],"capabilities":{"sdr_rx":"no","sdr_tx":"no","sdr_bandwidth":"no","scriptable":"yes","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no","wifi_monitor_mode":"no"},"legal":{"risk_level":"low","notes":"A passive antenna switch carries no meaningful independent legal risk beyond whatever applies to the HackRF it's attached to."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"opticspy","hardware_id":"opticspy","name":"OpticSpy","firmware_kind":"n/a","vendor":"Grand Idea Studio","category":"hardware-debug","subcategory":"optical-covert-channel","status":"available","price_usd":49.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Outputs a raw NRZ digital bitstream with no onboard decoding. You manually tune two gain potentiometers and then capture/decode the signal yourself (logic analyzer, sigrok, custom script) - it is not a point-and-click IR/optical decoder.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"An open-source (CC-BY-3.0) analog photodiode receiver module from Grand Idea Studio (Joe Grand), sold continuously on Crowd Supply since its February 2018 campaign. A Vishay BPW21R silicon photodiode feeds two Maxim op-amp gain stages and a Maxim comparator to turn a visible-light or near-IR optical signal into a raw digital serial bitstream, exposed to a host PC over USB via an onboard FTDI chip.","honest_take":"This is essentially Maxim's own decades-old application-note reference circuit (AN1117, 'Small Photodiode Receiver Handles Fiber-Optic Data Rates to 800kbps') built onto a nice open PCB with an FTDI chip added for USB convenience - there is no microcontroller, no signal processing, and no decoding logic on board at all. It cites the classic Loughry & Umphress 'optical TEMPEST' paper as inspiration, but OpticSpy itself is not a TEMPEST-grade eavesdropping tool: no directional optics, no long-range sensitivity - the vendor's own range tests only reached about 1-3 inches. It's a hobbyist-range receiver front end, full stop, and you still have to build or find your own decoder for whatever signal you're chasing.","released":"2018","aliases":["Grand Idea Studio OpticSpy"],"capabilities":{"ir_rx":"yes","ir_tx":"no","uart":"no","ir_learn":"no","ir_universal_remote":"no","ir_flood":"no","jtag_swd":"no","i2c":"no","spi_flash_dump":"no","logic_analyzer":"no","glitching":"no","optical_covert_rx":"yes"},"legal":{"risk_level":"low","notes":"Passively receiving light emitted by a device you can see (e."},"ecosystem":{"community":"commercial","docs_quality":"excellent","last_release":"2018-02","app_store":"No","abandoned_risk":"low"}},{"id":"osmocombb-calypso","hardware_id":"osmocombb-calypso-phone","name":"OsmocomBB","firmware":"OsmocomBB","firmware_kind":"community","vendor":"Osmocom project","category":"sdr","subcategory":"gsm-baseband-research","status":"diy-only","price_usd":15.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"Requires understanding GSM's Layer 1/2/3 stack, sourcing a discontinued phone model on the secondhand market, and running the host-side layer23 applications yourself - there is no beginner path here.","build_effort":"full-diy","stealth":"covert","form_factor":"handheld","summary":"Open-source GSM baseband firmware for old TI Calypso-chipset feature phones (Motorola C1xx/C139/C155/V171 family), giving full open access to the GSM Layer 1/2/3 stack for protocol research: scanning control channels, logging cell info, and - because 2G's A5/1 encryption and lack of mutual network authentication are both weak - passive research into IMSI-catching and control-channel interception on 2G networks specifically. It is GSM (2G) only; it has no 3G/4G/5G capability of any kind, because those protocols don't run on this hardware or firmware at all.","honest_take":"Be blunt about what this still gets you in 2026: it is 2G-only, full stop, and 2G is actively being shut down worldwide. US carriers finished their 2G sunsets years ago; multiple European and Asian operators (France's Orange, the Netherlands, Japan, several in Vietnam and Thailand) have 2026 shutdown dates; roughly 70 countries have 2G phase-outs completed or scheduled. That doesn't make OsmocomBB useless - a substantial minority of countries (Saudi Arabia explicitly says it will run 2G indefinitely, and 21 countries have no published shutdown plan at all) still carry live 2G traffic, and it remains the standard open-source reference for GSM air-interface research and teaching regardless of live-network availability. But if the goal is real-world interception capability against a modern phone in a market that has sunset 2G, this tool cannot reach it - the target phone will simply refuse to fall back to a network this hardware can speak to. And this is entirely a research/education tool with a discontinued hardware dependency: you're hunting 15-20-year-old phones on eBay, not buying anything current.","aliases":["osmocom-bb","Osmocom Baseband"],"capabilities":{"sdr_rx":"no","sdr_tx":"no","sdr_bandwidth":"no","sdr_full_duplex":"no","packet_capture":"partial","scriptable":"yes","standalone_untethered":"no","usb_mass_storage":"no","web_ui":"no","app_store":"no","jtag_swd":"unknown","glitching":"no"},"legal":{"risk_level":"high","notes":"GSM interception and IMSI-catching are tightly regulated or outright illegal for non-licensed operators in most countries, regardless of how cheap or old the hardware is - many jurisdictions treat any unauthorized reception/decoding of mobile network control-channel data, and certainly any active network impersonation, as a serious telecommunications-interception offence carrying criminal penalties."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2026-06","app_store":"No","abandoned_risk":"low"}},{"id":"oui-spy-unified-blue","hardware_id":"oui-spy","name":"Oui-Spy","firmware":"OUI-SPY Unified Blue","firmware_kind":"stock","vendor":"Colonel Panic's Hack Shack","category":"detection-defense","subcategory":"ble-wifi-surveillance-detection","status":"available","price_usd":85.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Flash from a web page, join its Wi-Fi AP, pick a mode from a menu. No CLI needed for normal use.","build_effort":"assembled","stealth":"overt","form_factor":"pocket","summary":"A passive 2.4 GHz surveillance-detection scanner: a Seeed XIAO ESP32-S3 on a pair of art PCBs with a piezo buzzer and an RGB LED. It listens for BLE and Wi-Fi signatures belonging to surveillance hardware - Flock Safety ALPR cameras, Axon/Taser, Ring, DJI/Parrot/Skydio drones, Meta Ray-Bans - and beeps when it matches one. The name is a pun on OUI, the vendor prefix in a MAC address, which is what most of its matching is built on.","honest_take":"It is a $7.49 XIAO ESP32-S3 with a buzzer and an LED on two art PCBs, sold for $85 - you are buying the curated signature lists, the boot-menu firmware and the silkscreen, not the silicon. It only hears 2.4 GHz, so it will miss any camera that talks over LTE and does not also beacon Wi-Fi or BLE. And 'detection' means matching MAC OUI prefixes, BLE company IDs and service UUIDs against a hand-maintained list, which any vendor defeats by rotating MACs - the README says exactly that about Meta's Ray-Bans, which is why those get a separate composite rule instead.","aliases":["OUI-SPY","OuiSpy","Oui Spy","Colonel Panic Oui-Spy"],"capabilities":{"ble_scan":"yes","ble_sniff":"yes","ble_advertise":"no","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_probe_sniff":"yes","packet_capture":"yes","wifi_ap_mode":"yes","web_ui":"yes","detect_surveillance_cam":"yes","detect_drone":"yes","detect_generic_ble":"yes","detect_generic_wifi":"yes","gps":"no","sd_logging":"no","standalone_untethered":"partial"},"legal":{"risk_level":"low","notes":"As shipped it only receives, which is legal in nearly every jurisdiction, and detecting police or ALPR hardware is not itself an offence in the US."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08","app_store":"No - fixed set of firmware modes","abandoned_risk":"medium"}},{"id":"ovrdrive-usb","hardware_id":"ovrdrive-usb","name":"Ovrdrive USB","vendor":"Interrupt Labs","category":"accessory","subcategory":"anti-forensics-storage","status":"available","price_usd":79.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Normal hidden-data use just needs a specific triple-reinsertion sequence, but enabling the physical self-destruct requires cutting a PCB trace — an irreversible hardware modification.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"An open-hardware 16GB USB flash drive (ATtiny24A logic MCU + SM3257ENT flash controller) that reads as blank/broken unless plugged in three times in quick succession, at which point the real 16GB partition mounts normally. A separate, disabled-by-default circuit can invert the flash chip's supply voltage to heat it past 100°C as a physical self-destruct, armed only by cutting a PCB trace.","honest_take":"Multiple independent outlets (PCBWay's own engineering write-up, Hackster.io, CNX Software, TechSpot) describe a 16GB flash chip (part K9HDG08U1A), which contradicts the 8GB figure in some early coverage — treat 16GB as the better-sourced number for the shipped product, though an earlier prototype may genuinely have used 8GB. The self-destruct feature that gets all the headlines is disabled out of the box and requires physically cutting a trace to enable — most buyers who never do that are just getting a USB drive with a mildly clever hidden-partition trick, not a self-destructing one. Interrupt Labs themselves note the voltage-inversion heating may not be hot enough alone to fully destroy the NAND without an added thermite-like compound, so even 'armed' units aren't a guaranteed data-destruction method without further DIY work. This is squarely an anti-forensics tool for journalists/researchers in hostile environments, and using the self-destruct feature against data under a legal hold or active investigation carries real legal exposure regardless of the underlying data's content.","released":"2024","aliases":[],"capabilities":{"usb_mass_storage":"partial","hardware_destruct":"partial","usb_hid_inject":"no","usb_keylogger":"no","usb_exfil":"no","scriptable":"yes","standalone_untethered":"no","sd_logging":"no","wifi_ap_mode":"no","cloud_c2":"no"},"legal":{"risk_level":"medium","notes":"Owning and using hidden storage, including the concealment trick, is legal in most places."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2024","app_store":"No","abandoned_risk":"medium"}},{"id":"p4wnp1-aloa","hardware_id":"p4wnp1-aloa","name":"P4wnP1 A.L.O.A.","firmware":"P4wnP1 A.L.O.A.","firmware_kind":"diy","vendor":"Community project (MaMe82 originally, RoganDawes now)","category":"usb-hid","subcategory":"usb-attack-platform","status":"diy-only","price_usd":35.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Nominally 'flash an image', but in practice you are administering an unmaintained Debian-derived system, and when the image does not boot on the Pi you own, the fix is a community fork rather than a documented option.","build_effort":"flash-only","stealth":"covert","form_factor":"usb-stick","summary":"A Raspberry Pi Zero W that turns into whatever USB device you tell it to be: HID keyboard and mouse, USB Ethernet (RNDIS and CDC ECM), mass storage, or several at once. That composite-gadget ability is what set it apart from single-purpose BadUSBs - it can type a payload and simultaneously become the target's network interface, then serve it a shell over that link. Driven from a web UI with a visual payload editor and a HIDScript engine.","honest_take":"This is the clearest example in this batch of the trap the brief warns about: a beginner finds a 2019 tutorial, buys the wrong Pi, and gets a dead board. The project's last code push was October 2023, there are 210 open issues, and the Raspberry Pi Zero 2 W support ticket (#307) has been open since October 2021 with the official image simply not booting. If you follow the README you must buy the original 32-bit Pi Zero W specifically. Technically the design is still excellent and the USB gadget tricks are the real thing - but you are adopting an abandoned Debian image, and the safer route today is Kali's own P4wnP1 A.L.O.A. build, which at least tracks a maintained distribution. Also worth knowing: it boots a full Linux system, so it is not instant - budget tens of seconds before the payload runs.","released":"2018","aliases":["P4wnP1","P4wnP1 ALOA","A Little Offensive Appliance","MaMe82 P4wnP1"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_ethernet_attack":"yes","usb_mass_storage":"yes","usb_exfil":"yes","hid_remote_trigger":"yes","wifi_ap_mode":"yes","wifi_scan_24":"partial","web_ui":"yes","scriptable":"yes","packet_capture":"partial","standalone_untethered":"no"},"legal":{"risk_level":"high","notes":"Building and owning it is legal."},"ecosystem":{"community":"dormant","docs_quality":"excellent","last_release":"n/a - no release since the repo went quiet; Kali publishes its own P4wnP1 A.L.O.A. image","app_store":"No, but a community payload/template ecosystem grew up around it","abandoned_risk":"already-abandoned"}},{"id":"packet-squirrel-mark-ii","hardware_id":"packet-squirrel-mark-ii","name":"Packet Squirrel Mark II","firmware":"Packet Squirrel 4.x","firmware_kind":"stock","vendor":"Hak5","category":"network-implant","subcategory":"inline-ethernet-implant","status":"available","price_usd":150.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The web UI is friendly, but the thing that makes it useful - understanding bridging, NAT, ARP and where to physically place it - is not.","build_effort":"assembled","stealth":"implant","form_factor":"box","summary":"A matchbox-sized OpenWrt computer with two Ethernet ports that you install between a target device and the wall jack. Traffic passes through it while it captures pcaps, spoofs DNS, tunnels out over VPN, or holds the target in a jail. It is powered over USB-C and managed from a web interface or remotely through Cloud C2.","honest_take":"Understand the difference between this and a Plunder Bug before you buy either: the Packet Squirrel is INLINE and ACTIVE. It is a router in the path. It can modify, block, spoof and inject traffic, and it can route the target's traffic through your VPN. That power is also the risk - if it dies or you fumble a payload, you drop the target's network connection and you get noticed. Two honest caveats: Hak5 publishes no SoC, RAM or flash figure for the Mark II anywhere, which is unusual and means nobody outside Hak5 can tell you what it is running on. And the shipping firmware, 4.0.0-stable, is dated the day before the product launched in July 2023 and has not been updated since - for a device whose whole job is sitting on someone else's network, that is a security-maintenance question worth asking.","released":"2023","aliases":["Packet Squirrel MK2","PS MkII","Squirrel"],"capabilities":{"ethernet_mitm":"yes","ethernet_tap_passive":"partial","packet_capture":"yes","vpn_exfil":"yes","cloud_c2":"yes","web_ui":"yes","scriptable":"yes","usb_payload_lang":"partial","usb_mass_storage":"partial","standalone_untethered":"no","sd_logging":"no","wifi_scan_24":"no"},"legal":{"risk_level":"high","notes":"Physically installing a device that intercepts and can modify someone else's network traffic engages computer-misuse and wiretap law in most jurisdictions, and unlike a passive tap it also actively transmits onto the network."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2023-07","app_store":"Yes - official payload repository plus the Hak5 Payload Hub","abandoned_risk":"medium"}},{"id":"panda-comma-ai","hardware_id":"panda","name":"panda","firmware":"Stock (comma.ai)","firmware_kind":"stock","vendor":"comma.ai","category":"automotive","subcategory":"can-bus-interface","status":"available","price_usd":99.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Raw CAN/CAN-FD access to a live vehicle bus; the safety-rated firmware helps, but effective use still requires understanding vehicle CAN semantics.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"comma.ai's open-hardware USB CAN interface, currently sold as a single SKU ('red panda') built on an STM32H725 (4x the CPU of prior generations) with CAN-FD support on all 3 of its CAN buses plus one additional multiplexed bus. It is comma's own tool for both openpilot (where a red panda is required to run CAN-FD-only cars on a comma 3) and general car-hacking/diagnostics via its Python library and the opendbc/cabana ecosystem, and works as a plain CAN-to-USB adapter independent of openpilot.","honest_take":"The '3 CAN buses, all CAN-FD' spec reads like a lab-grade interface, but comma has never published a galvanic-isolation claim anywhere in its documentation - assume it is NOT isolated between the vehicle bus and your USB port unless you find evidence otherwise, unlike CANable Pro or the (discontinued) CANtact Pro, which both market isolation as a headline feature. The real product here is the safety-audited opendbc firmware and the openpilot/cabana software ecosystem around it, not exotic hardware - at $99 it undercuts every isolated competitor, but you're trading isolation and a shipped enclosure design for that price and for openpilot integration most car-hacking buyers won't use.","released":"2016","aliases":["red panda","comma panda"],"capabilities":{"packet_capture":"yes","scriptable":"yes","web_ui":"no","app_store":"no","standalone_untethered":"no","sd_logging":"no","cloud_c2":"no","usb_mass_storage":"addon","uart":"no","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","can_sniff":"yes","can_inject":"yes","can_fd":"yes","can_isolated":"no","obd2":"unknown"},"legal":{"risk_level":"low","notes":"Owning and using panda for diagnostics/research on a vehicle you own or are authorized to test is legal."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-09","app_store":"No","abandoned_risk":"low"}},{"id":"pandwarf-marauder","hardware_id":"pandwarf-marauder","name":"PandwaRF Marauder","firmware_kind":"stock","vendor":"PandwaRF (Comthings)","category":"subghz","subcategory":"covert-capture-deaddrop","status":"available","price_usd":1069.2,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Designed to be deployed and left running unattended (a 'dead drop'); its rolling-code analysis output is only useful to someone who already understands RF/keyfob protocols and has (or buys) the separate Kaiju analysis software/subscription.","build_effort":"assembled","stealth":"covert","form_factor":"box","summary":"An autonomous, battery-powered sub-GHz capture device meant to be hidden near a target (a 'dead drop') and left running for extended periods, silently recording keyfob, garage-door and alarm-remote transmissions on 315/433/868/915 MHz to internal memory (256-512 captures depending on tier) for later retrieval over Bluetooth LE. It shares the broader PandwaRF ecosystem with the handheld PandwaRF Rogue Pro, but is built for unattended field collection rather than interactive handheld use.","honest_take":"Read the tier structure before assuming you are buying 'rolling-code defeat': the Basic tier (EUR790) only logs fixed-code transmissions with no timestamps; genuine rolling-code cataloguing needs the Standard tier (EUR990) or above, and PandwaRF's own material is explicit that 'rolling code support' here means capturing and cataloguing transmissions for offline analysis via their separate Kaiju software, not defeating the rolling-code cryptography outright. Kaiju's most capable 'Gate Openers Pack' - with model identification and code generation - is gated behind a one-year 'LEA' (Law Enforcement Agency) license bundled only with the Ultimate tier, which strongly implies PandwaRF does not sell the strongest rolling-code-defeat features to the general public. As a covert implant this is a serious, purpose-built tool at a serious price (comparable to the handheld PandwaRF Rogue Pro plus an ongoing analysis subscription) - it is not a garage-door hacking gadget for a hobbyist, and deploying it on property or vehicles you do not own crosses from an RF-licensing question into a physical-intrusion and surveillance-law question well before the transmission-licensing one does.","aliases":["PandwaRF Marauder Basic","PandwaRF Marauder Standard","PandwaRF Marauder Ultimate"],"capabilities":{"subghz_rx":"yes","subghz_tx":"unknown","subghz_replay":"unknown","subghz_rolling_code":"partial","subghz_bruteforce":"no","subghz_external_antenna":"yes","subghz_amplified":"unknown","sd_logging":"no","standalone_untethered":"yes","packet_capture":"yes","scriptable":"unknown","app_store":"no","web_ui":"no","gps":"unknown"},"legal":{"risk_level":"high","notes":"This is a passive receiver for its core function, so the pure radio-licensing risk is lower than for a transmitter - but that is almost beside the point: a device explicitly designed to be hidden and left recording other people's keyfob and remote-control signals is a covert-surveillance device, and placing one on a vehicle, property, or gate you do not own or lack authorization to test is very likely to violate wiretapping/surveillance-device and trespass laws in most jurisdictions regardless of any radio-licensing rule."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No - dedicated PandwaRF Marauder Android app for retrieval","abandoned_risk":"medium"}},{"id":"pandwarf-rogue-pro","hardware_id":"pandwarf","name":"PandwaRF Rogue Pro","firmware":"PandwaRF","firmware_kind":"stock","vendor":"ComThings (GollumTech)","category":"subghz","subcategory":"rf-brute-force","status":"available","price_usd":490.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"The phone app hides most of the RF work, but interpreting captures still needs sub-GHz knowledge.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A CC1111-based sub-GHz capture/replay/brute-force tool driven over Bluetooth from a phone, sold to professional testers of gate and garage remotes. The Rogue tier adds a hardware brute-force engine (De Bruijn sequences, bit-mask skipping) that runs autonomously even if the phone disconnects.","honest_take":"The silicon is a TI CC1111 - the same class of chip as a YARD Stick One or a Flipper's CC1101 - so the radio is not what you are paying for; the brute-force engine and the licensed 'Kaiju' gate-opener packs are. Several of those packs cost as much again as the device. Brute-forcing fixed-code remotes was always easy; against modern rolling-code systems this does not magically work, and the vendor's own product tiering is confusing enough that buyers regularly order the wrong thing.","released":"2016","aliases":["PandwaRF","GollumRF"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_bruteforce":"yes","subghz_rolling_code":"no","subghz_external_antenna":"yes","scriptable":"partial"},"legal":{"risk_level":"high","notes":"Brute-forcing a gate or barrier you do not own is unauthorised access nearly everywhere, and sustained sub-GHz transmission breaches radio rules on top of that."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"unknown","app_store":"No - vendor app plus paid licence packs","abandoned_risk":"medium"}},{"id":"paw-detector","hardware_id":"paw-detector","name":"Paw Detector","firmware_kind":"stock","vendor":"Electronic Cats","category":"detection-defense","subcategory":"usb-cable-detector","status":"available","price_usd":18.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug the suspect cable/port through it and read one LED - no software, no setup.","build_effort":"assembled","stealth":"discreet","form_factor":"keychain","summary":"A keychain-sized USB pass-through tester built around a CH32V003 RISC-V microcontroller that runs onboard ADC analysis on the data-line pins to flag the electrical signature of a hidden keylogger/exfiltration implant inside a 'malicious cable' (O.MG-Cable-style). A steady LED means the cable/port is flagged as suspicious; no light is the vendor's 'presumed safe' state. Presented at DEF CON 34.","honest_take":"This is a heuristic anomaly detector tuned against known inline-implant electrical signatures, not a certified verifier - a well-engineered implant that keeps its data-line loading within normal-cable tolerances, or one that only activates after a time delay, is a plausible way to slip past it, and it only tests the instant you plug in rather than continuously monitoring. The common misconception is treating a clear LED as proof a cable is safe in any absolute sense; it only means this specific detector's heuristics didn't trip, against the implant designs it was tuned on.","released":"2026","aliases":["Paw Detector - Malicious USB cables detector"],"capabilities":{"usb_mass_storage":"no","usb_hid_inject":"no","usb_keylogger":"no","usb_exfil":"no","standalone_untethered":"yes","scriptable":"no","app_store":"no","web_ui":"no","sd_logging":"no","usb_cable_detect":"yes"},"legal":{"risk_level":"low","notes":"A purely defensive detection device."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"paw-protector","hardware_id":"paw-protector","name":"PAW Protector","firmware_kind":"n/a","vendor":"Electronic Cats","category":"detection-defense","subcategory":"usb-data-blocker","status":"available","price_usd":20.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-play inline adapter; nothing to configure.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A passive inline USB-A adapter that physically severs the D+/D- data lines between a phone/laptop and an untrusted charger or public USB port, while still passing up to 2.4A of charging current (with Apple/Quick-Charge fast-charge detection). It is a 'USB condom' - there is no MCU, just power-management and ESD-protection silicon (TPS2561 power switch, TPS2514A fast-charge detect, TPD2E001 ESD array).","honest_take":"It cannot detect or warn you of anything - it structurally blocks data regardless of what is on the other end, so don't confuse it with Electronic Cats' own Paw Detector, which actually inspects a cable. The common misconception is that a 'USB data blocker' senses a malicious charger; this one doesn't sense, it just amputates the data pins, which is simpler and arguably more trustworthy but gives zero feedback if you plug it in wrong or the port is doing something exotic like USB-PD data-over-power signaling.","released":"2023","aliases":[],"capabilities":{"usb_mass_storage":"no","usb_hid_inject":"no","usb_keylogger":"no","usb_exfil":"no","usb_ethernet_attack":"no","standalone_untethered":"yes","scriptable":"no","app_store":"no","web_ui":"no","usb_data_block":"yes","usb_cable_detect":"no"},"legal":{"risk_level":"low","notes":"A purely defensive device with no restrictions anywhere Electronic Cats ships to."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025-06","app_store":"No","abandoned_risk":"low"}},{"id":"phantap","hardware_id":"phantap-gl-ar150","name":"PhanTap (Phantom Tap)","firmware":"PhanTap","firmware_kind":"community","vendor":"NCC Group","category":"network-implant","subcategory":"invisible-lan-tap","status":"diy-only","price_usd":25.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"Requires comfort with OpenWrt CLI, Linux bridging/netfilter, and OpenVPN to set up correctly; a misconfigured bridge is easy to make visible on the wire.","build_effort":"flash-only","stealth":"implant","form_factor":"box","summary":"PhanTap is an NCC Group red-team research project: an OpenWrt package that turns a cheap two-port router into an inline network implant which learns the victim device's MAC/IP and masquerades as it, so the implant is invisible to switches, NAC, and traffic monitoring, while phoning home over an OpenVPN tunnel on TCP/443 for remote pivoting. It was built and demonstrated on the GL.iNet GL-AR150 but is software, not a product.","honest_take":"This is a research proof-of-concept, not a plug-and-play implant — you are building and hardening an OpenWrt bridge yourself, and the README itself flags real limits: the GL-AR150 caps out at 100Mbps against modern gigabit LANs, STP/pause/LACP frames aren't passed by a Linux bridge (so it can out itself on a switch that cares about those), and the victim's port stays 'live' even if the real device is unplugged, which is a detectable anomaly to anyone watching switch logs closely. NCC Group has not updated the core project's attack surface since 2019 even though the repo still gets maintenance commits; treat the NAC-bypass claim as solid 2019-era 802.1X, not a guarantee against modern posture-checking NAC.","released":"2019","aliases":["Phantom Tap"],"capabilities":{"ethernet_tap_passive":"yes","ethernet_mitm":"yes","packet_capture":"yes","cloud_c2":"yes","vpn_exfil":"yes","usb_ethernet_attack":"no","usb_mass_storage":"no","wifi_ap_mode":"no","wifi_scan_24":"no","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"The code and a spare router are legal to own and study."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2025-10","app_store":"No","abandoned_risk":"low"}},{"id":"phywhisperer-usb","hardware_id":"phywhisperer-usb","name":"PhyWhisperer-USB (CW610)","firmware":"Stock (NewAE, open source)","firmware_kind":"stock","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"usb-monitor-trigger","status":"available","price_usd":360.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"An in-line USB protocol monitor/trigger for timing side-channel and fault-injection captures against USB targets - assumes familiarity with USB 2.0 protocol framing and with ChipWhisperer-style capture workflows.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"An in-line USB 2.0 Low/Full/High-Speed monitor and pattern trigger built around a Xilinx Spartan-7 XC7S15 FPGA and an Atmel/Microchip ATSAM3U (Cortex-M3) microcontroller. It buffers 8,192 bytes of captured USB traffic in FPGA block RAM, fires a cycle-accurate trigger when 1-64 bytes of masked pattern match (with 0-1,048,576 cycle programmable delay), includes a bypassable 5-ohm power shunt for correlating captures with power draw on an external scope, and feeds synchronized clock/trigger signals to ChipWhisperer capture hardware for USB-target power analysis and fault injection.","honest_take":"This is a precision timing/triggering instrument, not a USB sniffer for casual protocol analysis - Wireshark with a USB capture driver, or a cheap USB protocol analyzer, does general-purpose USB traffic inspection far more conveniently. PhyWhisperer-USB earns its keep specifically for side-channel and fault-injection work against USB-connected targets, where you need a trigger that fires on exact protocol bytes with cycle-accurate timing synced to a ChipWhisperer - a niche need, but one nothing else in this price range addresses.","aliases":["CW610"],"capabilities":{"hid_remote_trigger":"yes","packet_capture":"partial","scriptable":"yes","uart":"no","jtag_swd":"no","spi_flash_dump":"no","i2c":"no","glitching":"addon","logic_analyzer":"partial","standalone_untethered":"no","web_ui":"no","app_store":"no","sd_logging":"no","side_channel_power":"addon"},"legal":{"risk_level":"low","notes":"A passive-ish USB in-line monitor/trigger for lab research use - no radio transmitter, and it sits on a cable you already control."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"piccante-can-firmware","hardware_id":"piccante-pico-can","name":"PiCCANTE","firmware":"PiCCANTE","firmware_kind":"community","vendor":"Alia5 (open source project)","category":"automotive","subcategory":"can-bus","status":"diy-only","price_usd":15.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You are sourcing parts, wiring or fabricating a PCB from the provided KiCAD files, removing stray 120-ohm termination resistors from generic transceiver breakouts, and flashing firmware yourself. Nothing is sold pre-built.","build_effort":"full-diy","stealth":"discreet","form_factor":"board","summary":"Open-source firmware that turns a Raspberry Pi Pico or Pico 2 (W) plus one to three 3.3V CAN transceivers into a multi-channel CAN bus sniffer and injector, speaking SLCAN/SocketCAN and SavvyCAN's GVRET protocol and partially emulating an ELM327 OBD-II adapter. It's a from-scratch, solder-it-yourself alternative to commercial CAN interfaces like CANtact or PCAN-USB.","honest_take":"This is a hobbyist CAN interface, not a drop-in CANtact or Kvaser replacement: CAN FD and CAN XL are unsupported by design (the PIO-based bit-banging can't keep up with them), there's no hardware bus filtering yet, and the project's own docs call the ELM327 emulation partial - no adaptive timeouts, no auto protocol detection. There is also no vendor here at all: no assembled board, no warranty, no support contract, just a GitHub repo with 12 open issues. What the ~$15-45 in parts actually buys you is real multi-channel SocketCAN/SavvyCAN compatibility, which is the expensive part of commercial tools - budget your own time for the rest.","aliases":["PiCCANTE CAN firmware","Pico CAN sniffer"],"capabilities":{"packet_capture":"yes","scriptable":"yes","web_ui":"addon","wifi_ap_mode":"addon","sd_logging":"no","standalone_untethered":"no","usb_mass_storage":"no","i2c":"no","spi_flash_dump":"no","jtag_swd":"no","glitching":"no","logic_analyzer":"no","can_sniff":"yes","can_inject":"yes","can_fd":"no","can_isolated":"no","obd2":"partial"},"legal":{"risk_level":"medium","notes":"Reading CAN traffic on a vehicle you own for diagnostics is unremarkable almost everywhere."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-01","app_store":"No","abandoned_risk":"low"}},{"id":"pico-ducky","hardware_id":"raspberry-pi-pico","name":"pico-ducky (Raspberry Pi Pico BadUSB)","firmware":"pico-ducky (dbisu)","firmware_kind":"diy","vendor":"Raspberry Pi (hardware) / open-source firmware","category":"usb-hid","subcategory":"badusb","status":"diy-only","price_usd":6.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Drag two files onto a mass-storage device; no toolchain, no soldering.","build_effort":"flash-only","stealth":"overt","form_factor":"usb-stick","summary":"The reference way to build a USB Rubber Ducky for the price of a coffee: a Raspberry Pi Pico running CircuitPython, executing DuckyScript payloads as a USB HID keyboard. With a Pico W it also serves a small web interface so payloads can be triggered over Wi-Fi. 3,300 GitHub stars and still updated in 2026.","honest_take":"It is a bare green board with a micro-USB connector - it looks nothing like a flash drive, so 'someone will plug this in' social engineering needs a case. It also mounts as writable storage by default unless you disable that, which is both a giveaway and a way to lose your payload. What it does not have is the Hak5 Ducky's tidy hardware, attack-mode switching or its script-language extensions. For learning and for throwaway hardware, the price difference makes the trade obvious.","released":"2021","aliases":["picoducky","Pico Rubber Ducky","Pi Pico BadUSB"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","hid_remote_trigger":"partial","usb_mass_storage":"partial","usb_exfil":"partial","scriptable":"yes"},"legal":{"risk_level":"high","notes":"The Pico is a general-purpose dev board and legal everywhere."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-03","app_store":"No - community payload repositories","abandoned_risk":"low"}},{"id":"faultyhardware-picoglitcher-v3","hardware_id":"faultyhardware-picoglitcher-v3","name":"PicoGlitcher v3","firmware":"Findus","firmware_kind":"stock","vendor":"Faulty Hardware (Mathias Kesenheimer)","category":"hardware-debug","subcategory":"voltage-glitcher","status":"available","price_usd":59.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Even the pre-assembled unit is a bare Python/CLI tool with no GUI hand-holding - you're expected to understand fault-injection concepts (timing, voltage window search) to get useful results. The unassembled kit additionally requires SMD/THT soldering.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An open-source voltage-glitching board built around a Raspberry Pi Pico 2, with two MOSFETs wired as crowbar switches to fault a target's power rail, dual level shifters multiplexing 1.2/1.8/3.3/5V target power, and adjustable Schmitt-trigger inputs (EXT1/EXT2) for filtering the trigger signal. It's driven by the open-source 'Findus' Python library, which can alternatively drive a ChipWhisperer Pro or Husky using the same code.","honest_take":"This is the third hardware revision of a one-person open-source project - v1 (plain Raspberry Pi Pico) is now officially retired on Tindie ('no longer available for sale'), and v2 (still original Pico, added the 4-voltage multiplexer) doesn't appear to have a current standalone store listing either; what's actually sold today under both 'Pico Glitcher' and 'PicoGlitcher v3' branding is this same Pico-2-based v3 board - this record merges what first-pass research logged as two separate products. The core design is fully open (schematics, GPL-3.0) on GitHub, so a comfortable hobbyist solderer could scratch-build the electronics for something like $15-30 in parts (a Pico 2 is about $5, the FETs/level-shifters/passives are a few dollars more); the $59-67 asking price mostly buys a routed/tested PCB, SMA connectors, and a kit rather than novel hardware. The '66A' transistor rating quoted in marketing is the switching device's absolute maximum, not a sustained operating current. 207 GitHub stars and commits as recent as 2026-07-29 make it a reasonably healthy hobbyist project, but it's maintained by one person, so treat it as a bus-factor-of-one dependency.","released":"2025","aliases":["Pico Glitcher","Pico Glitcher v3","PicoGlitcher","Findus","fault-injection-library"],"capabilities":{"glitching":"yes","jtag_swd":"no","uart":"no","i2c":"no","spi_flash_dump":"no","logic_analyzer":"no","usb_mass_storage":"no","usb_hid_inject":"no"},"legal":{"risk_level":"low","notes":"It's lab/test equipment with no radios - no import restrictions found."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"No","abandoned_risk":"low"}},{"id":"piglet-wardriver","hardware_id":"piglet-wardriver","name":"Piglet Wardriver","firmware":"Piglet","firmware_kind":"diy","vendor":"Hamspiced (open-source project, no company)","category":"wardriving","subcategory":"wifi-wardriver-firmware","status":"diy-only","price_usd":14.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flashing is simple, but there is no official carrier board - you wire your own GPS module (and optionally an OLED) to a bare XIAO before it is a wardriver at all.","build_effort":"soldering","stealth":"discreet","form_factor":"board","summary":"Open-source wardriving firmware for Seeed's XIAO ESP32 family: 2.4GHz Wi-Fi scanning on every supported board, genuine 5GHz scanning on the C5, GPS-tagged WiGLE-format CSV logging to SD, a live web UI, and an ESP-NOW mesh mode letting several units share scan coverage as networked nodes. It is a passive collection tool with no attack features anywhere in the source.","honest_take":"Piglet does one job and is honest that it only does that job - there is no deauth, no injection, nothing offensive in the source, and it is entitled to the credit that deserves. The catch is what the $14 headline price hides: that is a bare MCU board with no GPS, no case, and no carrier PCB, so a real build costs closer to $35-50 once you wire in a GPS module yourself. If you want 5GHz wardriving without any DIY wiring, the already-tracked C5 Wardriver (also ESP32-C5-based, from the ESP32 Marauder author) ships as a proper host board with GPS, battery management, a screen and buttons built in for $69 plus a $10-15 dev kit - more total dollars, zero soldering. Piglet's actual differentiator is the ESP-NOW mesh mode, which nothing else in this comparison offers, and the CC BY-NC license means nobody can legally sell you a finished unit even if they wanted to.","aliases":["Piglet"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"partial","wifi_monitor_mode":"no","wifi_injection":"no","wifi_deauth_24":"no","wifi_evil_twin":"no","wifi_beacon_spam":"no","wifi_handshake_capture":"no","wifi_wardriving":"yes","wifi_ap_mode":"yes","ble_scan":"no","gps":"addon","gps_wardrive_log":"yes","sd_logging":"yes","web_ui":"yes","app_store":"no","standalone_untethered":"partial"},"legal":{"risk_level":"low","notes":"Purely passive Wi-Fi scanning and logging - no transmission beyond normal Wi-Fi/ESP-NOW association."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-07","app_store":"No","abandoned_risk":"low"}},{"id":"pikvm-v4-plus-hardware-rat","hardware_id":"pikvm-v4-plus","name":"PiKVM v4 Plus","firmware":"PiKVM OS (Arch Linux ARM)","firmware_kind":"stock","vendor":"PiKVM (hardware); resold by Lab401 under a red-team-branded listing","category":"network-implant","subcategory":"covert-kvm-rat","status":"available","price_usd":540.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"The device itself is plug-and-play once configured, but getting covert cellular connectivity working means sourcing and pairing a compatible LTE modem yourself, which the box does not include.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"A Raspberry Pi Compute Module 4 based KVM-over-IP unit: HDMI capture up to 1920x1200@60Hz, virtual keyboard/mouse/mass-storage emulation, Ethernet and Wi-Fi, plus an mPCIe slot and SIM slot for an LTE/5G modem so it can phone home over cellular instead of the target's network. It is PiKVM's own legitimate open-source sysadmin remote-management hardware; Lab401 resells the identical unit as a 'Hardware RAT' for red-team drop-in installs.","honest_take":"Read PiKVM's own site and this is a sysadmin tool for managing datacenter servers - 'undetectable by antivirus' is Lab401's marketing language, not PiKVM's, and it's true only in the boring sense that a KVM dongle isn't malware running on the host OS, not in the sense that it's hard to notice physically. It genuinely is powerful for physical-access engagements: full keyboard/mouse/video/mass-storage control independent of the target's network. But the 'RAT' framing implies more covertness than you're buying - there's no modem in the box, the mPCIe and SIM slots are empty, and Lab401's page doesn't mention that. A real covert cellular install needs you to separately source a modem, SIM and antenna, adding cost, time and one more thing that can fail during an engagement.","released":"2024","aliases":["PiKVM V4 Plus","Hardware RAT"],"capabilities":{"hdmi_capture":"yes","usb_hid_inject":"yes","usb_mass_storage":"yes","cloud_c2":"claimed","ethernet_mitm":"no","ethernet_tap_passive":"no","packet_capture":"no","usb_keylogger":"no","standalone_untethered":"yes","scriptable":"yes","web_ui":"yes","wifi_ap_mode":"unknown","glitching":"no"},"legal":{"risk_level":"high","notes":"Connecting this to a machine or network you don't own or have explicit written authorization to access is a computer-misuse offence in most jurisdictions, independent of how the hardware is marketed."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026","app_store":"No - REST API and web UI","abandoned_risk":"low"}},{"id":"pikvm-v4-plus","hardware_id":"pikvm-v4-plus","name":"PiKVM V4 Plus","firmware":"kvmd (PiKVM software stack)","firmware_kind":"stock","vendor":"PiKVM / HiPi Industries (hardware); resold by lab401 and others","category":"network-implant","subcategory":"kvm-over-ip","status":"available","price_usd":387.72,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Legitimate use is straightforward web-UI remote administration; using it as a covert drop device requires real operational security and physical access planning that the product itself doesn't provide.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"PiKVM V4 Plus is a legitimate, well-regarded open-source KVM-over-IP appliance built around a Raspberry Pi Compute Module 4: it captures a target machine's video (up to 1080p60), emulates a USB keyboard/mouse and a virtual mass-storage drive for OS reinstalls, and controls ATX power - giving BIOS-level remote access over Ethernet, Wi-Fi, or an optional cellular modem card. lab401 resells this exact hardware with 'undetectable hardware RAT for red-team engagements' marketing that is entirely the reseller's framing, not the PiKVM project's.","honest_take":"PiKVM is genuinely good, actively maintained open-source engineering, used widely by homelabbers and datacenter admins for exactly what it says: remote BIOS-level access to a machine you own or administer. The 'undetectable' framing is 100% lab401's marketing copy - the official PiKVM site describes it purely as sysadmin/datacenter equipment and never mentions covert or red-team use. What the marketing also glosses over: this is not a drop-in-five-seconds implant like a cable-swap device - you need physical access to plug in HDMI, USB, and power on the target machine, which is a much bigger physical-access requirement than something like an O.MG Cable or Screen Crab. The optional cellular modem (sold as a separate mPCIe card, not built in) does let an operator reach the unit over an out-of-band channel that bypasses the target network's own monitoring, which is the one part of the pitch that's technically accurate.","released":"2023","aliases":[],"capabilities":{"hdmi_capture":"yes","usb_hid_inject":"yes","usb_mass_storage":"yes","web_ui":"yes","cloud_c2":"partial","standalone_untethered":"yes","ethernet_tap_passive":"no","packet_capture":"no","wifi_scan_24":"no","ble_scan":"no","gps":"no","app_store":"unknown","jtag_swd":"no"},"legal":{"risk_level":"high","notes":"Owning and using PiKVM on your own equipment is completely legal."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026","app_store":"No","abandoned_risk":"low"}},{"id":"plunder-bug","hardware_id":"plunder-bug","name":"Plunder Bug LAN Tap","firmware_kind":"n/a","vendor":"Hak5","category":"network-implant","subcategory":"lan-tap","status":"available","price_usd":130.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug it in, open Wireshark. The subtlety is knowing that you must actively mute it to stop it transmitting.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A small three-port device: two RJ45 sockets that you insert into an existing Ethernet run, and a USB-C port that presents packets from that link to your laptop as an ordinary network interface. It uses an ASIX AX88772C USB Ethernet chip, so no drivers are needed on most systems.","honest_take":"The single most important thing about this device is the thing beginners get wrong: out of the box it is NOT a passive tap. Hak5's own documentation says the USB-C tap port 'will also act as an additional Ethernet port on the target LAN' - it transmits by default, which means it can be seen, can respond to ARP, and puts you on the network. Passive 'mute' mode is a deliberate opt-in you enable by running plunderbug.ps1 or plunderbug.sh --mute on your laptop, and that setting lives on your host, not on the device. If you genuinely must not transmit - forensics, air-gapped environments, or anywhere that would notice a new MAC - use a real passive tap: Great Scott Gadgets' Throwing Star LAN Tap is an open-source PCB with no active components that costs about $15 to $40 and physically cannot transmit. Also note the Plunder Bug is 10/100 only, so a gigabit link will auto-negotiate down to 100 Mbps, which is both a bottleneck and a visible anomaly on a well-monitored network.","released":"2019","aliases":["Plunder Bug","Bug","LAN Tap"],"capabilities":{"ethernet_tap_passive":"partial","ethernet_mitm":"no","packet_capture":"yes","standalone_untethered":"no","cloud_c2":"no","scriptable":"partial","sd_logging":"no"},"legal":{"risk_level":"high","notes":"Intercepting network traffic you are not a party to engages wiretap and interception law in most jurisdictions, and because this device transmits by default it may additionally constitute unauthorised access to the network rather than mere passive listening - a materially worse position legally."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2019-02","app_store":"No","abandoned_risk":"high"}},{"id":"pn532killer","hardware_id":"pn532killer","name":"PN532Killer","firmware_kind":"stock","vendor":"NFC-funs (MCUer)","category":"rfid-nfc","subcategory":"nfc-emulator-sniffer-bare-pcb","status":"available","price_usd":29.99,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Bare PCB, no case, no built-in menu - you drive it over UART/USB with the MTools/MTools BLE phone apps or your own serial client.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A bare-PCB NFC reader/emulator/sniffer built around a chip the vendor calls 'AD156', with no public datasheet found for it. It's positioned as a faster, cheaper alternative to genuine PN532 modules and to the Chameleon Ultra for MIFARE Classic/Ultralight/NTAG/ISO15693 emulation and nested/hardnested nonce sniffing.","honest_take":"The 'Killer' branding oversells it: this isn't breaking anything a PN532 or Chameleon Ultra can't already do, it's a competing implementation on a chip with no independently verifiable datasheet, so the vendor's own performance claims (4x the frame-delay speed of a Chameleon Ultra) can't be checked against a public spec. As of this research pass, the vendor's own documentation lists Darkside and StaticNested key-recovery, plus full relay attack, as 'coming soon' - not shipping - so don't assume that column is live without checking the current firmware changelog. At $29.99 it's Chameleon Ultra money for hardware with far less public scrutiny and no case included.","aliases":[],"capabilities":{"hf_1356_read":"yes","hf_1356_emulate":"yes","hf_1356_write":"unknown","iso15693":"yes","felica":"yes","mifare_classic_attacks":"partial","mifare_desfire":"no","nfc_type4_ndef":"no","emv_read":"no","nfc_relay":"claimed","lf_125khz_read":"unknown","lf_125khz_write":"no","lf_125khz_emulate":"no","scriptable":"yes","standalone_untethered":"partial","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"Owning the board is legal in most places."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-01","app_store":"n/a - companion Android app 'MTools' and iOS app 'MTools BLE'","abandoned_risk":"medium"}},{"id":"pocket-ghost-ghostesp","hardware_id":"pocket-ghost","name":"Pocket Ghost","firmware":"GhostESP (Revival)","firmware_kind":"community","vendor":"The Wired Hatters","category":"wifi","subcategory":"esp32-wifi-handheld","status":"available","price_usd":41.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"One chip, one web flasher, a touchscreen menu. The cheapest way into GhostESP with a screen if you do not want to source your own board.","build_effort":"flash-only","stealth":"discreet","form_factor":"pocket","summary":"A small assembled ESP32 board with a colour touchscreen, sold as a palm-sized GhostESP handheld. It covers the 2.4 GHz Wi-Fi and BLE side of GhostESP - scanning, deauth, evil portal, SSID cloning, beacon spam, handshake capture - and nothing else. The vendor does not name the board it is built on.","honest_take":"The listing says 'packet sniffing and injection', which on a plain 2.4 GHz ESP32 means 802.11 management-frame spam - deauth, beacons, probes - not the arbitrary frame injection a real monitor-mode adapter gives you. The vendor never names the module, but a EUR35 ESP32 with a colour touchscreen is a Cheap Yellow Display-class board that costs $12-15 on its own, running the same free GhostESP; you are paying roughly EUR20 for the case, the assembly and someone else's testing. That is a defensible EUR20 if you do not want to shop for boards, but it is not a $200 device in a small package.","aliases":["Pocket Marauder","Wired Hatters Pocket Ghost"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"partial","wifi_probe_sniff":"yes","ble_scan":"yes","ble_spam_apple":"yes","web_ui":"yes","standalone_untethered":"unknown","sd_logging":"unknown","subghz_rx":"no","ir_tx":"no","gps":"no"},"legal":{"risk_level":"medium","notes":"Owning it is legal."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-09","app_store":"Yes - via GhostESP","abandoned_risk":"low"}},{"id":"poisontap","hardware_id":"poisontap","name":"PoisonTap","vendor":"Samy Kamkar","category":"network-implant","subcategory":"usb-ethernet-implant","status":"diy-only","price_usd":15.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"Setup is scripted, but understanding and safely wielding the DNS-rebinding/cache-poisoning attack chain requires real web-security depth.","build_effort":"full-diy","stealth":"covert","form_factor":"usb-stick","summary":"Samy Kamkar's 2016 proof-of-concept: a Raspberry Pi Zero that emulates a USB Ethernet adapter when plugged into a locked or unlocked computer, tricks the OS into routing all traffic through it via a DHCP response claiming the entire IPv4 space, then siphons HTTP cookies across the Alexa top 1M domains through hidden iframes and force-caches persistent WebSocket backdoors in the browser cache — all without needing to unlock the screen.","honest_take":"This is the direct ancestor of the O.MG Cable / Packet Squirrel class of device already in this database, and it's worth understanding for that lineage alone, but it does essentially nothing against a fully modern browser: any cookie with the Secure flag survives, any site with HSTS blocks the HTTP downgrade the whole attack depends on, and both are now close to universal on major sites. It is not a keystroke injector (a common mix-up with Rubber Ducky-class devices) — PoisonTap never types anything, it hijacks network routing and browser caching. The GitHub repo has been dormant since 2018 with 90 open issues and no license file, so there's no vendor and no update path; it survives purely as a teaching example.","released":"2016","aliases":[],"capabilities":{"usb_ethernet_attack":"yes","ethernet_mitm":"yes","usb_exfil":"yes","usb_hid_inject":"no","usb_mass_storage":"no","vpn_exfil":"no","cloud_c2":"partial","packet_capture":"no","wifi_scan_24":"no","standalone_untethered":"no","scriptable":"yes","sd_logging":"yes"},"legal":{"risk_level":"medium","notes":"Owning a Pi Zero and studying the code is legal."},"ecosystem":{"community":"dead","docs_quality":"good","last_release":"2018-11","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"poom-stock","hardware_id":"poom","name":"POOM","firmware":"POOM firmware","firmware_kind":"stock","vendor":"Stellar IoT","category":"multitool","subcategory":"wireless-and-maker-handheld","status":"preorder","price_usd":140.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Four very different modes on one small mono OLED, plus a Lua scripting layer and a CLI. Approachable to poke at, deep to actually use.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A small ESP32-C5 handheld with a 1.3in monochrome OLED, a D-pad and A/B buttons, a Qwiic connector, microSD, an IMU, an IR transmitter and an NFC front end. It splits into four personalities: a maker mode with an I2C scanner and sensor streaming into Home Assistant or Edge Impulse, a motion-to-MIDI performance mode, a genuine wireless security toolkit covering Wi-Fi, BLE, Zigbee and Thread with PCAP export, and an Arduboy-compatible games machine that runs the whole Arduboy library.","honest_take":"The security half is more real than the price suggests - the firmware carries a working PicoPass/iCLASS reader with loclass key recovery and Wiegand decoding, MIFARE Classic key discovery, an 802.15.4 sniffer that writes PCAP, Open Drone ID capture and spoofing, and Lua scripting. That is a serious amount of engineering for a 140-dollar gadget. But three things do not line up. The site says MIT licence while the actual repository has no licence file at all, which legally means all rights reserved. The Kickstarter says the default NFC chip is a PN532 with the far more capable ST25R3916 only as a stretch goal, while the firmware's entire NFC stack is written against the ST25R3916 - so which chip is in a shipped unit is genuinely unclear. And the repo's own default build target is the ESP32-C6, which is 2.4 GHz only, even though the whole product is marketed on the C5's 5 GHz. There is also no sub-GHz radio at all, no published battery capacity, and no way to actually order one.","released":"2026","aliases":["The POOM","POOM multitool","Stellar IoT POOM"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"partial","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"unknown","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_karma":"yes","wifi_beacon_spam":"yes","wifi_handshake_capture":"yes","wifi_ap_mode":"yes","packet_capture":"yes","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_hid":"yes","ble_tracker_detect":"yes","zigbee":"partial","hf_1356_read":"partial","hf_1356_emulate":"partial","mifare_classic_attacks":"yes","ir_tx":"yes","detect_drone":"yes","detect_generic_wifi":"yes","subghz_rx":"no","lf_125khz_read":"no","usb_hid_inject":"no","gps":"no","sd_logging":"yes","scriptable":"yes","app_store":"partial","web_ui":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"medium","notes":"Owning it is legal in most places."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"none","app_store":"Web flasher and games catalogue on the vendor site","abandoned_risk":"medium"}},{"id":"portapack-h4m-pro-hackrf-pro","hardware_id":"portapack-h4m-pro","name":"PortaPack H4M Pro for HackRF Pro","firmware":"Mayhem","firmware_kind":"community","vendor":"OpenSourceSDRLab (board manufacture); Great Scott Gadgets (HackRF Pro design); Mayhem community (firmware)","category":"sdr","subcategory":"handheld-sdr","status":"available","price_usd":210.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Flashing Mayhem and understanding HackRF Pro's extended sampling modes (16-bit extended-precision, 4-bit half-precision) assumes real SDR experience.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"A touchscreen, battery, and control module that turns a HackRF Pro into a standalone handheld SDR running Mayhem firmware - a display shell for a separately-purchased HackRF Pro, not a radio in its own right. Physically NOT compatible with the older HackRF One (different battery connector, USB-C, and board revision).","honest_take":"This board contributes zero RF capability of its own - every frequency-range, ADC-bit-depth, and bandwidth number that actually matters belongs to the HackRF Pro underneath it (100kHz-6GHz, half-duplex, up to 20MSPS over USB at 8-bit or 16-bit extended-precision at lower rates), which is sold separately and not included in this $210. What you're actually paying for is a touchscreen, 18650 battery holder, SD slot, headphone jack, and RTC - the same value proposition as the older H4M for HackRF One, just re-wired for HackRF Pro's 18650 battery format, USB-C port, and TCXO. Budget the HackRF Pro's cost on top of this if you don't already own one; a 'PortaPack' listing at $210 undersells the true cost of a working handheld unit.","released":"2025","aliases":["H4M Pro"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"no","standalone_untethered":"yes","app_store":"no","sd_logging":"yes","web_ui":"no","scriptable":"yes","gps":"no","ble_scan":"no","packet_capture":"partial"},"legal":{"risk_level":"medium","notes":"Owning a general-purpose SDR transceiver is legal in most countries."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026","app_store":"No","abandoned_risk":"low"}},{"id":"ucshop-programmable-badusb-cable","hardware_id":"ucshop-programmable-badusb-cable","name":"Programmable BadUSB Payload Cable (USB-A to USB-C)","firmware":"unknown/proprietary","firmware_kind":"third-party-product","vendor":"Unlimited Coverage","category":"usb-hid","subcategory":"badusb-cable","status":"available","price_usd":24.99,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Marketed as a ready-to-use platform; without a published toolchain link, actually reprogramming it is not confirmed to be beginner-friendly in practice.","build_effort":"assembled","stealth":"covert","form_factor":"cable","summary":"A USB-A-to-USB-C cable advertised as containing a programmable microcontroller that can emulate HID keyboard/mouse input and virtual mass storage while looking like an ordinary charging/data cable. The listing is built almost entirely from generic marketing language - no chip, no schematic, and no linked GitHub repository or configuration tool are given anywhere on the page.","honest_take":"Treat this one with real skepticism: the Tindie listing's product description reads as templated boilerplate reused across this seller's catalog (which also includes rooted-phone 'HacPhone' resells and a 'USB Power-Kill Tester'), names no MCU, no radio, no storage capacity, and links to no GitHub repo, schematic, or the 'configuration toolchain' and 'docs' it repeatedly references. At roughly a tenth of the O.MG Cable's $180 price, either this is a rebadged generic BadUSB cable PCB (several near-identical ones circulate on AliExpress, typically built around cheap ATtiny85 or CH552-class chips) sold at a fair price for what it is, or the capabilities are simply unverifiable marketing copy - available sources cannot distinguish between the two. Buy it expecting a basic single-payload cable, not a full O.MG-Cable-class device, and don't expect vendor documentation to back up any specific claim.","aliases":[],"capabilities":{"usb_hid_inject":"claimed","usb_mass_storage":"claimed","usb_exfil":"unknown","usb_keylogger":"no","hid_remote_trigger":"no","usb_payload_lang":"unknown","scriptable":"unknown","standalone_untethered":"claimed","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning the device is legal."},"ecosystem":{"community":"commercial","docs_quality":"none","last_release":"unknown - no firmware repository found","app_store":"No","abandoned_risk":"medium"}},{"id":"project-reboot-hardware-target","hardware_id":"project-reboot","name":"Project Reboot: Hardware Audit Training Target","firmware_kind":"n/a","vendor":"Mindstorm Security","category":"hardware-debug","subcategory":"training-target","status":"available","price_usd":110.7,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Explicitly built as an on-ramp for people intimidated by hardware RE - each of the four challenges (UART, I2C, SPI, BLE) has a Normal and a Hard mode plus a full written walkthrough, so it scales from first-timer to a harder self-test.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A commercial practice-target PCB shaped like a 'crashed robot' that gates four staged challenges - UART console recovery, I2C bus sniffing, external SPI flash extraction, and BLE GATT interaction - each ending in a flag, with an official written walkthrough. Built by Mindstorm Security (also behind the separate MACOBOX hardware-pentest tool) and sold through Lab401.","honest_take":"This is a boxed version of the exercises any hardware-hacking course already teaches on breadboards and cheap dev boards - you're paying roughly EUR100+ for curation, a written walkthrough, and not having to design your own target. Mindstorm Security hasn't published a schematic or named the MCU/BLE chip, so unlike the other three devices in this batch you can't verify difficulty or extend it yourself. Worth it for a guided, zero-setup on-ramp or as a consistent target for a class; skip it if you're comfortable sourcing your own STM32/nRF52 dev board and wiring up the same four interfaces yourself for a fraction of the price.","aliases":[],"capabilities":{"uart":"yes","i2c":"yes","spi_flash_dump":"yes","ble_advertise":"yes","jtag_swd":"no","glitching":"no","logic_analyzer":"no","bt_classic":"no","usb_mass_storage":"no"},"legal":{"risk_level":"low","notes":"A passive practice PCB with a low-power BLE radio, not a transmitter or jammer - the same low regulatory profile as any hobbyist BLE dev board."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"proxmark3-rdv4-sim-sam-extension","hardware_id":"proxmark3-rdv4-sim-sam-extension","name":"Proxmark 3 RDV4 - SIM/SAM Extension","firmware_kind":"n/a","vendor":"RRG (RFID Research Group) / Proxgrind - designers and manufacturers of the Proxmark3 RDV4 platform","category":"rfid-nfc","subcategory":"Proxmark3 RDV4 accessory: SIM/SAM smart-card slot extension","status":"available","price_usd":26.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Only useful to someone already running Proxmark3/RRG firmware and pursuing SAM-based research (e.g. HID iCLASS PACS/SIO decode) - not a beginner accessory, and a genuine HID SAM is not something a hobbyist can easily or legitimately obtain.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A small extension module that plugs into the dedicated SIM/SAM header on a Proxmark 3 RDV4 or RDV4.01 mainboard, exposing a full-size ISO 7816 contact smart-card slot. It enables the Proxmark's RRG/Iceman firmware to interface with a real SIM- or SAM-format smart card for contact-chip operations the Proxmark's contactless RF frontend cannot do alone - for example, the documented `hf iclass sam` command uses a genuine HID SAM inserted here to extract PACS data from an iCLASS card dump. It has no RF/RFID capability of its own - it is purely a contact-interface accessory.","honest_take":"This does nothing by itself and requires a Proxmark 3 RDV4/RDV4.01 host - it's purely an accessory, already tracked as bundled-in on the base RDV4.01 entry in this database, so only buy it separately if you have an older RDV4.0 without one. The bigger catch isn't the module (a cheap, simple contact-slot board) but what you put in it: a genuine HID SAM is not something sold to the general public, so most buyers will own the slot and never have a legitimate card to put in it - the module's real value is narrow and specific to researchers who already have vetted SAM access. Every RFID/NFC capability key below is 'no' for this exact reason: it has zero contactless capability, that all belongs to the host RDV4.","aliases":[],"capabilities":{"lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","mifare_desfire":"no","nfc_type4_ndef":"no","emv_read":"no","iso15693":"no","felica":"no","magspoof":"no","nfc_relay":"no","sd_logging":"no","scriptable":"addon","web_ui":"no","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"The extension module itself - an empty ISO 7816 contact slot - is legal to own everywhere the Proxmark3 is."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"n/a","abandoned_risk":"low"}},{"id":"proxmark-5","hardware_id":"proxmark-5","name":"Proxmark 5","firmware":"Iceman (RfidResearchGroup)","firmware_kind":"community","vendor":"RFID Research Group (RRG / Proxgrind)","category":"rfid-nfc","subcategory":"rfid-research-platform","status":"available","price_usd":355.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Same command-line workflow as a Proxmark3 - hundreds of commands, minimal hand-holding.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"The first genuine hardware generation change in the Proxmark line: an AT32F435 at 288 MHz with a GOWIN FPGA replacing the Proxmark3's ARM+Spartan design, hot-swappable antennas with dynamic power control, a 10-bit ADC and a modular back. RRG crowdfunded it on Indiegogo and markets tri-band coverage (LF 125-500 kHz, HF 13.56 MHz and UHF 860-960 MHz), on-board Wi-Fi/BLE and cooperative use with a Flipper Zero.","honest_take":"Read the reseller's own warning before buying: the firmware is pre-release and Lab401 openly recommends the Proxmark3 RDV4.01 if you need something that just works today. The UHF and wireless claims also do not line up cleanly - the manufacturer site says Wi-Fi and BLE are built in while the reseller sells a EUR 99 wireless-plus-battery module, and 'UHF ready' has been phrased as a future capability elsewhere. The Proxmark3 has fifteen years of community scripts and Iceman commands behind it; the Proxmark5 is buying into a transition.","released":"2025","aliases":["PM5","Proxmark5"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"yes","mifare_classic_attacks":"yes","mifare_desfire":"partial","iso15693":"yes","nfc_relay":"claimed","standalone_untethered":"partial","scriptable":"yes","subghz_rx":"claimed","ble_scan":"claimed"},"legal":{"risk_level":"medium","notes":"Owning RFID research hardware is legal in most countries."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-09","app_store":"No - Iceman client with scripting","abandoned_risk":"low"}},{"id":"proxmark5-wireless-battery-module","hardware_id":"proxmark5-wireless-battery-module","name":"Proxmark 5 - Wireless + Battery Module","firmware_kind":"n/a","vendor":"RFID Research Group (ProxGrind)","category":"rfid-nfc","subcategory":"proxmark-accessory","status":"available","price_usd":110.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Installation is a two-minute drop-in fit, but the Proxmark 5 platform it attaches to runs pre-release firmware the maintainers themselves call unstable - this is not a beginner-friendly combination.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"The official wireless/battery add-on for the newer Proxmark 5 platform, adding BLE and WiFi plus an internal battery so the reader can run untethered and phone-driven in the field. Two modules can be paired for a wireless relay audit - one unit reads a card, the second opens a door - directly from two Proxmark 5 units.","honest_take":"The vendor's own listing carries a real warning: it ships with 'pre-release firmware' and is 'currently unsupported', with Lab401 explicitly recommending the Proxmark 3 RDV4.01 instead if you need stable, out-of-the-box functionality. This is early-adopter hardware for a next-generation platform that has not yet matured, not a safe default purchase - the RDV4.01's Blue Shark module (also in this batch) is the proven equivalent for anyone who actually needs a working tool today. The two-device wireless-relay capability (one unit reads, a second opens the door) is a genuinely new trick this module enables that the RDV4/Blue Shark combination does not do as directly, but it is only as reliable as the unstable firmware underneath it.","aliases":["PM5 Wireless Module"],"capabilities":{"hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","lf_125khz_read":"no","lf_125khz_write":"no","mifare_classic_attacks":"no","iso15693":"no","ble_scan":"claimed","wifi_ap_mode":"claimed","standalone_untethered":"yes","nfc_relay":"claimed","sd_logging":"unknown","web_ui":"unknown","scriptable":"no"},"legal":{"risk_level":"medium","notes":"A power/wireless accessory carries no legal exposure of its own beyond whatever applies to the RFID reading/cloning performed by the Proxmark 5 host it is attached to."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"proxmark3-easy-iceman","hardware_id":"proxmark3-easy","name":"Proxmark3 Easy","firmware":"Iceman (RfidResearchGroup)","firmware_kind":"community","vendor":"No single vendor - numerous Chinese OEMs (kkmoon, PiSwords, Radiowar, Ryscorp and unbranded)","category":"rfid-nfc","subcategory":"rfid-research-platform","status":"available","price_usd":92.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Same command line as an RDV4 with none of the safety rails: you must verify your own flash size, tune your own expectations about read range, and keep firmware and client versions in lockstep or commands silently return wrong answers.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"The commodity Chinese Proxmark3, descended from the RDV3 design: same AT91SAM7S ARM and Spartan-II FPGA architecture as an RDV4, with the HF antenna etched into the mainboard and the LF antenna on brass standoffs. Running the Iceman firmware it does most of what an RDV4 does at a quarter of the price. What you give up is hardware, not software.","honest_take":"Hardware revision roulette is the real problem. Two boards sold as 'Proxmark3 Easy' can have different ARM parts, and the difference is not cosmetic: the Iceman repo now requires 512KB, so a 256KB board makes you compile away entire protocol families to fit. On top of that the antennas are untuned and stamped into the PCB, so read range is visibly shorter than a tuned RDV4; there is no external SPI flash, so on-device key dictionaries and several standalone modes simply do not exist; there is no SIM/SAM slot, so the HID-SAM-based 'hf seos pacs' and 'hf iclass sam' PACS extraction is off the table entirely; and there is no battery unless you buy a shield. If you are learning, or you want a beater you will not cry over, this is the right buy. If you are billing for the results, the RDV4's tuned antennas and SAM slot are what you are actually paying for.","released":"2016","aliases":["Proxmark3 Easy V3","PM3 Easy","RDV3 Easy","Chinese Proxmark","Proxmark3 Easy V5"],"capabilities":{"lf_125khz_read":"partial","lf_125khz_write":"yes","lf_125khz_emulate":"yes","hf_1356_read":"partial","hf_1356_write":"yes","hf_1356_emulate":"yes","mifare_classic_attacks":"yes","mifare_desfire":"partial","nfc_type4_ndef":"yes","emv_read":"partial","iso15693":"yes","felica":"partial","standalone_untethered":"partial","sd_logging":"no","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Same position as any Proxmark3: owning one is legal in most countries, using it against credentials you are not authorised to use is not."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-04","app_store":"No - shares the Iceman script collection","abandoned_risk":"medium"}},{"id":"proxmark3-easy-vendor","hardware_id":"proxmark3-easy","name":"Proxmark3 Easy","firmware":"Vendor stock","firmware_kind":"stock","vendor":"No single vendor - numerous Chinese OEMs (kkmoon, PiSwords, Radiowar, Ryscorp and unbranded)","category":"rfid-nfc","subcategory":"rfid-research-platform","status":"available","price_usd":92.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"Not because the stock firmware is powerful, but because diagnosing it is: when firmware and client versions do not match, commands do not error, they return wrong readings. You need enough experience to recognise a plausible-looking wrong answer.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"The same Proxmark3 Easy board as it arrives from the seller, running whatever firmware and client the OEM bundled. Listed separately because a meaningful number of buyers never reflash, and then judge the Proxmark platform on this.","honest_take":"This is the single most common reason people conclude 'my Proxmark is broken'. The bundled firmware and the bundled client are frequently from different versions, and a version mismatch on a Proxmark does not throw an error - it silently returns garbage that looks like data. Add a GUI wrapper that is often Chinese-only and undocumented, and you have a device that appears to work while giving you wrong answers. There is no upside to keeping it: the stock build has no attack the Iceman build lacks. Flash it, then evaluate it.","released":"2016","aliases":["Proxmark3 Easy stock firmware","PM3 Easy out of the box"],"capabilities":{"lf_125khz_read":"unknown","lf_125khz_write":"unknown","hf_1356_read":"unknown","mifare_classic_attacks":"partial","mifare_desfire":"unknown","emv_read":"unknown","scriptable":"unknown"},"legal":{"risk_level":"medium","notes":"Identical to any other Proxmark3: legal to own in most countries, the offence is in unauthorised use."},"ecosystem":{"community":"dead","docs_quality":"none","last_release":null,"app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"proxmark3-rdv4-iceman","hardware_id":"proxmark3-rdv4","name":"Proxmark3 RDV4.01","firmware":"Iceman (RfidResearchGroup)","firmware_kind":"community","vendor":"RFID Research Group (ProxGrind)","category":"rfid-nfc","subcategory":"rfid-research-platform","status":"available","price_usd":355.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Command-line only, and the client will happily let you run the wrong attack on the wrong card type all day. You need to know what protocol you are looking at before the tool helps you.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"The reference RFID research platform: an ARM microcontroller plus an FPGA that does the modulation and demodulation for both 125/134 kHz LF and 13.56 MHz HF in software. Because the radio is an FPGA rather than a fixed-function reader IC, it can talk to protocols nobody has written a driver for yet, sniff raw traffic between a card and a reader, and emulate cards at the bit level. It is the tool the published attacks are written against.","honest_take":"It does not break modern cards. There is no attack on this or any other device that recovers a MIFARE DESFire EV1/EV2/EV3 AES key, a MIFARE Plus SL3 key, or an iCLASS SE / SEOS credential from the card alone - the Proxmark's own documentation states flatly that for SE/SEOS 'there is no card-only attack vectors'. Essentially every 'watch me clone this badge' video is either LF 125 kHz (unauthenticated by design, trivial) or MIFARE Classic (cryptographically broken since 2008). What you are buying is the ability to find out which of those a site is actually using, and to work with raw protocol when it is neither.","released":"2018","aliases":["PM3","Proxmark 3 RDV4","RDV4.01","Proxmark3 RDV4.01"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"yes","hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"yes","mifare_classic_attacks":"yes","mifare_desfire":"partial","nfc_type4_ndef":"yes","emv_read":"partial","iso15693":"yes","felica":"partial","nfc_relay":"partial","standalone_untethered":"partial","sd_logging":"partial","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Owning a Proxmark3 is legal in most countries and it is standard equipment for physical-security consultants and biohackers."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-04","app_store":"No - in-repo Lua and Python script collection plus community cheat sheets","abandoned_risk":"low"}},{"id":"pwnagotchi","hardware_id":"pwnagotchi","name":"Pwnagotchi","firmware":"jayofelony fork (v2.9.5.8)","firmware_kind":"community","vendor":"Community project (evilsocket originally; jayofelony maintains)","category":"wifi","subcategory":"handshake-collector","status":"diy-only","price_usd":95.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flashing an image and editing a YAML config is the easy part; the hard part is that the Wi-Fi driver is a patched firmware blob (nexmon) tied to a specific kernel, so when something breaks you are debugging kernel modules on a headless Pi over USB gadget mode.","build_effort":"assembly","stealth":"discreet","form_factor":"pocket","summary":"A Raspberry Pi in a small case with an e-ink screen that walks around collecting WPA handshake material. It drives bettercap to capture PMKIDs and full or half WPA handshakes into PCAPNG files for later cracking with hashcat, and shows an animated face on the display reflecting what it is doing. Multiple units in range advertise their presence to each other using custom information elements in 802.11 beacons.","honest_take":"Two things people get wrong. First, the AI: the maintained fork removed it entirely - the maintainer's README says AI destabilised the Wi-Fi firmware, so it was cut for uptime and battery life. Even when present, it was reinforcement learning tuning channel-hop and dwell parameters, not anything that understood networks. Second, it does not crack anything. It collects handshake material; the actual cracking happens later on a real GPU, and if the target's password is not in your wordlist you get nothing at all. Add that most of what it captures is from networks you have no permission to touch, and the honest description is 'a Tamagotchi that generates hashcat homework'.","released":"2019","aliases":["Pwnagotchi","pwny","jayofelony pwnagotchi"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"yes","wifi_deauth_24":"partial","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_wardriving":"addon","wifi_evil_twin":"no","gps":"addon","sd_logging":"yes","web_ui":"yes","scriptable":"yes","standalone_untethered":"yes","cloud_c2":"partial"},"legal":{"risk_level":"high","notes":"Owning and building it is legal."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-08","app_store":"No app store, but a mature Python plugin ecosystem","abandoned_risk":"medium"}},{"id":"pwnagotchi-hat-hackergadgets","hardware_id":"pwnagotchi-hat-hackergadgets","name":"Pwnagotchi Hat (UPS/GPS/AC WiFi/USB Hub/RTC)","firmware_kind":"n/a","vendor":"Hacker Gadgets","category":"wardriving","subcategory":"raspberry-pi-hat","status":"out-of-stock","price_usd":74.5,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"You still need to source a Pi Zero, flash a Pwnagotchi image yourself, and configure it — the hat has no setup wizard or onboarding of its own.","build_effort":"assembly","stealth":"discreet","form_factor":"hat-shield","summary":"A Raspberry Pi Zero expansion board that bundles the specific hardware Pwnagotchi needs to run standalone: a dual-band MediaTek MT7612U USB WiFi chipset (the vendor states it is the same chipset as Alfa's AWUS036ACM, independently confirmed via a third-party listing), a USB-serial GPS module with PPS output, a UPS circuit for an optional 18650 cell, an internal 4-port USB hub, and a battery-backed RTC. It is bare hardware only — you provide the Pi Zero and flash Pwnagotchi's own OS image yourself.","honest_take":"This is an integration convenience, not new capability: every function on this hat exists separately for less (an MT7612U dongle, a USB GPS puck, an RTC module, a USB hub), and Pwnagotchi itself is free, open-source software that has never shipped pre-installed on any commercial product, per its own install docs. What the ~$75 buys is not having to wire four separate peripherals into a Pi Zero's single USB port and GPIO header, plus a UPS so the unit survives being carried around. It ships as a bare board — no Pwnagotchi pre-installed, no Pi included, no SD card slot of its own (it rides on the Pi's) — budget extra money and 30-60 minutes of flashing and config before it does anything, and don't mistake 'purpose-built for Pwnagotchi' on the product page for 'comes with Pwnagotchi.'","aliases":["Pwnagotchi UPS/GPS/AC WiFi/USB Hub/RTC Hat","Pwnagotchi All-in-One Hat"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"claimed","wifi_injection":"claimed","wifi_deauth_24":"claimed","wifi_handshake_capture":"claimed","wifi_wardriving":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"no","ble_scan":"no","bt_classic":"no","subghz_rx":"no","hf_1356_read":"no","lf_125khz_read":"no","standalone_untethered":"yes","scriptable":"yes","web_ui":"unknown"},"legal":{"risk_level":"medium","notes":"Owning the hardware is legal everywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No — not applicable; runs whatever OS you flash onto the Pi Zero, most commonly Pwnagotchi (a separately tracked project with its own ecosystem)","abandoned_risk":"medium"}},{"id":"quadrf","hardware_id":"quadrf","name":"QuadRF","firmware":"Stock (Scale RF)","firmware_kind":"stock","vendor":"Scale RF","category":"sdr","subcategory":"mimo-direction-finding-tile","status":"available","price_usd":549.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Coherent MIMO direction-finding, beamforming calibration, and GNU Radio/SDRangel integration assume real RF and DSP background, not just SDR-hobbyist level.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A 4-element coherent MIMO SDR tile built around a Lattice ECP5 FPGA and discrete Skyworks RF front-end (not an AD9361-class integrated transceiver), which measures arrival-time differences across its four patch antennas to render a real-time AR overlay of RF sources at 30fps on a phone/laptop, streaming over a Raspberry Pi 5.","honest_take":"The 'RF camera that sees Wi-Fi through walls' framing describes real direction-finding math, but the hardware only covers 4.9-6.0GHz C-band - it cannot tune to sub-GHz garage remotes, 900MHz ISM devices, or anything outside that narrow slice, so 'sees hidden wireless cameras' really means 'sees Wi-Fi-band and similar C-band emitters,' not arbitrary RF. It's built from discrete Skyworks mixers/PAs/LNAs rather than a general-purpose wideband transceiver chip, with an 8+8-bit I/Q ADC (7-bit effective when beamforming) - respectable for direction-finding, not exceptional for general SDR work. It's also not a standalone device: it needs its own Raspberry Pi 5 to function, so the effective price includes that dependency even in kit form.","released":"2026","aliases":[],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"yes","sdr_full_duplex":"yes","wifi_scan_24":"no","wifi_monitor_mode":"no","gps":"no","scriptable":"yes","standalone_untethered":"no","ble_scan":"no","packet_capture":"no","web_ui":"claimed"},"legal":{"risk_level":"low","notes":"Passive RX and the tile's TX capability both sit in bands (4."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026","app_store":"No","abandoned_risk":"low"}},{"id":"rabbit-labs-flux-capacitor","hardware_id":"rabbit-labs-flux-capacitor","name":"Rabbit-Labs Flux Capacitor (Amplified CC1101)","firmware_kind":"n/a","vendor":"Rabbit-Labs","category":"accessory","subcategory":"flipper-subghz-board","status":"available","price_usd":58.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Physically plug-and-play, but you must switch the Flipper to the external radio, and you must understand that an amplified TX has legal consequences the internal radio does not.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A Flipper Zero GPIO board carrying an Ebyte E07-433M20S module - a CC1101 with an integrated power amplifier and low-noise amplifier - on a low-noise 5 V regulated supply with an SMA antenna. It replaces the Flipper's internal sub-GHz radio for both receive and transmit, raising rated TX from the CC1101's +12 dBm maximum to +20 dBm and adding an LNA on receive.","honest_take":"Two hard truths. One: the amplifier is band-locked. The E07-433M20S is specified 425-450.5 MHz, so this board is a 433 MHz device - at 315 MHz, 868 MHz or 915 MHz the PA and matching network are out of band and you are worse off than the Flipper's stock radio, not better. Two: the extra power is the legally dangerous part. In the US, 433 MHz consumer remotes operate under FCC Part 15.231, which caps field strength at roughly 11 mV/m at 3 m and forbids continuous transmission; +20 dBm into a gain antenna is far outside that, and 433.05-434.79 MHz overlaps the 70 cm amateur band, where unlicensed transmission is separately prohibited. Ten dB is also only about 3x the range in free space, not the kilometres the module's marketing implies - that figure assumes 5 dBi antennas at 2.5 m height in open ground at 1.2 kbps, not a jammer-in-a-pocket scenario.","released":"2024","aliases":["Flux Capacitor","RL Flux Capacitor","Amplified CC1101 board"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_amplified":"yes","subghz_external_antenna":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_bruteforce":"partial"},"legal":{"risk_level":"high","notes":"This is the highest-risk item in this batch."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"n/a - uses the Flipper's built-in Sub-GHz app and community FAPs","abandoned_risk":"low"}},{"id":"rabbit-labs-original-ir-blaster","hardware_id":"rabbit-labs-original-ir-blaster","name":"Rabbit-Labs IR Blaster (Original, 7-LED)","firmware_kind":"n/a","vendor":"Rabbit-Labs","category":"accessory","subcategory":"flipper-ir-board","status":"available","price_usd":45.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Plug-and-play with official Flipper firmware - no GPIO setting changes or unofficial firmware needed, unlike Rabbit-Labs' pricier Masta-Blasta.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A 7-LED infrared blaster add-on for the Flipper Zero, the budget tier of Rabbit-Labs' IR lineup. Vendor claims it can reach any device within line of sight, and unlike the pricier Masta-Blasta it works with the Flipper's official, unmodified firmware.","honest_take":"This is the cheapest of Rabbit-Labs' three IR boards and the only one of the three that needs zero firmware changes - Masta-Blasta needs unofficial firmware and GPIO tweaks, Slim Shady is a wide-flood design at a higher price. Vendor's '100 meters depending on room conditions' range claim is unverified and almost certainly best-case line-of-sight in a dark room; treat it as marketing until independently measured. Like every board in this category, it's LEDs and a resistor network, not silicon - you're paying for convenience and a tidy form factor, not technology.","aliases":["The Original IR Blaster by Rabbit-Labs","IR Blaster"],"capabilities":{"ir_tx":"yes","ir_flood":"no","ir_universal_remote":"yes","ir_rx":"no","ir_learn":"no","standalone_untethered":"no","scriptable":"no","usb_mass_storage":"no","web_ui":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"Infrared remote control is unregulated as radio spectrum."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"n/a - uses the Flipper's built-in Infrared app","abandoned_risk":"low"}},{"id":"rabbit-labs-masta-blasta","hardware_id":"rabbit-labs-masta-blasta","name":"Rabbit-Labs Masta-Blasta (IR Blaster)","firmware_kind":"n/a","vendor":"Rabbit-Labs","category":"accessory","subcategory":"flipper-ir-board","status":"available","price_usd":49.95,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Requires enabling GPIO 5V output and, per Hacker Warehouse's own listing, unofficial firmware with the Debug IR feature enabled - not plug-and-play with stock firmware the way the cheaper 'Original IR Blaster' is.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A 12-LED high-intensity infrared blaster board for the Flipper Zero GPIO header, designed for a tight, long-throw beam so you can hit a device across a room without aiming precisely. It's Rabbit-Labs' mid/high-power tier, sitting between their cheaper 7-LED 'Original IR Blaster' and their wide-angle-flood 'Slim Shady' board.","honest_take":"Same story as every powered IR add-on in this niche: it is a resistor-and-LED array, not a chip - the $50 buys Rabbit-Labs' thermal design and focused-beam optics, not silicon. It also needs GPIO 5V mode enabled and, per the vendor's own listing, unofficial firmware with Debug IR turned on, which the cheaper 7-LED 'Original IR Blaster' explicitly does not require ('works out-of-the-box with official firmware'). If you don't want to touch GPIO settings or flash unofficial firmware, the cheaper board is the easier buy; if you specifically want a tight, long-range 'throw' beam rather than wide flood coverage, this is the one in the Rabbit-Labs lineup built for that.","aliases":["Masta-Blasta","MastaBlasta IR Blaster"],"capabilities":{"ir_tx":"yes","ir_flood":"no","ir_universal_remote":"yes","ir_rx":"no","ir_learn":"no","standalone_untethered":"no","scriptable":"no","usb_mass_storage":"no","web_ui":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"Infrared remote control is unregulated as radio spectrum."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"n/a - uses the Flipper's built-in Infrared app","abandoned_risk":"low"}},{"id":"rabbit-labs-multi-pass-magspoof","hardware_id":"rabbit-labs-multi-pass-magspoof","name":"Rabbit-Labs Multi Pass MagSpoof Flipper Board","firmware_kind":"n/a","vendor":"Rabbit-Labs","category":"accessory","subcategory":"flipper-magstripe-board","status":"available","price_usd":30.85,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The board is simple, but the app is a work in progress that often has to be compiled yourself, and getting a reliable swipe is a matter of practised technique.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A credit-card-thin PCB carrying an H-bridge, two large capacitors and a coil, based on Samy Kamkar's MagSpoof. Attached to a Flipper Zero it generates a changing magnetic field that a magnetic-stripe reader head interprets as a card being swiped, letting you replay previously captured track data. Its practical selling point over the Flipper's internal-TX hack is that it does not risk damaging the Flipper's own radio hardware.","honest_take":"This is a legacy attack that gets less useful every year, and the board cannot read anything - it only replays track data you already have, in a format you had to obtain some other way. Against modern payment it is essentially dead: EMV chip and contactless generate a per-transaction cryptogram, so a cloned magstripe fails, and US merchants have been chip-liable since 2015. Where it still works is old, dumb readers - hotel door locks, gym and arcade cards, some parking and access badges, and time clocks - which is genuinely a real physical-red-team niche, just a much narrower one than the word 'MagSpoof' suggests. Also budget for frustration: the app the vendor points you at is openly described as buggy, and upstream magspoof_flipper has not had a code push since April 2025.","released":"2023","aliases":["Multi Pass","MagSpoof board","RL Multi Pass"],"capabilities":{"magspoof":"yes","lf_125khz_read":"no","hf_1356_read":"no","emv_read":"no"},"legal":{"risk_level":"high","notes":"The hardware is a coil and an H-bridge and is not itself restricted."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"2025-04","app_store":"Yes - magspoof is on Flipper Lab, but the vendor recommends the HummusSec fork which usually needs compiling","abandoned_risk":"medium"}},{"id":"rabbit-labs-poltergeist","hardware_id":"rabbit-labs-poltergeist","name":"Rabbit-Labs Poltergeist 5GHz Wi-Fi Board","firmware":"GhostESP (Revival)","firmware_kind":"community","vendor":"Rabbit-Labs","category":"accessory","subcategory":"flipper-wifi-board","status":"available","price_usd":145.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plugs onto the GPIO header and is pre-flashed, but everything useful happens in GhostESP menus that assume you know what a beacon frame and a deauth are.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An ESP32-C5 expansion board for the Flipper Zero, notable mainly because the C5 is Espressif's first dual-band part, so this is one of the few Flipper add-ons that can actually see and attack 5 GHz Wi-Fi. It also carries a high-output 940 nm IR blaster, an OLED status screen and a microSD slot, and can be driven either from the Flipper over UART or standalone over USB-C.","honest_take":"The genuinely new thing here is the ESP32-C5's 5 GHz radio; the rest is a well-built carrier board for firmware someone else writes for free. At ~$146 you are paying roughly ten times the cost of a bare ESP32-C5 dev board for the Flipper form factor, the IR section and Rabbit-Labs' QC. Also note that deauth on 5 GHz is increasingly a dead end: any network with 802.11w/PMF enabled (mandatory on WPA3, common on modern WPA2 gear) simply ignores the frames.","released":"2026","aliases":["Poltergeist","RL Poltergeist","Poltergeist C5"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"partial","wifi_beacon_spam":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"partial","wifi_ap_mode":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_advertise":"yes","detect_airtag":"partial","detect_flipper":"partial","ir_tx":"yes","ir_rx":"yes","sd_logging":"yes","standalone_untethered":"yes","gps":"addon","subghz_tx":"no"},"legal":{"risk_level":"medium","notes":"Owning the board is unremarkable."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2026-09","app_store":"No - firmware features come from GhostESP; the Flipper side uses the GhostESP companion FAP","abandoned_risk":"medium"}},{"id":"rabbit-labs-ghost-board","hardware_id":"rabbit-labs-ghost-board","name":"Rabbit-Labs RL Ghost Board (ESP32-C6)","firmware":"GhostESP","firmware_kind":"community","vendor":"Rabbit-Labs","category":"accessory","subcategory":"flipper-wifi-board","status":"available","price_usd":74.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug and play physically, but the GhostESP menus expect you to already understand APs, stations, deauth and captive portals.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An ESP32-C6 carrier board for the Flipper Zero, pre-flashed with GhostESP, with an SD slot, three RGB status LEDs and an expansion header for GPS or another ESP32. It gives a Flipper 2.4 GHz Wi-Fi and BLE attack and capture tooling that the Flipper's own STM32WB radio cannot do.","honest_take":"Underneath, this is an ESP32-C6 module - about $6-10 in single quantities, or $15-20 as a finished dev board - on a Flipper-shaped PCB with an SD slot and three RGB LEDs, running firmware written by volunteers. That is a real convenience and Rabbit-Labs' build quality is well reviewed, but $75 is mostly form factor, assembly and brand. Note also the ESP32-C6 is 2.4 GHz only: it cannot see or touch 5 GHz networks, which is where most modern traffic lives. And the 'AirTag detector' and 'Flipper detector' features are BLE advertisement pattern-matching, not tracking-hardware detection.","released":"2025","aliases":["RL Ghost Board","Ghost Board","SpookyESP","GhostESP board"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"addon","wifi_ap_mode":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_advertise":"yes","detect_airtag":"partial","detect_flipper":"partial","detect_generic_ble":"yes","gps":"addon","sd_logging":"yes","standalone_untethered":"partial","zigbee":"unknown","subghz_tx":"no"},"legal":{"risk_level":"medium","notes":"The board itself is a plain ESP32 carrier and is not restricted anywhere we found."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No - features come from GhostESP; the Flipper side uses the GhostESP companion FAP","abandoned_risk":"medium"}},{"id":"rabbit-labs-slim-shady","hardware_id":"rabbit-labs-slim-shady","name":"Rabbit-Labs The Slim Shady (IR Blaster)","firmware_kind":"n/a","vendor":"Rabbit-Labs","category":"accessory","subcategory":"flipper-ir-board","status":"available","price_usd":59.99,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Push it onto the GPIO header, set Infrared > GPIO Settings > Signal Output to Detect and 5V on GPIO to Auto. That is the whole setup.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A passive infrared LED array that plugs onto the Flipper Zero's GPIO header and replaces the Flipper's single weak IR LED with a wide-angle flood of high-output 940 nm emitters. It is a range-and-coverage upgrade for the Flipper's existing Infrared app: universal-remote work, TV-B-Gone style sweeps, and hitting several devices in a room at once.","honest_take":"Two things to be clear about. First, this is a resistor-and-LED board with no chip on it - $60-$86 buys you Rabbit-Labs' thermal design, hand assembly and the credit-card-slim form factor, not silicon. Second, the IR flood is for consumer remote-control protocols, not for blinding security cameras: these LEDs emit 38 kHz-modulated pulse trains a few milliseconds long, most surveillance cameras run an IR-cut filter in daylight and auto-exposure at night, and even if you did bloom the sensor you would produce an obvious white glare that reads as deliberate tampering. Treat 'IR flood' as 'wider remote coverage', not as camera defeat.","released":"2023","aliases":["Slim Shady","Slim Shady IR Blaster","RL Slim Shady"],"capabilities":{"ir_tx":"yes","ir_flood":"yes","ir_universal_remote":"yes","ir_rx":"no"},"legal":{"risk_level":"low","notes":"Infrared remote control is unregulated as radio spectrum."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"n/a - uses the Flipper's built-in Infrared app","abandoned_risk":"low"}},{"id":"ragnar","hardware_id":"ragnar","name":"Ragnar","firmware":"Ragnar (PierreGode)","firmware_kind":"diy","vendor":"Community project (PierreGode)","category":"network-implant","subcategory":"network-assessment-suite","status":"diy-only","price_usd":70.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Much larger surface than Bjorn - threat-intelligence feeds, SIEM integration, Docker, optional ZAP - so you need to be comfortable with Linux service administration, not just following an install script.","build_effort":"assembly","stealth":"discreet","form_factor":"pocket","summary":"A Raspberry Pi network assessment suite that began as a Bjorn fork and has since expanded well past it: host discovery and vulnerability scanning, Wi-Fi spectrum analysis, GPS wardriving, passive monitoring, asset inventory, SIEM integration, and threat-intelligence correlation against CISA KEV, NVD CVE, AlienVault OTX and MITRE ATT&CK. It runs standalone on a handheld, meshed across several units, or as a Docker container on a server.","honest_take":"First, correct the record: several forks describe Ragnar as 'the Father of Bjorn'. It is the other way round - Bjorn's repo was created in June 2024, Ragnar's in November 2025, and Ragnar's own README calls itself a fork of Bjorn. Second, note the direction of travel. Ragnar has been pulling away from the Tamagotchi-attacker genre toward network verification, monitoring and troubleshooting, which makes it more genuinely useful and much less of a toy - but it also means the heavier features want more machine than a Pi Zero 2 W has, and the project's own docs suggest 8GB+ RAM for ZAP. Treat the Pi build as the portable sensor and expect the serious analysis to happen elsewhere. Also: 2,840 commits in ten months against one open issue is fast movement with little external review, so pin a version rather than tracking main.","released":"2025","aliases":["Ragnar Pi","PierreGode Ragnar","Runar (fork)","Ragnar_Bjorn (fork)"],"capabilities":{"packet_capture":"yes","wifi_scan_24":"yes","wifi_scan_5":"partial","wifi_wardriving":"addon","gps":"addon","usb_exfil":"partial","web_ui":"yes","scriptable":"yes","cloud_c2":"partial","sd_logging":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"The monitoring, inventory and threat-intel features are benign."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No","abandoned_risk":"medium"}},{"id":"rainbow-tables-hdd-hackerwarehouse","hardware_id":"rainbow-tables-hdd-hackerwarehouse","name":"Rainbow Tables HDD","vendor":"Hacker Warehouse","category":"accessory","subcategory":"precomputed-hash-dataset","status":"available","price_usd":190.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Using the tables requires separate cracking software (e.g. RainbowCrack, Ophcrack, or coWPAtty/cowpatty-format tools); none is confirmed included.","build_effort":"assembled","stealth":"overt","form_factor":"box","summary":"A 2TB USB 3.0 external hard drive preloaded with precomputed rainbow/lookup tables for cracking A5/1 (GSM voice encryption), LM hashes, WPA-PSK (1 million words across 1000 preselected SSIDs), and two MD5 variants. The drive itself is generic storage; the only product here is the dataset that's already copied onto it.","honest_take":"This is a generic 2TB USB drive plus files that have been freely downloadable for over a decade — the WPA-PSK set matches the well-known Church of WiFi tables (172,000-1,000,000 words x 1000 SSIDs, originally distributed as 7-33GB torrents by RenderLab since the 2000s). You're mostly paying $190 to skip the download and get it on a drive already, which is a real convenience but not a unique dataset. The WPA-PSK tables only work if your target's SSID happens to be one of the 1000 baked in — because WPA-PSK's key derivation salts with the SSID, a rainbow table only pays off per-SSID, so this is close to useless against an uncommon or custom network name. For WPA cracking specifically, modern practice has largely moved to GPU-accelerated hashcat brute-forcing and PMKID attacks rather than precomputed tables, and A5/1 rainbow tables target 2G GSM voice/SMS, a niche and largely superseded attack surface today.","aliases":[],"capabilities":{"usb_mass_storage":"yes","wifi_ap_mode":"no","cloud_c2":"no","scriptable":"no","standalone_untethered":"no","sd_logging":"no","usb_hid_inject":"no","usb_keylogger":"no"},"legal":{"risk_level":"medium","notes":"Owning precomputed hash tables and a hard drive is legal."},"ecosystem":{"community":"commercial","docs_quality":"poor","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"raspyjack","hardware_id":"raspyjack","name":"RaspyJack","firmware":"RaspyJack (7h30th3r0n3)","firmware_kind":"diy","vendor":"Community project (7h30th3r0n3)","category":"network-implant","subcategory":"lan-drop-box","status":"diy-only","price_usd":60.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"No soldering with a Zero 2 WH, but you must understand Linux networking, which USB Wi-Fi chipsets support injection, and how to recover a Pi that will not boot after an install script.","build_effort":"assembly","stealth":"discreet","form_factor":"pocket","summary":"An offensive network toolkit for a Raspberry Pi with a small joystick LCD HAT, styled after Hak5's Shark Jack and pager-format tools. You plug it into a LAN or attach a USB Wi-Fi adapter and drive 231 bundled payloads from the on-device joystick menu or a browser IDE: Nmap recon, ARP MITM and DNS spoofing, evil portals with 84 templates, Wi-Fi deauth and handshake hunting, Bluetooth attacks, and exfiltration over HTTP, DNS, Discord, SMB, FTP and Dropbox.","honest_take":"The single most important thing to get right is the Wi-Fi adapter, and the project's own recommendation list contains a trap. The TP-Link TL-WN722N is listed as 'v1' for a reason: only the original Atheros AR9271 version does monitor mode and injection, and essentially everything sold under that name today is a v2 or v3 with a Realtek RTL8188EUS that does not. Buy the wrong one and every Wi-Fi payload silently fails. Beyond that, the 231-payload count is impressive breadth but wildly uneven depth - 25 of them are games, and the security payloads range from genuinely useful to thin wrappers around a single command. It is also very new (repo created June 2025), so expect churn.","released":"2025","aliases":["Raspyjack","RaspyJack Pi"],"capabilities":{"packet_capture":"yes","ethernet_mitm":"yes","ethernet_tap_passive":"partial","wifi_scan_24":"yes","wifi_scan_5":"addon","wifi_monitor_mode":"addon","wifi_injection":"addon","wifi_deauth_24":"addon","wifi_deauth_5":"addon","wifi_handshake_capture":"addon","wifi_evil_twin":"addon","wifi_captive_portal":"addon","ble_scan":"yes","ble_spam_apple":"partial","usb_exfil":"yes","cloud_c2":"partial","web_ui":"yes","scriptable":"yes","sd_logging":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Nearly everything this device is for - ARP poisoning, DNS spoofing, credential portals, deauthentication, exfiltration - is unlawful against systems you do not own or have written permission to test, under the CFAA in the US, the Computer Misuse Act in the UK and equivalents elsewhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No, but a large bundled payload library and an in-browser payload IDE","abandoned_risk":"medium"}},{"id":"rayhunter-orbic","hardware_id":"rayhunter","name":"Rayhunter (on Orbic RC400L)","firmware":"Rayhunter","firmware_kind":"community","vendor":"Electronic Frontier Foundation (software) / Orbic (hardware)","category":"detection-defense","subcategory":"imsi-catcher-detector","status":"diy-only","price_usd":40.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"One installer script over USB; EFF deliberately targets non-technical users at risk of surveillance.","build_effort":"flash-only","stealth":"discreet","form_factor":"pocket","summary":"Free open-source software that turns a cheap LTE hotspot into a cell-site-simulator (IMSI catcher / stingray) detector by reading the Qualcomm modem's diagnostic interface and applying heuristics for things like downgrade attempts and unusual identity requests. Roughly nine hotspot models are supported, with the Orbic RC400L the reference device in the Americas.","honest_take":"It detects behaviour consistent with a cell-site simulator; it cannot prove one is present, and a quiet or well-configured catcher can go unflagged. It watches only the band and carrier the hotspot is attached to, so it is a sampling instrument, not a shield - it does not protect your phone, it tells you the airspace looked wrong. The hardware side is a used consumer hotspot, so battery health and firmware build vary and behaviour genuinely differs between units.","released":"2025","aliases":["EFF Rayhunter","IMSI catcher catcher"],"capabilities":{"detect_generic_wifi":"no","packet_capture":"yes","web_ui":"yes","sd_logging":"partial","standalone_untethered":"yes","gps":"no"},"legal":{"risk_level":"low","notes":"Rayhunter only reads your own modem's diagnostic data - it transmits nothing extra and does not attack the network."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"rf-clown-v1","hardware_id":"rf-clown-v1","name":"RF-Clown v1","firmware":"RF-Clown v1.0.0","firmware_kind":"diy","vendor":"CiferTech (open-source project, no official vendor)","category":"bluetooth","subcategory":"24ghz-jammer","status":"diy-only","price_usd":35.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"One small PCB with a handful of SMD parts and two through-hole radio modules - simpler than the ESP32-DIV, but you still need to solder, flash, and understand why two transmitting nRF24s can brown out a badly decoupled 3.3V rail.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"The first RF-Clown: a small ESP32 board carrying two nRF24L01+ modules whose only job is to flood the 2.4GHz advertising and pairing channels used by BLE and Classic Bluetooth. There is no display - a NeoPixel tells you which of the three modes is running. It has been superseded by v2 and exists now mainly as a reference design.","honest_take":"This is a jammer with an educational README, and no amount of 'for testing and learning' framing changes what it is - in the US, operating it is flatly illegal under FCC rules, with no exception for hobbyists. Technically it is also weaker than the name implies: two nRF24s can only sit on a couple of 1MHz channels at a time, so it reliably breaks BLE advertising and pairing within a few metres but does far less to an established, frequency-hopping Bluetooth link. If you want to learn 2.4GHz RF rather than break it, the nRFBox from the same author does scanning and analysis too.","released":"2024","aliases":["RFClown","RF Clown v1"],"capabilities":{"ble_jam":"partial","nrf24_jam":"partial","bt_classic":"no","ble_scan":"no","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"This device has essentially one function and that function is illegal to operate in most of the world."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2024-12","app_store":"No","abandoned_risk":"medium"}},{"id":"rf-clown-v2","hardware_id":"rf-clown-v2","name":"RF-Clown v2","firmware":"RF-Clown v2.0.0","firmware_kind":"diy","vendor":"CiferTech (open-source project, no official vendor)","category":"bluetooth","subcategory":"24ghz-jammer","status":"diy-only","price_usd":55.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"A single-board SMD build with three radio modules to align and an OLED to wire; the hard part is power - three nRF24s transmitting at once will crash a board with thin traces or weak decoupling, which is exactly the bug the author had to fix in nRFBox.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"A full hardware redesign of RF-Clown: an ESP32-WROOM-32U with three GT24 mini nRF24 modules, external 8dBi antennas on IPEX pigtails, an OLED with three buttons for on-device navigation, and a NeoPixel status light. Its purpose is unchanged - flooding the 2.4GHz channels that BLE and Classic Bluetooth depend on.","honest_take":"More radios and 8dBi antennas make this meaningfully more disruptive than v1, and that is the problem: it is a better jammer, and jammers are illegal to operate in the US, UK and most of the EU with no hobbyist exemption. The 'testing and learning' framing in the README does not create a legal defence. Technically, be clear about what three nRF24s buy you - three simultaneous 1MHz channels of narrowband energy, not a wall of noise across the band; BLE advertising and pairing fall over quickly, established hopping links often limp on. There is no scanner, so you cannot see what you are affecting.","released":"2025","aliases":["RFClown v2","RF Clown 2"],"capabilities":{"ble_jam":"partial","nrf24_jam":"partial","bt_classic":"no","ble_scan":"no","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Single-purpose jamming hardware."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":"2025-10","app_store":"No","abandoned_risk":"medium"}},{"id":"rfgen44","hardware_id":"rfgen44","name":"RFGEN44","firmware":"Stock (CircuitValley)","firmware_kind":"stock","vendor":"CircuitValley","category":"accessory","subcategory":"rf-signal-generator","status":"preorder","price_usd":139.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Transmit-only, unfiltered RF source - useful mainly to people who already understand what they're generating and why, plus the legal constraints of doing so.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A small, USB-powered, driver-free RF signal generator built around an Analog Devices ADF4351 synthesizer and a Microchip PIC16 controller, producing an output tone anywhere from 35MHz to 4.4GHz in 10kHz steps, with adjustable amplitude and programmable frequency sweep/hop. It is a transmit-only signal source with no receive capability.","honest_take":"This is purely a test/signal source, not a transceiver - it has no receiver, no demodulation, and no ability to interact with an existing protocol beyond emitting a raw carrier at a chosen frequency. Despite being marketed as 'open source,' the license is Creative Commons Attribution-NonCommercial-NoDerivatives (CC BY-NC-ND), which blocks commercial use and modification/redistribution of derivative designs - meaningfully more restrictive than a typical open-hardware license (e.g. CERN-OHL or MIT), so don't assume you can freely build on or resell derivatives of this design. Output amplitude is modest (roughly -1dBm to +4dBm depending on frequency) and unfiltered straight off the synthesizer, so harmonic/spurious content should be assumed present unless you add your own filtering - treat it as a lab signal source, not a clean RF reference.","released":"2027","aliases":["RFSTAMP44 (castellated breakout variant)"],"capabilities":{"sdr_rx":"no","sdr_tx":"yes","sdr_bandwidth":"no","sdr_full_duplex":"no","scriptable":"yes","standalone_untethered":"no","app_store":"no","web_ui":"no","wifi_scan_24":"no","gps":"no","sd_logging":"no"},"legal":{"risk_level":"high","notes":"Owning a signal generator is legal."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"low"}},{"id":"rfid-detector-diagnostic-card-v2","hardware_id":"rfid-detector-diagnostic-card-v2","name":"RFID Detector / Diagnostic Card v2","firmware_kind":"n/a","vendor":"Generic/unbranded OEM (sold by Hacker Warehouse under SKU RRG-RD2)","category":"rfid-nfc","subcategory":"rfid-field-detector","status":"available","price_usd":25.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"No setup or configuration - hold it near a reader/terminal and observe which LED lights.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A battery-free, credit-card-sized detector potted in epoxy resin that lights one of three color-coded LEDs (red/green/blue) to indicate whether a nearby RFID/NFC reader is transmitting in the 125kHz LF, 13.56MHz HF, or 860-960MHz UHF band. It's powered entirely by rectifying the reader's own RF field, so there's nothing to charge, replace, or maintain. It is a genuinely single-purpose device - it does not read, write, clone, or emulate any tag - which is why almost every capability key below is an explicit 'no'.","honest_take":"This looks like a generic overseas OEM design rebranded by multiple security-tool resellers, not a Hacker Warehouse original - the same epoxy-card construction and near-identical marketing language shows up on RedTeamTools' 2-band card and MTools Tec's tri-band card, so you're likely paying a security-vendor markup on a commodity part available more cheaply elsewhere. It only tells you THAT a field is present and roughly which band - it can't identify the reader, log anything, measure range/power precisely, or distinguish a legitimate access-control reader from a hidden skimmer. Useful as a quick field-presence check during a physical pentest walkthrough; not a real skimmer detector.","aliases":["RFID Field Detector Card","RFID LF/HF/UHF Detector Card","SKU RRG-RD2"],"capabilities":{"detect_skimmer":"partial","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","mifare_desfire":"no","nfc_type4_ndef":"no","emv_read":"no","iso15693":"no","felica":"no","magspoof":"no","nfc_relay":"no","standalone_untethered":"yes","scriptable":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"Purely passive/receive-only device - it does not transmit, read, write, or store data, so owning and using it carries essentially no legal risk anywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"n/a","abandoned_risk":"low"}},{"id":"lab401-rfid-field-detector-ultra","hardware_id":"lab401-rfid-field-detector-ultra","name":"RFID Field Detector Ultra - LF/HF/UHF","firmware_kind":"n/a","vendor":"RRG / Proxgrind (design and manufacture); sold rebranded as 'Ultra' by Lab401","category":"rfid-nfc","subcategory":"Passive RF field-presence indicator (tri-band)","status":"available","price_usd":33.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"No setup - hold it near a reader and watch which LED lights.","build_effort":"assembled","stealth":"discreet","form_factor":"keychain","summary":"A completely passive, battery-free card that lights a red, green, or blue LED when it senses an active 125kHz (LF), 13.56MHz (HF), or 860-960MHz (UHF) RFID reader field, respectively, powered parasitically by the field itself. It has no read/write/clone capability of any kind - it only indicates that a field of a given band is present. This is a genuinely single-purpose device, which is why nearly every capability key below is an explicit 'no'.","honest_take":"This is RRG/Proxgrind's existing tri-band field-detector card resold by Lab401 under the 'Ultra' name - RRG sells the identical red/green/blue LF/HF/UHF card direct (via KSEC) for about the same price, and RRG also sells a cheaper LF/HF-only version ('Proxgrind RFID Field Detector', ~£20/$25 range) that this superseded. It genuinely is a real 3-band design (not just a rebadged 2-band card), which does distinguish it from the sea of $10-20 generic dual-band (LF/HF only) detector-card clones sold on Amazon under names like CHEOTIME, LICAEVEY, Tangxi, and EBTOOLS - but if you don't need UHF detection, one of those generic 2-band cards does the same core job for a fraction of the price. There's no capability key in this schema for 'passive field presence indicator' since it doesn't read or decode any tag data - that's the entirety of what it does.","aliases":["RRG RFID Field Detector (tri-band)"],"capabilities":{"lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","mifare_desfire":"no","nfc_type4_ndef":"no","emv_read":"no","iso15693":"no","felica":"no","magspoof":"no","nfc_relay":"no","sd_logging":"no","scriptable":"no","web_ui":"no","standalone_untethered":"yes"},"legal":{"risk_level":"low","notes":"It doesn't read, store, or write any tag data - it just lights an LED - so it doesn't touch unauthorized-access or card-cloning statutes anywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"n/a","abandoned_risk":"low"}},{"id":"rfid-hf-extender-pro","hardware_id":"rfid-hf-extender-pro","name":"RFID HF Extender Pro","firmware_kind":"n/a","vendor":"Midwest Gadgets","category":"rfid-nfc","subcategory":"passive-range-extender","status":"available","price_usd":65.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"No electronics knowledge required - it is two coils and a cable, placed by hand.","build_effort":"assembled","stealth":"covert","form_factor":"cable","summary":"Two coupled 13.56MHz HF/NFC antennas - one 60mm, one 27mm - joined by a 30cm IPEX cable. Placed one coil against a reader and the other where you actually want the card presented, the pair passively relays the reader's field (and the card's response) across the cable, physically repositioning where a badge needs to be tapped without moving the reader itself.","honest_take":"This sits right on the line the brief for this database explicitly excludes ('plain cables and antennas') - and functionally, that is almost exactly what it is: two passive coils and a cable, with no active circuitry, amplification or protocol handling anywhere in it. It works by simple magnetic coupling, not by decoding and re-transmitting a signal, so it is not a true active NFC relay attack tool (compare to a genuine two-device relay built from two SDRs or NFC readers with a network link between them, which can span arbitrary distances) - it only repositions a reader's existing field by the length of its 30cm cable. The single legitimate niche it fills is exactly what the vendor's own copy admits: freeing a reader from an awkward fixed mounting position during a physical test, not extending range or enabling a long-distance relay attack.","aliases":[],"capabilities":{"hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","nfc_relay":"partial","mifare_classic_attacks":"no","iso15693":"no","lf_125khz_read":"no","standalone_untethered":"no","scriptable":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"A passive antenna coupler is not itself restricted for ownership."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"rfid-hf-field-generator","hardware_id":"rfid-hf-field-generator","name":"RFID HF Field Generator","firmware_kind":"n/a","vendor":"Midwest Gadgets","category":"rfid-nfc","subcategory":"rfid-field-generator","status":"available","price_usd":25.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Press the momentary switch near a compatible HF/13.56MHz tag or implant - no setup required.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A coin-cell-powered 13.56MHz field generator, made by Midwest Gadgets and also resold via Hacker Warehouse, that energizes a passive HF/NFC tag without needing an actual reader present. Press the momentary switch and it radiates a weak 13.56MHz field for a few millimeters - enough to power the community-favorite Dangerous Things xSIID and xLED implants, or any other compliant loose HF tag, without touching it to a phone or reader. It does not read, write, or communicate with the tag in any way - it only supplies power, which is why every read/write/attack capability below is 'no'.","honest_take":"Contrary to a 'not primarily an implant tool' framing, it actually is: Midwest Gadgets' own product page frames it explicitly around powering the xSIID/xLED implants, and even states the V2 unit 'will only work with the HF 13.56MHz xLED implants.' Community reviews do show it also lighting up unimplanted diagnostic cards and xFD readers, so it will energize any compliant passive HF tag - but don't expect a general-purpose RFID-research bench tool. It's a proof-of-concept-grade hobbyist board (per the maker's own description), range is only a few millimeters, and the manufacturer's own store currently has it as pre-order-only.","aliases":["13.56MHz Field Generator","HF Field Generator"],"capabilities":{"hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","mifare_classic_attacks":"no","mifare_desfire":"no","nfc_type4_ndef":"no","emv_read":"no","iso15693":"no","felica":"no","magspoof":"no","nfc_relay":"no","standalone_untethered":"yes","scriptable":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"The field generator itself is a very low-power, short-range near-field coupler (similar in emission profile to a contactless payment terminal or phone's NFC radio) and isn't a licensed-spectrum transmitter - legal to own and use essentially everywhere."},"ecosystem":{"community":"active","docs_quality":"sparse","last_release":null,"app_store":"n/a","abandoned_risk":"low"}},{"id":"rfid-hf-repeater-large","hardware_id":"rfid-hf-repeater-large","name":"RFID HF Repeater Large","firmware_kind":"n/a","vendor":"Midwest Gadgets","category":"rfid-nfc","subcategory":"field-relay-accessory","status":"available","price_usd":20.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"It's a passive card-sized resonator - place it between the obstruction and the reader. No configuration, no firmware, no electronics knowledge needed.","build_effort":"assembled","stealth":"covert","form_factor":"pocket","summary":"A passive, unpowered 13.56MHz resonant coil in a 3x3 inch card, sold to relay a reader's HF field through an obstruction (a wallet, a bag, a thin door panel) and recover a few millimeters of lost read range. Hacker Warehouse's own listing quotes an example gain of 5-9mm of extra read distance; a same-technology competing product (Lab401's range booster line) claims up to double the read range on cards/fobs, which gives a sense of how wide the real-world variance is depending on target tag size and reader geometry.","honest_take":"This is a tuned LC resonator, not an amplifier - it has no battery and no active gain stage, so it cannot make a card readable from meters away or defeat a Faraday-shielded wallet; it only recovers some of the range an obstruction otherwise costs you, and how much (Hacker Warehouse quotes single-digit millimeters, a competing seller quotes up to 2x) depends entirely on how well its resonant frequency and coupling geometry happen to match your reader and card. For genuine long-range HF field manipulation (the kind used in real relay/ghost-and-leech attacks) you want an active repeater built from two coupled reader/emulator stages with real amplification, not a passive card like this one.","aliases":["RFID Field Repeater","HF Repeater Large"],"capabilities":{"hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","lf_125khz_read":"no","mifare_classic_attacks":"no","nfc_relay":"no"},"legal":{"risk_level":"low","notes":"A passive antenna accessory with no transmitter of its own - it does not generate RF energy, only relays an existing reader's field, so it isn't a separate radio device under most regulatory schemes."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"rfidetector","hardware_id":"rfidetector","name":"RFIDetector","firmware_kind":"n/a","vendor":"wh201906 (independent developer)","category":"rfid-nfc","subcategory":"field-detector","status":"diy-only","price_usd":15.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Small SMD passive/diode design - buildable by anyone comfortable hand-soldering fine-pitch parts, but you're fabricating the PCB yourself from KiCad files with no vendor to buy it assembled.","build_effort":"soldering","stealth":"covert","form_factor":"pocket","summary":"A small open-hardware PCB (CERN-OHL-S licensed) that indicates whether it is sitting in an active LF (125kHz) or HF (13.56MHz) RFID reader field. Direct inspection of the rev0.22 KiCad schematic shows it is a purely passive/analogue design - two tuned coils, nine 1N5819WS Schottky diodes for envelope detection on each band, and three status LEDs, with solder-jumper pads to select modes - not a microcontroller-based device.","honest_take":"This is a passive field-presence indicator, not a reader or a security scanner: it tells you 'something nearby is generating an LF or HF field,' not what protocol, what data, or whose reader it is. It has no microcontroller, no logging, and no way to distinguish a legitimate access-control reader from a skimmer or from your own Flipper Zero sitting in your pocket. With 3 GitHub stars and a single contributor it is effectively a personal project shared as open hardware, not a maintained product - expect to debug your own PCB order.","released":"2024","aliases":[],"capabilities":{"lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","iso15693":"no","felica":"no","standalone_untethered":"yes","scriptable":"no","sd_logging":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"A passive receive-only indicator with no transmitter and no data capture."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2024-03","app_store":"No","abandoned_risk":"high"}},{"id":"rfidler","hardware_id":"rfidler","name":"RFIDler","firmware":"RFIDler custom PIC32 firmware","firmware_kind":"stock","vendor":"Aperture Labs Ltd","category":"rfid-nfc","subcategory":"lf-sdr-platform","status":"diy-only","price_usd":102.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Using it means learning a CLI-driven LF protocol workflow, and getting one at all now likely means self-fabricating from the published Eagle files and hand-soldering a PIC32 board, since no vendor currently ships assembled units.","build_effort":"full-diy","stealth":"overt","form_factor":"board","summary":"RFIDler is Aperture Labs' (Adam Laurie) open-hardware, software-defined LF (125/134kHz) reader/writer/emulator built around a Microchip PIC32MX795F512L, controlled over a USB-serial CLI. Firmware source confirms real read, write and one-shot emulate (EMU command) support for a broad sweep of LF formats including EM4X02/4X05, HID Prox (HID26), Indala (64/224-bit), UNIQUE, HITAG1/2, Q5, T55x7, AWID26 and FDXB, with write support specifically for T55x7, Q5 and HITAG2. It has no HF hardware at all.","honest_take":"This is a decade-plus-old project: Aperture Labs' own store lists it at £80+VAT 'Currently OUT OF STOCK' with no restock date, and the last real firmware commit was September 2024 - treat it as effectively DIY-only now, buildable from the Eagle files in the repo rather than something you can simply order. It's also not standalone in the field: it needs a host PC/terminal over USB the entire time you're using it, unlike a Proxmark3 or Flipper Zero. If you can get or build one, the format coverage is genuinely broad for LF and the emulate command is real (confirmed directly in firmware source, not just marketing copy) - but a Proxmark3 or Flipper Zero will get a newcomer working today with far more active support.","released":"2013","aliases":["RFIDler v22"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"yes","lf_125khz_emulate":"yes","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","iso15693":"no","scriptable":"yes","standalone_untethered":"no","sd_logging":"no","web_ui":"no"},"legal":{"risk_level":"medium","notes":"RFIDler is an LF reader/writer/emulator capable of cloning and emulating common access-control formats (EM4100, HID Prox, Indala, etc."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2024-09","app_store":"n/a","abandoned_risk":"high"}},{"id":"rfquack","hardware_id":"rfquack","name":"RFQuack","firmware":"RFQuack","firmware_kind":"diy","vendor":"rfquack (open-source project / academic)","category":"subghz","subcategory":"scriptable-rf-firmware","status":"diy-only","price_usd":15.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You wire your own ESP32/Teensy to a CC1101/RF69/nRF24L01 module, flash the firmware yourself, and drive it from a Python shell - there is no packaged product or guided setup.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"An open-source, GPL-2.0 firmware (with an accompanying academic paper) that turns a user-wired ESP32 or Teensy plus a CC1101, RF69 or nRF24L01 radio module into a Python-scriptable RF sniff/analyze/transmit tool, in the same spirit as RfCat but supporting three different radio chips including 2.4 GHz via the nRF24L01.","honest_take":"This is a software project, not a device - there is nothing to buy, and the price in this database is a rough guess at the cost of one bare radio module, not a working tool. Its real comparison point is RfCat/YARD Stick One: RFQuack covers more radio chips (CC1101 and RF69 sub-GHz, plus nRF24L01 2.4 GHz in one framework) but has no equivalent to a pre-built, cased USB stick - you are entirely on your own for hardware, wiring and enclosure. Development has been quiet since its last commit in December 2024 (GitHub API rate-limited a precise 'last release' check during this research pass, but the commit date is confirmed), so expect an academic-project pace of support - it originated from a published research paper - rather than a maintained commercial product.","aliases":[],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_external_antenna":"unknown","nrf24_scan":"yes","nrf24_jam":"unknown","mousejack":"unknown","ble_jam":"no","packet_capture":"yes","scriptable":"yes","standalone_untethered":"no","app_store":"no","web_ui":"no"},"legal":{"risk_level":"high","notes":"As a general-purpose sub-GHz and 2."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2024-12","app_store":"No","abandoned_risk":"medium"}},{"id":"rpi0-usb-a-addon-hackerwarehouse","hardware_id":"rpi0-usb-a-addon-hackerwarehouse","name":"RPi0 USB-A Addon Board","vendor":"Hacker Warehouse","category":"accessory","subcategory":"usb-host-addon","status":"out-of-stock","price_usd":6.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Screws onto the Pi Zero's pogo pins; no soldering, but reviewers note the mounting screws need firm installation.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A $6 pogo-pin breakout board that gives a Raspberry Pi Zero (not included) a standard full-size USB-A port, marketed specifically for running Responder or building PoisonTap-style USB implants that otherwise need a micro-USB-to-USB-A adapter cable. Four spring-loaded pogo pins engage the Pi Zero's USB data/power test points on the underside of the board.","honest_take":"This is purely a physical connector — there is no silicon on it, no logic, and it does nothing by itself. It exists to save you from carrying a flaky micro-USB OTG adapter cable when building a Pi Zero implant. The entire capability of whatever you build comes from the software running on the attached Pi Zero (PoisonTap, Responder, Int3rcept0r, etc.), not from this board. It also isn't a Hacker Warehouse original: the identical 4-pogo-pin design and near-word-for-word 'Responder or PoisonTap type attacks' marketing copy shows up under at least three other brand names (REES52, ZeroKey, Geekworm) at a fraction of the price directly from overseas suppliers — you're paying roughly a 60% markup here for US-based stock and a matched screw-down fit, not for any unique engineering.","aliases":[],"capabilities":{"usb_mass_storage":"no","usb_ethernet_attack":"no","usb_hid_inject":"no","usb_exfil":"no","scriptable":"no","standalone_untethered":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"It is a passive USB connector adapter; owning and using it carries no legal risk on its own."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"rtl-sdr-generic-hackerwarehouse","hardware_id":"rtl-sdr-generic-hackerwarehouse","name":"RTL-SDR (Generic RTL2832U/R820T)","firmware_kind":"n/a","vendor":"Hacker Warehouse (reseller); OEM manufacturer not disclosed","category":"sdr","subcategory":"rx-only-dongle","status":"available","price_usd":40.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Same ten-minutes-to-first-signal experience as any RTL-SDR dongle.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A bare-bones RTL2832U+R820T USB dongle sold as a general-purpose SDR receiver, 24-1750 MHz (up to roughly 1.85 GHz in practice), officially marketed as a DVB-T/DAB/FM tuner repurposed for SDR use.","honest_take":"This is the no-frills version of the RTL-SDR story, and the seller's own page does not claim a TCXO or bias tee - features the RTL-SDR Blog V3/V4 and Hacker Gadgets' Mini dongle both advertise explicitly. Frequency stability will drift more with temperature without a TCXO, which matters for narrowband digital modes (POCSAG paging, some IoT protocols) more than for wideband work like ADS-B. At $40 this is not meaningfully cheaper than a documented, community-standard RTL-SDR Blog V3, so there is little reason to pick it over that one unless you specifically want Hacker Warehouse's own bundling.","aliases":["RTL-SDR DVB-T Dongle"],"capabilities":{"sdr_rx":"yes","sdr_tx":"no","sdr_bandwidth":"partial","subghz_rx":"yes","subghz_tx":"no","subghz_rolling_code":"no","subghz_external_antenna":"yes","gps":"partial","scriptable":"yes","wifi_scan_24":"no","ble_scan":"no","packet_capture":"partial","standalone_untethered":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"Receive-only; owning and using it is legal essentially everywhere, subject to the normal local caveats about intercepting cellular or other protected traffic."},"ecosystem":{"community":"active","docs_quality":"poor","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"rtl-sdr-blog-v4","hardware_id":"rtl-sdr-blog-v4","name":"RTL-SDR Blog V4","firmware":"Stock (RTL-SDR Blog driver)","firmware_kind":"stock","vendor":"RTL-SDR Blog","category":"sdr","subcategory":"rx-only-dongle","status":"discontinued","price_usd":38.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug it in, install SDR++ or SDRSharp, and you are listening in about ten minutes. There is no way to break anything or break the law with it.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A $40 receive-only USB software-defined radio covering roughly 500 kHz to 1.766 GHz, built on the RTL2832U demodulator with an R828D tuner and a built-in upconverter for HF. It is the entry point that the whole SDR hobby is built on, and it is the correct first purchase for almost everyone.","honest_take":"Buy this first. Seriously - if you are reading a comparison page trying to decide between a HackRF and something else, the honest answer is that you should spend $40 here and learn what a waterfall is before spending $330. It receives only: there is no transmit path, no DAC, no way to make it transmit, and that is a feature, not a limitation - it means you cannot accidentally commit a felony while learning. The real limits are the 8-bit ADC, the ~2.4 Msps of usable bandwidth, and the 1.766 GHz ceiling. Note also that the V4 specifically is now end-of-life; the V4L that replaced it uses a different tuner.","released":"2023","aliases":["RTL-SDR V4","RTL SDR Blog V4 dongle"],"capabilities":{"sdr_rx":"yes","sdr_tx":"no","sdr_bandwidth":"partial","sdr_full_duplex":"no","subghz_rx":"yes","subghz_tx":"no","gps":"partial","packet_capture":"partial","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"About as low-risk as security hardware gets, because it physically cannot transmit."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2025","app_store":"No - but the host software ecosystem (SDR++, SDRSharp, gqrx, rtl_433, dump1090, SDRangel) is the largest of any SDR","abandoned_risk":"low"}},{"id":"rtl-sdr-lora-gps-rtc-hat","hardware_id":"rtl-sdr-lora-gps-rtc-hat","name":"RTL-SDR/LoRa/GPS/RTC HAT for Raspberry Pi","firmware_kind":"n/a","vendor":"Hacker Gadgets","category":"sdr","subcategory":"multi-radio-hat","status":"preorder","price_usd":84.9,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Four separate radio subsystems each need their own host-side setup (librtlsdr, a Meshtastic/LoRa stack, gpsd) - nothing about it is plug-and-play beyond the physical HAT connection.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A Raspberry Pi HAT bundling a receive-only RTL2832U+R860 SDR tuner, a Semtech SX1262 LoRa radio (860-960 MHz with out-of-the-box Meshtastic support), a GNSS receiver, and a PCF85063A real-time clock with rechargeable coin-cell backup, aimed at turning a Pi into a self-contained spectrum-monitoring or mesh-relay station.","honest_take":"This is four fairly ordinary radio modules sharing one PCB, not a unified 'signals platform.' The SDR side is receive-only - no DAC, no transmit path, so despite living in this batch it cannot do any of the sub-GHz transmit/replay/jamming work people associate with RF security gadgets. Its R860 tuner is functionally identical to the R820T2 found in $25 dongles (Rafael Micro simply renamed the die when R820T2 was formally discontinued) - it is not the three-port R828D used on the RTL-SDR Blog V4, and the advertised '100 kHz-28.8 MHz HF direct sampling' is the standard RTL2832U direct-sampling trick (bypassing the tuner entirely), not a dedicated HF upconverter, so expect the weaker sensitivity that comes with it. The LoRa and GPS/RTC sides are conventional and fine for a Meshtastic node. At $84.90 for four bundled radios you are paying hobbyist prices for hobbyist-grade parts; the appeal is integration and one shared enclosure, not superior performance versus buying an RTL-SDR dongle and a LoRa HAT separately.","aliases":[],"capabilities":{"sdr_rx":"yes","sdr_tx":"no","sdr_bandwidth":"yes","subghz_rx":"yes","subghz_tx":"addon","subghz_rolling_code":"no","subghz_external_antenna":"yes","gps":"yes","gps_wardrive_log":"addon","sd_logging":"addon","standalone_untethered":"no","scriptable":"yes","wifi_scan_24":"no","ble_scan":"no","hf_1356_read":"no","packet_capture":"partial","app_store":"no","mesh_lora":"yes"},"legal":{"risk_level":"medium","notes":"The SDR side is receive-only and carries the same low legal risk as any RTL-SDR (check local rules on what you are allowed to listen to, e."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No - relies on standard host software (librtlsdr, Meshtastic, gpsd)","abandoned_risk":"medium"}},{"id":"newae-sam4s-cw313-target","hardware_id":"newae-sam4s-cw313-target","name":"SAM4S CW313 Target","firmware_kind":"n/a","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"glitching-target","status":"available","price_usd":44.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The MCU is pre-populated (no chip handling required), but you still need to already understand ChipWhisperer/side-channel workflow and own a CW313 baseboard for it to do anything.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A small CW313-family target board with a populated Microchip ATSAM4S2 (Arm Cortex-M4, 128KB flash, 64KB SRAM, 1.2V core) that plugs into NewAE's cut-down CW313 baseboard for running crypto code under power-analysis and fault-injection testing. It's the budget counterpart to the CW308 UFO ecosystem - CW313 is a simpler interposer built into the ChipWhisperer-Husky/HuskyPlus kits.","honest_take":"Cheap and populated, but still not a standalone product - CW313 targets only work seated on a CW313 baseboard, which is why NewAE bundles this exact board into its Husky starter kits rather than selling it to be useful alone. The listed core voltage (1.2V) is not actually delivered by an onboard regulator for testing purposes - NewAE bypasses the SAM4S's internal regulator and feeds 1.2V in externally from the baseboard's LDO specifically so the power trace is clean, which is a deliberate side-channel-friendly design choice, not a limitation, but it means this board cannot run on its own supply rail either. Like the CW308 socket target in this same batch, this is a legitimately sparse device - it is a fixed target board, not a multi-function tool, and the short capability list reflects that rather than shallow research.","aliases":["CW313 SAM4S Target","ATSAM4S2 CW313 Target"],"capabilities":{"jtag_swd":"yes","uart":"partial","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","glitching":"no","side_channel_power":"yes"},"legal":{"risk_level":"low","notes":"Bare lab/test equipment (a populated microcontroller target board) with no radios - no import restrictions found."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"screamer-pcie-squirrel","hardware_id":"screamer-pcie-squirrel","name":"Screamer PCIe Squirrel","firmware":"PCILeech FPGA gateware","firmware_kind":"community","vendor":"LambdaConcept","category":"hardware-debug","subcategory":"dma-attack","status":"available","price_usd":175.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You need to understand PCIe, DMA, IOMMU and the PCILeech toolchain.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A low-profile PCIe x1 FPGA card that turns any spare slot into a direct memory access port: with PCILeech you can read and write the target's RAM at over 190 MB/s without any software on the target, dump credentials, or manipulate kernel structures. The reference commercial hardware for DMA attacks.","honest_take":"It does nothing at all against a machine with VT-d/IOMMU enabled and properly configured - which is the default on most current laptops with virtualisation-based security. It also needs physical access to an internal slot, so the threat model is 'evil maid with a screwdriver', not remote attack. And note the crowd this hardware now mostly serves: the DMA board market is driven by game cheating, which is why cards are cheap and why some vendors ship deliberately spoofed device IDs.","released":"2022","aliases":["PCIe Squirrel","Screamer Squirrel","LambdaConcept Screamer"],"capabilities":{"packet_capture":"no","spi_flash_dump":"no","jtag_swd":"partial","usb_exfil":"yes","scriptable":"yes","glitching":"no"},"legal":{"risk_level":"high","notes":"Reading a machine's memory without authorisation is unauthorised access everywhere."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026","app_store":"No - PCILeech / MemProcFS","abandoned_risk":"low"}},{"id":"screen-crab","hardware_id":"screen-crab","name":"Screen Crab","firmware":"Screen Crab (stock)","firmware_kind":"stock","vendor":"Hak5","category":"network-implant","subcategory":"video-implant","status":"available","price_usd":330.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Genuinely simple: plug it inline, insert a card, apply power. The hard part is the physical access, not the device.","build_effort":"assembled","stealth":"implant","form_factor":"box","summary":"An inline HDMI implant that sits between a computer and its monitor, or a console and its television, and silently writes screenshots or video to a microSD card. Optionally it joins a 2.4 GHz Wi-Fi network and streams the captures to a self-hosted Cloud C2 server so you can watch a screen remotely.","honest_take":"Two things will decide whether this works for you, and Hak5 documents neither well. First, resolution: the official statement is the entire sentence 'Most resolutions below 1920x1080 in 16:9 format', the interfaces are HDMI 1.4 / DVI 1.0, and the troubleshooting page warns that non-16:9 aspect ratios may not work. A 1440p, 4K, ultrawide or vertically-rotated monitor is a real risk of no capture at all. Second, HDCP: Hak5's documentation does not mention HDCP anywhere. The widely-repeated claim that HDCP-protected content is not captured comes from a reseller's product page, not from Hak5, and we could not verify it - the one relevant forum thread sits behind a bot challenge. Treat HDCP behaviour as unverified and test before you rely on it. Also note it only joins dedicated 2.4 GHz access points (band-steering APs break it), and it has no entry at all in Hak5's firmware download API while every other product does, which suggests it is receiving no active firmware support at a $330 price point.","released":"2019","aliases":["ScreenCrab","Crab"],"capabilities":{"hdmi_capture":"yes","sd_logging":"yes","cloud_c2":"yes","wifi_ap_mode":"no","wifi_scan_24":"no","standalone_untethered":"no","scriptable":"partial","usb_payload_lang":"no","packet_capture":"no"},"legal":{"risk_level":"high","notes":"Covertly recording what appears on someone else's screen is squarely the kind of surveillance that interception, wiretap and privacy statutes are written about, and in many jurisdictions it is treated more seriously than network sniffing because of what screens display - medical records, messages, banking."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2024-04","app_store":"No - configuration is a text file, there is no payload ecosystem","abandoned_risk":"high"}},{"id":"sparkfun-sd-sniffer","hardware_id":"sparkfun-sd-sniffer","name":"SD Sniffer","firmware_kind":"n/a","vendor":"SparkFun Electronics","category":"hardware-debug","subcategory":"bus-interposer","status":"available","price_usd":12.5,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same as the microSD version - the board is trivial, the capture and decode work is on you.","build_effort":"assembled","stealth":"covert","form_factor":"board","summary":"The full-size-SD sibling of SparkFun's microSD Sniffer: a passive interposer that sits between an SD card and its host socket, exposing bus signals to an external header. The official repository is explicit that this board is 'for use whether hacking or debugging' the SPI signals between socket and card.","honest_take":"SparkFun's own GitHub README describes this in one sentence: it lets you 'view SPI signals between an SD socket and SD card' - so despite a full-size SD card physically carrying DAT1-DAT3 lines for 4-bit SDIO mode, the board and its documentation are built and described around SPI-mode sniffing. If your target host talks to the card in 4-bit mode (many cameras and higher-throughput embedded hosts do), you're on your own for decoding those extra lines even though the pins may be physically present on the header. Functionally identical value proposition to the microSD Sniffer, just for full-size cards, and it shares the same complete absence of debug-port, I2C or glitching capability.","released":"2013","aliases":["TOL-11468"],"capabilities":{"spi_flash_dump":"partial","logic_analyzer":"no","uart":"no","i2c":"no","jtag_swd":"no","glitching":"no","scriptable":"no","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A passive bus interposer with no radio - legal to own and use everywhere."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"sdr-rx-upconverter-jasonkits","hardware_id":"sdr-rx-upconverter-jasonkits","name":"SDR-Rx HF Up Converter Module","firmware_kind":"n/a","vendor":"JasonKits","category":"accessory","subcategory":"hf-upconverter","status":"available","price_usd":39.5,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"You need to already own and understand a separate RTL-SDR/DVB-T dongle and how to retune for the shifted HF frequencies - this module supplies nothing on its own.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A relay-switched HF upconverter and VHF/UHF preamp that sits between an antenna and an existing RTL-SDR/DVB-T dongle, shifting 10 kHz-50 MHz up into the dongle's normal tuning range while passing VHF/UHF/SHF straight through with a 3dB preamp.","honest_take":"This is a classic mixer-based upconverter - the JasonKits listing does not name the exact IC, but this class of module has historically been built around an NE612/SA612-family mixer (now a legacy, out-of-production chip family per its Wikipedia entry, so modern boards may use a different but functionally similar part; unconfirmed here). It is not itself an SDR and does nothing without a separate RTL2832U-based dongle plugged downstream, which the listing explicitly states is 'NOT SUPPLIED.' It solves the exact HF problem the RTL-SDR Blog V4 already solves for free with a built-in SA612 upconverter - if you do not already own an older dongle that lacks HF coverage, buying a V4-class dongle instead is simpler and no more expensive than buying this plus a separate receive-only dongle.","aliases":["SDR-Rx Up Converter"],"capabilities":{"sdr_rx":"addon","sdr_tx":"no","subghz_rx":"partial","subghz_tx":"no","subghz_external_antenna":"yes","subghz_amplified":"partial","standalone_untethered":"no","scriptable":"no","gps":"unknown","app_store":"no","packet_capture":"no"},"legal":{"risk_level":"low","notes":"Passive receive-only accessory with no transmit capability; owning and using it carries essentially no radio-licensing risk."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"shark-jack","hardware_id":"shark-jack","name":"Shark Jack","firmware":"Shark Jack","firmware_kind":"stock","vendor":"Hak5","category":"network-implant","subcategory":"drop-box-scanner","status":"out-of-stock","price_usd":100.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Flick the switch and it runs an nmap sweep. Writing your own payloads needs bash.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A tiny battery-powered Linux computer on the end of an Ethernet plug. You walk up to a live wall jack, flick a switch, plug it in, and it runs a payload - by default a fast nmap sweep - then you pull it out and read the loot later. It is built for the fifteen seconds you have unsupervised in a corridor.","honest_take":"The battery is 50 mAh. That is not a typo: it gives roughly ten to fifteen minutes of runtime on a full charge and takes about seven minutes to recharge, so this is strictly a smash-and-grab tool, not a drop box. If you want it to sit somewhere, you have to feed it USB power, at which point the Cable edition ($120, in stock, adds a CP2102 serial console) is the version you actually want. The SoC is a MediaTek MT7628DAN at 580 MHz with 64 MB of RAM and 64 MB of flash, which is fine for nmap and not much more. The base model is out of stock and Hak5 has since shipped a Display edition with a screen, so the line is clearly moving on. For the money it is a well-executed one-trick device and it does that trick well.","released":"2019","aliases":["SharkJack","Shark"],"capabilities":{"packet_capture":"yes","ethernet_mitm":"no","cloud_c2":"yes","scriptable":"yes","usb_payload_lang":"partial","standalone_untethered":"partial","uart":"addon","web_ui":"no","sd_logging":"no","wifi_scan_24":"no"},"legal":{"risk_level":"high","notes":"Plugging an unauthorised device into an organisation's network and scanning it is unauthorised access under computer-misuse law in most countries, and port scanning specifically has been prosecuted."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2022-02","app_store":"Yes - official payload repository, 764 stars, last pushed 2025-10","abandoned_risk":"medium"}},{"id":"shark-jack-display","hardware_id":"shark-jack-display","name":"Shark Jack Display","firmware":"Shark Jack Display 1.0.2","firmware_kind":"stock","vendor":"Hak5","category":"network-implant","subcategory":"drop-box-scanner","status":"available","price_usd":120.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"The screen removes the biggest weakness of the original - you can now see what happened without going back to a laptop.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"The 2026 refresh of the Shark Jack with a screen and a user-serviceable battery. Payloads can now prompt you interactively - entering an IP address, picking an option - and you read results on the device instead of retrieving loot later. Battery life is 25-35 minutes.","honest_take":"This is the Shark Jack that should have shipped first: the screen fixes the original's core frustration, and 25-35 minutes of battery is roughly double the base model's. It is also, notably, the same $120 as the Cable edition. Caveats: it is very new (firmware 1.0.2, August 2026) and its payload repository has only 19 stars, so the community library is thin compared to the original's 764-star repo - expect to write your own or port existing Shark Jack payloads. Hak5 does not publish an SoC for it, so assume the MT7628-class hardware of its siblings but do not take that as confirmed.","released":"2026","aliases":["Shark Jack Display","SJD"],"capabilities":{"packet_capture":"yes","ethernet_mitm":"no","cloud_c2":"yes","scriptable":"yes","usb_payload_lang":"partial","standalone_untethered":"yes","web_ui":"no","sd_logging":"unknown"},"legal":{"risk_level":"high","notes":"Same as the Shark Jack - plugging an unauthorised device into a network and scanning it is unauthorised access in most jurisdictions."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08","app_store":"Yes, but new - the dedicated payload repository has only 19 stars as of this check","abandoned_risk":"low"}},{"id":"signal-owl","hardware_id":"signal-owl","name":"Signal Owl","firmware":"Signal Owl 1.0.1","firmware_kind":"stock","vendor":"Hak5","category":"wifi","subcategory":"signals-intelligence-implant","status":"discontinued","price_usd":199.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"There is no UI at all. Everything is a bash payload written blind and dropped on a USB stick, with a single LED for feedback.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A headless Wi-Fi attack platform on a USB-A pigtail with a pass-through USB port, designed to be plugged in behind a monitor or into a USB charger and left running. It has no screen and no web interface: you write a bash payload, put it on a flash drive, and read a single LED. Discontinued.","honest_take":"Two hard facts settle this one. It was discontinued and delisted by Hak5, and its payload repository has not been touched since September 2020 - the openwrt-owl repo is archived. The hardware is a 2019-era Atheros AR9331 at 400 MHz with 64 MB of RAM and a single 2.4 GHz radio at 0.1 W, which we confirmed by reading the die markings in the FCC internal photos: ATHEROS AR9331-AL1A alongside an ESMT M13S512168A. So it is 2.4 GHz only, single-core MIPS, dead software, no vendor support, and secondhand only. Everything it did, a $15 Raspberry Pi Zero W or an ESP32 board with a USB power passthrough will do better today with maintained software. Its one genuinely clever design touch was the pass-through USB port: with a keyboard or mouse plugged through it, the Owl itself never enumerates on the target OS.","released":"2019","aliases":["SignalOwl","Owl"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"yes","wifi_deauth_24":"partial","wifi_handshake_capture":"yes","wifi_ap_mode":"yes","wifi_wardriving":"addon","sdr_rx":"addon","ble_scan":"addon","cloud_c2":"yes","scriptable":"yes","usb_payload_lang":"partial","standalone_untethered":"yes","web_ui":"no"},"legal":{"risk_level":"high","notes":"Same considerations as the WiFi Pineapple - transmitting deauthentication frames and impersonating access points are potential offences distinct from mere possession - compounded by the fact that this device is designed to be hidden and left unattended."},"ecosystem":{"community":"dead","docs_quality":"sparse","last_release":"2019-09","app_store":"Payload repository exists but has not been updated since September 2020","abandoned_risk":"already-abandoned"}},{"id":"signalsdr-pro","hardware_id":"signalsdr-pro","name":"SignalSDR Pro","firmware":"Vendor SD-card images","firmware_kind":"stock","vendor":"SignalLens","category":"sdr","subcategory":"cellular-research","status":"available","price_usd":1200.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"Its whole point is running 5G/LTE stacks (Open5GS, 5ghoul) - that is a research-grade workload.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An AD9361 + Zynq 7020 SDR in a Raspberry-Pi footprint that can impersonate a USRP or a PlutoSDR in hardware by changing SD cards, so existing cellular tooling works without porting. Positioned as the cheap way into 5G and LTE security testing.","honest_take":"Same radio chip as a bladeRF and an ADALM-PLUTO - the differentiator is the Zynq SoC, the gigabit Ethernet and the device emulation, not RF performance. It is a niche instrument: if you are not running a cellular stack, a bladeRF or a Pluto does the same radio job for a third of the money. Vendor claims about '5G auditing' are not independently benchmarked.","released":"2024","aliases":["Signal SDR Pro"],"capabilities":{"sdr_rx":"yes","sdr_tx":"yes","sdr_bandwidth":"claimed","sdr_full_duplex":"claimed","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"This board exists to transmit on cellular bands."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"medium"}},{"id":"simple-rfid","hardware_id":"simple-rfid","name":"simple_rfid","firmware":"Stock (zosko)","firmware_kind":"diy","vendor":"zosko (independent developer)","category":"rfid-nfc","subcategory":"lf-125khz-reader-diy","status":"diy-only","price_usd":10.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Off-the-shelf Arduino Nano + RDM6300 module wired per the schematic and flashed with the provided sketch - straightforward for anyone who has done basic Arduino projects, no RF design of your own required.","build_effort":"soldering","stealth":"covert","form_factor":"board","summary":"A DIY 125kHz LF RFID reader/cloner/emulator built from an Arduino Nano and an off-the-shelf RDM6300 reader module, with open schematic, PCB layout and firmware. It targets the same basic EM4100/T5577-class tags as any generic 125kHz copier - the RDM6300 module does the actual RF demodulation, the Arduino handles UID capture, storage and re-transmission.","honest_take":"The README describes this in one line as an 'emulator/cloner/reader' with no further technical detail on how writing or emulation is actually implemented - and that claim deserves real skepticism, because the RDM6300's own datasheet documents it purely as a 125kHz receive module (UART UID output only), not a writer. Genuine T5577 rewriting normally needs either a stronger dedicated write driver or a documented trick to repurpose the RDM6300's own coil in reverse, and this project's one-paragraph README doesn't say which it uses. The chip underneath is the same cheap part found in countless sub-$10 generic 125kHz copier kits already on the market - this project's real value is that it's open source and buildable from raw parts, not that it does anything those kits don't. It only covers 125kHz LF (EM4100/T5577-class) tags - it has no HF/13.56MHz capability at all, so it can't touch MIFARE or any modern access card.","released":"2024","aliases":["Simple RFID Emulator / Cloner"],"capabilities":{"lf_125khz_read":"yes","lf_125khz_write":"claimed","lf_125khz_emulate":"claimed","hf_1356_read":"no","hf_1356_write":"no","hf_1356_emulate":"no","mifare_classic_attacks":"no","iso15693":"no","felica":"no","mifare_desfire":"no","emv_read":"no","magspoof":"no","nfc_relay":"no","nfc_type4_ndef":"no","sd_logging":"no","app_store":"no","web_ui":"no"},"legal":{"risk_level":"medium","notes":"A DIY LF RFID reader/cloner is legal to own and build in most jurisdictions - it's functionally similar to any generic 125kHz copier already sold openly."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"2025-01","app_store":"No","abandoned_risk":"medium"}},{"id":"skimmerguard","hardware_id":"skimmerguard","name":"SkimmerGuard","firmware":"Stock","firmware_kind":"stock","vendor":"Mindstorm Security","category":"detection-defense","subcategory":"skimmer-detector","status":"available","price_usd":54.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Insert and remove; you get a safe/unsafe answer.","build_effort":"assembled","stealth":"covert","form_factor":"keychain","summary":"A card-format skimmer detector that counts how many times it is read during a single insertion: more than one read means a second reader - a skimmer - is present. Functionally the same idea as Electronic Cats' Hunter Cat, sold by a European vendor with a battery in the box.","honest_take":"Identical limitation to every device of this type: it detects a second magnetic read, so it catches insert and deep-insert skimmers and misses everything else - chip shimmers, keypad overlays, camera pinholes, and skimmers that read only the chip. The 'no matter how well hidden, SkimmerGuard will find it' line in the marketing is overstated; it will find a second read head, which is not the same claim.","released":"2023","aliases":["Skimmer Guard"],"capabilities":{"detect_skimmer":"yes"},"legal":{"risk_level":"low","notes":"Passive consumer device, legal to own and carry."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"n/a","app_store":"No","abandoned_risk":"medium"}},{"id":"sneak32","hardware_id":"sneak32","name":"Sneak32","firmware":"Sneak32","firmware_kind":"diy","vendor":"Jordi Murgo","category":"detection-defense","subcategory":"ble-wifi-follower-detection-firmware","status":"diy-only","price_usd":5.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Requires PlatformIO/Arduino toolchain setup and flashing a bare dev board yourself; no vendor support or pre-built binaries distribution described in the repo beyond source.","build_effort":"flash-only","stealth":"discreet","form_factor":"board","summary":"Open-source firmware for a generic ESP32 board that scans Wi-Fi beacons/probes and BLE advertisements, then flags devices that keep reappearing near the user over time as possible trackers or physical followers. A single-developer counter-surveillance project, not a commercial product.","honest_take":"This is early-stage, single-maintainer firmware - version 0.0.1, 27 GitHub stars, and no commits in roughly a year as of this writing - so treat it as a proof of concept rather than dependable anti-stalking gear. Its 'detection' is exactly what any Wi-Fi/BLE scanner does: log MAC addresses, track RSSI and how many times/how recently each one was seen, and flag repeat offenders - it has no special sauce for identifying AirTags or professional trackers specifically. There's no assembled product to buy, and the range depends heavily on which antenna your chosen ESP32 board has, which the project explicitly flags as a limitation.","released":"2024","aliases":[],"capabilities":{"wifi_scan_24":"yes","wifi_probe_sniff":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"no","wifi_wardriving":"no","ble_scan":"yes","ble_advertise":"no","ble_tracker_detect":"yes","detect_generic_ble":"yes","detect_generic_wifi":"yes","detect_airtag":"unknown","scriptable":"yes","sd_logging":"unknown","standalone_untethered":"partial"},"legal":{"risk_level":"low","notes":"Passive Wi-Fi/BLE scanning for defensive/counter-surveillance purposes is broadly legal in most jurisdictions since it only involves receiving publicly broadcast radio signals, though wiretap/privacy law nuances vary by country - check local law if deploying it to monitor others rather than your own surroundings."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2023-10 (v0.0.1)","app_store":"No","abandoned_risk":"medium"}},{"id":"newae-cw308-socket-target-stm32f","hardware_id":"newae-cw308-socket-target-stm32f","name":"Socket Target for CW308 (STM32F-SOCKET64)","firmware_kind":"n/a","vendor":"NewAE Technology","category":"hardware-debug","subcategory":"glitching-target","status":"available","price_usd":140.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"You're expected to already run ChipWhisperer, own a CW308 UFO baseboard, and be comfortable hand-placing a bare TQFP-64 chip and picking the right pinout-switch position for your specific STM32F part.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"A CW308-family daughtercard that is nothing but an empty TQFP-64 ZIF socket, a 2-position switch to select between two STM32F pinout families (chips with an onboard voltage regulator like STM32F415, vs. chips without like STM32F303), and routing to the CW308 20-pin connector. It exists so a researcher can side-channel or fault-inject an arbitrary user-supplied STM32F part without designing a custom carrier PCB for every chip.","honest_take":"This is a passive accessory, not a tool - it doesn't glitch or measure anything itself, it's the thing that gets glitched by an external ChipWhisperer (or similar) attacking it through the CW308 baseboard. It is genuinely useless on its own: no MCU is included, and it will not connect to anything without a CW308 UFO baseboard, which NewAE sells separately and which most buyers don't already own unless they're already deep into the ChipWhisperer ecosystem. If you're not already a CW308 UFO owner, buying this $140 socket card first is backwards - budget for the baseboard too before you order this. This record is deliberately capability-sparse: it is a passive chip socket with no independent function of its own, and that sparseness is the finding, not an oversight.","aliases":["STM32F-SOCKET64","CW308T-STM32F-SOCKET64","NAE-CW308T-STM32F-SOCKET64"],"capabilities":{"jtag_swd":"partial","uart":"partial","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","glitching":"no","side_channel_power":"no"},"legal":{"risk_level":"low","notes":"This is bare test/lab equipment (a chip socket) with no radios and no attack payloads of its own - no import restrictions found."},"ecosystem":{"community":"commercial","docs_quality":"excellent","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"nugget-solder-kit","hardware_id":"nugget-solder-kit","name":"Solder Your Own Nugget Kit","firmware":"Wi-Fi Nugget","firmware_kind":"diy","vendor":"Retia","category":"wifi","subcategory":"nugget-lineage-diy","status":"out-of-stock","price_usd":70.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Vendor describes it as 'easy to moderate' for soldering beginners - through-hole and some surface-mount with large pads.","build_effort":"soldering","stealth":"overt","form_factor":"board","summary":"An unassembled kit - PCB, SH1106 OLED, four buttons, a neopixel and a 3D-printed case - plus a pre-flashed D1 Mini ESP8266 and a pre-flashed S2 Mini ESP32-S2, so a buyer solders together either a Wi-Fi Nugget or a USB Nugget depending on which microcontroller they use. It is a soldering-practice packaging of the same hardware/firmware already covered under the WiFi Nugget entry elsewhere in this database, sold by a different current vendor (Retia) than the board's original makers.","honest_take":"This is not a new device - built with the D1 Mini, it is the already-tracked WiFi Nugget, with the same limitations noted there: ESP8266-only means 2.4GHz and no Bluetooth, and the deauth is the same PMF/WPA3-defeated management-frame trick as everything else. What's genuinely notable is that it exists as a current, purchasable product at all: the already-tracked WiFi Nugget entry in this database describes the original maker's storefront as dead (payment-required errors, an unresolving domain) as of the same week this kit was checked - Retia is evidently now selling and shipping Nugget-derived hardware and running the nugget.dev flasher, which that entry did not account for. Retia's own site does not explain its relationship to the original HakCat/Alex Lynd/DevKitty team, so treat this as a currently-available packaging of the same open design rather than confirmation the original project has a maintainer again.","aliases":["DIY S2 WiFi Nugget Kit"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_beacon_spam":"unknown","usb_hid_inject":"partial","usb_mass_storage":"unknown","ble_scan":"no","bt_classic":"no","detect_deauth":"claimed","hf_1356_read":"no","subghz_rx":"no","ir_tx":"no","gps":"no","web_ui":"unknown","app_store":"no"},"legal":{"risk_level":"medium","notes":"Same as the WiFi Nugget/USB Nugget lineage generally - deauth and HID injection against systems not owned or lacking authorization are computer-misuse offences in most jurisdictions."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"sonoff-zbdongle-p-sniffle","hardware_id":"sonoff-zbdongle-p","name":"SONOFF ZBDongle-P (CC2652P) running Sniffle","firmware":"Sniffle (NCC Group)","firmware_kind":"third-party-product","vendor":"ITEAD/SONOFF (hardware); NCC Group (Sniffle firmware)","category":"bluetooth","subcategory":"ble-sniffer","status":"available","price_usd":20.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Cheap and capable, but you must flash it yourself over its serial bootloader and then interpret BLE link-layer traffic in Wireshark.","build_effort":"flash-only","stealth":"covert","form_factor":"usb-stick","summary":"A $20 Zigbee dongle whose TI CC2652P is exactly the silicon NCC Group's Sniffle targets. Flashed with Sniffle it captures BLE 5 traffic across all three primary advertising channels simultaneously, supports every BLE 5 PHY including coded, and follows connections far more reliably than single-channel sniffers.","honest_take":"This is the answer to 'what should I actually buy to sniff BLE', and almost nobody knows it. Watching all three advertising channels at once is not a nice-to-have - it is the difference between catching the connection request and missing it, and Sniffle's own documentation puts connection detection at roughly three times more reliable than single-channel sniffers. It beats a retired $125 Ubertooth and a $11 Nordic dongle on capability while sitting between them on price. The catches are real but small: you must flash it yourself, doing so removes the Zigbee function, and Sniffle is a link-layer capture tool - it does not break encryption, and a connection using LE Secure Connections pairing will be captured but not readable.","released":"2021","aliases":["Sonoff Zigbee 3.0 USB Dongle Plus","ZBDongle-P","Sniffle dongle","CC2652P dongle"],"capabilities":{"ble_sniff":"yes","ble_scan":"yes","bt_classic":"no","zigbee":"addon","packet_capture":"yes","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"The hardware is an ordinary consumer smart-home accessory and legal everywhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"sparkfun-microsd-sniffer","hardware_id":"sparkfun-microsd-sniffer","name":"SparkFun microSD Sniffer","firmware_kind":"n/a","vendor":"SparkFun Electronics","category":"hardware-debug","subcategory":"bus-interposer","status":"available","price_usd":13.5,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The board itself is trivial (insert card, insert into host) but you supply your own logic analyzer or MCU to actually capture and decode what it exposes.","build_effort":"assembled","stealth":"covert","form_factor":"board","summary":"A passive interposer PCB that sits between a microSD card and its host socket (camera, dashcam, router, IoT device), breaking every physical microSD pad out to an 8-pin 0.1\" header so an external logic analyzer or MCU can passively capture the traffic. SparkFun's own product copy describes it as being for viewing SPI traffic 'whether for hacking or debugging.'","honest_take":"This is just a physical tap - it captures nothing on its own. You need to supply the logic analyzer (or MCU + firmware) and, more importantly, do the protocol decoding yourself: SparkFun's documentation frames this specifically around watching SPI-mode traffic, and most embedded hosts that use microSD in full 4-bit SDIO mode (rather than the simpler SPI mode) will need you to decode DAT1-DAT3 yourself with tooling this board does not provide. At $13.50 it is a fair price for a bare tap, but budget separately for a real logic analyzer and expect to write your own decoder for anything beyond SPI-mode traffic.","released":"2011","aliases":["TOL-09419"],"capabilities":{"spi_flash_dump":"partial","logic_analyzer":"no","uart":"no","i2c":"no","jtag_swd":"no","glitching":"no","scriptable":"no","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A passive bus interposer with no radio - legal to own and use everywhere."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"spidriver","hardware_id":"spidriver","name":"SPIDriver","firmware":"Stock (ExCamera Labs)","firmware_kind":"stock","vendor":"ExCamera Labs","category":"hardware-debug","subcategory":"protocol-bridge","status":"available","price_usd":29.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Conceptually simple (one protocol, a live display of what's on the wire) but you still need to understand SPI framing and chip-select behaviour to use it productively.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A dedicated single-protocol SPI bus probe: a small open-hardware board built around an FTDI USB-serial chip and a Silicon Labs EFM8 controller, with a built-in display that shows live SPI traffic, voltage and current as you probe a target. Adafruit's own listing describes it as 'kinda like a Bus Pirate with a display and great Python support.' It is the SPI-only sibling to the I2CDriver from the same maker.","honest_take":"This is a narrower, more expensive way to talk to SPI devices than a Bus Pirate or a $5 FTDI/CH552 adapter - the entire value proposition is the live display and the clean host tooling (GUI, CLI, Python/C bindings), not raw capability. 500 Kbps sustained SPI is fine for flash chips and sensors but slow next to a real logic analyzer or a dedicated SPI programmer, and it has zero debug-port (JTAG/SWD) or I2C support - buy the I2CDriver or a Bus Pirate 5 if you need those too. If you already own a Bus Pirate or a Glasgow, this adds nothing you don't have; it earns its keep specifically for people who want a purpose-built, always-on SPI monitor on the bench rather than a general multi-protocol tool.","released":"2019","aliases":[],"capabilities":{"spi_flash_dump":"yes","logic_analyzer":"partial","uart":"no","i2c":"no","jtag_swd":"no","glitching":"no","scriptable":"yes","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A passive bench probe with no radio - legal to own and use everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"ppe-stealth-decoy-reader-sdr-v2","hardware_id":"ppe-stealth-decoy-reader-sdr-v2","name":"Stealth Decoy Reader (SDR v2)","firmware":"Doppelgänger","firmware_kind":"third-party-product","vendor":"Mayweather Group (PPE - Physical Exploitation)","category":"rfid-nfc","subcategory":"decoy-credential-harvester","status":"available","price_usd":375.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Installing a convincing decoy at a real door and not getting caught is the actual skill; operating the capture app once it is placed is trivial.","build_effort":"assembled","stealth":"implant","form_factor":"box","summary":"A genuine commercial access-control reader - HID multiCLASS SE, HID Signo, or a Paxton Net2-specific model - with a Doppelgänger Core credential-capture module hidden inside, meant to be mounted beside or in place of a real reader so anyone who badges it hands over their credential. It is the 'looks completely legitimate' counterpart to the bag-carried long-range capture units in the same PPE product line, and the Paxton-specific configuration that some resellers list separately as the 'Dual Mode Paxton Long Range / Stealth Decoy Reader' is the same base product.","honest_take":"This device only works because it looks exactly like the reader already on the wall - the entire attack is social engineering plus physical access, not a technical exploit. It supports a long protocol list (iCLASS SE/SEOS/SR, MIFARE Classic/DESFire EV1, HID Prox, AWID, EM4102, T5577, Indala on Signo readers, Paxton Net2), but as with every other device in this batch, supporting a protocol in the Wiegand-tap sense means capturing whatever the real reader already decoded - it does not defeat DESFire or SEOS cryptography, it just sits downstream of a reader that already did the legitimate authentication and taps the wire carrying the result. The 4+ hour battery figure is for the module alone; a full engagement mounting it near an entrance for days needs mains power or repeat battery swaps, neither of which the covert framing advertises. This is, bluntly, a physical-access wiretap wearing a badge reader's clothes.","aliases":["Dual Mode Paxton Long Range / Stealth Decoy Reader","SDR v2","Ghost Reader","PPE Stealth Decoy Reader"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"no","hf_1356_emulate":"no","lf_125khz_read":"yes","lf_125khz_write":"no","mifare_classic_attacks":"no","mifare_desfire":"partial","iso15693":"no","nfc_relay":"no","web_ui":"yes","standalone_untethered":"yes","cloud_c2":"addon","scriptable":"no","wiegand_tap":"yes"},"legal":{"risk_level":"high","notes":"A decoy reader designed to be mistaken for the real one is a covert interception device by construction."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-01","app_store":"No - Doppelgänger Assistant app/WebUI, optional ATLAS subscription platform","abandoned_risk":"low"}},{"id":"steppenprobe","hardware_id":"steppenprobe","name":"Steppenprobe","firmware_kind":"n/a","vendor":"Diego Herranz","category":"hardware-debug","subcategory":"jtag-swd-uart-debug-probe","status":"diy-only","price_usd":20.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You fab your own PCB from the provided Gerbers and hand-solder an LQFP-64 0.5mm-pitch FTDI chip plus SOT-23/SC-70 logic ICs yourself (or pay a fab house for assembly), then configure OpenOCD by hand. No kit, no guided build, no assembled option from anyone.","build_effort":"full-diy","stealth":"overt","form_factor":"board","summary":"Steppenprobe is a one-person, open-hardware (KiCad) debug probe built around an FTDI FT2232H dual-channel USB bridge: channel A does JTAG or SWD (OpenOCD-compatible, no jumpers needed), channel B does UART or SWO trace, and both run simultaneously over a single USB-C cable to a 14-pin STDC14 Cortex debug connector (backward compatible with the standard 10-pin ARM connector). It also exposes 4 general-purpose GPIO controllable from OpenOCD.","honest_take":"Steppenprobe uses the exact same core chip as Tigard - the FT2232H - and Tigard's own README describes itself as 'an FTDI FT2232H-based multi-protocol tool for hardware hacking.' The difference is what's built around that chip: Tigard also does SPI, I2C, AVR ISP and iCE40 programming and ships assembled and ready to use, while Steppenprobe is JTAG/SWD/UART/SWO only and you have to fab and hand-solder the board yourself from Gerbers - no one sells it assembled. If you don't specifically need simultaneous JTAG/SWD plus UART/SWO on one USB-C cable, or don't want to hand-solder an LQFP-64 0.5mm-pitch part, Tigard or the Glasgow Interface Explorer get you a working, more capable probe faster. The project itself is functionally frozen: the last real code change was in 2021/2022, and a 2024 commit only re-saved the same files for KiCad 8 compatibility with no functional change. It has 0 open issues, which reads less as 'bug-free' and more as 'nobody is actively filing against it anymore' - though 11 forks suggest some people did build on it.","released":"2020","aliases":[],"capabilities":{"uart":"yes","jtag_swd":"yes","logic_analyzer":"no","i2c":"no","spi_flash_dump":"no","glitching":"no","scriptable":"no","standalone_untethered":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A standard JTAG/SWD/UART debug adapter for hardware you own or are authorized to test; no radio, nothing export-controlled."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2020-04","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"stm32f1-picopwner","hardware_id":"stm32f1-picopwner","name":"stm32f1-picopwner","firmware":"CTXz stm32f1-picopwner","firmware_kind":"diy","vendor":"CTXz","category":"hardware-debug","subcategory":"glitching-exploit-implementation","status":"diy-only","price_usd":4.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"This is a ready-made implementation of a published academic attack, not a beginner tool - you need to wire power, reset, boot and USART lines precisely between the Pico and the target, and understand why the timing-dependent SRAM-retention trick works to troubleshoot it.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"A ready-to-run implementation, on a $4 Raspberry Pi Pico, of a published academic power-glitch attack that bypasses STM32F1 Read-Out Protection Level 1 by keeping exploit code alive in SRAM across a power cycle, then using the Flash Patch and Breakpoint unit to redirect execution and dump the protected flash over serial.","honest_take":"This turns a peer-reviewed, previously-manual RDP bypass into something you can run with a Pico and some jumper wires, which is genuinely valuable - but know its limits before relying on it. It only affects RDP Level 1 (not Level 2, which is designed to be unrecoverable), and the technique is reported to have been closed in STM32F1 silicon revisions from 2020 onward, so it will not work against a current-production chip. It is also STM32F1-specific - it has no JTAG/SWD debugging function of its own beyond the exploit's use of an external ST-Link, and no I2C or general bus-probe capability. Treat this as a tool for older STM32F1 stock or legacy-device forensics, not a general 'unlock any STM32' button - and note the repo carries no explicit license, so redistribution terms are unclear.","released":"2023","aliases":["STM32F1 Pico Pwner"],"capabilities":{"glitching":"yes","jtag_swd":"addon","spi_flash_dump":"no","uart":"yes","i2c":"no","logic_analyzer":"no","scriptable":"unknown","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"medium","notes":"A bench glitching tool with no radio - legal to build and use on your own hardware everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2024-04","app_store":"No","abandoned_risk":"medium"}},{"id":"sword-of-secrets","hardware_id":"sword-of-secrets","name":"Sword of Secrets","firmware":"Sword of Secrets firmware","firmware_kind":"stock","vendor":"Nyx Software Security Solutions","category":"hardware-debug","subcategory":"training-target","status":"available","price_usd":45.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Solving stages requires reading datasheets, RISC-V assembly/firmware-level work, and spotting cryptographic implementation flaws - the vendor markets it to 'security researchers, enthusiasts, educators', not total beginners, though a free browser-based emulator lets you preview challenges before buying.","build_effort":"assembled","stealth":"overt","form_factor":"keychain","summary":"A keychain-sized, sword-shaped PCB built around a WCH CH32V003 RISC-V microcontroller, a Winbond W25Q128 SPI NOR flash chip, and a CH340E USB-serial bridge, packaged as a multi-stage hardware CTF. Made by Israeli embedded-security researcher Gili Yankovitch under Nyx Software Security Solutions, it shipped its first production batch of 250 units in Dec 2025-Jan 2026 after a 969%-funded Crowd Supply campaign, and the vendor has committed to shipping new encrypted challenge stages over USB for at least a year post-fulfillment.","honest_take":"The brief's framing of this as 'successor to The Skull CTF by the same maker' needs correcting: Crowd Supply's own page calls it a 'spiritual successor to Uri Shaked's The Skull CTF' - same genre of hardware-puzzle badge, but a different maker entirely (Gili Yankovitch/Nyx vs. Uri Shaked/Wokwi). Don't expect direct continuity of challenges, design, or team between the two. On the hardware: the CH32V003 is a real, extremely cheap (~$0.10-0.15 in volume) RISC-V MCU - the campaign itself jokes about building a secure update mechanism around 'a 10-cent MCU' - so the $45 price is mostly paying for the puzzle design, the encrypted content pipeline, and the promise of ongoing new stages, not exotic silicon. That's a legitimate thing to pay for if the challenge content is good (open firmware and hardware files back that up), but go in knowing you're buying curated content and a subscription-style update stream on commodity hardware, not a beefier board than a Skull or a DVID.","released":"2025","aliases":["SoS"],"capabilities":{"uart":"yes","spi_flash_dump":"yes","jtag_swd":"no","usb_hid_inject":"no","scriptable":"yes","i2c":"unknown","glitching":"unknown","logic_analyzer":"no","gps":"no","usb_mass_storage":"no"},"legal":{"risk_level":"low","notes":"A wired USB puzzle device with no radio at all - a local firmware/hardware exploitation exercise, not a transmitter or network-attack tool."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"tastic-rfid-thief","hardware_id":"tastic-rfid-thief","name":"Tastic RFID Thief","firmware":"Bishop Fox Arduino sketch","firmware_kind":"diy","vendor":"Bishop Fox (design, open source)","category":"rfid-nfc","subcategory":"long-range-badge-capture","status":"diy-only","price_usd":250.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"No exploitation knowledge required - the hard parts are sourcing a used reader, soldering to the right two wires, and rigging a battery and a bag. The RFID side is solved by the commercial reader you bought.","build_effort":"soldering","stealth":"covert","form_factor":"box","summary":"A commercial HID long-range proximity reader with its brain replaced: instead of sending Wiegand credentials to a door controller, it logs every badge that comes near it to a microSD card, silently, on battery, inside a bag or a case. Published by Bishop Fox in 2014 with full parts list, PCB and code, and it remains the reference design for long-range badge capture.","honest_take":"The read range is the thing people inflate. Bishop Fox's own figure is 'up to 3 feet' - not the six or ten feet the demo videos imply - and that is with clean high-voltage power and no interference, from a reader the size of a large hardback book. You have to get genuinely close, standing next to someone in a lift or a queue. Second, note what is doing the work: this is not a clever attack, it is a stock HID MaxiProx 5375 doing exactly the job it was sold for, with a US$10 Arduino recording the output. The 'hack' is that 125 kHz proximity credentials are unauthenticated and shout their ID at anything that energises them, which has been true since the 1980s. Third, it only captures - there is no cloning here. You still need a Proxmark or a T5577 cloner to turn CARDS.txt into a working badge. And the HF variant is not the same build: it needs an HID iCLASS R90, a much more expensive reader, and against iCLASS SE or SEOS you get a credential you cannot use without a downgrade path the site may have closed.","released":"2014","aliases":["Tastic RFID Thief","Bishop Fox RFID Thief","Tastic"],"capabilities":{"lf_125khz_read":"yes","hf_1356_read":"addon","lf_125khz_write":"no","lf_125khz_emulate":"no","sd_logging":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"This is a device whose only function is capturing access credentials from people who have not consented, at a distance, in a public or semi-public space."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2023-12","app_store":"No","abandoned_risk":"medium"}},{"id":"teensy4vfi","hardware_id":"teensy4vfi","name":"teensy4vfi","firmware":"SKGleba teensy4vfi","firmware_kind":"diy","vendor":"SKGleba","category":"hardware-debug","subcategory":"voltage-glitcher-firmware","status":"diy-only","price_usd":21.49,"price_is_estimate":true,"skill_level":"expert","skill_note":"The repository ships as raw firmware with almost no documentation ('Docs, readme, measurements, etc.' is listed as an open TODO); you are expected to read and modify the source to use it for a real target.","build_effort":"flash-only","stealth":"discreet","form_factor":"board","summary":"Open-source firmware that repurposes a Teensy 4.0/4.1 (an off-the-shelf i.MX RT1060 dev board) as a voltage fault-injection controller, with a Python RPC script for host-side control. It is an early, actively-underdocumented research project rather than a finished glitching tool.","honest_take":"The author's own README calls this 'very early stages' and a personal learning project, and that shows: there is no documentation of what external glitch-injection circuit (if any) is needed to actually hit a target's power rail, no measurements, and no published successful attack against a real chip. Compare this squarely against the ChipWhisperer-Nano ($50, ready-to-run with a built-in target and a mature Python/Jupyter course) - that is the safer choice if you are learning voltage glitching for the first time. teensy4vfi is worth watching only if you specifically want to build your own glitcher on hardware you already own and are comfortable filling in the undocumented parts yourself.","released":"2024","aliases":[],"capabilities":{"glitching":"partial","uart":"partial","scriptable":"yes","jtag_swd":"no","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"DIY firmware for a bench glitching tool with no radio - legal to own and build everywhere."},"ecosystem":{"community":"slow","docs_quality":"poor","last_release":"2025-01","app_store":"No","abandoned_risk":"medium"}},{"id":"termdriver-2","hardware_id":"termdriver-2","name":"TermDriver 2","firmware":"Stock","firmware_kind":"stock","vendor":"ExCamera Labs","category":"hardware-debug","subcategory":"serial-console-display","status":"available","price_usd":24.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"It is a USB-to-serial adapter with a screen; if you already know how to use a UART console, there is nothing new to learn.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A USB-to-serial adapter with a built-in 240x240 IPS display that renders the serial stream as a live ANSI terminal, so you can read a device's boot/debug console without a laptop attached. It can also run standalone off header power as a permanent console for an embedded system.","honest_take":"This solves a specific annoyance - tailing serial console output without dedicating a laptop screen to a terminal window - and it does that well with real ANSI color and cursor support, not just a scrolling text dump. It is not a logic analyzer, protocol sniffer, or debug probe of any kind: it is a single UART endpoint, full stop, with no SPI, I2C or JTAG/SWD capability at all. At $24 it is priced for the display and RP2040-driven terminal emulation, not for any hacking capability beyond what a $3 USB-UART cable already gives you. If you just need to talk to a serial console with a laptop already open, a bare adapter is cheaper; buy this specifically for the standalone-display use case.","released":"2026","aliases":["TermDriver2"],"capabilities":{"uart":"yes","logic_analyzer":"no","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","glitching":"no","scriptable":"no","standalone_untethered":"yes","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A passive serial console display with no radio - legal to own and use everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2026","app_store":"No","abandoned_risk":"low"}},{"id":"banshee-ghostesp","hardware_id":"banshee","name":"The Banshee","firmware":"GhostESP (Revival)","firmware_kind":"community","vendor":"The Wired Hatters","category":"multitool","subcategory":"dual-band-wifi-multitool","status":"available","price_usd":219.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Two chips to flash separately, no firmware pre-installed, and you must source and fit your own battery before it leaves the desk.","build_effort":"flash-only","stealth":"overt","form_factor":"handheld","summary":"The most hardware-dense ESP32 handheld in this batch: an ESP32-C5 and an ESP32-S3 on one board, linked over UART, both running GhostESP. The C5 drives the colour touchscreen and provides the only dual-band (2.4 + 5 GHz) Wi-Fi radio; the S3 handles BLE, NFC, IR, wired Ethernet, USB host and GPS. It is aimed at people who want one device that covers Wi-Fi, BLE, NFC, IR and wired network work without carrying a bag of dongles.","honest_take":"The 'dual-SoC' is two independent GhostESP nodes talking over a UART, not shared processing - and the C5 is simultaneously the display driver and the only 5 GHz radio, so it is doing both jobs at once. The 5 GHz itself is real and unusually well evidenced: GhostESP's changelog has entries for fixing 5 GHz channel discovery above UNII-1, AP-aware 5 GHz hopping, 5 GHz HT40 deauth tuning and role-split wardriving. What you do not get for $220 is sub-GHz - there is no CC1101 anywhere on this board, so a $49 LilyGo T-Embed CC1101 will open your garage and this will not - plus you supply the battery, the card and the GPS antenna, and the firmware doing all the work is free and runs on a $12.58 dongle.","released":"2026","aliases":["Banshee","Wired Hatters Banshee","GhostESP Banshee"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"partial","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_beacon_spam":"yes","wifi_wardriving":"yes","wifi_ap_mode":"yes","detect_pineapple":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_tracker_detect":"yes","nrf24_scan":"yes","hf_1356_read":"partial","mifare_classic_attacks":"partial","hf_1356_emulate":"addon","lf_125khz_read":"addon","ir_tx":"yes","ir_rx":"yes","ir_universal_remote":"yes","usb_hid_inject":"yes","ethernet_mitm":"yes","packet_capture":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","web_ui":"yes","app_store":"yes","standalone_untethered":"partial","subghz_rx":"no","subghz_tx":"no"},"legal":{"risk_level":"high","notes":"Owning it is legal."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026-09","app_store":"Yes - GhostESP native SD app marketplace","abandoned_risk":"low"}},{"id":"the-tick","hardware_id":"the-tick","name":"The Tick","firmware":"The Tick (jkramarz)","firmware_kind":"diy","vendor":"Open-source project (PCBs via PCBWay community, or self-fabricated)","category":"rfid-nfc","subcategory":"access-control-implant","status":"diy-only","price_usd":25.0,"price_is_estimate":true,"skill_level":"expert","skill_note":"You fabricate and hand-solder the board, then install it inside live access-control wiring.","build_effort":"soldering","stealth":"implant","form_factor":"board","summary":"The most capable open-source access-control implant currently maintained: an ESP32-C3 board that sits behind a card reader and handles Wiegand, magnetic-stripe clock-and-data and some OSDP, with both BLE and Wi-Fi interfaces, configurable data lines, and tolerance for up to 25 V supply and 16 V data lines. Its own README contains an honest comparison table against BLEKey, ESP-RFID-Tool and ESPKey.","honest_take":"The maintainer describes his own firmware as 'slightly-organised code soup' - this is a research project, not a product, and there is nobody to call when it misbehaves inside a client's wall. It is also the only one of the four Wiegand implants that is still under active development, which matters more than polish. The OSDP support is partial: do not assume it defeats a properly configured OSDP Secure Channel installation.","released":"2024","aliases":["TheTick"],"capabilities":{"lf_125khz_read":"partial","hf_1356_read":"partial","magspoof":"partial","uart":"yes","web_ui":"yes","ble_hid":"no","wifi_ap_mode":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Same as any reader implant: installing it in equipment you do not own is unlawful interception and tampering."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025-09","app_store":"No","abandoned_risk":"medium"}},{"id":"throwing-star-lan-tap","hardware_id":"throwing-star-lan-tap","name":"Throwing Star LAN Tap","firmware_kind":"n/a","vendor":"Great Scott Gadgets","category":"network-implant","subcategory":"passive-ethernet-tap","status":"available","price_usd":15.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug it inline and run Wireshark on the monitor ports.","build_effort":"soldering","stealth":"discreet","form_factor":"board","summary":"A completely passive Ethernet tap: no power, no chips, nothing for the target network to detect. Two monitor ports are wired receive-only so your capture machine physically cannot transmit onto the tapped link. Two capacitors deliberately degrade the line so gigabit links renegotiate down to 100BASE-TX, which is what makes passive tapping possible at all.","honest_take":"That gigabit downgrade is the whole trade-off and people miss it: the tap forces the link to 100 Mb/s, which is both a performance hit and a very visible event to anyone watching interface stats. You also need two capture interfaces to see both directions. If you need silent gigabit capture, this is the wrong tool - you want a proper aggregating tap or a SPAN port.","released":"2011","aliases":["Throwing Star","LAN Tap Pro"],"capabilities":{"ethernet_tap_passive":"yes","ethernet_mitm":"no","packet_capture":"yes"},"legal":{"risk_level":"medium","notes":"The device is legal hardware."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"n/a - hardware design is stable","app_store":"No","abandoned_risk":"low"}},{"id":"ti-cc1352p7-launchpad-sniffle","hardware_id":"ti-cc1352p7-launchpad","name":"TI CC1352P7 LaunchPad running Sniffle","firmware":"Sniffle (NCC Group)","firmware_kind":"third-party-product","vendor":"Texas Instruments (hardware); NCC Group (Sniffle firmware)","category":"bluetooth","subcategory":"ble-sniffer","status":"available","price_usd":60.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"Same analysis skill as the Sonoff route, but easier to flash (on-board XDS110 debugger) and easier to extend.","build_effort":"flash-only","stealth":"overt","form_factor":"board","summary":"The reference hardware family for Sniffle. Any of eight TI LaunchPads (CC26x2R, CC2652RB, CC1352R, CC1352P, CC2652R7, CC1352P7, CC2651P3, CC1354P10) run Sniffle identically; the Electronic Cats Catsniffer V3 is also supported. The dual-band parts add a sub-GHz radio the Sonoff dongle does not have.","honest_take":"Functionally this captures exactly what the $20 Sonoff dongle captures - Sniffle's own documentation says the supported boards are equivalent - so you are paying three times as much for the on-board debugger, the expansion headers, and on the dual-band parts a sub-GHz radio. That is a fair trade if you intend to modify Sniffle or build something on top of it, and a waste of $40 if you just want to sniff BLE. Buy the LaunchPad if you are developing; buy the Sonoff if you are using.","released":"2022","aliases":["CC1352P LaunchPad","LAUNCHXL-CC1352P7","Sniffle LaunchPad","Catsniffer V3"],"capabilities":{"ble_sniff":"yes","ble_scan":"yes","bt_classic":"no","subghz_rx":"addon","zigbee":"addon","packet_capture":"yes","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"An ordinary development board, legal everywhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"tigard","hardware_id":"tigard","name":"Tigard","firmware_kind":"n/a","vendor":"SecuringHardware.com / tigard-tools","category":"hardware-debug","subcategory":"multi-protocol-adapter","status":"available","price_usd":55.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The hardware is genuinely simple - switches for voltage and mode - but you need to know which host tool to point at it and what a JTAG scan chain is.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An FT2232HQ-based multi-protocol, multi-voltage adapter with proper level shifters and dedicated labelled headers for UART, JTAG, SWD, SPI and I2C. Its whole reason to exist is that it handles 1.8 V to 5.5 V correctly and does not require you to guess which pin is which.","honest_take":"This is the boring, correct answer for most hardware hacking, and the honest pitch is that it saves you from a drawer full of cheap FTDI breakouts that all run at 3.3 V and quietly damage 1.8 V targets. The 1.8 V support is the point - a lot of modern flash and SoCs are 1.8 V and the generic adapters simply do not handle them. Its limits are real though: FT2232H means two channels, so you get one dedicated UART plus one shared port that must be switched between SPI/JTAG and I2C/SWD, and its 'logic analyzer port' is a header for your own analyser, not a built-in one. It does not discover interfaces for you either - that is a JTAGulator.","released":"2020","aliases":["Tigard v1.1","SecuringHardware Tigard"],"capabilities":{"uart":"yes","i2c":"yes","spi_flash_dump":"yes","jtag_swd":"yes","logic_analyzer":"partial","glitching":"no","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"A passive debug adapter with no radio."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2025","app_store":"No","abandoned_risk":"low"}},{"id":"tinysa-ultra-plus","hardware_id":"tinysa-ultra-plus","name":"tinySA Ultra+","firmware":"Stock (tinySA)","firmware_kind":"stock","vendor":"Zeenko","category":"sdr","subcategory":"handheld-spectrum-analyzer","status":"available","price_usd":209.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Reading a spectrum plot and understanding RBW/attenuation tradeoffs takes some RF background, but the touchscreen UI is usable without programming.","build_effort":"assembled","stealth":"discreet","form_factor":"handheld","summary":"A handheld, battery-powered spectrum analyzer (the ZS406 hardware revision of tinySA Ultra+) with a calibrated 100kHz-900MHz range, extending to 5.4GHz in an uncalibrated 'Ultra mode' and 10GHz in harmonic mode. It doubles as a basic signal generator up to roughly 4.4-6.3GHz depending on mode. It is NOT a general-purpose SDR - it sweeps and displays signal strength vs. frequency, it does not demodulate or stream raw I/Q to a host.","honest_take":"This gets filed under 'SDR' for lack of a dedicated test-equipment category, but calling it an SDR is misleading - a tinySA sweeps frequency and shows you signal strength, it cannot demodulate, decode, or record raw I/Q like a HackRF or RTL-SDR can. Its real strength (finding an unknown transmitter's exact frequency before you point a proper SDR at it) is genuinely useful for RF security work, but the flashy 5.4GHz+ 'Ultra mode' numbers are uncalibrated and 10GHz harmonic mode is a mathematical trick using higher-order mixer harmonics with reduced accuracy - the honestly-usable calibrated range is 100kHz-900MHz. Multiple hardware revisions exist under similar names (ZS406 vs ZS407, this listing is the ZS406, capped at 5.4GHz Ultra mode; the ZS407 variant goes to 7.3GHz) - confirm which one you're buying, since sellers aren't always precise about it.","released":"2025","aliases":["tinySA Ultra+ ZS406"],"capabilities":{"sdr_rx":"no","sdr_tx":"partial","sdr_bandwidth":"no","sdr_full_duplex":"no","detect_generic_wifi":"partial","wifi_monitor_mode":"no","sd_logging":"yes","web_ui":"no","app_store":"no","standalone_untethered":"yes","scriptable":"yes","gps":"no"},"legal":{"risk_level":"low","notes":"Receiving/analyzing ambient RF spectrum is broadly legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"tinysniffer","hardware_id":"tinysniffer","name":"tinySniffer","firmware":"tinyDebian","firmware_kind":"stock","vendor":"tinyDebian","category":"hardware-debug","subcategory":"usb-analyzer","status":"available","price_usd":179.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Setup requires SSH into a Linux SBC, optional cloud registration on usb7.net for remote/shipped-to-someone-else use, and Wireshark/URB familiarity to make sense of captures.","build_effort":"assembled","stealth":"discreet","form_factor":"board","summary":"A USB 1.x/2.0 inline sniffer built on a FriendlyElec NanoPi NEO Air single-board computer (Allwinner H3), confirmed directly in the vendor's own documentation. Instead of dedicated capture silicon (FPGA/CPLD) like the other sniffers in this category, it does USB passthrough and packet capture entirely in software on the SBC's Linux kernel, then lets you pull PCAP files or control it remotely over WiFi/SSH.","honest_take":"This is essentially a ~$15-20 Allwinner H3 Linux SBC marked up roughly 10x, with the real value being the vendor's custom 'software passthrough' capture stack rather than any special hardware. That software approach is also its biggest limitation: the vendor's own docs explicitly warn against connecting a USB flash drive because it can't keep up with sustained bulk transfers - something a hardware FPGA sniffer wouldn't struggle with. 'Remote control' is genuinely just SSH and a cloud web portal into a Linux box, and the device must stay network-connected to capture at all, which undercuts any 'portable field tool' framing. An independent reviewer (Doug Brown's blog) also flagged unclear language suggesting cloud registration might be required even for local use.","released":"2022","aliases":["tinySniffer USB 1.x/2.0 Sniffer"],"capabilities":{"wifi_monitor_mode":"no","standalone_untethered":"no","usb_hid_inject":"no","usb_mass_storage":"no","usb_keylogger":"no","hid_remote_trigger":"no","jtag_swd":"no","uart":"no","i2c":"no","ethernet_tap_passive":"no"},"legal":{"risk_level":"low","notes":"Passively capturing USB traffic on hardware you own/control is broadly legal."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"2024-11","app_store":"No","abandoned_risk":"medium"}},{"id":"tplink-tl-mr3020-minipwner","hardware_id":"tplink-tl-mr3020","name":"TP-Link TL-MR3020 (MiniPwner/OpenWrt SKU)","firmware":"Custom","firmware_kind":"stock","vendor":"TP-Link (sold by Hacker Warehouse)","category":"network-implant","subcategory":"travel-router-dropbox","status":"available","price_usd":50.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Buying it is trivial; turning it into a MiniPwner or OpenWrt dropbox means flashing OpenWrt yourself and is meaningfully harder today because the 4MB/32MB hardware no longer fits current OpenWrt releases.","build_effort":"flash-only","stealth":"discreet","form_factor":"box","summary":"A tiny 802.11n travel router built around a Qualcomm Atheros AR9331 SoC, sold here at a markup specifically because the reflashing community (OpenWrt, MiniPwner) validated years ago that this model works as a pocket-sized pentest dropbox. The unit itself ships with stock TP-Link firmware - it is not preloaded with OpenWrt or MiniPwner.","honest_take":"This SKU is bare, unmodified TP-Link firmware - Hacker Warehouse is charging $50 for a router that sells for $15-25 elsewhere, and the entire premium is 'we know this specific model works for MiniPwner,' not anything they've done to the hardware. Worse, OpenWrt itself now actively discourages this device: its 4MB flash/32MB RAM is officially flagged as too small for any OpenWrt release newer than 19.07 (last built 2022), so a buyer chasing a modern, patched OpenWrt dropbox will not get one on this hardware - you're building on a permanently frozen, unpatched base. MiniPwner itself is a real, well-documented project dating to 2012 (Kevin Bong and Michael Vieau), not a marketing name, but its guides and package set (Aircrack-ng, Kismet, Nmap, Reaver, etc.) predate modern Wi-Fi security and haven't seen meaningful updates in years.","aliases":["TL-MR3020 MiniPwner","MiniPwner (TL-MR3020 build)"],"capabilities":{"wifi_ap_mode":"yes","wifi_scan_24":"addon","wifi_scan_5":"no","wifi_monitor_mode":"addon","wifi_injection":"addon","packet_capture":"addon","ethernet_mitm":"addon","vpn_exfil":"addon","usb_mass_storage":"addon","uart":"yes","standalone_untethered":"yes","scriptable":"addon"},"legal":{"risk_level":"low","notes":"Owning or importing this router is unrestricted almost everywhere - it's a generic consumer travel router."},"ecosystem":{"community":"dormant","docs_quality":"sparse","last_release":"2019","app_store":"No","abandoned_risk":"high"}},{"id":"ubertooth-one","hardware_id":"ubertooth-one","name":"Ubertooth One","firmware":"Stock (Great Scott Gadgets)","firmware_kind":"stock","vendor":"Great Scott Gadgets","category":"bluetooth","subcategory":"bluetooth-sniffer","status":"discontinued","price_usd":125.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"Bluetooth sniffing on this hardware requires understanding piconet timing, hopping and the CC2400's modulation limits - and accepting that it often just does not capture.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"The original open-source 2.4 GHz Bluetooth monitoring platform, built on a TI CC2400 radio and an NXP LPC175x ARM Cortex-M3. It made Bluetooth traffic visible to researchers for the first time on affordable hardware. It has been retired by its creator and, for BLE work specifically, has been comprehensively overtaken.","honest_take":"Do not buy this in 2026 unless you specifically need Bluetooth Classic. It is retired, what is on sale is clones, and for BLE a $20 Sonoff dongle running Sniffle beats it on every axis - Sniffle listens on all three advertising channels at once and supports BLE 5's 2M and coded PHYs, none of which the CC2400 can do. Its Classic capability is also more limited than its reputation suggests: the CC2400 can only demodulate 1 Mbps basic-rate GFSK, so EDR (2 and 3 Mbps) traffic is simply invisible to it, and it decrypts nothing. Historically important, practically superseded.","released":"2011","aliases":["Ubertooth","Ubertooth-1"],"capabilities":{"ble_sniff":"partial","bt_classic":"partial","ble_scan":"yes","ble_advertise":"no","ble_jam":"partial","nrf24_scan":"partial","packet_capture":"yes","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"Owning it is legal."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2022","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"uconsole-aio-v2","hardware_id":"uconsole-aio-v2","name":"uConsole AIO V2 (RTL-SDR/LoRa/GPS/RTC/USB Hub/USB 3.0/RJ45 Ethernet)","firmware_kind":"n/a","vendor":"Hacker Gadgets","category":"sdr","subcategory":"uconsole-expansion-board","status":"preorder","price_usd":92.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Requires already owning (or building) a ClockworkPi uConsole handheld Linux computer, plus comfort with Linux-based SDR/LoRa tooling.","build_effort":"assembly","stealth":"discreet","form_factor":"board","summary":"An expansion board for the ClockworkPi uConsole handheld Linux computer that adds an RTL2832U+R860-based RTL-SDR receiver (100kHz-1.74GHz, with HF direct sampling down to 100kHz-28.8MHz), a Semtech SX1262 LoRa radio (860-960MHz, up to 22dBm), GPS/GNSS, an RTC, and USB 3.0/Gigabit Ethernet ports, turning the uConsole into a field SDR/LoRa/wardriving platform.","honest_take":"The RTL-SDR portion is receive-only - it's the same RTL2832U+R860 tuner combination found in $25 RTL-SDR dongles, just integrated onto a board with everything else; buying this specifically for wideband transmit capability would be a mistake, that job belongs to the SX1262 LoRa radio (which is TX+RX but only in the 860-960MHz LoRa band, not general-purpose). The 'USB 3.0 and RJ45 Gigabit Ethernet' headline claim comes with a real asterisk the listing itself states: full USB 3.0 and RJ45 only work with the uConsole's CM5 upgrade kit, not the base CM4 unit most existing uConsoles ship with - check which compute module you have before assuming you'll get those speeds/ports.","released":"2026","aliases":["uConsole AIO Board V2"],"capabilities":{"sdr_rx":"yes","sdr_tx":"no","sdr_bandwidth":"unknown","sdr_full_duplex":"no","gps":"yes","gps_wardrive_log":"claimed","ethernet_tap_passive":"no","packet_capture":"claimed","usb_mass_storage":"unknown","standalone_untethered":"partial","sd_logging":"unknown","scriptable":"yes"},"legal":{"risk_level":"low","notes":"RTL-SDR reception and GPS are passive/receive-only and broadly legal to own and use."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"uhfkill","hardware_id":"uhfkill","name":"UHFKill","firmware_kind":"n/a","vendor":"NFCKill (Info Wise Limited)","category":"rfid-nfc","subcategory":"uhf-tag-deactivator","status":"available","price_usd":1650.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Point, hold 5cm from the tag for the pulse duration, done - no protocol knowledge needed. The judgment call is knowing which tags in a shipment are UHF vs the HF/LF tags a standard NFC Kill handles.","build_effort":"assembled","stealth":"overt","form_factor":"desktop","summary":"A mains-powered electromagnetic-pulse emitter that permanently disables passive UHF RFID tags (800-960MHz, EPC Gen1/Gen2) used for retail inventory and supply-chain tracking, at up to 5cm range. It is the UHF sibling of the same company's HF/LF 'NFC Kill' deactivator, built for the specific case - apparel, footwear, eyewear - where a UHF tag is sewn or moulded in and cannot be cut out.","honest_take":"This is a bench tool, not a pocket gadget: 2.5kg, mains-powered at up to 15kW instantaneous pulse power, and it needs to sit within 5cm of the tag. It does not 'jam' or block UHF reads - it physically burns out the tag's antenna-to-chip bond with an induced pulse, which is irreversible and detectable (the tag is dead, not hidden). NFCKill's own claim is ~98% coverage of common antenna geometries, not 100%, so a rack of unusual tags may need the reader/verification step (Lab401 pairs it with the Industrial Handheld UHF Reader for exactly this). The obvious misconception is that this is a covert shoplifting tool - it is loud, requires a power outlet, and is marketed and priced for legitimate supply-chain/loss-prevention/returns-processing workflows, not something you carry into a store. It also does nothing at all to HF/LF tags - that is a different product from the same maker.","aliases":["NFCKill UHF","UHF Kill"],"capabilities":{"hardware_destruct":"yes","hf_1356_read":"no","hf_1356_emulate":"no","lf_125khz_read":"no","lf_125khz_emulate":"no","mifare_classic_attacks":"no","iso15693":"no","nfc_relay":"no","standalone_untethered":"no","scriptable":"no","web_ui":"no","uhf_rfid_read":"no","uhf_rfid_write":"no"},"legal":{"risk_level":"low","notes":"Deactivating UHF tags on goods you own or are authorised to process (returns, recycling, retail operations, research) is not itself restricted in most jurisdictions - this is a supply-chain tool sold openly to retailers."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"ultimate-marauder-esp32marauder","hardware_id":"ultimate-marauder","name":"Ultimate Marauder","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"The Wired Hatters","category":"wifi","subcategory":"flipper-wifi-module","status":"available","price_usd":173.25,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Two separate ESP32s to flash with two different Marauder builds, and a GPS that has to be switched to whichever chip you want using it.","build_effort":"flash-only","stealth":"overt","form_factor":"hat-shield","summary":"A dual-ESP32 Wi-Fi module for the Flipper Zero that also works standalone over USB-C. An ESP32-WROOM-UE drives a touchscreen running ESP32 Marauder directly, while an ESP32-WROVER is controlled by the Flipper through its GPIO header. An onboard GPS with a ceramic antenna handles wardriving, switched to one chip or the other.","honest_take":"$173 buys two 2.4 GHz-only ESP32 modules and a GPS on one board. The two chips do not cooperate - one drives the screen, one answers the Flipper, and the single GPS is switched between them, so you get one working Marauder at a time, not two. Marauder itself is free and runs on a $30 board; what you are actually paying for here is the Flipper integration, the built-in GPS and the case. There is no 5 GHz, no sub-GHz and no NFC, and the deauth everyone buys these for stops working the moment a network turns on 802.11w, which WPA3 does by default.","aliases":["Ultimate Maurauder","Ultimate Marauder Flipper module","Wired Hatters Ultimate Marauder"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_deauth_24":"yes","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_handshake_capture":"partial","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_wardriving":"yes","ble_scan":"yes","ble_spam_apple":"yes","ble_tracker_detect":"yes","detect_flipper":"yes","gps":"yes","gps_wardrive_log":"yes","standalone_untethered":"partial","subghz_rx":"no","hf_1356_read":"no","ir_tx":"no"},"legal":{"risk_level":"medium","notes":"Owning it is legal."},"ecosystem":{"community":"very-active","docs_quality":"good","last_release":"2026","app_store":"No","abandoned_risk":"low"}},{"id":"unsurv-offline","hardware_id":"unsurv-offline","name":"unsurv offline","firmware":"unsurv-offline firmware","firmware_kind":"stock","vendor":"Unsurv Technologies","category":"detection-defense","subcategory":"camera-proximity-logger","status":"available","price_usd":99.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Setup involves loading an OSM-derived camera-location database onto the SD card and pairing with the companion Android app over NFC - not a flash-and-forget device.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A tiny open-source ESP32 board with a real GNSS receiver, an accelerometer and a passive NFC tag interface. It logs a GPS track, cross-references it offline against an OpenStreetMap-derived database of known camera locations stored on its SD card, and produces a daily proximity report read by tapping a phone's NFC reader against it - no data leaves the device to any third party.","honest_take":"This is a location logger with an offline lookup table, not a camera detector - it does not sense cameras with any sensor of its own; it matches a GPS track against wherever OSM contributors have manually tagged a camera, so its accuracy is entirely a function of how complete and current that crowdsourced tagging is in a given area, which varies enormously by city and is frequently stale or missing entirely for private or newer installations. The privacy design is genuinely good and rare in this category - fully open source, a passive NFC tag rather than an active radio to avoid leaking the device's presence, and everything processed locally rather than phoning home - but don't confuse 'privacy-respecting camera awareness log' with 'camera detector.' It also shipped years late to its original 2021-2022 Crowd Supply backers over component sourcing problems, worth weighing against a small team with no dedicated production line.","released":"2021","aliases":["Unsurv Offline"],"capabilities":{"gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","detect_surveillance_cam":"partial","detect_generic_ble":"no","nfc_relay":"no","hf_1356_read":"no","hf_1356_emulate":"no","wifi_scan_24":"unknown","wifi_wardriving":"claimed","scriptable":"yes","standalone_untethered":"yes","wifi_deauth_24":"no","subghz_rx":"no","ble_scan":"no","usb_hid_inject":"no","mifare_classic_attacks":"no","ir_tx":"no"},"legal":{"risk_level":"low","notes":"Passive GPS logging and local data processing carry minimal legal exposure anywhere; this is a privacy tool, not an attack tool."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":null,"app_store":"No - has a dedicated 'unsurv-companion' Android app instead","abandoned_risk":"medium"}},{"id":"urti","hardware_id":"urti","name":"URTI (Universal Radio Test Instrument)","firmware_kind":"n/a","vendor":"Great Scott Gadgets","category":"sdr","subcategory":"multi-instrument-sdr","status":"vaporware","price_is_estimate":false,"skill_level":"expert","skill_note":"Aimed at replacing several pieces of bench test equipment at once (spectrum analyzer, VNA, signal generator, power meter, frequency counter); using it well will require understanding what each of those instruments does.","build_effort":"assembled","stealth":"overt","form_factor":"handheld","summary":"An in-development, ARDC/TAPR-funded open-source SDR instrument from Great Scott Gadgets (makers of HackRF and YARD Stick One) intended to combine a spectrum analyzer, vector network analyzer, vector signal generator/analyzer, antenna analyzer, power meter and frequency counter with a full-duplex wideband SDR and an integrated directional coupler, released under CERN-OHL-P/BSD-3-Clause open licenses, in both a handheld and a tethered computer-peripheral form factor.","honest_take":"There is no shipping product, no price, and no confirmed release date - this is a public, transparently-tracked engineering effort (GSG's own phase-two update confirms an initial prototype board has been fabricated and its components tested), not vaporware in the deceptive sense, but it is also not something you can buy or evaluate today. If the ambitious feature list actually ships as described, it would be a meaningfully different class of device from anything else in this batch, and notably GSG's existing flagship, the HackRF, is explicitly half-duplex - a working full-duplex GSG product would be new territory for them. Until it ships, treat every capability below as aspirational and unconfirmed.","aliases":[],"capabilities":{"sdr_rx":"claimed","sdr_tx":"claimed","sdr_full_duplex":"claimed","sdr_bandwidth":"unknown","subghz_rx":"claimed","subghz_tx":"claimed","standalone_untethered":"claimed","scriptable":"unknown","app_store":"unknown","web_ui":"unknown","packet_capture":"unknown"},"legal":{"risk_level":"low","notes":"Not a shipping product, so no transmission is currently occurring anywhere; legal risk assessment will need revisiting once (if) it ships, given the stated full-duplex wideband transmit capability."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"usb-armory-mk2","hardware_id":"usb-armory-mk2","name":"USB armory Mk II","firmware":"Debian / TamaGo","firmware_kind":"stock","vendor":"WithSecure Foundry / inversepath (design), sold via Mouser, Crowd Supply, Hacker Warehouse, HackmoD","category":"usb-hid","subcategory":"usb-computer","status":"available","price_usd":260.0,"price_is_estimate":false,"skill_level":"expert","skill_note":"It is a bare Linux/Go computer - you build what it does, including the USB device personality.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"An open-hardware secure computer in a USB stick: i.MX6ULZ at 900 MHz, 512 MB RAM, 16 GB eMMC, USB-C on both ends supporting host and device mode, plus a u-blox ANNA-B112 (nRF52832) for Bluetooth. Because it can be either a USB host or a USB device, it is the reference platform for USB firewalling, custom device emulation and hardware-backed key storage.","honest_take":"This is not a Rubber Ducky. Out of the box it does nothing offensive; it is a developer platform with secure boot, TrustZone and a bare-metal Go runtime, and its most-used applications are defensive (encrypted storage, smartcard emulation, USB firewalling). If you want push-button HID injection, a USD 6 Pico does that better. Buy this if you need a trustworthy, fully open computer that fits in a USB port and you intend to write software for it.","released":"2019","aliases":["USB armory","USBarmory MkII"],"capabilities":{"usb_hid_inject":"partial","usb_mass_storage":"yes","usb_ethernet_attack":"yes","usb_exfil":"yes","ble_scan":"yes","scriptable":"yes","standalone_untethered":"no","jtag_swd":"partial"},"legal":{"risk_level":"low","notes":"A general-purpose computer with strong cryptographic features."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-08","app_store":"No - first-party apps (INTERLOCK, GoKey, GoTEE, armory-drive)","abandoned_risk":"low"}},{"id":"retia-usb-nugget-s2","hardware_id":"retia-usb-nugget-s2","name":"USB Nugget (ESP32-S2)","firmware":"Nugget OS / S2-Nugget","firmware_kind":"community","vendor":"Retia (retia.io)","category":"usb-hid","subcategory":"educational-badusb-board","status":"out-of-stock","price_usd":75.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Purpose-built as a teaching platform: drag-and-drop payload deployment via mass storage, quick-select buttons for pre-made attacks, and an OLED that shows what's executing. Deeper use (writing your own CircuitPython payloads) is intermediate.","build_effort":"assembled","stealth":"overt","form_factor":"usb-stick","summary":"A cat-themed ESP32-S2 board with native USB, an OLED screen, quick-select buttons and Wi-Fi, sold by Retia LLC as the current-generation successor to Alex Lynd's original HakCat WiFi/USB Nugget line. It mounts as a USB flash drive for drag-and-drop payload deployment, injects keystrokes as a HID keyboard, and can be remotely controlled from a phone or desktop over its own Wi-Fi.","honest_take":"The existing database entry for the original 'WiFi Nugget' calls the whole Nugget lineage already-abandoned, based on the DevKitty-branded shop and repos going dark - and that assessment is correct for DevKitty specifically, but it misses that creator Alex Lynd's line is alive and being actively developed today under Retia LLC (commits into September 2026, per Retia's GitHub org), just under new branding and a new firmware name (Nugget OS / S2-Nugget, distinct from DevKitty's archived ScriptKitty-era code). If you're evaluating whether to buy into this ecosystem, judge it on Retia's current activity, not the DevKitty shop's dead Shopify store. On capability: it's an ESP32-S2 board, so 2.4GHz-only Wi-Fi, no 5GHz, and the 'monitor mode' is the same management-frame-level tooling every other ESP32 security board in this database uses - not a magic wand against WPA3/PMF-protected networks.","released":"2022","aliases":["Wi-Fi Nugget S2","S2 Nugget"],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","usb_exfil":"unknown","usb_keylogger":"no","hid_remote_trigger":"yes","usb_payload_lang":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"partial","detect_generic_wifi":"yes","bt_classic":"no","standalone_untethered":"partial","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning and building the board is legal."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09 (Retia's scriptkitty.sh browser flasher for the Nugget/Nibble line updated Sep 5, 2026)","app_store":"No","abandoned_risk":"medium"}},{"id":"dlogic-dl533n-usb-stick","hardware_id":"dlogic-dl533n-usb-stick","name":"USB RFID Reader/Writer DL533N","firmware_kind":"n/a","vendor":"D-Logic (Digital Logic Ltd)","category":"rfid-nfc","subcategory":"hf-reader-writer-usb","status":"available","price_usd":42.12,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"No GUI - you drive libnfc command-line tools (nfc-list, mfoc, mfcuk, nfc-mfclassic) yourself and read raw APDU-level output.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A direct-plug USB dongle built around the NXP PN533 chip, exposing a libnfc-compatible 13.56MHz reader/writer/emulator. It is the RF front end; all the actual attack logic (mfoc/mfcuk dictionary and darkside/nested key recovery) runs on the host PC through standard open-source libnfc tooling, the same tooling that works with any PN532/PN533-class reader.","honest_take":"The MIFARE Classic 'cracking' capability people associate with this device is not unique to it - mfoc and mfcuk run against any PN532/PN533 board, including $5-10 generic breakout modules from AliExpress. What D-Logic actually sells for ~$40-55 is a properly engineered, driver-tested, SDK-documented board and support, not exclusive silicon capability. It has zero standalone mode - without a PC running libnfc it is inert, and it does not touch ISO15693 (iCode/library tags) at all because the PN533 silicon doesn't implement that RF interface.","aliases":["DL533N","DL533N USB Stick"],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"yes","hf_1356_emulate":"yes","mifare_classic_attacks":"yes","mifare_desfire":"partial","nfc_type4_ndef":"yes","felica":"yes","iso15693":"no","emv_read":"unknown","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","nfc_relay":"no","scriptable":"yes","standalone_untethered":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"Owning an HF reader/writer is legal essentially everywhere and this exact chip class is used in countless legitimate access-control and payments products."},"ecosystem":{"community":"active","docs_quality":"good","last_release":null,"app_store":"n/a","abandoned_risk":"low"}},{"id":"usb-rubber-ducky","hardware_id":"usb-rubber-ducky-mk2","name":"USB Rubber Ducky","firmware":"DuckyScript 3.0 firmware","firmware_kind":"stock","vendor":"Hak5","category":"usb-hid","subcategory":"keystroke-injection","status":"available","price_usd":100.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Writing a first payload takes ten minutes. Writing one that survives a real target's timing, locale and EDR takes much longer.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"The device that invented keystroke injection as an attack class. It looks like a flash drive but enumerates as a keyboard, then types a pre-written payload at machine speed. The 2022 hardware added DuckyScript 3.0, a real structured language with variables, conditionals, loops and functions, plus out-of-band exfiltration.","honest_take":"DuckyScript 3 is a genuine advance and not just marketing - you get IF/ELSE, WHILE, functions, integer variables, arithmetic and bitwise operators, VID/PID/manufacturer/serial spoofing, and Keystroke Reflection, which exfiltrates binary data back out through the keyboard's lock-key LED channel to loot.bin on the card. Nothing cheap does that last one. But be honest about the price: for pure 'type this script when plugged in', a $5 Digispark ATtiny85 or a $10-15 CH552 board does the job, and there are open-source projects that will run Ducky payloads on them. What you lose going cheap is real: no conditionals or host feedback, no reliable OS detection via lock-key state, no exfiltration channel, no VID/PID spoofing, ATtiny85 boards famously have flaky USB timing and enumerate slowly, and payload space is tiny, and Digispark boards use a fixed, well-known VID/PID that is trivial to blocklist. Two footnotes: Hak5 never publishes the microcontroller, though its own DFU recovery instructions give it away as an AT32UC3B1512; and the shop has carried backorder notices with multi-month batch queues.","released":"2022","aliases":["Rubber Ducky","Ducky","USB Rubber Ducky Mark II","Ducky 2022"],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","usb_exfil":"yes","usb_payload_lang":"yes","usb_keylogger":"no","hid_remote_trigger":"partial","usb_ethernet_attack":"no","cloud_c2":"no","sd_logging":"yes","scriptable":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"high","notes":"Owning one is legal essentially everywhere - it is a keyboard."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-09","app_store":"Yes - the official payload repository is the largest in the category at nearly 6,000 stars, plus the Hak5 Payload Hub","abandoned_risk":"low"}},{"id":"usb-rubber-ducky-pro","hardware_id":"usb-rubber-ducky-mk2","name":"USB Rubber Ducky Pro Bundle","firmware":"DuckyScript 3.0 firmware","firmware_kind":"stock","vendor":"Hak5","category":"usb-hid","subcategory":"keystroke-injection","status":"available","price_usd":110.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Same device as the base model.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"Not a distinct device. This is the mid-tier purchase option for the USB Rubber Ducky, bundling the same 2022 hardware with Hak5's PayloadStudio Pro subscription and learning material. It is listed here because it appears on spreadsheets and price lists as though it were a separate product.","honest_take":"There is no Pro hardware. If a comparison table shows 'USB Rubber Ducky Pro' as a device with unknown specs, that is a data-entry artefact from Hak5's Shopify variant names. The only decision is whether $10 for PayloadStudio Pro bundled at purchase is worth it to you - PayloadStudio Pro is $60 bought separately, so as a bundle it is cheap, but the free tier of PayloadStudio compiles DuckyScript 3 perfectly well for most people. Merge this row into the base USB Rubber Ducky on any comparison you publish.","released":"2022","aliases":["Rubber Ducky Pro","USB Rubber Ducky Pro Bundle"],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","usb_exfil":"yes","usb_payload_lang":"yes","sd_logging":"yes","scriptable":"yes","cloud_c2":"no"},"legal":{"risk_level":"high","notes":"Identical to the standard USB Rubber Ducky."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-09","app_store":"Yes - shared with the standard model","abandoned_risk":"low"}},{"id":"themakercat-usb-snake-box","hardware_id":"themakercat-usb-snake-box","name":"USB Snake Box","firmware":"USB Snake Box firmware","firmware_kind":"diy","vendor":"The Maker Cat","category":"usb-hid","subcategory":"badusb-board","status":"out-of-stock","price_usd":38.74,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Four physical buttons map to four pre-set payload scripts; editing them means dropping a new ducky-script-style text file onto the exposed mass-storage volume.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A four-button CircuitPython BadUSB board in a 3D-printed enclosure: it enumerates as both a keyboard and a flash drive, and each of its four buttons fires a different pre-loaded keystroke-injection script, which the vendor describes as reading directly from ducky-script-style text files.","honest_take":"This is a hobbyist Tindie project, not a maintained product - its own GitHub repo has no real documentation beyond a title and five commits, and the seller's storefront is currently on a break with no listed return date. The core idea (multi-button physical payload selection on a CircuitPython board that also exposes mass storage) is genuinely useful and distinct from most single-payload sticks in this batch, but buyers should expect to read the source directly rather than rely on docs, and should not assume this is currently purchasable.","released":"2018","aliases":[],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"yes","usb_exfil":"unknown","usb_keylogger":"no","hid_remote_trigger":"no","usb_payload_lang":"yes","scriptable":"yes","standalone_untethered":"yes","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning the device is legal."},"ecosystem":{"community":"dormant","docs_quality":"poor","last_release":"unknown - GitHub repo shows 5 commits with no visible dates in available sources","app_store":"No","abandoned_risk":"high"}},{"id":"usbkeylogger-push3ax","hardware_id":"usbkeylogger-push3ax","name":"USBKeylogger","firmware":"Stock (Push3AX)","firmware_kind":"diy","vendor":"Push3AX","category":"usb-hid","subcategory":"hardware-keylogger","status":"diy-only","price_usd":12.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Requires SMD soldering (or a PCB assembly service) and flashing ESP8266 firmware; no case design or enclosure is provided.","build_effort":"full-diy","stealth":"covert","form_factor":"cable","summary":"A hardware keystroke logger built around an ESP8266 (ESP-07S) module that sits inline between a USB keyboard and the host, invisible to host-side antivirus because the capture happens entirely in hardware before the OS ever sees it. It logs to 3MB of onboard flash in a circular buffer and can push AES-128-encrypted keylogs over its own Wi-Fi to ntfy.sh or a custom HTTP endpoint; a bundled offline HTML tool decrypts the payload. Ships as Gerbers/BOM only, in a compact inline form or a USB-hub form where only the bottom port logs.","honest_take":"'Invisible to antivirus' is true only for the host machine - the device broadcasts its own open Wi-Fi access point (default SSID USBKeylogger_XXXXXX) by default, which is a dead giveaway to anyone running a Wi-Fi scanner nearby, and unless you self-host an ntfy server, the public ntfy.sh relay only retains pushed logs for 3 hours. This is a real wiretapping device, not a 'pentest gadget' in the softened sense the README's framing implies - installing it on hardware you don't own or aren't explicitly authorized to monitor is a criminal offense almost everywhere (see legal notes), regardless of how the project markets itself.","released":"2023","aliases":[],"capabilities":{"usb_keylogger":"yes","usb_hid_inject":"no","usb_mass_storage":"no","web_ui":"yes","wifi_ap_mode":"yes","wifi_scan_24":"partial","cloud_c2":"yes","sd_logging":"no","standalone_untethered":"yes","scriptable":"no","app_store":"no"},"legal":{"risk_level":"high","notes":"Hardware keyloggers that capture keystrokes without the device owner's and user's consent implicate wiretapping/interception law in most jurisdictions (e."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2026-06","app_store":"No","abandoned_risk":"medium"}},{"id":"usbkill-v4","hardware_id":"usbkill-v4","name":"USBKill V4","firmware":"Stock","firmware_kind":"stock","vendor":"USBKill","category":"usb-hid","subcategory":"destructive-tester","status":"available","price_usd":85.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Trivially easy to use, which is exactly the problem.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A device that harvests power from a USB port, multiplies the voltage and dumps it back into the data lines, destroying unprotected hardware. The V4 adds an internal battery so it works on powered-off devices, plus BLE remote, timer and magnet triggers, and adapters for Lightning, USB-C, Ethernet, HDMI and DisplayPort.","honest_take":"Be clear what this is: it is not a pentest tool, it is a destruction tool. It reads nothing, proves nothing about software security, and the only legitimate use is deliberately stress-testing port protection on hardware you own or manufacture. The covert triggers (magnet, timer, BLE) exist because customers want to destroy things without being seen doing it, and in most jurisdictions using one on someone else's equipment is criminal damage with an unusually clear evidence trail. Also note it can wreck the port, the motherboard, or an entire industrial system in one press.","released":"2021","aliases":["USB Killer","USB Kill"],"capabilities":{"usb_hid_inject":"no","usb_mass_storage":"no","hid_remote_trigger":"yes","hardware_destruct":"yes"},"legal":{"risk_level":"high","notes":"Owning it is legal in most places and it is openly sold."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"n/a","app_store":"No","abandoned_risk":"low"}},{"id":"usbninja-professional","hardware_id":"usbninja","name":"USBNinja Professional","firmware":"USBNinja embedded framework","firmware_kind":"stock","vendor":"RFID Research Group / Sneak Technology","category":"usb-hid","subcategory":"malicious-cable","status":"out-of-stock","price_is_estimate":false,"skill_level":"intermediate","skill_note":"Payload authoring is Arduino-style rather than DuckyScript.","build_effort":"assembled","stealth":"covert","form_factor":"cable","summary":"A BadUSB implant built into an ordinary-looking charge/data cable, triggered wirelessly from a Bluetooth remote at up to about 50 m. It predates and directly competes with the O.MG Cable, offering eight payload slots and a fast-charge-capable cable that works normally until triggered.","honest_take":"Do not buy this without checking the vendor first. As of this research the usbninja.com front page is stuffed with hundreds of injected spam links - a site that has been compromised and left that way - the store redirects to a third party that did not respond, and the firmware repository has not seen meaningful work since 2023. The O.MG Cable is the maintained product in this category now. Listed here as a warning, not a recommendation: a compromised vendor is not somewhere to send your card details, let alone buy an implant you intend to plug into a client's machine.","released":"2018","aliases":["USB Ninja","USBNinja Pro"],"capabilities":{"usb_hid_inject":"yes","hid_remote_trigger":"claimed","usb_payload_lang":"partial","usb_mass_storage":"partial"},"legal":{"risk_level":"high","notes":"A cable designed to look innocuous while injecting keystrokes is close to the definition of a covert intrusion device."},"ecosystem":{"community":"dormant","docs_quality":"poor","last_release":"2023","app_store":"No","abandoned_risk":"high"}},{"id":"ks-elektronikdesign-usbsafe2","hardware_id":"ks-elektronikdesign-usbsafe2","name":"UsbSafe2","firmware":"UsbSafe2 firmware (C, MikroC)","firmware_kind":"diy","vendor":"KS Elektronikdesign","category":"accessory","subcategory":"usb-data-blocker","status":"available","price_usd":39.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Single button controls both data-blocking and current-threshold settings via press-and-hold timing and LED flash counts, explained in the included manual.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A defensive inline USB dongle, not an attack tool: it sits between your device and an untrusted host or charger, and lets you cut the USB data lines entirely ('anti-juice-jacking' data integrity mode) while separately capping current at one of five selectable thresholds (0.5-2.4A) and hard-clamping over-voltage at 6.5V to protect against a faulty or malicious power source.","honest_take":"This solves a real, narrow problem - juice-jacking and dodgy charging ports - and does it with genuinely open, inspectable hardware (schematic, PCB layout and firmware are all public), which is more than most of the covert attack tools in this batch can say. It is not a general USB firewall: it does nothing against a device that already has a valid, unblocked data connection, and the over-voltage protection is fixed at 6.5V by hardware, not adjustable. It occupies the same defensive niche as the O.MG UnBlocker already in this database; UsbSafe2 predates it by years and adds current/voltage protection that the UnBlocker doesn't claim, but doesn't have the UnBlocker's more polished branding or O.MG ecosystem integration.","released":"2017","aliases":["UsbSafe squared","USBSafe2"],"capabilities":{"usb_mass_storage":"no","usb_hid_inject":"no","usb_exfil":"no","usb_keylogger":"no","scriptable":"no","standalone_untethered":"yes","app_store":"no"},"legal":{"risk_level":"low","notes":"A purely defensive device with no offensive capability; no legal concerns beyond ordinary product safety/CE-type compliance for a USB power-path device."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2017-03 (per the Crowd Supply project's last posted update)","app_store":"No","abandoned_risk":"medium"}},{"id":"usbvalve","hardware_id":"usbvalve","name":"USBvalve","firmware":"USBvalve 1.0.x","firmware_kind":"diy","vendor":"cecio (open source; no assembled unit sold)","category":"detection-defense","subcategory":"usb-threat-detector","status":"diy-only","price_usd":6.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Flashing the pre-built .uf2 is trivial (drag-and-drop bootloader); building the hardware (Pico + OLED, optional custom PCB or 3D-printed spacer) takes basic soldering or careful breadboarding.","build_effort":"soldering","stealth":"discreet","form_factor":"board","summary":"A Raspberry Pi Pico (RP2040) inline USB inspection tool: in device mode it presents a fake filesystem and shows on an OLED whether a connected host is reading or writing files (catching mass-storage-based exfiltration or drops); from v0.8.0 it can also run in USB host mode to detect a plugged-in device behaving like a keyboard (catching HID-injection BadUSB before you trust it). It is the defensive counterpart to the various BadUSB sticks and cables tracked elsewhere in this database.","honest_take":"USBvalve only sees what happens on the USB link it's actually sitting on - it flags file reads/writes to its fake filesystem, or a newly-plugged device announcing itself as a keyboard, and nothing else. It offers no protection against a device that behaves normally at the USB protocol level but is malicious in its payload (e.g., a legitimate-looking flash drive with a booby-trapped file you open yourself), and it has no shielding, so it is explicitly not a tool for safely testing USB Killer-style devices. It's a genuinely well-regarded open-source project (1.3k GitHub stars) with an unusually direct answer to 'is this random USB stick doing something to my computer right now,' which most of the flashier commercial BadUSB-detector gadgets don't actually provide as clearly.","aliases":[],"capabilities":{"usb_mass_storage":"partial","scriptable":"yes","standalone_untethered":"yes","usb_hid_inject":"no","usb_keylogger":"no","usb_exfil":"no","usb_ethernet_attack":"no","hid_remote_trigger":"no","wifi_scan_24":"no","ble_scan":"no","web_ui":"no","cloud_c2":"no","app_store":"no"},"legal":{"risk_level":"low","notes":"Purely defensive/diagnostic tool; legal to build, own, and use everywhere."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-08-19","app_store":"No","abandoned_risk":"low"}},{"id":"vicino","hardware_id":"vicino","name":"VICINO","firmware_kind":"diy","vendor":"MCQN Ltd","category":"rfid-nfc","subcategory":"rfid-module","status":"available","price_usd":40.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The board itself is a drop-in SPI reader IC, but you must wire it to your own host MCU and build firmware around MCQN's own library forks rather than a mature, widely documented SDK.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"VICINO is a bare SPI breakout board built around ST's ST25R3916B multi-protocol 13.56MHz NFC/RFID reader IC, designed by UK studio MCQN Ltd as a mechanically and electrically compatible upgrade path for projects built around cheap MFRC522 (RC522) modules. It was originally developed for MCQN's own Museum in a Box v2.0 project, ships assembled and OSHWA-certified (UK000061), and pairs with MCQN's forked ST NFC-RFAL/ST25R3916 Arduino libraries running on an ESP32 host.","honest_take":"This is not a pentest tool - it's a better-spec'd reader chip in an RC522-shaped footprint, built for a museum tag-reading kiosk, not for card attacks; don't expect Mifare Classic cracking or Flipper-style attack menus out of the box. You still bring your own host MCU, wire SPI yourself, and build firmware against a small (11-star), still-thin-on-docs library fork rather than a mature SDK. At $40 for a chip that street-prices around $8-12 bare from distributors, the premium buys the antenna-tuned PCB, RC522 pin/hole compatibility and OSHW documentation - reasonable if that compatibility saves you a redesign, questionable if you're just comparing raw part cost.","released":"2024","aliases":[],"capabilities":{"hf_1356_read":"yes","hf_1356_write":"claimed","hf_1356_emulate":"claimed","iso15693":"yes","felica":"yes","mifare_classic_attacks":"unknown","mifare_desfire":"unknown","nfc_type4_ndef":"unknown","emv_read":"no","nfc_relay":"no","lf_125khz_read":"no","lf_125khz_write":"no","lf_125khz_emulate":"no","scriptable":"yes","standalone_untethered":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"VICINO is a general-purpose 13."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"2026-03","app_store":"n/a","abandoned_risk":"low"}},{"id":"vidar-attiny85-badusb","hardware_id":"vidar-attiny85-badusb","name":"Vidar ATtiny85-based BadUSB","firmware":"Stock demo payload","firmware_kind":"diy","vendor":"rot13labs","category":"usb-hid","subcategory":"badusb-stick","status":"out-of-stock","price_usd":20.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-run for the stock demo payload; editing the payload requires installing the Arduino IDE and an ATtiny85/Digispark board profile.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"A minimal, very small ATtiny85-based BadUSB stick that enumerates as a USB keyboard and fires a pre-programmed keystroke payload on plug-in. Functionally the same class of device as a Digispark BadUSB or the low end of the Evil Crow Cable line, built by a different one-person hardware shop (rot13labs, Gainesville FL).","honest_take":"This is a Digispark-class ATtiny85 keystroke injector in tiny packaging, nothing more. The ATtiny85 has no native USB peripheral, so it almost certainly relies on V-USB (bit-banged software USB), which caps HID reliability and speed well below a real USB-HID microcontroller like the ATmega32U4 in a Rubber Ducky. There's no storage for multiple payloads and no way to trigger a different script without physically re-flashing it from a computer - you get exactly one script running until you reprogram it. At $20 for a fixed single-payload stick, it is priced like a novelty, not a tool; a $5 Digispark clone running the same class of open-source ATtiny85 BadUSB sketch does the identical job.","aliases":["Vidar BadUSB"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"claimed","scriptable":"yes","usb_mass_storage":"no","usb_ethernet_attack":"no","usb_keylogger":"no","usb_exfil":"no","hid_remote_trigger":"no","web_ui":"no","standalone_untethered":"yes","cloud_c2":"no","wifi_scan_24":"no","ble_scan":"no","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning and building the device is legal essentially everywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"high"}},{"id":"wardriver-uk-rev3","hardware_id":"wardriver-uk-rev3","name":"wardriver.uk Rev3","firmware":"Wardriver Rev3 Firmware","firmware_kind":"community","vendor":"Joseph Hewitt (independent open-source project)","category":"wardriving","subcategory":"esp32-wardriving-rig","status":"available","price_usd":50.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You are wiring two separate ESP32 dev boards, a GPS module, an optional SIM800L cellular module, an I2C OLED, and a temperature sensor by hand — a genuine electronics-assembly project, not a flash-and-go kit, unless you pay extra for a pre-assembled unit from a third party.","build_effort":"soldering","stealth":"discreet","form_factor":"box","summary":"An open-source, dual-ESP32-WROOM-32U wardriving rig: one ESP32 handles WiFi scanning, the other handles Bluetooth/BLE scanning plus peripherals (ATGM336H GPS, optional SIM800L cellular module, SSD1306 OLED status display, DS18B20 temperature sensor). Everything logs to a microSD card as WiGLE-format CSV, with the current firmware able to upload directly to WiGLE.net. Joseph Hewitt publishes schematics, Gerbers and firmware on GitHub under GPL-3.0; the bare PCB is normally sold via Tindie, with DIY kits and assembled units available from independent third-party resellers.","honest_take":"Confirmed as a genuinely distinct project from the 'C5 Wardriver' already in this database, not the same thing under a different name: this rig splits WiFi and Bluetooth scanning across two separate, older ESP32-WROOM-32U modules (2.4GHz-only silicon) rather than one newer single-chip solution, a deliberate architectural choice, not an oversight. It requires real through-hole soldering unless you pay a third-party reseller extra for a pre-built unit — the original creator's own bare-PCB Tindie listing is currently paused and won't ship to the US, so US buyers are pushed toward third-party kits by default. The firmware is unusually healthy for a single-maintainer hobby project: 368 GitHub stars, 40 forks, and commits into 2026 (OTA updates, direct WiGLE upload, a NimBLE migration for Bluetooth). But this is not a flash-only device — budget real assembly time and a soldering iron, or pay significantly more for someone else's assembled unit.","aliases":["Wardriver Rev3","Portable ESP32 Wardriver","JHewitt Wardriver"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_wardriving":"yes","gps":"yes","gps_wardrive_log":"yes","sd_logging":"yes","ble_scan":"yes","bt_classic":"unknown","web_ui":"yes","standalone_untethered":"yes"},"legal":{"risk_level":"low","notes":"This is a passive scanner and logger — it does not transmit attacks, jam, or inject packets, so legal exposure is much lower than most devices in this database."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-05","app_store":"No","abandoned_risk":"low"}},{"id":"wardriver3000","hardware_id":"wardriver3000","name":"wardriver3000","firmware":"wardriver3000 firmware","firmware_kind":"diy","vendor":"CiferTech (open-source project, not sold)","category":"wardriving","subcategory":"gps-wifi-logger","status":"diy-only","price_usd":30.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"You fabricate the author's custom PCB yourself (Altium source files only - most hobbyists will need Altium's free viewer, not their usual KiCad workflow, just to inspect it) and hand-solder an ESP32, GPS module, OLED and SD breakout to it, then compile Arduino code with pins hardcoded in the .ino rather than a config file.","build_effort":"soldering","stealth":"discreet","form_factor":"pocket","summary":"wardriver3000 is a solo hobbyist's open-source ESP32 + GPS + OLED wardriving rig on a custom PCB: it scans nearby Wi-Fi networks, tags them with a GPS fix, and appends the results to a CSV file on a microSD card. It's a from-scratch build - custom board, 3D-printed case, no assembled version - for people who want to build their own wardriving hardware rather than buy one.","honest_take":"The GitHub repo has had zero commits since April 28, 2024 - over two years before this was written - and a basic 'can you give the gpio pins for this project' issue from mid-2024 sits open and unanswered, so treat this as a frozen snapshot, not a maintained project. More importantly, despite the README's framing around uploading to Wigle.net, the actual firmware writes a custom CSV (BSSID, SSID, capabilities, RSSI, channel, lat, lng, then three hardcoded zeros for altitude/accuracy/type) with no WigleWifi-1.4 header line at all - that's not the format WiGLE's own importer expects, so you'd need to reformat the file yourself before uploading, something the README never mentions. The scanning itself is also just the stock Arduino WiFi.scanNetworks() station-mode call - the same thing any $5 ESP32 dev board can do - not a promiscuous-mode capture; nothing here actually needed the custom PCB except tidiness. For similar money and real solder time, JCMK's actively-maintained 'C5 Wardriver' (dual-band 2.4+5GHz plus BLE, genuine WiGLE-formatted output, updated within the last month as of this check) is the better wardriving pick if you're choosing between DIY projects, and this database's ESP32 Wardriver Pro is a more honestly-documented single-band alternative at similar build effort.","released":"2024","aliases":["Wardriver3000","Your Secret Weapon for Wireless Networks - Wardriver"],"capabilities":{"wifi_scan_24":"yes","gps":"yes","gps_wardrive_log":"partial","sd_logging":"yes","wifi_wardriving":"yes","ble_scan":"no","wifi_deauth_24":"no","wifi_injection":"no","wifi_ap_mode":"no","standalone_untethered":"yes"},"legal":{"risk_level":"low","notes":"Passive Wi-Fi scanning and GPS logging for your own reference is legal in essentially every jurisdiction - it's the same activity your phone does constantly."},"ecosystem":{"community":"dead","docs_quality":"sparse","last_release":"2024-04","app_store":"No","abandoned_risk":"already-abandoned"}},{"id":"usbarmyknife-waveshare-esp32-s3-lcd-147","hardware_id":"waveshare-esp32-s3-lcd-147","name":"Waveshare ESP32-S3 1.47in LCD (USB Army Knife)","firmware":"USB Army Knife","firmware_kind":"community","vendor":"Waveshare","category":"usb-hid","subcategory":"usb-attack-platform","status":"available","price_usd":12.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Bare board with exposed circuitry on the underside - fine on a bench, conspicuous in a pocket.","build_effort":"flash-only","stealth":"discreet","form_factor":"usb-stick","summary":"A USB-A-plug ESP32-S3 board with a 1.47-inch 172x320 colour LCD, 16MB flash and 8MB of Octal PSRAM, and a microSD slot on a 4-bit bus. Under USB Army Knife it does the full platform: HID injection, mass storage, USB Ethernet and the embedded Marauder, with the best screen and most RAM of the supported dongles.","honest_take":"On paper this is the best-specified USB Army Knife board - 8MB PSRAM against the T-Dongle-S3's none, a much larger screen, and a 4-bit SD bus rather than SPI. The catch is presentation: it is a bare PCB with exposed circuitry on the underside and an acrylic front layer, so it looks like a project, not a memory stick, which undercuts the covertness that makes these tools interesting. There is no battery or charging circuit, so it only lives while plugged in. If you want the capability and do not need to hide it, this is the pick; if you need it to look innocuous, the cased ESP32-S3-GEEK or the T-Dongle-S3 are better. Watch out for the sibling models - the 1.47B adds an IMU and battery charging, and a separate Touch variant exists. The Wi-Fi side carries the usual caveat - deauth is defeated by 802.11w/PMF, which WPA3 makes mandatory - so the USB attack surface, not the radio, is the reason to own one.","released":"2024","aliases":["Waveshare ESP32-S3 1.47","ESP32-S3-LCD-1.47"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_mass_storage":"yes","usb_ethernet_attack":"yes","usb_exfil":"yes","hid_remote_trigger":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_ap_mode":"yes","wifi_handshake_capture":"yes","packet_capture":"yes","ble_scan":"yes","bt_classic":"no","web_ui":"yes","sd_logging":"yes","scriptable":"yes","standalone_untethered":"no","subghz_rx":"no","jtag_swd":"no"},"legal":{"risk_level":"high","notes":"A generic development board by itself, but running USB Army Knife it is a HID injection tool."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-02","app_store":"No - DuckyScript payloads","abandoned_risk":"low"}},{"id":"usbarmyknife-waveshare-esp32-s3-geek","hardware_id":"waveshare-esp32-s3-geek","name":"Waveshare ESP32-S3-GEEK (USB Army Knife)","firmware":"USB Army Knife","firmware_kind":"community","vendor":"Waveshare","category":"usb-hid","subcategory":"usb-attack-platform","status":"available","price_usd":9.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Hold the button while plugging in to enter flashing mode. The SD card compatibility problem is a real early hurdle.","build_effort":"flash-only","stealth":"covert","form_factor":"usb-stick","summary":"A $10 ESP32-S3 in a finished white USB-stick case with a 1.14-inch LCD, a microSD slot and three side-facing JST ports breaking out UART, GPIO and I2C. Under USB Army Knife it is a HID injector, mass storage device and USB network adapter with a screen for status or theatre.","honest_take":"The cheapest cased option with both a screen and an SD card, which makes it good value - but the SD card slot is genuinely troublesome. USB Army Knife's own README documents compatibility and speed problems and reports needing a specific Kingston card with an undersized partition to get it working, so budget time for that. It has 2MB PSRAM rather than the 8MB on Waveshare's 1.47-inch board, which matters for buffering. One thing to be clear about: unlike its RP2040 sibling, this board has NO SWD debug port - the three JST sockets are UART, plain GPIO and I2C, so it is not a hardware-debug tool. Also note Waveshare's own marketing calls it 'ESP32-GEEK' in body text while the part number is ESP32-S3-GEEK; there is no separate ESP32-GEEK product. The embedded Marauder fork gives it Wi-Fi attacks too, subject to the usual limit: deauth only works where management frames are unprotected, so 802.11w/PMF defeats it and WPA3 mandates PMF.","released":"2024","aliases":["Waveshare ESP32-GEEK","ESP32-S3-GEEK"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_mass_storage":"partial","usb_ethernet_attack":"yes","usb_exfil":"yes","hid_remote_trigger":"yes","wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"yes","wifi_ap_mode":"yes","ble_scan":"yes","bt_classic":"no","web_ui":"yes","sd_logging":"partial","uart":"yes","i2c":"yes","jtag_swd":"no","scriptable":"yes","standalone_untethered":"no","subghz_rx":"no"},"legal":{"risk_level":"high","notes":"A generic $10 development board on its own, but running USB Army Knife it becomes a HID injection tool, and plugging one into a machine you are not authorised to use is unauthorised access under computer-misuse law in most countries."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-02","app_store":"No - DuckyScript payloads","abandoned_risk":"low"}},{"id":"usbarmyknife-waveshare-rp2040-geek","hardware_id":"waveshare-rp2040-geek","name":"Waveshare RP2040-GEEK (USB Army Knife)","firmware":"USB Army Knife","firmware_kind":"community","vendor":"Waveshare","category":"usb-hid","subcategory":"usb-attack-platform","status":"available","price_usd":8.99,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Hold the button while plugging in for flashing mode. On Windows you may need to set a WinUSB driver with Zadig.","build_effort":"flash-only","stealth":"covert","form_factor":"usb-stick","summary":"A Raspberry Pi RP2040 in a USB-stick case with a 1.14-inch LCD, a microSD slot, and UART, I2C/ADC and SWD debug ports. Waveshare sells it as a CMSIS-DAP debug probe. USB Army Knife runs on it for HID injection, but it has no radio of any kind.","honest_take":"Read the radio line twice: this is an RP2040, which contains no Wi-Fi and no Bluetooth silicon whatsoever, so every wireless feature of USB Army Knife is gone - no web interface control, no Wi-Fi exfiltration, no embedded Marauder. The README says so outright. USB Ethernet (NCM) and whole-disk SD use are also unsupported here. What you get is offline HID injection from a stick that must be physically retrieved. Its actual best use is arguably the one Waveshare designed it for: at $8.99 it is a CMSIS-DAP SWD debugger with an LCD and an SD slot, which undercuts the official Raspberry Pi Debug Probe and is a legitimately useful hardware-hacking tool - just not a wireless one.","released":"2024","aliases":["RP2040-GEEK"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","usb_mass_storage":"partial","usb_ethernet_attack":"no","usb_exfil":"partial","hid_remote_trigger":"no","wifi_scan_24":"no","wifi_deauth_24":"no","ble_scan":"no","bt_classic":"no","web_ui":"no","jtag_swd":"yes","uart":"yes","i2c":"yes","sd_logging":"yes","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"medium","notes":"Lower risk than its ESP32 siblings for a practical reason: with no radio it cannot deauth, cannot host a rogue AP and cannot exfiltrate wirelessly, so several of the offences the other boards enable are simply off the table."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2026-02","app_store":"No - DuckyScript payloads","abandoned_risk":"low"}},{"id":"whidboard-pro","hardware_id":"whidboard-pro","name":"WHIDBoard Pro","firmware":"Custom","firmware_kind":"stock","vendor":"WHID (Luca Bongiorni)","category":"hardware-debug","subcategory":"hardware-audit-platform","status":"available","price_usd":325.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"It removes tooling friction, not the need to know UART/SPI/JTAG work.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"An all-in-one hardware-auditing bench board from Luca Bongiorni: multiple selectable logic levels, automated pin enumeration to discover unknown interfaces, an 8-channel logic analyser, and integration with Tsurugi Linux so the software side is a known-good environment rather than a pile of half-working Python.","honest_take":"You are paying for integration, not unique silicon - a Bus Pirate 5 (about EUR 59), a Tigard and a cheap logic analyser cover most of the same ground for a third of the price, at the cost of your time and a drawer of adapters. The vendor does not publish the MCU or the interface chips, and there is no open repository, so you are trusting the brand. Worth it if your billable hours cost more than the board; hard to justify for hobby use.","released":"2023","aliases":["WHID Board","WHIDBoard"],"capabilities":{"uart":"yes","spi_flash_dump":"yes","i2c":"yes","jtag_swd":"claimed","logic_analyzer":"yes","glitching":"no"},"legal":{"risk_level":"low","notes":"Bench debug equipment; legal to own and use."},"ecosystem":{"community":"slow","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"medium"}},{"id":"wican","hardware_id":"wican","name":"WiCAN","firmware":"Stock WiCAN firmware","firmware_kind":"stock","vendor":"MeatPi Electronics","category":"automotive","subcategory":"obd2-can-interface","status":"available","price_usd":42.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Simple enough for enthusiasts using RealDash/SavvyCAN, but effective CAN work still requires understanding the target vehicle's bus.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"An ESP32-C3-based CAN-to-Wi-Fi/BLE bridge sold as either an OBD-II dongle (WiCAN-OBD) or a bare USB/screw-terminal board (WiCAN-USB), supporting CAN 2.0 A/B up to 1 Mbit/s with a built-in web interface for Wi-Fi/CAN configuration, an AP-or-station Wi-Fi mode, MQTT battery-voltage alerts, and a sub-1mA sleep mode triggered by low bus voltage. It works with RealDash, SavvyCAN, BUSMaster, and python-can/SocketCAN, and there's also a browser-based Web-CAN client that talks to it over WebSocket or WebUSB with no native app at all.","honest_take":"At $42 for either form factor, this is one of the cheapest actively-maintained CAN-to-Wi-Fi bridges around (770 GitHub stars, commits within the last day as of this writing) - but it is CAN 2.0 only with no galvanic isolation and no CAN-FD, so treat it as a telemetry/convenience tool for your own vehicle rather than a lab-grade interface. For CAN-FD, step up to WiCAN Pro or panda; for isolation, step up to CANable Pro.","released":"2022","aliases":["WiCAN-OBD","WiCAN-USB"],"capabilities":{"packet_capture":"yes","scriptable":"yes","web_ui":"yes","wifi_ap_mode":"yes","ble_scan":"no","app_store":"no","sd_logging":"no","standalone_untethered":"yes","cloud_c2":"no","usb_mass_storage":"no","uart":"no","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","can_sniff":"yes","can_inject":"yes","can_fd":"no","can_isolated":"no","obd2":"partial"},"legal":{"risk_level":"low","notes":"A diagnostics/telemetry-focused CAN interface; legal to own and use on a vehicle you own or are authorized to test."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-09","app_store":"No","abandoned_risk":"low"}},{"id":"wican-pro","hardware_id":"wican-pro","name":"WiCAN Pro","firmware":"Stock WiCAN firmware","firmware_kind":"stock","vendor":"MeatPi Electronics","category":"automotive","subcategory":"obd2-can-interface","status":"preorder","price_usd":89.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Designed to be usable by car enthusiasts with common OBD apps, but its dual-UART dev features and Home Assistant integration reward more technical users.","build_effort":"assembled","stealth":"discreet","form_factor":"box","summary":"An ESP32-S3-based OBD-II scanner built around a dedicated (unnamed by the vendor) OBD interpreter chip that covers all legislated OBD-II protocols in one device: ISO 15765-4 CAN, SAE J1939 CAN, ISO 11898 raw CAN, Medium-Speed CAN (MS-CAN), GM High-Speed CAN, Single-Wire CAN (GMLAN), plus the legacy K-line protocols SAE J1850-PWM/VPW, ISO 9141-2, and ISO 14230-4. It emulates ELM327 v2.3, ELM329 v2.2, STN, and VT instruction sets (so it works with Car Scanner, Torque, OBD Auto Doctor, BimmerCode, OBD Fusion, etc.), integrates directly with Home Assistant with no companion app required, and adds a USB-C flashing port, microSD logging, a wake-on-motion accelerometer, and a USB host port for optional LTE/GPS modules on top of the base WiCAN feature set.","honest_take":"The protocol coverage genuinely is broad - MeatPi's own comparison table shows it matching or beating a $150+ OBDLink MX+ on paper - but CAN-FD is never mentioned anywhere in the spec sheet despite being increasingly common on 2021+ vehicles, and there's no claim of galvanic isolation either, so this is a convenience/diagnostics tool for your own vehicle's OBD-II port, not a lab-grade isolated interface for bench work on a live harness. The 'cannot be powered via USB-C' caveat catches people off guard too: you can't bench-test it from a USB power brick, only from a vehicle or an OBD-II 12V breakout.","released":"2024","aliases":[],"capabilities":{"packet_capture":"yes","scriptable":"yes","web_ui":"yes","app_store":"no","cloud_c2":"no","sd_logging":"yes","standalone_untethered":"yes","gps":"addon","usb_mass_storage":"no","uart":"partial","spi_flash_dump":"no","i2c":"no","jtag_swd":"no","logic_analyzer":"no","glitching":"no","can_sniff":"yes","can_inject":"yes","can_fd":"no","can_isolated":"no","lin_bus":"no","obd2":"yes"},"legal":{"risk_level":"low","notes":"A diagnostics-focused OBD-II scanner; legal to own and use on a vehicle you own or are authorized to diagnose."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-09","app_store":"No","abandoned_risk":"low"}},{"id":"wiebetech-drive-erazer","hardware_id":"wiebetech-drive-erazer","name":"WiebeTech Drive eRazer","vendor":"CRU / WiebeTech","category":"accessory","subcategory":"forensic-drive-wiper","status":"out-of-stock","price_usd":330.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"LCD-menu driven, no computer needed; picking the wrong erase mode for your compliance needs is the main user risk.","build_effort":"assembled","stealth":"overt","form_factor":"desktop","summary":"A standalone appliance that wipes bare SATA (2.5\"/3.5\") and PATA/IDE 3.5\" drives (with 1.8\" ZIF/IDE adapters) at native interface speed without a computer, claiming roughly 7GB/min on modern drives and 2GB/min on older ones, with an LCD menu of preconfigured erase modes and automatic label printing support.","honest_take":"The Hacker Warehouse listing for this base 'Drive eRazer' model does not name a specific wipe standard (no DoD 5220.22-M or NIST 800-88 language on that page) — those named standards (DoD SANITIZE, NIST 800-88 Clear/Purge, 12 erase modes) are documented for CRU's higher-end 'Drive eRazer Ultra' model, a different, later product. Don't assume this base model meets a specific compliance standard unless CRU's own datasheet for this exact model says so; if a specific certification matters for your audit trail, verify directly with CRU/WiebeTech before relying on it. Also: no wipe, from any vendor, defeats a drive-level SSD wear-leveling reserve — for SSDs, ATA Secure Erase or the drive's own sanitize command is generally the more defensible method, and this appliance's marketing doesn't distinguish HDD from SSD behavior.","aliases":[],"capabilities":{"usb_mass_storage":"no","standalone_untethered":"yes","scriptable":"no","sd_logging":"no","cloud_c2":"no","usb_hid_inject":"no","drive_wipe":"yes"},"legal":{"risk_level":"low","notes":"Legal to own and use for authorized data disposal or asset decommissioning."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"wiebetech-forensic-combodock-v5","hardware_id":"wiebetech-forensic-combodock-v5","name":"WiebeTech Forensic ComboDock v5","vendor":"CRU / WiebeTech","category":"accessory","subcategory":"forensic-write-blocker","status":"out-of-stock","price_usd":400.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Straightforward to operate (choose write-block or read/write mode at power-on) but chain-of-custody discipline matters for the results to hold up.","build_effort":"assembled","stealth":"overt","form_factor":"desktop","summary":"A desktop forensic drive dock that forces an explicit write-blocked-or-read/write choice every time it powers on, so a forgotten mode setting can't silently let an examiner write to evidence media. It bridges SATA and Ultra ATA (IDE) drives out to FireWire 400/800, USB 3.0, and eSATA host interfaces.","honest_take":"CRU/WiebeTech's ComboDock family has a real NIST CFTT track record — NIST/DHS published hardware write-block test reports for the original 'WiebeTech Forensic ComboDock' (USB and FireWire interfaces) in 2006, and for 'WiebeTech Forensic ComboDock v6' in 2022 (Federated Testing) — but the exact revision sold here as 'v5' does not have its own dedicated NIST CFTT report in the record I could locate; the closest documented version is a 'v5.5' SKU referenced in reseller catalogs. Treat any 'this exact box is NIST-validated' claim as unverified for the v5 specifically, even though the ComboDock architecture as a family has a solid CFTT history. The vendor's own listing here makes no explicit court-admissibility or NIST claim at all — that language shows up in third-party CFTT test reports, not the product page.","aliases":["FCDv5","Forensic ComboDock"],"capabilities":{"usb_mass_storage":"yes","standalone_untethered":"no","scriptable":"no","sd_logging":"no","cloud_c2":"no","wifi_ap_mode":"no","write_block":"yes"},"legal":{"risk_level":"low","notes":"Standard, legal forensic lab equipment."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"No","abandoned_risk":"low"}},{"id":"wiegotcha","hardware_id":"wiegotcha","name":"Wiegotcha","firmware":"Custom","firmware_kind":"diy","vendor":"n/a (DIY project, no commercial vendor)","category":"rfid-nfc","subcategory":"lf-covert-capture","status":"diy-only","price_usd":130.0,"price_is_estimate":true,"skill_level":"advanced","skill_note":"The Pi wiring itself is straightforward, but success depends on sourcing and covertly disassembling/re-installing a real commercial access-control reader without detection - that's the hard part, not the electronics.","build_effort":"full-diy","stealth":"implant","form_factor":"box","summary":"Wiegotcha is a DIY Raspberry Pi 3 rig, descended from Bishop Fox's Tastic RFID Thief, meant to be built into the shell of a real commercial long-range reader (HID Maxiprox 5375, Indala ASR-620, or HID R90) so it can tap the reader's Wiegand output and log captured badge IDs to SD/CSV, viewable over a Wi-Fi access point's web page. It has no RFID radio of its own.","honest_take":"There is very little to this beyond a Raspberry Pi, a level shifter, an RTC, and careful GPIO wiring stuffed inside a donor reader shell - the actual engineering is picking a real, working long-range reader to gut and not getting caught planting it, not anything on the Pi side. It does not read RFID itself; it is entirely parasitic on the donor reader's own decode circuitry, so its real capability is whatever that reader already supports. The project is effectively dead: last commit October 2021, the install image lives on an aging Google Drive link, default root/pi passwords are literally 'Wiegotcha', and its own README lists Proxmark3 cloning as an unimplemented 'future plan' - that exact gap is what the separate Gatekeeper fork later added.","released":"2017","aliases":["Long Range RFID Thief"],"capabilities":{"lf_125khz_read":"partial","lf_125khz_write":"no","lf_125khz_emulate":"no","hf_1356_read":"partial","hf_1356_write":"no","mifare_classic_attacks":"no","standalone_untethered":"yes","wifi_ap_mode":"yes","sd_logging":"yes","web_ui":"yes","scriptable":"yes","gps":"no","packet_capture":"no","wiegand_tap":"yes"},"legal":{"risk_level":"high","notes":"Wiegotcha is purpose-built to be physically hidden inside a real commercial access-control reader to intercept badge credentials from people who have no idea it's there."},"ecosystem":{"community":"dead","docs_quality":"good","last_release":"2021-10","app_store":"n/a","abandoned_risk":"already-abandoned"}},{"id":"michalmonday-wifi-badusb","hardware_id":"michalmonday-wifi-badusb","name":"Wifi BadUSB","firmware":"supremeDuck","firmware_kind":"community","vendor":"michalmonday","category":"usb-hid","subcategory":"wifi-badusb-stick","status":"out-of-stock","price_usd":25.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Hosts its own Wi-Fi AP with a default SSID ('supremeDuck') and password for control; reflashing the ESP-12F is helped by an onboard switch the maker added specifically for that purpose.","build_effort":"assembled","stealth":"covert","form_factor":"usb-stick","summary":"An ATmega32U4 USB stick paired with an ESP-12F Wi-Fi module, hosting its own access point ('supremeDuck' by default) for wireless keystroke-injection control. It's compatible with three different open-source firmware options (supremeDuck, wifi_ducky, ESPloitV2) since its ATmega32U4+ESP-12F hardware pairing matches what all three projects target.","honest_take":"This is the direct $25 open-source ancestor of the architecture Diabolic Drive charges $115 for elsewhere in this batch: both pair an ATmega32U4 for HID injection with an ESP-series Wi-Fi chip over serial, both run DuckyScript-compatible payloads, and both host a self-controlled Wi-Fi AP. What the $115 device adds - real usable 64GB storage that works simultaneously with injection, spoofable VID/PID/serial on both personas, and an assembled/tested/supported product - is real, but so is the roughly 4.5x price gap for what is architecturally the same trick. The maker's own comparison notes the Wi-Fi version has 'occasional lag spikes in mouse movement' and is less reliable than the BLE variants, and reflashing the ESP-12F requires a NodeMCU-style flasher rather than a simple drag-and-drop. This one has been sold out since 2023, and the default AP password ('37373737') is published in the product listing, so anyone buying a used or self-built unit should change it before relying on it for anything sensitive.","aliases":[],"capabilities":{"usb_hid_inject":"yes","usb_mass_storage":"no","usb_exfil":"unknown","usb_keylogger":"no","hid_remote_trigger":"yes","usb_payload_lang":"yes","wifi_ap_mode":"yes","scriptable":"yes","standalone_untethered":"partial","app_store":"no"},"legal":{"risk_level":"medium","notes":"Owning the device is legal."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"unknown exact date; supremeDuck repo shows 155 commits and 241 stars","app_store":"No","abandoned_risk":"high"}},{"id":"wifi-coconut","hardware_id":"wifi-coconut","name":"WiFi Coconut","firmware":"WiFi Coconut userspace tools","firmware_kind":"stock","vendor":"Hak5","category":"wifi","subcategory":"full-spectrum-sniffer","status":"discontinued","price_usd":200.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"You need to already know why simultaneous multi-channel capture matters and be comfortable in Wireshark or Kismet.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A USB-C device containing fourteen separate 2.4 GHz Wi-Fi radios, one per channel, so it can record the entire 2.4 GHz band simultaneously instead of channel-hopping and missing traffic. Output is standard pcap with radiotap headers, and it plugs straight into Kismet and Wireshark.","honest_take":"It does exactly what it says and the engineering is genuinely clever - but be clear about what is inside. The radios enumerate as USB ID 148F:5370, which is the Ralink/MediaTek RT5370: a single-stream 802.11n 2.4 GHz chip that Hak5 themselves used to sell individually for $14.99. The Coconut is fourteen of those on a hub board. It is receive-only by design and Hak5 warns that transmitting may damage it and voids the warranty, so there is no injection, no deauth, no evil twin. It is 2.4 GHz only - no 5 GHz, no 6 GHz - which in 2026 means it misses most of the interesting traffic. It draws enough power that a Raspberry Pi 3 cannot run it. And the software repo has not been touched since February 2024 while the product itself has quietly left the shop navigation. Buy one secondhand only if wide-band 2.4 GHz capture is specifically your problem.","released":"2021","aliases":["Coconut","Hak5 Coconut"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"no","wifi_handshake_capture":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"partial","packet_capture":"yes","wifi_deauth_24":"no","cloud_c2":"no","standalone_untethered":"no","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"This is a receive-only device, which puts it in a materially better legal position than transmitting gear - there is no interference or impersonation question."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2024-02","app_store":"No - it works through Kismet and Wireshark","abandoned_risk":"high"}},{"id":"wifi-deauther-maltronics","hardware_id":"maltronics-wifi-deauther","name":"WiFi Deauther","firmware":"Deauther V2","firmware_kind":"community","vendor":"Maltronics","category":"wifi","subcategory":"wifi-deauther","status":"available","price_usd":46.99,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Pre-flashed, controlled entirely through a phone or laptop browser hitting the device's own web UI; no coding needed for stock use.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A sealed, pre-flashed ESP8266 board in a small metallic USB-stick case running Maltronics' fork of the open-source Spacehuhn ESP8266 Deauther v2 firmware. It scans nearby Wi-Fi networks and clients, then sends 802.11 deauthentication frames to disconnect them, plus beacon-frame and probe-request spam, all driven from a phone or laptop browser hitting its built-in web UI.","honest_take":"This is a $3-6 ESP8266 dev board running firmware that Spacehuhn/SpacehuhnTech gives away free on GitHub; Maltronics' fork adds nothing beyond the case, an RGB LED, and USB-A/USB-C wiring, so most of the ~$45 premium over a bare board buys convenience and cosmetics, not capability. It is not a jammer - it sends spoofed management frames, and those only work against networks that don't enforce 802.11w/PMF, which WPA3 makes mandatory, so it increasingly does nothing against modern APs. The case is sealed with no exposed GPIO, so unlike a bare dev board you can't repurpose it for anything else once you're done deauthing.","aliases":["Maltronics Deauther"],"capabilities":{"wifi_scan_24":"yes","wifi_injection":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"no","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","wifi_evil_twin":"no","web_ui":"yes","standalone_untethered":"partial","rgb_backlight":"yes","packet_capture":"no"},"legal":{"risk_level":"medium","notes":"Owning an ESP8266 board is legal virtually everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2022-12","app_store":"No","abandoned_risk":"medium"}},{"id":"wifi-deauther-plugplay-esp8266","hardware_id":"nodemcu-esp8266-deauther-plugplay","name":"Wifi Deauther PLUG PLAY ESP8266 v2.0","firmware":"Spacehuhn ESP8266 Deauther v2","firmware_kind":"community","vendor":"ez sellers (Tindie)","category":"wifi","subcategory":"wifi-deauther","status":"out-of-stock","price_usd":29.76,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Pre-flashed and pre-configured; connect to its 'deauther' Wi-Fi AP (default password 'deauther') and open 192.168.4.1.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A bare NodeMCU ESP8266 development board (CH340G USB-serial chip) pre-flashed with the free, open-source Spacehuhn ESP8266 Deauther v2 firmware and shipped ready to use - connect to its 'deauther' Wi-Fi AP, browse to 192.168.4.1, and you get SSID spoofing, probe-request spam, and deauthentication.","honest_take":"This is exactly a stock NodeMCU dev board - the kind sold for $3-6 on AliExpress or Amazon - running firmware that is free and open source on GitHub (SpacehuhnTech/esp8266_deauther). The seller's entire value-add is flashing it and mailing it to you; there is no custom hardware or code here. At $29.76 that's roughly a 5-8x markup over the bare board purely for skipping a 10-minute Arduino IDE flash. As of this check the seller's shop shows 'On A Break' with no stock. The underlying firmware is also showing its age - the actively developed v3 branch hasn't had a real commit since late 2022.","aliases":["ez sellers Deauther","NodeMCU Deauther v2.0"],"capabilities":{"wifi_scan_24":"yes","wifi_injection":"yes","wifi_deauth_24":"yes","wifi_deauth_5":"no","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","wifi_evil_twin":"no","web_ui":"yes","standalone_untethered":"partial","packet_capture":"no","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Owning an ESP8266 board is legal virtually everywhere."},"ecosystem":{"community":"slow","docs_quality":"good","last_release":"2022-12","app_store":"No","abandoned_risk":"medium"}},{"id":"flipper-wifi-devboard-gps-expansion","hardware_id":"flipper-wifi-devboard-gps-expansion","name":"WiFi Dev Board GPS Expansion","firmware_kind":"n/a","vendor":"Just Call Me Koko LLC","category":"wifi","subcategory":"accessory-expansion","status":"out-of-stock","price_usd":21.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"The vendor describes soldering the adapter PCB directly against the back of the Flipper Zero Wi-Fi Dev Board, joint by joint ('no wires needed') - fine hand-soldering on an already-populated board, not a beginner's first solder job.","build_effort":"soldering","stealth":"discreet","form_factor":"board","summary":"A small adapter PCB from JCMK (the ESP32 Marauder developer's company) that solders onto the back of the official Flipper Zero Wi-Fi Dev Board (an ESP32-S2 board made by Flipper Devices, which has no SD slot or GPS of its own) to add a microSD slot, a GPS receiver with ceramic antenna, and UART activity LEDs. It exists specifically to give that board's ESP32 Marauder firmware somewhere to write pcap captures and Wigle-format wardrive logs, and a GPS fix to tag them with.","honest_take":"This only makes sense if you already own three separate things: a Flipper Zero, the official ESP32-S2 Wi-Fi Dev Board (sold separately by Flipper Devices), and now this $21 adapter - plus a soldering iron. The Wi-Fi Dev Board's ESP32-S2 has no Bluetooth at all (S2 silicon lacks it) and 2.4GHz-only Wi-Fi, so this expansion doesn't add any radio capability - it only adds the storage and positioning that Marauder's wardriving and pcap-capture modes need. The 'UART activity LEDs' are exactly what they sound like: two indicator LEDs so you can tell serial traffic is flowing without hooking up a logic analyzer, not a new interface. If GPS wardriving is the actual goal rather than stacking accessories onto a Flipper you already own, JCMK's own 'C5 Wardriver' or Marauder v8 board (both already in this database) get you dual-band Wi-Fi, GPS and SD in one purchase with no soldering.","aliases":["Flipper Zero Wi-Fi Dev Board SD/GPS Adapter","WiFi Dev Board SD GPS Adapter"],"capabilities":{"gps":"yes","sd_logging":"yes","gps_wardrive_log":"addon","packet_capture":"yes","wifi_scan_24":"addon","wifi_scan_5":"no","wifi_deauth_24":"addon","wifi_monitor_mode":"addon","bt_classic":"no","ble_scan":"no","standalone_untethered":"no"},"legal":{"risk_level":"low","notes":"This is a passive storage/positioning add-on - GPS reception carries no transmission legal exposure."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":null,"app_store":"No","abandoned_risk":"medium"}},{"id":"wifi-duck","hardware_id":"wifi-duck","name":"WiFi Duck","firmware":"WiFi Duck 1.2.0-RC1","firmware_kind":"diy","vendor":"Community project (Spacehuhn Technologies)","category":"usb-hid","subcategory":"wireless-badusb","status":"diy-only","price_usd":12.0,"price_is_estimate":true,"skill_level":"intermediate","skill_note":"Only four wires to solder, but you flash two different microcontrollers with two different toolchains and then debug an I2C link between them if they do not talk.","build_effort":"soldering","stealth":"discreet","form_factor":"usb-stick","summary":"A two-chip BadUSB: an ATmega32u4 emulates a USB keyboard while an ESP8266 next to it hosts a Wi-Fi access point and web interface, so you can write, edit and fire DuckyScript payloads remotely instead of pulling the device out to reflash it. It was built as a teaching tool for keystroke injection, and the wireless part is the whole point.","honest_take":"The elephant: this project is dormant. The last code commit to the default branch was February 2022, the newest release is a release candidate from January 2022, and there are 22 open issues with nobody closing them. It still works - keystroke injection has not changed - but nothing is being fixed and no new keyboard layouts are landing, so check the layout list before you build. Also note it is genuinely just two commodity dev boards and four wires: if someone sells you a 'WiFi Duck' for $60, you are paying for a PCB and a case. And be clear about the trade-off you are making versus a plain Rubber Ducky clone: you gain remote control, and you add an ESP8266 broadcasting an access point next to the machine you are attacking.","released":"2019","aliases":["WiFiDuck","Wi-Fi Duck","Spacehuhn WiFi Duck"],"capabilities":{"usb_hid_inject":"yes","usb_payload_lang":"yes","hid_remote_trigger":"yes","usb_mass_storage":"no","usb_exfil":"partial","wifi_ap_mode":"yes","web_ui":"yes","scriptable":"yes"},"legal":{"risk_level":"medium","notes":"Owning and building it is legal."},"ecosystem":{"community":"dormant","docs_quality":"good","last_release":"2022-01","app_store":"No","abandoned_risk":"high"}},{"id":"esp32-marauder-flipper-hackerwarehouse","hardware_id":"flipper-marauder-electroniccats","name":"WiFi ESP32 Marauder for Flipper Zero","firmware":"ESP32 Marauder","firmware_kind":"community","vendor":"Hacker Warehouse","category":"wifi","subcategory":"wifi-bluetooth-audit","status":"available","price_usd":50.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Ships pre-flashed and just plugs onto the Flipper's GPIO header, but the Flipper itself must be running Momentum, Unleashed, Xtreme or RogueMaster firmware (stock firmware has no WiFi Marauder app) before this does anything.","build_effort":"assembly","stealth":"overt","form_factor":"board","summary":"An ESP32-S3 GPIO add-on that puts the free, open-source ESP32 Marauder WiFi/Bluetooth firmware behind the Flipper Zero's screen and buttons. Hacker Warehouse does not appear to manufacture this board themselves; the SKU, description text and specs match Electronic Cats' own 'Flipper Add-On: Marauder' board exactly.","honest_take":"There is no evidence Hacker Warehouse designed or builds this - the SKU (EC-WMFZ), the ESP32-S3 spec, and the product description text all match Electronic Cats' own $40 Marauder add-on word for word, and Hacker Warehouse is charging $10 more for the identical board. Unless you specifically want it bundled with Hacker Warehouse's other gear or shipping, buy direct from Electronic Cats and save $10. Beyond that, this is the same story as every Marauder board: it's a WiFi/BLE scanner and spammer, not a Flipper-native capability, deauth dies against any WPA3/PMF network, and it has no screen, battery, GPS or confirmed onboard SD of its own - it is entirely dependent on the Flipper for power, display and storage.","released":"2024","aliases":["Hacker Warehouse Flipper Marauder","EC-WMFZ"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"yes","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"unknown","wifi_beacon_spam":"yes","wifi_probe_sniff":"yes","wifi_wardriving":"no","wifi_ap_mode":"yes","packet_capture":"addon","ble_scan":"yes","ble_advertise":"yes","ble_spam_apple":"yes","ble_spam_android":"yes","ble_spam_samsung":"yes","ble_spam_swift_pair":"yes","bt_classic":"no","ble_sniff":"partial","ble_tracker_detect":"yes","ble_tracker_spoof":"yes","detect_flipper":"yes","detect_skimmer":"yes","detect_pineapple":"yes","detect_pwnagotchi":"yes","gps":"no","sd_logging":"addon","scriptable":"partial","standalone_untethered":"no","subghz_rx":"no","hf_1356_read":"no","lf_125khz_read":"no","ir_tx":"no","usb_hid_inject":"no"},"legal":{"risk_level":"medium","notes":"Owning and using it to scan/log is legal in most places."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-05","app_store":"No single app store - Electronic Cats provides a browser-based 'Marauder UI Pro' dashboard for the underlying hardware; Hacker Warehouse provides no unique docs or software of its own","abandoned_risk":"low"}},{"id":"wifi-nugget","hardware_id":"wifi-nugget","name":"WiFi Nugget","firmware":"Custom","firmware_kind":"diy","vendor":"Retia LLC (Alex Lynd)","category":"wifi","subcategory":"educational-wifi-board","status":"available","price_usd":75.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Deliberately designed as a first hardware project - through-hole soldering, a friendly shape, and workshop material written around it. That was its whole purpose.","build_effort":"assembled","stealth":"overt","form_factor":"board","summary":"A cat-shaped ESP8266 board with a small OLED and a d-pad, built by Alex Lynd as a teaching platform for Wi-Fi security and hardware soldering. It ran a family of separate sketches - Nugget Invader for deauthentication and reconnaissance, HaxxDetector for spotting Wi-Fi attacks, a packet monitor, a WiGLE wardriver - and was widely used in conference workshops and HackerBoxes kits.","honest_take":"Earlier reports that this line was dead are out of date. The original wifinugget.com domain and the DevKitty shop really are gone, which is why the project looks abandoned from the outside, but the creator moved it to Retia LLC and the WiFi, USB and Bluetooth Nuggets are all in stock and actively committed to as of September 2026. What has genuinely changed is the price: this is a $75 assembled ESP8266 teaching board, not the ~$20 DIY item it once was, and an ESP8266 running the free ESP8266 Deauther firmware costs about $6. You are paying for the case, the assembly, the curriculum and the cat.","released":"2021","aliases":["Nugget","HakCat Nugget","Nugget Invader","USB Nugget","CutieCat (successor)"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"no","wifi_deauth_24":"partial","wifi_deauth_5":"no","wifi_monitor_mode":"partial","wifi_probe_sniff":"yes","wifi_wardriving":"addon","wifi_handshake_capture":"no","detect_generic_wifi":"yes","detect_pwnagotchi":"unknown","usb_hid_inject":"addon","standalone_untethered":"partial"},"legal":{"risk_level":"medium","notes":"Owning and building it is legal, and the detector sketch is entirely passive."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2026-09","app_store":"No - separate sketches you flash individually","abandoned_risk":"medium"}},{"id":"wifi-pineapple-enterprise","hardware_id":"wifi-pineapple-enterprise","name":"WiFi Pineapple Enterprise","firmware":"WiFi Pineapple Enterprise","firmware_kind":"stock","vendor":"Hak5","category":"wifi","subcategory":"rogue-ap-platform","status":"available","price_usd":850.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"Rack-mount, mains-powered, five radios and 100+ client handling; this is scoped for consultants running multi-day engagements, not for learning.","build_effort":"assembled","stealth":"overt","form_factor":"desktop","summary":"A 1U mains-powered rack unit with five dual-band radios and eight antennas, running the same PineAP software as the Mark VII but sized for permanent or long-running installation at a client site. The selling point is Plug-and-Provision: you ship it to the client, they plug it in, and you drive the whole thing remotely through a self-hosted Cloud C2 server.","honest_take":"The hardware is real and considerably better than the Mark VII (Qualcomm IPQ4019 quad-core with two integrated radios, plus three MT7612U, 1 GB RAM, dual gigabit), but understand what the price ladder is selling. The $6600 'Pentest' tier is $850 of hardware plus a Cobalt.io consulting engagement; you are buying four consultant-days, not a better Pineapple. The $2699.99 Advanced tier's premium is TAA compliance for government procurement plus a Cloud C2 Teams licence. And the same 2026 reality check applies to all of them: Hak5's own Enterprise docs concede that Management Frame Protection 'prevents forged deauthentication packets from being respected by the client', so against a modern WPA3 or PMF-enabled estate the headline PineAP attacks largely do not land. What you are really getting is a very capable, remotely-managed, multi-radio 802.11 sensing and reporting platform.","released":"2022","aliases":["Pineapple Enterprise","WPE","Enterprise Pineapple"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_injection":"yes","wifi_deauth_24":"partial","wifi_deauth_5":"partial","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"partial","wifi_beacon_spam":"yes","wifi_karma":"partial","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","packet_capture":"yes","cloud_c2":"yes","web_ui":"yes","scriptable":"yes","app_store":"yes","standalone_untethered":"no","usb_payload_lang":"no"},"legal":{"risk_level":"high","notes":"Owning it is legal in most places; operating a rogue access point that impersonates a third party's SSID, deauthenticating clients, or capturing WPA-Enterprise credentials are each potentially separate offences."},"ecosystem":{"community":"commercial","docs_quality":"excellent","last_release":"2025-06","app_store":"Yes - shared Pineapple module system","abandoned_risk":"low"}},{"id":"wifi-pineapple-mk7-ac","hardware_id":"wifi-pineapple-mk7","name":"WiFi Pineapple Mark VII + AC","firmware":"WiFi Pineapple 7 (stock)","firmware_kind":"stock","vendor":"Hak5","category":"wifi","subcategory":"rogue-ap-platform","status":"out-of-stock","price_usd":300.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Same as the Basic, but you now have to reason about band steering, DFS channels and which interface is doing what.","build_effort":"assembled","stealth":"overt","form_factor":"box","summary":"The Mark VII Basic bundled with Hak5's MK7AC USB adapter, an MT7612U dual-band radio that adds 5 GHz scanning, monitor mode and injection. This is the configuration most people actually want, because a 2.4 GHz-only tool misses most modern corporate and home traffic.","honest_take":"This is not a different device, it is the same box with a $100 USB dongle in the port, and the dongle is an ordinary MT7612U adapter. An ALFA AWUS036ACM is the same chipset, is explicitly listed as compatible in Hak5's own docs, and is usually cheaper and easier to buy. Everything said about WPA3, PMF, MAC randomisation and HSTS blunting the Basic applies here too, and 5 GHz adds its own problem: injection is not possible on DFS channels, which is where a lot of enterprise 5 GHz traffic lives. Buying the Basic and sourcing an AWUS036ACM yourself is the pragmatic move, especially while the bundle is out of stock.","released":"2020","aliases":["MK7 AC","Pineapple Mark VII AC","MK7+AC"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_injection":"yes","wifi_deauth_24":"partial","wifi_deauth_5":"partial","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"partial","wifi_beacon_spam":"yes","wifi_karma":"partial","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","wifi_wardriving":"partial","packet_capture":"yes","cloud_c2":"yes","web_ui":"yes","scriptable":"yes","app_store":"yes","standalone_untethered":"partial","usb_payload_lang":"no"},"legal":{"risk_level":"high","notes":"Same as the Basic."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025-06","app_store":"Yes - shared with the Basic","abandoned_risk":"medium"}},{"id":"wifi-pineapple-mk7-basic","hardware_id":"wifi-pineapple-mk7","name":"WiFi Pineapple Mark VII Basic","firmware":"WiFi Pineapple 7 (stock)","firmware_kind":"stock","vendor":"Hak5","category":"wifi","subcategory":"rogue-ap-platform","status":"available","price_usd":250.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The web UI makes launching attacks trivial, but interpreting results and staying in scope requires real 802.11 knowledge.","build_effort":"assembled","stealth":"overt","form_factor":"box","summary":"A pocket-sized OpenWrt box with three dedicated 2.4 GHz radios and a web interface built around PineAP, Hak5's rogue access point suite. It exists to impersonate access points that client devices are already looking for, capture handshakes, and run captive-portal attacks. The Basic model is 2.4 GHz only.","honest_take":"The classic Pineapple attack chain has been substantially blunted since this hardware launched. WPA3 and 802.11w Protected Management Frames make forged deauthentication frames ineffective, iOS/Android/Windows all randomise MAC addresses and have largely stopped broadcasting directed probe requests for saved networks (which is what PineAP's karma attack feeds on), and HSTS plus universal HTTPS means a captive portal mostly gets you a browser warning rather than credentials. Hak5's own Enterprise documentation admits MFP 'prevents forged deauthentication packets from being respected by the client'. It is still a genuinely good and fast platform for auditing legacy WPA2 estates and open guest networks, but you are paying $250 for a single-core MIPS SoC and three cheap 2.4 GHz radios; the value is the software and the workflow, not the silicon.","released":"2020","aliases":["Pineapple MK7","Mark 7","MK7 Basic","WiFi Pineapple 7"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"addon","wifi_monitor_mode":"yes","wifi_injection":"yes","wifi_deauth_24":"partial","wifi_deauth_5":"addon","wifi_evil_twin":"yes","wifi_captive_portal":"yes","wifi_handshake_capture":"yes","wifi_pmkid":"partial","wifi_beacon_spam":"yes","wifi_karma":"partial","wifi_probe_sniff":"yes","wifi_ap_mode":"yes","wifi_wardriving":"partial","packet_capture":"yes","cloud_c2":"yes","web_ui":"yes","scriptable":"yes","app_store":"yes","standalone_untethered":"partial","usb_payload_lang":"no"},"legal":{"risk_level":"high","notes":"Owning wireless test equipment is legal in most countries."},"ecosystem":{"community":"active","docs_quality":"excellent","last_release":"2025-06","app_store":"Yes - built-in module manager plus a community package repository","abandoned_risk":"medium"}},{"id":"wifi-pineapple-pager","hardware_id":"wifi-pineapple-pager","name":"WiFi Pineapple Pager","firmware":"Pineapple Pager","firmware_kind":"stock","vendor":"Hak5","category":"wifi","subcategory":"handheld-wifi-recon","status":"available","price_usd":300.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"The on-device menu makes recon approachable, but writing useful alert payloads means writing bash.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A belt-clip, battery-powered Pineapple with a colour screen, a d-pad, a buzzer and a vibration motor. It monitors 2.4, 5 and 6 GHz, runs PineAP, fires 'alert' payloads when it sees things like a deauth flood, and logs Wigle-compatible wardrives if you add a USB GPS. It is the first Pineapple you can genuinely walk around with.","honest_take":"Hak5's marketing line that it is 'hundreds of times faster than other Pineapples' is about the radio, not the computer. The host SoC is the same MediaTek MT7628AN MIPS chip as the seven-year-old Mark VII - that is confirmed by Hak5's own published device tree file. The speed comes from a MediaTek MT7921U USB radio bolted alongside it, which is what supplies Wi-Fi 6/6E and Bluetooth. Battery life is about four hours, GPS is not included (it is a USB dongle you supply), and less than 32 MB of the internal flash overlay is free after firmware, so heavy package installs have to go to the 4 GB storage partition. Credit where due: the docs are unusually honest, stating outright that WPA3 and 802.11w PMF prevent injected disconnection packets and that injection is impossible on DFS and 6 GHz channels - 6 GHz mandates WPA3 even for 'open' networks. Buy it for tri-band recon and wardriving, not because you expect deauth to work.","released":"2025","aliases":["Pineapple Pager","Pager","WiFi Pineapple Pager"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"yes","wifi_monitor_mode":"yes","wifi_injection":"partial","wifi_deauth_24":"partial","wifi_deauth_5":"partial","wifi_evil_twin":"yes","wifi_beacon_spam":"yes","wifi_karma":"partial","wifi_probe_sniff":"yes","wifi_handshake_capture":"yes","wifi_ap_mode":"yes","wifi_wardriving":"yes","gps":"addon","gps_wardrive_log":"addon","ble_scan":"partial","bt_classic":"partial","packet_capture":"yes","cloud_c2":"unknown","web_ui":"yes","scriptable":"yes","usb_payload_lang":"partial","standalone_untethered":"yes","sd_logging":"no","app_store":"yes"},"legal":{"risk_level":"high","notes":"Portability makes this easier to misuse than a rack unit, and that cuts both ways legally."},"ecosystem":{"community":"very-active","docs_quality":"excellent","last_release":"2026-09","app_store":"Yes - official payload, theme and ringtone repos on GitHub, all pushed within the last month","abandoned_risk":"low"}},{"id":"xds110-debugger-muselab","hardware_id":"xds110-debugger-muselab","name":"XDS110 Debugger","firmware":"Stock (MuseLab)","firmware_kind":"stock","vendor":"MuseLab","category":"hardware-debug","subcategory":"jtag-swd-probe","status":"available","price_usd":15.0,"price_is_estimate":false,"skill_level":"intermediate","skill_note":"Plug-and-play with TI's own tools (Code Composer Studio, UniFlash) but using it via OpenOCD requires the usual manual target/adapter configuration.","build_effort":"assembled","stealth":"overt","form_factor":"pocket","summary":"A compact third-party debug probe implementing TI's XDS110 protocol, for debugging TI microcontrollers and DSPs - the C2000 series and ARM Cortex-A/Cortex-M parts - over JTAG, cJTAG, SWD or UART. It is meant as a cheaper alternative to TI's own XDS110-based launchpad debuggers (TI's official standalone XDS110 units, like the TMDSEMU110-U, sell well above $100) for people who already own the target board but not a spare probe.","honest_take":"TI silicon debugging is a narrow niche most general-purpose probes (Mini DAPLink, ST-Link, generic CMSIS-DAP adapters) do not cover well, so this fills a real gap at $15 rather than TI's own $100+ standalone XDS110 units. The listing does not publish which chip drives the probe itself, so treat any specific throughput claims as unverified; buy it for TI-target compatibility with CCS/UniFlash, not as a general-purpose Cortex debugger - it has no I2C or SPI flash-dumping function, and a Mini DAPLink is the better and cheaper choice for non-TI ARM targets.","released":"2023","aliases":[],"capabilities":{"jtag_swd":"yes","uart":"yes","spi_flash_dump":"no","i2c":"no","logic_analyzer":"no","glitching":"no","scriptable":"unknown","standalone_untethered":"no","app_store":"no","web_ui":"no","sd_logging":"no"},"legal":{"risk_level":"low","notes":"A bench debug probe with no radio - legal to own and use everywhere."},"ecosystem":{"community":"commercial","docs_quality":"sparse","last_release":"unknown","app_store":"No","abandoned_risk":"low"}},{"id":"yard-stick-one","hardware_id":"yard-stick-one","name":"YARD Stick One","firmware":"RfCat","firmware_kind":"stock","vendor":"Great Scott Gadgets","category":"subghz","subcategory":"sub-ghz-transceiver","status":"available","price_usd":140.0,"price_is_estimate":false,"skill_level":"advanced","skill_note":"You drive it from a Python shell and you must already know your target's modulation, data rate, deviation and encoding - it will not find them for you.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A sub-1 GHz half-duplex transceiver built on a TI CC1111 with RX and TX amplifiers, driven from Python via RfCat. It is not an SDR - it is a configurable protocol radio, which means it is far better than a HackRF at actually talking to a specific device once you know that device's radio parameters.","honest_take":"The common mistake is comparing it to a HackRF on frequency coverage and concluding it is worse. Different tool: a HackRF gives you raw samples across 6 GHz and leaves the demodulation to you, while a YARD Stick One demodulates in hardware and hands you bytes - which is dramatically more practical for actually interacting with a garage door or a sensor. The flip side is that you must know the modulation and data rate in advance, so people usually reach for an RTL-SDR or HackRF first to characterise a signal and a YARD Stick One second to talk to it. Note the official frequency ranges have gaps; the wider 'unofficial' ranges work in practice but are not guaranteed. It is also a decade old and RfCat development is slow.","released":"2014","aliases":["YS1","YardStick One","Yard Stick 1"],"capabilities":{"subghz_rx":"yes","subghz_tx":"yes","subghz_replay":"yes","subghz_rolling_code":"no","subghz_bruteforce":"yes","subghz_external_antenna":"yes","subghz_amplified":"yes","sdr_rx":"no","scriptable":"yes","standalone_untethered":"no"},"legal":{"risk_level":"high","notes":"Receiving on sub-GHz is generally lawful."},"ecosystem":{"community":"active","docs_quality":"good","last_release":"2024","app_store":"No - RfCat is a Python library and shell","abandoned_risk":"medium"}},{"id":"yubikey-neo","hardware_id":"yubikey-neo","name":"YubiKey NEO","firmware":"Yubico stock","firmware_kind":"stock","vendor":"Yubico","category":"rfid-nfc","subcategory":"hardware-auth-token","status":"discontinued","price_usd":50.0,"price_is_estimate":false,"skill_level":"beginner","skill_note":"Plug-and-play OTP out of the box; configuring PIV/OpenPGP smart-card slots needs Yubico's management tools.","build_effort":"assembled","stealth":"discreet","form_factor":"usb-stick","summary":"A discontinued (2012-2018) dual-interface USB+NFC hardware authentication token supporting Yubico OTP, OATH (TOTP/HOTP), FIDO U2F, and PIV/OpenPGP smart-card functions. It is an authentication device, not an offensive or defensive pentest tool, included here because vendors like Hacker Warehouse stock it as a cheap way to demonstrate hardware-backed authentication.","honest_take":"The single biggest thing to know: the NEO predates FIDO2/WebAuthn entirely and cannot do it - it only speaks the older FIDO U2F protocol. In 2026, passkeys and FIDO2 are what most 'phishing-resistant auth' deployments actually mean, and this device cannot fill that role no matter how it's marketed. It's a fine, cheap way to demonstrate that hardware OTP/U2F exists and what it feels like to tap a key, but if the goal is to show or use modern passkey-based authentication, a current YubiKey 5-series (or similar FIDO2 token) is the correct purchase, not this discontinued unit. It was not affected by the 2017 ROCA RSA-key-generation flaw that hit YubiKey 4 - that's one thing it has going for it.","released":"2012","aliases":["Yubico NEO"],"capabilities":{"hf_1356_emulate":"yes","usb_hid_inject":"yes","mifare_classic_attacks":"no","emv_read":"no","nfc_relay":"no","scriptable":"no","web_ui":"no","standalone_untethered":"no","ibutton_1wire":"no","magspoof":"no"},"legal":{"risk_level":"low","notes":"An authentication device with no offensive capability; owning and using it is unremarkable everywhere."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":null,"app_store":"n/a","abandoned_risk":"already-abandoned"}},{"id":"zerotrace-airleak-pro","hardware_id":"zerotrace-airleak-pro","name":"ZeroTrace AirLeak Pro","firmware":"ZeroTrace AirLeak (stock)","firmware_kind":"stock","vendor":"NetzSec (ZeroTrace)","category":"detection-defense","subcategory":"ble-wifi-counter-surveillance","status":"available","price_usd":152.0,"price_is_estimate":true,"skill_level":"beginner","skill_note":"Power it on and configure from a phone app. It is a passive scanner with no attack modes to get wrong.","build_effort":"assembled","stealth":"discreet","form_factor":"pocket","summary":"A passive dual-radio counter-surveillance logger from the German vendor NetzSec. An ESP32-S3 runs the application and the BLE radio while a dedicated ESP32-C5 co-processor sweeps 2.4 and 5 GHz Wi-Fi, so both bands and BLE are captured in parallel rather than time-sliced. It classifies BLE trackers and beacons, flags follow-me devices and privacy leaks, and logs to microSD. It has no attack modes at all.","honest_take":"'ZeroTrace' is a whole product family, not one device - EUR19.85 BadUSB kits, a EUR34.85 USB-A HID stick, a EUR54.85 USB logger and this EUR129.85 scanner - and several completely unrelated projects share the name (a Tor-routing bash script, an AI dork generator, an Intel SGX ORAM research paper), so establish which one you are actually looking at. The 5 GHz here is real silicon, a dedicated ESP32-C5, but the firmware is closed, there is no source, no teardown and no independent review anywhere, so every capability claim is the vendor's word and nothing more. It is also purely receive-only: no deauth, no injection, no attack modes, which is a design decision rather than a limitation but does mean it is not a substitute for a Ghost ESP or Bruce device.","released":"2026","aliases":["ZeroTrace","AirLeak Pro","NetzSec ZeroTrace","ZeroTrace AirLeak"],"capabilities":{"wifi_scan_24":"yes","wifi_scan_5":"claimed","ble_scan":"yes","ble_tracker_detect":"claimed","detect_airtag":"claimed","detect_tile":"claimed","detect_generic_ble":"yes","detect_generic_wifi":"yes","gps":"addon","sd_logging":"yes","standalone_untethered":"partial","wifi_deauth_24":"no","wifi_injection":"no"},"legal":{"risk_level":"low","notes":"Passive receive-only, sold and CE/ElektroG-registered in Germany, with no transmit or attack features - about as low-risk as this category gets."},"ecosystem":{"community":"commercial","docs_quality":"good","last_release":"2026-08","app_store":"No","abandoned_risk":"medium"}}];
